INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beddings','n.寝具；（建筑）[建]基床；（家畜）草垫adj.适于花坛种植的vt.把…栽入苗床（bed的ing形式）vi.睡（bed的ing形式）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('although','conj.尽管；虽然；但是；然而','/ɔːlˈðəʊ/','/ɑlˈðoʊ/','conjunction',["Although it was very muddy, the football game went on.","It was difficult, although not as difficult as we had expected."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('effort','n.努力；成就','/ˈɛfət/','/ˈɛfɚt/','noun',["It took a lot of effort to find a decent-sized, fully-furnished apartment within walking distance of the office.   He made a conscious effort to not appear affected by the stories in the paper.","Although he didn''t win any medals, Johnson''s effort at the Olympics won over many fans."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preference','n.偏爱，倾向；优先权','/ˈpɹɛf(ə)ɹ(ə)ns/','/ˈpɹɛf(ə)ɹ(ə)ns/','noun',["He has a preference for crisp wines.","Can I keep my preferences when I upgrade to the new version of this application?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beneath','prep.在…之下adv.在下方','/bɪˈniːθ/','/bɪˈniːθ/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('currency','n.货币；通货','/ˈkʌɹ.ən.si/','/ˈkɝ.ən.si/','noun',["Wampum was used as a currency by Amerindians.","The jargon’s currency."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warmth','n.温暖；热情；激动','/wɔːmθ/','/wɔɹmθ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adapt','v.使适应；改编','/əˈdæpt/','/əˈdæpt/','verb',["to adapt a story for the stage","a word of an adapted form","They could not adapt to the new climate and so perished."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rewrite','v.改写；重写n.重写或改写的文稿；改写的作品','/ˈɹiː.ɹaɪt/','/ˈɹiː.ɹaɪt/','noun',["The film script underwent a rewrite for the European market.","The editor asked me to rewrite my article for a non-technical audience."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fourteen','num.十四；十四个；第十四n.十四的记号；十四岁；十四点钟；十五世纪','/ˈfɔː.tiːn/','','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steam','v.蒸，散发；用蒸汽处理n.蒸汽；精力adj.蒸汽的','/stiːm/','/stiːm/','noun',["After three weeks in bed he was finally able to sit up under his own steam.","Dad had to go outside to blow off some steam.","The best way to cook artichokes is to steam them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('piano','n.钢琴','/piˈænəʊ/','/piˈænoʊ/','noun',["He can play \"Happy Birthday\" on the piano."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('firm','adj.坚定的；牢固的；严格的；结实的v.使坚定；使牢固adv.稳固地n.公司；商号','/fɜːm/','/fɜɹm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bake','v.烤，烘焙n.烤；烘烤食品','/beɪk/','/beɪk/','noun',["I baked a delicious cherry pie.","The cake baked at 350°F.","The clay baked in the sun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suggest','v.提议，建议；启发；使人想起；显示；暗示','/səˈdʒɛst/','/sə(ɡ)ˈdʒɛst/','verb',["Are you suggesting that I killed my wife?","The name \"hamburger\" suggests that hamburgers originated from Hamburg.","I’d like to suggest that we go out to lunch.   I’d like to suggest going out to lunch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('happily','adv.快乐地；幸福地；幸运地；恰当地','/ˈha.pə.li/','/ˈhæ.pə.li/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('changeable','adj.无常的；可改变的；易变的；不定的','/ˈt͡ʃeɪnd͡ʒəbəl/','/ˈt͡ʃeɪnd͡ʒəbəl/','adjective',["The weather is very changeable today: we''ve had bright sunshine, clouds, wind and rain in the same half-hour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('happen','v.发生；碰巧；偶然遇到','/ˈhæpən/','/ˈhæpən/','verb',["Let me tell you how it happened.","Do you happen to have an umbrella?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stream','n.溪流；流动；潮流；光线v.流；涌进；飘扬','/stɹiːm/','/stɹiːm/','noun',["He poured the milk in a thin stream from the jug to the glass.","Her constant nagging was to him a stream of abuse.","Haredi Judaism is a stream of Orthodox Judaism characterized by rejection of modern secular culture."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('late','adj.晚的；迟的；已故的；最近的adv.晚；迟；最近；在晚期','/leɪt/','/leɪt/','noun',["It was late in the evening when we finally arrived.","It was getting late and I was tired.","Late Latin is less fully inflected than classical Latin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hey','int.喂！（引起注意等）；你好！（表示问候）n.干草（等于hay）','/heɪ/','/heɪ/','interjection',["Hey! Listen!","Hey! Stop that!","Hey! This is new!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charge','n.费用；电荷；掌管；控告；命令；负载v.使充电；使承担；指责；装载；对…索费；向…冲去','/t͡ʃɑːd͡ʒ/','/t͡ʃɑɹd͡ʒ/','noun',["There will be a charge of five dollars.","Pickett did not die leading his famous charge.","That''s a slanderous charge of abuse of trust."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treat','v.治疗；对待；探讨；视为n.请客；款待','/tɹiːt/','/tɹiːt/','noun',["Here are some healthy Halloween treats for ghouls and witches of all ages.","It was such a treat to see her back in action on the London stage.","I lured the cat into her carrier by throwing a couple of treats in there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simplify','v.简化；使单纯；使简易','/ˈsɪmpləfaɪ/','/ˈsɪmpləfaɪ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statesman','n.政治家；国务活动家','/ˈsteɪtsmən/','/ˈsteɪtsmən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reservation','n.预约，预订；保留','/ˌɹɛzəˈveɪʃən/','/ˌɹɛzəˈveɪʃən/','noun',["The committee authorised the reservation of funds.","I have reservations about your intentions.","I have a hotel reservation in the name of Mr Smith."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('framework','n.框架，骨架；结构，构架','/ˈfɹeɪm.wɜːk/','/ˈfɹeɪm.wɜːk/','noun',["These ‘three principles of connexion’ compose the framework of principles in Hume''s account of the association of ideas."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consider','v.考虑；认为；考虑到；细想','/kənˈsɪdə/','/kənˈsɪdɚ/','verb',["Consider that we’ve had three major events and the year has hardly begun.","I’m considering going to the beach tomorrow.","Consider yourself lucky, but consider your opponent skillful."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gram','n.克；鹰嘴豆（用作饲料）','/ɡɹæm/','/ɡɹæm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('DVD','abbr.数字化视频光盘（DigitalVideoDisk）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superior','adj.上级的；优秀的，出众的；高傲的n.上级，长官；优胜者，高手；长者','/suːˈpɪəɹi.ə(ɹ)/','/suːˈpɪɹiɚ/','noun',["Rebecca had always thought shorts were far superior to pants, as they didn''t constantly make her legs itch.","A genus is superior to a species.","the superior jaw; the superior part of an image"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('achievement','n.成就；完成；达到；成绩','/əˈtʃiːvmənt/','/əˈtʃiːvmənt/','noun',["Finishing the game does not give you a 100% score until you have unlocked all of the achievements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urgent','adj.紧急的；急迫的','/ˈɜːdʒənt/','/ˈɚdʒənt/','adjective',["An urgent appeal was sent out for assistance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sense','n.感觉，功能；观念；道理；理智v.感觉到；检测','/sɛn(t)s/','/sɛns/','noun',["a sense of security","It''s common sense not to put metal objects in a microwave oven.","You don’t make any sense."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foresee','v.预见；预知','/fɔːˈsiː/','/fɔɹˈsi/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('try','v.试图，努力；试验；审判；考验n.尝试；努力；试验','/tɹaɪ/','/tɹaɪ/','noun',["I gave unicycling a try but I couldn’t do it.","I gave sushi a try but I didn’t like it.","Today I scored my first try."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compass','n.指南针，罗盘；圆规v.包围','/ˈkʌm.pəs/','/ˈkʌm.pəs/','noun',["within the compass of an encircling wall"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headteacher','n.中小学的校长','','','noun',["I had to go and see the headteacher about my attitude."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earn','v.赚，赚得；获得，挣得；使得到；博得n.(Earn)人名；(泰)炎','/ɜːn/','/ɝn/','verb',["You can have the s''mores: you earned them, clearing the walkway of snow so well.","He earns seven million dollars a year as CEO.  My bank account is only earning one percent interest.","Now that you are earning, you can start paying me rent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collect','v.收集；募捐adv.由收件人付款地adj.由收件人付款的n.(Collect)人名；(英)科莱克特','/kəˈlɛkt/','/kəˈlɛkt/','verb',["Suzanne collected all the papers she had laid out.","A bank collects a monthly payment on a client''s new car loan.   A mortgage company collects a monthly payment on a house.","I don''t think he collects as much as hoards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mask','n.面具；口罩；掩饰v.掩饰；戴面具；化装','/mæsk/','/mæsk/','noun',["a dancer''s mask; a fencer''s mask; a ball player''s mask","to mask a body of troops or a fortess by a superior force, while some hostile evolution is being carried out"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assume','v.假定；设想；承担；采取','/əˈsjuːm/','/əˈsuːm/','verb',["We assume that, as her parents were dentists, she knows quite a bit about dentistry.","Mr. Jones will assume the position of a lifeguard until a proper replacement is found.","He assumed an air of indifference"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('player','n.运动员，比赛者；游戏者，做游戏的人；演奏者，表演者；演员；播放器','/ˈpleɪə(ɹ)/','/ˈpleɪə(ɹ)/','noun',["He thought he could become a player, at least at the state level."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revision','n.[印刷]修正；复习；修订本','/riˈvɪ.ʒ(ə)n/','/riˈvɪ.ʒ(ə)n/','noun',["A revision story"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('farm','v.种田，务农；经营农场n.农场；农家；畜牧场','/fɑːɹm/','/fɑːɹm/','noun',["antenna farm","a render farm","to farm the taxes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hive','v.群居；入蜂房；生活在蜂房中n.蜂房，蜂巢；热闹的场所；熙攘喧闹的人群','/haɪv/','/haɪv/','noun',["to hive a swarm of bees"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('year','n.年；年度；历年；年纪；一年的期间；某年级的学生','/jɪə/','/jɪɹ/','noun',["we moved to this town a year ago;  I quit smoking exactly one year ago","Mars goes around the sun once in a Martian year, or 1.88 Earth years.","A normal year has 365 full days, but there are 366 days in a leap year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continue','v.继续，延续；仍旧，连续','/kənˈtɪnjuː/','/kənˈtɪnjuː/','noun',["Do you want me to continue to unload these?","When will the concert continue?","This meeting has been continued to the thirteenth of July."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contradict','v.反驳；否定；与…矛盾；与…抵触','/kɒntɹəˈdɪkt/','/kɒntɹəˈdɪkt/','verb',["His testimony contradicts hers.","Everything he says contradicts me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('usually','adv.通常，经常','/ˈjuːʒju(ə)li/','/ˈjuːʒ(ʊə)li/','adverb',["Except for one or two days a year, he usually walks to work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persuade','v.说服，劝说；使某人相信；劝某人做（不做）某事adj.空闲的，有闲的','/pəˈsweɪd/','/pɚˈsweɪd/','verb',["That salesman was able to persuade me into buying this bottle of lotion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mental','adj.精神的；脑力的；疯的n.精神病患者','/ˈmɛntəl/','/ˈmɛntəl/','adjective',["He is the most mental freshman I''ve seen yet.","That was a mental party last night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hawk','v.兜售，沿街叫卖；捕捉；咳出n.鹰；鹰派成员；掠夺他人的人','/hɔːk/','/hɔk/','noun',["It is illegal to hunt hawks or other raptors in many parts of the world.","to hawk at flies"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clothes','n.衣服','/kləʊ(ð)z/','/kloʊ(ð)z/','noun',["He is a respected man of the cloth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plastic','adj.塑料的；（外科）造型的；可塑的n.塑料制品；整形；可塑体','/ˈplæstɪk/','/ˈplæstɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terrible','adj.可怕的；很糟的；令人讨厌的adv.很，非常','/ˈtɛ.ɹə.bl̩/','','adjective',["The witch gave him a terrible curse.","He paid a terrible price for his life of drinking.","The food was terrible, but it was free."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bedclothes','n.床上用品；铺盖','','','noun',["She pulled her bedclothes over her neck to stay warm."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('award','v.授予；判定n.奖品；判决','/əˈwɔːd/','/əˈwɔɹd/','noun',["the arbitrators awarded damages to the complainant","Four or five of these medals are awarded every year.","He was awarded the Nobel Prize for Literature."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surround','v.围绕；包围n.围绕物adj.环绕立体声的','/səˈɹaʊnd/','/səˈɹaʊnd/','noun',["to surround the world"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humour','n.幽默（等于humor）；诙谐v.迁就；使满足','/ˈhjuː.mə(ɹ)/','/ˈhjuːmɚ/','noun',["She has a great sense of humour, and I always laugh a lot whenever we get together.","He was in a particularly vile humour that afternoon.","I know you don''t believe my story, but humour me for a minute and imagine it to be true."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hostess','n.女主人，女老板；女服务员；舞女；女房东','/ˈhəʊstəs/','/ˈhoʊstəs/','noun',["The host and hostess greeted their guests at the door."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speaker','n.演讲者；扬声器；说话者；说某种语言的人','/ˈspiːkə/','/ˈspikɚ/','noun',["The company hired a motivational speaker to boost morale."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('successful','adj.成功的；一帆风顺的','/səkˈsɛsfl̩/','/səkˈsɛsfl̩/','adjective',["a successful use of medicine;  a successful experiment;  a successful enterprise"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chance','n.机会，际遇；运气，侥幸；可能性v.偶然发生；冒……的险','[tʃʰɑːns]','[tʃʰeəns]','noun',["We had the chance to meet the president last week.","Why leave it to chance when a few simple steps will secure the desired outcome?","There is a 30 percent chance of rain tomorrow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lid','n.盖子；眼睑；限制vt.给…盖盖子','/lɪd/','/lɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dollar','n.美元','/dɔlɚ/','/ˈdɑlɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('man','n.人；男人；人类；丈夫；雇工v.操纵；给…配置人员；使增强勇气；在…就位','/mæn/','/mæn/','noun',["The show is especially popular with middle-aged men.","every man for himself","Some people prefer apple pie, but me, I’m a cherry pie man."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ten','num.十个，十n.(Ten)人名；(英)坦恩；(意)泰恩；(柬)登','/tɛn/','/tɛn/','noun',["We divided the chocolates into tens to hand out to Hallowe''en visitors.","Can you give me two tens for this twenty?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pay','v.支付，付；偿还，补偿；给予n.工资，薪水；付款；报答adj.收费的；需付费的','/peɪ/','/peɪ/','noun',["Many employers have rules designed to keep employees from comparing their pays.","he paid her off the books and in kind where possible","he has paid his debt to society"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('under','prep.低于，少于；在之下adv.在下面；在下方adj.下面的；从属的','/ˈʊndə/','/ˈʌndɚ/','adjective',["Ensure the patient is sufficiently under.","It took the hypnotist several minutes to make his subject go under.","He served in World War II under General Omar Bradley."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leading','adj.领导的；主要的n.领导；铅板；行距v.领导（lead的ing形式）','/ˈliːdɪŋ/','/ˈlidɪŋ/','verb',["continuous firing leads the grooves of a rifle.","leaded matter","to lead someone to a righteous cause"]);
