INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('escape','v.逃避，避开，避免；被忘掉；被忽视n.逃跑；逃亡；逃走；逃跑工具或方法；野生种；泄漏','/əˈskeɪp/','/əˈskeɪp/','noun',["The prisoners made their escape by digging a tunnel.","You forgot to insert an escape in the datastream.","The factory was evacuated after toxic gases escaped from a pipe."]);
