INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affair','n.事情；事务；私事；（尤指关系不长久的）风流韵事','/əˈfɛə/','/əˈfɛə(ɹ)/','noun',["a difficult affair to manage","an affair of honor, a duel;  an affair of love, an intrigue","He used a hook-shaped affair with a long handle to unlock the car."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steward','n.管家；乘务员；膳务员；工会管事vi.当服务员；当管事vt.管理','/ˈstjuː.əd/','/ˈstuɚd/','noun',["a steward in a Methodist church"]);
