INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('import','n.进口，进口货；输入；意思，含义；重要性v.输入，进口；含…的意思','/ˈɪm.pɔːt/','/ˈɪm.pɔːt/','noun',["It was a matter of great import.","How can I import files from older versions of this application?"]);
