INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('honest','adj.诚实的，实在的；可靠的；坦率的','/ˈɒnɪst/','/ˈɑnɪst/','verb',["We’re the most honest people you will ever come across.","an honest account of events","an honest mistake"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('new','adj.新的，新鲜的；更新的；初见的adv.新近n.(New)人名；(英)纽','/njuː/','/n(j)u/','noun',["Out with the old, in with the new.","This is a new scratch on my car!   The band just released a new album.","We turned up some new evidence from the old files."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pause','n.暂停；间歇v.暂停，停顿，中止；踌躇','/pɔːz/','/pɔz/','noun',["Teach the pupil to mind the pauses.","When telling the scary story, he paused for effect.","to pause a song, a video, or a computer game"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunlight','n.日光','/ˈsʌnˌlaɪt/','/ˈsʌnˌlaɪt/','noun',["Sunlight on the skin gives you vitamin D.","I''ll meet you at the docks at sunrise.","Did you see the beautiful sunrise this morning?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disturb','v.打扰；妨碍；使不安；弄乱；使恼怒','/dɪsˈtɜːb/','','noun',["A school of fish disturbed the water.","A mudslide disturbed the course of the river.","A disturbing film that tries to explore the mind of a serial killer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distribute','v.分配；散布；分开；把…分类','/dɨˈstɹɪbjuːt/','/dɪˈstɹɪbjut/','verb',["He distributed the bread amongst his followers.","The agency distributes newspapers to local shops.","A network of children distributes flyers to every house."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stable','n.马厩；牛棚adj.稳定的；牢固的；坚定的v.被关在马厩','/ˈsteɪ.bəɫ/','/ˈsteɪ.bəɫ/','noun',["There were stalls for fourteen horses in the squire''s stables."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('straw','n.稻草；吸管；一文不值的东西adj.稻草的；无价值的','/stɹɔː/','/stɹɔ/','noun',["straw hat","A straw enemy built up in the media to seem like a real threat, which then collapses like a balloon."]);
