INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zoo','n.动物园','/zuː/','/zuː/','noun',["The shopping center was a zoo the week before Christmas."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perhaps','adv.或许；（表示不确定）也许；（用于粗略的估计）或许；（表示勉强同意或其实不赞成）也许；可能n.假定；猜想；未定之事','/pəˈhæps/','/pɚˈhæps/','noun',["Perhaps John will come over for dinner."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pressure','n.压力；压迫，[物]压强v.迫使；密封；使……增压','[ˈpɹɛʃ.ə(ɹ)]','[ˈpɹɛʃ.ɚ]','noun',["Apply pressure to the wound to stop the bleeding.","the pressure of poverty; the pressure of taxes; the pressure of motives on the mind; the pressure of civilization.","She has felt pressure lately because her boss expects her to get the job done by the first."]);
