INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basis','n.基础；底部；主要成分；基本原则或原理','/ˈbeɪsɪs/','/ˈbeɪsɪs/','noun',["Cars must be checked on a yearly basis.","The collection of all possible unions of basis elements of a basis is said to be the topology generated by that basis."]);
