INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electric','adj.电的；电动的；发电的；导电的；令人震惊的n.电；电气车辆；带电体','/əˈlɛktɹɪk/','/əˈlɛktɹɪk/','noun',["We had to sit in the dark because the electric was cut off."]);
