INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chalk','v.用粉笔写；用白垩粉擦；记录；规划n.粉笔；白垩；用粉笔划的记号adj.用粉笔写的','/t͡ʃɔːk/','/t͡ʃɔːk/','noun',[]);
