INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hard','adj.努力的；硬的；困难的；辛苦的；确实的；严厉的；猛烈的；冷酷无情的adv.努力地；困难地；辛苦地；接近地；猛烈地；牢固地n.(Hard)人名；(英、芬、瑞典)哈德','/hɑːd/','/hɑɹd/','noun',["The prisoners were sentenced to three years'' hard.","hard evidence;  a hard requirement","At the intersection, there are two roads going to the left. Take the hard left."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('half','n.一半；半场；半学年adv.一半地；部分地adj.一半的；不完全的；半途的','/hɑːf/','/hɑːf/','noun',["I ate the slightly smaller half of the apple.","Three-quarters minus a quarter is a half.","a half bushel; a half hour; a half dollar; a half view"]);
