INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comrade','n.同志；伙伴','/ˈkɒmɹeɪd/','/ˈkɒmɹeɪd/','noun',["Hello, comrade. Are you going to the Communist Party meeting tonight?","Comrade Lenin inspired our people to undertake great works."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duty','n.责任；[税收]关税；职务','/ˈdjuːti/','/duːti/','noun',["We don''t have a duty to keep you here.","I’m on duty from 6 pm to 6 am."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pile','n.堆；大量；建筑群v.累积；打桩于','/paɪl/','/paɪl/','noun',["When we were looking for a new housemate, we put the nice woman on the \"maybe\" pile, and the annoying guy on the \"no\" pile","a pile of shot","He made a pile from that invention of his."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worn','adj.疲倦的；用旧的v.穿；磨损（wear的过去分词）；佩戴n.(Worn)人名；(柬)翁；(英、葡)沃恩','/wɔːn/','/wɔɹn/','verb',["He''s wearing some nice pants today.  She wore her medals with pride.  Please wear your seatbelt.  Can you wear makeup and sunscreen at the same time?  He was wearing his lunch after tripping and falling into the buffet.","He wears eyeglasses.  She wears her hair in braids.","She wore a smile all day.  He walked out of the courtroom wearing an air of satisfaction."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('click','v.点击；使发咔哒声n.单击；滴答声','/klɪk/','/klɪk/','noun',["I turned the key, the lock gave a click and the door opened;  a click of one’s fingers","Visit a location, call, or click www.example.com.","From the home page, click through to the Products section."]);
