INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pull','v.拉；拔；拖n.拉，拉绳；拉力，牵引力；拖','/pʊl/','[pʰʊːɫ]','noun',["He gave the hair a sharp pull and it came out.","She took a pull on her cigarette.","a zipper pull"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('still','adv.仍然；更；静止地adj.静止的，不动的；寂静的，平静的；不起泡的n.寂静；剧照；蒸馏室conj.仍然；但是；尽管如此v.蒸馏；使…静止；使…平静下来','/stɪl/','/stɪl/','noun',["the still of the night","Still waters run deep.","still water; still wines"]);
