INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoken','adj.口语的，口头的v.说（speak的过去分词）','/ˈspoʊkən/','/ˈspoʊkən/','verb',["I was so surprised I couldn''t speak.","It''s been ages since we''ve spoken.","Actions speak louder than words."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('native','adj.本国的；土著的；天然的；与生俱来的；天赋的n.本地人；土产；当地居民','/ˈneɪtɪv/','/ˈneɪtəv/','noun',["English is not my native language.","The native peoples of Australia are called aborigines.","Many native artists studied abroad."]);
