INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meeting','n.会议；会见；集会；汇合点v.会面；会合（meet的ing形式）','/ˈmiːtɪŋ/','/ˈmitɪŋ/','noun',["Meeting him will be exciting. I enjoy meeting new people.","We need to have a meeting about that soon.","What has the meeting decided."]);
