INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worry','n.担心；烦恼；撕咬v.担心；发愁；折磨','/ˈwɒɹi/','/ˈwɝɹi/','noun',["I''m afflicted by worry throughout the night.","My main worry is that I''ll miss the train.","Stop worrying about your test, it’ll be fine."]);
