INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eye','n.眼睛；视力；眼光；见解，观点v.注视，看','/aɪ/','/aɪ/','noun',["Bright lights really hurt my eyes.","The car was quite pleasing to the eye, but impractical.","Brown, blue, green, hazel eyes."]);
