INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('to','adv.向前；（门等）关上prep.到；向；（表示时间、方向）朝…方向n.(To)人名；(柬)多；(中)脱(普通话·威妥玛)','/tʉː/','/tʉː/','adverb',["Please push the door to.","We are walking to the shop.","He devoted himself to education."]);
