INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('friendly','adj.友好的；亲切的；支持的；融洽的，和睦的adv.友善地；温和地n.(Friendly)人名；(英)弗兰德利','/ˈfɹɛndli/','/ˈfɹɛndli/','noun',["This match is merely a friendly, so don''t worry too much about it.","Your cat seems very friendly.","He gave a friendly smile."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forward','adj.向前的；早的；迅速的adv.向前地；向将来v.促进；转寄；运送n.前锋','/ˈfoːwəd/','/ˈfɔɹ.wɚd/','noun',["I''ll be glad to forward your mail to you while you''re gone.","The fire was confined to the forward portion of the store.","The stock price is currently 12 times forward earnings."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exchange','n.交换；交流；交易所；兑换v.交换；交易；兑换','/ɛksˈtʃeɪndʒ/','/ɛksˈtʃeɪndʒ/','noun',["All in all, it was an even exchange.","The stock exchange is open for trading.","NPA-NXX-1234 is standard format, where NPA is the area code and NXX is the exchange."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suppose','v.假设；认为；让（虚拟语气）；推想conj.假使…结果会怎样','/səˈpəʊz/','/səˈpoʊz/','verb',["Suppose that A implies B and B implies C. Then A implies C.","I suppose we all agree that this is the best solution.","Purpose supposes foresight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generous','adj.慷慨的，大方的；宽宏大量的；有雅量的','/ˈdʒɛn(ə)ɹəs/','/ˈdʒɛn(ə)ɹəs/','adjective',["Thank you for your generous words.","She''s been extremely generous with her winnings.","Add a generous helping of mayonnaise."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hers','pron.她的（所有格）n.(Hers)人名；(法)埃尔','/əz/','/ɚz/','noun',["I think this bird is a him, but it may be a her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explain','v.说明；解释','/ɛkˈspleɪn/','/ɛkˈspleɪn/','verb',["To explain a chapter of the Bible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valid','adj.有效的；有根据的；合法的；正当的','/ˈvælɪd/','/ˈvælɪd/','adjective',["I will believe him as soon as he offers a valid answer.","A valid format for the date is MM/DD/YY.","An argument is valid if and only if the set consisting of both (1) all of its premises and (2) the contradictory of its conclusion is inconsistent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tie','v.系；约束；打结；与…成平局n.领带；平局；鞋带；领结；不分胜负','/taɪ/','/taɪ/','noun',["It''s two outs in the bottom of the ninth, tie score.","the sacred ties of friendship or of duty","Ties work to maintain structural integrity in windstorms and earthquakes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('then','adv.然后；那么；于是；当时；此外n.那时conj.然后，当时','/ðen/','/ðɛn/','conjunction',["she''s taller than I am;  she found his advice more witty than helpful;  we have less work today than we had yesterday;  We had no choice than to return home","It will be finished before then.","He was happy then."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sew','v.缝合，缝上；缝纫','/səʊ/','/soʊ/','verb',["Balls were first made of grass or leaves held together by strings, and later of pieces of animal skin sewn together and stuffed with feathers or hay.","to sew money into a bag"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desperate','adj.不顾一切的；令人绝望的；极度渴望的','/ˈdɛsp(ə)ɹət/','','noun',["I hadn''t eaten in two days and was desperate for food.","I was so desperate at one point, I even went to see a loan shark.","a desperate effort"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steak','n.牛排；肉排；鱼排','/steɪk/','/steɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('British','adj.英国的；英国人的；大不列颠的n.英国人','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sailor','n.水手，海员；乘船者','/ˈseɪlə/','/ˈseɪlɚ/','noun',["He''s a talented sailor and has spent many years at sea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wear','n.衣物；磨损；耐久性v.穿着；用旧；耗损；面露','/wɛə/','/wɛə(ɹ)/','noun',["footwear; outdoor wear; maternity wear","He''s wearing some nice pants today.  She wore her medals with pride.  Please wear your seatbelt.  Can you wear makeup and sunscreen at the same time?  He was wearing his lunch after tripping and falling into the buffet.","He wears eyeglasses.  She wears her hair in braids."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postage','n.邮资，邮费','/ˈpəʊstɪdʒ/','/ˈpəʊstɪdʒ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presentation','n.展示；描述，陈述；介绍；赠送','/ˌpɹizənˈteɪʃən/','/ˌpɹizənˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wet','adj.[气象][物]潮湿的；有雨的n.雨天；湿气v.弄湿','/wɛt/','/wɛt/','noun',["Don''t go out in the wet.","Johnny wets the bed several times a week.","Wet ''em up!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avoid','v.避免；避开，躲避；消除','/əˈvɔɪd/','/əˈvɔɪd/','verb',["I try to avoid the company of gamblers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pity','n.怜悯，同情；遗憾v.对……表示怜悯；对……感到同情','/ˈpɪti/','/ˈpɪti/','noun',["I can''t feel any pity towards the gang, who got injured while attempting to break into a flat.","It''s a pity you''re feeling unwell because there''s a party on tonight.","You have got to pity the guy - he lost his wife, mother and job in the same month."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrangement','n.布置；整理；准备','/əˈɹeɪnd͡ʒmənt/','/əˈɹeɪnd͡ʒmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('among','prep.在…中间；在…之中','/əˈmɒŋ/','/əˈmɒŋ/','preposition',["How can you speak with authority about their customs when you have never lived among them?","He is among the few who completely understand the subject.","Lactose intolerance is common among people of Asian heritage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('author','n.作者；作家；创始人v.创作出版','/ˈɔː.θə/','/ˈɔ.θɚ/','noun',["Have you read any Corinthian authors?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mommy','n.妈咪','','','noun',["She is the mommiest of mommies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theft','n.盗窃；偷；赃物','/θɛft/','/θɛft/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bathe','v.沐浴；用水洗n.洗澡；游泳','/beɪð/','/beɪð/','noun',["I''m going to have a midnight bathe tonight.","We bathe our baby before going to bed; other parents do it in the morning if they have time.","She bathed her eyes with liquid to remove the stinging chemical."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assistant','n.助手，助理，助教adj.辅助的，助理的；有帮助的','/əˈsɪstənt/','/əˈsɪstənt/','noun',["an assistant surgeon"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('battle','n.战役；斗争v.斗争；作战','/ˈbætəl/','/ˈbætl̩/','noun',["the battle of life","Scientists always battle over theories.","She has been battling cancer for years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beancurd','n.豆腐','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('front','n.前面；正面；前线v.面对；朝向；对付adj.前面的；正面的adv.在前面；向前','/fɹʌnt/','/fɹʌnt/','noun',["Officially it''s a dry-cleaning shop, but everyone knows it''s a front for the mafia.","He says he likes hip-hop, but I think it''s just a front.","to front court"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('work','n.工作；[物]功；产品；操作；职业；行为；事业；工厂；著作；文学、音乐或艺术作品v.使工作；操作；经营；使缓慢前进','/wɜːk/','/wəik/','noun',["We don''t have much time. Let''s get to work piling up those sandbags.","Tell me you''re using clean works at least."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blackboard','n.黑板','/ˈblækbɔːd/','/ˈblækboɹd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('washroom','n.洗手间；盥洗室；厕所','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legal','adj.法律的；合法的；法定的；依照法律的n.(Legal)人名；(法)勒加尔','/ˈliː.ɡəl/','/ˈliɡəl/','noun',["Legal wants this in writing.","legal profession","legal precedent"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fill','v.装满，使充满；满足；堵塞；任职n.满足；填满的量；装填物','/fɪl/','/fɪl/','verb',["the bucket filled with rain;  the sails fill with wind","My heart filled with joy.","The pharmacist filled my prescription for penicillin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crime','n.罪行，犯罪；罪恶；犯罪活动vt.控告……违反纪律','/kɹaɪm/','/kɹaɪm/','noun',["Crime doesn’t pay."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fifteen','n.十五；十五个；十五人组成的橄榄球队adj.十五的num.十五','/fɪfˈtiːn/','','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indeed','adv.的确；实在；真正地；甚至int.真的（表示惊讶、怀疑、讽刺等）','/ɪnˈdiːd/','/ɪnˈdiːd/','adverb',["Indeed, he made several misplays.","As a soccer player, he is terrible indeed.","\"I am a great runner.\" \"Indeed!\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clever','adj.聪明的；机灵的；熟练的','/ˈklɛvɚ/','/ˈklɛvɚ/','adjective',["clever like a fox"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refuse','n.垃圾；废物v.拒绝；不愿；抵制','/ˈɹɛfjuːs/','/ˈɹɛfjuːs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whichever','pron.任何一个；无论哪个adj.无论哪个；无论哪些','/wɪtʃˈɛvɚ/','/wɪtʃˈɛvɚ/','pronoun',["These chocolates all look delicious. Whichever shall I choose?","Whichever you pick, be content with it.","I have a few books; please borrow whichever interest you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leftover','n.残留物；吃剩的饭菜；剩余物adj.残余的；吃剩的','','','noun',["It''s a leftover from yesterday, but it''s still perfectly good.","Not leftovers again!","Do you want some of the leftover supplies from the event?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('base','n.基础；底部；垒adj.卑鄙的；低劣的v.以…作基础','/beɪs/','/beɪs/','noun',["The logarithm to base 2 of 8 is 3.","Peter adjusted the equalizer on his audio equipment to emphasize the bass.","The conductor preferred to situate the bass in the middle rear, rather than to one side of the orchestra."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('action','n.行动；活动；功能；战斗；情节','/ˈæk.ʃən/','/ˈæk.ʃən/','noun',["Knead bread with a rocking action.","a movie full of exciting action","a rifle action"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catholic','adj.天主教的；宽宏大量的n.天主教徒；罗马天主教','/ˈkaθ(ə)lɪk/','/ˈkæθ(ə)lɪk/','adjective',["Christmas is celebrated at different dates in the Catholic and Orthodox calendars.","Catholic churches are built differently than Protestant ones."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('succeed','v.成功；继承；继任；兴旺','/səkˈsiːd/','/səkˈsiːd/','verb',["Autumn succeeds summer.","The persecution of any righteous practice has never succeeded in the face of history; in fact, it can expedite the collapse of the persecutory regime.","So, if the issue of the elder son succeed before the younger, I am king."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('track','n.轨道；足迹，踪迹；小道v.追踪；通过；循路而行；用纤拉','/tɹæk/','/tɹæk/','noun',["Can you see any tracks in the snow?","The fox tracks were still visible in the snow.","Follow the track for a hundred metres."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('few','adj.很少的；几乎没有的pron.很少n.很少数','/fjuː/','/fju/','pronoun',["Many are called, but few are chosen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('city','n.城市，都市adj.城市的；都会的','/sɪtɪ/','/ˈsɪɾi/','noun',["São Paulo is the largest city in South America.","I''m going into the city today to do some shopping.","It''s video game city in here!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Sunday','n.星期日；礼拜日','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pet','n.宠物；生气；受宠爱的人v.宠爱adj.宠爱的','/pɛt/','/pɛt/','noun',["His daughter was petted and spoiled.","The professor seemed offended by the criticism of her pet theory.","pet rock"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('into','prep.到…里；深入…之中；成为…状况；进入到…之内n.(Into)人名；(芬、英)因托','/ˈɪn.tuː/','','preposition',["Mary danced into the house.","The eagle flew off into the wide blue sky.","I wasn''t careful, and walked into a wall"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defeat','v.击败，战胜；挫败；使…失败n.失败的事实；击败的行为','/dɪˈfiːt/','/dɪˈfiːt/','verb',["Wellington defeated Napoleon at Waterloo."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('teenager','n.十几岁的青少年；十三岁到十九岁的少年','/ˈtiːnˌeɪ.dʒə(ɹ)/','/ˈtiːnˌeɪ.dʒə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jeep','n.吉普车','/dʒiːp/','/dʒiːp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ample','adj.丰富的；足够的；宽敞的n.(Ample)人名；(西)安普尔','/ˈæm.pəl/','/ˈæm.pəl/','adjective',["an ample house","ample material","an ample story"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mirror','n.镜子；真实的写照；榜样v.反射；反映','/ˈmɪ.ɹə/','/ˈmiɹ.ɚ/','noun',["I had a look in the mirror to see if the blood had come off my face.","His story is a mirror into the life of orphans growing up.","Although the content had been deleted from his blog, it was still found on some mirrors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typist','n.打字员，打字者','/ˈtaɪpɪst/','/ˈtaɪpɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stadium','n.体育场；露天大型运动场','/ˈsteɪ.di.əm/','/ˈsteɪ.di.əm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('substitute','n.代用品；代替者v.替代','/ˈsʌbstɪtjut/','/ˈsʌbstɪtjut/','noun',["I had no shallots so I substituted onion.","I had to substitute new parts for the old ones.","I had to substitute old parts with the new ones."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carve','v.雕刻；切开；开创n.(Carve)人名；(西、瑞典)卡韦','/kɑːv/','/kɑɹv/','noun',["give that turkey a careful carve","You carve the roast and I''ll serve the vegetables.","to carve a name into a tree"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electrical','adj.有关电的；电气科学的','/ɪˈlɛktɹɪkəl/','/ɪˈlɛktɹɪkəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yell','v.大叫，叫喊n.喊声，叫声','/jɛl/','/jɛl/','noun',["He yelled directions to the party from the car.","If I come home late again, my dad is gonna yell at me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wide','adj.广泛的；宽的，广阔的；张大的；远离目标的adv.广泛地；广阔地；充分地n.大千世界','/waɪd/','/waɪd/','noun',["We walked down a wide corridor.","The inquiry had a wide remit.","That team needs a decent wide player."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grape','n.葡萄；葡萄酒；葡萄树；葡萄色','/ɡɹeɪp/','/ɡɹeɪp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resign','v.辞职；放弃；委托；使听从n.辞去职务','/ɹɪˈzaɪn/','/ɹɪˈzaɪn/','verb',["He resigned the crown to follow his heart.","After fighting for so long, she finally resigned to her death."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percentage','n.百分比；百分率，百分数','/pəˈsɛntɪd͡ʒ/','/pɚˈsɛntɪd͡ʒ/','noun',["A high percentage of secondary school leavers take a gap year.","She gets a percentage for every vacuum cleaner sold.","There was no percentage in staying at home."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stout','adj.结实的；矮胖的；勇敢的；激烈的n.矮胖子；烈性啤酒','/stʌʊt/','/staʊt/','noun',["Stout is darker, stronger and sweeter than porter beer.","Campers prefer stout vessels, sticks and cloth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('final','adj.最终的；决定性的；不可更改的n.决赛；期末考试；当日报纸的末版','/ˈfaɪ.nəl/','/ˈfaɪ.nəl/','noun',["final solution;   the final day of a school term","a final judgment;   the battle of Waterloo brought the contest to a final issue"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certain','adj.某一；必然的；确信；无疑的；有把握的pron.某些；某几个n.(Certain)人名；(葡)塞尔塔因；(法)塞尔坦','/ˈsɝtn̩/','/ˈsɝtn̩/','noun',["I was certain of my decision.","Bankruptcy is the certain outcome of your constant gambling and lending.","There were serious objections to certain of the proposals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discourage','v.阻止；使气馁','/dɪsˈkʌɹɪd͡ʒ/','/dɪsˈkɝɪd͡ʒ/','noun',["Don''t be discouraged by the amount of work left to do: you''ll finish it in good time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strict','adj.严格的；绝对的；精确的；详细的','/stɹɪkt/','/stɹɪkt/','adjective',["strict embrace","strict fiber","to keep strict watch"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visual','adj.视觉的，视力的；栩栩如生的','/ˈvɪʒuəl/','/ˈvɪʒuəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('those','adj.那些的pron.那些（that的复数）','/ðəʊz/','/ðoʊz/','pronoun',["He went home, and after that I never saw him again.","They''re getting divorced. What do you think about that?","The water is so cold! — That it is."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('needle','n.针；指针；刺激；针状物v.缝纫；做针线','/ˈniː.dl/','/ˈniː.dl/','noun',["The seamstress threaded the needle to sew on a button.","The needle on the fuel gauge pointed to empty.","Ziggy bought some diamond needles for his hi-fi phonograph."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('car','n.汽车；车厢','/kɑː/','/kɑɹ/','noun',["She drove her car to the mall.","The conductor coupled the cars to the locomotive.","The 11:10 to London was operated by a 4-car diesel multiple unit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('put','v.放；表达；移动；安置；赋予n.掷；笨蛋；投击；怪人adj.固定不动的','/pʊt/','/pʊt/','noun',["He bought a January ''08 put for Procter and Gamble at 80 to hedge his bet.","the put of a ball","She put her books on the table."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circumstance','n.环境，情况；事件；境遇','/-æns/','/ˈsɝ.kəm.ˌstæns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('without','prep.没有；超过；在…外面adv.户外；在外面；没有或不显示某事物n.外部；外面','/wɪθˈʌʊt/','/wɪðˈaʊt/','adverb',["Being from a large, poor family, he learned to live without.","The snow was swirling without the cottage, but it was warm within.","It was a mistake to leave my house without a coat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mend','v.修理，修补；改善；修改n.好转，改进；修补处','/mɛnd/','/mɛnd/','noun',["My trousers have a big rip in them and need a mend.","My trousers have a big rip in them and need mending.","Her stutter was mended by a speech therapist."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arithmetic','n.算术，算法','','','noun',["arithmetic geometry","arithmetic progression"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smart','adj.聪明的；巧妙的；敏捷的；厉害的；潇洒的；剧烈的；时髦的n.(Smart)人名；(法)斯马尔；(英、德)斯马特','/smɑːt/','/smɑɹt/','verb',["After being hit with a pitch, the batter exclaimed \"Ouch, my arm smarts!\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fade','v.褪色；凋谢；逐渐消失adj.平淡的；乏味的n.[电影][电视]淡出；[电影][电视]淡入','/feɪd/','/feɪd/','noun',["The milkman''s whistling faded into the distance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attain','v.达到，实现；获得；到达n.成就','/əˈteɪn/','/əˈteɪn/','verb',["To attain such a high level of proficiency requires hours of practice each day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Greek','n.希腊语；希腊人adj.希腊的；希腊人的，希腊语的','/ɡɹiːk/','/ɡɹiːk/','noun',["Was Joe a Greek in college?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smile','v.微笑n.微笑；笑容；喜色','/ˈsmaɪ.əl/','/ˈsmaɪ.əl/','noun',["He always puts a smile on my face.","the smile of the gods","I don''t know what he''s smiling about."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eventually','adv.最后，终于','/ɪ.ˈvɛn.tjʊ.li/','/ɪ.ˈvɛn.t͡ʃu.li/','adverb',["Eventually, all prime numbers are odd."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fortune','n.财富；命运；运气vt.给予财富vi.偶然发生','/ˈfɔːtʃuːn/','/ˈfɔːtʃuːn/','noun',["She read my fortune. Apparently I will have a good love life this week, but I will have a bad week for money.","Fortune favors the brave.","He''s amassed a small fortune working in the Middle East."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purpose','n.目的；用途；意志v.决心；企图；打算','/ˈpɜːpəs/','/ˈpɝpəs/','noun',["The purpose of turning off the lights overnight is to save energy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tense','adj.紧张的；拉紧的v.变得紧张；使拉紧n.时态','/tɛns/','/tɛns/','noun',["English only has a present tense and a past tense; it has no future tense.","Dyirbal verbs are not inflected for tense.","tensing a verb"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bridge','n.桥；桥牌；桥接器；船桥v.架桥；渡过','/bɹɪd͡ʒ/','/bɹɪd͡ʒ/','noun',["With enough cable, we can bridge this gorge.","The two groups were able to bridge their differences."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lemonade','n.柠檬水','/ˌlɛmənˈeɪd/','/ˌlɛmənˈeɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stranger','n.陌生人；外地人；局外人','/ˈstɹeɪndʒə/','/ˈstɹeɪndʒɚ/','adjective',["He thought it strange that his girlfriend wore shorts in the winter.","I moved to a strange town when I was ten.","That gentleman is a stranger to me.  Children are taught not to talk to strangers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liberate','v.解放；放出；释放','/ˈlɪbəɹeɪt/','/ˈlɪbəɹeɪt/','verb',["We didn''t need IDs. We just liberated these beers from the back of the shop."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('librarian','n.图书馆员；图书管理员','/laɪˈbɹɛɹ.i.ən/','/laɪˈbɹɛɹ.i.ən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('club','n.俱乐部，社团；夜总会；棍棒；（扑克牌中的）梅花v.用棍棒打；募集adj.俱乐部的','/klʌb/','/klʌb/','noun',["She was sitting in a jazz club, sipping wine and listening to a bass player''s solo.","Michael stood you up?  Welcome to the club.","He clubbed the poor dog."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspect','n.嫌疑犯adj.可疑的；不可信的v.怀疑；猜想','/ˈsʌs.pɛkt/','/ˈsʌs.pɛkt/','noun',["to suspect the presence of disease","to suspect the truth of a story","I suspect him of being the thief."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tin','n.锡；罐头，罐；马口铁adj.锡制的v.涂锡于；给…包马口铁','/tɪn/','/tɪn/','noun',["muffin tin"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proper','adj.适当的；本身的；特有的；正派的adv.完全地n.(Proper)人名；(英、德)普罗珀','/ˈpɹɔp.ə/','/ˈpɹɑ.pɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greeting','n.问候，招呼；祝贺v.致敬，欢迎（greet的现在分词）','/ˈɡɹiːtɪŋ/','/ˈɡɹiːtɪŋ/','verb',["A brilliant dawn greeted her eyes as she looked out of the window.","It''s polite to begin a letter with a greeting, but this practice is less common in email."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discount','n.折扣；贴现率v.贴现；打折扣出售商品','/dɪsˈkaʊnt/','/dɪsˈkaʊnt/','noun',["This store offers discounts on all its wares. That store specializes in discount wares, too.","Merchants sometimes discount five or six per cent for prompt payment of bills.","the banks discount notes and bills of exchange"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delay','v.延期；耽搁n.延期；耽搁；被耽搁或推迟的时间','/dɪˈleɪ/','/dɪˈleɪ/','noun',["the delay before the echo of a sound","The mail is delayed by a heavy fall of snow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wheel','n.车轮；方向盘；转动v.转动；使变换方向；给…装轮子','/ʍiːl/','/wil/','noun',["the wheel of life","Wheel that trolley over here, would you?","The vulture wheeled above us."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('time','n.时间；时代；次数；节拍；倍数v.计时；测定…的时间；安排…的速度adj.定时的；定期的；分期的','/tɑem/','/taɪm/','noun',["Time stops for nobody.   the ebb and flow of time","Let''s synchronize our watches so we''re not on different time.","your car runs three times faster than mine;  that is four times as heavy as this"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hit','v.打击；袭击；碰撞；偶然发现；伤…的感情n.打；打击；（演出等）成功；讽刺','/hɪt/','/hɪt/','noun',["The hit was very slight.","The catcher got a hit to lead off the fifth.","Where am I going to get my next hit?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leather','n.皮革；皮革制品v.用皮革包盖；抽打adj.皮的；皮革制的','/ˈlɛðə/','/ˈlɛðɚ/','noun',["He leathered the ball all the way down the street."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correction','n.改正，修正','/kəˈɹɛkʃən/','/kəˈɹɛkʃən/','noun',["I have four T-80 tanks at grid Three-niner-niner-four-eight-eight, Correction: Grid Three niner-niner-four-eight-five. How copy? Over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twelve','n.十二；十二个num.十二；十二个adj.十二的；十二个的','/twɛlv/','/twɛlv/','noun',["Fractions would be a little easier if we counted by twelves.","There are twelve months in a year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exact','adj.准确的，精密的；精确的v.要求；强求；急需','/ɪɡˈzækt/','/ɪɡˈzækt/','verb',["to exact tribute, fees, or obedience from someone","to exact revenge on someone","He paid the exact debt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('it','pron.[指无生命的东西、动物、植物]它；这；那abbr.信息技术informationtechnology','/ɪt/','/ɪt/','noun',["In the next game, Adam and Tom will be it…","Let''s play it at breaktime.","caught them doing it"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fisherman','n.渔夫；渔人','/ˈfɪʃəmən/','/ˈfɪʃəmən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('know','v.知道；认识；懂得','/nəʊ/','/noʊ/','noun',["He knew something terrible was going to happen.","Did you know Michelle and Jack were getting divorced? ― Yes, I knew.","I know your mother, but I’ve never met your father."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pension','n.退休金，抚恤金；津贴；膳宿费v.发给养老金或抚恤金','/ˈpɛnʃ(ə)n/','/ˈpɛnʃ(ə)n/','noun',["Many old people depend on their pension to pay the bills.","A pension had somewhat less to offer than a hotel; it was always smaller, and never elegant; it sometimes offered breakfast, and sometimes not (John Irving)."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ourselves','pron.我们自己；我们亲自','/aʊəˈsɛlvz/','/aʊɚˈsɛlvz/','pronoun',["We should keep this for ourselves.","We did it ourselves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eleven','n.十一；十一个adj.十一的；十一个的num.十一；十一个','/ɪˈlɛv.ən/','/iˈlɛv.ən/','noun',["A: SUM1 Hl3p ME im alwyz L0ziN!!?!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('let','v.允许，让；出租；假设；妨碍n.障碍；出租屋','/lɛt/','/lɛt/','noun',["After he knocked for hours, I decided to let him come in.","Let me alone!","The physicians let about a pint of his blood, but to no avail."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('good','adj.好的；优良的；愉快的；虔诚的n.好处；善行；慷慨的行为adv.好','/ɡʊ(d)/','[ɡɪ̈d]','adjective',["The soup is good and hot.","Good Friday","Good! I can leave now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unfortunate','adj.不幸的；令人遗憾的；不成功的','/ʌnˈfɔːtjʊnət/','/ʌnˈfɔːtjʊnət/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('news','n.新闻，消息；新闻报导','/njuːz/','/njuːz/','noun',["Is there any news about the storm?","Did you hear/read/see the latest news?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('watch','v.观察；注视；看守；警戒n.手表；监视；守护；值班人','/wɒt͡ʃ/','/wɑt͡ʃ/','noun',["More people today carry a watch on their wrists than in their pockets.","The second watch of the night began at midnight.","The watch stopped the travelers at the city gates."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agreement','n.协议；同意，一致','/əˈɡɹiːmənt/','/əˈɡɹiːmənt/','noun',["to enter an agreement;  the UK and US negotiators nearing agreement;  he nodded his agreement.","The results of my experiment are in agreement with those of Michelson and with the law of General Relativity."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deposit','n.存款；押金；订金；保证金；沉淀物v.使沉积；存放','/dɪˈpɒzɪt/','/dɨˈpɑzɪt/','noun',["a deposit of seaweed on the shore","They put a deposit on the apartment.","A crocodile deposits her eggs in the sand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('determine','v.（使）下决心，（使）做出决定','/dɪˈtɜːmɪn/','/dɪˈtɝmɪn/','verb',["The news of his father''s illness determined him to depart immediately.","The court has determined the cause.","I determined to go home at once."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Mexican','adj.墨西哥的；墨西哥人的n.墨西哥人；墨西哥语','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modem','n.调制解调器（等于modulator-demodulator）','/ˈməʊdəm/','/ˈməʊdəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salad','n.色拉；尤指莴苣','/ˈsæləd/','/ˈsæləd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contrary','adj.相反的；对立的adv.相反地n.相反；反面','/ˈkɒntɹəɹi/','/ˈkɑntɹɛɹi/','noun',["contrary winds","What may be \"politically correct\" could be contrary to the teachings of Jesus.","a contrary disposition; a contrary child"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('education','n.教育；培养；教育学','/ˌɛdjʊˈkeɪʃn̩/','/ˌɛdjʊˈkeɪʃn̩/','noun',["2016-06-17 AROP JOSEPH \"Education is the slight hammer that breaks the yoke of ignorance, and moulds knowledge, skills, ideas, good moral values in a person be it a child, a youth or full grown adult. no matter a persons age learning never stops\".","He has had a classical education."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheer','v.欢呼；使高兴；为…加油n.欢呼；愉快；心情；令人愉快的事','/t͡ʃɪə(ɹ)/','/t͡ʃɪɹ/','noun',["a table loaded with good cheer","A cheer rose from the crowd.","We were cheered by the offer of a cup of tea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shout','v.呼喊；喊叫；大声说n.呼喊；呼叫','/ʃaʊt/','/ʃaʊt/','noun',["Next up the new single from Beyoncé, but first a shout to Barry Bloggins and his wife Belinda...","They shouted his name to get his attention.","He′s shouting us all to the opening night of the play."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pardon','n.原谅；赦免；宽恕v.原谅；赦免；宽恕','/ˈpɑɹ.dən/','/ˈpɑɹ.dn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nice','adj.精密的；美好的；细微的；和蔼的n.(Nice)人名；(英)尼斯','/naɪs/','/naɪs/','noun',["What is a nice person like you doing in a place like this?","The soup is nice and hot.","Children, play nice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purchase','n.购买；紧握；起重装置v.购买；赢得','/ˈpɜːtʃəs/','/ˈpɝtʃəs/','noun',["They offer a free hamburger with the purchase of a drink.","He was pleased with his latest purchase.","It is hard to get purchase on a nail without a pry bar or hammer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('owe','v.欠；感激；应给予；应该把……归功于n.(Owe)人名；(瑞典、挪)奥弗','/əʊ/','/oʊ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awake','v.觉醒，意识到；醒来；被唤起adj.醒着的','/əˈweɪk/','/əˈweɪk/','adjective',["They were awake to the possibility of a decline in sales."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everywhere','adv.到处n.每个地方','/ɛv.ɹi.(h)weə(ɹ)/','/ɛv.ɹi.(h)wɛɹ/','adverb',["He delivers the mail everywhere on this street.","I''ve looked everywhere in the house and still can''t find my glasses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fair','adj.公平的；美丽的，白皙的；[气象]晴朗的adv.公平地；直接地；清楚地v.转晴n.展览会；市集；美人','/feː(ə)/','/fɛəɹ/','noun',["When will we learn to distinguish between the fair and the foul?","Monday''s child is fair of face.","After scratching out and replacing various words in the manuscript, he scribed a fair copy to send to the publisher."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Ireland','n.爱尔兰','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pick','v.挑选；采摘；挖n.选择；鹤嘴锄；挖；掩护','/pɪk/','/pɪk/','noun',["so many picks to an inch","Don''t pick at that scab.","It''s time to pick the tomatoes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organiser','n.组织者；发起人；形成体（等于organizer）','','','noun',[]);
