INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weekend','n.周末，周末休假；周末聚会adj.周末的，周末用的v.度周末','/wiːˈkɛnd/','/ˈwiˌkɛnd/','noun',["We''ll weekend at the beach.","I''m wearing my weekend shoes.","a weekend break"]);
