INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lady','n.女士，夫人；小姐；妻子','/ˈleɪdi/','/ˈleɪdi/','noun',["Sir John Smith and Lady Smith.","\"I would like the dining room to be fully set by tonight; would you do so?\" \"Yes, my lady\".","Please direct this lady to the soft furnishings department."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slice','n.薄片；部分；菜刀，火铲v.切下；把…分成部分；将…切成薄片','/slaɪs/','/slaɪs/','noun',["Jim was munching on a slice of toast.","I bought a ham and cheese slice at the service station.","Slice the cheese thinly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('favour','n.偏爱；赞同；善行v.赞成；喜爱；有助于','/ˈfeɪ.və/','/ˈfeɪ.vɚ/','noun',["He did me a favor when he took the time to drive me home.","She enjoyed the queen''s favor.","A marriage favour is a bunch or knot of white ribbons or white flowers worn at a wedding."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Arctic','adj.北极的；极寒的n.北极圈；御寒防水套鞋','','','noun',[]);
