INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tune','n.曲调；和谐；心情v.调整；使一致；为…调音','/tjuːn/','/t(j)un/','noun',["Your engine needs a good tune.","This piano is not in tune.","to tune a piano or a violin"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foreign','adj.外国的；外交的；异质的；不相关的','/ˈfɒɹən/','/ˈfɔɹən/','noun',["He liked visiting foreign cities.","There are many more foreign students in Europe since the Erasmus scheme started.","foreign policy; foreign navies"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('funeral','n.葬礼；麻烦事adj.丧葬的，出殡的','/ˈfjuːnəɹəl/','/ˈfjunəɹəl/','noun',["Many mourners turned up at the local artist''s funeral to pay homage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compete','v.竞争；比赛；对抗','/kəm.ˈpiːt/','/kəm.ˈpiːt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallon','n.加仑（容量单位）','/ˈɡælən/','/ˈɡælən/','noun',["The pipe burst and gallons of water flooded into the kitchen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conduct','v.导电；带领n.进行；行为；实施','/kənˈdʌkt/','/ˈkɒndʌkt/','noun',["Good conduct will be rewarded and likewise poor conduct will be punished.","The commander conducted thousands of troops.","He conducted himself well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worth','adj.值…的n.价值；财产','/wɜːθ/','/wɝθ/','noun',["I’ll have a dollar''s worth of candy, please.","Our new director is a man whose worth is well acknowledged.","A painting worth thousands."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discovery','n.发现，发觉；被发现的事物','/dɪsˈkʌvəɹi/','/dɪsˈkʌvəɹi/','noun',["This latest discovery should eventually lead to much better treatments for disease.","Automatic discovery of RSS feeds by a Web browser.","The prosecution moved to suppress certain items turned up during discovery."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centre','v.以…为中心n.中心adj.中央的','/ˈsen.tə(ɹ)/','/ˈsɛn.tɚ/','noun',["shopping center, convention center, civic center, garment center, Lincoln Center for the Performing Arts, Rockefeller Center","the center of attention","He centered the heading of the document."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abrupt','adj.生硬的；突然的；唐突的；陡峭的','/aˈbɹʌpt/','/aˈbɹʌpt/','noun',["The party came to an abrupt end when the parents of our host arrived."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hot','adj.热的；辣的；热情的；激动的；紧迫的adv.热；紧迫地v.变热n.(Hot)人名；(塞)霍特；(法)奥特','/hɒt/','/hɑt/','verb',["He forgot that the frying pan was hot and burned his hand.","It is hotter in summer than in winter.","Aren''t you hot with that thick coat on?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solar','adj.太阳的；日光的；利用太阳光的；与太阳相关的n.日光浴室','/ˈsəʊlə/','/ˈsoʊlɚ/','adjective',["solar influence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clothing','n.（总称）[服装]服装；帆装v.覆盖（clothe的ing形式）；给…穿衣','/ˈkləʊðɪŋ/','/ˈkloʊðɪŋ/','verb',["to feed and clothe a family; to clothe oneself extravagantly","to clothe somebody with authority or power","The clothing and unclothing of the idols was of special significance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emergency','n.紧急情况；突发事件；非常时刻adj.紧急的；备用的','/ɪˈmɝ.dʒən.si/','/ɪˈmɝ.dʒən.si/','noun',["Cardiac arrest is an emergency and if you find someone in cardiac arrest you should call 999 immediately."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abandon','n.放任；狂热v.遗弃；放弃','/əˈbæn.dən/','/əˈbæn.dn̩/','verb',["Many baby girls have been abandoned on the streets of Beijing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sheep','n.羊，绵羊；胆小鬼','/ʃiːp/','/ʃip/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('computer','n.计算机；电脑；电子计算机','/kəmˈpjuːtə/','/kəmˈpjutɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('traditional','adj.传统的；惯例的','/tɹəˈdɪʃnəl/','/tɹəˈdɪʃnəl/','noun',["I think her traditional values are antiquated.","traditional expositions of the Scriptures.","The traditional form of the character has twice as many strokes as the simplified form."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plus','n.正号，加号；好处；附加额adj.正的；附加的prep.加，加上','/plʌs/','/plʌs/','noun',["He is a real plus to the team.","−2 * −2 = +4 (\"minus 2 times minus 2 equals plus four\")","He is a plus factor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('band','n.带，环；[物]波段；(演奏流行音乐的)乐队v.用带绑扎；给镶边','/bænd/','/bænd/','noun',["valence band;  conduction band"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('document','n.文件，公文；[计]文档；证件v.用文件证明','/ˈdɒkjʊmɛnt/','/ˈdɑkjʊmənt/','noun',["He documented each step of the process as he did it, which was good when the investigation occurred.","A ship should be documented according to the directions of law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gate','n.大门；出入口；门道v.给…装大门','/ɡeɪt/','/ɡeɪt/','noun',["The gate in front of the railroad crossing went up after the train had passed.","Singh was bowled through the gate, a very disappointing way for a world-class batsman to get out."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drum','v.击鼓；大力争取n.鼓；鼓声','/ˈdɹʌm/','/ˈdɹʌm/','noun',["Replace the drum unit of your printer.","The restaurant ordered ketchup in 50-gallon drums."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('library','n.图书馆，藏书室；文库','/ˈlaɪbɹi/','/ˈlaɪbɹəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nutrition','n.营养，营养学；营养品','/njuːˈtɹɪ.ʃən/','/nuˈtɹɪ.ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('may','aux.可以，能够；可能，也许；祝，愿；会，能','/meɪ/','/meɪ/','verb',["you may smoke outside;  may I sit there?","he may be lying;  Schrödinger''s cat may or may not be in the box","may you win;  may the weather be sunny"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shake','v.动摇；摇动；震动；握手n.摇动；哆嗦','/ˈʃeɪk/','/ˈʃeɪk/','noun',["She replied in the negative, with a shake of her head.","He shook the can of soda for thirty seconds before delivering it to me, so that, when I popped it open, soda went everywhere.","Shaking his head, he kept repeating \"No, no, no\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worthwhile','adj.值得做的，值得花时间的','/wɜː(ɹ)θˈwaɪl/','/wɜː(ɹ)θˈwaɪl/','adjective',["Doing volunteer work to help others is truly worthwhile."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quilt','n.被子；棉被v.东拼西凑地编；加软衬料后缝制','/kwɪlt/','/kwɪlt/','noun',["My grandmother is going to sew a quilt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('myself','pron.我自己；我亲自；我的正常的健康状况和正常情绪','/maɪˈsɛlf/','','pronoun',["I taught myself.","I feel like myself.","Myself John."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tease','v.取笑；戏弄；梳理；欺负；强求；使起毛n.戏弄；爱纠缠的小孩；挑逗者；卖弄风骚的女孩','/tiːz/','/tiːz/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('book','n.书籍；卷；帐簿；名册；工作簿v.预订；登记','/buːk/','/buːk/','noun',["He was frustrated because he couldn''t find anything about dinosaurs in the book.","I have three copies of his first book.","Genesis is the first book of the Bible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modern','adj.现代的，近代的；时髦的n.现代人；有思想的人','/ˈmɒd(ə)n/','/ˈmɑdɚn/','noun',["Our online interactive game is a modern approach to teaching about gum disease.  Although it was built in the 1600s, the building still has a very modern look."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sorry','adj.遗憾的；对不起的，抱歉的int.对不起，抱歉（表示委婉的拒绝等）','/ˈsɔɹi/','/ˈsɑɹi/','noun',["I am sorry I stepped on your toes. It was an accident.","The storm left his garden in a sorry state.","Bob is a sorry excuse for a football player."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parallel','n.平行线；对比v.使…与…平行adj.平行的；类似的，相同的','/ˈpæɹəˌlɛl/','/ˈpæɹəˌlɛl/','noun',["The 31st parallel passes through the center of my town.","Johnson''s parallel between Dryden and Pope","The horizontal lines on my notebook paper are parallel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evident','adj.明显的；明白的','/ˈɛ.vɪ.dənt/','/ˈɛ.vɪ.dənt/','adjective',["It was evident she was angry, after she slammed the door."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snack','n.小吃，快餐；一份，部分v.吃快餐，吃点心','/snæk/','/snæk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possibly','adv.可能地；也许；大概','/ˈpɒsɪbli/','/ˈpɑsəbli/','adverb',["It was possibly the costliest mistake in the organization''s history.","I couldn''t possibly be there on time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('your','pron.你的，你们的','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('authority','n.权威；权力；当局','/ɔːˈθɒɹəti/','/əˈθɑɹəti/','noun',["I have the authority to penalise the staff in my department, but not the authority to sack them.","the world''s foremost authority on orangutans"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('northern','adj.北部的；北方的n.北部方言','/ˈnɔːðn̩/','/ˈnɔɹðɚn/','noun',["Les Dawson was a famous northern comedian."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('by','prep.通过；被；依据；经由；在附近；在……之前adv.通过；经过；附近；[互联网]白俄罗斯的国家代码顶级域名','/baɪ/','/baɪ/','noun',["geography bee","I watched as it passed by.","The shop is hard by the High Street."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('following','adj.下面的；其次的，接着的n.下列事物；一批追随者v.跟随；沿行（follow的ing形式）','/ˈfɒləʊɪŋ/','/ˈfɑloʊɪŋ/','verb',["Follow that car!","B follows A in the alphabet.","Follow these instructions to the letter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seashell','n.海贝，贝壳；海贝壳','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pair','n.一对，一双，一副v.把…组成一对','/pɛə(ɹ)/','/pɛɹ/','noun',["I couldn''t decide which of the pair of designer shirts I preferred, so I bought the pair.","Spouses should make a great pair.","a pair of scissors; two pairs of spectacles; several pairs of jeans"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explore','v.探索；探测；探险','/ɪkˈsplɔː/','/ɪkˈsplɔɹ/','noun',["The committee has been exploring alternative solutions to the problem at hand.","It was around that time that the expedition began exploring the Arctic Circle.","It is normal for a boy of this age to be exploring his sexuality."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partner','n.伙伴；合伙人；配偶v.合伙；合股；成为搭档','/ˈpɐːtnə/','/ˈpɑɹtnɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spread','v.传播；伸展n.传播；伸展adj.伸展的','/spɹɛd/','/spɹɛd/','noun',["He spread his newspaper on the table.","I spread my arms wide and welcomed him home.","I spread the rice grains evenly over the floor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Swiss','adj.瑞士的；瑞士人的；瑞士风格的n.瑞士人；瑞士腔调','/swɪs/','/swɪs/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microscope','n.显微镜','/ˈmaɪkɹəˌskəʊp/','/ˈmaɪkɹəˌskəʊp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monument','n.纪念碑；历史遗迹；不朽的作品vt.为…树碑','/ˈmɒnjʊmənt/','/ˈmɑnjəmənt/','noun',["There is a monument on the town green to the soldiers who died in World War I."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slow','adj.慢的；减速的；迟钝的v.变慢；变萧条adv.慢慢地；迟缓地n.(Slow)人名；(英)斯洛','/sləʊ/','/sloʊ/','noun',["a slow train;  a slow computer","That clock is slow.","I''m just sitting here with a desk of cards, enjoying a slow afternoon."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worse','adj.更坏的；更差的；更恶劣的（bad的比较级）；（病情）更重的（ill的比较级）adv.更糟；更坏；更恶劣地；更坏地n.更坏的事；更恶劣的事','/wɜːs/','/wɝs/','adjective',["Abducting children is bad for mothers.","Do you think it is a bad idea to confront him directly?","It is bad manners to talk with your mouth full."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('particular','adj.特别的；详细的；独有的；挑剔的n.详细说明；个别项目','/pəˈtɪkjələ/','/pəˈtɪkjələ/','noun',["I couldn''t find the particular model you asked for, but I hope this one will do.","I don''t appreciate your particular brand of cynicism.","He brought no particular news."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bid','v.投标；出价；表示；吩咐n.出价；叫牌；努力争取','/bɪd/','/bɪd/','verb',["He bade me come in.","She was bidden to the wedding.","Have you ever bid in an auction?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('battery','n.[电]电池，蓄电池','/ˈbætəɹi/','/ˈbætəɹi/','noun',["Schoolchildren take a battery of standard tests to measure their progress."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tape','n.胶带；磁带；带子；卷尺v.录音；用带子捆扎；用胶布把…封住','/teɪ̯p/','/teɪ̯p/','noun',["Hand me some tape. I need to fix a tear in this paper.","After the party there was tape all over the place.","Jones broke the tape in 47.77 seconds, a new world record."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('later','adv.后来；稍后；随后adj.更迟的；更后的n.(Later)人名；(德)拉特','/ˈleɪtə/','/ˈleɪtɚ/','adjective',["It was late in the evening when we finally arrived.","It was getting late and I was tired.","Late Latin is less fully inflected than classical Latin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('envelope','n.信封，封皮；包膜；[天]包层；包迹','/ˈɒn.və.ləʊp/','/ˈɑn.vəˌloʊp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('short','adj.短的；不足的；矮的，低的n.短；缺乏；短路；短裤adv.不足；突然；唐突地','/ʃɔːt/','/ʃɔɹt/','noun',["38 short suits fit me right off the rack.","Jones smashes a grounder between third and short.","The market decline was terrible, but the shorts were buying champagne."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insect','n.昆虫；卑鄙的人','/ˈɪnsɛkt/','/ˈɪnsɛkt/','noun',["Our shed has several insect infestions, including ants, yellowjackets, and wasps.","The swamp is swarming with every sort of insect.","The manager’s assistant was the worst sort of insect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('might','n.力量；威力；势力v.可以；或许（may的过去式）；应该aux.可能；也许','/maɪt/','/maɪt/','noun',["He pushed with all his might, but still it would not move."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zone','n.地带；地区；联防v.分成区','/zəʊn/','/zoʊn/','noun',["Files in the Internet zone are blocked by default, as a security measure.","a zone of evergreens on a mountain; the zone of animal or vegetable life in the ocean around an island or a continent","That pitch was low and away, just outside of the zone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paint','v.油漆；绘画；装饰；涂色于；描绘；（用语言，文字等）描写；擦脂粉等n.油漆；颜料，涂料；绘画作品；胭脂等化妆品；色彩，装饰','/peɪnt/','/peɪnt/','noun',["The Nimrods are strong on the outside, but not very good in the paint.","I am running low on paint for my marker.","to paint a portrait or a landscape"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spring','n.春天；弹簧；泉水；活力；跳跃adj.春天的v.生长；涌出；跃出；裂开','/spɹɪŋ/','/spɹɪŋ/','verb',["to sprain one''s ankle","Spring is the time of the year most species reproduce.","The documentary made tears spring to their eyes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personally','adv.亲自地；当面；个别地；就自己而言','/ˈpɜːsnəli/','/ˈpɜːsnəli/','adverb',["Personally, I think that …","I like you personally, but as a colleague you are useless."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('directory','n.[计]目录；工商名录；姓名地址录adj.指导的；咨询的','/daɪˈɹɛktəɹi/','/daɪˈɹɛktəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('up','adv.起来；上涨；向上prep.在…之上；向…的较高处adj.涨的；起床的；向上的n.上升；繁荣','/ap/','/ʌp/','noun',["Up is a good way to go.","I hate almost everything about my job. The only up is that it''s so close to home.","She lives in a two-up two-down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warehouse','n.仓库；货栈；大商店v.储入仓库；以他人名义购进（股票）','','','noun',["the warehousing of syndicated TV shows"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freeway','n.高速公路','/ˈfɹiː.wei/','/ˈfɹiː.wei/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('that','pron.那；那个adv.那么；那样conj.因为；以至于adj.那；那个n.(That)人名；(德)塔特','/ˈðæt/','','noun',["\"The ribbon was that thin.\" \"I disagree, I say it was not that thin, it was thicker... or maybe thinner...\"","I did the run last year, and it wasn''t that difficult.","Ooh, I was that happy I nearly kissed her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('again','adv.又，此外；再一次；再说；增加n.（英、保）阿盖恩','/əˈɡeɪn/','/əˈɡeɪn/','adverb',["Great, thanks again!","Bring us word again.","The South will rise again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digital','adj.数字的；手指的n.数字；键','/ˈdɪd͡ʒɪtəɫ/','/ˈdɪd͡ʒɪtəɫ/','noun',["He moved to digital for the first time, using a Sony camera.","digital computer;  digital clock","Digital payment systems are replacing cash transactions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('random','adj.[数]随机的；任意的；胡乱的n.随意adv.胡乱地','/ˈɹændəm/','/ˈɹændəm/','noun',["The party was boring. It was full of randoms.","The flip of a fair coin is purely random.","A toss of loaded dice is still random, though biased."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maximum','n.[数]极大，最大限度；最大量adj.最高的；最多的；最大极限的','/ˈmæksɪməm/','/ˈmæksɪməm/','noun',["Use the proper dose for the maximum effect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horse','n.马；骑兵；脚架；海洛因v.使骑马；系马于；捉弄','/hɔːs/','/hɔɹs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monkey','n.猴子；顽童v.胡闹；捣蛋','/ˈmʌŋki/','/ˈmʌŋki/','noun',["He had been visiting an area zoo when a monkey swung from its tree perch, swiped his glasses and hurled them into a hippo hole.","Chimpanzees are known to form bands to hunt and kill other monkeys.","She''s a cheeky monkey."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flight','n.飞行；班机；逃走v.射击；使惊飞','/flaɪt/','/flaɪt/','noun',["Most birds are capable of flight.","The migrating birds'' flight took them to Africa.","a flight of swallows"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coin','v.铸造（货币）；杜撰，创造n.硬币，钱币','/kɔɪn/','/kɔɪn/','noun',["She spent some serious coin on that car!","What''s the best coin to buy right now?","to coin a medal"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('willingness','n.乐意；心甘情愿；自动自发','/ˈwɪlɪŋnəs/','/ˈwɪlɪŋnəs/','noun',["All it takes is a willingness to learn."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pork','n.猪肉vt.与女子性交','/pɔːk/','/pɔɹk/','noun',["The cafeteria serves pork on Tuesdays."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abolish','v.废除，废止；取消，革除','/əˈbɒlɪʃ/','/əˈbɑl.əʃ/','verb',["Slavery was abolished in the nineteenth century."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flood','v.淹没；充满；溢出n.洪水；泛滥；一大批','/flʌd/','/flʌd/','noun',["a flood of complaints","The floor was flooded with beer.","The station''s switchboard was flooded with listeners making complaints."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('react','v.反应；影响；反抗；起反作用','/ɹiːˈækt/','/ɹiːˈækt/','noun',["Sad reacts only","Every body reacts on the body that impels it from its natural state."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offer','v.提供；出价；试图n.提议；出价；意图；录取通知书','/ˈɑfɚ/','/ˈɔfɚ/','noun',["I decline your offer to contract.","His offer was $3.50 per share.","His first letter was not a real offer, but an attempt to determine interest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bend','v.使弯曲；使屈服；使致力；使朝向n.弯曲','/bɛnd/','/bɛnd/','noun',["There''s a sharp bend in the road ahead.","A diver who stays deep for too long must ascend very slowly in order to prevent the bends.","the midship bends"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constant','adj.不变的；恒定的；经常的n.[数]常数；恒量','/ˈkɒnstənt/','/ˈkɑnstənt/','noun',["constant time   constant space"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guilty','adj.有罪的；内疚的','/ˈɡɪl.ti/','/ˈɡɪl.ti/','noun',["He was guilty of cheating at cards.","The guilty man was led away.","Do you have a guilty conscience?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('web','n.网；卷筒纸；蹼；织物；圈套v.用网缠住；使中圈套','/wɛb/','/wɛb/','proper noun',["Some of that content is now only available on the Web.","The sunlight glistened in the dew on the web.","Let me search the web for that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('description','n.描述，描写；类型；说明书','/dɪˈskɹɪpʃən/','','noun',["The zoo had no lions, tigers, or cats of any description.","The type description of the fungus was written by a botanist."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fear','n.害怕；恐惧；敬畏；担心v.害怕；敬畏；为…担心','/fɪə/','/fɪəɹ/','noun',["He was struck by fear on seeing the snake.","Not everybody has the same fears.  I have a fear of ants.","I fear the worst will happen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choose','v.选择，决定','/t͡ʃuːz/','/t͡ʃuːz/','verb',["I chose a nice ripe apple from the fruit bowl.","He was chosen as president in 1990.","I chose to walk to work today."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prisoner','n.囚犯，犯人；俘虏；刑事被告','/ˈpɹɪzənəɹ/','/ˈpɹɪzənəɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('towel','n.毛巾，手巾；[纸]纸巾v.用毛巾擦','/taʊl/','/taʊl/','noun',["He got out of the shower and toweled himself dry."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tiny','adj.微小的；很少的n.(Tiny)人名；(葡、印)蒂尼','/ˈtaɪni/','/ˈtaɪni/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tension','n.张力，拉力；紧张，不安；电压vt.使紧张；使拉紧','/ˈtɛnʃən/','/ˈtɛnʃən/','noun',["We tensioned the cable until it snapped."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cover','v.包括；采访，报导；涉及n.封面，封皮；盖子；掩蔽物;幌子，借口','/ˈkʌvə/','/ˈkʌvɚ/','noun',["The soldiers took cover behind a ruined building.","There''s a $15 cover tonight.","We need to set another cover for the Smith party."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tree','n.树；木料；树状物v.把赶上树','/tɹiː/','/tɹi/','noun',["Birds have a nest in a tree in the garden.","the banana tree","He had the choice of buying a scratching post or a cat tree."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('founding','adj.创办的；发起的v.[机]铸造；建造；以…为基础（found的ing形式）n.[机]铸造；溶解','/ˈfaʊndɪŋ/','/ˈfaʊndɪŋ/','verb',["the founding of the republic","The founding fathers of our country."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wonderful','adj.极好的，精彩的，绝妙的；奇妙的；美妙；胜；神妙','/ˈwʌn.də.fl/','/ˈwʌn.dɚ.fl̩/','adjective',["They served a wonderful six-course meal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('position','n.位置，方位；职位，工作；姿态；站位v.安置；把……放在适当位置','/pəˈzɪʃ(ə)n/','/pəˈzɪʃ(ə)n/','noun',["Chief of Staff is the second-highest position in the army.","My position on this issue is unchanged.","Stand in this position, with your arms at your side."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yard','n.院子；码（英制中丈量长度单位，1码=3英尺）；庭院；帆桁vt.把…关进或围在畜栏里','/jɑːd/','/jɑɹd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('else','adv.其他；否则；另外adj.别的；其他的n.(Else)人名；(英)埃尔斯；(德)埃尔泽；(芬、丹)埃尔塞','/ɛls/','/ɛls/','adjective',["The instructor is busy. Can anyone else help me?","How else (=in what other way) can it be done?","Then the Wronskian of f and g must be nonzero, else they could not be linearly independent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expand','v.扩张；使膨胀；详述','/ɛkˈspænd/','/ɛkˈspænd/','verb',["You can expand this compact umbrella to cover a large table.","A flower expands its leaves.","Use the binomial theorem to expand {(x+1)}^4."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mm','abbr.毫米（millimeter）n.缅甸的域名','','','interjection',["Mmm, this is a tasty pie!","Mmm, I see what you mean.","July is my favourite month."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('country','n.国家，国土；国民；乡下，农村；乡村；故乡adj.祖国的，故乡的；地方的，乡村的；国家的；粗鲁的；乡村音乐的','/ˈkʌntɹi/','/ˈkʌntɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('below','adv.在下面，在较低处；在本页下面prep.在…下面n.(Below)人名；(英、德、芬、瑞典)贝洛','/bɪˈləʊ/','/bəˈloʊ/','adverb',["the landlubbers lying down below","The treasure is buried two meters below the surface.","\"By their execution hereof, the Parties incur a legal obligation to pass consideration under this Loan Contract as is set forth below.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('press','v.压；按；逼迫；紧抱n.压；按；新闻；出版社；[印刷]印刷机','/pɹɛs/','/pɹɛs/','noun',["a flower press","Stop the presses!","This article appeared in the press."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saucer','n.茶托，浅碟；浅碟形物；眼睛','/ˈsɔː.sə/','/ˈsɔː.sə/','noun',["The saucer-shaped object could have been a UFO."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('literature','n.文学；文献；文艺；著作','/ˈlɪ.tə.ɹɪ.tʃə(ɹ)/','/ˈlɪ.tə.ɹɪ.tʃə(ɹ)/','noun',["However, even “literary” science fiction rarely qualifies as literature, because it treats characters as sets of traits rather than as fully realized human beings with unique life stories. —Adam Cadre, 2008"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meanwhile','adv.同时，其间n.其间，其时','/ˈmiːnhwaɪl/','/ˈmiːnhwaɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ridiculous','adj.可笑的；荒谬的','/ɹiːˈdɪkjʊləs/','/ɹiːˈdɪkjʊləs/','adjective',["It''s ridiculous to charge so much for a little souvenir.","Gaines is a classic motor player with a low center of gravity and ridiculous strength."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('least','adj.最小的；最少的（little的最高级）adv.最小；最少n.最小；最少','/list/','/list/','noun',["It was the least surprising thing.","They travel the least of all."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('packet','n.数据包，信息包；小包，小捆vt.包装，打包','/ˈpak.ɪt/','/ˈpak.ɪt/','noun',["Don''t throw the crisp packet on the floor!","2012 August 6, Wendy Knowler, Plastic packets: who bags the profits?","It''ll cost a packet to fix this."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('failure','n.失败；故障；失败者；破产','/ˈfeɪl.jɚ/','/ˈfeɪl.jɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apartment','n.公寓；房间','/əˈpɑːt.mənt/','/əˈpɑɹt.mənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conscience','n.道德心，良心','/kɒnʃəns/','/kɒnʃəns/','noun',["Your conscience is your highest authority."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('running','n.运转；赛跑；流出adj.连续的；流动的；跑着的；运转着的v.跑；运转（run的ing形式）；行驶','/ˈɹʌnɪŋ/','/ˈɹʌnɪŋ/','verb',["He is running the candidate''s expensive campaign.","I have decided to run for governor of California.","He ran his best horse in the Derby."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worldwide','adj.全世界的adv.在世界各地','/ˈwɜːldwaɪd/','/ˈwɝldˌwaɪd/','adjective',["A large meteorite impact would cause worldwide extinction of life.","English is spoken worldwide."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('on','adv.向前地；作用中，行动中；继续着prep.向，朝……；关于；在……之上；在……时候adj.开着的；发生着的，正在进行中n.(On)人名；(日)温(姓、名)；(缅、柬、印)翁','/ɒn/','/ɔn/','verb',["Can you on the light?","All the lights are on, so they must be home.","Are we still on for tonight?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appendix','n.附录；阑尾；附加物','/əˈpɛn.dɪks/','/əˈpɛn.dɪks/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Canada','n.加拿大（北美洲国家）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parent','n.父亲（或母亲）；父母亲；根源','/ˈpɛəɹənt/','/ˈpeəɹənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kill','v.杀死；扼杀；使终止；抵消n.杀戮；屠杀adj.致命的；致死的','/kɪl/','/kɪl/','noun',["The assassin liked to make a clean kill, and thus favored small arms over explosives.","The hunter delivered the kill with a pistol shot to the head.","The fox dragged its kill back to its den."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frighten','v.使惊吓；吓唬…','/ˈfɹaɪtn̩/','/ˈfɹaɪtn̩/','verb',["Avery puts a sheet over her head, pretending to be a ghost to frighten Emily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unsafe','adj.不安全的；危险的；不安稳的','/ʌnˈseɪf/','/ʌnˈseɪf/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('term','n.术语；学期；期限；条款；(代数式等的)项v.把…叫做','/tɜːm/','/tɝm/','noun',["\"Alright, look...we can spend the holidays with your parents, but this time it will be on my terms.\"","The term of a lease agreement is the period of time during which the lease is effective, and may be fixed, periodic, or of indefinite duration.","Be sure to read the terms and conditions before signing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bureaucratic','adj.官僚的；官僚政治的','','','adjective',["the European Union is legalistic, bureaucratic and runs by precedent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gown','n.长袍，长外衣；礼服；睡袍；法衣v.使穿睡衣','/ɡaʊn/','/ɡaʊn/','noun',["In the perennial town versus gown battles, townies win some violent battles, but the collegians are winning the war."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crazy','adj.疯狂的；狂热的，着迷的','/ˈkɹeɪzi/','/ˈkɹeɪzi/','noun',["His ideas were both frightening and crazy.","When she gets on the motorcycle she goes crazy.","He went crazy when he won."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outward','adj.向外的；外面的；公开的；外服的；肉体的adv.向外（等于outwards）；在外；显而易见地n.外表；外面；物质世界','/ˈaʊt.wəd/','/ˈaʊt.wɚd/','adjective',["By all outward indications, he''s a normal happy child, but if you talk to him, you will soon realize he has some psychological problems.","an outward war","We are outward bound."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exploit','v.开发，开拓；剥削；开采n.勋绩；功绩','','','noun',["The first trek to the summit of Mount Everest was a stunning exploit.","Materialistic monsters who exploit \"kind\" folks will not have good outcomes, no matter how much comforts were ill-gained."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divide','v.划分；除；分开；使产生分歧n.[地理]分水岭，分水线','/dɪˈvaɪd/','','noun',["Stay on your side of the divide, please.","The divide left most of the good land on my share of the property.","There is a great divide between us."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('line','n.路线，航线；排；绳v.排成一行；划线于；以线条标示；使…起皱纹','/laɪn/','/laɪn/','noun',["The arrow descended in a curved line.","a brake line","the line of sight"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bag','n.袋；猎获物；（俚）一瓶啤酒v.猎获；把…装入袋中；占据，私吞；使膨大','/ˈbæːɡ/','/ˈbeɪɡ/','noun',["Acid House is not my bag: I prefer the more traditional styles of music.","The grounder hit the bag and bounced over the fielder’s head.","He headed back to the bag."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sail','v.航行；启航，开船n.帆，篷；航行','/seɪl/','/seɪl/','noun',["Take in sail: a storm is coming.","Let''s go for a sail.","Twenty sail were in sight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('untrue','adj.不真实的；不合标准的；不忠实的；不正当的','','','adjective',["She says that I stole her necklace, but that''s completely untrue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reading','n.阅读，朗读；读物；读数adj.阅读的v.阅读（read的ing形式）','/ˈɹidiŋ/','/ˈɹidiŋ/','verb',["Have you read this book?","All right, class, who wants to read next?","At the moment I''m reading Milton."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toward','prep.向；对于；为了；接近adj.即将来到的，进行中的n.(Toward)人名；(英)特沃德','/tɘ.ˈwoːd/','/tʊ.ˈwɔɹd/','adjective',["She moved toward the door.","What are your feelings toward him?","I''m saving money toward retirement."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discrimination','n.歧视；区别，辨别；识别力','/dɪskɹɪmɪˈneɪʃən/','/dɪskɹɪmɪˈneɪʃən/','noun',["reverse discrimination"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interval','n.间隔；间距；幕间休息','/ˈɪntəvəl/','/ˈɪntɚvəl/','noun',["the interval between contractions during childbirth"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outgoing','adj.对人友好的，开朗的；出发的，外出的；即将离职的；乐于助人的n.外出；流出；开支v.超过；优于（outgo的ing形式）','','','verb',["Tom is very outgoing and enjoys meeting people; his brother, on the other hand, is painfully shy.","Is there any outgoing post?","The outgoing politician wasn''t too disappointed he''d lost the election; he was tired of political infighting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subtraction','n.[数]减法；减少；差集','/səbˈtɹækʃən/','/səbˈtɹækʃən/','noun',["The teacher has set us ten subtractions to do by tomorrow.","The subtraction of the wealth from the economy will result in recession."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kid','n.小孩；小山羊v.欺骗；取笑；戏弄adj.小山羊皮制的；较年幼的','/kɪd/','/kɪd/','noun',["He treated the oxen like they didn''t exist, but he treated the goat kid like a puppy.","She''s a kid. It''s normal for her to have imaginary friends.","He''s been living in Los Angeles for years now, but he''s a Florida kid."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('singer','n.歌手，歌唱家','/ˈsɪŋə/','/ˈsɪŋɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hire','n.雇用，租用；租金，工钱v.雇用；出租','/haɪə/','/haɪɹ/','noun',["The sign offered pedalos on hire.","When my grandfather retired, he had over twenty mechanics in his hire.","We pair up each of our new hires with one of our original hires."]);
