INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rob','v.抢劫；使…丧失；非法剥夺','/ɹɒb/','/ɹɑb/','verb',["He robbed three banks before he was caught.","The best way to rob a bank is to own one.","Working all day robs me of any energy to go out in the evening."]);
