INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('truck','n.卡车；交易；手推车v.驾驶卡车；以物易物adj.（美）运货汽车的','/tɹʌk/','/tɹʌk/','noun',["Mexican open-bed trucks haul most of the fresh produce that comes into the United States from Mexico.","Last week, Cletus trucked 100 pounds of lumber up to Dubuque.","Keep on trucking!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallery','n.画廊；走廊；旁听席；地道vt.在…修建走廊；在…挖地道vi.挖地道','/ˈɡæləɹi/','/ˈɡæləɹi/','noun',["a clip-art gallery in a wordprocessor"]);
