INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glad','adj.高兴的；乐意的；令人高兴的；灿烂美丽的vt.使高兴n.(Glad)人名；(塞、瑞典)格拉德；(英)格莱德；(法、挪)格拉','/ɡlæd/','/ɡlæd/','verb',["I''m glad the rain has finally stopped."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inch','n.英寸；身高；少许v.使缓慢地移动','/ɪntʃ/','/ɪntʃ/','noun',["\"Don''t move an inch!\"","Fearful of falling, he inched along the window ledge."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('teach','v.教；教授；教导n.(Teach)人名；(英)蒂奇','/tiːt͡ʃ/','/tiːt͡ʃ/','verb',["‘The bliss is there’, mumbled the old man and taught to Heaven.","Can you teach me to sew?  Can you teach sewing to me?","She used to teach at university."]);
