INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fairness','n.公平；美好；清晰；顺利性','','','noun',["Some questioned the fairness of the new laws."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('report','n.报告；报道；成绩单v.报告；报导；使报到','/ɹəˈpoːt/','/ɹɪˈpɔɹt/','noun',["A report by the telecommunications ministry on the phone network revealed a severe capacity problem.","For insurance reasons, I had to report the theft to the local police station.","If you do that again I''ll report you to the boss."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neck','n.脖子；衣领；海峡v.搂著脖子亲吻；变狭窄','/nɛk/','/nɛk/','noun',["Giraffes have long necks.","a neck forming the journal of a shaft","to risk one''s neck; to save someone''s neck"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('member','n.成员；会员；议员','/ˈmɛmbə/','/ˈmɛmbɚ/','noun',["The I-beams were to become structural members of a pedestrian bridge.","The zip file holding the source code of this application has 245 members."]);
