INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jam','n.果酱；拥挤；困境；扣篮v.使堵塞；挤进，使塞满；混杂；压碎','/ˈdʒæm/','/ˈdʒæm/','noun',["A traffic jam caused us to miss the game''s first period.","Her poor little baby toe got jammed in the door.","The rush-hour train was jammed with commuters."]);
