INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cross','n.交叉，十字；十字架，十字形物v.交叉；杂交；横过adj.交叉的，相反的；乖戾的；生气的','/kɹɑs/','/kɹɔs/','noun',["Put a cross for a wrong answer and a tick for a right one.","Criminals were commonly executed on a wooden cross.","She made the cross after swearing."]);
