INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dawn','n.黎明；开端v.破晓；出现；被领悟','/doːn/','/dɔn/','noun',["She rose before dawn to meet the train.","the dawn of civilization","A new day dawns."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diverse','adj.不同的；多种多样的；变化多的','/daɪˈvɜːs/','/daɪ.ˈvɝs/','adjective',["Idris Elba was a diverse hire for the franchise"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('someone','pron.有人，某人','/ˈsʌmwʌn/','/ˈsʌmwʌn/','noun',["Do you need a gift for that special someone?","He thinks he has become someone.","Can someone help me, please?"]);
