INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smell','v.嗅，闻；有…气味n.气味，嗅觉；臭味','/smɛl/','/smɛl/','noun',["I love the smell of fresh bread.","I can smell fresh bread.","Her feet smell of cheese."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('matter','n.物质；事件v.有关系；要紧','/ˈmætə/','/ˈmætɚ/','noun',["What''s the matter?;   state matters","I stayed for a matter of months.","Sorry for pouring ketchup on your clean white shirt! - Oh, don''t worry, it does not matter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barbecue','n.烤肉；吃烤肉的野宴v.烧烤；烤肉','/ˈbɑːbɪˌkjuː/','/ˈbɑɹbɪˌkju/','noun',["We cooked our food on the barbecue.","We''re having a barbecue on Saturday, and you''re invited.","She ordered a plate of barbecue with a side of slaw."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aside','adv.离开，撇开；在旁边n.旁白；私语，悄悄话；离题的话prep.在…旁边','/əˈsaɪd/','/əˈsaɪd/','noun',["Move aside, please, so that these people can come through."]);
