INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lake','n.湖；深红色颜料；胭脂红vt.（使）血球溶解vi.（使）血球溶解','/leɪk/','/leɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('my','pron.我的int.哎呀（表示惊奇等）；喔唷n.(My)人名；(越)美；(老、柬)米','/mi/','/mi/','interjection',["My, what big teeth you have!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plate','n.碟；金属板；金属牌；感光底片v.电镀；给…装甲','/pleɪt/','/pleɪt/','noun',["I filled my plate from the bountiful table.","I ate a plate of beans.","The meat plate was particularly tasty."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approximately','adv.大约，近似地；近于','/əˈpɹɒk.sɪ.mət.li/','/əˈpɹɒk.sɪ.mət.li/','adverb',["...approximately 60 beats per minute."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diet','n.饮食；食物；规定饮食v.节食','/ˈdaɪət/','/ˈdaɪət/','noun',["The diet of the Giant Panda consists mainly of bamboo.","He''s been reading a steady diet of nonfiction for the last several years.","diet soda"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('way','n.方法；道路；方向；行业；习惯adv.大大地；远远地adj.途中的','/weɪ/','/weɪ/','noun',["You''re going about it the wrong way.  He''s known for his quirky ways.  I don''t like the way she looks at me.","When I returned home, I found my house and belongings in a most terrible way.","To walk the Way of the Runes, you must experience the runes as they manifest both in the part of Midgard that lies outside yourself and the worlds within. (Diana Paxson)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diamond','n.钻石，金刚石；菱形；方块牌adj.菱形的；金刚钻的','/ˈdaɪ(ə)mənd/','/ˈdaɪ(ə)mənd/','noun',["The saw is coated with diamond.","The dozen loose diamonds sparkled in the light.","What a beautiful engagement diamond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remain','v.保持；依然；留下；剩余；逗留；残存n.遗迹；剩余物，残骸','/ɹɪˈmeɪn/','/ɹɪˈmeɪn/','noun',["There was no food in the house, so I had to remain hungry.","The light remained red for two full minutes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aircraft','n.飞机，航空器','/ɛə.kɹɑːft/','/ɛəɹ.kɹæft/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curtain','n.幕；窗帘v.遮蔽；装上门帘','/ˈkɜːtn̩/','/ˈkɝtn̩/','noun',["He took so long to shave his head that we arrived 45 minutes after curtain and were denied late entry."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dig','v.挖，掘；探究n.戳，刺；挖苦','/dɪɡ/','/dɪɡ/','noun',["He guffawed and gave me a dig in the ribs after telling his latest joke.","a £1 charity shop dig","If the plane can''t pull out of the dive it is in, it''ll dig a hole in the ground."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Scotland','n.苏格兰','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('age','n.年龄；时代；寿命，使用年限；阶段v.成熟；变老','/eɪd͡ʒ/','/eɪd͡ʒ/','noun',["the age of infancy","the age of consent; the age of discretion","the golden age; the age of Pericles"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bamboo','n.竹，竹子vt.为…装上篾条adj.竹制的；土著居民的','/bæmˈbu/','/bæmˈbu/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arch','n.弓形，拱形；拱门adj.主要的v.使…弯成弓形；用拱连接','/ɑːt͡ʃ/','/ɑɹt͡ʃ/','noun',["to pass into the arch of a bridge","The cat arched its back"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poet','n.诗人','/ˈpəʊɪt/','/ˈpəʊɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fan','v.煽动；刺激；吹拂n.迷；风扇；爱好者','/fæn/','/fæn/','noun',["We enjoyed standing at the edge of the cliff, being fanned by the wind.","I attempted to fan the disagreeable odour out of the room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breast','n.乳房，胸部；胸怀；心情v.以胸对着；与…搏斗','/bɹɛst/','/bɹɛst/','noun',["Tanya''s breasts grew remarkably during pregnancy.","She kindled hope in the breast of all who heard her.","The robin has a red breast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleeve','n.[机]套筒，[机]套管；袖子，[服装]袖套vt.给……装袖子；给……装套筒','/sliːv/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mentally','adv.精神上，智力上；心理上','/ˈmɛntəli/','/ˈmɛntəli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('power','n.力量，能力；电力，功率；政权，势力；[数]幂v.激励；供以动力；使…有力量adj.借影响有权势人物以操纵权力的','/ˈpaʊ.ə(ɹ)/','/ˈpaʊ.ɚ/','noun',["the mechanical powers","This CD player is powered by batteries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('via','prep.渠道，通过；经由','/ˈvaɪə/','/ˈvaɪə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tick','v.标记号于；滴答地记录n.滴答声；扁虱；记号；赊欠','/tɪk/','/tɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relax','v.放松，休息；松懈，松弛；变从容；休养','/ɹɪˈlæks/','/ɹɪˈlæks/','verb',["to relax a rope or cord","to relax discipline","Amusement relaxes the mind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawing','n.图画；牵引；素描术v.绘画；吸引（draw的ing形式）；拖曳','/ˈdɹɔ.(w)ɪŋ(ɡ)/','/ˈdɹɔ.(w)ɪŋ(ɡ)/','verb',["She had to draw upon her experience to solve the problem.","We drew last time we played.  I drew him last time I played him.  I drew my last game against him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rough','adj.粗糙的；粗略的；粗野的；艰苦的；未经加工的v.使粗糙；粗暴对待；草拟n.艰苦；高低不平的地面；未经加工的材料；粗糙的部分adv.粗糙地；粗略地；粗暴地','/ɹʌf/','/ɹʌf/','noun',["Rough in the shape first, then polish the details.","a rough estimate; a rough sketch of a building; a rough plan","rough sea"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('systematic','adj.系统的；体系的；有系统的；[图情]分类的；一贯的，惯常的','/ˌsɪs.təˈmæt.ɪk/','/ˌsɪs.təˈmæt.ɪk/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barber','v.为…理发；修整n.理发师','/ˈbɑː.bə/','/ˈbɑɹ.bɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trouble','n.麻烦；烦恼；故障；动乱v.麻烦；使烦恼；折磨','/ˈtɹʌb(ə)l/','/ˈtɹə-/','noun',["He was in trouble when the rain started.","The trouble was a leaking brake line.   The trouble with that suggestion is that we lack the funds to put it in motion.   The bridge column magnified the trouble with a slight tilt in the wrong direction.","the troubles in Northern Ireland"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('male','adj.男性的；雄性的；有力的n.男人；雄性动物','/meɪl/','/meɪl/','noun',["a male bird feeding a seed to a female","stereotypically male interests, an insect with typically male coloration","the male chromosome;   like testes, ovaries also produce testosterone and some other male hormones"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('production','n.成果；产品；生产；作品','/pɹəˈdʌkʃən/','/pɹəˈdʌkʃən/','noun',["The widget making machine is being used for production now.","The widgets are coming out of production now.","They hope to increase spaghetti production next year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('down','adv.向下，下去；在下面adj.向下的n.软毛，绒毛；[地质]开阔的高地prep.沿着，往下v.打倒，击败','/daʊn/','/daʊn/','noun',["I love almost everything about my job. The only down is that I can''t take Saturdays off.","I bet after the third down, the kicker will replace the quarterback on the field.","I haven''t solved 12 or 13 across, but I''ve got most of the downs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liquid','adj.液体的；清澈的；明亮的；易变的n.液体，流体；流音','/ˈlɪkwɪd/','/ˈlɪkwɪd/','noun',["A liquid can freeze to become a solid or evaporate into a gas.","liquid nitrogen","a liquid melody"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adolescence','n.青春期','/ˌædəˈlɛsəns/','/ˌædəˈlɛsəns/','noun',["During adolescence, the body and mind go through many complex changes, some of which are difficult to deal with."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neighbour','n.n邻居;同胞；仁慈的人v.邻接adj.邻居的；邻近的','/ˈneɪbə/','/ˈneɪbɚ/','noun',["My neighbour has two noisy cats.","Though France neighbours Germany, its culture is significantly different.","That sort of talk is neighbouring on treason."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('potential','n.潜能；可能性；[电]电势adj.潜在的；可能的；势的','/pəˈtɛnʃəl/','/po(ʊ)ˈtɛnʃəl/','noun',["Even from a young age it was clear that she had the potential to become a great musician."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('first','adv.第一；首先；优先；宁愿n.第一；开始；冠军adj.第一的；基本的；最早的num.第一','/fɪrst/','/fɝst/','noun',["He was the first to complete the course.","This is a first. For once he has nothing to say.","There was a close play at first."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diagram','n.图表；图解v.用图解法表示','/ˈdaɪ.ə.ɡɹæm/','/ˈdaɪ.ə.ɡɹæm/','noun',["Electrical diagrams show device interconnections."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memory','n.记忆，记忆力；内存，[计]存储器；回忆','/ˈmɛm(ə)ɹi/','/ˈmɛm(ə)ɹi/','noun',["Memory is a facility common to all animals.","I have no memory of that event.","This data passes from the CPU to the memory."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unhappy','adj.不快乐的；不幸福的；不适当的','/ʌnˈhæpi/','/ʌnˈhæpi/','noun',["An unhappy customer is unlikely to return to your shop.","The doomed lovers must have been born under an unhappy star."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distant','adj.遥远的；冷漠的；远隔的；不友好的，冷淡的','/ˈdɪstənt/','','adjective',["We heard a distant rumbling but didn''t pay any more attention to it.   She was surprised to find that her fiancé was a distant relative of hers.   His distant look showed that he was not listening to me.","Ever since our argument, she has been totally distant toward me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fence','n.栅栏；围墙；剑术v.防护；用篱笆围住；练习剑术','/fɛns/','/fɛns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crowd','n.群众,一伙;一堆,许多,大众v.拥挤,挤满,挤进','/kɹaʊd/','/kɹaʊd/','noun',["After the movie let out, a crowd of people pushed through the exit doors.","There was a crowd of toys pushed beneath the couch where the children were playing.","That obscure author''s fans were a nerdy crowd which hardly ever interacted before the Internet age."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('function','n.功能；[数]函数；职责；盛大的集会v.运行；活动；行使职责','/ˈfʌŋ(k)ʃən/','/ˈfʌŋkʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bird','n.鸟；家伙；羽毛球v.向…喝倒彩；起哄','/bɜd/','/bɝd/','noun',["Ducks and sparrows are birds.","Mike went out with his bird last night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classify','v.分类；分等','/ˈklæsɪfaɪ/','/ˈklæsɪfaɪ/','verb',["Should we classify \"make up\" as an idiom or as a phrasal verb?","They decided to classify that information."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explicit','adj.明确的；清楚的；直率的；详述的','/ɪkˈsplɪsɪt/','/ɪkˈsplɪsɪt/','adjective',["I gave explicit instructions for him to stay here, but he followed me, anyway.","The film had several scenes including explicit language and sex."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lightning','adj.闪电的；快速的n.闪电vi.闪电','/ˈlaɪt.nɪŋ/','/ˈlaɪt.nɪŋ/','noun',["Although we did not see the lightning, we did hear the thunder.","That tree was hit by lightning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('step','n.步，脚步；步骤；步伐；梯级v.踏，踩；走','/stɛp/','/stɛp/','noun',["He improved step by step, or by steps.","The driver must have a clear view of the step in order to prevent accidents.","One step is generally about three feet, but may be more or less."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jog','v.慢跑；轻推；蹒跚行进；使颠簸n.慢跑；轻推，轻撞','/dʒɒɡ/','/dʒɑɡ/','noun',["jog one''s elbow","I tried desperately to jog my memory.","to jog a horse"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('already','adv.已经，早已；先前','/ɑlˈɹɛdi/','/ɔlˈɹɛdi/','adverb',["Are you quitting already?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('night','n.夜晚，晚上；黑暗，黑夜adj.夜晚的，夜间的','/naɪt/','/naɪt/','noun',["How do you sleep at night when you attack your kids like that!?","a night on the town","I stayed my friend''s house for three nights."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawer','n.抽屉；开票人；出票人；起草者；酒馆侍','/dɹɔː(ɹ)/','/dɹɔɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wooden','adj.木制的；僵硬的，呆板的','/ˈwʊdən/','/ˈwʊdən/','adjective',["On a recent windy day, hundreds of visitors climbed wooden stairs to take pictures in front of the glacier.","wooden acting"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accessible','adj.易接近的；可进入的；可理解的','','/əkˈsɛs.ə.bəl/','adjective',["an accessible town or mountain","accessible public transport"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passive','adj.被动的，消极的；被动语态的n.被动语态','/ˈpæs.ɪv/','/ˈpæs.ɪv/','noun',["He remained passive during the protest.","a passive balloon; a passive aeroplane; passive flight, such as gliding and soaring"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wonder','n.惊奇；奇迹；惊愕v.怀疑；想知道；惊讶adj.奇妙的；非凡的','/ˈwʌndə/','/ˈwʌndɚ/','noun',["Wonders of the World seem to come in sevens.","The idea was so crazy that it is a wonder that anyone went along with it.","He''s a wonder at cooking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ought','aux.应该，应当；大概vi.应该，应当；大概','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transform','v.改变，使…变形；转换','/tɹænzˈfɔːm/','/tɹænzˈfɔɹm/','noun',["The alchemists sought to transform lead into gold."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defend','v.辩护；防护','/dɪˈfɛnd/','/diˈfɛnd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kilometre','n.[计量]公里；[计量]千米','/kɪˈlɒmɪtə/','/kəˈlɑmɪtəɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talk','v.说；谈话；讨论n.谈话；演讲；空谈','/toːk/','/toːk/','verb',["Although I don''t speak Chinese I managed to talk with the villagers using signs and gestures.","That''s enough about work, let''s talk holidays!","We talk French sometimes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('girl','n.女孩；姑娘，未婚女子；女职员，女演员；（男人的）女朋友','/ɡɵːl/','/ɡɝl/','noun',["Your girl turned up on our doorstep.","Don''t be such a girl!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambassador','n.大使；代表；使节','/æmˈbæs.ə.də(ɹ)/','/æmˈbæs.ə.də(ɹ)/','noun',["As front hall porter, you are an ambassador for the hotel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grass','n.草；草地，草坪v.放牧；使……长满草；使……吃草','[ɡɹ̠ɑːs]','[ɡɹ̠eəs]','noun',["What just happened must remain secret. Don''t be a ''grass."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('billion','n.十亿；大量num.十亿adj.十亿的','/ˈbɪljən/','/ˈbɪljən/','noun',["There were billions of people at the concert."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('summary','adj.简易的；扼要的n.概要，摘要，总结','/ˈsʌməɹi/','/ˈsʌməɹi/','noun',["A summary review is in the appendix.","They used summary executions to break the resistance of the people.","Summary justice is bad justice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Moslem','adj.穆斯林的；伊斯兰教的；回教的n.穆斯林；穆罕默德信徒；伊斯兰','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wire','n.电线；金属丝；电报v.拍电报；给…装电线','/waɪə(ɹ)/','/ˈwaɪɚ/','noun',["This election is going to go right to the wire","to pull the wires for office","We need to wire that hole in the fence."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('morning','n.早晨；黎明；初期','/ˈmɔːnɪŋ/','/ˈmɔɹnɪŋ/','noun',["I''ll see you tomorrow morning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depend','v.依赖，依靠；取决于；相信，信赖','/dɪˈpɛnd/','/dɪˈpɛnd/','verb',["We would like to go skiing, but it depends on the amount of snow.","we depend on the mailman to come at the usual time.","a cause depending in court"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fold','v.折叠；合拢；抱住；笼罩n.折痕；信徒；羊栏','/fəʊld/','/foʊld/','noun',["After two reraises in quick succession, John realised his best option was probably a fold.","If you fold the sheets, they''ll fit more easily in the drawer.","Cardboard doesn''t fold very easily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precise','adj.精确的；明确的；严格的','/pɹɪˈsaɪs/','/pɹɪˈsaɪs/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quick','n.核心；伤口的嫩肉adj.快的；迅速的，敏捷的；灵敏的adv.迅速地，快','/kwɪk/','/kwɪk/','noun',["He''s a quick runner.","That was a quick meal.","You have to be very quick to be able to compete in ad-lib theatrics."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conference','n.会议；讨论；协商；联盟；（正式）讨论会；[工会、工党用语]（每年的）大会vi.举行或参加（系列）会议','/ˈkɒn.fə.ɹəns/','/ˈkɒn.fə.ɹəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instead','adv.代替；反而；相反','/ɪnˈstɛd/','/ɪnˈstɛd/','adverb',["I was going to go shopping, but I went dancing instead."]);
