INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absolute','adj.绝对的；完全的；专制的n.绝对；绝对事物','/ˈæb.səˌljuːt/','/ˈæb.səˌlut/','noun',["moral absolutes","1658, Samuel Hoard, God''s Love to Mankind, Manifested, by disprooving his absolute decree for their damnation","absolute purity, absolute liberty"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('example','n.例子；榜样vt.作为…的例子；为…做出榜样vi.举例','/əɡˈzæmpl̩/','/əɡˈzæmpl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bill','n.[法]法案；广告；账单；[金融]票据；钞票；清单v.宣布；开账单；用海报宣传','/bɪl/','/bɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('since','conj.因为；由于；既然；自…以来；自…以后prep.自…以来；自…以后adv.后来','/sɪns/','/sɪns/','adverb',["A short/long time since","I have loved you since I first met you.","Since you didn''t call, we left without you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('almost','adv.差不多，几乎','/ɔːl.ˈməʊst/','/ˈɑl.moʊst/','noun',["In all the submissions, they found four papers that were clearly worth publishing and another dozen almosts.","Almost all people went there. - Not all but very close to it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marry','v.嫁；娶；与……结婚n.(Marry)人名；(阿拉伯)马雷；(法)马里','/ˈmæɹɪ/','/ˈmeɹi/','verb',["Neither of her daughters showed any desire to marry.","His daughter was married some five years ago to a tailor''s apprentice.","He was eager to marry his daughter to a nobleman."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adore','v.崇拜；爱慕；喜爱；极喜欢n.(Adore)人名；(法)阿多尔','/əˈdɔː/','/əˈdɔɹ/','verb',["It is obvious to everyone that Gerry adores Heather."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('starvation','n.饿死；挨饿；绝食','/stɑːˈveɪʃən/','/stɑːˈveɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handful','n.少数；一把；棘手事','/ˈhæn(d)fəl/','/ˈhæn(d)fəl/','noun',["Those twins are a real handful to look after."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('porridge','n.粥，糊；麦片粥vt.服刑','/ˈpɔɹɪdʒ/','/ˈpɔɹɪdʒ/','noun',["Eat your porridge while it''s hot!","Just do your porridge and keep your head down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jet','n.喷射，喷嘴；喷气式飞机；黑玉adj.墨黑的v.射出','/dʒɛt/','/dʒɛt/','noun',["Farmers may either dip or jet sheep with chemicals.","jet airplane"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volleyball','n.排球','/ˈvɒlibɔ(ː)l/','/ˈvɒlibɔ(ː)l/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('draft','n.汇票；草稿；选派；（尤指房间、烟囱、炉子等供暖系统中的）（小股）气流v.起草；制定；征募adj.初步画出或（写出）的；（设计、草图、提纲或版本）正在起草中的，草拟的；以草稿形式的；草图的','/dɹæft/','/dɹæft/','noun',["She took a deep draft from the bottle of water.","His first drafts were better than most authors'' final products.","He left the country to avoid the draft."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('festival','n.节日；庆祝，纪念活动；欢乐adj.节日的，喜庆的；快乐的','/ˈfɛstəvəl/','/ˈfɛstəvəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alarm','n.闹钟；警报，警告器；惊慌v.警告；使惊恐','/əˈlɑːm/','/əˈlɑɹm/','noun',["The clock radio is a friendlier version of the cold alarm by the bedside.","You should set the alarm on your watch to go off at seven o''clock."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sharp','adj.急剧的；锋利的；强烈的；敏捷的；刺耳的adv.急剧地；锐利地；突然地n.尖头；骗子；内行vt.磨快；把音调升高vi.打扮；升音演奏','/ʃɑːp/','/ʃɑɹp/','noun',["The pitch pipe sounded out a perfect F♯ (F sharp).","The piece was difficult to read after it had been transposed, since in the new key many notes were sharps.","Beethoven''s \"Moonlight Sonata\" is written in C♯ minor (C sharp minor.)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regular','adj.定期的；有规律的；合格的；整齐的；普通的n.常客；正式队员；中坚分子adv.定期地；经常地','/ˈɹɛɡjʊlə/','/ˈɹɛɡjəlɚ/','noun',["Bartenders usually know their regulars by name.","This gentleman was one of the architect''s regulars.","regular clergy, in distinction from the secular clergy"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('application','n.应用；申请；应用程序；敷用','/aplɪˈkeɪʃ(ə)n/','/ˌæpləˈkeɪʃən/','noun',["The application of this cream should reduce the swelling.","I make the remark, and leave you to make the application.","This iPhone application can connect to most social networks."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('republic','n.共和国；共和政体','[ɹɪˈpʌblɪk]','[ɹɪˈpʌblɪk]','noun',["The United States is a republic; the United Kingdom of Great Britain and Northern Ireland is a constitutional monarchy.","The Republic of Udmurtia is west of the Permian Oblast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rubbish','n.垃圾，废物；废话adj.毫无价值的','/ˈɹʌbɪʃ/','/ˈɹə-/','noun',["The rubbish is collected every Thursday in Gloucester, but on Wednesdays in Cheltenham.","Much of what they sell is rubbish.","Everything the teacher said during that lesson was rubbish. How can she possibly think that a bass viol and a cello are the same thing?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heavy','adj.沉重的；繁重的，巨大的；拥挤的；阴沉的n.重物；严肃角色adv.大量地；笨重地','/ˈhe.vi/','/ˈhɛ.vi/','noun',["With his wrinkled, uneven face, the actor always seemed to play the heavy in films.","A fight started outside the bar but the heavies came out and stopped it.","The union was well known for the methods it used to heavy many businesses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drown','v.淹没；把…淹死n.(Drown)人名；(英)德朗','/dɹaʊn/','/dɹaʊn/','verb',["The answers intelligence services seek are often drowned in the flood of information they can now gather."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quality','n.质量，[统计]品质；特性；才能adj.优质的；高品质的；<英俚>棒极了','/ˈkwɒlɪti/','/ˈkwɑləti/','noun',["Quality of life is usually determined by health, education, and income.","One of the qualities of pure iron is that it does not rust easily.","A peasant is not allowed to fall in love with a lady of quality."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catalogue','n.目录；（美）大学情况一览v.把…编入目录','/ˈkætəlɑɡ/','/ˈkætəlɔɡ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cube','n.立方；立方体；骰子v.使成立方形；使自乘二次；量…的体积','/kjuːb/','/kjub/','noun',["a stock cube","the cube of 2 is 8","Three cubed can be written as 33, and equals twenty-seven."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrinkle','n.皱纹v.起皱','/ˈɹɪŋkl̩/','/ˈɹɪŋkl̩/','noun',["Spending time out in the sun may cause you to develop wrinkles sooner.","Three months later, we''re still discovering new wrinkles.","Be careful not to wrinkle your dress before we arrive."]);
