INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('white','adj.白色的；白种的；纯洁的n.白色；洁白；白种人','/waɪt/','/waɪt/','noun',["Write in black ink on white paper.","white drinking fountain","white birch"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pencil','n.铅笔；笔状物v.用铅笔写；用眉笔涂','/ˈpɛnsɪl/','/ˈpɛnsəl/','noun',["I penciled (BrE: pencilled) a brief reminder in my notebook."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weigh','v.权衡；考虑；称…重量n.权衡；称重量','/weɪ/','/weɪ/','verb',["He weighed out two kilos of oranges for a client.","You have been weighed in the balance and found wanting.","I weigh ten and a half stone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abuse','n.滥用；虐待；辱骂；弊端；恶习，陋习v.滥用；虐待；辱骂','/əˈbjuːs/','/əˈbjus/','noun',["All abuse, whether physical, verbal, psychological or sexual, is bad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tiger','n.老虎；凶暴的人','/ˈtaɪɡə/','/ˈtaɪɡɚ/','noun',["three cheers and a tiger"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('TRUE','adj.真实的；正确的adv.真实地；准确地n.真实；准确v.装准','/tɹuː/','/tɹu/','noun',["He trued the spokes of the bicycle wheel.","We spent all night truing up the report.","This is a true story."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eighty','n.八十；八十岁；八十年代adj.八十的，八十个的；八十岁的num.八十','[ˈ(ʔ)eɪ̯ɾi]','[ˈ(ʔ)eɪ̯ɾi]','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sickness','n.疾病；呕吐；弊病','/ˈsɪknɪs/','/ˈsɪknɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spiritual','n.圣歌（尤指美国南部黑人的）adj.精神的，心灵的','/ˈspɪɹɪtjʊəl/','/ˈspɪɹɪtʃuəl/','noun',["He assigns supremacy to the pope in spirituals, and to the emperor in temporals. — Lowell.","Respect towards ancestors is an essential part of Thai spiritual practice.","a spiritual substance or being"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('I','pron.我n.碘元素；英语字母I','','','noun',["the position of an i-dot (the dot of an i)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blank','adj.空白的；空虚的；单调的n.空白；空虚；空白表格v.使…无效；使…模糊；封锁','/blæŋk/','/blæŋk/','noun',["the double blank","I blanked out my previous entry.","She blanked me for no reason."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('through','prep.通过；穿过；凭借adv.彻底；从头至尾adj.直达的；过境的；完结的','/θɹuː/','/θɹu/','noun',["Interstate highways form a nationwide system of through roads.","They were through with laying the subroof by noon.","After being implicated in the scandal, he was through as an executive in financial services."]);
