INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vote','n.投票，选举；选票；得票数v.提议，使投票；投票决定；公认','/vəʊt/','/voʊt/','noun',["One occasion indicative votes were used was in 2003 when MPs were presented with seven different options on how to reform the House of Lords.","The Supreme Court upheld the principle of one person, one vote.","Did you vote last month?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ruin','n.废墟；毁坏；灭亡v.毁灭；使破产','/ˈɹuː.ɪn/','/ˈɹuː.ɪn/','noun',["The monastery has fallen into ruin.","Gambling has been the ruin of many.","the ruin of a ship or an army;  the ruin of a constitution or a government;  the ruin of health or hopes"]);
