INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airport','n.机场；航空站','/ˈɛə.pɔːt/','/ˈɛɹ.pɔɹt/','noun',["Because of this, and contrary to popular belief, British airports primarily act as giant wealth extractors, transporting our richest citizens out of the country as often as possible to take their money overseas. ― The Independent, Heathrow expansion to mainly benefit wealthy frequent fliers, research finds, 23 june 2018."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flee','v.逃走；消失，消散','/fliː/','/fliː/','verb',["The prisoner tried to flee, but was caught by the guards.","Many people fled the country as war loomed.","Ethereal products flee once freely exposed to air."]);
