INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fight','v.打架；与…打仗，与…斗争；反对…提案n.打架；战斗，斗志','/faɪt/','[fʌɪt]','verb',["A wounded animal will fight like a maniac, relentless, savage and murderous.","The two boxers have been fighting for more than half an hour.","He fought for the Democrats in the last election."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('piece','n.块；件；篇；硬币v.修补；接合；凑合','/piːs/','/piːs/','noun',["I’d like another piece of pie.","a piece of machinery","a sixpenny piece"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breath','n.呼吸，气息；一口气，（呼吸的）一次；瞬间，瞬息；微风；迹象；无声音，气音','/bɹɛθ/','/bɹɛθ/','noun',["I could hear the breath of the runner behind me.","I took a deep breath and started the test.","I could feel the runner''s breath on my shoulder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ownership','n.所有权；物主身份','','','noun',["The successful candidate will take ownership of all internal design projects."]);
