INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fluent','adj.流畅的，流利的；液态的；畅流的','/ˈfluːənt/','/ˈfluənt/','noun',["fluent handwriting","She''s fluent in French."]);
