INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Indian','adj.印度的；印第安人的；印第安语的n.印度人；印第安人；印第安语','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bad','adj.坏的；严重的；劣质的n.坏事；坏人adv.很，非常；坏地；邪恶地','/bæd/','/beəd/','noun',["Abducting children is bad for mothers.","Do you think it is a bad idea to confront him directly?","It is bad manners to talk with your mouth full."]);
