INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doll','n.洋娃娃；玩偶；无头脑的美丽女人v.把…打扮得花枝招展','/dɒl/','/dɑl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yellow','adj.黄色的；黄皮肤的n.黄色；黄种人；黄色颜料v.使变黄或发黄','/ˈjɛl.əʊ/','/ˈjɛl.oʊ/','noun',["2012 March 2, Andrew Grice, \"Yellow rebels take on Clegg over NHS ''betrayal''\", The Independent","the black-yellow coalition"]);
