INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('favourite','adj.特别受喜爱的n.特别喜爱的人（或物）','/ˈfeɪv.ɹɪt/','/ˈfeɪv.ɹɪt/','noun',["The teacher''s favourite always went first.","She''s the favourite, she''ll probably be elected.","This is my second favourite occupation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delicious','adj.美味的；可口的','/dɪˈlɪʃəs/','/diˈlɪʃəs/','adjective',["The irony is delicious!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stage','n.阶段；舞台；戏剧；驿站v.举行；上演；筹划','/steɪd͡ʒ/','/steɪd͡ʒ/','noun',["Completion of an identifiable stage of maintenance such as removing an aircraft engine for repair or storage.","The band returned to the stage to play an encore.","The stage pulled into town carrying the payroll for the mill and three ladies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('academic','adj.学术的；理论的；学院的n.大学生，大学教师；学者','/ˌækəˈdɛmɪk/','/ˌækəˈdɛmɪk/','noun',["the academic sect or philosophy","I have always had an academic interest in hacking.","I''m more academic than athletic — I get lower marks in phys. ed. than in anything else."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rainbow','n.彩虹；五彩缤纷的排列；幻想adj.五彩缤纷的；彩虹状的vt.使呈彩虹状；如彩虹般装饰vi.呈彩虹状','/ˈɹeɪnbəʊ/','/ˈɹeɪmboʊ/','noun',["a rainbow of possibilities","Many electoral promises are rainbows, vanishing soon after poll day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interview','n.接见，采访；面试，面谈v.采访；接见；对…进行面谈；对某人进行面试','/ˈɪntəvjuː/','/ˈɪntɚvjuː/','noun',["The reporter gave the witness an interview.","It was a dreadful interview; I have no hope of getting the job.","He interviewed the witness."]);
