INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deed','n.行动；功绩；证书；[法]契据vt.立契转让','/diːd/','/diːd/','noun',["I have fulfilled my promise in word and in deed.","I inherited the deed to the house.","He deeded over the mineral rights to some fellas from Denver."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pain','n.疼痛；努力v.使…痛苦；使…烦恼','/peɪn/','/peɪn/','noun',["I had to stop running when I started getting pains in my feet.","In the final analysis, pain is a fact of life.","Your mother is a right pain."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fox','v.欺骗；使变酸n.狐狸；狡猾的人','/fɒks/','/fɑks/','noun',["The quick brown fox jumps over the lazy dog.","This crossword puzzle has completely foxed me.","The pages of the book show distinct foxing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('penny','n.（美）分；便士','/pəni/','/pəni/','noun',["to turn an honest penny","Zach and Ben had only been at college for a week when their door was pennied by the girls down the hall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('around','adv.大约；到处；在附近prep.四处；在…周围','/əˈɹaʊnd/','/əˈɹaʊnd/','adjective',["Is Clare around today?","\"How is old Bob? I heard that his health is failing.\"  \"Oh, he''s still around. He''s feeling better now.\"","High above, vultures circled around."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grandma','n.奶奶；外婆','/ˈɡɹænmɑː/','/ˈɡɹænmɑː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('read','v.阅读；读懂，理解n.阅读；读物adj.有学问的','/ɹiːd/','/ɹid/','noun',["His thrillers are always a gripping read.","What''s your read of the current political situation?","Have you read this book?"]);
