INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wine','n.酒，葡萄酒；紫红色v.喝酒','/waɪn/','/waɪn/','noun',["She ordered some wine for the meal.","I''d like three beers and two wines, please."]);
