INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plan','n.计划；平面图v.计划；设计；打算','/plæn/','/plæn/','noun',["The plans for many important buildings were once publicly available.","He didn''t really have a plan; he had a goal and a habit of control.","Seen in plan, the building had numerous passageways not apparent to visitors."]);
