INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spend','v.度过，消磨（时光）；花费；浪费；用尽n.预算','/spɛnd/','/spɛnd/','noun',["I’m sorry, boss, but the advertising spend exceeded the budget again this month.","He spends far more on gambling than he does on living proper.","to spend an estate in gambling"]);
