INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('operate','v.运转；动手术；起作用','/ˈɒpəɹeɪt/','/ˈɑpəɹeɪt/','verb',["to operate a machine"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affect','v.影响；感染；感动；假装n.情感；引起感情的因素','/əˈfɛkt/','/əˈfɛkt/','verb',["The experience affected me deeply.","He was deeply affected by the tragic ending of the play.","Hepatitis affects the liver."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bike','n.自行车；脚踏车v.骑自行车（或摩托车）','[bɐɪk]','[bɐɪk]','noun',["I biked so much yesterday that I''m very sore today.","It was such a nice day I decided to bike to the store, though it''s far enough I usually take my car."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacred','adj.神的；神圣的；宗教的；庄严的','/ˈseɪkɹɪd/','/ˈseɪkɹɪd/','adjective',["a sacred day"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('means','n.手段；方法；财产v.意思是；打算（mean的第三人称单数）[复数means]','/miːnz/','/miːnz/','verb',["Does she really mean what she said to him last night?","One faltering step means certain death.","Formality and titles mean nothing in their circle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tire','v.疲劳；厌倦n.轮胎；头饰','/ˈtʌɪ̯ɚ/','/ˈtʌɪ̯ɚ/','verb',["I tire of this book."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marble','n.大理石；大理石制品；弹珠adj.大理石的；冷酷无情的','/ˈmɑːbəl/','/ˈmɑɹbəl/','noun',["The Elgin Marbles were originally part of the temple of the Parthenon.","a marble mantel","a marble heart"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ferry','n.渡船；摆渡；渡口v.（乘渡船）渡过；用渡船运送；空运','/ˈfɛɹɪ/','/ˈfɛɹi/','noun',["Trucks plowed through the water to ferry flood victims to safety.","Being a good waiter takes more than the ability to ferry plates of food around a restaurant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('break','v.打破；折断；弄坏；削弱n.破裂；间断；（持续一段时间的状况的）改变；间歇','/bɹeɪk/','/bɹeɪk/','noun',["The femur has a clean break and so should heal easily.","He waited minutes for a break in the traffic to cross the highway.","Let’s take a five-minute break."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('natural','adj.自然的；物质的；天生的；不做作的n.自然的事情；白痴；本位音','/ˈnætʃəɹəl/','/-ɚəl/','noun',["He''s a natural on the saxophone.","The species will be under threat if its natural habitat is destroyed.","In the natural world the fit tend to live on while the weak perish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('letter','n.信；字母，文字；证书；文学，学问；字面意义v.写字母于','/ˈlɛtə(ɹ)/','/-ɾɚ/','noun',["There are twenty-six letters in the English alphabet.","I wrote a letter to my sister about my life.","Benjamin Franklin was multiskilled – a scientist, politician and a man of letters."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extreme','adj.极端的；极度的；偏激的；尽头的n.极端；末端；最大程度；极端的事物','/ɛkˈstɹiːm/','/ɪkˈstɹim/','noun',["extremes of temperature","Some people go to extremes for attention on social media.","At the extreme edges, the coating is very thin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disappointment','n.失望；沮丧','/dɪsəˈpɔɪntmənt/','','noun',["Our trip to California was a disappointment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kitchen','n.厨房；炊具；炊事人员','/ˈkɪt͡ʃən/','/ˈkɪt͡ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consideration','n.考虑；原因；关心；报酬','/kənˌsɪdəˈɹeɪʃən/','/kənˌsɪdəˈɹeɪʃən/','noun',["After much consideration, I have decided to stay.","Will you noisy children show some consideration and stop your infernal screaming? I''m trying to study!","Sure I''ll move my car, but only for a consideration."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merchant','n.商人，批发商；店主adj.商业的，商人的','/ˈmɜːtʃənt/','/ˈmɝtʃənt/','noun',["a merchanting service"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jewelry','n.珠宝；珠宝类','','','noun',["She had more jewellery ornamented about her than any three ladies needed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('status','n.地位；状态；情形；重要身份','/ˈsteɪt.əs/','/ˈsteɪt.əs/','noun',["Superstition is highly correlated with economic status.","New York is known for its status as a financial center.","I''m just about to update my status to \"busy\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homework','n.家庭作业，课外作业','/ˈhəʊmˌwɜːk/','/ˈhəʊmˌwɜːk/','noun',["You must do your homework before you can watch television.","The speaker had certainly done his homework before delivering the lecture."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('autumn','n.秋天；成熟期；渐衰期，凋落期adj.秋天的，秋季的','/ˈɔːtəm/','/ˈɔtəm/','noun',["autumn leaves"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forever','adv.永远；不断地；常常','/fəˈɹɛvə(ɹ)/','/fəˈɹɛvɚ/','noun',["I haven''t seen him in forever!","Sure, I''d be happy to meet with you on the 12th of forever.","I shall love you forever."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('selfish','adj.自私的；利己主义的','/ˈsɛlfɪʃ/','/ˈsɛlfɪʃ/','adjective',[]);
