INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('before','prep.在…之前，先于adv.以前；在前conj.在…以前；在…之前','/bɪˈfɔː/','/biˈfɔɹ/','adverb',["I''ve never done this before.","I want this done before Monday.","He stood before me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('itself','pron.它自己；它本身','/ɪtˈsɛlf/','/ɪtˈsɛlf/','pronoun',["The door closed by itself","The door itself is quite heavy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('role','n.角色；任务','/ɹəʊl/','/ɹəʊl/','noun',["Her dream was to get a role in a Hollywood movie, no matter how small.","The role of women has changed significantly in the last century.","Local volunteers played an important role in cleaning the beach after the oil spill."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('family','n.家庭；亲属；家族；子女；[生]科；语族；[化]族adj.家庭的；家族的；适合于全家的','/ˈfæm(ɪ)li/','/ˈfæm(ə)li/','noun',["Our family lives in town.","1915, William T. Groves, A History and Genealogy of the Groves Family in America","Our company is one big happy family."]);
