INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worm','n.虫，蠕虫；蜗杆；螺纹；小人物v.使蠕动；给除虫；使缓慢前进','/wɜːm/','/wɝm/','noun',["Don''t try to run away, you little worm!","We wormed our way through the underbrush.","He wormed his way into the organization"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shopkeeper','n.店主，老板','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wedding','n.婚礼，婚宴；结婚；结合v.与…结婚（wed的ing形式）','/ˈwɛdɪŋ/','/ˈwɛdɪŋ/','verb',["The priest wed the couple.","She wed her first love.","I''m not wedded to this proposal; suggest an alternative."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classical','adj.古典的；经典的；传统的；第一流的n.古典音乐','/ˈklæsɪkl̩/','/ˈklæsɪkl̩/','noun',["classical dance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surplus','n.剩余；[贸易]顺差；盈余；过剩adj.剩余的；过剩的','/ˈsɜːpləs/','/ˈsɜːpləs/','noun',["It is surplus to our needs"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steep','adj.陡峭的；不合理的；夸大的；急剧升降的v.泡；浸；使…充满n.峭壁；浸渍','/stiːp/','/stiːp/','noun',["a steep hill or mountain; a steep roof; a steep ascent; a steep barometric gradient","Twenty quid for a shave? That''s a bit steep.","The steep rake of the windshield enhances the fast lines of the exterior. http//legacy.sandiegouniontribune.com/uniontrib/20070303/news_lz1dd3maynard.html"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('woollen','adj.羊毛制的n.毛织品','','','noun',["Put all the woolens in this basket.","a woolen draper"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('of','prep.关于；属于；…的；由…组成的','/ɔv/','/ʌv/','preposition',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fibre','n.纤维；纤维制品','/ˈfaɪ.bə(ɹ)/','/ˈfaɪ.bə(ɹ)/','noun',["The microscope showed several different fibres stuck to the sole of the shoe.","The cloth was made from strange, somewhat rough fibre.","Fresh vegetables are a good source of fibre."]);
