INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dog','n.狗；丑女人；卑鄙的人；(俚)朋友v.跟踪；尾随','/dɒɡ/','/dɔɡ/','noun',["The dog barked all night long.","She’s a real dog.","He''s a silly dog."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensitive','adj.敏感的；感觉的；[仪]灵敏的；感光的；易受伤害的；易受影响的n.敏感的人；有灵异能力的人','/ˈsɛnsɪtɪv/','/ˈsɛnsɪtɪv/','noun',["Max is very sensitive; he cried today because of the bad news.","Religion is often a sensitive topic of discussion and should be avoided when dealing with foreign business associates.","These are highly sensitive documents."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('junior','adj.年少的；后进的；下级的n.年少者，晚辈；地位较低者；大学三年级学生','/ˈdʒuːnɪə/','/ˈdʒuːnɪə/','noun',["four years his junior"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('translator','n.译者；翻译器','/ˈtɹanzleɪtə/','/ˈtɹanzleɪtə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adventure','n.冒险；冒险精神；投机活动v.冒险；大胆说出','/ædˈvɛnt͡ʃɚ/','/ædˈvɛnt͡ʃɚ/','noun',["A life full of adventures.","his sense of adventure"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('qualification','n.资格；条件；限制；赋予资格','/ˌkwɒlɪfɪˈkeɪʃən/','/ˌkwɒlɪfɪˈkeɪʃən/','noun',["Qualification for this organization is extraordinarily difficult.","What are your qualifications for this job?","I accept your offer, but with the following qualification."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('planet','n.行星','/ˈplænət/','/ˈplænɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ugly','adj.丑陋的；邪恶的；令人厌恶的','/ˈʌɡli/','/ˈʌɡli/','noun',["He played an ugly trick on us.","an ugly temper; to feel ugly","With all this competition, expect things to get ugly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('history','n.历史，历史学；历史记录；来历','/ˈhɪst(ə)ɹi/','/ˈhɪst(ə)ɹi/','noun',["History repeats itself if we don’t learn from its mistakes.","He teaches history at the university.   History will not look kindly on these tyrants.   He dreams of an invention that will make history.","What is your medical history?   The family''s history includes events best forgotten."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('house','n.住宅；家庭；机构；议会；某种用途的建筑物v.覆盖；给…房子住；把…储藏在房内','/haʊs/','/hʌʊs/','noun',["This is my house and my family''s ancestral home.","On arriving at the zoo, we immediately headed for the monkey house.","After her swan-song, there wasn''t a dry eye in the house."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surface','n.表面；表层；外观adj.表面的，肤浅的v.浮出水面','/ˈsɜːfɪs/','/ˈsɝːfəs/','noun',["On the surface, the spy looked like a typical businessman."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devote','v.致力于；奉献','/dɪˈvəʊt/','/dɪˈvoʊt/','verb',["I devoted this afternoon to repainting my study, and nothing will get in my way.","The city was devoted to the flames."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aid','n.援助；帮助；助手；帮助者v.援助；帮助；有助于','/eɪd/','','noun',["He came to my aid when I was foundering.","Slimming aids include dietary supplements and appetite suppressants.","The incompetent general''s brilliant aid often made priceless suggestions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('component','adj.组成的，构成的n.成分；组件；[电子]元件','/kʌmˈpoʊnənt/','/kʌmˈpoʊnənt/','noun',["A CPU is a component of a computer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generation','n.一代；产生；一代人；生殖','/ˌd͡ʒɛnəˈɹeɪʃən/','/ˌd͡ʒɛnəˈɹeɪʃən/','noun',["This is the book of the generations of Adam - Genesis 5:1","the generation of a line or curve","Generation X grew up in the eighties, whereas the generation known as the millennials grew up in the nineties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edge','n.边缘；优势；刀刃；锋利v.使锐利；将…开刃；给…加上边','/ɛdʒ/','/ɛdʒ/','noun',["I have the edge on him.","He is standing on the edge of a precipice.","in the edge of evening"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organ','n.[生物]器官；机构；风琴；管风琴；嗓音','/ˈɔː.ɡən/','/ˈɔɹ.ɡən/','noun',["bodily organs"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('federal','adj.联邦的；同盟的；联邦政府的；联邦制的adv.联邦政府地n.(Federal)人名；(英)费德勒尔','/ˈfɛdəɹəl/','/ˈfɛdəɹəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alive','adj.活着的；活泼的；有生气的','','/əˈlaɪv/','adjective',["As long as the plant is alive, he will continue to water it.","to keep the affections alive","Although quite dull during the day, the main street comes alive at night, with many bars and clubs opening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('top','n.顶部，顶端；上部；首席；陀螺v.高出，超越；结束；达到顶点adj.最高的，顶上的；头等的','/tɒp/','/tɑp/','noun',["His kite got caught at the top of the tree.","The boy was amazed at how long the top would spin.","I prefer being a top, and my boyfriend prefers being a bottom."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minority','n.少数民族；少数派；未成年adj.少数的；属于少数派的','/maɪˈnɒɹ.ɪ.ti/','/maɪˈnɑɹ.ɪ.ti/','noun',["Most people agreed, but a sizable minority were upset by the decision.","The company claims it has hired several minorities since the complaint was lodged.","They hold a minority interest in the company."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('have','v.有；让；拿；从事；允许aux.已经n.(Have)人名；(芬)哈韦；(德)哈弗','','','noun',["I have a house and a car.","Do you have the key? (not necessarily one''s own key)","I have a really mean boss."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notice','n.通知，布告；注意；公告v.通知；注意到；留心','/ˈnəʊtɪs/','/ˈnoʊtɪs/','noun',["He took no notice of the changes, and went on as though nothing had happened.","I always read the death notices in the paper.","The sidewalk adjacent to the damaged bridge stonework shall be closed until further notice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tower','n.塔；高楼；堡垒v.高耸；超越','/ˈtaʊ.ə(ɹ)/','/ˈtaʊɚ/','noun',[]);
