INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enthusiastic','adj.热情的；热心的；狂热的','/ɪnˌθjuːzɪˈæstɪk/','/ɪnˌθjuːzɪˈæstɪk/','adjective',["an enthusiastic lover of art"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loose','adj.宽松的；散漫的；不牢固的；不精确的v.释放；开船；放枪adv.松散地n.放纵；放任；发射','/luːs/','/luːs/','noun',["This wheelbarrow has a loose wheel.","''You can buy apples in a pack, but they are cheaper loose.","The dog is loose again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adequate','adj.充足的；适当的；胜任的','','','verb',["an adequate definition"]);
