INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blood','n.血，血液；血统v.从…抽血；使先取得经验','/blʌd/','/blʌd/','noun',["The cultists gathered around a chalice of blood.","They came looking for blood."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('birthplace','n.出生地','/ˈbɝθˌpleɪs/','/ˈbɝθˌpleɪs/','noun',["Portsmouth was Charles Dickens’ birthplace.","Coney Island was the birthplace of the hot dog."]);
