INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('problem','n.难题；引起麻烦的人adj.成问题的；难处理的','/ˈpɹɒbləm/','/ˈpɹɑbləm/','noun',["She''s leaving because she faced numerous problems to do with racism.","You got a problem with that?"]);
