INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleasure','n.快乐；希望；娱乐；令人高兴的事vt.使高兴；使满意vi.高兴；寻欢作乐','/ˈplɛʒə/','/ˈplɛʒɚ/','noun',["He remembered with pleasure his home and family.","Having a good night''s sleep is one of life''s little pleasures.","What is your pleasure: coffee or tea?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appointment','n.任命；约定；任命的职位','/əˈpɔɪnt.mɛnt/','/əˈpɔɪnt.mɛnt/','noun',["His appointment was deemed suitable","the appointment of treasurer","I''m leaving work early because I have a doctor''s appointment."]);
