INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('redirect','v.使改方向；重新寄送adj.再直接的n.再直接询问','','','noun',["redirect output to /dev/null","You will be redirected shortly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('niece','n.外甥女，侄女','/niːs/','/nis/','noun',["My niece just celebrated her 15th birthday."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coal','v.上煤；加煤n.煤；煤块；木炭','/kɔʊl/','/koʊl/','noun',["Put some coal on the fire.","Put some coals on the fire.","Just as the camp-fire died down to just coals, with no flames to burn the marshmallows, someone dumped a whole load of wood on, so I gave up and went to bed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mainland','n.大陆；本土adj.大陆的；本土的','/ˈmeɪ̪nlənd/','/ˈmeɪ̪nlənd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mother','n.母亲；大娘；女修道院院长v.生下；养育；像母亲般关怀或照管adj.母亲的；出生地的','/ˈmʌðə(ɹ)/','/ˈmʌðɚ/','noun',["He had something of his mother in him.","Nutrients and oxygen obtained by the mother are conveyed to the fetus.","The lioness was a mother of four cubs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chaos','n.混沌，混乱','/ˈkeɪ.ɒs/','/ˈkeɪ.ɑs/','noun',["After the earthquake, the local hospital was in chaos"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polite','adj.有礼貌的，客气的；文雅的；上流的；优雅的','/pəˈlaɪt/','/pəˈlaɪt/','verb',["It''s not polite to use a mobile phone in a restaurant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entertainment','n.娱乐；消遣；款待','/ˈɛn.tɚˈteɪn.mənt/','/ˈɛn.tɚˈteɪn.mənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personnel','n.人事部门；全体人员adj.人员的；有关人事的','/-el/','/pɝ.səˈnɛl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circle','n.循环，周期；圆；圈子；圆形物v.盘旋，旋转；环行','/ˈsɜɹkəl/','[ˈsɝ.kəɫ]','noun',["The set of all points (x, y) such that (x − 1)2 + y2 = r2 is a circle of radius r around the point (1, 0).","Children, please join hands and form a circle.","circle of friends"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Chinese','n.中文，汉语；中国人adj.中国的，中国人的；中国话的','','','',[]);
