INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('save','v.节省；保存；储蓄；解救prep.除之外n.救援','/seɪv/','/seɪv/','noun',["The goaltender made a great save.","Jones retired seven to earn the save.","The giant wrestler continued to beat down his smaller opponent, until several wrestlers ran in for the save."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collar','n.衣领；颈圈v.抓住；给…上领子；给…套上颈圈','/ˈkɒl.ə/','/ˈkɑ.lɚ/','noun',["a collar of brawn","A nylon collar kept the bolt from damaging the surface underneath.","Collar and leash aggressive dogs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dot','n.点，圆点；嫁妆v.打上点','/dɒt/','/dɑt/','noun',["a dot of colour","a dot of a child","His jacket was dotted with splashes of paint."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coach','n.教练；旅客车厢；长途公车；四轮大马车v.训练；指导','/kəʊtʃ/','/koʊtʃ/','noun',["John flew coach to Vienna, but first-class back home.","She has coached many opera stars."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nuclear','adj.原子能的；[细胞]细胞核的；中心的；原子核的','/ˈnjuː.klɪə/','/ˈn(j)ukjəlɚ/','noun',["a nuclear reactor","a nuclear explosion","nuclear option, nuclear solution"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voice','n.声音；嗓音；发言权；愿望v.表达；吐露','/vɔɪs/','/vɔɪs/','noun',["His low voice allowed him to become a bass in the choir.","to cultivate the voice","The verbal system of Latin has two voices, active and passive."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('select','v.挑选；选拔adj.精选的；挑选出来的；极好的n.被挑选者；精萃','/sɪˈlɛkt/','/sɪˈlɛkt/','verb',["He looked over the menu, and selected the roast beef.","Only a select few were allowed into the premiere.","This is a select cut of beef."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thunder','n.雷；轰隆声；恐吓v.打雷；怒喝','/ˈθʌndə/','/ˈθʌndɚ/','noun',["Thunder is preceded by lightning.","Off in the distance, he heard the thunder of hoofbeats, signalling a stampede.","Shortly after I announced my pregnancy, he stole my thunder with his news of landing his dream job."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ancestor','n.始祖，祖先；被继承人','/ˈæn.sɛs.tə/','/ˈæn.sɛs.tɚ/','noun',["This fossil animal is regarded as the ancestor of the horse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tend','v.趋向，倾向；照料，照顾','/tɛnd/','/tɛnd/','verb',["It tends to snow here in winter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bowl','n.碗；木球；大酒杯v.玩保龄球；滑动；平稳快速移动','/bəʊɫ/','/boʊɫ/','noun',["You can’t have any more soup – you’ve had three bowls already.","This restaurant offers a number of different bowls.","Direct the cleaning fluid around the toilet bowl and under the rim."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pretend','v.假装，伪装，佯装adj.假装的','/pɹɪˈtɛnd/','/pɹɪˈtɛnd/','verb',["As children we used to go on \"spying\" missions around the neighbour''s house, but it was all pretend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('majority','n.多数；成年','/məˈd͡ʒɒɹɪti/','/məˈd͡ʒɑɹɪti/','noun',["The majority agreed that the new proposal was the best.","The winner with 53% had a 6% majority over the loser with 47%.","By the time I reached my majority, I had already been around the world twice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minute','n.分，分钟；片刻，一会儿；备忘录，笔记；会议记录v.将…记录下来adj.微小的，详细的[maɪˈnjuːt;US-ˈnuːt;maɪˋnut]','/ˈmɪnɪt/','/ˈmɪnɪt/','noun',["You have twenty minutes to complete the test.","Wait a minute, I’m not ready yet!","We need to be sure these maps are accurate to within one minute of arc."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weather','n.天气；气象；气候；处境v.经受住；使风化；侵蚀；使受风吹雨打adj.露天的；迎风的','/ˈwɛðə/','/ˈwɛðɚ/','noun',["Wooden garden furniture must be well oiled as it is continuously exposed to weather.","to weather a cape; to weather another ship","Joshua weathered a collision with a freighter near South Africa."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suggestion','n.建议；示意；微量，细微的迹象','/səˈd͡ʒɛstjən/','/səɡˈd͡ʒɛstʃən/','noun',["I have a small suggestion for fixing this: try lifting the left side up a bit.","Suggestion often works better than explicit demand.","He''s somehow picked up the suggestion that I like peanuts."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunrise','n.日出；黎明','/ˈsʌnɹaɪz/','/ˈsʌnɹaɪz/','noun',["I''ll meet you at the docks at sunrise.","Did you see the beautiful sunrise this morning?","It was the sunrise of her spirit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alike','adj.相似的；相同的adv.以同样的方式；类似于','/əˈlaɪk/','/əˈlaɪk/','adjective',["The twins were alike.","We are all alike concerned in religion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('district','n.区域；地方；行政区','/ˈdɪstɹɪkt/','/ˈdɪstɹɪkt/','noun',["the Soho district of London","the Lake District in Cumbria","South Oxfordshire District Council"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compulsory','adj.义务的；必修的；被强制的n.（花样滑冰、竞技体操等的）规定动作','/kəmˈpʌlsəri/','/kəmˈpʌlsəri/','noun',["The ten-dollar fee was compulsory.","Such compulsory measures are limited."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Tibet','n.西藏（中国一自治区）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lay','v.躺下；产卵；搁放；放置；铺放；涂，敷adj.世俗的；外行的；没有经验的n.位置；短诗；花纹方向；叙事诗；性伙伴','/leɪ/','/leɪ/','noun',["the lay of the land","Worm and parcel with the lay; turn and serve the other way.","What was I, just another lay you can toss aside as you go on to your next conquest?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stomach','n.胃；腹部；胃口v.忍受；吃下','/ˈstʌmək/','/ˈstʌmək/','noun',["a good stomach for roast beef","I have no stomach for a fight today.","I can''t stomach her cooking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('damage','n.损害；损毁；赔偿金v.损害；损毁','/ˈdæmɪdʒ/','/ˈdæmɪdʒ/','noun',["The storm did a lot of damage to the area.","\"What''s the damage?\" he asked the waiter.","Be careful not to damage any of the fragile items while unpacking them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cough','n.咳嗽，咳嗽声；咳嗽病v.咳出','/kɑf/','/kɔf/','noun',["Behind me, I heard a distinct, dry cough.","Sorry, I can''t come to work today – I''ve got a nasty cough.","He was – cough – indisposed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shut','v.关闭；停业；幽禁n.关闭adj.关闭的；围绕的','/ʃʌt/','/ʃʌt/','adjective',["a close alley; close quarters","Is your house close?","He is a close friend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anniversary','n.周年纪念日','/ˌænɪˈvɜːs(ə)ɹi/','/ˌænəˈvɝs(ə)ɹi/','noun',["Today is the fiftieth anniversary of the end of the war."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coat','n.外套v.覆盖…的表面','/kəʊt/','/koʊt/','noun',["When the dog shed its coat, it left hair all over the furniture and the carpet.","The frying pan was coated with a layer of non-stick material, making it easier to wash."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ham','n.火腿；业余无线电爱好者；蹩脚演员v.表演过火adj.过火的；做作的','/ˈhæm/','/ˈhæm/','noun',["a little piece of ham for the cat"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depth','n.[海洋]深度；深奥','/dɛpθ/','/dɛpθ/','noun',["Measure the depth of the water in this part of the bay.","The depth of her misery was apparent to everyone.","the depth of a sound"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somebody','n.大人物；重要人物pron.有人；某人','/ˈsʌmbədɪ/','/ˈsʌmbɑdi/','noun',["I''m tired of being a nobody – I want to be a somebody.","Somebody has to clean this mess up."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('requirement','n.要求；必要条件；必需品','/ɹɪˈkwʌɪəm(ə)nt/','/ɹɪˈkwʌɪəm(ə)nt/','noun',["There was a requirement of the government on citizens for paying taxes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guard','n.守卫；警戒；护卫队；防护装置v.警惕','/ɡɑːd/','/ɡɑɹd/','noun',["The prison guard unlocked the door of the cell.   After completing the repairs, he replaced the sump guard.","The president inspected the guard of honour.","The motorcycle mechanic removed the damaged chain guard."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superman','n.超人，能力非凡的','/ˈs(j)uːpəmæn/','/ˈs(j)uːpəmæn/','noun',["Nietzsche wrote of the coming of the superman.","He worked like a superman to single-handedly complete the project on time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artist','n.艺术家；美术家（尤指画家）；大师','/ˈɑːtɪst/','/ˈɑɹ.tɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prove','v.证明；检验；显示','/pɹuːv/','/pɹuːv/','verb',["I will prove that my method is more effective than yours.","It proved to be a cold day.","Have an exit strategy should your calculations prove incorrect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cry','v.叫喊；哭出；大声说n.叫喊；叫声；口号；呼叫','/kɹaɪ̯/','/kɹaɪ̯/','noun',["After we broke up, I retreated to my room for a good cry.","I heard a cry from afar.","a battle cry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lunch','n.午餐v.吃午餐；供给午餐','/lʌnt͡ʃ/','/lʌnt͡ʃ/','noun',["After the funeral there was a lunch for those who didn''t go to the cemetery.","I like to lunch in Italian restaurants."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fourth','adj.第四的，第四个的；四分之一的n.第四，月的第四日；四分之一num.第四','/fɔːθ/','/fɔɹθ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tractor','n.拖拉机；牵引机','/ˈtɹæktə/','/ˈtɹæktɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entire','adj.全部的，整个的；全体的n.(Entire)人名；(英)恩泰尔','/ənˈtaɪə/','/ənˈtaɪɚ/','noun',["We had the entire building to ourselves for the evening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bare','adj.空的；赤裸的，无遮蔽的v.露出，使赤裸n.(Bare)人名；(英)贝尔','/bɛə(ɹ)/','/bɛəɹ/','noun',["a bare majority","I do wonder why keeping my little breasts bare can be lewd even as none tells my brother anything for being bare-chested.","The cupboard was bare."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guess','v.猜测；认为；推测；猜中n.猜测；推测','/ɡɛs/','/ɡɛs/','verb',["He who guesses the riddle shall have the ring.","That album is quite hard to find, but I guess you could try ordering it online.","\"I guess I''ll go to bed.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outside','adj.外面的，外部的；外来的n.外部；外观adv.在外面，向外面；在室外prep.在…范围之外','','','noun',["He''s repainting the outside of his house.","Her outside was stern, but inside was a heart of gold.","Viewed from the outside, the building seemed unremarkable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absent','adj.缺席的；缺少的；心不在焉的；茫然的v.使缺席','/ˈæb.sn̩t/','/ˈæb.sn̩t/','noun',["The part was rudimental or absent.","Absent taxes modern governments cannot function."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('firewood','n.柴火；木柴','','','noun',["After many days of hard work, we finally had enough firewood for the winter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('our','pron.我们的','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Iceland','n.冰岛（欧洲岛名，在大西洋北部，近北极圈）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ecology','n.生态学；社会生态学','/ɛˈkɒlədʒi/','/ɛˈkɒlədʒi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('religion','n.宗教；宗教信仰','/ɹɪˈlɪdʒən/','/ɹɪˈlɪdʒən/','noun',["My brother tends to value religion, but my sister not as much.","Eckankar is a new religion but Zoroastrianism is an old religion.","The monk entered religion when he was 20 years of age."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('participate','v.参与，参加；分享','/pɑːˈtɪsɪpeɪt/','','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unusual','adj.不寻常的；与众不同的；不平常的','/ʌnˈjuːʒuəl/','/ʌnˈjuːʒuəl/','noun',["Every once in a while, though, Idol comes across an unusual talent who just blows everyone away."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gravity','n.重力，地心引力；严重性；庄严','/ˈɡɹævɪti/','/ˈɡɹævɪti/','noun',["I hope you appreciate the gravity of the situation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dust','n.灰尘；尘埃；尘土v.撒；拂去灰尘','/dʌst/','/dʌst/','noun',["to raise, or kick up, a dust","The cleaning lady needs a stool to dust the cupboard.","Dusting always makes me cough."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('science','n.科学；技术；学科；理科','/ˈsaɪəns/','/ˈsaɪəns/','noun',["Of course in my opinion Social Studies is more of a science than an art.","My favorite subjects at school are science, mathematics, and history."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('money','n.钱；货币；财富','/ˈmʌni/','/ˈmʌni/','noun',["Before colonial times cowry shells imported from Mauritius were used as money in Western Africa.","money supply;  money market","He married money."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ship','v.运送，乘船；以船运送n.船；舰；太空船','/ʃɪp/','/ʃɪp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precious','adj.宝贵的；珍贵的；矫揉造作的n.(Precious)人名；(英)普雷舍斯，普雷舍丝(女名)','/ˈpɹɛʃəs/','/ˈpɹɛʃəs/','noun',["The crown had many precious gemstones.   This building work needs site access, and tell the city council that I don''t care about a few lorry tyre ruts across their precious grass verge.","My precious daughter is to marry.","He spent hours painting the eyes of the portrait, which his fellow artists regarded as a bit precious."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('today','adv.今天；现今n.今天；现今','/təˈdeɪ/','/təˈdeɪ/','noun',["Today is the day we''ll fix this once and for all.","I want this done today.","In the 1500s, people had to do things by hand, but today we have electric can openers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overlook','v.忽略；俯瞰；远眺；检查；高耸于…之上n.忽视；眺望','/əʊvəˈlʊk/','/oʊvəɹˈlʊk/','noun',["Our hotel room overlooks the lake.","These errors were overlooked by the proofreaders.","I’m not willing to overlook such bad behaviour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hang','v.悬挂，垂下；装饰；绞死；使悬而未决n.悬挂；暂停，中止','[heɪŋ]','[heɪŋ]','noun',["This skirt has a nice hang.","He got the hang of it after only two demonstrations.","We sometimes get system hangs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ticket','n.票；入场券，标签；（美）候选人名单；证明书；交通罚款单v.加标签于；指派；对…开出交通违规罚单','/ˈtɪkɪt/','/ˈtɪkɪt/','noun',["Joe has joined the party''s ticket for the county elections.","I saw my first bike as my ticket to freedom.","to ticket goods in a retail store"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Mosquito','n.蚊子','/mɒsˈkiː.təʊ/','/məˈski.toʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repairs','n.修理；[会计]修理费；备件；修理工作（repair的复数形式）v.修理；恢复（repair的三单形式）；弥补；纠正','','','noun',["I took the car to the workshop for repair.","If you look closely you can see the repair in the paintwork.","The car was overall in poor repair before the accident. But after the workshop had it for three weeks it was returned in excellent repair. But the other vehicle was beyond repair."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dormitory','n.宿舍，学生宿舍adj.住宅区的','/ˈdɔɹmɪˌtɔɹi/','/ˈdɔɹmɪˌtɔɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('write','v.写，写字；写作，作曲；写信','/ɹaɪt/','/ɹaɪt/','noun',["How many writes per second can this hard disk handle?","The pupil wrote his name on the paper.","My uncle writes newspaper articles for The Herald."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seat','n.座位；所在地；职位v.使…坐下；可容纳…的；使就职','/siːt/','/siːt/','noun',["Be sure to seat the gasket properly before attaching the cover.","The waiter seated us and asked what we would like to drink.","Please seat the audience after the anthem and then introduce the first speaker."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wander','v.徘徊；漫步；迷路；离题n.(Wander)人名；(英)万德(女子教名)','/ˈwɒndə/','/ˈwɑndɚ/','noun',["to go for a wander in the park","baseline wander in ECG signals","to wander over the fields"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tentative','adj.试验性的，暂定的；踌躇的n.假设，试验','/ˈtɛntətɪv/','/ˈtɛntətɪv/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eighteen','n.十八，十八个adj.十八个的，十八的num.十八','/ˈeɪ.tiːn/','','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hold','v.持有；拥有；保存；拘留；约束或控制n.控制；保留','/həʊld/','/hoʊld/','noun',["Keep a firm hold on the handlebars.","Can I have a hold of the baby?","Senator X placed a hold on the bill, then went to the library and placed a hold on a book."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('habit','n.习惯，习性；嗜好v.使穿衣','/ˈhæbət/','/ˈhæbət/','noun',["It’s become a habit of mine to have a cup of coffee after dinner.","By force of habit, he dressed for work even though it was holiday.","It’s interesting how Catholic and Buddhist monks both wear habits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('future','n.未来；前途；期货；将来时adj.将来的，未来的','/ˈfjuːt͡ʃə/','/ˈfjuːt͡ʃɚ/','noun',["There is no future in dwelling on the past.","Future generations will either laugh or cry at our stupidity."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('independent','adj.独立的；单独的；无党派的；不受约束的n.独立自主者；无党派者','/ɪndɪˈpɛndənt/','/ɪndɪˈpɛndənt/','noun',["the independent candidate","an independent property","a man of an independent mind"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subject','n.主题；科目；[语]主语；国民adj.服从的；易患…的；受制于…的v.使…隶属；使屈从于…','/ˈsʌb.dʒɪkt/','/ˈsʌb.dʒɛkt/','adjective',["He''s subject to sneezing fits.","The local board sets local policy, subject to approval from the State Board."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('say','v.讲；说明；例如；声称；假设；指明n.(Say)人名；(土)萨伊；(法、老、柬)赛；(英)塞伊；(匈、罗)绍伊','/seɪ/','/seɪ/','noun',["Please say your name slowly and clearly.","Martha, will you say the Pledge of Allegiance?","He said he would be here tomorrow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('target','n.目标；靶子v.把……作为目标；规定……的指标；瞄准某物','/tɑːɡɪt/','/ˈtɑɹɡɪt/','noun',["Take careful aim at the target.","They have a target to finish the project by November.","He made a good target."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disease','n.病，[医]疾病；弊病vt.传染；使…有病','/dɪˈziːz/','/dɪˈziz/','noun',["The tomato plants had some kind of disease that left their leaves splotchy and fruit withered."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('death','n.死；死亡；死神；毁灭','/diːθ/','/diːθ/','noun',["The death of my grandmother saddened the whole family.","When death walked in, a chill spread through the room.","England scored a goal at the death to even the score at one all."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ago','adv.以前，以往adj.以前的；过去的n.(Ago)人名；(英、西、意、塞、瑞典)阿戈','/əˈɡəʊ/','/əˈɡoʊ/','adjective',["in days ago/in days agone","Woe the day- she is agone!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shore','v.支撑，使稳住；用支柱撑住n.海滨；支柱','/ʃɔː/','/ʃɔɹ/','noun',["lake shore;  bay shore;  gulf shore;  island shore;  mainland shore;  river shore;  estuary shore;  pond shore;  sandy shore;  rocky shore","The passengers signed up for shore tours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obey','v.服从，听从；按照……行动n.(Obey)人名；(英、法)奥贝','/əʊˈbeɪ/','/oʊˈbeɪ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thankful','adj.感谢的；欣慰的','/ˈθæŋkfəl/','/ˈθæŋkfəl/','adjective',["I''m thankful that you helped me out today. How can I ever repay you?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restaurant','n.餐馆；[经]饭店','/ˈɹɛs.t(ə).ɹ(ə)nt/','/ˈɹɛs.t(ə).ɹ(ə)nt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awesome','adj.令人敬畏的；使人畏惧的；可怕的；极好的','/ˈɔːsəm/','/ˈɔs.əm/','noun',["pure awesome; made of awesome","The tsunami was awesome in its destructive power.","Awesome, dude!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decorate','v.装饰；布置；授勋给','/ˈdɛkəɹeɪt/','/ˈdɛkəɹeɪt/','verb',["We decorated the Christmas tree with tinsel and baubles.","There''s some paint left over from when we decorated the guest bedroom.","People tend to decorate for the holidays or special events."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('judgement','n.意见；判断力；[法]审判；评价','/dʒʌdʒmənt/','/dʒʌdʒmənt/','noun',["a man of judgment"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congratulation','n.祝贺；贺辞','/kənˌɡɹætjʊˈleɪʃ(ə)n/','/kənˌɡɹætjʊˈleɪʃ(ə)n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appropriate','adj.适当的；恰当的；合适的v.占用，拨出','','','verb',["Let no man appropriate the use of a common benefit.","A spot of ground is appropriated for a garden.","The headmaster wondered what an appropriate measure would be to make the pupil behave better."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assessment','n.评定；估价','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supper','n.晚餐，晚饭；夜宵','/ˈsʌpə/','/ˈsʌpɚ/','noun',["a fish supper; a pizza supper"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bent','n.爱好，嗜好adj.弯曲的；决心的','/bɛnt/','/bɛnt/','verb',["Don’t bend your knees.","Look at the trees bending in the wind.","The road bends to the right"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('they','pron.他们；它们；她们','/ðeɪ/','/ðeɪ/','pronoun',["Dogs may bark if they want to be fed.","They requested a seat at Friday''s performance but didn''t say if they preferred the balcony or the floor.","Ha, you believe the moon is real? That''s just what they want you to think."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('move','n.移动；步骤；迁居；策略v.移动；搬家，迁移；离开','/muːv/','/muːv/','noun',["A slight move of the tiller, and the boat will go off course.","He made another move towards becoming a naturalized citizen.","She always gets spontaneous applause for that one move."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eagle','n.鹰；鹰状标饰','/ˈiːɡəl/','/ˈiːɡəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('common','adj.共同的；普通的；一般的；通常的n.普通；平民；公有地','/ˈkɒmən/','/ˈkɑmən/','noun',["The two competitors have the common aim of winning the championship.","It is common to find sharks off this coast.","It differs from the common blackbird in the size of its beak."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('customer','n.顾客；家伙','/ˈkʌstəmə/','/ˈkʌstəmə/','noun',["Every person who passes by is a potential customer.","a cool customer, a tough customer, an ugly customer"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cast','v.投，抛；计算；浇铸；投射（光、影、视线等）n.投掷，抛；铸件，[古生]铸型；演员阵容；脱落物','/kæst/','/kæst/','noun',["The area near the stream was covered with little bubbly worm casts.","He’s in the cast of Oliver.","The men got into position for the cast, two at the ladle, two with long rods, all with heavy clothing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('million','n.百万；无数adj.百万的；无数的num.百万','/ˈmɪljən/','/ˈmɪljən/','numeral',["I can think of millions of reasons not to go."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('custom','n.习惯，惯例；风俗；海关，关税；经常光顾；[总称]（经常性的）顾客adj.（衣服等）定做的，定制的','/ˈkʌstəm/','/ˈkʌstəm/','noun',["The Ancient Egyptian culture had many distinctive and interesting beliefs and customs.","My feet are very large, so I need custom shoes.","We can embroider a wide range of ready designs or a custom logo."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extra','adv.特别地，非常；另外n.临时演员；号外；额外的事物；上等产品adj.额外的，另外收费的；特大的','/ˈɛkstɹə/','/ˈɛkstɹə/','noun',["Extra, extra! Read all about it!","I don''t mind doing some extra work, as long as I get extra pay.","You unfollowed her for posting cat memes? You''re so extra!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ash','n.灰；灰烬','/æʃ/','/æʃ/','noun',["Ash from a fireplace can restore minerals to your garden''s soil.","The urn containing his ashes was eventually removed to a closet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evaluate','v.评价；估价；求…的值','/ɨˈvaljʊeɪt/','/ɪ̈ˈvaljəˌweɪt/','verb',["It will take several years to evaluate the material gathered in the survey.","Evaluate this integral."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suit','v.适合；使适应n.诉讼；恳求；套装，西装；一套外衣','/s(j)uːt/','/s(j)ut/','noun',["Nick hired a navy-blue suit for the wedding.","Be sure to keep your nose to the grindstone today; the suits are making a \"surprise\" visit to this department.","If you take my advice, you''ll file a suit against him immediately."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('servant','n.仆人，佣人；公务员；雇工','/ˈsɜːvənt/','/ˈsɝvənt/','noun',["There are three servants in the household, the butler and two maids.","She is quite the humble servant, the poor in this city owe much to her but she expects nothing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Wednesday','n.星期三','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('after','adv.后来，以后prep.在……之后conj.在……之后adj.以后的','/ˈæf.tə(ɹ)/','/ˈæf.tɚ/','adjective',["The after gun is abaft the forward gun.","I left the room, and the dog bounded after.","The Cold War began shortly after the Second World War."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attempt','n.企图，试图；攻击v.企图，试图；尝试','/əˈtɛmpt/','/əˈtɛmpt/','noun',["It was worth the attempt.","1584 No man can charge us of any attempt against the realm. (Allen''s Defence Of English Catholics, cited after Edinburgh review 1883, p. 378)","A group of 80 budding mountaineers attempted Kilimanjaro, but 30 of them didn''t make it to the top."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retire','v.退休；撤退；退却n.退休；退隐；退兵信号','/ɹəˈtaɪə(ɹ)/','/ɹəˈtaɪə(ɹ)/','noun',["At the retire, the cavalry fell back.","Having made a large fortune, he retired.","The steamship made thousands of trips over several decades before it was retired by the shipping company."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('return','v.返回；报答n.返回；归还；回球adj.报答的；回程的；返回的','/ɹɪˈtɜːn/','/ɹɪˈtɝn/','noun',["I expect the house to be spotless upon my return.","Do you want a one-way or a return?","Last year there were 250 returns of this product, an improvement on the 500 returns the year before."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('celebrate','v.庆祝；举行；赞美；祝贺；宣告','/ˈsɛl.ə.bɹeɪt/','/ˈsɛl.ə.bɹeɪt/','verb',["to celebrate the name of the Most High","to celebrate a birthday","I was promoted today at work—let’s celebrate!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('switch','v.转换；用鞭子等抽打n.开关；转换；鞭子','/swɪtʃ/','/swɪtʃ/','noun',["Use the /b switch to specify black-and-white printing.","2004, \"Curt\", Can I use IF statements, and still use switches? (on newsgroup microsoft.public.word.mailmerge.fields)","I want to switch this red dress for a green one."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cure','v.治疗；治愈；使硫化；加工处理n.治疗；治愈；[临床]疗法','/kɜː(ɹ)/','/kjɝ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primary','adj.主要的；初级的；基本的n.原色；最主要者','/ˈpɹɒeməɹi/','/ˈpɹaɪməɹi/','noun',["most common primaries","Children attend primary school, and teenagers attend secondary school.","Preferred stock has primary claim on dividends, ahead of common stock."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keep','v.保持；经营；遵守；饲养n.保持；生计；生活费','/kiːp/','/kiːp/','noun',["He works as a cobbler''s apprentice for his keep.","to be in good keep","to keep silence;  to keep one''s word;  to keep possession"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pyramid','n.金字塔；角锥体v.渐增；上涨；成金字塔状','/ˈpɪɹəmɪd/','/ˈpɪɹəmɪd/','noun',["Build your pyramid with all cards face down, except the cards in the bottom row."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afford','v.给予，提供；买得起n.(Afford)人名；(英)阿福德','/əˈfɔːd/','/əˈfoɹd/','verb',["I think we can afford the extra hour it will take.  We can only afford to buy a small car at the moment.","A affords his goods cheaper than B.","Grapes afford wine.  Olives afford oil.  The earth affords fruit.  The sea affords an abundant supply of fish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cut','n.伤口；切口；削减；（服装等的）式样；削球；切入v.[机]切割；削减；缩短；刺痛adj.割下的；雕过的；缩减的','/kʌt/','/kʌt/','noun',["He made a fine cut with his sword.","a smooth or clear cut","Look at this cut on my finger!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ban','v.禁止，取缔n.禁令，禁忌','/bæn/','/bæn/','noun',["Bans is common and ordinary amongst the Feudists, and signifies a proclamation, or any public notice.","France was at such a Pinch..that they call''d their Ban and Arriere Ban, the assembling whereof had been long discussed, and in a manner antiquated.","Bare feet are banned in this establishment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tablet','n.碑；药片；写字板；小块；平板电脑vt.用碑牌纪念；将(备忘录等)写在板上；将…制成小片或小块','/ˈtæblət/','/ˈtæblət/','noun',["Many people take vitamin tablets as a food supplement."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('head','n.头；头痛；上端；最前的部分；理解力v.前进；用头顶；作为…的首领；站在…的前头；给…加标题adj.头的；主要的；在顶端的','/hɛd/','/hɛd/','noun',["Be careful when you pet that dog on the head; it may bite.","What does it say at the head of the page?","We are having a difficult time making head against this wind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foreigner','n.外地人，外国人','/ˈfɒɹ.ɪ.nə(ɹ)/','/ˈfɑɹ.ɪ.nɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('willing','adj.乐意的；自愿的；心甘情愿的v.决心；用意志力驱使；将（财产等）遗赠某人（will的现在分词）n.(Willing)人名；(德、芬、瑞典)维林；(英)威林','/ˈwɪlɪŋ/','/ˈwɪlɪŋ/','verb',["All the fans were willing their team to win the game.","He willed his stamp collection to the local museum.","If my boyfriend isn''t willing to change his drinking habits, I will split up with him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mineral','n.矿物；（英）矿泉水；无机物；苏打水（常用复数表示）adj.矿物的；矿质的','/ˈmɪ.nəɹ.əl/','/ˈmɪ.nəɹ.əl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shade','n.树荫；阴影；阴凉处；遮阳物；（照片等的）明暗度；少量、些微；细微的差别v.使阴暗；使渐变；为…遮阳；使阴郁；掩盖','/ʃeɪd/','/ʃeɪd/','noun',["The old oak tree gave shade in the heat of the day.","Close the shade, please: it''s too bright in here.","I''ve painted my room in five lovely shades of pink and chartreuse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('various','adj.各种各样的；多方面的','/ˈvɛə.ɹi.əs/','/ˈvæɹ.i.əs/','adjective',["The reasons are various.","a various reading of a Biblical text"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poem','n.诗','/ˈpəʊ̯ɪm/','/ˈpoʊ̯ɪm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('above','prep.超过；在……上面；在……之上adv.在上面；在上文adj.上文的n.上文','/əˈbʌv/','/əˈbʌv/','noun',["He''s in a better place now, floating free as the clouds above.","He appealed to the court above.","It was a cold day at only 5 above."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dinosaur','n.恐龙；过时、落伍的人或事物','/ˈdaɪnəsɔː(ɹ)/','/ˈdaɪnəsɔː(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valuable','adj.有价值的；贵重的；可估价的n.贵重物品','/ˈvæljuəbl̩/','/ˈvæljuəbl̩/','noun',["valuable gemstones","a valuable friend; a valuable companion"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swallow','v.忍受；吞没n.燕子；一次吞咽的量','/ˈswɒləʊ/','/ˈswɑloʊ/','noun',["He took the aspirin with a single swallow of water.","My throat was so sore that I was unable to swallow.","to swallow one''s opinions"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blue','n.蓝色；[复数]（美国海、陆、空三军穿的）蓝色制服；蓝颜料；[theblue(s)][用作单数或复数]布鲁斯（歌曲）（一种伤感的美国黑人民歌adj.蓝色的；沮丧的，忧郁的；下流的v.把…染成蓝色；使成蓝色；给…用上蓝剂；用上蓝剂于','/bluː/','/blu/','noun',["The boys in blue marched to the pipers.","His request for leave came out of the blue.","the deep blue sea"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('teamwork','n.团队合作；协力','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wax','n.蜡；蜡状物v.给…上蜡adj.蜡制的；似蜡的','/wæks/','/wæks/','noun',["What role does the wax in your earhole fulfill?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tyre','vt.装轮胎于n.[橡胶]轮胎；轮箍','/taɪə(ɹ)/','/taɪə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hour','n.小时；钟头；课时；…点钟','/ˈaʊə(ɹ)/','/ˈaʊɚ/','noun',["I spent an hour at lunch.","The hour grows late and I must go home.","This place is an hour away from where I live."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('battleground','n.战场','/ˈbætəlˌɡɹaʊnd/','/ˈbætəlˌɡɹaʊnd/','noun',["The farmer''s field was a civil war battleground, and relics such a minnie bullets were frequently found while plowing.","Abortion was becoming the season''s big political battleground."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sometimes','adv.有时，间或','/ˈsʌmtaɪmz/','/ˈsʌmtaɪmz/','adjective',["Sometimes I sit and think, but mostly I just sit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mud','v.弄脏；用泥涂n.泥；诽谤的话；无价值的东西','/mʌd/','/mʌd/','noun',["The campaign issues got lost in all the mud from both parties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('office','n.办公室；政府机关；官职；营业处','/ˈɑfɪs/','/ˈɔfɪs/','noun',["When the office of Secretary of State is vacant, its duties fall upon an official within the department.","She held office as secretary of state until she left office to run for office.","The office of the Secretary of State is cleaned when it is vacant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leg','n.腿；支柱','/lɛɡ/','/lɛɡ/','noun',["{{ux|en|Insects have six legs.}","Dan won''t be able to come to the party, since he broke his leg last week and is now on crutches.","The left leg of these jeans has a tear."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melon','n.瓜；甜瓜；大肚子；圆鼓鼓像瓜似的东西','/ˈmɛlən/','/ˈmɛlən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('race','n.属，种；种族，人种；家庭，门第v.使参加比赛；和…竞赛；使急走，使全速行进','/ɹeɪs/','/ɹeɪs/','noun',["The race around the park was won by Johnny, who ran faster than the others.","the race to cure cancer","The drivers were racing around the track."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optional','adj.可选择的，随意的n.选修科目','','','noun',["On that beach clothing is entirely optional."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stop','v.停止；堵塞；断绝n.停止；车站；障碍；逗留','/stɒp/','/stɑp/','noun',["They agreed to meet at the bus stop.","That stop was not planned.","door stop"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dustbin','n.垃圾箱；吃货','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('screen','n.屏，幕；屏风v.筛；拍摄；放映；掩蔽','/skɹiːn/','/skɹiːn/','noun',["a fire screen","a drug screen, a genetic screen","Mary screened the beans to remove the clumps of gravel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stocking','n.长袜','/ˈstɒkɪŋ/','/ˈstɑkɪŋ/','noun',["a pair of stockings"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flat','adj.平的；单调的；不景气的；干脆的；平坦的；扁平的；浅的adv.（尤指贴着另一表面）平直地；断然地；水平地；直接地，完全地n.平地；公寓；平面vt.使变平；[音乐]使（音调）下降，尤指降半音vi.逐渐变平；[音乐]以降调唱（或奏）','/flæt/','/flæt/','noun',["She liked to walk in her flats more than in her high heels.","a flat of strawberries","The land around here is flat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alone','adj.独自的；单独的；孤独的adv.独自地；单独地','/əˈləʊn/','/əˈloʊn/','adjective',["I can''t ask for help because I am alone.","Jones alone could do it.","She walked home alone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('print','n.印刷业；印花布；印刷字体；印章；印记v.印刷；打印；刊载；用印刷体写；在…印花样','/pɹɪnt/','/pɹɪnt/','noun',["TV and the internet haven''t killed print.","Write in print using block letters.","The print is too small for me to read."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('die','v.死亡；凋零；熄灭n.冲模，钢模；骰子','/daɪ/','/daɪ/','verb',["He died a hero''s death.","I''m dying for a packet of crisps.","The day our sister eloped, she died to our mother."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mouse','n.鼠标；老鼠；胆小羞怯的人v.探出','','','noun',["Captain Higgins moused the hook with a bit of marline to prevent the block beckets from falling out under slack."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('space','n.空间；太空；距离v.留间隔','/speɪs/','/speɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('early','adj.早期的；早熟的adv.提早；在初期n.(Early)人名；(英)厄尔利','/ˈɜː.li/','/ˈɝli/','noun',["at eleven, we went for an early lunch;  she began reading at an early age;  his mother suffered an early death","The early guests sipped their punch and avoided each other''s eyes.","Early results showed their winning 245 out of 300 seats in parliament. The main opponent locked up only 31 seats."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('athletic','adj.运动的，运动员的；体格健壮的','/æθˈlɛt.ɪk/','/æθˈlɛt.ɪk/','adjective',["Are you a member of the American Athletic Association?","Since you''re such an athletic person, you may wish to consider joining.","You have such an athletic build—you must work out regularly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cubic','adj.立方体的，立方的n.(Cubic)人名；(罗)库比克','/ˈkjuː.bɪk/','/ˈkju.bɪk/','noun',["cubic foot","cubic cleavage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secret','n.秘密；秘诀；机密adj.秘密的；机密的','/ˈsiːkɹət/','/ˈsiːkɹət/','noun',["\"Can you keep a secret?\" \"Yes.\" \"So can I.\"","The secret to a long-lasting marriage is compromise.","The work was done in secret, so that nobody could object."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bush','n.灌木；矮树丛v.以灌木装饰；使…精疲力竭adj.如灌木般长得低矮的；粗野的','/bʊʃ/','/bʊʃ/','noun',["bushes to support pea vines","to bush peas","to bush a piece of land; to bush seeds into the ground"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calculate','v.计算；以为；作打算','/ˈkælkjəleɪt/','/ˈkælkjəleɪt/','verb',["Calculate the square root of 3 to 10 decimal places.","to calculate or cast one''s nativity","to calculate a system of laws for the government and protection of a free people"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('super','adj.特级的；极好的n.特级品，特大号；临时雇员','/ˈs(j)uːpə(ɹ)/','/ˈs(j)uːpə(ɹ)/','adjective',["The party was super awesome."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('people','n.人；人类；民族；公民v.居住于；使住满人','/ˈpiːpəl/','/ˈpipl̩/','noun',["There were so many people at the restaurant last night.","My people lived through the Black Plague and the Thirty Years War.","Each person is unique, both mentally and physically."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brake','v.刹车n.闸，刹车；阻碍','/bɹeɪk/','/bɹeɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('side','n.方面；侧面；旁边v.支持；赞助；偏袒adj.旁的，侧的','/saɪd/','/saɪd/','noun',["A square has four sides.","A cube has six sides.","Which side of the tray shall I put it on?  The patient was bleeding on the right side."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('safety','n.安全；保险；安全设备；保险装置；安打','/ˈseɪfti/','/ˈseɪfti/','noun',["If you push it to the limit, safety is not guaranteed.","Be sure that the safety is set before proceeding.","He sacked the quarterback in the end zone for a safety."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snowball','n.雪球v.掷雪球；滚雪球般增大','/ˈsnoʊbɑl/','/ˈsnoʊbɔl/','noun',["The high unemployment rates quickly snowballed into a major budget problem for the government."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('address','v.演说；从事；忙于；写姓名地址；向…致辞；与…说话；提出；处理n.地址；演讲；致辞；说话的技巧；称呼','/əˈdɹɛs/','/æˈdɹɛs/','noun',["He addressed some portions of his remarks to his supporters, some to his opponents.","He addressed a letter.","The ship was addressed to a merchant in Baltimore."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('store','n.商店；储备，贮藏；仓库v.贮藏，储存','/stɔː/','/stɔɹ/','noun',["This building used to be a store for old tires.","I need to get some milk from the grocery store.","The main store of 1000 36-bit words seemed large at the time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('institution','n.制度；建立；（社会或宗教等）公共机构；习俗','/ˌɪnstɪˈtjuːʃən/','/ˌɪnstɪˈtuːʃən/','noun',["He''s been in an institution since the crash.","Over time, the local pub has become something of an institution.","The institution of higher speed limits was a popular move but increased the severity of crashes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neat','adj.灵巧的；整洁的；优雅的；齐整的；未搀水的；平滑的','/niːt/','/niːt/','noun',["My room is neat because I tidied it this morning.  She has very neat hair.","I like my whisky neat.","The Arbuzov reaction is performed by adding the bromide to the phosphite, neat.  The molecular beam was neat acetylene."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laughter','n.笑；笑声','/ˈlɑːftə/','/ˈlæftɚ/','noun',["Their loud laughter betrayed their presence."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('schoolbag','n.书包','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clap','v.鼓掌，拍手；啪地关上n.鼓掌；拍手声','/klæp/','/klæp/','noun',["He summoned the waiter with a clap.","Off in the distance, he heard the clap of thunder.","His father''s affection never went further than a handshake or a clap on the shoulder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wall','n.墙壁，围墙；似墙之物v.用墙围住，围以墙adj.墙壁的','/wɔːl/','/wɔl/','noun',["The town wall was surrounded by a moat.","We''re adding another wall in this room during the remodeling.  The wind blew against the walls of the tent.","A wall of police officers met the protesters before they reached the capitol steps."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duck','n.鸭子；鸭肉；（英）宝贝儿；零分v.闪避；没入水中','/dʌk/','/dʌk/','verb',["I''m just going to duck into the loo for a minute, can you hold my bag?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('download','v.[计]下载','/ˈdaʊnˌləʊd/','/ˈdaʊnˌloʊd/','noun',["The download took longer than I expected.","I got the download but it wouldn''t work on my computer.","You can download a trial version of the program for thirty days to determine whether you want to purchase the full version."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pine','v.渴望，痛苦；憔悴n.[林]松树；凤梨，菠萝adj.松木的；似松的','/paɪn/','/paɪn/','noun',["The northern slopes were covered mainly in pine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agree','v.同意，赞成；承认；约定，商定','/əˈɡɹi/','/əˈɡɹi/','verb',["all parties agree in the expediency of the law.","to agree to an offer, or to opinion.","the picture does not agree with the original; the two scales agree exactly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remember','v.记得；牢记；纪念；代…问好','/ɹɪˈmɛmbə/','/ɹɪˈmɛmbɚ/','verb',["Please remember this formula!","Remember what I''ve said.","Remember to lock the door when you go out."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('large','adj.大的；多数的；广博的adv.大大地；夸大地n.大','/ˈlɑːd͡ʒ/','/ˈlɑɹd͡ʒ/','noun',["Getting a car tricked out like that will cost you 50 large.","One small coffee and two larges, please.","Russia is a large country.   The fruit-fly has large eyes for its body size.   He has a large collection of stamps."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curious','adj.好奇的，有求知欲的；古怪的；爱挑剔的','/ˈkjɔː-/','/ˈkjɝ.i.əs/','adjective',["Young children are naturally curious about the world and everything in it.","The platypus is a curious creature, with fur like a mammal and a beak like a bird."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('day','n.一天；时期；白昼adv.每天；经常在白天地adj.日间的；逐日的','/deɪ/','/deɪ/','noun',["I''ve been here for two days and a bit.","The day begins at midnight.","A day on Mars is slightly over 24 hours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motorcycle','n.摩托车；机动车v.骑摩托车','/ˈməʊtəˌsaikəl/','/ˈməʊtəˌsaikəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jeans','n.牛仔裤；工装裤','/d͡ʒiːnz/','/d͡ʒiːnz/','noun',["She wore a tattered jean jacket.","Traditionally most jeans are dyed dark blue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('busy','adj.忙碌的；热闹的；正被占用的v.使忙于n.(Busy)人名；(匈)布希；(法)比西','/ˈbɪzi/','/ˈbɪzi/','noun',["On my vacation I''ll busy myself with gardening.","We crossed a busy street.","He is busy with piano practice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astonish','v.使惊讶','/əˈstɒnɪʃ/','/əˈstɑnɪʃ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cotton','n.棉花；棉布；棉线v.一致；理解；和谐；亲近adj.棉的；棉制的','/ˈkɒt.n̩/','/ˈkɑt.n̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tax','v.向…课税；使负重担n.税金；重负','/tæks/','/tæks/','noun',["a heavy tax on time or health"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juicy','adj.多汁的；利润多的；生动的','/ˈdʒusi/','/ˈdʒusi/','adjective',["a juicy peach","I do not keep up with all the latest juicy rumors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apply','v.申请；涂，敷；应用','/əˈplaɪ/','/əˈplaɪ/','verb',["to apply cream to a rash","to apply funds to the repayment of a debt","We need to apply the skills we''ve learned to solve this problem"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aggressive','adj.侵略性的；好斗的；有进取心的；有闯劲的','/əˈɡɹɛs.ɪv/','/əˈɡɹɛs.ɪv/','adjective',["an aggressive policy, war, person, nation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canal','n.运河；[地理]水道；[建]管道；灌溉水渠v.在…开凿运河','/kəˈnæl/','/kəˈnɛl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('achieve','v.取得；获得；实现；成功','/əˈtʃiːv/','','verb',["Show all the spoils by valiant kings achieved."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('straight','adj.直的；连续的；笔直的；正直的；整齐的；异性恋的adv.直接地；不断地；立即；坦率地n.直；直线；直男，直女，异性恋者','/stɹeɪt/','/stɹeɪt/','noun',["My friends call straights \"heteros\".","After four straight wins, Mudchester United are top of the league.","a straight Democrat"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shoulder','n.肩，肩膀；肩部v.肩负，承担','/ˈʃəʊldə/','/ˈʃoʊldɚ/','noun',["shoulder the blame"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bitter','adj.苦的；痛苦的；尖刻的；充满仇恨的n.苦味；苦啤酒adv.激烈地；严寒刺骨地v.使变苦','/ˈbɪtə/','/ˈbɪtəɹ/','noun',["The coffee tasted bitter.","They''re bitter enemies.","I''ve been bitter ever since that defeat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('growth','n.增长；发展；生长；种植','/ɡɹəʊθ/','/ɡɹoʊθ/','noun',["Growth was dampened by a softening of the global economy in 2001, but picked up in the subsequent years due to strong growth in China."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volunteer','n.志愿者；志愿兵adj.志愿的v.自愿','/vɒl.ənˈtɪə/','/vɑl.ənˈtɪɹ/','noun',["to volunteer for doing the dishes","to volunteer an explanation","My sister volunteered me to do the dishes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lip','n.嘴唇；边缘vt.以嘴唇碰adj.口头上的vi.用嘴唇','/lɪp/','/lɪp/','noun',["Don’t give me any lip!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('representative','adj.典型的，有代表性的；代议制的n.代表；典型；众议员','/ˌɹɛpɹɪˈzɛnt(ət)ɪv/','/ˌɹɛpɹɪˈzɛnt(ət)ɪv/','noun',["Are you sure this paper is representative of your child''s writing?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('same','adj.相同的；同一的；上述的（通常与the连用）；无变化的pron.同样的事物或人（通常与the连用）adv.同样地（通常与the连用）n.(Same)人名；(意)萨梅','/seɪm/','/seɪm/','adjective',["Are you the same person who phoned me yesterday?","It took all night to find our hotel room, as we forgot our room number and each door looked the same.","You have the same hair I do!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('southern','adj.南的；南方的n.南方人','/ˈsʌðɚn/','/ˈsʌðɚn/','noun',["The southern climate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('daylight','n.白天；日光；黎明；公开','/ˈdeɪlaɪt/','/ˈdeɪlaɪt/','noun',["We should get home while it''s still daylight.","We had only two hours to work before daylight.","Budgeting a spy organization can''t very well be done in daylight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symphony','n.交响乐；谐声，和声','/ˈsɪm.fə.ni/','/ˈsɪm.fə.ni/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('watermelon','n.西瓜','/ˈwɔːtəˌmɛlən/','/ˈwɔtəɹˌmɛlən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smoking','n.抽烟；冒气adv.冒着烟adj.准许吸烟的v.吸烟；冒烟（smoke的现在分词）','/ˈsməʊkɪŋ/','/ˈsmoʊkɪŋ/','verb',["He''s smoking his pipe.","Do you smoke?","My old truck was still smoking even after the repairs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clinic','n.临床；诊所','/ˈklɪnɪk/','/ˈklɪnɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('model','n.模型；典型；模范；模特儿；样式v.模拟；塑造；模仿adj.模范的；作模型用的','/ˈmɒdl̩/','/ˈmɑdl̩/','noun',["The beautiful model had her face on the cover of almost every fashion magazine imaginable.","The boy played with a model of a World War II fighter plane.","The computer weather model did not correctly predict the path of the hurricane."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partly','adv.部分地；在一定程度上','/ˈpɑːtli/','/ˈpɑɹtli/','adverb',["they partly finished the house so they could move in before winter;  the car was partly visible in the garage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('painter','n.画家；油漆匠','/ˈpeɪntə/','/ˈpeɪntɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purse','n.(女士)手提袋；(国家、家庭、团体等的)财力v.（嘴巴）皱起，使缩拢；撅嘴','/pɜːs/','/pɝs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('characteristic','adj.典型的；特有的；表示特性的n.特征；特性；特色','/ˌkæɹəktəˈɹɪstɪk/','/ˌkæɹəktəˈɹɪstɪk/','noun',["The characteristic of a field, if non-zero, must be a prime number."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skin','n.皮肤；外皮v.剥皮','/skɪn/','/skɪn/','noun',["He is so disgusting he makes my skin crawl.","In order to get to the rest of the paint in the can, you′ll have to remove the skin floating on top of it.","You can use this skin to change how the browser looks."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('train','n.火车；行列；长队；裙裾v.培养；训练；瞄准','/tɹeɪn/','/tɹeɪn/','noun',["She trained seven hours a day to prepare for the Olympics.","You can''t train a pig to write poetry.","I trained with weights all winter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vivid','adj.生动的；鲜明的；鲜艳的','/ˈvɪvɪd/','/ˈvɪvɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('operation','n.操作；经营；[外科]手术；[数][计]运算','/ˌɒpəˈɹeɪʃən/','/ˌɑpəˈɹeɪʃən/','noun',["The Katrina relief operation was considered botched.","They run a multinational produce-supply operation.","She had an operation to remove her appendix."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('check','v.检查，核对；制止，抑制；在…上打勾n.<美>支票；制止，抑制；检验，核对','/t͡ʃɛk/','/t͡ʃɛk/','noun',["I don''t know if she will be there, but it''s worth a check.","The castle moat should hold the enemy in check.","Place a check by the things you have done."]);
