INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('button','n.按钮；纽扣v.扣住；扣紧；在…上装纽扣','/ˈbʌtn̩/','/ˈbʌtn̩/','noun',["April fastened the buttons of her overcoat to keep out the wind.","Pat pushed the button marked \"shred\" on the blender.","Click the button that looks like a house to return to your browser''s home page."]);
