INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('give','v.给；产生；让步；举办；授予n.弹性；弯曲；伸展性','/ɡɪv/','/ɡɪv/','noun',["There is no give in his dogmatic religious beliefs.","I give it a 95% chance of success.","One pillar gave, then more, and suddenly the whole floor pancaked onto the floor below."]);
