INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquisition','n.获得物，获得；收购','/æ.kwɪ.ˈzɪ.ʃən/','/æ.kwɪ.ˈzɪ.ʃən/','noun',["The acquisition of sports equipment can be fun in itself.","That graphite tennis racquet is quite an acquisition."]);
