INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dish','n.盘；餐具；一盘食物；外貌有吸引力的人v.盛于碟盘中；分发；使某人的希望破灭；说（某人）的闲话','/dɪʃ/','/dɪʃ/','noun',["a dish of stew","a vegetable dish","It''s your turn to wash the dishes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tap','v.轻敲；轻打；装上嘴子n.水龙头；轻打','/tæp/','/tæp/','noun',["We don''t have bottled water; you''ll have to get it from the tap.","a liquor of the same tap","We drilled a hole and then cut the threads with the proper tap to match the valve''s thread."]);
