INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unemployment','n.失业；失业率；失业人数','/ʌn.ɪmˈplɔɪ.mənt/','/ʌn.ɪmˈplɔɪ.mənt/','noun',["Unemployment made Jack depressed.","Unemployment has been considered a cause of crime.","Unemployment was reported at 5.2% in May, up from 4.9% in April."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('football','n.足球，橄榄球vi.踢足球；打橄榄球','[fʷʊʔt̚bɑɫ]','[fʷʊʔt̚bɑɫ]','noun',["Roman and medieval football matches were more violent than any modern type of football.","Each team scored three goals when they played football.","Each team scored two touchdowns when they played football."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ahead','adj.向前；在前的；领先adv.向前地；领先地；在（某人或某事物的）前面；预先；在将来，为未来','/əˈhɛd/','/əˈhɛd/','adverb',["Just ahead you can see the cliffs.","There may be tough times ahead.","He paid his rent ahead."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impression','n.印象；效果，影响；压痕，印记；感想；曝光（衡量广告被显示的次数。打开一个带有该广告的网页，则该广告的impression次数增加一次）','/ɪmˈpɹɛʃən/','/ɪmˈpɹɛʃən/','noun',["His head made an impression on the pillow.","He tried to make a good impression on his parents.","I have the impression that he''s already left for Paris."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buy','v.购买；获得；贿赂n.购买，买卖；所购的物品','/baɪ/','/baɪ/','noun',["At only $30, the second-hand kitchen table was a great buy.","I''m going to buy my father something nice for his birthday.","I''ve bought material comfort by foregoing my dreams."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spit','v.吐痰；吐口水；发出劈啪声n.唾液','/spɪt/','/spɪt/','noun',["to spit a loin of veal","She’s spitting the roast in the kitchen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('across','prep.穿过；横穿adv.横过；在对面','/əˈkɹɑs/','/əˈkɹɔs/','noun',["I solved all of the acrosses, but then got stuck on 3 down.","she helped the blind man across;  the river is half a mile across","If we sail off at noon, when will we be across?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('no','adv.不adj.没有；不是n.不；否决票abbr.数字（number）；元素锘（nobelium）的符号','/nəʊ/','/noʊ/','noun',["The workers voted on whether to strike, and there were thirty \"yeses\" and two \"nos\".","I just want to find out whether she''s coming or no. (Scotland)"]);
