INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bang','n.刘海；重击；突然巨响adv.直接地；砰然地；突然巨响地v.重击；发巨响','/bæŋ(ɡ)/','/bæŋ(ɡ)/','noun',["When he struck it with a hammer, there was a loud bang.","An e-mail address with an ! is called a bang path.","Load the bang into the hole."]);
