INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('international','n.国际组织；国际体育比赛；外国居留者；国际股票adj.国际的；两国（或以上）国家的；超越国界的；国际关系的；世界的','/ˌɪntəˈnæʃ(ə)n(ə)l/','/ˌɪntɚˈnæʃ(ə)n(ə)l/','noun',["The United team includes five England internationals.","an international discussion","an international competition"]);
