INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quit','v.离开；放弃；停止；使…解除n.离开；[计]退出adj.摆脱了…的；已经了结的','/kwɪt/','/kwɪt/','verb',["After having to work overtime without being paid, I quit my job.","John is planning to quit smoking."]);
