INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sculpture','n.雕塑；雕刻；刻蚀v.雕塑；雕刻；刻蚀','/ˈskʌlptj(ʊ)ə/','/ˈskʌlpt͡ʃɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steal','v.剽窃；偷偷地做；偷窃n.偷窃；便宜货；偷垒；断球','/stiːl/','/stiːl/','noun',["At this price, this car is a steal.","Three irreplaceable paintings were stolen from the gallery.","They stole my idea for a biodegradable, disposable garbage de-odorizer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miniskirt','n.超短裙；迷你短裙','/ˈmɪnɪskəːt/','/ˈmɪnɪskəːt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('research','n.研究；调查v.研究；调查','/ɹɪˈsɜːtʃ/','/ɹiˈsɝtʃ/','noun',["The research station that houses Wang and his team is outside Lijiang, a city of about 1.2 million people."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refrigerator','n.冰箱，冷藏库','/ɹɪˈfɹɪd͡ʒəˌɹeɪtə/','/ɹəˈfɹɪd͡ʒəˌɹeɪɾɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('round','n.圆；循环；一回合；圆形物adj.圆的；完全的；大概的；肥胖的adv.在周围；迂回地；朝反方向；挨个v.完成；围捕；绕行；弄圆prep.附近；绕过；大约；在…周围','/ˈɹaʊnd/','/ˈɹaʊnd/','adverb',["High above, vultures circled around.","Everybody please gather around.","An adult elephant weighs around five tons."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('casual','adj.随便的；非正式的；临时的；偶然的n.便装；临时工人；待命士兵','/ˈkɛʒɘl/','/ˈkɛʒɘl/','noun',["The devs dumbed the game down so the casuals could enjoy it.","They only had casual meetings.","The purchase of donuts was just a casual expense."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cancel','v.取消；删去n.取消，撤销','/ˈkænsl̩/','/ˈkænsl̩/','noun',["He cancelled his order on their website.","This machine cancels the letters that have a valid zip code.","The corrective feedback mechanism cancels out the noise."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('he','n.男孩，男人；它（雄性动物）pron.他','','/hi/','noun',["Is your cat a he or a she?","The rulebook clearly states that \"if any student is caught cheating, he will be expelled\", and you were caught cheating, were you not, Anna?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('colleague','n.同事，同僚','/ˈkɒliːɡ/','/ˈkɑliɡ/','noun',["Young Fortinbras,/ Holding a weak supposal of our worth/...Colleagued with the dream of his advantage,/...hath not failed to pester us with message/ Importing the surrender of those lands/Lost by his father. - Hamlet (Act I, Scene 2)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whether','conj.是否；不论pron.两个中的哪一个','/ˈwɛðə(ɹ)/','/ˈwɛðə(ɹ)/','pronoun',["He chose the correct answer, but I don''t know whether it was by luck or (whether it was) by skill.","Do you know whether he''s coming?","He''s coming, whether you like it or not."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('live','adj.活的；生动的；实况转播的；精力充沛的v.经历；度过n.(Live)人名；(法)利夫','/lɪv/','/lɪv/','verb',["He''s not expected to live for more than a few months.","I live at 2a Acacia Avenue.  He lives in LA, but he''s staying here over the summer.","Her memory lives in that song."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beyond','prep.超过；越过；那一边；在较远的一边adv.在远处；在更远处n.远处','/biˈjɒnd/','/biˈjɑnd/','noun',["2017 July 13, Joseph Gamp \"Marvel release stirring new set images of Black Panther and we are BEYOND excited\" Metro (UK)","She had no reason for the conviction beyond the very inadequate one that she had seen him around London.","No swimming beyond this point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ill','adj.生病的；坏的；邪恶的；不吉利的adv.不利地；恶劣地；几乎不n.疾病；不幸','/ɪl/','/ɪl/','noun',["Music won''t solve all the world''s ills, but it can make them easier to bear.","I wouldn''t want you to do me ill.","I am incapacitated by rheumatism and other ills."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skate','v.滑冰；滑过n.溜冰；冰鞋','/skeɪt/','/skeɪt/','noun',["There''s time for a quick skate before dinner.","The boys had a skate every morning when the lake was frozen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('herb','n.香草，药草','/hɜːb/','/hɜːb/','noun',["If any medicinal herbs used by witches were supposedly evil, then how come people from at least the past benefited from the healing properties of such herbs?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recent','adj.最近的；近代的','/ˈɹiːsənt/','/ˈɹiːsənt/','adjective',["I met three recent graduates at the conference."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discuss','v.讨论；论述，辩论','/dɪsˈkʊs/','/dɪsˈkʌs/','verb',["I don''t wish to discuss this further. Let''s talk about something else."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silent','adj.沉默的；寂静的；无记载的n.无声电影','/ˈsaɪlənt/','/ˈsaɪlənt/','noun',["The wind is silent.","Silent letters can make some words difficult to spell.","My phone was on silent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kind','n.种类；性质adj.和蔼的；宽容的；令人感激的','/kaɪnd/','/kaɪnd/','noun',["This is a strange kind of tobacco.","The opening served as a kind of window.","I''ll pay in kind for his insult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('badly','adv.非常，很；严重地，厉害地；恶劣地','/ˈbæd.li/','/ˈbæd.li/','adjective',["He''s never badly.","I want it so badly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contradictory','adj.矛盾的；反对的；反驳的；抗辩的n.对立物；矛盾因素','/ˌkɑntɹəˈdɪktəɹi/','/ˌkɑntɹəˈdɪktəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shower','n.淋浴；（倾泻般出现的）一阵，一大批；阵雨v.大量地给予；把……弄湿','/ˈʃaʊ.ə(ɹ)/','/ˈʃaʊ.ə(ɹ)/','noun',["Today there will be frequent showers and some sunny spells.","I′m going to have a shower.","a shower of sparks;  a meteor shower;  a Gatorade shower"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aspect','n.方面；方向；形势；外貌','/ˈæspɛkt/','/ˈæspɛkt/','noun',["Japan''s aging population is an important aspect of its economy.","The house has a southern aspect, i.e. a position which faces the south."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decade','n.十年，十年期；十','/dəˈkeɪd/','/dəˈkeɪd/','noun',["a decade of soldiers","There are decades between 1.8 and 18, between 25 and 250 and between 0.03 and 0.003."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distance','n.距离；远方；疏远；间隔v.疏远；把…远远甩在后面','/ˈdɪs.təns/','/ˈdɪs.təns/','noun',["From Moscow, the distance is relatively short to Saint Petersburg, relatively long to Novosibirsk, but even greater to Vladivostok.","We''re narrowing the distance between the two versions of the bill.  The distance between the lowest and next gear on my bicycle is annoying.","the distance between a descendant and his ancestor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zipper','n.拉链v.拉上拉链','/ˈzɪpɚ/','/ˈzɪpɚ/','noun',["He zippered his sweater against the cold.","These fall jackets are zippered."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permanent','adj.永久的，永恒的；不变的n.烫发（等于permanentwave）','/ˈpɜːmənənt/','/ˈpɝmənənt/','noun',["Nothing in this world is truly permanent.","The countries are now locked in a permanent state of conflict."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('honour','n.荣誉；尊敬；勋章v.尊敬；[金融]承兑；承兑远期票据','/ˈɒnə(ɹ)/','/ˈɒnə(ɹ)/','noun',["The crowds gave the returning general much honor and praise.","He was a most perfect knight, for he had great honor and chivalry.","Audie Murphy received many honors, such as the Distinguished Service Cross."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('political','adj.政治的；党派的','/pəˈlɪtɪkəl/','/pəˈlɪtɪkəl/','noun',["Political principles are rarely absolute, as political logic holds an imperfect result by compromise is better than a theoretically perfect abstention from the political process in the opposition.","Good political staff is hard to find, they may neither be ambitious and corrupted by power nor tempted by private sector careers.","“The Court invalidates Minnesota’s political apparel ban based on its inability to define the term ‘political''”"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organise','v.组织起来；组织工会','','','verb',["an organized being","to organize an anthem","the workers decided to organize; their next task was to organize the workers at the steel mill"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('driver','n.驾驶员；驱动程序；起子；传动器','/ˈdɹaɪ.və(ɹ)/','/ˈdɹaɪvɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complete','adj.完整的；完全的；彻底的v.完成','/kəmˈpliːt/','/kəmˈpliːt/','noun',["He completed the assignment on time.","The last chapter completes the book nicely.","After she found the rook, the chess set was complete."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nowhere','adv.无处；任何地方都不；毫无结果n.无处；任何地方；无名之地adj.不存在的；毫无结果的；不知名的','/ˈnəʊ.wɛə/','/ˈnoʊ.(h)wɛɹ/','noun',["They went on a cruise to nowhere.","Nowhere did the rules say anything about popcorn.","We sat in traffic, going nowhere."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shop','n.商店；店铺v.购物','/ʃɒp/','/ʃɑp/','noun',["This is where I do my weekly shop.","He’s shopping for clothes.","Shop our new arrivals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gradually','adv.逐步地；渐渐地','/ˈɡɹædʒuəli/','/ˈɡɹædʒuəli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shaver','n.理发师；电动剃刀','/ˈʃeɪvə/','/ˈʃeɪvə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virus','n.[病毒]病毒；恶毒；毒害','/ˈvaɪɹəs/','/ˈvaɪɹəs/','noun',["He caught a virus and had to stay home from school."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disk','n.[计]磁盘，磁碟片；圆盘，盘状物；唱片','/dɪsk/','/dɪsk/','noun',["A coin is a disk of metal.","Venus'' disk cut off light from the Sun.","Turn the disk over, after it has finished."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loaf','n.条，一条面包；块；游荡v.游荡；游手好闲；虚度光阴','/ləʊf/','/ləʊf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrest','v.逮捕；阻止；吸引n.逮捕；监禁','/əˈɹɛst/','/əˈɹɛst/','noun',["The police have arrested a suspect in the murder inquiry."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('square','adj.平方的；正方形的；直角的；正直的v.使成方形；与…一致n.平方；广场；正方形adv.成直角地','/skwɛə(ɹ)/','/skwɛɚ/','noun',["64 is the square of 8.","Why do you always wear a tie? Don''t be such a square!","Enter your account number followed by a square."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('justice','n.司法，法律制裁；正义；法官，审判员','/ˈdʒʌs.tɪs/','/ˈdʒʌs.tɪs/','noun',["the justice of a description","Justice was served.","to demand justice"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Dr','abbr.速度三角形定位法（deadreckoning）；数据记录器（DataRecorder）','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('world','n.世界；领域；世俗；全人类；物质生活','/wɝld/','/wɝld/','noun',["There will always be lovers, till the world’s end.","People are dying of starvation all over the world.","Our mission is to travel the galaxy and find new worlds."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('if','conj.（表条件）如果；即使；是否；（表假设）假如n.条件；设想','/ɪf/','/ɪf/','noun',["If it rains, I shall get wet.","If A, then B, else C.","I would be unhappy if you had not talked with me yesterday."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dirt','n.污垢，泥土；灰尘，尘土；下流话','/dɜːt/','/dɝt/','noun',["The reporter uncovered the dirt on the businessman by going undercover."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('procedure','n.程序，手续；步骤','/pɹəˈsiːdʒə/','/pɹəˈsidʒɚ/','noun',["Ensure that you follow procedure when accessing customers'' personal information."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mix','v.配制；混淆；使混和；使结交n.混合；混合物；混乱','/ˈmɪks/','/ˈmɪks/','verb',["Mix the eggs and milk with the flour until the consistency is smooth.","Don''t mix the meat recipes with the dairy recipes.","Yellow and blue paint mix to make green."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strong','adj.坚强的；强壮的；牢固的；擅长的adv.强劲地；猛烈地n.(Strong)人名；(英)斯特朗','/stɹɒŋ/','/stɹɔŋ/','adjective',["a big strong man; Jake was tall and strong","a strong foundation; good strong shoes","The man was nearly drowned after a strong undercurrent swept him out to sea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fact','n.事实；实际；真相','/fækt/','/fækt/','noun',["In this story, the Gettysburg Address is a fact, but the rest is fiction.","Gravity is a fact, not a theory.","Let''s look at the facts of the case before deciding."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kilo','n.千克','/ˈkiːləʊ/','/ˈkiːləʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scientific','adj.科学的，系统的','/ˌsaɪənˈtɪfɪk/','/ˌsaɪənˈtɪfɪk/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feed','v.喂养；供给；放牧；抚养（家庭等）；靠…为生n.饲料；饲养；（动物或婴儿的）一餐','/ˈfiːd/','/ˈfiːd/','noun',["They sell feed, riding helmets, and everything else for horses.","a satellite feed","the paper feed of a printer"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('category','n.种类，分类；[数]范畴','/ˈkætəˌɡɔɹi/','/ˈkætəˌɡɔɹi/','noun',["I wouldn''t put this book in the same category as the author''s first novel.","Just as a monoid consists of an underlying set with a binary operation \"on top of it\" which is closed, associative and with an identity, a category consists of an underlying digraph with an arrow composition operation \"on top of it\" which is transitively closed, associative, and with an identity at each object. In fact, a category''s composition operation, when restricted to a single one of its objects, turns that object''s set of arrows (which would all be loops) into a monoid."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dead','adj.无生命的；呆板的；废弃了的adv.完全地n.死者','/diːd/','/diːd/','noun',["Have respect for the dead.","The dead of night. The dead of winter.","All of my grandparents are dead."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('against','prep.反对，违反；靠；倚；防备adj.不利的；对立的','/əˈɡeɪnst/','/əˈɡɛnst/','preposition',["It is hard work to swim against the current.","The rain pounds against the window.","The kennel was put against the back wall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrupt','adj.腐败的，贪污的；堕落的v.使腐烂；使堕落，使恶化','/kəˈɹʌpt/','/kəˈɹʌpt/','verb',["to corrupt a book","The government here is corrupt, so we''ll emigrate to escape them.","It turned out that the program was corrupt - that''s why it wouldn''t open."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laugh','n.笑；引人发笑的事或人v.笑','/laːf/','/læf/','noun',["His deep laughs boomed through the room.","Your new hat''s an absolute laugh, dude.","There were many laughing children running on the school grounds."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airspace','n.空域；领空；空间','','','noun',["Various European countries transferred the aviation control of their adjoining airspace to Eurocontrol, while each retaining legal jurisdiction.","The legalisation of free radios caused a bitter fight for airspace."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vanilla','n.香子兰，香草adj.香草味的','/vəˈnɛlə/','/vəˈnɛlə/','noun',["You can tell that the secret ingredient missing from New CokeTM was vanilla, because certain South American economies collapsed when it was introduced, and miraculously revived when the old formula was used again.","vanilla JavaScript"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hammer','v.锤击；敲打；重复n.铁锤；链球；[解剖]锤骨；音锤','/ˈhæm.ə(ɹ)/','/ˈhæmɚ/','noun',["Bobby used a hammer and nails to fix the two planks together","The nail is too loose - give it a hammer.","The sound the piano makes comes from the hammers striking the strings"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perfume','n.香水；香味v.洒香水于…；使…带香味','/ˈpɜːfjuːm/','/ˈpɜːfjuːm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whose','pron.谁的（疑问代词）','/huːz/','/huːz/','pronoun',["Several people have lost their suitcases. Whose have you found?","This car is blocking the way, but Mr Smith, whose it is, will be here shortly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necktie','n.领带','/ˈnɛk.taɪ/','/ˈnɛk.taɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bury','v.埋葬；隐藏n.(Bury)人名；(法)比里；(英、西)伯里；(德、意、罗、波、捷、匈)布里；(俄)布雷','/ˈbʌ.ɹi/','/ˈbɛ.ɹi/','noun',["bury a bone;  bury the embers","she buried her face in the pillow;  they buried us in paperwork","secrets kept buried; she buried her shame and put on a smiling face."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cabbage','n.卷心菜，甘蓝菜，洋白菜；（俚)脑袋；（非正式、侮辱）植物人（常用于英式英语）；（俚）钱，尤指纸币（常用于美式俚语）','/ˈkæbɪdʒ/','/ˈkæbɪdʒ/','noun',["Cabbage is good for you.","After the car crash, he became a cabbage.","to make lettuce cabbage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shortcoming','n.缺点；短处','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salt','n.盐；风趣，刺激性adj.咸水的；含盐的，咸味的；盐腌的；猥亵的v.用盐腌；给…加盐；将盐撒在道路上使冰或雪融化','/sɒlt/','/sɑlt/','noun',["Attic salt","to salt fish, beef, or pork; to salt the city streets in the winter","The brine begins to salt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seventy','n.七十；七十个；七十岁；七十年代adj.七十的；七十个的；七十岁的num.七十','/ˈsɛv.ən.di/','/ˈsɛv.ən.di/','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('length','n.长度，长；时间的长短；（语）音长','/lɛn(t)θ/','/lɛn(t)θ/','noun',["the length of a book","a length of rope"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worst','adj.最差的，最坏的；最不利的；效能最低的n.最坏；最坏的时候adv.最坏地；最不利地','/wɜːst/','/wɝst/','adjective',["Abducting children is bad for mothers.","Do you think it is a bad idea to confront him directly?","It is bad manners to talk with your mouth full."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audience','n.观众；听众；读者；接见；正式会见；拜会','/ˈɔːdi.əns/','/ˈɔːdi.əns/','noun',["We joined the audience just as the lights went down.","She managed to get an audience with the Pope.","\"Private Eye\" has a small but faithful audience."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('measure','n.测量；措施；程度；尺寸v.测量；估量；权衡','/ˈmɛʒə/','/ˈmɛʒɚ/','noun',["We measured the temperature with a thermometer.   You should measure the angle with a spirit level.","The window measured two square feet.","I measure that at 10 centimetres."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outline','n.轮廓；大纲；概要；略图v.概述；略述；描画…轮廓','/ˈaʊtlaɪn/','/ˈaʊtlaɪn/','noun',["the outline of a speech","Wikipedia items featuring books usually outline them after giving their background."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bathroom','n.浴室；厕所；盥洗室','/ˈbæθ.ɹuːm/','/ˈbæθ.ɹuːm/','noun',["Most Americans don''t know ''WC'' and many Brits mock ''bathroom'' but almost everyone understands ''toilet'' or ''lavatory''."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('height','n.高地；高度；身高；顶点','/haɪt/','/haɪt/','noun',["She''s at the height of her career."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prairie','n.大草原；牧场','/ˈpɹɛəɹi/','/ˈpɹɛəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balance','n.平衡；余额；匀称v.使平衡；结算；使相称','/ˈbæləns/','/ˈbæləns/','noun',["Blair thought he could provide a useful balance to Bush''s policies.","I think the balance of opinion is that we should get out while we''re ahead.","I just need to nip to a bank and check my balance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blind','adj.盲目的；瞎的adv.盲目地；看不见地n.掩饰，借口；百叶窗v.使失明；使失去理智','/blaɪnd/','/blaɪnd/','noun',["a duck blind","The blinds are $10/$20 and the ante is $1.","The blinds immediately folded when I reraised."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('portable','adj.手提的，便携式的；轻便的n.手提式打字机','/ˈpɔː(ɹ)təbl̩/','/ˈpɔː(ɹ)təbl̩/','noun',["a portable pension plan"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('row','n.行，排；划船；街道；吵闹v.划船；使……成排','/ˈɹəʊ/','/ˈɹoʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('truly','adv.真实地，不假；真诚地n.(Truly)人名；(英)特鲁利','/ˈtɹuːli/','','adverb',["That is truly all I know.","You are truly silly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downward','adj.向下的，下降的adv.向下','/ˈdaʊnwəd/','/ˈdaʊnwəd/','adjective',["He spoke with a downward glance.","His position in society moved ever downward."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accent','n.口音；重音；强调；特点；重音符号v.强调；重读；带…口音讲话','/ˈak.sənt/','/ˈak.sənt/','noun',["In the word \"careful\", the accent is placed on the first syllable.","At this hotel, the accent is on luxury.","The name Cézanne is written with an acute accent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basket','n.篮子；（篮球比赛的）得分；一篮之量；篮筐vt.装入篮','/ˈbaːskət/','/ˈbæskɪt/','noun',["A basket of fake fruit adorned the table.","The point guard drove toward the basket.","The last-second basket sealed the victory."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shave','v.剃须，剃毛n.刮脸，剃胡子；修面；<口>侥幸逃过，幸免；剃刀，刮刀','/ʃeɪv/','/ʃeɪv/','verb',["The labourer with the bending scythe is seen / Shaving the surface of the waving green.","I had little time to shave this morning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outer','adj.外面的，外部的；远离中心的n.环外命中','/ˈaʊtə/','/ˈaʊtɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('note','n.笔记；音符；票据；注解；纸币；便笺；照会；调子v.注意；记录；注解','/nəʊt/','/noʊt/','noun',["a poet of note","If you look to the left, you can note the old cathedral.","We noted his speech."]);
