INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drag','v.拖累；拖拉；缓慢而吃力地行进n.拖；拖累','/dɹæɡ/','','noun',["When designing cars, manufacturers have to take drag into consideration.","Travelling to work in the rush hour is a real drag.","to run a drag"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unite','v.使…混合；使…联合；使…团结','/juˈnaɪt/','/juˈnaɪt/','noun',["I hope this song can unite people from all different cultures.","If we want to win, we will need to unite."]);
