INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confident','adj.自信的；确信的','/ˈkɒn.fɪ.dənt/','/ˈkɑn.fɪ.dənt/','noun',["I''m pretty confident that she''s not lying, she''s acting normally."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('website','n.网站（全球资讯网的主机站）','/ˈwɛbˌsaɪt/','/ˈwɛbˌsaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swell','v.膨胀；肿胀；隆起n.肿胀；隆起adj.漂亮的；一流的','/swɛl/','/swɛl/','verb',["Rains and dissolving snow swell the rivers in spring.","The organ music swelled.","to be swelled with pride or haughtiness"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medicine','n.药；医学；内科；巫术v.用药物治疗；给…用药','/ˈmed(ɪ).sn̩/','/ˈmɛ.dɪ.sɪn/','noun',["She''s studying medicine at university because she wants to be a doctor in the future."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('set','n.[数]集合；一套；布景；[机]装置v.树立；点燃；点缀；adj.固定的；规定的；固执的','/sɛt/','/sɛt/','verb',["Set the tray there.","I have set my heart on running the marathon.","to set a coach in the mud"]);
