INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('process','v.处理；加工n.过程，进行；方法，步骤；作用；程序；推移adj.经过特殊加工（或处理）的','/ˈpɹəʊsɛs/','/ˈpɹɑsɛs/','noun',["This product of last month''s quality standards committee is quite good, even though the process was flawed.","1960, Mack Tyner, Process Engineering Calculations: Material and Energy Balances – Ordinarily a process plant will use a steam boiler to supply its process heat requirements and to drive a steam-turbine generator.","We have processed the data using our proven techniques, and have come to the following conclusions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('east','n.东方；东风；东方国家adj.东方的；向东的；从东方来的adv.向东方，在东方','/iːst/','/iːst/','noun',["the east front of a cathedral"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurry','n.匆忙，急忙v.仓促（做某事）；催促；（朝某方向）迅速移动；迅速处理','/ˈhʌ.ɹi/','/ˈhʌ.ɹi/','noun',["Why are you in such a big hurry?","There is no hurry on that paperwork.","He''s hurrying because he''s late."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('how','adv.如何；多少；多么n.方法；方式conj.如何','/haʊ/','/haʊ/','noun',["I am not interested in the why, but in the how.","How often do you practice?","How do you solve this puzzle?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beast','n.野兽；畜生，人面兽心的人','/biːst/','/biːst/','noun',["That is a beast of a stadium."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practice','n.实践；练习；惯例v.练习；实习；实行','/ˈpɹæktɪs/','/ˈpɹæktɪs/','noun',["He will need lots of practice with the lines before he performs them.","Being on a team is hard: you''re always having to go to practice while everyone else is taking it easy.","She ran a thriving medical practice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reliable','adj.可靠的；可信赖的n.可靠的人','/ɹɪˈlaɪəbəl/','/ɹɪˈlaɪəbəl/','noun',["the old reliables"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evening','n.晚上；傍晚；（联欢性的）晚会；后期adj.在晚上的；为晚上的；晚上用的int.晚上好（等于goodevening）','/ˈivnɪŋ/','/ˈivnɪŋ/','noun',["It was the evening of the Roman Empire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allocate','v.分配；拨出；使坐落于','/ˈæl.ə.keɪt/','/ˈæl.ə.keɪt/','verb',["The bulk of K–12 education funds are allocated to school districts that in turn pay for the cost of operating schools."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('development','n.发展；开发；发育；住宅小区（专指由同一开发商开发的）；[摄]显影','/dɪˈvɛləpmənt/','/dɪˈvɛləpmənt/','noun',["The development of this story has been slow.","The organism has reached a crucial stage in its development.","Our news team brings you the latest developments."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paragraph','n.段落；短评；段落符号v.将…分段','/ˈpæɹəɡɹɑːf/','/ˈpɛɹəɡɹæf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terminal','n.末端；终点；终端机；极限adj.末端的；终点的；晚期的','/ˈtɚmɪnəl/','/ˈtɚmɪnəl/','noun',["terminal cancer","a student''s terminal fees"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correspond','v.符合，一致；相应；通信','/ˌkɒɹəˈspɒnd/','/ˌkɑɹəˈspɑnd/','verb',["I''ve been corresponding with my German pen pal for three years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('war','n.战争，斗争；军事，战术；冲突，对抗，竞争v.打仗，作战；对抗','/wɔː/','/wɔɹ/','noun',["The war was largely between Sunni and Shia militants.","You look like you''ve been through the wars."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleepy','adj.欲睡的；困乏的；不活跃的','/ˈsliːpi/','/ˈsliːpi/','noun',["a sleepy drink or potion","a sleepy English village"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surprise','n.惊奇，诧异；突然袭击v.使惊奇；奇袭adj.令人惊讶的','/səˈpɹaɪz/','/səˈpɹaɪz/','noun',["It was a surprise to find out I owed twice as much as I thought I did.","Imagine my surprise on learning I owed twice as much as I thought I did.","It surprises me that I owe twice as much as I thought I did."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snowman','n.雪人','/ˈsnəʊ.mæn/','/ˈsnoʊ.mæn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('search','v.搜寻；调查；探求n.搜寻；探究，查究','/sɜːt͡ʃ/','/sɝt͡ʃ/','noun',["With only five minutes until we were meant to leave, the search for the keys started in earnest.","Search is a hard problem for computers to solve efficiently.","I searched the garden for the keys and found them in the vegetable patch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toothache','n.[口腔]牙痛','/ˈtuθˌeɪk/','/ˈtuθˌeɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wash','n.洗涤；洗的衣服；化妆水；冲积物v.洗涤；洗刷；冲走；拍打','/wɒʃ/','/wɑʃ/','noun',["I''m going to have a quick wash before coming to bed.","hand wash","There''s a lot in that wash: maybe you should split it into two piles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classroom','n.教室','/ˈklɑːsɹʊm/','/ˈklɑːsɹʊm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nephew','n.侄子；外甥','/ˈnɛf.ju/','/ˈnɛf.ju/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cap','n.盖；帽子v.脱帽致意','/kæp/','/kæp/','noun',["The children were all wearing caps to protect them from the sun.","He took the cap off the bottle and splashed himself with some cologne.","He had golden caps on his teeth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aggression','n.侵略；进攻；侵犯；侵害','/əˈɡɹɛʃən/','/əˈɡɹɛʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('TV','abbr.电视（television）','','','noun',["It’s a good thing that television doesn’t transmit smell.","I have an old television in the study.","fifty-seven channels and nothing on television"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notebook','n.笔记本，笔记簿；手册','/ˈnəʊtˌbʊk/','/ˈnəʊtˌbʊk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bonus','n.奖金；红利；额外津贴','/ˈbəʊ.nəs/','/ˈbəʊ.nəs/','noun',["The employee of the week receives a bonus for his excellent work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drop','v.滴；使降低；使终止；随口漏出n.滴；落下；空投；微量；滴剂','/dɹɒp/','/dɹɑp/','noun',["Put three drops of oil into the mixture.","asked for just a drop more tea; she was thirsty and there wasn''t a drop of water to be found","It doesn''t matter where you''re from; anyone who enjoys the drop is a friend of mine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circus','n.马戏；马戏团','/ˈsɜːkəs/','/ˈsɝkəs/','noun',["The circus will be in town next week.","Oxford Circus in London is at the north end of Regent Street."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amount','v.总计，合计；相当于；共计；产生…结果n.数量；总额，总数','/əˈmaʊnt/','/əˈmaʊnt/','noun',["The amount of atmospheric pollution threatens a health crisis.","Pour a small amount of water into the dish.","It amounts to three dollars and change."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bounce','n.跳；弹力；活力v.弹跳；使弹起','/baʊns/','/baʊns/','noun',["Them pro-ballers got bounce!","The tennis ball bounced off the wall before coming to rest in the ditch.","He bounces nervously on his chair."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('married','adj.已婚的，有配偶的；婚姻的，夫妇的；密切结合的n.已婚者v.结婚，与…结婚（marry的过去式）','/ˈmæɹ.ɪd/','/ˈmæɹ.id/','noun',["married to one''s work.","Neither of her daughters showed any desire to marry.","His daughter was married some five years ago to a tailor''s apprentice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('none','pron.没有人；一个也没有；没有任何东西adj.没有的，一点没有的adv.决不，一点也不n.(None)人名；(葡、罗)诺内；(日)野根(姓)','/nɒn/','/nɒn/','noun',["I felt none the worse for my recent illness.","He was none too pleased with the delays in the program that was supposed to be his legacy.","None of this meat tastes right."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrive','v.到达；成功；达成；出生n.(Arrive)人名；(法)阿里夫','/əˈɹaɪv/','/əˈɹaɪv/','verb',["He arrived home for two days.","He had finally arrived on Broadway.","The time has arrived for us to depart."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steady','adj.稳定的；不变的；沉着的v.稳固adv.稳定地；稳固地n.关系固定的情侣；固定支架','/ˈstɛdi/','/ˈstɛdi/','noun',["Hold the ladder steady while I go up.","a man steady in his principles, in his purpose, or in the pursuit of an object","a steady ride"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('museum','n.博物馆','/mjuːˈziːəm/','/mjuˈzi.əm/','noun',[]);
