INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headache','n.头痛；麻烦；令人头痛之事','/ˈhɛdeɪk/','/ˈhɛdeɪk/','noun',["The clumsy filing system has been a huge headache."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hopeful','adj.有希望的；有前途的n.有希望成功的人','/ˈhəʊpfəl/','/ˈhəʊpfəl/','noun',["Several presidential hopefuls are campaigning in New Hampshire this week.","I am hopeful that I will recover from the disease."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('event','n.事件，大事；项目；结果','/əˈvɛnt/','/əˈvɛnt/','noun',["I went to an event in San Francisco last week.","In the event, he turned out to have what I needed anyway."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ache','v.疼痛；渴望n.疼痛','/eɪk/','/eɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heavily','adv.沉重地；猛烈地；沉闷地','/ˈhɛvɪli/','/ˈhɛvɪli/','adverb',["He clomped heavily up the stairs in his boots.","heavily burdened","He drank heavily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warning','n.警告；预兆；预告adj.警告的；引以为戒的v.警告（warn的ing形式）','/ˈwɔːnɪŋ/','/ˈwɔɹnɪŋ/','verb',["Don''t let me catch you running in the corridor again, I warn you.","A sign warns trespassers off/away from the site.","The boss gave him a warning that he would be fired if he did not desist from his behaviour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('form','n.形式，形状；形态，外形；方式；表格v.构成，组成；排列，组织；产生，塑造','/fɔːm/','/fɔɹm/','noun',["To apply for the position, complete the application form.","The orchestra was on top form this evening.","participial forms;  verb forms"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outspoken','adj.坦率的，直言不讳的','','','verb',["an outspoken man"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hungry','adj.饥饿的；渴望的；荒年的；不毛的','/ˈhʌŋ.ɡɹi/','/ˈhʌŋ.ɡɹi/','adjective',["My kids go to bed hungry every night because I haven''t got any money.","a hungry soil"]);
