INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rugby','n.英式橄榄球；拉格比（英格兰中部的城市）','/ˈɹʌɡbi/','/ˈɹʌɡbi/','noun',["The scrum is a distinctive element of rugby."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lamb','n.羔羊，小羊；羔羊肉v.生小羊，产羔羊','/læm/','/læm/','noun',["The shepherd was up all night, lambing her young ewes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cream','n.奶油，乳脂；精华；面霜；乳酪','/kɹiːm/','/kɹiːm/','noun',["Take 100 ml of cream and 50 grams of sugar…","the cream of the crop;  the cream of a collection of books or pictures","You look really sunburnt; you should apply some cream."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fond','adj.喜欢的；温柔的；宠爱的n.(Fond)人名；(法)丰；(瑞典)丰德','/fɒnd/','/fɑnd/','verb',["a fond farewell","I have fond grandparents who spoil me."]);
