INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fun','n.乐趣；玩笑；有趣的人或事adj.供娱乐用的vi.开玩笑','/fʊn/','/fʌn/','noun',["Hey, don''t get bent out of shape over it; I was just funning you.","He is such a fun person to be with.","This year''s fashion style is much more fun than recent seasons."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vain','adj.徒劳的；自负的；无结果的；无用的','/veɪn/','/veɪn/','adjective',["vain toil;  a vain attempt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('service','n.服务，服侍；服役；仪式adj.服务性的；耐用的；服现役的v.维修，检修；保养','/ˈsɜːvɪs/','/ˈsɜːvɪs/','noun',["I say I did him a service by ending our relationship – now he can freely pursue his career.","Hair care is a service industry.","This machine provides the name service for the LAN."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stainless','adj.不锈的；纯洁的，未被玷污的；无瑕疵的','','','noun',[]);
