INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('too','adv.太；也；很；还；非常；过度','/tuː/','/tu/','adverb',["There has been a cutback in federal subsidies. Too, rates have been increasing.","She doesn''t talk too much.  I''m not too sure about this.","\"You''re not old enough yet.\"  \"I am, too!\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nine','n.九，九个num.九；九个adj.九的，九个的','/naɪn/','/naɪn/','noun',["They guaranteed that our Web site would have 99.99% uptime, or four nines.","A cat has nine lives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perform','v.执行；完成；演奏','/pəˈfɔːm/','/pɚˈfɔɹm/','verb',["It took him only twenty minutes to perform the task.","She will perform in the play."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doubt','n.怀疑；疑问；疑惑v.怀疑；不信；恐怕；拿不准','/dʌʊt/','/daʊt/','noun',["I have doubts about how to convert this code to JavaScript.","He doubted that was really what you meant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digest','v.消化；吸收；融会贯通n.文摘；摘要','/daɪˈdʒɛst/','/daɪˈdʒɛst/','verb',["to digest laws","I just ate an omelette and I''m waiting for it to digest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('while','conj.虽然；然而；当……的时候n.一会儿；一段时间v.消磨；轻松地度过','/waɪl/','/waɪl/','noun',["He lectured for quite a long while.","He was sleeping while I was singing.","This case, while interesting, is a bit frustrating."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pretty','adj.漂亮的；可爱的；优美的adv.相当地；颇n.有吸引力的事物（尤指饰品）；漂亮的人','/ˈpɹɪti/','/ˈpɝti/','noun',["We''ll stop at the knife store and look at the sharp pretties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('studio','n.工作室；[广播][电视]演播室；画室；电影制片厂','/ˈstjuːdiəʊ/','/ˈstudioʊ/','noun',["His studio was cramped when he began as an artist.","As he gained a reputation, he took larger space and took students into his studio,","The recording studio had some slight echo, but was good enough to make a demo."]);
