INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('schoolmate','n.同学；同窗','','','noun',["I''ve lost touch with all my old schoolmates: I only see them at class reunions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adult','adj.成年的；成熟的n.成年人','/əˈdʌlt/','/əˈdʌlt/','noun',["an adult human, animal, or plant","adult clothes","This program contains adult content. Parental discretion is advised."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miss','n.女士，小姐，年轻未婚女子','/mɪs/','/mɪs/','noun',["I think I’ll give the meeting a miss.","I missed the target.","to miss an opportunity"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hobby','n.嗜好；业余爱好','/ˈhɒ.bi/','/ˈhɒ.bi/','noun',["I like to collect stamps from different countries as a hobby."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disagree','v.不同意；不一致；争执；不适宜','/dɪsəˈɡɹiː/','/dɪsəˈɡɹiː/','verb',["Bob says cats are friendlier than dogs, but I disagree.","My results in the laboratory consistently disagree with yours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bound','adj.有义务的；必定的；受约束的；装有封面的v.束缚；使跳跃n.范围；跳跃','/ˈbaʊnd/','/ˈbaʊnd/','verb',["Just to make the cheese more binding","I wish I knew why the sewing machine binds up after I use it for a while.","These are the ties that bind."]);
