INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convenience','n.便利；厕所；便利的事物','/kənˈviːnɪəns/','/kənˈvinjəns/','noun',["Fast food is popular because of its cost and convenience.","We will come over and begin the work at your convenience.","These are equally viable times and I propose we alternate between the two times in order to convenience as many people as possible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('who','pron.谁；什么人','/huː/','/huː/','noun',["I don''t know who it is. (indirect question)","I don''t like what you did, but who am I to criticize you? I''ve done worse.","It was a nice man who helped us."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arm','n.手臂；武器；袖子；装备；部门v.武装起来','/ɑːm/','/ɑɹm/','noun',["She stood with her right arm extended and her palm forward to indicate “Stop!”","The arm and forearm are parts of the upper limb in the human body.","the arms of an octopus"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goods','n.商品；动产；合意的人；真本领','/ɡʊdz/','/ɡʊdz/','noun',["The best is the enemy of the good."]);
