INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bottle','n.瓶子；一瓶的容量v.控制；把…装入瓶中','/ˈbɒ.təl/','/ˈbɑ.təl/','noun',["Beer is often sold in bottles.","I only drank a bottle of beer.","The baby wants a bottle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('literary','adj.文学的；书面的；精通文学的','/ˈlɪt(ə)ɹi/','/ˈlɪtəɹɛ(ə)ɹi/','adjective',["a literary history","a literary man"]);
