INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wallet','n.钱包，皮夹','/ˈwɒlɪt/','/ˈwɒlɪt/','noun',["The thief stole all the money and credit cards out of the old man''s wallet.","It''s unknown if the pro running back''s recent sex scandal will hit him in the wallet or not.","I won an auction online for a cheap CD wallet."]);
