INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abortion','n.流产，堕胎，小产；流产的胎儿；（计划等）失败，夭折','/əˈbɔɹ.ʃn̩/','/əˈbɔɹ.ʃn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sparrow','n.麻雀；矮小的人','/ˈspæɹəʊ/','/ˈspæɹoʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bond','n.债券；结合；约定；粘合剂；纽带v.结合，团结在一起','/bɒnd/','/bɑnd/','noun',["Investors face a quandary. Cash offers a return of virtually zero in many developed countries; government-bond yields may have risen in recent weeks but they are still unattractive. Equities have suffered two big bear markets since 2000 and are wobbling again. It is hardly surprising that pension funds, insurers and endowments are searching for new sources of return.","The prisoner was brought before the tribunal in iron bonds.","They had grown up as friends and neighbors, and not even vastly differing political views could break the bond of their friendship."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('face','n.脸；表面；面子；面容；外观；威信v.向；朝','/feɪs/','/feɪs/','noun',["That girl has a pretty face.","Why the sad face?","Children! Stop making faces at each other!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wound','n.创伤，伤口v.使受伤','/wuːnd/','/wund/','noun',["It took a long time to get over the wound of that insult.","The police officer wounded the suspect during the fight that ensued.","The actor''s pride was wounded when the leading role went to his rival."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mustard','n.芥末；芥菜；深黄色；强烈的兴趣','[ˈmɐs.təd]','[ˈmɐs.təd]','noun',["When the waitress brought the food, I asked whether she had any Dijon mustard.","Mustard and cress sandwiches."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ruler','n.尺；统治者；[测]划线板，划线的人','/ˈɹuːlə(ɹ)/','/ˈɹulɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('umbrella','n.雨伞；保护伞；庇护；伞形结构','/ʌmˈbɹɛlə/','/ʌmˈbɹɛlə/','noun',["Quick, grab that umbrella before you get rained on!","The fighters provide a defensive air umbrella over the battle group.","The test facility was established under the umbrella of the company''s quality program."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pub','n.酒馆；客栈','/pʊb/','/pʌb/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('playground','n.运动场，操场；游乐场','/ˈpleɪɡɹaʊnd/','','noun',["The exclusive tropical island was a millionaire''s playground."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arbitrary','adj.[数]任意的；武断的；专制的','/ˈɑɹ.bɪ.tɹɛ(ə).ɹi/','/ˈɑɹ.bɪ.tɹɛ(ə).ɹi/','noun',["Benjamin Franklin''s designation of \"positive\" and \"negative\" to different charges was arbitrary.","The equation is true for an arbitrary value of x."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turning','n.转向；旋转；回转；转弯处v.旋转（turn的ing形式）','[ˈtɜː.nɪŋ]','[ˈtɝ.nɪŋ]','verb',["They say they can turn the parts in two days.","We turned a pretty penny with that little scheme.","Ivory turns well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('account','n.账户；解释；账目，账单；理由；描述v.解释；导致；报账','/ə.ˈkaʊnt/','/ə.ˈkaʊnt/','noun',["to keep one''s account at the bank.","No satisfactory account has been given of these phenomena.","Don''t trouble yourself on my account."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quite','adv.很；相当；完全','/kwaɪt/','/kwaɪt/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wake','v.醒来；唤醒；警觉n.尾迹；守夜；守丧','/ˈweɪk/','/ˈweɪk/','noun',["I woke up at four o''clock this morning.","The neighbour''s car alarm woke me from a strange dream.","Command unto the guards that they diligently wake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('workmate','n.同事；工友','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('album','n.相簿；唱片集；集邮簿；签名纪念册','/ˈælbəm/','/ˈælbəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dangerous','adj.危险的','/ˈdeɪnd͡ʒ(ə)ɹəs/','/ˈdeɪnd͡ʒ(ə)ɹəs/','adjective',["Railway crossings without gates are highly dangerous."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replace','v.取代，代替；替换，更换；归还，偿还；把…放回原处','/ɹɪˈpleɪs/','/ɹɪˈpleɪs/','verb',["When you''ve finished using the telephone, please replace the handset.","You can take what you need from the petty cash, but you must replace it tomorrow morning.","I replaced my car with a newer model."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eyesight','n.视力；目力','/ˈaɪˌsaɪt/','/ˈaɪˌsaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tremble','v.发抖；战栗；焦虑；摇晃n.颤抖；战栗；摇晃','/ˈtɹɛmbl̩/','/ˈtɹɛmbl̩/','noun',["Her lip started to tremble as she burst into tears"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cage','n.笼，兽笼；牢房，监狱v.把…关进笼子；把…囚禁起来','/keɪdʒ/','/keɪdʒ/','noun',["The most dangerous prisoners are locked away in a cage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('either','adj.两者之中任一的；两者之中每一的prep.任何一个conj.也（用于否定句或否定词组后）；根本pron.任一，两方，随便哪一个；两者中的一个或另一个','/ˈaɪð.ə(ɹ)/','/ˈaɪð.ə(ɹ)/','adverb',["I don''t like him, and I don''t like her either.","He made me two offers, but I did not accept either.","Either you eat your dinner or you go to your room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lucky','adj.幸运的；侥幸的','/ˈlʌki/','/ˈlʌki/','adjective',["The downed pilot is very lucky to be alive.","a lucky cast"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('order','n.命令；顺序；规则；[贸易]定单v.命令；整理；定购','/ˈɔːdə/','/ˈɔɹdɚ/','noun',["The house is in order; the machinery is out of order.","to preserve order in a community or an assembly","St. Ignatius Loyola founded the Jesuit order in 1537."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('south','n.南方，南边；南部adv.在南方，向南方adj.南的，南方的','/saʊθ/','/saʊθ/','noun',["The moon souths at nine.","south highway 1"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mobile','adj.可移动的；机动的；易变的；非固定的n.运动物体','/ˈməʊbaɪl/','/ˈməʊbaɪl/','noun',["there are many business opportunities in mobile","a mobile home","mobile internet"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('door','n.门；家，户；门口；通道','/dɔː/','/dɔɹ/','noun',["I knocked on the vice president''s door","the 24 doors in an Advent calendar","Learning is the door to wisdom."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('list','n.[计]列表；清单；目录v.列于表上','/lɪst/','/lɪst/','noun',["to list a door","to list a board"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('videophone','n.电视电话','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empty','adj.空的；无意义的；无知的；徒劳的v.使失去；使…成为空的n.空车；空的东西','/ˈɛmpti/','/ˈɛmpti/','noun',["Put the empties out to be recycled.","The cinema emptied quickly after the end of the film.","Salmon River empties on the W shore about 2 miles below Bear River."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('armchair','n.扶手椅，单人沙发adj.不切实际的','/ˈɑː(ɹ)mtʃɛə(ɹ)/','/ˈɑɹmtʃɛɚ/','noun',["These days I''m an armchair detective.","After the American football game, the armchair quarterbacks talked about what they would have done differently to win, if they had been star athletes instead of out-of-shape old men."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('self','n.自己，自我；本质；私心adj.同一的vt.使自花授精；使近亲繁殖vi.自花授精','/sɛlf/','/sɛlf/','noun',["one''s true self; one''s better self; one''s former self","a self bow: one made from a single piece of wood","This argument was put forward by the defendant self."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nature','n.自然；性质；本性；种类','/ˈneɪtʃə/','/ˈneɪtʃɚ/','noun',["Nature never lies (i.e. tells untruths)."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transparent','adj.透明的；显然的；坦率的；易懂的','/tɹæn(t)sˈpæɹənt/','/tɹæn(t)sˈpæɹənt/','adjective',["The waters of the lake were transparent until the factory dumped waste there.","His reasons for the decision were transparent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submit','v.使服从；主张；呈递','/səbˈmɪt/','/səbˈmɪt/','verb',["They will not submit to the destruction of their rights.","I submit these plans for your approval."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agriculture','n.农业；农耕；农业生产；农艺，农学','/ˈæɡɹɪˌkʌltʃə/','/ˈæɡɹɪˌkʌltʃɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exactly','adv.恰好地；正是；精确地；正确地','/ɪɡˈzæk(t)li/','/ɪɡˈzæk(t)li/','adverb',["He divided the coins exactly in half.","He did it that way exactly to prove the point.","So you''re saying that we have only three days left? — Yes, exactly!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undo','v.取消；解开；破坏；扰乱','/ʌnˈduː/','/ʌnˈduː/','noun',["How many undos does this program support?","Fortunately, we can undo most of the damage to the system by the war.","Could you undo my buckle for me?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheerful','adj.快乐的；愉快的；高兴的','/ˈt͡ʃɪəfəl/','/ˈt͡ʃɪɹfəl/','adjective',["They enjoyed a cheerful room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remind','v.提醒；使想起','/ɹəˈmaɪnd/','/ɹəˈmaɪnd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disaster','n.灾难，灾祸；不幸','/dɪˈzæs.tə/','/dɪˈzæs.tɚ/','noun',["People would suffer disasters when society''s morality degenerates."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('daily','adj.日常的；每日的n.日报；朝来夜去的女佣adv.日常地；每日；天天','/ˈdeɪli/','/ˈdeɪli/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheers','v.感谢；谢谢；再见','/tʃɪəz/','/tʃɪɹz/','noun',["a table loaded with good cheer","A cheer rose from the crowd.","We were cheered by the offer of a cup of tea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('season','n.时期；季节；赛季v.给…调味；使适应','/ˈsiːzən/','/ˈsizən/','noun',["mating season","The third season of Friends aired from 1996 to 1997.","to season oneself to a climate"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dislike','v.不喜欢，厌恶n.嫌恶，反感，不喜爱','/dɪsˈlaɪk/','/dɪsˈlaɪk/','noun',["Tell me your likes and dislikes.","Rebecca Black''s \"Friday\" video has gained notoriety for being one of the most disliked videos in YouTube history."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('software','n.软件','/ˈsɑftˌwɛɹ/','/ˈsɔftˌwɛɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steel','n.钢铁；钢制品；坚固v.钢化；使冷酷adj.钢制的；钢铁业的；坚强的','/stiːl/','/stiːl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('industry','n.产业；工业；勤勉','/ˈɪndəstɹi/','/ˈɪndəstɹi/','noun',["Over the years, their industry and business sense made them wealthy.","The software and tourism industries continue to grow, while the steel industry remains troubled.","There used to be a lot of industry around here, but now the economy depends on tourism."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('there','adv.在那里；在那边；在那点上int.你瞧n.那个地方','/ðɛə(ɹ)/','/ðɛəɹ/','noun',["You rinse and de-string the green beans; I''ll take it from there.","He did not stop there, but continued his speech.","Is there an answer?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('botany','n.植物学；地区植物总称','/-ɪ/','/-ɪ/','noun',["the botany of Greenland"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unfortunately','adv.不幸地','/ʌnˈfɔːtjʊnətli/','/ʌnˈfɔɹt͡ʃənɪtli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gain','n.增加；利润；收获v.获得；增加；赚到','/ɡeɪn/','/ɡeɪn/','noun',["Looks like you''ve gained a new friend.","The sick man gains daily.","to gain a battle; to gain a case at law"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('together','adv.一起；同时；相互；连续地；总共adj.新潮的；情绪稳定的，做事有效率的','/təˈɡɛð.ə(ɹ)/','/təˈɡɛðɚ/','adjective',["He''s really together.","We went to school together.","He put all the parts together."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visit','n.访问；参观；逗留v.访问；参观；视察','/ˈvɪzɪt/','/ˈvɪzɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gather','v.收集；收割；使…聚集；使…皱起n.聚集；衣褶；收获量','/ˈɡæðə/','/ˈɡæðɚ/','noun',["I''ve been gathering ideas from the people I work with.","She gathered the shawl about her as she stepped into the cold.","From his silence, I gathered that things had not gone well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('over','adv.结束；越过；从头到尾prep.越过；在…之上；遍于…之上adj.结束的；上面的vt.越过n.(Over)人名；(俄、西、土)奥韦尔','/ˈəʊ.və(ɹ)/','/ˈoʊ.vɚ/','noun',["He overed the fence in good style.","The cattle have been overing all day because of the flies.","The show is over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('madam','n.夫人；女士；鸨母','/ˈmæd.əm/','/ˈmæd.əm/','noun',["Later, Mrs Grey was sitting in her favourite tea shop. “Would madam like the usual cream cakes and patisserie with her tea?” the waitress asked.","Selina kept pushing and shoving during musical chairs. The nursery school teacher said she was a bad-tempered little madam.","After she grew too old to work as a prostitute, she became a madam."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recreation','n.娱乐；消遣；休养','/ɹɛkɹiˈeɪʃən/','/ɹɛkɹiˈeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dive','v.潜水；跳水；俯冲；急剧下降n.潜水；跳水；俯冲；扑','/ˈdaɪv/','/ˈdaɪv/','noun',["the dive of a hawk after prey","to dive into home plate","She dove right in and started making improvements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wing','n.翼；翅膀；飞翔；派别；侧厅，耳房，厢房v.使飞；飞过；空运；增加…速度；装以翼','/wɪŋ/','/wɪŋ/','noun',["to take wing","the west wing of the hospital","Tom''s a 4 on the Enneagram, with a 3 wing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lemon','adj.柠檬色的n.柠檬','/ˈlɛmən/','/ˈlɛmən/','noun',["He didn’t realise until he’d paid for it that the car was a lemon.","A thousand quid for that motor? Do me a lemon, I could get it for half that.","You can start the vegetables cooking while you are lemoning the fish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('record','v.记录，记载；标明；将录音n.档案，履历；唱片；最高纪录adj.创纪录的','/ˈɹɛkɔːd/','/ˈɹɛkɚd/','noun',["The person had a record of the interview so she could review her notes.","We have no record of you making this payment to us.","The heat and humidity were both new records."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beach','n.海滩；湖滨v.将…拖上岸','/biːt͡ʃ/','/bit͡ʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chairwoman','n.女主席；女议长','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basement','n.地下室；地窖','/ˈbeɪsmənt/','/ˈbeɪsmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('schedule','v.安排，计划；编制目录；将……列入计划表n.时间表；计划表；一览表','/ˈskɛ.dʒu.əl/','/ˈskɛ.dʒu.əl/','noun',["schedule of tribes","stick to the schedule","I''ll schedule you for three-o''clock then."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wood','n.木材；木制品；树林vi.收集木材vt.植林于；给…添加木柴','/wʊd/','/wʊd/','noun',["There was lots of wood on the beach.","Teak is much used for outdoor benches, but a number of other woods are also suitable, such as ipé, redwood, etc.","He got lost in the woods beyond Seattle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deaf','adj.聋的','/diːf/','/diːf/','noun',["Those people are deaf to reason.","a deaf nut; deaf corn"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('architect','n.建筑师','/ˈɑːkɪtɛkt/','/ˈɑɹkɪtɛkt/','noun',["Plato made the causes of things to be matter, ideas, and an efficient architect.","Peisistratus was the first architect of the Iliad and the Odyssey.","He architected the military coup against the government."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('walnut','n.胡桃；胡桃木adj.胡桃科植物的','/ˈwɔːlnʌt/','/ˈwɑlnət/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Irish','adj.爱尔兰的；爱尔兰人的n.爱尔兰人；爱尔兰语；爱尔兰','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manner','n.方式；习惯；种类；规矩；风俗','/ˈmænə/','/ˈmænɚ/','noun',["His natural manner makes him seem like the boss.","These people have strange manners.","It is in a manner done already."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twin','v.使成对n.双胞胎中一人adj.双胞胎的','/twɪn/','/twɪn/','noun',["Coventry twinned with Dresden as an act of peace and reconciliation, both cities having been heavily bombed during the war."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('powerful','adj.强大的；强有力的adv.很；非常','/ˈpaʊəfl/','/ˈpaʊɚfəl/','adjective',["Not very many (of them) had been damaged.","He was the very best runner there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frequent','adj.频繁的；时常发生的；惯常的v.常到，常去；时常出入于','/ˈfɹiː.kwənt/','/ˈfɹiː.kwənt/','adjective',["I am a frequent visitor to that city."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dam','v.控制；筑坝n.[水利]水坝；障碍','/dæm/','/dæm/','noun',["A dam is often an essential source of water to farmers of hilly country.","Boats may only be used at places set aside for boating on the dam."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('free','adj.免费的；自由的，不受约束的；[化学]游离的v.使自由，解放；释放adv.自由地；免费n.(Free)人名；(英)弗里','/fɹiː/','/fɹiː/','noun',["He was given free rein to do whatever he wanted.","It''s free real estate.","We had a wholesome, filling meal, free of meat.  I would like to live free from care in the mountains."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ninety','n.九十adj.九十的；九十岁的num.九十','/ˈnaɪn.ti/','/ˈnaɪn.di/','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fright','n.惊吓；惊骇v.使惊恐','','/fɹaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snake','n.蛇；阴险的人v.迂回前进','/ˈsneɪk/','/ˈsneɪk/','noun',["The path snaked through the forest.","He snaked my DVD!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('version','n.版本；译文；倒转术','/ˈvɜːʃən/','/ˈvɝʒən/','noun',["It''s only in the King James Version of the Bible.","He gave another version of the affair.","Upgrade to the latest version for new features and bug fixes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disabled','adj.残废的，有缺陷的v.使…失去能力（disable的过去分词）','[dɪsˈeɪbəɫd]','[dɪsˈeɪbəɫd]','verb',["Falling off the horse disabled him.","The pilot had to disable the autopilot of his airplane."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('march','v.（坚定地向某地）前进；行军，进军；游行示威；进展，进行n.行进，前进；行军；游行示威；进行曲','/mɑːtʃ/','/mɑɹtʃ/','noun',["the march of time"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('truth','n.真理；事实；诚实；实质','/tɹuːθ/','/tɹuːθ/','noun',["The truth is that our leaders knew a lot more than they were letting on.","There was some truth in his statement that he had no other choice.","Truth to one''s own feelings is all-important in life."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heel','n.脚后跟；踵v.倾侧','/hiːl/','/hiːl/','noun',["He drove the heel of his hand into the man''s nose.","the heel of a mast","She called to her dog to heel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furnished','adj.家具，有家具的v.供应；装备（furnish的过去分词）','/ˈfɜːnɪʃt/','/ˈfɝnɪʃt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nest','n.巢，窝；安乐窝；温床v.筑巢；嵌套','/nɛst/','/nɛst/','noun',["That nightclub is a nest of strange people!","I am aspiring to leave the nest.","I was forced to change trumps when I found the ace, jack, and nine of diamonds in the nest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conclude','v.推断；决定，作结论；结束','/kən.ˈkluːd/','/kən.ˈkluːd/','verb',["The story concluded with a moral.","to conclude a bargain","From the evidence, I conclude that this man was murdered."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basin','n.水池；流域；盆地；盆','/ˈbeɪsɪn/','/ˈbeɪsɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pear','n.[园艺]梨树；梨子','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awkward','adj.尴尬的；笨拙的；棘手的；不合适的','/ˈɑkwɚd/','/ˈɔkwɚd/','noun',["John was awkward at performing the trick. He''ll have to practice to improve.","An awkward silence had fallen.","I''m very awkward at parties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stopwatch','n.码表；跑表vt.用秒表测定时间','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shame','n.羞耻，羞愧；憾事，带来耻辱的人v.使丢脸，使羞愧','/ʃeɪm/','/ʃeɪm/','noun',["The teenager couldn’t bear the shame of introducing his parents.","It was a shame not to see the show after driving all that way.","Shame, you poor thing, you must be cold!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiz','n.考查；恶作剧；课堂测验v.挖苦；张望；对…进行测验','/kwɪz/','/kwɪz/','noun',["We came second in the pub quiz."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forty','n.四十adj.四十的；四十个的','/ˈfɔɹti/','/ˈfɔɹti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clumsy','adj.笨拙的','/ˈklʌmzi/','/ˈklʌmzi/','noun',["He''s very clumsy. I wouldn''t trust him with carrying the dishes.","It is a clumsy solution, but it might work for now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ground','n.地面；土地；范围；战场;根据v.使接触地面；打基础；使搁浅adj.土地的；地面上的；磨碎的；磨过的','/ɡɹaʊnd/','/ɡɹaʊnd/','noun',["Look, I found a ten dollar bill on the ground!","The fox escaped from the hounds by going to ground.","He could not come on grounds of health, or on health grounds."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('show','v.显示；说明；演出；展出n.显示；表演；炫耀','/ʃəʊ/','/ʃoʊ/','noun',["art show;  dog show","radio show;  television show","Let''s catch a show."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rebuild','v.重建；改造，重新组装；复原','/ˈɹiːbɪld/','/ˈɹiːbɪld/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('politician','n.政治家，政客','/ˈpɒl.ɪ.tɪʃ.ən/','/pɑl.ɪˈtɪʃ.ən/','noun',["Politicians should serve the country''s interest.","Unlike the other candidates, I''m not a politician.","Only real politicians are interested in this issue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('north','n.北，北方adj.北方的；朝北的adv.在北方，向北方','/nɔːθ/','/noɹθ/','noun',["Minnesota is in the north of the USA.","Stock prices are heading north.","He lived in north Germany."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rat','n.鼠；卑鄙小人，叛徒v.捕鼠；背叛，告密','/ɹæt/','/ɹæt/','noun',["What a rat, leaving us stranded here!","He loved hockey and was a devoted rink rat.","Get your rat out."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nor','conj.也不；也不是adv.也不；也没有n.(Nor)人名；(中)挪(广东话·威妥玛)；(马来、俄)诺尔；(柬)诺','/nɔː/','/nɔːɹ/','conjunction',["Nor did I stop to think, but ran.","I am neither hungry nor thirsty nor tired.","The struggle didn''t end, nor was it any less diminished."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('captain','n.队长，首领；船长；上尉；海军上校v.指挥；率领','/-tən/','/ˈkæp.tən/','noun',["The captain is the last man to leave a sinking ship.","John Henry said to the captain, \"A man ain''t nothing but a man.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cautious','adj.谨慎的；十分小心的','/ˈkɔːʃəs/','/ˈkɔːʃəs/','adjective',["He took a few cautious steps toward the cave."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guest','n.客人，宾客；顾客v.款待，招待adj.客人的；特邀的，客座的','/ɡɛst/','/ɡɛst/','noun',["The guests were let in by the butler.","Guests must vacate their rooms by 10 o''clock on their day of departure.","The guest for the broadcast was a leading footballer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hair','n.头发；毛发；些微vt.除去…的毛发vi.生长毛发；形成毛状纤维adj.毛发的；护理毛发的；用毛发制成的','/hɛə/','/hɛ(ə)ɹ/','noun',["In the western world, women usually have long hair while men usually have short hair.","Internal hairs occur in the flower stalk of the yellow frog lily (Nuphar).","Just a little louder please—turn that knob a hair to the right."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dozen','n.十二个，一打adj.一打的','/ˈdʌzən/','/ˈdʌzən/','noun',["Can I have a dozen eggs, please?","There must have been dozens of examples just on the first page."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certificate','v.发给证明书；以证书形式授权给…；用证书批准n.证书；执照，文凭','','','noun',["The film is certificate 15."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('love','n.恋爱；亲爱的；酷爱；喜爱的事物；爱情，爱意；疼爱；热爱；爱人，所爱之物v.爱，热爱；爱戴；赞美，称赞；喜爱；喜好；喜欢；爱慕','/lʌv/','/lʌv/','noun',["Hello love, how can I help you?","I love my spouse.   I love you!","Mold loves moist, dark places."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('container','n.集装箱；容器','/kənˈteɪnə/','/kənˈteɪnə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flour','n.面粉；粉状物质v.撒粉于；把…磨成粉','/ˈflaʊə/','/ˈflaʊɚ/','noun',["mustard flour","We transplanted the flowers to a larger pot.","The dogwoods are in flower this week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('total','adj.全部的；完全的；整个的v.总数达n.总数，合计','/ˈtəʊ.təl/','/ˈtəʊ.təl/','noun',["A total of £145 was raised by the bring-and-buy stall.","The total of 4, 5 and 6 is 15.","When we totalled the takings, we always got a different figure."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purple','adj.紫色的；帝王的；华而不实的n.紫色；紫袍v.变成紫色','/ˈpɜː(ɹ).pəl/','/ˈpɝpəl/','noun',["to put on the imperial purple","the banded purple"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withdraw','v.撤退；收回；撤消；拉开','/wɪðˈdɹɔː/','/wɪðˈdɹɔː/','verb',["to withdraw false charges"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insist','v.坚持，强调','/ɪnˈsɪst/','/ɪnˈsɪst/','verb',["I insist that my secretary dresses nicely.","I insist that my secretary dress nicely."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('joke','n.玩笑，笑话；笑柄v.开…的玩笑','/dʒəʊk/','/dʒoʊk/','noun',["It was a joke!","The president was a joke.","I didn’t mean what I said — I was only joking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('autonomous','adj.自治的；自主的；自发的','/ɔːˈtɒnəməs/','/ɔˈtɑnəməs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('all','adj.全部的adv.全然地；越发n.全部pron.全部','/ɔːl/','/ɔl/','noun',["She gave her all, and collapsed at the finish line.","The butter is all.","It suddenly went all quiet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('score','n.分数；二十；配乐；刻痕v.获得；评价；划线，刻划；把…记下','/skɔː/','/skɔɹ/','noun',["The player with the highest score is the winner.","The score is 8-1 even though it''s not even half-time!","The test scores for this class were high."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protect','v.保护，防卫；警戒','/pɹəˈtɛkt/','/pɹəˈtɛkt/','verb',["Condoms are designed to protect against sexually-transmitted diseases."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handwriting','n.笔迹；书法；书写；手稿v.亲手写（handwrite的ing形式）','/ˈhændɹaɪtɪŋ/','/ˈhændɹaɪtɪŋ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sing','v.唱歌；歌颂；鸣叫；呼号n.演唱；鸣声；呼啸声','/sɪŋ/','/sɪŋ/','noun',["\"I really want to sing in the school choir,\" said Vera.","to sing somebody to sleep","The air sings in passing through a crevice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deliver','v.交付；发表；递送；释放；给予（打击）；给…接生n.投球','/dɪˈlɪvə(ɹ)/','/dɪˈlɪvɚ/','verb',["deliver a captive from the prison","deliver a package;  deliver the mail","deliver the thief to the police"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meaning','n.意义；含义；意图adj.意味深长的v.意味；意思是（mean的ing形式）','/ˈmiːnɪŋ/','/ˈmiːnɪŋ/','noun',["the meaning of life"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balcony','n.阳台；包厢；戏院楼厅','/ˈbælkəni/','/ˈbælkəni/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hibernation','n.冬眠；过冬；避寒','/ˌhaɪ.bəːˈneɪ.ʃən/','/ˌhaɪ.bəːˈneɪ.ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vase','n.瓶；花瓶','/væes/','/veɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resemble','v.类似，像','/ɹɪˈzɛmb(ə)l/','/ɹɪˈzɛmb(ə)l/','verb',["The twins resemble each other."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cab','n.驾驶室；出租汽车；出租马车v.乘出租马车（或汽车）','/kæb/','/kæb/','noun',["a cab ride"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decision','n.决定，决心；决议','/dɪˈsɪʒən/','','noun',["It is the decision of the court that movies are protected as free speech.","After agonizing deliberations, they finally proceeded with decision.","He has won twice by knockout, once by decision."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('composition','n.作文，作曲，作品；[材]构成；合成物；成分','/ˌkɒmpəˈzɪʃən/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tent','n.帐篷；住处；帷幕v.用帐篷遮盖；使在帐篷里住宿','/tɛnt/','/tɛnt/','noun',["We were camping in a three-man tent.","We’ll be tented at the campground this weekend.","The sheet tented over his midsection."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rewind','n.重绕；倒带器v.倒回；重绕','/ɹiːˈwaɪnd/','/ɹiːˈwaɪnd/','noun',["I meant to pause the picture, but hit the rewind by mistake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conductor','n.导体；售票员；领导者；管理人','/kənˈdʌktɚ/','/kənˈdʌktɚ/','noun',["train conductor; tram conductor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edition','n.版本','/əˈdɪʃən/','/əˈdɪʃən/','noun',["The first edition was soon sold.","The 2014 edition of the Tour de France started in Leeds, Yorkshire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('female','adj.女性的；雌性的；柔弱的，柔和的n.女人；[动]雌性动物','/ˈfiː.meɪl/','/ˈfiː.meɪl/','noun',["female authors, the leading male and female artists, a female bird cooing at a male, intersex female patients, a trans female vlogger","stereotypically female pastimes, an insect with typically female coloration","the female chromosome;   estrogen, the primary female sex hormone, is produced by both females and males"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('determination','n.决心；果断；测定','/dɪˌtɜːmɪˈneɪʃən/','','noun',["Through sheer determination, we managed to escape from the tornado.","a determination of blood to the head","the determination of the level of salt in sea water"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equal','adj.平等的；相等的；胜任的v.等于；比得上n.对手；匹敌；同辈；相等的事物','/ˈiːkwəl/','/ˈiːkwəl/','noun',["This beer has no equal.","Two plus two equals four.","David equaled the water levels of the bottles, so they now both contain exactly 1 liter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('little','adj.小的；很少的；短暂的；小巧可爱的adv.完全不n.少许；没有多少；短时间','/ˈlɪtəl/','/ˈlɪtl̩/','noun',["Can I try a little of that sauce?","This is a little table.","It''s of little importance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hibernate','v.过冬；（动物）冬眠；（人等）避寒','/ˈhaɪbəˌneɪt/','/ˈhaɪbəˌneɪt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pepper','n.胡椒；辣椒；胡椒粉v.加胡椒粉于；使布满','/ˈpɛpə/','/ˈpɛpə/','noun',["Some ballparks have signs saying \"No pepper games\".","After the hailstorm, the beach was peppered with holes.","He liked to pepper his conversation with long words."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glove','n.手套vt.给…戴手套','/ɡlʌv/','/ɡlʌv/','noun',["I wore gloves to keep my hands warm.","Frederico had a great glove, but he couldn''t hit a curveball, so he never broke into the pros.","to throw down the glove, i.e. to offer a challenge; to take up the glove, to accept it"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diary','n.日志，日记；日记簿','/ˈdaɪəɹi/','/ˈdaɪəɹi/','noun',["They kept separate diaries. His was on paper and her diary was on her computer''s hard drive."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('citizen','n.公民；市民；老百姓','/ˈsɪtɪzən/','/ˈsɪtɪsən/','noun',["Diogenes reckoned himself a citizen of the world."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destroy','v.破坏；消灭；毁坏','/dɪˈstɹɔɪ/','/dɪˈstɹɔɪ/','verb',["Hooligans destroy unprovoked.","Smoking destroys the natural subtlety of the palate.","Destroying a rabid dog is required by law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('altogether','adv.完全地；总共；总而言之n.整个；裸体','/ɔː.tuːˈɡɛð.ə(ɹ)/','/ɔl.tuˈɡɛð.ɚ/','adverb',["Altogether, I''m sorry it happened."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contribution','n.贡献；捐献；投稿','/ˌkɒntɹɪˈbjuːʃən/','/ˌkɑntɹɪˈbjuʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decoration','n.装饰，装潢；装饰品；奖章','/ˌdɛkəˈɹeɪʃən/','/ˌdɛkəˈɹeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('view','n.观察；视野；意见；风景v.观察；考虑；查看','/vjuː/','/vjuː/','noun',["a fine view of Lake George","The video was viewed by millions of people.","I view it as a serious breach of trust."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('darkness','n.黑暗；模糊；无知；阴郁','/ˈdɑːknəs/','/ˈdɑɹknɪs/','noun',["The darkness of the room made it difficult to see.","The darkness of her skin betrayed her Mediterranean heritage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bar','n.条，棒；酒吧；障碍；法庭v.禁止；阻拦prep.除……外','/bɑː/','/bɑɹ/','noun',["The window was protected by steel bars.","Ancient Sparta used iron bars instead of handy coins in more valuable alloy, to physically discourage the use of money.","bar of chocolate"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dessert','n.餐后甜点；甜点心','/dɪˈzɜːt/','/dɪˈzɝt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wag','v.摇摆；摇动；饶舌n.摇摆；爱说笑打趣的人','/wæɡ/','/wæɡ/','noun',["The wag of my dog''s tail expresses happiness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vinegar','n.醋','/ˈvɪnəɡə/','/ˈvɪnəɡɚ/','noun',["a range of herb-flavoured vinegars"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('realize','v.实现；认识到；了解；将某物卖得，把(证券等)变成现钱；变卖','/ˈɹɪə.laɪz/','/ˈɹi.ə.laɪz/','verb',["The objectives of the project were never fully realized.","He realized that he had left his umbrella on the train.","to realize large profits from a speculation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhibition','n.展览，显示；展览会；展览品','/ɛksɪˈbɪʃən/','/ɛksɪˈbɪʃən/','noun',["There was an art exhibition on in the town hall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('broadcast','v.播送，播放；（无线电或电视）广播；播撒（种子）n.广播；播音；广播节目adj.广播的','/ˈbɹɑdkæst/','/ˈbɹɔdkæst/','noun',["The DJ was feeling nervous before his first national broadcast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parrot','n.鹦鹉；学舌者，应声虫；机械模仿别人的人v.机械地模仿','/ˈpæɹət/','/ˈpæɹət/','noun',["I bought a wonderful parrot at the pet store.","What kind of a parrot are you? He just said that.","The interviewee merely parroted the views of her tabloid."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debt','n.债务；借款；罪过','/dɛt/','/dɛt/','noun',["I am in your debt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('birdcage','n.鸟笼；鸟笼状物；信号灯；宿舍','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scare','v.惊吓；把…吓跑n.恐慌；惊吓；惊恐adj.（美）骇人的','/skɛə/','/skɛɚ/','noun',["Johnny had a bad scare last night.","a food-poisoning scare"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('where','adv.在哪里pron.哪里conj.在…的地方n.地点','/wɛə(ɹ)/','/wɛəɹ/','noun',["A good article will cover the who, the what, the when, the where, the why and the how.","He asked where I grew up.","Where would we be without our parents?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambulance','n.[车辆][医]救护车；战时流动医院','/ˈæm.bjə.ləns/','/ˈæm.bjə.ləns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('easy','adj.容易的；舒适的adv.不费力地，从容地vi.停止划桨vt.发出停划命令','/ˈiːzi/','/ˈizi/','noun',["Now that I know it''s taken care of, I can rest easy at night.","It''s often easy to wake up but hard to get up.","Rich people live in easy circumstances."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('housework','n.家务事','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concrete','adj.混凝土的；实在的，具体的；有形的v.凝结n.具体物；凝结物','/kɵnˈkɹiːt/','/ˈkɑnkɹiːt/','noun',["The road was made of concrete that had been poured in large slabs.","I hate grass, so I concreted over my lawn.","Fuzzy videotapes and distorted sound recordings are not concrete evidence that bigfoot exists."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sound','v.听（诊）；测量，测…深；使发声；试探；宣告n.声音，语音；噪音；海峡；吵闹；听力范围；[医]探条adj.健全的，健康的；合理的；可靠的；有效彻底的adv.彻底地，充分地','/saʊnd/','/saʊnd/','adjective',["He was safe and sound.","Fred assured me the floorboards were sound.","\"How are you?\" - \"I''m sound.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scientist','n.科学家','/ˈsaɪ.ən.tɪst/','/ˈsaɪ.ən.tɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('construct','v.建造，构造；创立n.构想，概念','/ˈkɒn.stɹʌkt/','/ˈkɒn.stɹʌkt/','noun',["Loops and conditional statements are constructs in computer programming.","Bohr''s theoretical construct of the atom was soon superseded by quantum mechanics.","We constructed the radio from spares."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('get','v.使得；获得；受到；变成n.生殖；幼兽','/ɡɛt/','/ɡɛt/','noun',["I''m going to get a computer tomorrow from the discount store.","He got a severe reprimand for that.","I''ve got a concert ticket for you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tall','adj.高的；长的；过分的；夸大的adv.夸大地n.(Tall)人名；(马里、阿拉伯)塔勒；(芬、罗、瑞典)塔尔；(英)托尔；(土)塔勒','/tɔːl/','/tɑl/','noun',["Being tall is an advantage in basketball."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diploma','n.毕业证书，学位证书；公文，文书；奖状vt.发给…毕业文凭','/dɪˈpləʊmə/','/dɪˈpləʊmə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beside','prep.在旁边；与…相比；和…无关','/bɪˈsaɪd/','/biˈsaɪd/','adverb',["A small table beside the bed","That is beside the point"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('photographer','n.摄影师；照相师','/fəˈtɒɡɹəfə/','/fəˈtɒɡɹəfə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anchor','n.锚；抛锚停泊；靠山；新闻节目主播v.抛锚；使固定；主持节目adj.末棒的；最后一棒的','/ˈæŋ.kə/','/ˈæŋ.kɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('a','n.字母A；第一流的；学业成绩达最高标准的评价符号abbr.[物]安（ampere）','/æɪ/','/eɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('social','adj.社会的，社交的；群居的n.联谊会；联欢会','/ˈsəʊʃəl/','/ˈsoʊ.ʃəl/','noun',["They organized a social at the dance club to get people to know each other.","James is a very social guy; he knows lots of people.","Teresa feels uncomfortable in certain social situations."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('easily','adv.容易地；无疑地','/ˈiː.zə.liː/','/ˈiː.zə.liː/','adverb',["Individuals without a family network are easily controlled.","This is easily the best meal I have eaten."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chess','n.国际象棋，西洋棋','/t͡ʃɛs/','/t͡ʃɛs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strange','adj.奇怪的；陌生的；外行的adv.奇怪地；陌生地，冷淡地n.(Strange)人名；(英)斯特兰奇；(瑞典、塞)斯特朗格','/ˈstɹeɪnd͡ʒ/','/ˈstɹeɪnd͡ʒ/','noun',["He thought it strange that his girlfriend wore shorts in the winter.","I moved to a strange town when I was ten."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sick','adj.厌恶的；病态的；不舒服；渴望的；恶心的；生病的n.病人v.使狗去咬；呕吐；追击','/sɪk/','/sɪk/','noun',["We have to cure the sick.","He lay there in a pool of his own sick.","I woke up at 4 am and sicked on the floor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Russian','adj.俄国的；俄语的n.俄语；俄国人','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inland','n.内地；内陆adj.内陆的；内地的；国内的adv.在内地；向内地；向内陆；在内陆','/ˈɪnlənd/','/ˈɪnlənd/','noun',["an inland town","inland commerce"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('academy','n.学院；研究院；学会；专科院校','/əˈkæd.ə.mi/','/əˈkæd.ə.mi/','noun',["the military academy at West Point; a riding academy; the Academy of Music.; a music academy; a language academy"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invent','v.发明；创造；虚构','/ɪnˈvɛnt/','/ɪnˈvɛnt/','verb',["After weeks of hard work, I invented a new way to alphabetize matchbooks.","I knew I had to invent an excuse, and quickly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wealth','n.财富；大量；富有','/wɛlθ/','/wɛlθ/','noun',["She brings a wealth of knowledge to the project."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chick','n.小鸡；小鸟；少妇adj.胆小的；懦弱的','/t͡ʃɪk/','/t͡ʃɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('companion','n.同伴；朋友；指南；手册v.陪伴','/kəmˈpænjən/','/kəmˈpænjən/','noun',["His dog has been his trusted companion for the last five years.","The companion guide gives an in-depth analysis of this particular translation.","a companion of the Bath"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mouth','n.口，嘴；河口v.做作地说，装腔作势地说；喃喃地说出','/maʊθ/','/maʊθ/','noun',["\"Open your mouth and say ''aah'',\" directed the doctor.","The mouth of the river is a good place to go birdwatching in spring and autumn.","The mouth of a cave"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('find','v.查找，找到；发现；认为；感到；获得n.发现','/faɪnd/','/faɪnd/','noun',["I found my car keys. They were under the couch.","Water is found to be a compound substance.","to find leisure; to find means"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('town','n.城镇，市镇；市内商业区','/taʊn/','/taʊn/','noun',["This town is really dangerous because these youngsters have Beretta handguns.","I''ll be in Yonkers, then I''m driving into town to see the Knicks at the Garden tonight.","Call me when you get to town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trousers','n.裤子，长裤','/ˈtɹaʊzəz/','/ˈtɹaʊzəz/','noun',["The trousers need to be shortened."]);
