INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('petrol','n.（英）汽油','/ˈpɛt.ɹəl/','/ˈpɛt.ɹəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solid','adj.固体的；可靠的；立体的；结实的；一致的n.固体；立方体','/ˈsɒlɪd/','/ˈsɑlɪd/','noun',["I owe him; he did me a solid last year.","I prefer solids over paisleys.","The doctor said I can''t eat any solids four hours before the operation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uncomfortable','adj.不舒服的；不安的','/ʌnˈkʌm.fə.tə.bəl/','/ʌnˈkʌm.fɚ.tə.bəl/','adjective',["The class squirmed and fidgeted in the uncomfortable new chairs.","Sharing a house with them made me uncomfortable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expense','n.损失，代价；消费；开支vt.向…收取费用vi.被花掉','/ɪkˈspɛns/','/ɪkˈspɛns/','noun',["Buying the car was a big expense, but will be worth it in the long run.","Jones reached the final at the expense of Smith, who couldn''t beat him.","It should be acceptable to expense a business lunch with a client."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bowling','n.滚木球戏；保龄球戏v.打保龄球（bowl的现在分词）','/ˈbəʊlɪŋ/','/ˈbəʊlɪŋ/','verb',["We were bowled rapidly along the road."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metre','n.米；公尺；韵律','/ˈmiːtə/','/ˈmiːtəɹ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passage','n.一段（文章）；走廊；通路','/ˈpæsɪd͡ʒ/','/ˈpæsɪd͡ʒ/','noun',["She struggled to play the difficult passages.","He made his passage through the trees carefully, mindful of the stickers.","The company was one of the prime movers in lobbying for the passage of the act."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nearly','adv.差不多，几乎；密切地','/ˈniːɹli/','/ˈnɪɹli/','adverb',["He left a nearly full beer on the bar."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('institute','v.开始（调查）；制定；创立；提起（诉讼）n.学会，协会；学院','/ˈɪnstɪt(j)uːt/','/ˈɪnstɪt(j)uːt/','noun',["I work in a medical research institute."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('draw','v.画；拉；吸引n.平局；抽签','/dɹɔː/','/dɹɔː/','noun',["The game ended in a draw.","The draw is on Saturday.","She had to draw upon her experience to solve the problem."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('as','conj.因为；随着；虽然；依照；当…时prep.如同；当作；以…的身份adv.同样地；和…一样的','','','adverb',["It''s not as well made, but it''s twice as expensive.","1865, The Act of Suicide as Distinct from the Crime of Self-Murder: A Sermon","They''re big as houses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meal','n.一餐，一顿饭；膳食vi.进餐','/miːl/','[miːʟ̩]','noun',["Breakfast is the morning meal, lunch is the noon meal, and dinner, or supper, is the evening meal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sneeze','v.打喷嚏n.喷嚏','/sniːz/','/sniːz/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bit','n.[计]比特（二进位制信息单位）；少量；马嚼子；辅币；老一套；一点，一块vt.控制adj.很小的；微不足道的adv.有点儿；相当','/bɪt/','/bɪt/','noun',["A horse hates having a bit put in its mouth.","a threepenny bit","A quarter is two bits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('but','conj.但是；而是；然而adv.仅仅，只prep.除…以外n.(But)人名；(俄、罗)布特；(越)笔','/bʊt/','','noun',["It has to be done – no ifs or buts.","But me no buts.","Christmas comes  but once a year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monitor','n.监视器；监听器；监控器；显示屏；班长v.监控','/ˈmɒnɨtə/','/ˈmɒnɨtə/','noun',["The camp monitors look after the children during the night, when the teachers are asleep.","The information flashed up on the monitor.","a machine code monitor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thrill','n.激动；震颤；紧张v.使…颤动；使…紧张；使…感到兴奋或激动','[t̪ɾ̪̊ɪl]','[θɾ̪̊ɪɫ]','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advice','n.建议；忠告；劝告；通知','/ədˈvaɪs/','/ædˈvaɪs/','noun',["She was offered various piece of advice on what to do with her new-found wealth.","late advices from France","An advice of an incoming settlement payment order may be given to an off-line receiving bank."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whale','v.猛揍；使惨败n.鲸；巨大的东西','/weɪl/','/weɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacant','adj.空虚的；空的；空缺的；空闲的；茫然的n.(Vacant)人名；(法)瓦康','/ˈveɪkənt/','/ˈveɪkənt/','adjective',["a vacant stare"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underground','adv.在地下；秘密地adj.地下的；秘密的；先锋派的n.地下；地铁；地道；地下组织；秘密活动；先锋派团体','/ˈʌndəɡɹaʊnd/','/ˈʌndəɡɹaʊnd/','noun',["the French underground during World War II","There is an underground tunnel that takes you across the river.","These criminals operate through an underground network."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rocket','v.飞驰，飞快地移动；迅速增加n.火箭','/ˈɹɒkɪt/','/ˈɹɑkɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trial','n.试验；审讯；努力；磨炼adj.试验的；审讯的','/ˈtɹaɪəl/','/ˈtɹaɪəl/','noun',["They will perform the trials for the new equipment next week.","That boy was a trial to his parents.","soccer trials"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Shanghai','n.上海（中国东部港市）','/ˌʃæŋˈhaɪ/','/ˈʃæŋ.haɪ/','noun',["Let''s see if we can shanghai a room for a couple of hours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('root','n.根；根源；词根；祖先v.生根；根除','/ɹuːt/','/ɹuːt/','noun',["This tree''s roots can go as deep as twenty metres underground.","Root damage is a common problem of overbrushing.","The root is the only part of the hair that is alive."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nationwide','adj.全国范围的；全国性的adv.在全国','/ˌneɪ.ʃənˈwaɪd/','/ˌneɪ.ʃənˈwaɪd/','adjective',["There was a nationwide search on for the bankrobbers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hotel','n.旅馆，饭店；客栈vt.使…在饭店下榻vi.进行旅馆式办公','/(h)əʊˈtɛl/','/hoʊˈtɛl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specialist','n.专家；专门医师adj.专家的；专业的','/ˈspɛʃəlɪst/','/ˈspɛʃəlɪst/','noun',["The tree Lepidothamnus laxifolius is a high alpine specialist found in high-altitude bog communities and in scrub."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('any','adj.任何的；所有的；丝毫pron.任何；任何一个；若干adv.稍微；少许n.(Any)人名；(法、罗)阿尼','/ˈæni/','/ˈɛni/','adverb',["I will not remain here any longer.","Any may apply."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirty','n.三十年代num.三十adj.三十个的','/ˈθɜːti/','/ˈθɝti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attractive','adj.吸引人的；有魅力的；引人注目的','/əˈtɹæktɪv/','/əˈtɹæktɪv/','adjective',["That''s a very attractive offer.","He is an attractive fellow with a trim figure."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phenomenon','n.现象；奇迹；杰出的人才','/fɪˈnɒmənɒn/','/fɪˈnɒmənɒn/','noun',["An electromagnetic phenomenon.","A volcanic eruption is an impressive phenomenon."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counter','n.柜台；对立面；计数器；（某些棋盘游戏的）筹码v.反击，还击；反向移动，对着干；反驳，回答adj.相反的adv.反方向地；背道而驰地','/ˈkaʊntə/','/ˈkaʊntə/','noun',["He''s only 16 months, but is already a good counter – he can count to 100.","He rolled a six on the dice, so moved his counter forward six spaces.","He put his money on the counter, and the shopkeeper put it in the till."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scarf','n.围巾；嵌接，嵌接处；头巾领巾v.披嵌接；用围巾围','/skɑːf/','/skɑːf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tail','n.尾巴；踪迹；辫子；燕尾服v.尾随；装上尾巴adj.从后面而来的；尾部的','/teɪl/','/teɪl/','noun',["Most primates have a tail and fangs.","I''m gonna get me some tail tonight.","Tail that car!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swear','v.发誓；咒骂n.宣誓；诅咒','/swɛə/','/swɛɚ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('high','adj.高的；高级的；崇高的；高音调的n.高水平；天空；由麻醉品引起的快感；高压地带adv.高；奢侈地','/haɪ/','/haɪ/','noun',["It was one of the highs of his career.","That pill gave me a high for a few hours, before I had a comedown.","A large high is centred on the Azores."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjustment','n.调整，调节；调节器','/əˈdʒʌst.mənt/','/əˈdʒʌst.mənt/','noun',["The credit card company made an adjustment to my account to waive the late fee.","When Jim graduated, he found adjustment to the working world difficult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rely','v.依靠；信赖','/ɹɪˈlaɪ/','/ɹɪˈlaɪ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deserve','v.应受，应得','/dɪˈzɜːv/','/dɪˈzɝv/','verb',["After playing so well, the team really deserved their win."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mine','n.矿，矿藏；矿山，矿井；地雷，水雷v.开采，采掘；在…布雷pron.我的','/maɪn/','/maɪn/','pronoun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('AIDS','abbr.获得性免疫缺乏综合征；爱滋病（AcquiredImmuneDeficiencySyndrome）','/eɪdz/','/eɪdz/','noun',["He came to my aid when I was foundering.","Slimming aids include dietary supplements and appetite suppressants.","The incompetent general''s brilliant aid often made priceless suggestions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deal','v.处理；给予；分配；发牌n.交易；（美）政策；待遇；份量','/diːl/','/diːl/','noun',["We gave three deals of grain in tribute to the king."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apron','n.围裙；[航]停机坪；舞台口vt.着围裙于；围绕','/ˈeɪ.pɹən/','/ˈeɪ.pɹən/','noun',[]);
