INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquaintance','n.熟人；相识；了解；知道','/əˈkweɪntəns/','/ʌˈkweɪn.təns/','noun',["I know of the man; but have no acquaintance with him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('great','adj.伟大的，重大的；极好的，好的；主要的n.大师；大人物；伟人们','/ɡɹeɪt/','/ɡɹeɪt/','noun',["Newton and Einstein are two of the greats of the history of science.","My three-greats grandmother.","A great storm is approaching our shores."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bandage','n.绷带v.用绷带包扎','/ˈbændɪdʒ/','/ˈbændɪdʒ/','noun',["this new healthcare proposal merely applies a bandage to the current medical crisis"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oral','adj.口头的，口述的n.口试','/ˈɒɹəl/','/ˈɒɹəl/','noun',["We''ve got our Spanish oral tomorrow.","I gave my boyfriend oral for the first time on his birthday.","oral hygiene"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('throw','v.投；抛；掷n.投掷；冒险','/θɹəʊ/','/θɹoʊ/','verb',["What a great throw by the quarterback!","The gambler staked everything on one throw of the dice.","He''s always had a pretty decent throw."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loss','n.减少；亏损；失败；遗失','/lɑs/','/lɔs/','noun',["In other areas, glacier loss creates serious risk of a dry period across the Third Pole, Wang said.","It was a terrible crash; both cars were total losses.","The match ended in their first loss of the season."]);
