INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boil','v.煮沸，沸腾；激动，激昂n.沸腾，煮沸；疖子','/bɔɪl/','/bɔɪl/','noun',[]);
