INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chart','n.图表；海图；图纸；排行榜v.绘制…的图表；在海图上标出；详细计划；记录；记述；跟踪（进展或发展','/tʃɑːt/','/tʃɑɹt/','noun',["Let''s chart how we''re going to get from here to there.","The band first charted in 1994."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shape','n.形状；模型；身材；具体化v.形成；塑造，使成形；使符合','/ʃeɪp/','/ʃeɪp/','noun',["The used bookshop wouldn''t offer much due to the poor shape of the book.","The vet checked to see what kind of shape the animal was in.","He cut a square shape out of the cake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('milk','n.牛奶；乳状物v.榨取；挤…的奶','/mɪlk/','/mɪlk/','noun',["Table three ordered three milks. (Formally: The guests at table three ordered three glasses of milk.)","I take my tea with two milk(s) and two sugar."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('group','n.组；团体adj.群的；团体的v.聚合','/ɡɹuːp/','/ɡɹuːp/','noun',["A group of people gathered in front of the Parliament to demonstrate against the Prime Minister''s proposals.","Did you see the new jazz group?","Nitro is an electron-withdrawing group."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prevent','v.预防，防止；阻止','/pɹəˈvɛnt/','/pɹəˈvɛnt/','verb',["I brush my teeth regularly to prevent them from turning yellow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('associate','v.交往；结交n.同事，伙伴；关联的事物adj.副的；联合的','/əˈsəʊsi.ət/','/əˈsoʊsi.ət/','noun',["She associates with her coworkers on weekends.","He associated his name with many environmental causes.","particles of gold associated with other substances"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plug','n.插头；塞子；栓v.塞住；用插头将与电源接通','/plʌɡ/','/plʌɡ/','noun',["I pushed the plug back into the electrical socket and the lamp began to glow again.","Pull the plug out of the tub so it can drain.","He preferred a plug of tobacco to loose chaw."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detective','adj.侦探的n.侦探','/dɪˈtɛktɪv/','/dɪˈtɛktɪv/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alcohol','n.酒精，乙醇','/ˈæl.kə.hɒl/','/ˈæl.kə.hɑl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offshore','adj.离岸的；[海洋]近海的；吹向海面的adv.向海面，向海','/ɒfˈʃɔː(ɹ)/','/ɒfˈʃɔː(ɹ)/','noun',["an offshore oil rig"]);
