INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jacket','n.羽绒滑雪衫；西装短外套；短上衣，夹克；土豆皮；书籍的护封；文件套，公文夹v.给…穿夹克；给…装护套；给…包上护封；〈口〉打','/ˈd͡ʒæk.ɪt/','/ˈd͡ʒækət/','noun',["Cook the potatoes in their jackets."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('red','n.红色，红颜料；赤字adj.红色的；红肿的，充血的','/ɹɛd/','/ɹɛd/','noun',["The girl wore a red skirt.","Her hair had red highlights.","I got two red queens, and he got one of the black queens."]);
