INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('also','adv.也；而且；同样conj.并且；另外n.(Also)人名；(罗)阿尔索','/ˈɔːl.səʊ/','/ˈɔl.soʊ/','adverb',["They had porridge for breakfast, and also toast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necessary','adj.必要的；必需的；必然的n.必需品','/ˈnɛsəsɹɪ/','/ˈnɛsəˌsɛɹi/','noun',["Although I wished to think that all was false, it was yet necessary that I, who thus thought, must in some sense exist.","If it is absolutely necessary to use public computers, you should plan ahead and forward your e-mail to a temporary, disposable account."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gold','n.金，黄金；金色；金币adj.金的，金制的；金色的','/ɡɒʊld/','/ɡoʊld/','noun',["France has won three golds and five silvers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sympathy','n.同情；慰问；赞同','/ˈsɪmpəθi/','/ˈsɪmpəθi/','noun',["Many people in Hollywood were blacklisted merely because they were suspected of Communist sympathies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tomato','n.番茄，西红柿','[tʰə̥ˈmɑːtʰəʊ]','[tʰə̥ˈmeɪɾoʊ]','noun',["Lookit the legs on that hot tomato!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('create','v.创造，创作；造成','/kɹiːˈeɪt/','/kɹiːˈeɪt/','verb',["You can create the color orange by mixing yellow and red.","A sudden chemical spill on the highway created a chain‐collision which created a record traffic jam.","Henry VIII created him a Duke.   Last month, the queen created two barons."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyhow','adv.总之；无论如何；不管怎样','/ˈæn.i.haʊ/','/ˈæn.i.haʊ/','adverb',["Anyhow, he is dead now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('declare','v.宣布，声明；断言，宣称','/dɪˈkleə/','/dəˈklɛɚ/','verb',["He declared him innocent.","declare bankruptcy","Houghton and Sunderland South was the first constituency to declare in the 2015 general election."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recommend','v.推荐，介绍；劝告；使受欢迎；托付','/ɹɛkəˈmɛnd/','/ɹɛkəˈmɛnd/','verb',["The board recommends Philips, given his ample experience in similar positions.","A city that has much to recommend it.","The therapist recommends resting the mind and exercising the body."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('London','n.伦敦','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('addicted','adj.沉溺于某种（尤其是不良的）嗜好的；入了迷的，上了瘾的v.使…上瘾（addict的过去分词）','/əˈdɪktɪd/','/əˈdɪktɪd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('focus','n.焦点；中心；清晰；焦距v.使集中；使聚焦','/ˈfəʊ.kəs/','/ˈfəʊ.kəs/','noun',["The heat of sunlight at the focus of a magnifying glass can easily set dry leaves on fire.","Unfortunately, the license plate is out of focus in this image.","During this scene, the boy’s face shifts subtly from soft focus into sharp focus."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forget','v.忘记；忽略n.(Forget)人名；(法)福尔热','/fəˈɡɛt/','/fɚˈɡɛt/','verb',["I have forgotten most of the things I learned in school.","I forgot to buy flowers for my wife at our 14th wedding anniversary.","I forgot my car keys."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sailing','n.航行，航海；启航；航海术adj.航行的v.航行，起航（sail的现在分词形式）','/ˈseɪ.lɪŋ/','/ˈseɪ.lɪŋ/','verb',["We sail for Australia tomorrow.","The duchess sailed haughtily out of the room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('serious','adj.严肃的，严重的；认真的；庄重的；危急的','/ˈsɪə.ɹi.əs/','/ˈsɪə.ɹi.əs/','adjective',["It was a surprise to see the captain, who had always seemed so serious, laugh so heartily.","This is a serious problem. We''ll need our best experts.","After all these years, we''re finally getting serious attention."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dad','n.爸爸；爹爹','/dæd/','/dæd/','noun',["His dad was always there for him.","Happy Father''s Day, Dad!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scold','v.责骂；叱责n.责骂；爱责骂的人','/skəʊld/','/skoʊld/','verb',["to scald the hand","Scald the milk until little bubbles form."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacation','n.假期；（房屋）搬出v.休假，度假','/veɪˈkeɪʃ(ə)n/','/veɪˈkeɪʃən/','noun',["The Conservative Party’s vacation of the centre ground gave an opportunity to its opponents.","This year, we’re vacationing in Mexico."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immediate','adj.立即的；直接的；最接近的','/ɪˈmiːdɪət/','/ɪˈmi.di.ət/','adjective',["Computer users these days expect immediate results when they click on a link.","immediate family;  immediate vicinity","Bravo Three, this Bravo Six. Immediate! We are coming under fire from the north from an unknown enemy, over!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('timetable','n.时间表；时刻表；课程表','/ˈtaɪmˌteɪbəl/','/ˈtaɪmˌteɪbəl/','noun',["The timetable has been changed several times since it was first announced.","I''ve timetabled the meeting for Monday afternoon."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recycle','v.使再循环；使…重新利用n.再生；再循环；重复利用','/ɹiˈsaɪkəl/','/ɹiˈsaɪkəl/','noun',["Both paper and plastic can be recycled.","Sulfur recycles in the sulfur cycle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fall','v.落下；变成；来临；减弱n.下降；秋天；瀑布adj.秋天的','/fɔːl/','/fɔl/','noun',["the fall of Rome","He set up his rival to take the fall.","Have the goodness to secure the falls of the mizzen halyards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('join','v.参加；结合；连接n.结合；连接；接合点','/ˈdʒɔɪn/','/ˈdʒɔɪn/','noun',["The plumber joined the two ends of the broken pipe.","Parallel lines never join.","I will join you watching the football game as soon as I have finished my work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pink','n.粉红色；化身，典范；石竹花；头面人物v.扎，刺，戳；使…变粉红色；使…面红耳赤adj.粉红的；比较激进的；石竹科的；脸色发红的','/pɪŋk/','/pɪŋk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('joy','n.欢乐，快乐；乐趣；高兴v.欣喜，欢喜','/dʒɔɪ/','/dʒɔɪ/','noun',["They will be a source of strength and joy in your life.","the joys and demands of parenthood"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('muddy','adj.泥泞的；模糊的；混乱的v.使污浊；使沾上泥；把…弄糊涂','[ˈmʌdi]','[ˈmʌdi]','verb',["If you muddy your shoes don''t wear them inside.","The discussion only muddied their understanding of the subject.","He slogged across the muddy field."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rest','v.使休息，使轻松；把…寄托于n.休息，静止；休息时间；剩余部分；支架','/ɹɛst/','/ɹɛst/','noun',["I need to get a good rest tonight; I was up late last night.","We took a rest at the top of the hill to get our breath back.","It was nice to have a rest from the phone ringing when I unplugged it for a while."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exit','n.出口，通道；退场v.退出；离去','/ˈɛksɪt/','/ˈɛksət/','noun',["He made his exit at the opportune time.","the untimely exit of a respected politician"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headline','n.大标题；内容提要；栏外标题；头版头条新闻v.给…加标题；使成为注意中心；大力宣传','/ˈhɛd.laɪn/','/ˈhɛd.laɪn/','noun',["The headline on today''s newspaper reads \"John Doe Wins Wood-Splitting Competition.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flu','n.流感','/flʉː/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('network','n.网络；广播网；网状物','/nɛtwɜːk/','/nɛtwɝk/','noun',["A network of roads crisscrossed the country.","To get a job in today''s economy, it is important to have a strong network.","The copy machine is connected to the network so it can now serve as a printer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vehicle','n.[车辆]车辆；工具；交通工具；运载工具；传播媒介；媒介物','/ˈvɪː(ə).kəl/','/ˈvi.ə.kəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('task','v.分派任务n.工作，作业；任务','/tɑːsk/','/tæsk/','noun',["The user killed the frozen task.","On my first day in the office, I was tasked with sorting a pile of invoices."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unbearable','adj.难以忍受的；承受不住的','','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rapid','adj.迅速的，急促的；飞快的；险峻的n.急流；高速交通工具，高速交通网','/ˈɹæpɪd/','/ˈɹæpɪd/','noun',["a rapid stream"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concentrate','v.集中；浓缩；全神贯注；聚集n.浓缩，精选；浓缩液','/ˈkɒn.sən.tɹeɪt/','/ˈkɒn.sən.tɹeɪt/','noun',["to concentrate rays of light into a focus","to concentrate acid by evaporation","Population tends to concentrate in cities."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tiresome','adj.烦人的，无聊的；令人讨厌的','/ˈtaɪəsəm/','/ˈtaɪəsəm/','adjective',["Eventually his long stories became tiresome."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('market','n.市场；行情；股票市场；市面；集市；销路；商店v.在市场上出售','/ˈmɑːkɪt/','/ˈmɑɹkɪt/','noun',["The privilege to hold a weekly market was invaluable for any feudal era burgh.","Stop by the market on your way home and pick up some milk","We believe that the market for the new widget is the older homeowner."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burst','v.爆发，突发；爆炸n.爆发，突发；爆炸','/bɜːst/','/bɝst/','noun',["The bursts of the bombs could be heard miles away.","I blew the balloon up too much, and it burst.","I burst the balloon when I blew it up too much."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volcano','n.火山','/vɒlˈkeɪnəʊ/','/vɑlˈkeɪnoʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brush','n.刷子；画笔；毛笔；争吵；与某人有效冲突；灌木丛地带；矮树丛；狐狸尾巴v.刷；画；','/bɹʌʃ/','/bɹʌʃ/','noun',["She gave her hair a quick brush.","He has had brushes with communism from time to time.","donwloading brushes for Photoshop"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motherland','n.祖国；母国','/ˈmʌðɚˌlænd/','/ˈmʌðɚˌlænd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ear','n.耳朵；穗；听觉；倾听vi.（美俚）听见；抽穗','/ɪə̯/','/iɹ/','noun',["a good ear for music","the ears of a tub, skillet, or dish;   The ears of a boat are outside kneepieces near the bow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circuit','n.[电子]电路，回路；巡回；一圈；环道v.环行','[ˈsəɾ.kɪʈ]','[ˈsɝ.kət]','noun',["Having circuited the air."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('in','prep.按照（表示方式）；从事于；在…之内adv.进入；当选；（服装等）时髦；在屋里adj.在里面的；时髦的n.执政者；门路；知情者','/ɪn/','/ɪn/','noun',["His parents got him an in with the company.","Is Mr. Smith in?","Little by little I pushed the snake into the basket, until finally all of it was in."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pin','n.大头针，别针，针；栓；琐碎物v.钉住；压住；将……用针别住','/pɪn/','/pɪn/','noun',["Pull the pin out of the grenade before throwing it at the enemy.","I''m not so good on my pins these days.","The UK standard connector for domestic mains electricity has three pins."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belong','v.属于，应归入；居住；适宜；应被放置','/bɪˈlɒŋ/','/bɪˈlɔŋ/','verb',["Where does this document belong?","That house belongs to me.","Suppose x belongs to \\mathbb{R}...  (— written: x \\in \\mathbb{R})"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brotherhood','n.兄弟关系；手足情谊；四海之内皆兄弟的信念','/ˈbɹʌðəhʊd/','/ˈbɹʌðəhʊd/','noun',["the legal brotherhood"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('music','n.音乐，乐曲','/ˈmjuːzɪk/','/ˈmjuːzɪk/','noun',["I keep listening to this music because it''s a masterpiece."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brother','n.兄弟；同事；战友int.我的老兄！','/ˈbɹʌðə(ɹ)/','/ˈbɹʌðɚ/','noun',["I would like to thank the brother who just spoke.","Listen, brother, I don''t know what you want, but I''m not interested.","We''re being forced to work overtime? Oh, brother!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleasant','adj.令人愉快的，舒适的；讨人喜欢的，和蔼可亲的n.(Pleasant)人名；(英)普莱曾特','/ˈplɛzənt/','/ˈplɛzənt/','noun',["It wasn''t so hot outside, but pleasant enough to have lunch in the garden."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worried','adj.担心的','/ˈwʌɹid/','','adjective',["She was worried about her son who had been sent off to fight in the war.","Stop worrying about your test, it’ll be fine.","Your tone of voice worries me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chicken','n.鸡肉；小鸡；胆小鬼，懦夫adj.鸡肉的；胆怯的；幼小的','/ˈt͡ʃɪkɪn/','/ˈt͡ʃɪkɪn/','noun',["Why do you refuse to fight? Huh, I guess you''re just too chicken."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('argue','v.争论，辩论；提出理由n.(Argue)人名；(英、法)阿格','/ˈɑː.ɡjuː/','/ˈɑɹ.ɡju/','verb',["He also argued for stronger methods to be used against China.","He argued his point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dress','v.给…穿衣n.连衣裙；女装','/dɹɛs/','/dɹɛs/','noun',["Amy and Mary looked very pretty in their dresses.","He came to the party in formal dress.","He was dressed in the latest fashions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convince','v.说服；使确信，使信服','/kənˈvɪns/','/kənˈvɪns/','verb',["I wouldn''t have or do something, unless I''m convinced that it''s good."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reporter','n.记者','/ɹɪˈpɔːtə/','/ɹɪˈpɔɹtɚ/','noun',["The reporters of important security bugs may be paid a bounty by the software developer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sky','n.天空；顶点v.把…投向空中；把…挂得过高','/skaɪ/','/skaɪ/','noun',["That year, a meteor fell from the sky.","I lay back under a warm Texas sky.","This mortal has incurred the wrath of the skies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voluntary','adj.自愿的；志愿的；自发的；故意的n.志愿者；自愿行动','/ˈvɒ.lən.tɹi/','/ˈvɑ.lənˌtɛ.ɹi/','noun',["If a man accidentally kills another by lopping a tree, it is not voluntary manslaughter.","a voluntary church, in distinction from an established or state church"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drug','n.药；毒品；麻醉药；滞销货v.使服麻醉药；使服毒品；掺麻醉药于','/dɹʌɡ/','/dɹʌɡ/','noun',["Aspirin is a drug that reduces pain, acts against inflammation and lowers body temperature.","2010, Kesha Rose Sebert (Ke$ha), with Pebe Sebert and Joshua Coleman (Ammo), Your Love is My Drug","She suddenly felt strange, and only then realized she''d been drugged."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enquiry','n.[计]询问，[贸易]询盘','/ɛnˈkwaɪ.ɹi/','/ɛnˈkwaɪ.ɹi/','noun',["scientific enquiry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dip','v.浸，泡，蘸；舀取；把伸入n.下沉，下降；倾斜；浸渍，蘸湿','/dɪp/','/dɪp/','noun',["There is a dip in the road ahead.","I''m going for a dip before breakfast.","This onion dip is just scrumptious."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cuisine','n.烹饪，烹调法','/kwɪˈziːn/','/kwɪˈziːn/','noun',["French cuisine is considered to be one of the world''s most refined and elegant styles of cooking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('daughter','n.女儿；[遗][农学]子代adj.女儿的；子代的','/ˈdɔːtə(ɹ)/','/ˈdɔ.tɚ/','noun',["I already have a son, so I would like to have a daughter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('product','n.产品；结果；[数]乘积；作品','/ˈpɹɒd.əkt/','/ˈpɹɒd.əkt/','noun',["That store offers a variety of products.  We''ve got to sell a lot of product by the end of the month.","Wash excess product out of your hair.","The product of last month''s quality standards committee is quite good, even though the process was flawed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mixture','n.混合；混合物；混合剂','/ˈmɪkstʃə/','/ˈmɪkstʃɚ/','noun',["A teaspoonful of the mixture to be taken three times daily after meals"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('name','n.名称，名字；姓名；名誉v.命名，任命；指定；称呼；提名；叫出adj.姓名的；据以取名的','/neɪm/','/neɪm/','noun',["I''ve never liked the name my parents gave me so I changed it at the age of twenty.","Stop calling me names!","Halt in the name of the law!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('litre','n.[计量]公升（米制容量单位）','/ˈliː.tə/','/ˈliː.tə/','noun',["You should be able to fill four cups with one litre of water."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typhoon','n.[气象]台风','/taɪˈfuːn/','/taɪˈfun/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('helpful','adj.有帮助的；有益的','/ˈhɛlp.fəl/','/ˈhɛlp.fəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predict','v.预报，预言；预知','/pɹɪˈdɪkt/','/pɹɪˈdɪkt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uncertain','adj.无常的；含糊的；靠不住的；迟疑不决的','/ʌnˈsɜːtən/','/ʌnˈsɜːtən/','noun',["Tomorrow''s weather is uncertain."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noodle','n.面条；笨蛋','/nuːdl̩/','/nuːdl̩/','noun',["She slurped a long noodle up out of her soup.","\"Noodle that thought around for a while\" said Dr. Johnson to his Biblical Interpretations class.","If the machine is really broken, noodling with the knobs is not going to fix it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foolish','adj.愚蠢的；傻的','/ˈfuː.lɪʃ/','/ˈfuː.lɪʃ/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turn','v.转动，使旋转；转弯；翻过来；兑换n.转弯；变化；(损害或有益于别人的)行为，举动，举止','/tɜːn/','/tɝn/','verb',["They say they can turn the parts in two days.","We turned a pretty penny with that little scheme.","Ivory turns well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horrible','adj.可怕的；极讨厌的','/ˈhɑɹɪbəl/','/ˈhɑɹɪbəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cell','n.细胞；电池；蜂房的巢室；单人小室vi.住在牢房或小室中','/sɛl/','/sɛl/','noun',["Gregor Mendel must have spent a good amount of time outside of his cell.","The combatants spent the night in separate cells.","This MP3 player runs on 2 AAA cells."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dismiss','v.解散；解雇；开除；让离开；不予理会、不予考虑','/dɪsˈmɪs/','/dɪsˈmɪs/','verb',["The company dismissed me after less than a year.","The soldiers were dismissed after the parade.","He dismissed all thoughts of acting again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boring','adj.无聊的；令人厌烦的n.钻孔v.钻孔；使厌烦；挖空（bore的ing形式）','/ˈbɔːɹɪŋ/','/ˈbɔːɹɪŋ/','verb',["An insect bores into a tree.","to bore a steam cylinder or a gun barrel; to bore a hole","to bore one''s way through a crowd"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obvious','adj.明显的；显著的；平淡无奇的','/ˈɒ.vɪəs/','/ˈɑ.vi.əs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rainy','adj.下雨的；多雨的n.(Rainy)人名；(英)雷尼','/ˈɹeɪni/','/ˈɹeɪni/','adjective',["Due to the rainy weather, we decided not to play in the park."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violence','n.暴力；侵犯；激烈；歪曲','/ˈvaɪləns/','/ˈvaɪləns/','noun',["The violence of the storm, fortunately, was more awesome than destructive.","We try to avoid violence in resolving conflicts.","Violence between the government and the rebels continues."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antique','adj.古老的，年代久远的；过时的，古董的；古风的，古式的n.古董，古玩；古风，古希腊和古罗马艺术风格v.觅购古玩','/ænˈtiːk/','/ænˈtiːk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('experiment','v.尝试；进行实验n.实验，试验；尝试','/ɛk.ˈspɛ.ɹɪ.mənt/','/ɪk.ˈspɛɹ.ə.mənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('field','n.领域；牧场；旷野；战场；运动场v.担任场外队员adj.扫描场；田赛的；野生的','/fiːld/','/fild/','noun',["There are several species of wild flowers growing in this field.","A crop circle was made in a corn field.","The blue team are fielding first, while the reds are batting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handbag','n.手提包','/ˈhæm.bəɡ/','/ˈhæm.bəɡ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('include','v.包含，包括','/ɪnˈkluːd/','/ɪnˈkluːd/','noun',["I will purchase the vacation package if you will include car rental.","Does this volume of Shakespeare include his sonnets?","You have to include the strings library to use this function."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ripe','adj.熟的，成熟的；时机成熟的vt.搜查；调查vi.进行搜查n.(Ripe)人名；(意、瑞典)里佩','/ɹaɪp/','/ɹaɪp/','noun',["ripe apples","ripe cheese"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peasant','n.农民；乡下人','/ˈpɛzənt/','/ˈpɛzənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('athletics','n.竞技；体育运动；田径运动','/æθˈlɛtɪks/','/æθˈlɛtɪks/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discover','v.发现；发觉','/dɪsˈkʊvə/','/dɪsˈkʌvɚ/','verb',["Turning the corner, I discovered a lovely little shop. I discovered that they sold widgets.","The gust of wind discovered a bone in the sand.","This move discovers an attack on a vital pawn."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leak','n.泄漏；漏洞，裂缝v.使渗漏，泄露','/liːk/','/liːk/','noun',["a leak in a boat","The babies'' diapers had big leaks.","The leaks by Chelsea Manning showed the secrets of the US military."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rainfall','n.降雨；降雨量','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tool','n.工具，用具；器械，机床；手段v.使用工具；用机床装备工厂','/tuːl/','/tuːl/','noun',["Hand me that tool, would you?   I don''t have the right tools to start fiddling around with the engine.","These are the tools of the trade.","The software engineer had been developing lots of EDA tools.   a tool for recovering deleted files from a disk"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bite','v.咬；刺痛n.咬；一口；咬伤；刺痛abbr.机内测试设备（Built-InTestEquipment）','/bʌɪt/','/baɪt/','noun',["That snake bite really hurts!","After just one night in the jungle I was covered with mosquito bites.","There were only a few bites left on the plate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('praise','n.赞扬；称赞；荣耀；崇拜v.赞美，歌颂；表扬','/pɹeɪz/','/pɹeɪz/','noun',["Be sure to praise Bobby for his excellent work at school this week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('activity','n.活动；行动；活跃','/ækˈtɪ.və.ti/','/ækˈtɪ.və.ti/','noun',["Pit row was abuzz with activity.","The activity for the morning was a walk to the store.","An increasing number of sports activities are on offer at the university."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carry','v.拿，扛；携带；支持；搬运n.运载；[计]进位；射程','/ˈkæ.ɹi/','/ˈkæ.ɹi/','noun',["Adjust your carry from time to time so that you don''t tire too quickly.","The carry on this trade is 25 basis points per annum.","to carry an account to the ledger"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('take','v.拿，取；采取；接受（礼物等）；买，花费；耗费（时间等）n.捕获量；看法；利益，盈益；（入场券的）售得金额','/teɪk/','/teɪk/','noun',["What''s your take on this issue, Fred?","a new take on a traditional dish","Act seven, scene three, take two."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dimension','n.方面;[数]维；尺寸；次元；容积vt标出尺寸adj.规格的','/daɪˈmɛnʃən/','/daɪˈmɛnʃən/','noun',["The dimension of velocity is length divided by time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('format','n.格式；版式；开本v.使格式化；规定…的格式','/ˈfɔː(ɹ).mæt/','/ˈfɔːɹ.mæt/','noun',["The radio station changed the format of its evening program.","I lost weeks of work when I inadvertently formatted my hard drive."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('start','v.开始；启动n.开始；起点','/stɑːt/','/stɑɹt/','noun',["The movie was entertaining from start to finish.","He woke with a start.","Captured pieces are returned to the start of the board."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('week','n.周，星期','/wiːk/','/wik/','noun',["A 4-day week consists of Monday, Tuesday, Wednesday, and Thursday.","I''ll see you Thursday week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reject','v.拒绝；排斥；抵制；丢弃n.被弃之物或人；次品','','','noun',["She even rejected my improved offer.","I''ve been rejected three times this week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artificial','adj.人造的；仿造的；虚伪的；非原产地的；武断的','/ɑː(ɹ)təˈfɪʃəl/','/ɑː(ɹ)təˈfɪʃəl/','adjective',["The flowers were artificial, and he thought them rather tacky.","Her manner was somewhat artificial."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('welcome','adj.受欢迎的n.欢迎v.欢迎int.欢迎','/ˈwɛlkəm/','/ˈwɛlkəm/','noun',["We entered the house and found a ready welcome.","We welcome suggestions for improvement.","Refugees welcome in London!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earth','n.地球；地表，陆地；土地，土壤；尘事，俗事；兽穴v.把（电线）[电]接地；盖（土）；追赶入洞穴','/ɜːθ/','/ɝθ/','proper noun',["This is good earth for growing potatoes.","She sighed when the plane''s wheels finally touched earth.","Birds are of the sky, not of the earth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avenue','n.大街；林荫大道；[比喻](达到某物的)途径，手段，方法，渠道','/ˈæv.əˌnjuː/','/ˈæv.əˌn(j)u/','noun',["There are several avenues by which we can approach this problem."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strawberry','n.草莓；草莓色','/ˈstɹɔːb(ə)ɹi/','/ˈstɹɔːb(ə)ɹi/','noun',["They went to pick strawberries today.","She has the best strawberry patch I''ve ever seen.","I''d like a large strawberry shake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('translate','v.翻译；转化；解释；转变为；调动','/ˈtɹɛnzlæet/','/tɹæn(t)s-/','noun',["William was translated by the blow to the head he received, being unable to speak for the next few minutes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sea','n.海；海洋；许多；大量','/siː/','/siː/','noun',["The Caspian Sea, the Sea of Galilee, the Salton Sea, etc.","Seaman, sea gauge, sea monster, sea horse, sea level, seaworthy, seaport, seaboard, etc.","The Apollo 11 mission landed in the Sea of Tranquility."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drill','n.训练；钻孔机；钻子；播种机v.钻孔；训练','/dɹɪl/','/dɹɪl/','noun',["Wear safety glasses when operating an electric drill.","Use a drill with a wire brush to remove any rust or buildup.","Regular fire drills can ensure that everyone knows how to exit safely in an emergency."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('page','n.页；记录；大事件，时期；男侍者v.给…标页码','/peɪd͡ʒ/','/peɪd͡ʒ/','noun',["the page of history","The patient paged through magazines while he waited for the doctor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stamp','n.邮票；印记；标志；跺脚v.铭记；标出；盖章于…；贴邮票于…；用脚踩踏','/stæmp/','/stæmp/','noun',["The horse gave two quick stamps and rose up on its hind legs.","My passport has quite a collection of stamps.","She loved to make designs with her collection of stamps."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('along','adv.一起；向前；来到prep.沿着；顺着','/əˈlɑŋ/','/əˈlɔŋ/','adverb',["John played the piano and everyone sang along.","Don''t stop here. Just move along."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('style','n.风格；时尚；类型；字体v.设计；称呼；使合潮流','/staɪl/','/staɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garden','n.花园；菜园v.栽培花木','/ˈɡɑːdn̩/','/-n̩/','noun',["a vegetable garden  a flower garden","This house has a swimming pool, a tent, a swing set and a fountain in the garden.  We were drinking lemonade and playing croquet in the garden.  Our garden is overgrown with weeds.","N.B. From a commentary on Song of Solomon 4:16, which was written in Hebrew c. 950 BC; book footnotes are shown here within brackets. Many scholars disagree with this Biblical interpretation, which is included as evidence of the word''s usage in 1995 rather than its intended meaning in 950 BC."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oppose','v.反对；对抗，抗争','/əˈpəʊz/','/əˈpoʊz/','verb',["There is still time to oppose this plan.","Many religious leaders oppose cloning humans.","They are opposed to any form of hierarchy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nationality','n.国籍，国家；民族；部落','/-ˈnæl.ti/','/-ˈnæl.ti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consultant','n.顾问；咨询者；会诊医生','/kənˈsʌltənt/','/kənˈsʌltənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('load','n.负载，负荷；工作量；装载量v.[力]加载；装载；装货','/ləʊd/','/loʊd/','noun',["I struggled up the hill with the heavy load in my rucksack.","She put another load of clothes in the washing machine.","I put a load on before we left."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behavious','n.行为','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nylon','n.尼龙，[纺]聚酰胺纤维；尼龙袜','/ˈnaɪlɒn/','/ˈnaɪlɒn/','noun',["I tore a hole in my nylons while walking home through the woods."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statue','n.雕像，塑像vt.以雕像装饰','/ˈstæt.juː/','/ˈstætʃu/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('witness','n.证人；目击者；证据v.目击；证明；为…作证','/ˈwɪtnəs/','/ˈwɪtnəs/','noun',["She can bear witness, since she was there at the time.","As a witness to the event, I can confirm that he really said that.","The witness for the prosecution did not seem very credible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('difficult','adj.困难的；不随和的；执拗的','/ˈdɪfɪkəlt/','/ˈdɪfɪkəlt/','verb',["However, the difficult weather conditions will ensure Yunnan has plenty of freshwater.","Stop being difficult and eat your broccoli—you know it''s good for you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moral','adj.道德的；精神上的；品性端正的n.道德；寓意','/ˈmɒɹəl/','/ˈmɑɹəl/','noun',["a candidate with strong morals","moral judgments;  a moral poem","a moral obligation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evidence','n.证据，证明；迹象；明显v.证明','[ˈɛvəɾəns]','[ˈɛvəɾəns]','noun',["There is no evidence that anyone was here earlier.","She was furious, as evidenced by her slamming the door."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pour','n.倾泻；流出；骤雨v.灌，注；倒；倾泻；倾吐','/pɔː/','/pɔɹ/','noun',["The bartender''s inexpert pour left me with a pint of beer that was half foam.","pour water from a jug","the rain poured down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('map','v.映射；计划；绘制地图；确定基因在染色体中的位置n.地图；示意图；染色体图','/mæp/','/mæp/','noun',["I don''t want to play this map again!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blouse','n.宽松的上衣；女装衬衫vt.使…宽松下垂vi.宽松下垂','/blaʊs/','/blaʊs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lab','n.实验室，研究室','/læb/','/læb/','noun',["I dropped my mixture while doing my lab, so I had to start over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hall','n.过道，门厅，走廊；会堂；食堂；学生宿舍；大厅，前厅；娱乐中心，会所','/hɔːl/','/hɔl/','noun',["The drinking fountain was out in the hall.","The hotel had three halls for conferences, and two were in use by the convention.","The duke lived in a great hall overlooking the sea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compromise','v.妥协；危害n.妥协，和解；折衷','/ˈkɒmpɹəˌmaɪz/','/ˈkɑmpɹəˌmaɪz/','noun',["a compromise of character or right","He tried to compromise the security in the computer by guessing the password."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motivation','n.动机；积极性；推动','','','noun',["The motivation scores showed that 65% of people wanted to visit our website to learn more about the offer after watching the commercial."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unfit','adj.不适宜的；不合格的；不健康的v.使不合格；使不相宜；使不胜任','/ʌnˈfɪt/','/ʌnˈfɪt/','verb',["Jack cannot run, making him unfit for the track team.","I''ve become so unfit after stopping cycling to town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lonely','adj.寂寞的；偏僻的n.孤独者','/ˈləʊnli/','/ˈloʊnli/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gifted','adj.有天赋的；有才华的v.给予（gift的过去分词）','/ˈɡɪftɪd/','/ˈɡɪftɪd/','verb',["a gifted artist"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('considerate','adj.体贴的；体谅的；考虑周到的','/kənˈsɪdəɹət/','/kənˈsɪdəɹət/','verb',["Consider that we’ve had three major events and the year has hardly begun.","I’m considering going to the beach tomorrow.","Consider yourself lucky, but consider your opponent skillful."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plot','n.情节；图；阴谋v.密谋；绘图；划分；标绘','/plɒt/','/plɑt/','noun',["The assassination of Lincoln was part of a larger plot.","They had plotted a robbery.","They plotted the number of edits per day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carrot','n.胡萝卜','/ˈkæɹ.ət/','/ˈkæɹ.ət/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nothing','neg.没什么；毫不n.无；零；不关紧要之事adv.毫不；决不pron.无事；无物int.什么也没有','/ˈnʌθɪŋ/','/ˈnʌθɪŋ/','noun',["You''re nothing to me now!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brochure','n.手册，小册子','/ˈbɹəʊ.ʃə(ɹ)/','/bɹoʊˈʃɝ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weight','n.重量，重力；负担；砝码；重要性v.加重量于，使变重','/weɪt/','/weɪt/','noun',["He''s working out with weights.","the weight of care or business","He was pushing weight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hope','n.希望；期望；信心v.希望；期望','/həʊp/','/hoʊp/','verb',["I am still hoping that all will turn out well.","I hope you all the best."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lorry','n.（英）卡车；[车辆]货车；运料车','/ˈlɒɹi/','/ˈlɒɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noisily','adv.吵闹地，喧闹地','','','adverb',["They talked noisily and long into the night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cloud','n.云；阴云；云状物；一大群；黑斑v.使混乱；以云遮敝；使忧郁；玷污','/klaʊd/','/klaʊd/','noun',["He opened the door and was greeted by a cloud of bats.","The comic-book character''s thoughts appeared in a cloud above his head.","The glass clouds when you breathe on it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('topic','n.主题（等于theme）；题目；一般规则；总论','/ˈtɒpɪk/','/ˈtɑpɪk/','noun',["A society where a topic cannot be discussed, does not have free speech."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hug','v.拥抱；紧抱；抱有，坚持n.拥抱；紧抱；固执','/hʌɡ/','/hʌɡ/','noun',["Billy hugged Danny until he felt better."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('size','n.大小；尺寸adj.一定尺寸的v.依大小排列','/saɪz/','/saɪz/','noun',["The size of the building seemed to have increased since I was last there.","I don''t think we have the red one in your size."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ladder','n.阶梯；途径；梯状物v.成名；发迹','/ˈladə/','/ˈlædɚ/','noun',["Oh damn it, I''ve laddered my tights!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('folk','n.民族；人们；亲属（复数）adj.民间的','/fəʊk/','/foʊk/','noun',["Young folk, old folk, everybody come, / To our little Sunday School and have a lot of fun.","folk psychology; folk linguistics"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('energetic','adj.精力充沛的；积极的；有力的','/ˌɛnəˈdʒɛtɪk/','/ˌɛnɚˈdʒɛtɪk/','adjective',["Cosmic rays are energetic particles from outer space.","Those kids are so energetic: they want to run around playing all day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mop','v.擦干；用拖把拖洗n.拖把；蓬松的头发；鬼脸','/mɒp/','/mɑp/','noun',["He gave the floor a quick mop to soak up the spilt juice.","He ran a comb through his mop and hurried out the door.","to mop (or scrub) a floor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assumption','n.假定；设想；担任；采取','/əˈsʌmp.ʃən/','/əˈsʌmp.ʃən/','noun',["His assumption of secretarial duties was timely.","Their assumption of his guilt disqualified them from jury duty."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flesh','n.肉；肉体v.喂肉给…；使发胖','/flɛʃ/','/flɛʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marathon','n.马拉松赛跑；耐力的考验adj.马拉松式的；有耐力的vi.参加马拉松赛跑','/ˈmæɹəθən/','/ˈmæɹəθən/','noun',["He had a cleaning marathon the night before his girlfriend came over.","We''re going to marathon Star Trek next weekend."]);
