INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expect','v.期望；指望；认为；预料','/ɛkˈspɛkt/','/ɛkˈspɛkt/','verb',["He never expected to be discovered.","You are expected to get the task done by the end of next week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ward','n.病房；保卫；监视v.避开；保卫；守护','/wɔːd/','/wɔɹd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comfortable','adj.舒适的，舒服的n.盖被','/ˈkʌm.fə.tə.bəl/','/ˈkʌm.fə.tə.bəl/','noun',["This is the most comfortable bed I''ve ever slept in.","What a great guestroom! I''ll be quite comfortable here.","A comfortable income should suffice to consider oneself rich."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yesterday','n.昨天；往昔adv.昨天','/ˈjɛstədeɪ/','/ˈjɛstɚdeɪ/','noun',["Today is the child of yesterday and the parent of tomorrow.","yesterday''s technology","I started to watch the video yesterday, but could only finish it this evening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feeling','n.感觉，触觉；感情，情绪；同情adj.有感觉的；有同情心的；富于感情的v.感觉；认为（feel的现在分词）；触摸','/ˈfiːlɪŋ/','/ˈfilɪŋ/','verb',["Feel my wrath!","It looks like wood, but it feels more like plastic.","I don''t want you back here, ya feel me?"]);
