INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nut','n.螺母，螺帽；坚果；难对付的人，难解的问题v.采坚果','[nɐt]','/nʌt/','noun',["There are many sort of nuts: peanuts, cashews, pistachios, Brazil nuts and more.","He was driving his car like a nut.","I kicked him in the nuts."]);
