INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cinema','n.电影；电影院；电影业，电影制作术','/ˈsɪn.ɪ.mɑː/','/ˈsɪn.ə.mə/','noun',["The cinema is right across the street from the restaurant.","Despite the critics, he produced excellent cinema.","In the long history of Spanish cinema ."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weed','v.除草；铲除n.杂草，野草；菸草','/wiːd/','/wiːd/','noun',["If it isn''t in a straight line or marked with a label, it''s a weed."]);
