INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accident','n.事故；意外；[法]意外事件；机遇','/ˈæk.sə.dənt/','/ˈæk.sə.dənt/','noun',["to die by an accident","My insurance went up after the second accident in three months.","Beauty is an accident."]);
