INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magic','n.巫术；魔法；戏法adj.不可思议的；有魔力的；魔术的','/ˈmadʒɪk/','/ˈmædʒɪk/','noun',["a magic moment","a magic show; a magic trick","— I cleaned up the flat while you were out. — Really? Magic!"]);
