INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('May','n.五月','/meɪ/','/meɪ/','verb',["you may smoke outside;  may I sit there?","he may be lying;  Schrödinger''s cat may or may not be in the box","may you win;  may the weather be sunny"]);
