INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunshine','n.阳光；愉快；晴天；快活','/ˈsʌnʃaɪn/','/ˈsʌnʃaɪn/','noun',["We were warmed by the bright sunshine.","We moved out of the shade and into the sunshine.","I enjoyed the sunshine of her smile."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('project','v.设计；计划；表达；投射n.工程；计划；事业','','','noun',["Projects like Pruitt-Igoe were considered irreparably dangerous and demolished.","a man given to projects","The CEO is projecting the completion of the acquisition by April 2007."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('southwest','n.西南方adj.西南的adv.往西南；来自西南','/saʊˈwɛst/','/saʊˈwɛst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illegal','adj.[法]非法的；违法的；违反规则的n.非法移民，非法劳工','/ɪˈliːɡəl/','/ɪˈliːɡəl/','noun',["Nearly 40 million people live in UK areas with illegal air pollution","Moving a pawn backward is an illegal move in chess.","illegal immigrant;  illegal logger;  illegal pilot"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statistics','n.统计；统计学；[统计]统计资料','/stəˈtɪstɪks/','/stəˈtɪstɪks/','noun',["Statistics is the only mathematical field required for many social sciences."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('level','n.水平；标准；水平面adj.水平的；平坦的；同高的v.瞄准；拉平；变得平坦','/ˈlɛv.əl/','/ˈlɛv.əl/','noun',["Hand me the level so I can tell if this is correctly installed.","By the end of the day, we''d dug down to the level of the old basement floor.","The sound level is much too high; this hurts my ears.   We''ve reached a new level of success."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cosy','adj.舒适的；惬意的n.保温罩','/ˈkəʊzi/','/ˈkoʊzi/','noun',["He spent all day cosying up to the new boss, hoping for a plum assignment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tight','adj.紧的；密封的；绷紧的；麻烦的；严厉的；没空的；吝啬的adv.紧紧地；彻底地n.(Tight)人名；(英)泰特','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shadow','n.阴影；影子；幽灵；庇护；隐蔽处v.遮蔽；使朦胧；尾随；预示adj.影子内阁的','/ˈʃædəʊ/','/ˈʃædoʊ/','noun',["My shadow lengthened as the sun began to set.","I immediately jumped into shadow as I saw them approach.","The mountains block the passage of rain-producing weather systems and cast a \"shadow\" of dryness behind them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continent','n.大陆，洲，陆地adj.自制的，克制的','/ˈkɒntɪnənt/','/ˈkɑntɪnənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bacterium','n.[微]细菌；杆菌属','/bækˈtɪəɹ.ɪəm/','/bækˈtɪəɹ.ɪəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roundabout','adj.迂回的，绕道的；圆滚滚的n.迂回路线；环状交叉路口','/ˈɹaʊndəˌbaʊt/','/ˈɹaʊndəˌbaʊt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('connection','n.连接；关系；人脉；连接件','/kəˈnɛkʃən/','/kəˈnɛkʃən/','noun',["My headache has no connection with me going out last night.","As we were the only people in the room to laugh at the joke, I felt a connection between us.","I was talking to him, but there was lightning and we lost the connection."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bottom','n.底部；末端；臀部；尽头adj.底部的v.装底；测量深浅；查明真相','/ˈbɒtəm/','/ˈbɑtəm/','noun',["Footers appear at the bottoms of pages.","lack bottom","Where shall we go for a walk? How about Ashcombe Bottom?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('printer','n.[计]打印机；印刷工；印花工','/ˈpɹɪntə(ɹ)/','/ˈpɹɪntə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aboard','adv.在飞机上；[船]在船上；在火车上prep.在…上','/əˈbɔːd/','/əˈbɔɹd/','adverb',["We all climbed aboard.","To sling a saddle aboard.","He doubled with two men aboard, scoring them both."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('writing','n.书写；作品；著作；[法]笔迹v.书写（write的ing形式）','/ˈɹaɪtɪŋ/','/ˈɹaɪtɪŋ/','noun',["I can''t read your writing.","a writing table"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bleed','v.使出血；榨取','/ˈbliːd/','/ˈbliːd/','noun',["If her nose bleeds, try to use ice.","The company was bleeding talent.","Ink traps counteract bleeding."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spy','v.侦察；发现；暗中监视n.间谍；密探','/spaɪ/','/spaɪ/','noun',["During the Cold War, Russia and America would each spy on each other for recon.","I think I can spy that hot guy coming over here."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soldier','n.军人；[昆]兵蚁；懒汉；一片烤面包v.当兵；磨洋工；坚持干；假称害病','/ˈsɒld͡ʒə/','/ˈsoʊld͡ʒɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temperature','n.温度；体温；气温；发烧','/ˈtɛmp(ə)ɹətʃə(ɹ)/','/ˈtɛmp(ə)ɹətʃə(ɹ)/','noun',["The temperature in the room dropped nearly 20 degrees; it went from hot to cold.","You have a temperature. I think you should stay home today. You’re sick."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('both','adj.两个的；两者的adv.并；又；两者皆pron.双方都；两者都conj.既…且…n.(Both)人名；(德、罗、捷、南非、匈)博特','/bəʊθ/','/boʊθ/','pronoun',["\"Did you want this one or that one?\" — \"Give me both.\"","Both you and I are students."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fresh','adj.新鲜的；清新的；淡水的；无经验的n.开始；新生；泛滥adv.刚刚，才；最新地','/fɹɛʃ/','/fɹɛʃ/','noun',["He followed the fresh hoofprints to find the deer.","After taking a beating in the boxing ring, the left side of his face looked like fresh meat.","What a nice fresh breeze."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kingdom','n.王国；界；领域','/ˈkɪŋdəm/','/ˈkɪŋdəm/','noun',["the kingdom of the dead"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boating','n.划船adj.划船的v.划船（boat的ing形式）','/ˈbəʊtɪŋ/','/ˈbəʊtɪŋ/','verb',["to boat goods","to boat oars"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tendency','n.倾向，趋势；癖好','/ˈtɛndənsi/','/ˈtɛndənsi/','noun',["Denim has a tendency to fade."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concert','n.音乐会；一致；和谐v.使协调；协同安排adj.音乐会用的；在音乐会上演出的','','/ˈkɒnsət/','noun',["I''m going to the rock concert on Friday."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consume','v.消耗，消费；使…著迷；挥霍','/kənˈsjuːm/','/kənˈsuːm/','verb',["The power plant consumes 30 tons of coal per hour.","Baby birds consume their own weight in food each day.","Desire consumed him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('six','num.六，六个n.六，六个','/sɪks/','/sɪks/','noun',["cover my six"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refresh','v.更新；使……恢复；使……清新；消除……的疲劳','/ɹiˈfɹɛʃ/','/ɹɪˈfɹɛʃ/','noun',["Sleep refreshes the body and the mind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('broad','adj.宽的，辽阔的；显著的；大概的n.宽阔部分adv.宽阔地','/bɹɑd/','/bɹɔd/','noun',["the broad expanse of ocean","a broad hint","a broad compliment; a broad joke; broad humour"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('camp','v.露营；扎营n.露营','[kʰɛəmp]','[kʰɛəmp]','noun',["a hunter''s camp","We''re planning to camp in the field until Sunday.","Go and camp the flag for the win."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gale','n.[气象]大风，狂风；（突发的）一阵','/ɡeɪl/','/ɡeɪl/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('borrow','v.借；借用；从其他语言中引入n.(Borrow)人名；(英)博罗','/ˈbɔɹoʊ/','/ˈbɑɹoʊ/','noun',["This putt has a big left-to right borrow on it.","to borrow the style, manner, or opinions of another","Can I borrow a sheet of paper?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demand','v.要求；需要；查询n.[经]需求；要求；需要','/dɪˈmɑːnd/','/dəˈmænd/','noun',["Prices usually go up when demand exceeds supply.","Modern society is responding to women''s demands for equality.","His job makes many demands on his time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knock','v.敲；打；敲击n.敲；敲打；爆震声','/nɒk/','/nɑk/','noun',["I heard a knock on my door.","He took a knock on the head.","He played a slow but sure knock of 35."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sour','adj.酸的；发酵的；刺耳的；酸臭的；讨厌的v.发酵；变酸；厌烦n.酸味；苦事','/ˈsaʊə/','/ˈsaʊ(ə)ɹ/','noun',["Too much lemon juice will sour the recipe.","We broke up after our relationship soured.","Lemons have a sour taste."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grandpa','n.爷爷；外公','/ˈɡɹæmpɑː/','/ˈɡɹæmpɑː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zip','n.拉链；活力，精力；尖啸声，撕裂声；一种程序压缩的档案文件格式v.拉开或拉上；以尖啸声行进','/zɪp/','/zɪp/','noun',["I know zip about economics.","zip one''s lip","The bullet zipped through the air."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rank','n.排；等级；军衔；队列adj.讨厌的；恶臭的；繁茂的v.排列；把…分等','/ɹæŋk/','/ɹæŋk/','adjective',["rank nonsense","rank grass","rank land"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('butcher','v.屠杀n.屠夫','/ˈbʊtʃ.ə(ɹ)/','/ˈbʊt͡ʃ.ɚ/','noun',["The band at that bar really butchered \"Hotel California\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ready','adj.准备好；现成的；迅速的；情愿的；快要…的n.现款；预备好的状态adv.迅速地；预先v.使准备好','/ˈɹɛdi/','/ˈɹɛdi/','noun',["The porridge is ready to serve.","The seed is ready to sprout.","a ready apprehension"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pig','n.猪；猪肉v.生小猪；像猪一样过活','/ˈpɪɡ/','/ˈpɪɡ/','noun',["The man kept a pen with two pigs that he fed from carrots to cabbage.","Some religions prohibit their adherents from eating pig.","You gluttonous pig! Now that you''ve eaten all the cupcakes, there will be none for the party!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trap','v.诱捕；使…受限制；使…陷入困境n.陷阱；圈套；[建]存水湾','/tɹæp/','/tɹæp/','noun',["I put down some traps in my apartment to try and deal with the mouse problem.","Unfortunately she fell into the trap of confusing biology with destiny.","Close the trap, would you, before someone falls and breaks their neck."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cancer','n.癌症；恶性肿瘤','/ˈkænsə/','/ˈkænsɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vice','n.恶习；缺点；[机]老虎钳；卖淫prep.代替vt.钳住adj.副的；代替的','/vaɪs/','/vaɪs/','noun',["Gluttony is a vice, not a virtue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harm','n.伤害；损害v.伤害；危害；损害','/hɑːm/','/hɑɹm/','noun',["No harm came to my possessions.","Although not physically injured in the car accident, she received some psychological harm.","I wish him no harm."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rare','adj.稀有的；稀薄的；半熟的adv.非常；极其vi.用后腿站起；渴望','[ɹɜɹ]','/ɹɛəɹ/','noun',["Black pearls are very rare and therefore very valuable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brewery','n.啤酒厂','/ˈbɹuːəɹi/','/ˈbɹuːəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finish','v.完成；结束；用完n.结束；完美；回味（葡萄酒）','/ˈfɪnɪʃ/','/ˈfɪnɪʃ/','noun',["The car''s finish was so shiny and new.","Be sure to finish your homework before you go to bed!","The furniture was finished in teak veneer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cock','n.公鸡；龙头；雄鸟；头目v.使竖起；使耸立；使朝上','/kɒk/','/kɑk/','noun',["All right, cock?","In the darkness, the gun cocked loudly.","He cocked his hat jauntily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fairly','adv.相当地；公平地；简直n.(Fairly)人名；(英)费尔利','/ˈfɛə(ɹ).li/','/ˈfɛɹ.li/','adverb',["A jury is expected to ensure that the accused is fairly judged.","a town fairly situated for foreign trade","Consumer laws aim to have consumers fairly treated."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grandparents','n.祖父母（grandparent的复数）；外祖父母','','','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instant','adj.立即的；紧急的；紧迫的n.瞬间；立即；片刻','/ˈɪnstənt/','/ˈɪnstənt/','noun',["She paused for only an instant, which was just enough time for John to change the subject.","The instant the alarm went off, he fled the building."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('see','v.看见；理解；领会n.(See)人名；(英)西伊；(柬)塞；(德)泽','/siː/','/siː/','verb',["1999 saw the release of many great films.","I''ll see you hang for this!  I saw that they didn''t make any more trouble.","I saw the old lady safely across the road."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('back','n.后面；背部；靠背；足球等的后卫；书报等的末尾v.支持；后退；背书；下赌注adv.以前；向后地；来回地；上溯；回来；回原处adj.后面的；过去的；拖欠的','/bæk/','/bæk/','noun',["Could you please scratch my back?","He sat in the back of the room.","The small boat raced over the backs of the waves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('area','n.区域，地区；面积；范围','/ˈɛə̯ɹɪə̯/','/ˈæɹ.i.ə/','noun',["The photo is a little dark in that area.","The plans are a bit vague in that area."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacrifice','n.牺牲；祭品；供奉v.牺牲；献祭；亏本出售','/ˈsækɹɪfaɪs/','/ˈsækɹɪfaɪs/','noun',["the sacrifice of one''s spare time in order to volunteer","Venison has many advantages over meat from factory farms, although it still requires a hunter to sacrifice the life of a deer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Africa','n.非洲','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collision','n.碰撞；冲突；（意见，看法）的抵触；（政党等的）倾轧','/kəˈlɪʒən/','/kəˈlɪʒən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homeland','n.祖国；故乡','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technical','adj.工艺的，科技的；技术上的；专门的','/ˈtɛk.nɪk.əl/','/ˈtɛk.nɪk.əl/','noun',["The performance showed technical virtuosity, but lacked inspiration.","The market had a technical rally, due to an oversold condition.","Crossing the front lawn of that house to get to the mailbox was a technical trespass."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ink','v.签署；涂墨水于n.墨水，墨汁；油墨','/ɪŋk/','/iŋk/','noun',["The TSA has been getting a lot of ink lately."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faith','n.信仰；信念；信任；忠实','/feɪθ/','/feɪθ/','noun',["I have faith in the goodness of my fellow man.","I have faith in the healing power of crystals.","The Christian faith."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('never','adv.从未；决不','/ˈnɛv.ə(ɹ)/','/ˈnɛ.vɚ/','adverb',["I finally finished, and I never want to do that again.","I never saw him today."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quarrel','v.吵架；争论；挑剔n.吵架；反目；怨言；争吵的原因；方头凿','/ˈkwɒɹəl/','/ˈkwɑɹəl/','noun',["We got into a silly quarrel about what food to order.","A few customers in the shop had some quarrels with us, so we called for the manager.","to quarrel with one''s lot"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undivided','adj.专心的；专一的；未分开的；完整的v.未分开（undivide的过去式和过去分词）','/ˌʌndɪˈvaɪdɪd/','/ˌʌndɪˈvaɪdɪd/','adjective',["Long division can be hard to understand, so I want your undivided attention."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('separation','n.分离，分开；间隔，距离；[法]分居；缺口','/sɛpəˈɹeɪʃən/','/sɛpəˈɹeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Indicate','v.表明；指出；预示；象征','/ˈɪndɪkeɪt/','/ˈɪndɪkeɪt/','verb',["The guard blew his whistle to indicate imminent departure.","Great prostration of strength indicates the use of stimulants."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('will','n.意志；决心；情感；遗嘱；意图；心愿v.决心要；遗赠；用意志力使aux.将；愿意；必须','/wɪl/','/wɪl/','verb',["Do what you will.","I’ve told him three times, but he won’t take his medicine.","Unfortunately, only one of these gloves will actually fit over my hand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('express','v.表达；快递adj.明确的；迅速的；专门的n.快车，快递，专使；捷运公司','/ɛk.ˈspɹɛs/','/ɛk.ˈspɹɛs/','noun',["I took the express into town.","I gave him express instructions not to begin until I arrived, but he ignored me.","In my eyes it bore a livelier image of the spirit, it seemed more express and single, than the imperfect and divided countenance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fast','adj.快速的，迅速的；紧的，稳固的adv.迅速地；紧紧地；彻底地v.禁食，斋戒n.斋戒；绝食','/fæst/','/fæst/','noun',["That rope is dangerously loose. Make it fast!","I am going to buy a fast car.","a fast billiard table"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('open','adj.公开的；敞开的；空旷的；坦率的；营业着的v.开始；展现n.公开；空旷；户外','/ˈəʊ.pən/','/ˈoʊ.pən/','adjective',["an open hand; an open flower","Banks are not open on bank holidays.","I am open to new ideas."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pocket','n.口袋；钱；容器v.隐藏；忍受；将…放入衣袋adj.小型的，袖珍的；金钱上的','/ˈpɒkɪt/','/ˈpɑkɪt/','noun',["I paid for it out of my own pocket.","The drilling expedition discovered a pocket of natural gas.","Record executives pocketed most of the young singer''s earnings."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soul','n.灵魂；心灵；精神；鬼魂adj.美国黑人文化的','/səʊl/','/soʊl/','noun',["Fifty souls were lost when the ship sank."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('branch','v.分支；出现分歧n.树枝，分枝；分部；支流','/bɹæntʃ/','/bɹæntʃ/','noun',["the branch of an antler, a chandelier, or a railway","the branches of a hyperbola","Our main branch is downtown, and we have branches in all major suburbs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tip','v.给小费；翻倒；倾覆n.小费；尖端；小建议，小窍门；轻拍','/tɪp/','/tɪp/','noun',["The shape of the nozzle prevents the use of aftermarket eartips.","a cat with an eartip","the tip of one''s nose"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mutton','n.羊肉','/ˈmʌtn̩/','/ˈmʌtn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boom','v.使兴旺；发隆隆声n.繁荣；吊杆；隆隆声','/buːm/','/buːm/','noun',["The boom of the surf.","You should prepare for the coming boom in the tech industry.","I can hear the organ slowly booming from the chapel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magazine','n.杂志；弹药库；胶卷盒','/mæɡəˈziːn/','/mæɡəˈziːn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hospital','n.医院','/ˈhɒs.pɪ.tl̩/','/ˈhɑs.pɪ.tl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sock','n.短袜；一击v.重击；给……穿袜adv.正着地；不偏不倚地adj.非常成功的','/sɒk/','/sɑk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physics','n.物理学；物理现象','/ˈfɪz.ɪks/','/ˈfɪz.ɪks/','noun',["Newtonian physics was extended by Einstein to explain the effects of travelling near the speed of light; quantum physics extends it to account for the behaviour of atoms.","The physics of car crashes would not let Tom Cruise walk away like that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('taxi','v.乘出租车；滑行n.出租汽车','/ˈtæk.si/','/ˈtæk.si/','noun',["taxi down the runway"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('facial','adj.面部的，表面的；脸的，面部用的n.美容，美颜；脸部按摩','/ˈfeɪʃəl/','/ˈfeɪʃəl/','noun',["He gave his wife a creamy facial.","The facial constitutionality of the law is in question."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('famous','adj.著名的；极好的，非常令人满意的','/ˈfeɪməs/','/ˈfeɪməs/','verb',["Some people are only famous within their city."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('China','n.中国adj.中国的；中国制造的','/tʃʌɪnə/','','noun',["He set the table with china, cloth napkins, and crystal stemware.","John and I have been friends ever since we were roommates at college.   Trust is important between friends.   I used to find it hard to make friends when I was shy.","The Automobile Association is every motorist''s friend.   The police is every law-abiding citizen''s friend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exam','n.考试；测验','/ɛɡˈzæm/','/ɛɡˈzæm/','noun',["He examined the crime scene for clues.","The doctor examined the patient.","The witness was examined under oath."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passenger','n.旅客；乘客；过路人；碍手碍脚的人','/ˈpæsənd͡ʒə/','/ˈpæsənd͡ʒɚ/','noun',["Somebody in a team who does not do their fair share of the work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seagull','n.海鸥','/ˈsiː.ɡʌl/','/ˈsiː.ɡʌl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('when','conj.考虑到；既然；当…时；在…时；如果adv.什么时候，何时；（用于时间的表达方式之后）在那时；其时；当时pron.那时；什么时侯n.时间，时候；日期；场合','/wɛn/','/wɛn/','noun',["A good article will cover the who, the what, the when, the where, the why and the how.","Do you know when they arrived?","He''s mister high and mighty now, but I remember him when."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trick','n.诡计；恶作剧；窍门；花招；骗局；欺诈v.欺骗；哄骗；装饰；打扮adj.特技的；欺诈的；有决窍的','/tɹɪk/','/tɹɪk/','noun',["It was just a trick to say that the house was underpriced.","And for my next trick, I will pull a wombat out of a duffel bag.","That''s a nice skateboard, but can you do any tricks on it?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fix','v.使固定；修理；安装；准备n.困境；方位；贿赂','/ˈfɪks/','/ˈfɪks/','noun',["That plumber''s fix is much better than the first one''s.","It rained before we repaired the roof, and were we in a fix!","We have a fix on your position."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('onto','prep.在…之上；对…了解；映射到…上adj.映射的；自身的；映成的','/ˈɒn.tuː/','/ˈɒn.tuː/','adjective',["Considered as a function on the real numbers, the exponential function is not onto.","My cat just jumped onto the keyboard.","The thought-police were onto my plans of world domination."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commit','v.犯罪，做错事；把交托给；指派…作战；使…承担义务','/kəˈmɪt/','/kəˈmɪt/','noun',["Tony should be committed to a nuthouse!","to commit a series of heinous crimes","to commit oneself to a certain action"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oval','adj.椭圆的；卵形的n.椭圆形；卵形','/ˈəʊvəl/','/ˈəʊvəl/','noun',["oval conceptions"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('building','n.建筑；建筑物v.建筑；建立；增加（build的ing形式）','/ˈbɪl.dɪŋ/','/ˈbɪl.dɪŋ/','noun',["The building of the bridge will be completed in a couple of weeks.","My sister lives in that apartment building."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evolution','n.演变；进化论；进展','/ˈɛvəluːʃ(ə)n/','/ˌivə-/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disgusting','adj.令人厌恶的','/dɪsˈɡʊstɪŋ/','/dɪsˈkʌstɪŋ/','verb',["It disgusts me to see her chew with her mouth open."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unmarried','adj.[法]未婚的；单身的；独身的v.离婚（unmarry的过去分词）','/ʌnˈmæɹid/','/ʌnˈmɛɹid/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chair','n.椅子；讲座；（会议的）主席位；大学教授的职位v.担任（会议的）主席；使…入座；使就任要职','/t͡ʃɛə(ɹ)/','/t͡ʃɛəɹ/','noun',["All I need to weather a snowstorm is hot coffee, a warm fire, a good book and a comfortable chair.","My violin teacher used to play first chair with the Boston Pops.","Bob will chair tomorrow''s meeting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reasonable','adj.合理的，公道的；通情达理的','/ˈɹiː.zən.ə.bəl/','/ˈɹiː.zən.ə.bəl/','adjective',["a reasonable demand, amount, or price","$20 a bottle is very reasonable for a good wine at a restaurant.","The builders did a reasonable job, given the short notice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hide','v.隐藏；隐瞒；鞭打n.躲藏；兽皮；躲藏处','/haɪd/','/haɪd/','verb',["He hides his magazines under the bed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bye','int.再见n.轮空；次要的东西adj.次要的','/baɪ/','/baɪ/','noun',["Craig''s Crew plays the bye next week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sharpen','v.削尖；磨快；使敏捷；加重','','/ˈʃɑɹpɨn/','verb',["to sharpen a pencil or a knife or a musical note"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fantastic','adj.奇异的；空想的；异想天开的；古怪的；极好的，极出色的；不可思议的；不切实际的n.古怪的人','/fænˈtæstɪk/','/fænˈtæstɪk/','noun',["He told fantastic stories of dragons and goblins.","She entered the lab and stood gaping for a good ten minutes at the fantastic machinery at work all around her.","\"I had a simply fantastic vacation, and I can''t wait to tell you all about it!\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eraser','n.橡皮；擦除器；[计]清除器','/ɪˈɹeɪzə/','/ɪˈɹeɪzə/','noun',["I have worn out the eraser on this pencil."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chemical','n.化学制品，化学药品adj.化学的','/ˈkɛmɪkəl/','/ˈkɛmɪkəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ministry','n.（政府的）部门','/ˈmɪnɪstɹi/','/ˈmɪnɪstɹi/','noun',["She works for the ministry of finance.","The premier offered his last ministry''s resignation to the monarch, and is asked to form a new one in accordance with the election results.","the present ministry of the Holy Spirit"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sponsor','n.赞助者；主办者；保证人v.赞助；发起','/ˈspɒn.sə/','/ˈspɒn.sə/','noun',["He was my sponsor when I applied to join the club.","And now a word from our sponsor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nose','n.鼻子；嗅觉；突出的部分；探问v.嗅；用鼻子触','/nəʊz/','/noʊz/','noun',["She has a cold in the nose.","the nose of a tea-kettle, a bellows, or a fighter plane","Red Rum only won by a nose."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reserve','n.储备，储存；自然保护区；预备队；缄默；[金融]储备金v.储备；保留；预约','/ɹɪˈzɜːv/','/ɹɪˈzɝv/','noun',["We reserve the right to make modifications.","This cake is reserved for the guests!","I reserved a table for us at the best restaurant in town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('during','prep.在…的时候，在…的期间n.(During)人名；(法)迪兰；(瑞典、利比)杜林','/ˈdjɔː.ɹɪŋ/','/ˈd(j)ʊɚ.ɪŋ/','verb',["I lived with my parents during the 1970s.","I lived with my parents at several points during the 1980s."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corn','n.（美）玉米；（英）谷物；[皮肤]鸡眼v.腌；使成颗粒','/kɔɹn/','/kɔɹn/','noun',["He paid her the nominal fee of two corns of barley.","to corn gunpowder","Corn the horses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unfair','adj.不公平的，不公正的','/ʌnˈfɛə(ɹ)/','/ʌnˈfɛɚ/','verb',["It was unfair for the boss to give larger bonuses to his friends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('educate','v.教育；培养；训练','/ˈɛdjʊkeɪt/','/ˈɛdʒəkeɪt/','verb',["Wang said such changes to the Baishui glacier provide the chance to educate visitors about global warming."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrange','v.安排；排列；整理','/əˈɹeɪndʒ/','/əˈɹeɪndʒ/','verb',["to arrange to meet;   to arrange for supper"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rise','v.上升；增强；起立；高耸n.上升；高地；增加；出现','/ɹaɪs/','/ɹaɪs/','verb',["to rise a hill","to rise a fish, or cause it to come to the surface of the water"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('month','n.月，一个月的时间','/mʌnθ/','/mʌnθ/','noun',["July is my favourite month.","We went on holiday for two months."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competence','n.能力，胜任；权限；作证能力；足以过舒适生活的收入','/ˈkɒmpətəns/','/ˈkɒmpətəns/','noun',["That question is out with the competence of this court and must be taken to a higher court."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noon','n.中午；正午；全盛期','/nuːn/','/nuːn/','noun',["1885, When night was at its noon I heard a voice chanting the Koran in sweetest accents — Sir Richard Burton, The Book of the Thousand Nights and One Night, Night 17:"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glasshouse','n.温室；暖房','/ˈɡlɑːshaʊs/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('water','n.水；海水；雨水；海域，大片的水v.使湿；供以水；给…浇水','/ˈwɔːtə/','/ˈwɔtəɹ/','noun',["By the action of electricity, the water was resolved into its two parts, oxygen and hydrogen.","And God said, Let the waters under the heaven be gathered together unto one place, and let the dry land appear: and it was so.","The boat was found within the territorial waters."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('key','n.（打字机等的）键；关键；钥匙v.键入；锁上；调节…的音调；提供线索adj.关键的','/kiː/','/ki/','noun',["The key to solving this problem is persistence.","The key says that A stands for the accounting department.","Some students cheated by using the answer key."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lung','n.肺；呼吸器','/ˈlʌŋ/','/ˈlʌŋ/','noun',["He hasn''t the lungs to play long rallies like he use to."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sixty','num.六十；六十个','/ˈsɪkstɪ/','/ˈsɪksti/','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('January','n.一月','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fried','adj.油炸的，油煎的；喝醉了的v.油炸（fry的过去分词）','/fɹaɪd/','/fɹaɪd/','adjective',["He always ate his eggs fried, never scrambled.","a bucket of fried chicken","It looks like your motherboard is fried."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kilogram','n.公斤；千克','/ˈkɪləɡɹæm/','/ˈkɪləɡɹæm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smooth','adj.顺利的；光滑的；平稳的v.使光滑；消除（障碍等）；使优雅；缓和n.平滑部分；一块平地adv.光滑地；平稳地；流畅地','/smuːð/','/smuːð/','noun',["to smooth a person''s temper","Can I smooth your cat?","We hope for a smooth transition to the new system."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reviewer','n.评论者，评论家','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inside','n.里面；内部；内情；内脏adj.里面的；内部的；秘密的adv.在里面prep.少于；在…之内','/ɪnˈsaɪd/','/ɪnˈsaɪd/','noun',["The inside of the building has been extensively restored.","On a motorway, you should never pass another vehicle on the inside.","The car in front drifted wide on the bend, so I darted up the inside to take the lead."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('second','n.秒；第二名；瞬间；二等品v.支持adj.第二的；次要的；附加的num.第二adv.第二；其次；居第二位','/ˈsɛkɪnd/','/ˈsɛk.(ə)nd/','noun',["They were discounted because they contained blemishes, nicks or were otherwise factory seconds.","That was good barbecue. I hope I can get seconds.","I second the motion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('master','v.控制；精通；征服n.硕士；主人；大师；教师adj.主人的；主要的；熟练的','/ˈmastə/','/ˈmæstɚ/','noun',["Mark Twain was a master of fiction.","She has a master in psychology.","He is a master of marine biology."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('healthy','adj.健康的，健全的；有益于健康的','/ˈhɛl.θi/','/ˈhɛl.θi/','adjective',["He was father to three healthy kids.","A healthy diet and exercise can help to maintain proper weight.","Sam unwrapped the sandwich and took a healthy bite out of the middle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('file','n.文件；档案；文件夹；锉刀v.提出；锉；琢磨；把…归档','/faɪl/','/faɪl/','noun',["I''m going to delete these unwanted files to free up some disk space.","She filed for divorce the next day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seventh','n.第七；七分之一adj.第七的；七分之一的adv.居第七位地','/ˈsɛv.ənθ/','/ˈsɛv.ənθ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('college','n.大学；学院；学会','/ˈkɒlɪd͡ʒ/','/ˈkɑlɪd͡ʒ/','noun',["College of Cardinals, College of Surgeons","College of Engineering","These should be his college years, but he joined the Army."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liberty','n.自由；许可；冒失','/ˈlɪbɚti/','/ˈlɪbɚti/','noun',["The army is here, your liberty is assured.","The prisoners gained their liberty from an underground tunnel.","Everyone has the right to life, liberty and security of person."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blow','n.吹；打击；殴打v.风吹；喘气','/bləʊ/','/bloʊ/','noun',["We''re having a bit of a blow this afternoon.","The players were able to get a blow during the last timeout.","Blow the dust off that book and open it up."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('questionnaire','n.问卷；调查表','/ˌk(w)estjəˈnɛə/','/ˌk(w)estjəˈnɛə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Christmas','n.圣诞节；圣诞节期间','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('father','n.父亲，爸爸；神父；祖先；前辈v.发明，创立；当…的父亲','/ˈfɑːðə(ɹ)/','/ˈfɑðɚ/','noun',["My father was a strong influence on me.","Come, father; you can sit here.","My brother was a father to me after my parents got divorced."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everyone','pron.每个人；人人n.每个人','/ˈɛv.ɹi.wʌn/','/ˈɛv.ɹi.wʌn/','pronoun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mild','adj.温和的；轻微的；淡味的；文雅的；不含有害物质的的n.（英国的一种）淡味麦芽啤酒','/ˈmaɪld/','/ˈmaɪld/','noun',["a mild man","He received a mild sentence.","a mild day"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('could','aux.能够v.能（can的过去式）','/kʊd/','/kʊd/','verb',["She can speak English, French, and German.   I can play football.   Can you remember your fifth birthday?","You can go outside and play when you''re finished with your homework.   Can I use your pen?","Animals can experience emotions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('automatic','adj.自动的；无意识的；必然的n.自动机械；自动手枪','/ˌɔːtəˈmætɪk/','/ˌɔtəˈmætɪk/','noun',["I never learned to drive a stick. I can only drive an automatic.","The G-men raiding the speakeasy were equipped with .45 automatics, while the local policemen were carrying revolvers and shotguns.","The automatic clothes washer was a great labor-saving device."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('article','n.文章；物品；条款；[语]冠词v.订约将…收为学徒或见习生；使…受协议条款的约束','/ˈɑːtɪkəl/','/ˈɑɹtəkl̩/','noun',["a sales article","The Articles of War are a set of regulations to govern the conduct of military forces","Each of the chelicerae is composed of two articles, forming a powerful pincer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('link','n.[计]链环，环节；联系，关系v.连接，连结；联合，结合','/lɪŋk/','/lɪŋk/','noun',["Click the hyperlink to go to the next page.","Copy the hyperlink and paste it into an email.","The mayor’s assistant serves as the link to the media."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('CD','abbr.光盘，激光唱片（CompactDisc）；呼叫设备（CallingDevice）；中央地区（CentralDistrict）；商务部（CommerceDepartment）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('about','prep.关于；大约adj.在附近的；四处走动的；在起作用的adv.大约；周围；到处n.大致；粗枝大叶；不拘小节的人','/əˈbɛʊt/','/əˈbaʊt/','adjective',["After my bout with Guillan-Barre Syndrome, it took me 6 months to be up and about again.","This idea has been about for a while but has only recently become fashionable.","I had my keys just a minute ago, so they must be about somewhere."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('local','n.[计]局部；当地居民；本地新闻adj.当地的；局部的；地方性的；乡土的','/ˈləʊkl̩/','/ˈloʊkl̩/','noun',["It''s easy to tell the locals from the tourists.","I''m in the TWU, too. Local 6.","The expresses skipped my station, so I had to take a local."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hydrogen','n.[化学]氢','/ˈhaɪdɹədʒ(ə)n/','/ˈhaɪdɹədʒən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('backache','n.背痛；腰痛','/ˈbækeɪk/','/ˈbækeɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temptation','n.引诱；诱惑物','/tɛmpˈteɪʃən/','/tɛmpˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crayon','n.蜡笔，有色粉笔v.以蜡笔作画，用颜色粉笔画','/ˈkɹeɪ.ɒ̃/','/ˈkɹaʊn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fruit','n.水果；产物v.结果实','/fɹuːt/','/fɹut/','noun',["His long nights in the office eventually bore fruit when his business boomed and he was given a raise.","the fresh-squeezed fruit juice; a fruit salad; an artificial fruit flavor; a fruit tree; a fruit bat","Blessed art thou amongst women and blessed is the fruit of thy womb."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('learned','adj.博学的；有学问的；学术上的n.(Learned)人名；(英)勒尼德','/ˈlɜːnɪd/','/ˈlɜːnɪd/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rather','adv.宁可，宁愿；相当int.当然啦（回答问题时用）n.(Rather)人名；(英)拉瑟','/ˈɹɑːðə/','/ˈɹæðɚ/','verb',["I''d like this one rather than the other one.","It wasn''t supposed to be popular; rather, it was supposed to get the job done.","I didn''t want to leave. Or rather I did, just not alone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('job','n.工作；职业v.承包；代客买卖','/d͡ʒɒb/','/d͡ʒɑb/','noun',["A job half done is hardly done at all.","He''s been out of a job since being made redundant in January.","He had had a nose job."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mathematics','n.数学；数学运算','/mæθ(ə)ˈmætɪks/','/mæθ(ə)ˈmætɪks/','noun',["My mathematics is always improving."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occupation','n.职业；占有；消遣；占有期','/ɒkjəˈpeɪʃən/','/ɑkjəˈpeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consequence','n.结果；重要性；推论','/ˈkɒnsɪkwɛns/','/ˈkɑnsɪkwəns/','noun',["I''m warning you. If you don''t get me the report on time, there will be consequences."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('increase','n.增加，增长；提高v.增加，增大；繁殖','','','noun',["His rage only increased when I told him of the lost money.","The Moon increases."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forest','v.植树于，使成为森林n.森林','/ˈfɒɹɪst/','/ˈfɒɹɪst/','noun',["a forest of criticism"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relative','adj.相对的；有关系的；成比例的n.亲戚；相关物；[语]关系词；亲缘植物','[ˈɹɛl.ə.tʰɪv]','[ˈɹɛl.ə.tʰɪv]','noun',["Why do my relatives always talk about sex?","The relative URL /images/pic.jpg, when evaluated in the context of http://example.com/docs/pic.html, corresponds to the absolute URL http://example.com/images/pic.jpg.","relative to your earlier point about taxes, ..."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pupil','n.学生；[解剖]瞳孔；未成年人','/ˈpjuːpəl/','/ˈpjuːpəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visa','n.签证v.签发签证','/ˈviː.sə/','/ˈviː.sə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restriction','n.限制；约束；束缚','/ɹɪˈstɹɪkʃən/','/ɹɪˈstɹɪkʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fridge','n.电冰箱','/fɹɪd͡ʒ/','/fɹɪd͡ʒ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behind','prep.落后于；支持；晚于adv.在后地；在原处n.屁股','/bəˈhaɪnd/','/bəˈhaɪnd/','noun',["to look behind","I''m two weeks behind in my schedule.","My watch is four minutes behind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swing','n.摇摆；摆动；秋千；音律；涨落v.摇摆；转向；悬挂；大摇大摆地行走adj.旋转的；悬挂的；强节奏爵士音乐的','/ˈswɪŋ/','/ˈswɪŋ/','noun',["Door swing indicates direction the door opens.","The plant swung in the breeze.","The children laughed as they swung."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approach','n.方法；途径；接近v.接近；着手处理','/əˈpɹəʊt͡ʃ/','/əˈpɹoʊt͡ʃ/','noun',["1991, Carol Lee Johnston, Jeanne Lazaris, Plane Trigonometry, A New Approach.","as he approaches to the character of the ablest statesman.","\"Would counsel please approach the bench?\" asked the judge."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correct','v.改正；告诫adj.正确的；恰当的；端正的','/kəˈɹɛkt/','/kəˈɹɛkt/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('at','prep.在（表示存在或出现的地点、场所、位置、空间）；以（某种价格、速度等）；向；达；因为；朝；忙于n.阿特（老挝货币基本单位att）；[化]砹（极不稳定放射性元素）abbr.密封的（airtight）；气温（airtemperature）','','','verb',["Cars 2 is the most influential film of all time. Don''t @ me.","Caesar was at Rome;  at the corner of Fourth Street and Vine;  at Jim’s house","at six o’clock;  at closing time;  at night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pill','n.药丸；弹丸，子弹；口服避孕药v.把…制成丸剂；使服用药丸；抢劫，掠夺（古语）','/pɪl/','/pɪl/','noun',["Jane went on the pill when she left for college.","Pilling is a skill rarely used by modern pharmacists.","She pills herself with all sorts of herbal medicines."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underline','v.强调；在…下面划线；预告n.下划线；下期节目预告','/ˈʌndəˌlaɪn/','/ˈʌndɚˌlaɪn/','noun',["underline the important words in the text"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('team','n.队；组v.使合作','/tiːm/','/tiːm/','noun',["The IT manager leads a team of three software developers.","They teamed to complete the project.","to team lumber"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scholarship','n.奖学金；学识，学问','/ˈskɒləʃɪp/','/ˈskɒləʃɪp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('committee','n.委员会','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stick','v.刺，戳；伸出；粘贴n.棍；手杖；呆头呆脑的人','/stɪk/','/stɪk/','noun',["Sealing wax is available as a cylindrical or rectangular stick.","to stick type"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cowboy','n.牛仔；牧童；莽撞的人','/ˈkaʊˌbɔɪ/','/ˈkaʊˌbɔɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expectation','n.期待；预期；指望','/ɛkspɛkˈteɪʃən/','/ɛkspɛkˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unconditional','adj.无条件的；绝对的；无限制的','/ˌʌnkənˈdɪʃənəl/','/ˌʌnkənˈdɪʃənəl/','adjective',["We demand your unconditional surrender."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drier','n.干燥机；干燥剂；吹风机','/ˈdɹaɪə/','/ˈdɹaɪə/','noun',["The sun and a northwesterly wind are great driers of the earth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('end','n.结束；目标；尽头；末端；死亡v.结束，终止；终结','/ɛnd/','/ɛnd/','noun',["At the end of the road, turn left.","Is there no end to this madness?","He met a terrible end in the jungle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permission','n.允许，许可','/pəˈmɪʃən/','/pɚˈmɪʃən/','noun',["Sire, do I have your permission to execute this traitor?","I used the \"chmod\" command to change the file''s permission."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('use','n.使用；用途；发挥v.利用；耗费','','','noun',["The use of torture has been condemned by the United Nations.","What''s the use of a law that nobody follows?","This tool has many uses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hearing','n.听力；审讯，听讯v.听见（hear的ing形式）','/ˈhiːɹ.ɪŋ/','/ˈhɪɹ.ɪŋ/','verb',["I was deaf, and now I can hear.","I heard a sound from outside the window.","Eventually the king chose to hear her entreaties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('iron','n.熨斗；烙铁；坚强v.熨；用铁铸成adj.铁的；残酷的；刚强的','/ˈaɪən/','/ˈaɪɚn/','noun',["wrought iron, ductile iron, cast iron, pig iron, gray iron","He appeared easygoing, but inside he was pure iron.","He lifts iron on the weekends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reward','n.[劳经]报酬；报答；酬谢v.[劳经]奖励；奖赏','/ɹəˈwɔːd/','/ɹiˈwɔɹd/','noun',["For catching the thief, you''ll get a nice reward.","The rewards for bringing in badly wanted criminals are printed on ''dead or alive'' posters","Is this the reward I get for telling the truth: to be put in jail?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('signal','n.信号；暗号；导火线v.标志；用信号通知；表示adj.显著的；作为信号的','/ˈsɪɡnəl/','/ˈsɪɡnəl/','noun',["My mobile phone can''t get a signal in the railway station.","Seeing the flames, he ran to the control room and signalled headquarters.","a signal exploit; a signal service; a signal act of benevolence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oneself','pron.自己；亲自','/wʌnˈsɛlf/','/wʌnˈsɛlf/','pronoun',["Teaching oneself to swim can be dangerous."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('argument','n.论证；论据；争吵；内容提要','/ˈɑːɡjʊmənt/','/ˈɑɹɡjumənt/','noun',["Parameters are like labeled fillable blanks used to define a function whereas arguments are passed to a function when calling it, filling in those blanks.","The altitude is the argument of the refraction."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('character','n.性格，品质；特性；角色；[计]字符v.印，刻；使具有特征','/ˈkæɹəktə/','/ˈkæɹəktɚ/','noun',["A single locus governing the petal colour character was detected on the linkage group A2.","A study of the suspect''s character and his cast iron alibi ruled him out.","\"You may not like to eat liver,\" said Calvin''s father, \"but it builds character.\""]);
