INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('improve','v.改善，增进；提高…的价值','/ɪmˈpɹuːv/','/ɪmˈpɹuːv/','verb',["Buying more servers would improve performance.","I have improved since taking the tablets.","to improve negligence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fail','v.失败，不及格；破产；缺乏；衰退n.不及格','/feɪl/','/feɪl/','noun',["The project was full of fail.","Throughout my life, I have always failed.","The truck failed to start."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scholar','n.学者；奖学金获得者','/ˈskɒlə/','/ˈskɒlə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('require','v.需要；要求；命令','/ɹɪˈkwaɪə/','/ɹɪˈkwaɪɹ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mention','v.提到，谈到；提及，论及；说起n.提及，说起','/ˈmɛnʃən/','/ˈmɛnʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eight','num.八；八个；第八adj.八的n.八字形','/eɪt/','/eɪt/','noun',["He works eight hours a day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attention','n.注意力；关心；立正！（口令）','/əˈtɛn.ʃən/','/əˈtɛn.ʃən/','noun',["Please direct your attention to the following words.","The company will now come to attention."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decline','n.下降；衰退；斜面v.下降；衰落；谢绝','/dɪˈklaɪn/','/dɪˈklaɪn/','noun',["The dollar has declined rapidly since 2001.","My health declined in winter.","a line that declines from straightness"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skillfully','adv.巧妙地；精巧地','','','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cat','n.猫，猫科动物','/kat/','/kæt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('last','n.末尾，最后；上个；鞋楦（做鞋的模型）adj.最后的；最近的，最新的；仅剩的；最不可能…的v.持续；维持，够用；持久adv.最后地；上次，最近；最后一点','/last/','/læst/','adjective',["“Eyes Wide Shut” was the last film to be directed by Stanley Kubrick.","I have received your note dated the 17th last, and am responding to say that","He is the last person to be accused of theft."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yourself','pron.你自己','/jɔːˈsɛlf/','/jɔɹˈsɛlf/','pronoun',["Be careful with that fire or you''ll burn yourself.","After a good night''s sleep you''ll feel like yourself again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('like','v.喜欢；想；愿意prep.像；如同adj.同样的；相似的n.爱好；同样的人或物adv.可能conj.好像','/laɪk/','/laɪk/','noun',["Tell me your likes and dislikes.","I like hamburgers.","I like to go to the dentist every six months."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('west','n.西；西方；西部adj.西方的；朝西的adv.在西方；向西方；自西方','/wɛst/','/wɛst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surgeon','n.外科医生','/ˈsɜːdʒən/','/ˈsɜːdʒən/','noun',["The surgeon refused to operate because the patient was her son."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flow','v.流动，涌流；川流不息；飘扬n.流动；流量；涨潮，泛滥','/fləʊ/','/floʊ/','noun',["The notion of flow is basic to the study of ordinary differential equations.","The room was small, but it had good symmetry and flow.","Other devices measure water flow in streams fed by melted ice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congratulate','v.祝贺；恭喜；庆贺','/-t͡ʃə-/','/-d͡ʒə-/','verb',["Remind me to congratulate Dave and Lisa on their wedding.","I congratulated myself on the success of my plan."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whole','adj.完整的；纯粹的n.整体；全部','/həʊl/','/hoʊl/','noun',["This variety of fascinating details didn''t fall together into an enjoyable, coherent whole.","I ate a whole fish.","He is of whole mind, but the same cannot be said about his physical state."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Miss','n.女士，小姐，年轻未婚女子','/mɪs/','/mɪs/','noun',["I think I’ll give the meeting a miss.","I missed the target.","to miss an opportunity"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brief','adj.简短的，简洁的；短暂的，草率的n.摘要，简报；概要，诉书v.简报，摘要；作…的提要','/bɹiːf/','/bɹiːf/','noun',["We got a news brief.","I wear boxers under trousers but for sports I usually wear a brief.","The U.S. president was briefed on the military coup and its implications on African stability."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('animal','n.动物','/ˈænɪməl/','/ˈænɪməl/','noun',["A cat is an animal, not a plant. Humans are also animals, under the scientific definition, as we are not plants.","My students are animals.","He''s a political animal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('question','n.问题，疑问；询问；疑问句v.询问；怀疑；审问','/ˈkwɛstjən/','/ˈkwɛstjən/','noun',["What is your question?","The question of seniority will be discussed at the meeting.","He obeyed without question."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inn','n.客栈；旅馆vi.住旅馆','/ɪn/','/ɪn/','noun',["the Inns of Court; the Inns of Chancery; Serjeants'' Inns","Leicester Inn"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polish','n.磨光，擦亮；擦亮剂；优雅，精良v.擦亮，变光滑adj.波兰的','/ˈpɒlɪʃ/','/ˈpɑlɪʃ/','noun',["A good silver polish will remove tarnish easily.","The floor was waxed to a high polish.","The lecturer showed a lot of polish at his last talk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('principle','n.原理，原则；主义，道义；本质，本义；根源，源泉','/ˈpɹɪnsəpəl/','/ˈpɹɪnsəpəl/','noun',["We need some sort of principles to reason from.","The principle of least privilege holds that a process should only receive the permissions it needs.","I don''t doubt your principles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('satisfaction','n.满意，满足；赔偿；乐事；赎罪','/sætɪsˈfækʃən/','/sætɪsˈfækʃən/','noun',["He enjoyed the dish with great satisfaction. He''ll order it again the next time he arrives.","The count demanded satisfaction in the form of a duel at dawn."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clean','adj.清洁的，干净的；清白的v.使干净adv.完全地n.打扫','/kliːn/','/klin/','noun',["This place needs a clean.","Can you clean the windows today?","Clean your room right now!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reputation','n.名声，名誉；声望','/ˌɹɛpjʊˈteɪʃən/','/ˌɹɛpjʊˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belly','n.腹部；胃；食欲v.涨满；鼓起','/bɛli/','/bɛli/','noun',["the belly of a flask, muscle, violin, sail, or ship"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suck','v.吸吮；吸取n.吮吸','/sʌk/','/sʌk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toilet','n.厕所，盥洗室；梳妆，打扮vi.梳妆，打扮vt.给…梳妆打扮','/ˈtɔɪ.lət/','/ˈtɔɪ.lət/','noun',["Sorry, I was in the toilet.","My toilet backed up. Now the bathroom''s flooded."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bacon','n.咸肉；腌肉；熏猪肉','/ˈbeɪ.kən/','/ˈbeɪ.kən/','noun',["Run! It''s the bacon!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poison','v.污染；使中毒，放毒于；败坏；阻碍n.毒药，毒物；酒；有毒害的事物；[助剂]抑制剂adj.有毒的','/ˈpɔɪz(ə)n/','/ˈpɔɪz(ə)n/','noun',["We used a poison to kill the weeds.","Gossip is a malicious poison.","— I''ll have a glass of whisky."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motorbike','n.摩托车','','','noun',["We motorbiked all over the US that summer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sink','v.下沉；消沉；渗透n.水槽；洗涤槽；污水坑','/sɪŋk/','/sɪŋk/','noun',["Jones has a two-seamer with heavy sink.","I have sunk thousands of pounds into this project.","to sink the national debt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tongue','n.舌头；语言v.舔；斥责；用舌吹','/tɒŋɡ/','/tʌŋ/','noun',["cold tongue with mustard","He was speaking in his native tongue.","Playing wind instruments involves tonguing on the reed or mouthpiece."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violin','n.小提琴；小提琴手','/ˌvɑe.ɘˈlɘn/','/ˌvaɪəˈlɪn/','noun',["The first violin often plays the lead melody lines in a string quartet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delicate','adj.微妙的；精美的，雅致的；柔和的；易碎的；纤弱的；清淡可口的','/ˈdɛlɪkət/','/ˈdɛlɪkət/','noun',["Don''t put that in with your jeans: it''s a delicate!","The negotiations were very delicate.","Her face was delicate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embassy','n.大使馆；大使馆全体人员','/ˈɛmbəsi/','/ˈɛmbəsi/','noun',["The American embassy to France is located in Paris."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('error','n.误差；错误；过失','/ˈɛɹə(ɹ)/','/ˈɛɹɚ/','noun',["Remove that line of code and the script should stop erroring there.","The block transmission errored near the start and could not be received."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disadvantage','n.缺点；不利条件；损失','/ˌdɪsədˈvɑːntɪdʒ/','/ˌdɪsədˈvɑːntɪdʒ/','noun',["The disadvantage to owning a food processor is that you have to store it somewhere.","My height is a disadvantage for reaching high shelves.","They fear it might disadvantage honest participants to allow automated entries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('green','adj.绿色的；青春的n.绿色；青春v.使…变绿色','/ɡɹiːn/','/ɡɹin/','adjective',["The former flag of Libya is fully green.","Sally looks pretty green — is she going to be sick?","John''s kind of green, so take it easy on him this first week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seek','v.寻求；寻找；探索；搜索','/siːk/','/siːk/','noun',["I seek wisdom.","I seek forgiveness through prayer.","I sought my fortune on the goldfields."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maybe','adv.也许；可能；大概n.可能性；不确定性','/ˈmeɪbi/','/ˈmeɪbi/','noun',["The results of the poll were inconclusive. We got two yeses, three nos, and four maybes.","About your raise: it''s a big maybe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graph','n.图表；曲线图v.用曲线图表示','/ɡɹæf/','/ɡɹæf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recipe','n.食谱；[临床]处方；秘诀；烹饪法','/ˈɹɛs.ə.pi/','/ˈɹɛs.ə.pi/','noun',["His new approach is definitely a recipe for success.","Stepper recipes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laser','n.激光','/ˈleɪz.ə(ɹ)/','/ˈleɪz.ə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entrance','n.入口；进入v.使出神，使入迷','/ˈɛn.tɹəns/','/ˈɛn.tɹəns/','noun',["Her entrance attracted no attention whatsoever.","the entrance of an heir upon his inheritance, or of a magistrate into office","Place your bag by the entrance so that you can find it easily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rent','n.租金v.出租；租用；租借','/ɹɛnt/','/ɹɛnt/','noun',["A New York city taxicab license earns more than $10,000 a year in rent.","I rented a house from my friend''s parents for a year.","We rented our house to our son''s friend for a year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('match','v.使比赛；使相配；敌得过，比得上；相配；与…竞争n.比赛，竞赛；匹配；对手；火柴','/mæt͡ʃ/','/mæt͡ʃ/','noun',["My local team are playing in a match against their arch-rivals today.","He knew he had met his match.","The carpet and curtains are a match."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('very','adj.恰好是，正是；甚至；十足的；特有的adv.非常，很；完全n.(Very)人名；(英)维里','/ˈvɛɹi/','/ˈvɛɹi/','adjective',["He tried his very best.","He proposed marriage in the same restaurant, at the very table where they first met.","Not very many (of them) had been damaged."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('raw','adj.生的；未加工的；阴冷的；刺痛的；擦掉皮的；无经验的；（在艺术等方面）不成熟的n.擦伤处vt.擦伤','/ɹɔː/','/ɹɔː/','noun',["raw cane sugar","a raw wound","a raw beginner"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absurd','adj.荒谬的；可笑的n.荒诞；荒诞作品','/æbˈzɝd/','/æbˈsɝd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possibility','n.可能性；可能发生的事物','/ˌpɒsɪˈbɪliti/','/ˌpɑsɪˈbɪliti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garage','n.车库；汽车修理厂；飞机库v.把……送入车库；把（汽车）开进车库','/ˈɡæɹɑː(d)ʒ/','/ɡəˈɹɑː(d)ʒ/','noun',["We garaged the convertible during the monsoon months."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oxygen','n.[化学]氧气，[化学]氧','/ˈɒksɪdʒən/','/ˈɒksɪdʒən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goat','n.山羊；替罪羊（美俚）；色鬼（美俚）','/ɡɐ̟ʉt/','/ɡoʊt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radiation','n.辐射；发光；放射物','/ɹaɪ.di.ˈaɪ.ʃən/','/ɹaɪ.di.ˈaɪ.ʃən/','noun',["heat radiation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fog','n.雾；烟雾，尘雾；迷惑v.使模糊；使困惑；以雾笼罩','/fɒɡ/','/fɑɡ/','noun',["He did so many drugs, he was still in a fog three months after going through detox.","The mirror fogged every time he showered."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('host','n.[计]主机；主人；主持人；许多v.主持；当主人招待','/həʊst/','/hoʊst/','noun',["A good host is always considerate of the guest’s needs.","Our company is host of the annual conference this year.","The host was terrible, but the acts themselves were good."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amazing','adj.令人惊异的v.使吃惊（amaze的ing形式）','/əˈmeɪzɪŋ/','/əˈmeɪzɪŋ/','verb',["He was amazed when he found that the girl was a robot.","2015, June 10, Lindsey Bever, \"Morning Mix: Another reason seeing-eye dogs are amazing\"http//www.washingtonpost.com/news/morning-mix/wp/2015/06/10/another-heroic-story-showing-why-seeing-eye-dogs-are-amazing/"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outdoors','adv.在户外n.户外adj.户外的（等于outdoor）','','','noun',["She loves the outdoors.","They went outdoors to light up their cigarettes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('progress','n.进步，发展；前进v.前进，进步；进行','/ˈpɹɒɡɹɛs/','/ˈpɹoʊɡɹɛs/','noun',["Testing for the new antidote is currently in progress.","Science has made extraordinary progress in the last fifty years.","The thick branches overhanging the path made progress difficult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('authentic','adj.真正的，真实的；可信的','/ɒ.ˈθɛn.tɪk/','/ɒ.ˈθɛn.tɪk/','adjective',["The experts confirmed it was an authentic signature.","The report was completely authentic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('omelette','n.煎蛋卷','/ˈɒm.lɪt/','/ˈɔm.lət/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headmistress','n.女校长','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trip','v.绊倒；远足；犯错误；轻快地走n.旅行；绊倒；差错','/tɹɪp/','/tɹɪp/','noun',["We made a trip to the beach.","He was injured due to a trip down the stairs.","He had a strange trip after taking LSD."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transport','n.运输；运输机；狂喜；流放犯v.运输；流放；使狂喜','','','noun',["The transport of goods is not included in the price given on the website.","The local transport received a big boost as part of the mayor''s infrastructural plans.","to transport goods; to transport troops"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erupt','v.爆发；喷出；发疹；长牙','/ɪˈɹʌpt/','/ɪˈɹʌpt/','verb',["The volcano erupted, spewing lava across a wide area.","The third molar tooth erupts late in most people, and sometimes does not appear at all.","The crowd erupted in anger."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forgetful','adj.健忘的；不注意的；疏忽的；使遗忘的','','','adjective',["a forgetful mapping; a forgetful functor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sir','n.先生；（用于姓名前）爵士；阁下；（中小学生对男教师的称呼）先生；老师','/ˈsə(ɹ)/','/ˈsɝ/','noun',["Excuse me, sir, do you know the way to the art museum?","Sir, yes, sir!\nDon''t you sir me, private! I work for a living!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('friend','n.朋友；助手；赞助者','/fɹɛnd/','/fɹɛnd/','noun',["John and I have been friends ever since we were roommates at college.   Trust is important between friends.   I used to find it hard to make friends when I was shy.","The Automobile Association is every motorist''s friend.   The police is every law-abiding citizen''s friend.","a friend of a friend;  I added him as a friend on Facebook, but I hardly know him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('holiday','n.假日；节日；休息日v.外出度假','/ˈhɒlɪdeɪ/','/ˈhɑləˌdeɪ/','noun',["Today is a Wiccan holiday!","I want to take a French course this summer holiday.","a mortgage payment holiday"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drink','v.喝，饮；吸收；举杯庆贺n.酒，饮料；喝酒','/dɹɪŋk/','/dɹɪŋk/','verb',["He drank the water I gave him.","Jack drank the whole bottle by himself.","Everyone who is drinking is drinking, but not everyone who is drinking is drinking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commercial','adj.商业的；营利的；靠广告收入的n.商业广告','/kəˈmɜːʃəl/','/kəˈmɝʃəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whenever','conj.每当；无论何时adv.不论何时；随便什么时候','/wəˈnɛvə/','/hwəˈnɛvɚ/','adverb',["Whenever will I find time to finish that jigsaw?","Feel free to visit whenever.","Visit whenever you want to."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emperor','n.皇帝，君主','/ˈempɘɹɘ/','/ˈɛmpəɹɚ/','noun',["The Investiture Controversy was a conflict between the Emperor and the Pope."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bingo','n.宾戈游戏','/ˈbɪŋ.ɡəʊ/','/ˈbɪŋ.ɡoʊ/','noun',["There were two bingos in the last game, so the players split the prize money."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('operator','n.经营者；操作员；话务员；行家','/ˈɒpəˌɹeɪtə/','/ˈɒpəˌɹeɪtə/','noun',["In the sentence \"What did Bill say he wants to buy?\", \"what\" is an operator, binding a phonetically empty variable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apology','n.道歉；谢罪；辩护；勉强的替代物','/əˈpɒl.ə.dʒi/','/əˈpɒl.ə.dʒi/','noun',["The CEO made a public apology for the scandal, and promised full cooperation with the authorities.","The Apology of Socrates.","a poor apology for a hotel room"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pure','adj.纯的；纯粹的；纯洁的；清白的；纯理论的n.(Pure)人名；(俄)普雷','/ˈpjɔː/','/ˈpjɔɹ/','noun',["Tiger Woods pured his first drive straight down the middle of the fairway.","That idea is pure madness!","You’re pure busy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devotion','n.献身，奉献；忠诚；热爱','/dɪˈvəʊʃən/','/dɪˈvoʊʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grade','n.年级；等级；成绩；级别；阶段v.评分；把…分等级','/ɡɹeɪd/','/ɡɹeɪd/','noun',["I gave him a good grade for effort.","He got a good grade on the test.","The grade of this hill is more than 5 percent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('now','adv.现在；如今；立刻adj.现在的n.现在；目前conj.由于；既然','/naʊ/','/naʊ/','noun',["Now is the right time.","She is living in the now.","I think this band''s sound is very now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wounded','adj.受伤的n.受伤者，伤员v.使受伤（wound的过去分词）','/ˈwuːndɪd/','/ˈwuːndɪd/','verb',["The police officer wounded the suspect during the fight that ensued.","The actor''s pride was wounded when the leading role went to his rival.","A wounded soldier."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hen','n.母鸡；女人；雌禽','/hɛn/','/hɛn/','noun',["Don''t cry, hen. Everything will be all right."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opposite','adj.相反的；对面的；对立的n.对立面；反义词prep.在…的对面adv.在对面','/ˈɒpəsɪt/','/ˈɑp(ə)sɪt/','noun',["\"Up\" is the opposite of \"down\".","She saw him walking on the opposite side of the road.","They were moving in opposite directions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profit','n.利润；利益v.获利；有益','/ˈpɹɒfɪt/','/ˈpɹɑfɪt/','noun',["Reading such an enlightening book on the subject was of much profit to his studies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('courage','n.勇气；胆量','/ˈkʌɹɪdʒ/','/ˈkɝɹɪdʒ/','noun',["It takes a lot of courage to be successful in business.","He plucked up the courage to tell her how he felt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outstanding','adj.杰出的；显著的；未解决的；未偿付的n.未偿贷款','','','verb',["outstanding contracts"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shelter','n.庇护；避难所；遮盖物v.保护；使掩蔽','/ˈʃɛltə/','/ˈʃɛltɚ/','noun',["During the rainstorm, we sheltered under a tree."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('look','v.看；期待；注意；面向；看上去像n.看；样子；面容','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coast','v.滑行；沿岸航行n.海岸；滑坡','/kəʊst/','/koʊst/','noun',["The rocky coast of Maine has few beaches.","When I ran out of gas, fortunately I managed to coast into a nearby gas station."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignore','v.驳回诉讼；忽视；不理睬','/ɪɡˈnɔː/','/ɪɡˈnɔɹ/','verb',["A problem ignored is a problem doubled."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('different','adj.不同的；个别的，与众不同的','/ˈdɪf.(ə)ɹ.ənt/','/ˈdɪf.(ə)ɹ.ənt/','noun',["Several different scientists all reached this conclusion at about the same time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('real','adj.实际的；真实的；实在的adv.真正地；确实地n.现实；实数','/ɹiːl/','/ɹiːl/','noun',["This is real leather.","These are real tears!","a description of real life"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typical','adj.典型的；特有的；象征性的','/ˈtɪpɪkl̩/','/ˈtɪpɪkl̩/','noun',["Among the moths, typicals were more common than melanics."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handy','adj.便利的；手边的，就近的；容易取得的；敏捷的n.(Handy)人名；(英)汉迪','/ˈhæn.di/','/ˈhæn.di/','adjective',["Some people regard duct tape as a handy fix-all.","I keep a first-aid kit handy in case of emergency.","She''s very handy: she made all her own kitchen cupboards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('broken','adj.破碎的；坏掉的v.折断；打碎；损坏（break的过去分词）','/ˈbɹəʊkən/','/ˈbɹəʊkən/','verb',["If the vase falls to the floor, it might break.","Can you break a hundred-dollar bill for me?","Her child''s death broke Angela."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aloud','adv.大声地；出声地','/əˈlaʊd/','/əˈlaʊd/','adjective',["Try speaking aloud rather than whispering.","speaking aloud rather than thinking thoughts privately"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appear','v.出现；显得；似乎；出庭；登场','/əˈpiːɹ/','/əˈpiɹ/','verb',["A great writer appeared at that time.","He appeared quite happy with the result."]);
