INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yummy','adj.好吃的；美味的；愉快的n.美味的东西；令人喜爱的东西','/ˈjʌm.i/','/ˈjʌm.i/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('midnight','n.午夜，半夜12点钟adj.半夜的；漆黑的','/ˈmɪdnʌɪt/','/ˈmɪdˌnaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('addition','n.添加；[数]加法；增加物','/æˈdɪʃən/','/æˈdɪʃən/','noun',["The addition of five more items to the agenda will make the meeting unbearably long."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weatherman','n.气象员；天气预报员','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permit','v.许可；允许n.许可证，执照','','','noun',["A construction permit can be obtained from the town offices.","The Building Department permitted that project last week.","We''ve been busy permitting the State Street development."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hand','n.手，手艺；帮助；指针；插手v.传递，交给；支持；搀扶','/hænd/','/hænd/','noun',["Her hands are really strong.","an old hand at speaking;  large farms need many farm hands","Bob gave Alice a hand to move the furniture."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obtain','v.获得；流行','/əbˈteɪn/','/əbˈteɪn/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prize','n.奖品；奖赏；战利品v.珍视；捕获；估价adj.获奖的','/pɹaɪz/','/pɹaɪz/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('content','n.内容，目录；满足；容量adj.满意的v.使满足','/kənˈtɛnt/','/kənˈtɛnt/','noun',["You can''t have any more - you''ll have to content yourself with what you already have."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('firmly','adv.坚定地，坚决地；坚固地，稳固地','/fɜːmli/','/fɝmli/','adverb',["She corrected him firmly but gently.","Tie the rope firmly to the post."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('colour','v.把…涂颜色，粉饰；歪曲；使脸红n.颜色；风格；气色，面色；外貌','','','noun',["Humans and birds can perceive color.","The artist took out her colors and began work on a landscape.","Color has been a sensitive issue in many societies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tired','adj.疲倦的；厌倦的，厌烦的v.疲倦；对…腻烦（tire的过去分词形式）','/taɪəd/','/taɪɚd/','verb',["I tire of this book.","I''m tired of this","a tired song"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vague','adj.模糊的；含糊的；不明确的；暧昧的n.(Vague)人名；(法)瓦格；(英)韦格','/veɪɡ/','/veɪɡ/','noun',["a vague term of abuse","I haven’t the vaguest idea.","a vague longing"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classic','adj.经典的；古典的，传统的；最优秀的n.名著；经典著作；大艺术家','/ˈklæ.sɪk/','/ˈklæ.sɪk/','noun',["Users who dislike the new visual layout can return to classic mode."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concern','v.涉及，关系到；使担心n.关系；关心；关心的事；忧虑','/kənˈsɜːn/','/kənˈsɝn/','noun',["Judy''s eyes filled with concern as she listened to the news report.","The employees’ attitude is really hurting the concern.","A good prince concerns himself in the happiness of his subjects."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talent','n.才能；天才；天资','/ˈtalənt/','/ˈtælənt/','noun',["He has a real talent for drawing.","The director searched their talent pool to fill the new opening.","Not much talent in this bar tonight—let''s hit the clubs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('several','adj.几个的；各自的pron.几个；数个','/ˈsɛv(ə)ɹəl/','/ˈsɛv(ə)ɹəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simply','adv.简单地；仅仅；简直；朴素地；坦白地','/ˈsɪmpli/','/ˈsɪmpli/','adverb',["I was simply asking a question.","That was a simply wonderful dessert.","Simply, he just fired you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('India','n.印度（南亚国家）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acre','n.土地，地产；英亩','/ˈeɪ.kə/','/ˈeɪ.kɚ/','noun',["I like my new house - there’s acres of space!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('potato','n.[作物]土豆，[作物]马铃薯','/pəˈteɪ.təʊ/','/pəˈteɪ.təʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adopt','v.采取；接受；收养；正式通过','/əˈdɒpt/','/əˈdɑpt/','verb',["He adopted a new look in order to fit in with his new workmates.","These resolutions were adopted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knee','n.膝盖，膝v.用膝盖碰','/niː/','/ni/','noun',["Penny was wearing a miniskirt, so she skinned her exposed knees when she fell.","To make a knee.","the knee of a graph"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('newspaper','n.报纸','/ˈnjuːsˌpeɪpə/','/ˈn(j)uzˌpeɪpɚ/','noun',["She newspapered one end of the room before painting the bookcase.","He newspapered his way through the South on the sports beat, avoiding dry towns.","He was newspapered out of public life."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uniform','adj.统一的；一致的；相同的；均衡的；始终如一的n.制服v.使穿制服；使成一样','/ˈjuːnɪfɔːm/','/ˈjunəfɚm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('support','v.支持，支撑，支援；扶持，帮助；赡养，供养n.支持，维持；支援，供养；支持者，支撑物','/səˈpɔːt/','/səˈpɔɹt/','noun',["Don''t move that beam! It''s a support for the whole platform.","The government provides support to the arts in several ways.","Sure they sell the product, but do they provide support?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conservation','n.保存，保持；保护','/ˌkɑnsə(ɹ)ˈveɪʃən/','/ˌkɑnsə(ɹ)ˈveɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fundamental','adj.基本的，根本的n.基本原理；基本原则','/ˌfʌndəˈmɛntəl/','/ˌfʌndəˈmɛntəl/','noun',["one of the fundamentals of linear algebra","A need for belonging seems fundamental to humans."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wayside','n.路旁adj.路旁的','','','noun',["Many wild flowers grew on the wayside.","We stopped at a wayside pub."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('request','n.请求；需要v.要求，请求','/ɹɪˈkwɛst/','/ɹɪˈkwɛst/','noun',["The server returned a 404 error to the HTTP request.","I have requested that the furniture be moved back to its original position.","She called me into her office and requested me to sit down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coke','n.焦炭；可卡因；可口可乐（Coca-Cola）v.焦化','/kəʊk/','/kəʊk/','noun',["The plant should produce approximately 550,000 tons of screened blast furnace coke per year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('between','prep.在…之间adv.在中间','/bɪˈtwiːn/','/bəˈtwin/','noun',["I want to buy one that costs somewhere between forty and fifty dollars.","conversation between friends","Between you and me, I think the boss is crazy.  Let''s keep this between ourselves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opener','n.[五金]开启工具；开启的人','/ˈəʊpənə/','/ˈəʊpənə/','noun',["The late-night openers in the mall include two restaurants and a clothing store."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('credit','n.信用，信誉；[金融]贷款；学分；信任；声望v.相信，信任；把…归给，归功于；赞颂','/ˈkɹɛdɪt/','/ˈkɹɛdɪt/','noun',["He arrived five minutes late, but to his credit he did work an extra ten minutes at the end of his shift.","She received a singing credit in last year''s operetta.","They kissed, and then the credits rolled."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absorb','v.吸收；吸引；承受；理解；使…全神贯注','/əbˈsɔːb/','/æbˈsɔɹb/','verb',["Heat, light, and electricity are absorbed in the substances into which they pass."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('multiply','v.乘；使增加；使繁殖；使相乘adv.多样地；复合地adj.多层的；多样的','/ˈmʌltɪplaɪ/','/ˈmʌltɪplaɪ/','noun',["when you multiply 3 by 7, you get 21;  he multiplied several numbers","He had been multiplying, but it occurred to him he needed to resolve the exponents, first."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chocolate','n.巧克力，巧克力糖；巧克力色adj.巧克力色的；巧克力口味的','/t͡ʃɔk(ə)lət/','/ˈt͡ʃɔk(ə)lɪt/','noun',["Chocolate is a very popular treat.","He bought her some chocolates as a gift. She ate one chocolate and threw the rest away.","As he cooked it the whole thing turned a rich, deep chocolate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ball','n.球；舞会v.成团块','/bɔːl/','/bɔːl/','noun',["a ball of spittle; a fecal ball","to ball cotton","The horse balls; the snow balls."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheque','n.支票','/tʃɛk/','/tʃɛk/','noun',["I was not carrying cash, so I wrote a cheque for the amount."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Russia','n.俄罗斯','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Tibetan','adj.西藏的；藏族的n.藏语；西藏人','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temple','n.庙宇；寺院；神殿；太阳穴','/ˈtɛmp(ə)l/','/ˈtɛmp(ə)l/','noun',["a temple of commerce, a temple of drinking and dining","My body is my temple."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fire','n.火；火灾；炮火；炉火；热情；激情；磨难v.点燃；解雇；开除；使发光；烧制；激动；放枪','/ˈfɑeə(ɹ)/','/ˈfaɪɚ/','noun',["We sat about the fire singing songs and telling tales.","During hot and dry summers many fires in forests are caused by regardlessly discarded cigarette butts.","The fire was laid and needed to be lit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excite','v.激起；刺激…，使…兴奋','/ɪkˈsaɪt/','/ɪkˈsaɪt/','verb',["The fireworks which opened the festivities excited anyone present.","Favoritism tends to excite jealousy in the ones not being favored.","By applying electric potential to the neon atoms, the electrons become excited, then emit a photon when returning to normal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parcel','n.包裹，小包v.打包；捆扎','[ˈpʰaː.səɫ]','[ˈpʰɑɹ.səɫ]','noun',["I saw a brown paper parcel on my doorstep.","I own a small parcel of land between the refinery and the fish cannery.","A certain piece of land is part and parcel of another piece."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ability','n.能力，能耐；才能','/əˈ.bɪl.ɪ.ti/','/əˈ.bɪl.ɪ.ti/','noun',["This phone has the ability to have its software upgraded wirelessly.","She has an uncanny ability to defuse conflict."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leave','v.离开；留下；遗忘；委托n.许可，同意；休假','/liːv/','/liv/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handle','n.[建]把手；柄；手感；口实v.处理；操作；运用；买卖；触摸','/ˈhæn.dl/','/ˈhæn.dl/','noun',["The daily handle of a Las Vegas casino is typically millions of dollars.","The successful businessman was knighted and acquired a handle to his name.","This article describes how to find the module name from the window handle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flashlight','n.手电筒；闪光灯','/ˈflæʃˌlaɪt/','/ˈflæʃˌlaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keyboard','n.键盘v.键入；用键盘式排字机排字','/ˈkiːbɔːd/','/ˈkibɔɹd/','noun',["Keyboarding is the part of this job I hate the most."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candidate','n.候选人，候补者；应试者','/ˈkæn.dɪdət/','/ˈkæn.dɪ.deɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('photograph','v.为…拍照；使深深印入n.照片，相片','/ˈfəʊ.tə.ˌɡɹɑːf/','/ˈfoʊ.tə.ˌɡɹæf/','noun',["She photographs well. The camera loves her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glass','n.玻璃；玻璃制品；镜子v.反映；给某物加玻璃','/ɡlɑːs/','/ɡlæs/','verb',["to fibreglass the hull of a fishing-boat","A popular myth is that window glass is actually an extremely viscous liquid.","Fill my glass with milk, please."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tradition','n.惯例，传统；传说','/tɹəˈdɪʃn̩/','/tɹəˈdɪʃn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('these','pron.这些adj.这些的','/ðiːz/','/ðiz/','pronoun',["This isn''t the item that I ordered."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unlike','adj.不同的，不相似的prep.和…不同，不像','/ʌnˈlaɪk/','/ʌnˈlaɪk/','noun',["The brothers are quite unlike each other.","They contributed in unlike amounts.","Being late is unlike him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seldom','adv.很少，不常','/ˈsɛldəm/','/ˈsɛldəm/','adjective',["They seldom come here now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('please','v.使喜欢；使高兴，使满意int.请（礼貌用语）','/pliːz/','/pliz/','verb',["Her presentation pleased the executives.","Just do as you please."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overcome','v.克服；胜过','/ˌəʊvəˈkʌm/','/ˌoʊvəɹˈkʌm/','noun',["to overcome enemies in battle","We shall overcome.","I was overcome with anger."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('except','v.不计；把…除外prep.除…之外conj.除了；要不是','/ɪkˈsɛpt/','/ɛkˈsɛpt/','verb',["to except to a witness or his testimony","There was nothing in the cupboard except a tin of beans.","I never made fun of her except teasingly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advocate','v.提倡，主张，拥护n.提倡者；支持者；律师','/ˈæd.və.keɪt/','/ˈæd.və.keɪt/','noun',["Since she started working with her advocate, she has become much more confident.","I like trees, but I do not advocate living in them.","We have been advocating for changes in immigration law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mountainous','adj.多山的；巨大的；山一般的','/ˈmaʊntɪnəs/','/ˈmaʊntɪnəs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('four','num.四；四个adj.四的；四个的n.(Four)人名；(西)福尔；(法)富尔','/foː/','/fɔɹ/','noun',["Do you have any more fours? I want to make this a little taller.","I''ll take the threes, fours and fives and go to the playground.","There are four seasons: winter, spring, summer and autumn."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meet','v.满足；遇见；对付n.集会adj.合适的；适宜的','/miːt/','/mit/','noun',["OK, let''s arrange a meet with Tyler and ask him.","This proposal meets my requirements. The company agrees to meet the cost of any repairs.","The eye met a horrid sight. He met his fate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Dynasty','n.王朝，朝代','/ˈdɪnəsti/','/ˈdaɪnəsti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reach','v.达到；延伸；伸出手；传开n.范围；延伸；河段；横风行驶','/ɹiːt͡ʃ/','/ɹiːt͡ʃ/','noun',["The fruit is beyond my reach.","To call George eloquent is certainly a reach.","He reached for a weapon that was on the table."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ordinary','adj.普通的；平凡的；平常的n.普通；平常的人（或事）','/ˈɔːdənɹi/','/ˈɔɹdɪnɛ(ə)ɹi/','noun',["On an ordinary day I wake up at nine o''clock, work for six hours, and then go to the gym.","He looked so ordinary, I never thought he''d be capable of murder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('challenging','adj.挑战的；引起挑战性兴趣的v.要求；质疑；反对；向…挑战；盘问（challenge的ing形式）','/ˈtʃæləndʒɪŋ/','/ˈtʃæləndʒɪŋ/','verb',["We challenged the boys next door to a game of football.","to challenge the accuracy of a statement or of a quotation","The sentinel challenged us with \"Who goes there?\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speed','v.超速，加速；加速，迅速前行；兴隆n.速度，速率；迅速，快速；昌盛，繁荣','/spiːd/','/spiːd/','noun',["How does Usain Bolt run at that speed?","Speed limits provide information to the drivers about the safe speed to travel in average conditions.","We could go to the shore next week, or somewhere else if that''s not your speed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('once','adv.一次；曾经conj.一旦n.一次，一回','/wɒn(t)s/','/wʌn(t)s/','adverb',["I have only once eaten pizza.","He was once the most handsome man around.","Once three is three."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('type','n.类型，品种；模范；样式v.打字；测定（血等）类型','/taɪp/','/taɪp/','noun',["This type of plane can handle rough weather more easily than that type of plane.","He was exactly her type.","The fundamental types used to express the simplest and most essential chemical relations are hydrochloric acid, water, ammonia, and methane."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweet','adj.甜的；悦耳的；芳香的；亲切的n.糖果；乐趣；芳香；宝贝','/swiːt/','/swit/','noun',["Can we see the sweet menu, please?","a sweet apple","Sweet wines are better dessert wines."]);
