INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('share','v.分享，分担；分配n.份额；股份','/ʃɛə/','/ʃɛəɹ/','noun',["Upload media from the browser or directly to the file share.","to share a shelter with another;  They share a language.","He shared his story with the press."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intelligence','n.智力；情报工作；情报机关；理解力；才智，智慧；天分','/ɪnˈtɛl.ɪ.d͡ʒəns/','/ɪnˈtɛl.ɪ.d͡ʒəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aware','adj.意识到的；知道的；有…方面知识的；懂世故的n.(Aware)人名；(阿拉伯、索)阿瓦雷','/əˈweːɹ/','/əˈwɛɚ/','adjective',["Stay aware! Don''t let your guard down.","Are you aware of what is being said about you?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adolescent','adj.青春期的；未成熟的n.青少年','/ˌædəˈlɛsənt/','/ˌædəˈlɛsənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scan','v.扫描；浏览；细看；详细调查；标出格律n.扫描；浏览；审视；细看','/skæn/','/skæn/','noun',["The operators vacated the room during the scan.","The doctors looked at the scans and made a diagnosis.","She scanned the passage carefully but could not find what she was looking for."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anecdote','n.轶事；奇闻；秘史','/ˈæ.nɪk.doʊt/','/ˈæ.nɪk.doʊt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('former','adj.从前的，前者的；前任的n.模型，样板；起形成作用的人','/ˈfɔːmə/','/ˈfɔɹmɚ/','adjective',["A former president;  the former East Germany","I drive two vehicles, a Chevy Camaro and an AMC Gremlin. I won the former on a game show."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fetch','v.取来；接来；到达；吸引n.取得；诡计','/fɛtʃ/','/fɛtʃ/','noun',["If you put some new tyres on it, and clean it up a bit, the car should fetch about $5,000","to fetch headway or sternway","to fetch a man to"]);
