INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reform','n.改革，改良；改正v.改革，革新；重新组成adj.改革的；改革教会的','/ɹɪˈfɔːm/','/ɹəˈfɔɹm/','noun',["A major reform is needed to improve the efficiency in the factory.","1909, H. G. Wells, The History of Mr. Polly Chapter 9","It is hoped that many criminals, upon being freed, will eventually reform."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bench','n.长凳；工作台；替补队员v.给…以席位；为…设置条凳','/bɛntʃ/','/bɛntʃ/','noun',["They sat on a park bench and tossed bread crumbs to the ducks and pigeons.","They are awaiting a decision on the motion from the bench.","She sat on the bench for 30 years before she retired."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('best','n.最好的人，最好的事物；最佳状态adj.最好的adv.最好地v.打败，胜过','/ˈbɛst/','/ˈbɛst/','noun',["I did my best.","I was somewhat distant lately, and my lady promised me head every Tuesday of the week when I''m nice to her, so I better be on my best.","Unpacking took the best part of a week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vest','n.背心；汗衫v.授予；使穿衣','/vɛst/','/vɛst/','noun',["to vest a court with power to try cases of life and death","The power of life and death is vested in the king, or in the courts.","to vest money in goods, land, or houses"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weakness','n.弱点；软弱；嗜好','/ˈwiːk.nəs/','/ˈwiːk.nəs/','noun',["In a small number of horses, muscle weakness may progress to paralysis.","His inability to speak in front of an audience was his weakness.","She is an athlete who has a weakness for chocolate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luck','n.运气；幸运；带来好运的东西v.靠运气，走运；凑巧碰上','/lʌk/','/lʌk/','noun',["Gilbert had some bad luck yesterday — he got pick-pocketed and lost fifty dollars.","He blew on the dice for luck.","He has a lot of luck with the ladies, perhaps it is because of his new motorbike."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Friday','n.星期五','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('helicopter','n.[航]直升飞机vi.[航]乘直升飞机vt.由直升机运送','/ˈheliˌkɔptə(ɹ)/','/ˈheliˌkɔptə(ɹ)/','noun',["We flew over the city in a helicopter.","helicoptering his jacket, helicoptering his arms"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dare','n.挑战；挑动v.敢冒；不惧','/dɛə(ɹ)/','/dɛ(ə)ɹ/','noun',["I wouldn''t dare argue with my boss.","I dare you (to) kiss that girl.","Will you dare death to reach your goal?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confidential','adj.机密的；表示信任的；获信任的','/ˌkɑːnfɪˈdɛnʃl/','/ˌkɑːnfɪˈdɛnʃl/','adjective',["The newspaper claims a leaked confidential report by the government admits to problems with corrupt MPs.","Sitting in front of the fire, they became quite confidential, and began to gossip.","a confidential agent; a confidential servant; a confidential whisper"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slight','adj.轻微的，少量的；脆弱的；细长的；不重要的v.轻视，忽略；怠慢n.怠慢；轻蔑','[sl̥l͡ɐɪʔ̚]','[sl̥l͡ɐɪʔ̚]','noun',["a slight but graceful woman","A slight stone","The sea was slight and calm"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wait','v.等候；推迟；延缓n.等待；等候','/weɪt/','/weɪt/','noun',["I had a very long wait at the airport security check.","They lay in wait for the patrol.","Wait here until your car arrives."]);
