INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lazy','adj.懒惰的；懒洋洋的；怠惰的；慢吞吞的n.(Lazy)人名；(德)拉齐','/ˈleɪzi/','/ˈleɪzi/','noun',["Get out of bed, you lazy lout!","I love staying inside and reading on a lazy Sunday.","lazy writing"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('understanding','n.谅解，理解；理解力；协议adj.了解的；聪明的；有理解力的v.理解；明白（understand的ing形式）','/ʌndəˈstandɪŋ/','/ˌʌndəɹˈstændɪŋ/','verb',["I''m sorry. I don''t understand.","I understand that you have a package for me?","According to my understanding, the situation is quite perilous. I wonder if you see it this way, too."]);
