INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweep','v.扫除；猛拉；掸去n.打扫，扫除；范围；全胜','/swiːp/','/swiːp/','noun',["Give the front steps a quick sweep to get rid of those fallen leaves.","Bradman attempted a sweep, but in fact top edged the ball to the wicket keeper","Jim will win fifty dollars in the office sweep if Japan wins the World Cup."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endless','adj.无止境的；连续的；环状的；漫无目的的','/ˈɛndləs/','/ˈɛndləs/','adjective',["endless time; endless praise","an endless line"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instrument','n.仪器；工具；乐器；手段；器械','/ˈɪnstɹəmənt/','/ˈɪnstɹəmənt/','noun',["The violinist was a master of her instrument.","The instrument detected an increase in radioactivity.","The dentist set down his tray of instruments."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zoom','n.急速上升；嗡嗡声；[摄]变焦摄影v.急速上升；摄像机移动','/zuːm/','/zuːm/','verb',["prices zoomed"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prison','n.监狱；监禁；拘留所vt.监禁，关押','/ˈpɹɪzən/','/ˈpɹɪzən/','noun',["The cold stone walls of the prison had stood for over a century.","Prison was a harrowing experience for him.","The academy was a prison for many of its students because of its strict teachers."]);
