INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('port','n.港口，口岸；（计算机的）端口；左舷；舱门v.转向左舷','/pɔːt/','/pɔɹt/','noun',["Each eight has four ports and four starboards.","Port your helm!","on the port side"]);
