INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('low','adj.低的，浅的；卑贱的；粗俗的；消沉的adv.低声地；谦卑地，低下地n.低；低价；低点；牛叫声v.牛叫','/ləʊ/','/loʊ/','noun',["Economic growth has hit a new low.","Unemployment has reached a ten-year low.","He is in a low right now"]);
