INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Scratch','n.擦伤；抓痕；刮擦声；乱写adj.打草稿用的；凑合的；碰巧的v.抓；刮；挖出；乱涂','/skɹætʃ/','/skɹætʃ/','noun',["Her skin was covered with tiny scratches.","The dog sat up and had a good scratch.","There were two scratches in race 8, which reduced the field from 9 horses to 7."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spray','n.喷雾；喷雾器；水沫v.喷射','/spɹeɪ/','/spɹeɪ/','noun',["The sailor could feel the spray from the waves.","The firemen sprayed the house.","Spray some ointment on that scratch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('happiness','n.幸福','/ˈhæpinəs/','/ˈhæpinəs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sand','n.沙；沙地；沙洲；沙滩；沙子v.撒沙于；以沙掩盖；用砂纸等擦平或磨光某物；使撒沙似地布满；给…掺沙子','/sænd/','/sænd/','noun',["The Canadian tar sands are a promising source of oil."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hook','n.挂钩，吊钩v.钩住；引上钩','/huːk/','/huːk/','noun',["He is not handling this job, so we''re giving him the hook.","The song''s hook snared me.","We''ve added hooks to allow undefined message types to be handled with custom code."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jungle','n.丛林，密林；危险地带adj.丛林的；蛮荒的','/ˈdʒʌŋ.ɡ(ə)l/','/ˈdʒʌŋ.ɡ(ə)l/','noun',["It’s a jungle out there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cleaner','n.[化工]清洁剂；清洁工；干洗店；干洗商；洗洁器','/ˈkliː.nə/','/ˈkliː.nə/','noun',["I''ll have to take this shirt to the cleaners."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('develop','v.开发；进步；使成长；使显影','/dɛˈvɛ.ləp/','/dɪˈvɛ.ləp/','verb',["Let''s see how things develop and then make our decision.","Isabel developed from a tropical depression to a tropical storm to a hurricane.   An embryo develops into a fetus and then into an infant.","I need to develop a plan for the next three weeks."]);
