INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patent','v.授予专利；取得…的专利权adj.专利的；新奇的；显然的n.专利权；执照；专利品','/ˈpeɪtənt/','/ˈpeɪtənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modest','adj.谦虚的，谦逊的；适度的；端庄的；羞怯的n.(Modest)人名；(罗)莫代斯特；(德)莫德斯特；(俄)莫杰斯特','/ˈmɑdəst/','/ˈmɑdəst/','adjective',["He earns a modest amount of money.","modest thoughts or language"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cookie','n.饼干；小甜点','/ˈkuːki/','/ˈkuːki/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('German','adj.德国的；德语的，德国人的n.德语；德国人','/ˈd͡ʒɜː.mən/','/ˈd͡ʒɜː.mən/','noun',["brother-german","cousin-german","Wert thou a leopard, thou wert german to the lion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('popular','adj.流行的，通俗的；受欢迎的；大众的；普及的','/ˈpɒpjʊlə/','/ˈpɑpjələɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lead','n.领导；铅；导线；榜样v.领导；致使；引导；指挥adj.带头的；最重要的','/lɛd/','/lɛd/','noun',["This copy has too much lead; I prefer less space between the lines.","They pumped him full of lead.","continuous firing leads the grooves of a rifle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('labour','n.劳动力，人工；分娩v.劳动；分娩；费力地前进','/ˈleɪ.bə/','/ˈleɪ.bɚ/','noun',["I think we''ve all got the idea. There''s no need to labour the point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('textbook','n.教科书，课本','/ˈtɛkst.bʊk/','/ˈtɛkst.bʊk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feather','n.羽毛v.用羽毛装饰','/ˈfɛð.ə(ɹ)/','/ˈfɛð.ɚ/','noun',["The stylist feathered my hair.","After striking the bird, the pilot feathered the left, damaged engine’s propeller."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forehead','n.额，前额','/ˈfɒɹɛd/','/ˈfɑɹɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barrier','n.障碍物，屏障；界线vt.把…关入栅栏','/ˈbæɹi.ə(ɹ)/','/ˈbæɹi.əɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provide','v.提供；规定；准备；装备','/pɹəˈvaɪd/','/pɹəˈvaɪd/','verb',["It is difficult to provide for my family working on minimum wage.","Provide against disaster.","I''ll lend you the money, provided that you pay it back by Monday."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('throughout','adv.自始至终，到处；全部prep.贯穿，遍及','/θɹuˈʌʊt/','[θɹuːˈʷaʊt]','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optimistic','adj.乐观的；乐观主义的','/ˌɒptɪˈmɪstɪk/','/ˌɒptɪˈmɪstɪk/','adjective',["in an optimistic mood","optimistic concurrency"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('careful','adj.仔细的，小心的','/ˈkɛːfəl/','/ˈkɛ(ə)ɹfəl/','adjective',["He was a slow and careful driver.","They made a careful search of the crime scene."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rose','n.玫瑰；粉红色；蔷薇（花）；粉红色的葡萄酒adj.玫瑰花的；玫瑰色的；粉红色的；带有玫瑰香味的vt.使成玫瑰色，使（面颊）发红；使有玫瑰香味vi.起义(rise的过去式)；升起；（数量）增加；休会','/ɹəʊz/','/ɹəʊz/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slide','n.滑动；幻灯片；滑梯；雪崩v.滑动；滑落；不知不觉陷入','/slaɪd/','/slaɪd/','noun',["The long, red slide was great fun for the kids.","The slide closed the highway.","a slide on the ice"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sadness','n.悲哀','/ˈsædnəs/','/ˈsædnəs/','noun',["She has experienced many sadnesses in her forty years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cooker','n.炊具；烹饪用水果；窜改者','/ˈkʊkə/','/ˈkʊkə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('runner','n.跑步者；走私者；推销员；送信人','/ˈɹʌnə/','/ˈɹʌnə/','noun',["I just got back from my morning run.","I need to make a run to the store.","Let''s go for a run in the car."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hunt','v.打猎；搜索n.狩猎；搜寻','/hʌnt/','/hʌnt/','noun',["Her uncle will go out and hunt for deer, now that it is open season.","The little girl was hunting for shells on the beach.","He was hunted from the parish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('courtyard','n.庭院，院子；天井','/ˈkɔːt.jɑːd/','/ˈkɔɹt.jɑɹd/','noun',["She sat in the courtyard, enjoying the garden."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seven','num.七个，七n.七个，七adj.七的；七个的','/ˈsɛv.ən/','/ˈsɛv.ən/','noun',["He wrote three sevens on the paper."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ballet','n.芭蕾舞剧；芭蕾舞乐曲','/bælæe/','/bæˈleɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('angry','adj.生气的；愤怒的；狂暴的；（伤口等）发炎的','/ˈæŋ.ɡɹi/','/ˈæŋ.ɡɹi/','adjective',["An angry mob started looting the warehouse.","The broken glass left two angry cuts across my arm.","Angry clouds raced across the sky."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jewel','n.宝石；珠宝v.镶以宝石；饰以珠宝','/dʒul/','/dʒul/','noun',["Galveston was the jewel of Texas prior to the hurricane."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('due','adj.到期的；预期的；应付的；应得的n.应付款；应得之物adv.正（置于方位词前）','/dʒʉː/','/du/','noun',["Give him his due — he is a good actor.","He can wait for the amount due him.","With all due respect, you''re wrong about that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abroad','adv.在国外；到海外adj.往国外的n.海外；异国','/əˈbɹɔːd/','/əˈbɹɔd/','noun',["A tree spreads its branches abroad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sob','v.啜泣，呜咽；（风等）发出呜咽声n.啜泣，呜咽','/sɒb/','/sɑb/','noun',["\"He doesn''t love me!\" she sobbed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunny','adj.阳光充足的，和煦的；快活的；性情开朗的','/ˈsʌni/','/ˈsʌni/','noun',["Whilst it may be sunny today, the weather forecast is predicting rain.","I would describe Spain as sunny, but it''s nothing in comparison to the Sahara.","a sunny disposition"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('black','adj.黑色的；黑人的；邪恶的n.黑色；黑人；黑颜料v.使变黑；把鞋油等涂在…上；把（眼眶）打成青肿','/blak/','/blak/','noun',["At this point black makes a disastrous move.","black drinking fountain; black hospital","I was dealt two red queens, and he got one of the black queens."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contain','v.包含；控制；容纳；牵制（敌军）','/kənˈteɪn/','/kənˈteɪn/','verb',["I''m so excited, I can hardly contain myself!","A group contains a unique inverse for each of its elements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comfort','n.安慰；舒适；安慰者v.安慰；使（痛苦等）缓和','/ˈkʊm.fət/','/ˈkʌm.fəɹt/','noun',["Sleep in comfort with our new mattress.","the comforts of home","We still have the spare tire? That''s a comfort at least."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sightseeing','n.观光；游览adj.观光的；游览的v.观光（sightsee的ing形式）；游览','','','verb',["Sightseeing is a frequent reason to visit San Francisco."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('session','n.会议；（法庭的）开庭；（议会等的）开会；学期；讲习会','/ˈsɛʃən/','/ˈsɛʃən/','noun',["\"Are we having a recording session?\" / \"Yes. We''ve even got some session musicians to provide some brass.\"","This court is now in session.","Logging out or shutting down the computer will end your session."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toy','n.玩具；小装饰品；不值钱的东西v.玩弄；调情；随随便便地对待adj.作为玩具的；玩物似的','/tɔɪ/','/tɔɪ/','noun',["A grown man does not play with a child’s toy.","Figo is toying with the English defence.","I have been toying with the idea of starting my own business."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehension','n.理解；包含','/kɒmpɹɪˈhɛnʃn̩/','/kɒmpɹɪˈhɛnʃn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unsuccessful','adj.不成功的；失败的','/ˌʌnsəkˈsɛsfl̩/','/ˌʌnsəkˈsɛsfl̩/','adjective',["His unsuccessful attempt earned him sympathy, condolences, and an occasional good-natured ribbing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annual','adj.年度的；每年的n.年刊，年鉴；一年生植物','/ˈæn.ju.əl/','/ˈæn.ju.əl/','noun',["I read the magazine, but I usually don''t purchase the annuals.","I can''t wait to plant my annuals in the spring.","an annual general meeting;  an annual publication"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunburnt','adj.晒黑的；有晒斑的；日炙的v.晒黑（sunburn的过去式和过去分词）','','','adjective',["The van was painted a sunburnt brown."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('method','n.方法；条理；类函数adj.使用体验派表演方法的','/ˈmɛθəd/','/ˈmɛθəd/','noun',["If one method doesn''t work, you should ask a friend to help you.","The company employs extensive use of 3D modelling combined with solidification simulation to ensure that critical castings are properly methoded."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treasure','n.财富，财产；财宝；珍品v.珍爱；珍藏','/ˈtɹɛʒə/','/ˈtɹɛʒɚ/','noun',["Oh, this ring is beautiful! I’ll treasure it forever."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moment','n.片刻，瞬间，时刻；重要，契机','/ˈməʊmənt/','/ˈmoʊmənt/','noun',["Wait a moment, while I lock the front door.","If the points represent mass, then the zeroth moment is the total mass, the first moment divided by the total mass is the center of mass, and the second moment is the rotational inertia."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applaud','v.赞同；称赞；向…喝彩','/əˈplɔːd/','/əˈplɔd/','noun',["After the performance, the audience applauded for five minutes.","Although we don''t like your methods, we applaud your motives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grammar','n.语法；语法书','/ˈɡɹæm.ə(ɹ)/','/ˈɡɹæmɚ/','noun',["a grammar of geography","2012, Graeme Paton, A green light for more grammars? (in The Daily Telegraph, 11 January 2012)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ever','adv.永远；曾经；究竟n.(Ever)人名；(英)埃弗；(俄)叶韦尔；(西、法)埃韦尔','/ˈɛvə/','/ˈɛvɚ/','adjective',["It was ever thus.","He''s back and better than ever.","How can I ever get there in time?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fish','v.捕鱼，钓鱼；用钩捞取n.鱼，鱼类','/fɪʃ/','/fɪʃ/','noun',["Salmon is a fish.","The seafood pasta had lots of fish but not enough pasta."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bright','adj.明亮的，鲜明的；聪明的；愉快的adv.明亮地；光明地；欢快地n.车头灯光','/bɹaɪt/','/bɹaɪt/','noun',["Your brights are on.","Could you please dim the light? It''s far too bright.","He''s very bright. He was able to solve the problem without my help."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flame','n.火焰；热情；光辉v.焚烧；泛红','/fleɪm/','/fleɪm/','noun',["The cello has a two-piece back with a beautiful narrow flame.","I flamed him for spamming in my favourite newsgroup."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('light','n.光；光线；灯；打火机；领悟；浅色；天窗adj.轻的；浅色的；明亮的；轻松的；容易的；清淡的v.点着；变亮；着火adv.轻地；清楚地；轻便地','/laɪt/','[ɫɐɪ̯ʔ]','noun',["As you can see, this spacious dining-room gets a lot of light in the mornings.","Put that light out!","Can you throw any light on this problem?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nobody','pron.无人，没有人；没有任何人n.无名小卒；小人物','/ˈnəʊ.bɒ.di/','/ˈnoʊ.bɑ.di/','noun',["Whether you''re a nobody or a player, everyone in Tinseltown wants to be King of Hollywood! - Conquering Hollywood","I asked several people, but nobody knew how."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('object','n.目标；物体；客体；宾语v.提出…作为反对的理由','/ˈɒb.d͡ʒɛkt/','/ˈɑb.d͡ʒɛkt/','noun',["Mary Jane had been the object of Peter''s affection for years.","I object to the proposal to build a new airport terminal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('workday','n.工作日adj.日常的，工作日的；平凡的','','','adjective',["It will take five workdays to process your application.","My workday is 8 hours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('film','n.电影；薄膜；胶卷；轻烟v.在…上覆以薄膜；把…拍成电影','[ˈfɪlm̩]','[ˈfɪlm̩]','noun',["a clear plastic film for wrapping food","A Hollywood studio was filming on location in NYC."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immediately','adv.立即，立刻；直接地conj.一…就','/əˈmiːdi.ətli/','/əˈmiːdi.ətli/','adverb',["I hope we can begin immediately."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspire','v.激发；鼓舞；启示；产生；使生灵感','/ɪn.ˈspaɪə(ɹ)/','/ɪn.ˈspaɪə(ɹ)/','verb',["Elders should inspire children with sentiments of virtue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scream','v.尖叫；呼啸；发出尖锐刺耳的声音；令人触目惊心n.尖叫声；尖锐刺耳的声音；极其滑稽可笑的人','/skɹiːm/','/skɹim/','noun',["We had a real scream of a time at the beach.","He almost hit a pole, the way he came screaming down the hill.","Do you know what screams \"I''m obnoxious\"? People who feel the need to comment on every little thing they notice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('table','n.桌子；表格；平地层v.制表；搁置；嵌合adj.桌子的','/ˈteɪbəl/','/ˈteɪbəl/','noun',["to table fines","The legislature tabled the amendment, so they will not be discussing it until later."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anxious','adj.焦虑的；担忧的；渴望的；急切的','/ˈaŋ(k)ʃəs/','/ˈæŋ(k).ʃəs/','adjective',["I could tell she was anxious as she was biting her nails.","There was an anxious wait before the results were revealed.","All the voters were anxious to hear the election result."]);
