INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('funny','adj.有趣的，好笑的，滑稽的；（口）稀奇的，古怪的，奇异的；有病的，不舒服的；狡猾的，欺骗（性）的，可疑的，不光明n.滑稽人物；笑话，有趣的故事；滑稽连环漫画栏；（英）（比赛用）单人双桨小艇','/ˈfʌni/','/ˈfʌni/','noun',["When I went to the circus, I only found the clowns funny.","I''ve got a funny feeling that this isn''t going to work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suffer','v.遭受；忍受；经历n.(Suffer)人名；(意)苏费尔','/ˈsʌfə/','/ˈsʌfɚ/','verb',["Is anyone here afraid of suffering hardship?","At least he didn''t suffer when he died in the car crash.","If you keep partying like this, your school-work will suffer."]);
