INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('universe','n.宇宙；世界；领域','/ˈjuːnɪˌvɜːs/','/ˈjuːnəˌvɝs/','proper noun',["Powerful telescopes look far back into the distant reaches of the Universe.","I think that the universe was created by a life force rather than a deity.","In all this universe of possibilities, there is only one feasible option."]);
