INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('police','n.警察，警方；治安v.监督；管辖；维持治安；为…配备警察adj.警察的；有关警察的','[pəˈliːs]','/ˈpoʊ.liːs/','noun',["Call the police!","thought police","Extra security was hired to police the crowd at the big game."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ceiling','n.天花板；上限','/ˈsiːlɪŋ/','/ˈsiːlɪŋ/','verb',["the dining room had an ornate ceiling","the ceiling of 4.5 is 5, the ceiling of -4.5 is -4"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theory','n.理论；原理；学说；推测','/ˈθiːəɹi/','/ˈθiːəɹi/','noun',["Knot theory classifies the mappings of a circle into 3-space.","A theory is consistent if it has a model."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('direct','adj.直接的；直系的；亲身的；恰好的v.管理；指挥；导演；指向adv.直接地；正好；按直系关系','/d(a)ɪˈɹɛkt/','/d(a)ɪˈɹɛkt/','verb',["to direct the affairs of a nation or the movements of an army","He directed his question to the room in general.","He directed me to the left-hand road."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('some','adj.一些；某个；大约；相当多的pron.一些；若干；其中的一部分；（数量不确切时用）有些人adv.非常；相当；<美>稍微','/sɐm/','/sʌm/','adverb',["I guess he must have weighed some 90 kilos.","Some enjoy spicy food, others prefer it milder.","Can I have some of them?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tasty','adj.美味的；高雅的；有趣的n.可口的东西；引人入胜的东西','/ˈteɪsti/','/ˈteɪsti/','adjective',["You could make this tasty meal for breakfast.","These items will make an attractive and tasty display."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contemporary','n.同时代的人；同时期的东西adj.当代的；同时代的；属于同一时期的','/kənˈtɛm.p(ə).ɹi/','/kənˈtɛm.pəˌɹɛɹ.i/','noun',["Cervantes was a contemporary of Shakespeare."]);
