INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('must','aux.必须，一定；可以，应当；很可能n.绝对必要的事物；未发酵葡萄汁','','','noun',["If you''ll be out all day, a map is a must.","If it has rained all day, it must be very wet outside.","This door handle must be rotated fully."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attract','v.吸引；引起','/əˈtɹækt/','/əˈtɹækt/','verb',["A magnet attracts iron filings.","Advertising is designed to attract customers.","to attract admirers;   His big smile and brown eyes instantly attracted me."]);
