INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shorts','n.短裤','/ʃɔː(ɹ)ts/','/ʃɔː(ɹ)ts/','noun',["38 short suits fit me right off the rack.","Jones smashes a grounder between third and short.","The market decline was terrible, but the shorts were buying champagne."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negotiate','v.谈判，商议；转让；越过','/nəˈɡəʊ.ʃi.eɪt/','/nəˈɡoʊ.ʃi.eɪt/','verb',["The client and server computers must first negotiate a network protocol to be used.","Although the car was quite rickety, he could negotiate the curves very well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feast','v.享受；款待，宴请n.筵席，宴会；节日','/fiːst/','/fiːst/','noun',["We had a feast to celebrate the harvest.","It was a feast for the eyes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practical','adj.实际的；实用性的','/ˈpɹæktɪkəl/','/ˈpɹæktɪkəl/','noun',["Jack didn''t get an engineering degree, but has practical knowledge of metalworking.","Jack''s knowledge has the practical benefit of giving us useful prototype parts.","All in all, Jack''s a very practical chap."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('private','adj.私人的；私有的；私下的n.列兵；二等兵','/ˈpɹaɪvət/','/ˈpɹaɪvət/','noun',["If you want to learn ballet, consider taking privates.","Her address is private; you can''t have it.","private property"]);
