INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yet','adv.还；但是；已经conj.但是；然而n.(Yet)人名；(东南亚国家华语)一','/jɛt/','/jɛt/','adverb',["He has never yet been late for an appointment;   I’m not yet wise enough to answer that;   Have you finished yet?","The workers went to the factory early and are striking yet.","The riddle will be solved yet."]);
