INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('copy','v.复制；复印；抄袭n.副本；一册；摹仿','/ˈkɒpi/','/ˈkɑpi/','noun',["Please bring me the copies of those reports.","That handbag is a copy. You can tell because the buckle is different.","Submit all copy to the appropriate editor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thin','adj.薄的；瘦的；稀薄的；微弱的v.使瘦；使淡；使稀疏adv.稀疏地；微弱地n.细小部分','/ˈθɪn/','/ˈθɪn/','noun',["chocolate mint thins","The crowds thinned after the procession had passed: there was nothing more to see.","thin plate of metal;  thin paper;  thin board;  thin covering"]);
