INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sheet','n.薄片，纸张；薄板；床单v.覆盖；盖上被单；使成大片adj.片状的','/ʃiːt/','/ʃit/','noun',["Use the sheets in the hall closet to make the bed.","A sheet of paper measuring eight and one-half inches wide by eleven inches high is a popular item in commerce.","Place the rolls on the cookie sheet, edges touching, and bake for 10-11 minutes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('baggage','n.行李；[交]辎重（军队的）','/ˈbæɡɪdʒ/','/ˈbæɡɪdʒ/','noun',["Please put your baggage in the trunk.","This person has got a lot of emotional baggage."]);
