INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scores','n.考试成绩；比分（score的复数）v.得分（score的第三人称单数形式）；刻划','/skɔɹz/','/skɔɹz/','noun',["The player with the highest score is the winner.","The score is 8-1 even though it''s not even half-time!","The test scores for this class were high."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('otherwise','adv.否则；另外；在其他方面adj.另外的；其他方面的；原本，本来conj.其他；如果不；然后','/ˈʌð.əˌwaɪz/','','adjective',["He said he didn’t do it, but the evidence was otherwise.","Could I do otherwise than smile?.","I’m not well today, otherwise I would have helped.  You have to open your umbrella, otherwise you''ll get wet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('active','adj.积极的；活跃的；主动的；有效的；现役的n.主动语态；积极分子','/ˈæk.tɪv/','/ˈæk.tɪv/','noun',["certain active principles","an active child or animal","active hostilities"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('connect','v.连接；联合；关连','/kəˈnɛkt/','/kəˈnɛkt/','verb',["I think this piece connects to that piece over there.","Both roads have the same name, but they don''t connect: they''re on opposite sides of the river, and there''s no bridge there.","The new railroad will connect the northern part of the state to the southern part."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bucket','n.桶，水桶；铲斗；一桶的量v.倾盆而下；颠簸着行进','/ˈbʌkɪt/','/ˈbʌkɪt/','noun',["I need a bucket to carry the water from the well.","The horse drank a whole bucket of water.","The forward drove to the bucket."]);
