INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lend','v.贷；增添，提供；把……借给n.(Lend)人名；(德)伦德','/lɛnd/','/lɛnd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mushroom','n.蘑菇，伞菌；蘑菇形物体；暴发户adj.蘑菇的；蘑菇形的；迅速生长的v.迅速增加；采蘑菇；迅速生长','/ˈmʌʃˌɹuːm/','/ˈmʌʃˌɹuːm/','noun',["Some mushrooms are edible and taste good, while others are poisonous and taste foul.","The town’s population mushroomed from 10,000 to 110,000 in five years.","We used to go mushrooming in the forest every weekend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secondhand','adj.二手的；旧的；间接获得的；做旧货生意的adv.间接地；间接听来；以旧货','','','adjective',["exposure to secondhand smoke from cigarette-smoking colleagues"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('god','n.神；（大写首字母时）上帝vt.膜拜，崇拜','/ɡɔd/','/ɡɑd/','noun',["Dawn believes in God, but Willow believes in multiple gods and goddesses.","The most frequently used name for the Islamic god is Allah.","Leo Messi is my god!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('souvenirs','n.纪念品；旅游纪念品；回忆','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spin','v.旋转；纺纱；吐丝；晕眩n.旋转；疾驰','/spɪn/','/spɪn/','noun',["He put some spin on the cue ball.","The politician was mocked in the press for his reliance on spin rather than facts.","I''m off out for a spin in my new sports car."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rubber','n.橡胶；橡皮；合成橡胶；按摩师adj.橡胶制成的v.涂橡胶于；用橡胶制造','/ˈɹʌbə(ɹ)/','/ˈɹʌbɚ/','noun',["Jones toes the rubber and then fires to the plate.","Johnny, don''t forget your rubbers today.","Jones enters the pits to get new rubber."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sincerely','adv.真诚地；由衷地，诚恳地','/sɪnˈsɪəli/','/sɪnˈsɪɹli/','adverb',["I sincerely hope they make it home safely."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reception','n.接待；接收；招待会；感受；反应','/ɹɪˈsɛp.ʃn̩/','/ɹɪˈsɛp.ʃn̩/','noun',["The new system provides exceptional quality of the reception signal.","After the wedding we proceeded to the reception.","The ambassador''s jokes met a cold reception."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sauce','n.酱油；沙司；调味汁v.使增加趣味；给…调味','/sɔːs/','/sɑs/','noun',["apple sauce; mint sauce","meat pie and tomato sauce","Maybe you should lay off the sauce."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spot','n.地点；斑点v.认出；弄脏；用灯光照射adj.现场的；现货买卖的adv.准确地；恰好','/spɒt/','/spɑt/','noun',["The leopard is noted for the spots of color in its fur.","I have tried everything, and I can’t get this spot out.","I think she''s got chicken pox; she''s covered in spots."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('five','n.五，五个；五美元钞票num.五，五个adj.五的；五个的','/fɑev/','/faɪv/','noun',["He wrote a five followed by four zeroes.","Can anyone here change a five?","All the fives are over there in the corner, next to the fours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('workforce','n.劳动力；工人总数，职工总数','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concept','n.观念，概念','/ˈkɒn.sɛpt/','/ˈkɒn.sɛpt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('angle','v.钓鱼；谋取n.角度，角，方面','/ˈæŋ.ɡəl/','/ˈæŋ.ɡəl/','noun',["the angle between lines A and B","The angle between lines A and B is π/4 radians, or 45 degrees.","an angle of a building"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vertical','adj.垂直的，直立的；[解剖]头顶的，顶点的n.垂直线，垂直面','/ˈvɜːtɪkəl/','/ˈvɝtɪkəl/','noun',["We offer specialised accounting software targeting various verticals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insure','v.确保，保证；给…保险','/ɪnˈʃɔː/','/ɪnˈʃʊɚ/','verb',["I use an alarm clock to ensure that I get up on time.","I''m not insured against burglary."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coffee','n.咖啡；咖啡豆；咖啡色','/ˈkɒ.fi/','/ˈkɔ.fi/','noun',["He did not stay for coffee."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gas','n.气体；[矿业]瓦斯；汽油；毒气v.加油；毒（死）','/ɡæs/','/ɡæs/','noun',["A lot of gas had escaped from the cylinder.","The atmosphere is made up of a number of different gases.","Gas-fired power stations have largely replaced coal-burning ones."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radium','n.[化学]镭（88号元素符号Ra）','/ˈɹeɪ.dɪ.əm/','/ˈɹeɪ.dɪ.əm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drive','v.开车；猛击；飞跑n.驱动器；驾车；[心理]内驱力，推进力；快车道','/dɹaɪv/','/dɹaɪv/','noun',["Crassus had wealth and wit, but Pompey had drive and Caesar as much again.","Napoleon''s drive on Moscow was as determined as it was disastrous.","Some old model trains have clockwork drives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kiss','v.吻；（风等）轻拂n.吻；轻拂','/kɪs/','/kɪs/','verb',["His ball kissed the black into the corner pocket."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attend','v.出席；上（大学等）；照料；招待；陪伴','/əˈtɛnd/','/əˈtɛnd/','verb',["Secretaries attend to correspondence.","Servants attend the king day and night.","Children must attend primary school."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equipment','n.设备，装备；器材','/ɪˈkwɪpmənt/','/ɪˈkwɪpmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heroine','n.女主角；女英雄；女杰出人物','/ˈhɛɹoʊɪn/','/ˈhɛɹoʊɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gentleman','n.先生；绅士；有身份的人','/ˈdʒɛn.təl.mən/','[ˈdʒɛɾ̃.ɫ̩.mən]','noun',["Being a gentleman, Robert was entitled to shove other commoners into the gongpit but he still had to jump out of the way of the knights to avoid the same fate himself.","Well, la-di-da, aren''t you just a proper gentleman?","Please escort this gentleman to the gentlemen''s room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('difficulty','n.困难，困境','/ˈdɪfɪkəlti/','/ˈdɪfɪkəlti/','noun',["We faced a difficulty in trying to book a flight so late.","2012 August 2, \"Children rescued after getting into difficulties in Donegal\" BBC Online"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('follow','v.跟随；遵循；追求；密切注意，注视；注意；倾听n.跟随；追随','/ˈfɒləʊ/','/ˈfɑloʊ/','noun',["a follow shot","Follow that car!","B follows A in the alphabet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('him','pron.他（宾格）n.(Him)人名；(东南亚国家华语)欣；(柬)亨；(中)谦(广东话·威妥玛)','/əm/','/əm/','pronoun',["I think this bird is a him, but it may be a her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('old','adj.陈旧的，古老的；年老的n.古时','/ˈɒʊld/','/ˈoʊld/','noun',["A civilised society should always look after the old in the community.","when he was an eight-year-old ; a 62-year-old should","I had to sneak out to meet my girlfriend and tell the olds I was going to the library."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('big','adj.大的；重要的；量大的adv.大量地；顺利；夸大地n.(Big)人名；(土)比格','/bɪɡ/','/bɪɡ/','noun',["Elephants are big animals, and they eat a lot.","Big Tech","That style is very big right now in Europe, especially among teenagers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyway','adv.无论如何，不管怎样；总之','/ˈɛniweɪ/','/ˈɛniweɪ/','adverb',["He didn''t enjoy washing his car, but it was so dirty that he did it anyway.","I don''t think that''s true. I haven''t found any evidence, anyway."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fry','n.鱼苗；油炸食物v.油炸；油煎','/fɹaɪ/','/fɹaɪ/','noun',["to be in a fry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commitment','n.承诺，保证；委托；承担义务；献身','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stand','v.站立；位于；停滞n.站立；立场；看台；停止','/stænd/','/stænd/','noun',["The Commander says we will make our stand here.","They took a firm stand against copyright infringement.","They have a four-game stand at home against the Yankees.  They spent the summer touring giving 4 one-night stands a week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Australia','n.澳大利亚，澳洲','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recover','v.恢复；弥补；重新获得n.还原至预备姿势','/ɹɪˈkʌvə/','/ɹɪˈkʌvɚ/','noun',["After days of inquiries, he finally recovered his lost wallet.","They recovered three of the explorers very much alive, then another, wracked with severe hypothermia, who was taken to hospital.","At the top of the hill I asked to stop for a few minutes to recover my strength."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pint','n.品脱；一品脱的量；一品脱牛奶或啤酒','/paɪnt/','/paɪnt/','noun',["Please leave three pints tomorrow, milkman."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wolf','n.狼；色狼；残忍贪婪之人v.大吃；狼吞虎咽地吃','/wʊlf/','/wʊlf/','noun',["Check out my pet. He''s a wolf.","The soft violin solo was marred by persistent wolves.","They toiled hard to keep the wolf from the door."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creature','n.动物，生物；人；创造物','/ˈkɹiːt͡ʃə/','/ˈkɹiːt͡ʃəɹ/','noun',["He''s a creature of habit.   insects and other creatures"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sentence','n.[语][计]句子，命题；宣判，判决v.判决，宣判','[ˈsɛntn̩t͡s]','[ˈsɛntn̩t͡s]','noun',["The court returned a sentence of guilt in the first charge, but innocence in the second.","The judge declared a sentence of death by hanging for the infamous cattle rustler.","The children were made to construct sentences consisting of nouns and verbs from the list on the chalkboard."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('street','n.街道adj.街道的','/stɹiːt/','/ʃtɹiːt/','noun',["Walk down the street until you see a hotel on the right.","I live on the street down from Joyce Avenue.","I got some pot cheap on the street."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flash','v.使闪光；反射n.闪光，闪现；一瞬间adj.闪光的，火速的','/flæʃ/','/flæʃ/','noun',["I just got my first commando flash.","He flashed the light at the water, trying to see what made the noise.","The light flashed on and off."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equality','n.平等；相等；[数]等式','/ɪˈkwɒl.ɪ.ti/','/ɪˈkwɒl.ɪ.ti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relate','v.叙述；使…有联系','/ɹiˈleɪt/','/ɹiˈleɪt/','verb',["Please relate the circumstances of your journey here today.","The patterns on the screen relate to the pitch and volume of the music being played.","I find it difficult to relate to others because I''m extremely introverted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('independence','n.独立性，自立性；自主','/ɪndɪˈpɛndəns/','/ɪndɪˈpɛndəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('willingly','adv.欣然地；愿意地，乐意地','/ˈwɪlɪŋli/','/ˈwɪlɪŋli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basic','adj.基本的；基础的n.基础；要素','/ˈbeɪsɪk/','/ˈbeɪsɪk/','noun',["Rice is a basic for many Asian villagers.","Arithmetic is a basic for the study of mathematics.","The drill sergeants gave him hell in basic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consist','v.由…组成；在于；符合','/kənˈsɪst/','/kənˈsɪst/','verb',["The greeting package consists of some brochures, a pen, and a notepad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('land','n.国土；陆地；地面v.使…登陆；使…陷于；将…卸下','/lænd/','/lænd/','noun',["Most insects live on land.","There are 50 acres of land in this estate.","wet land; good or bad land for growing potatoes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('user','n.用户','/ˈjuːzə/','/ˈjuzɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brain','n.头脑，智力；脑袋v.猛击…的头部','/bɹeɪn/','/bɹeɪn/','noun',["She was a total brain.","She has a lot of brains.","The computer''s brain is capable of millions of calculations a second."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choice','n.选择；选择权；精选品adj.精选的；仔细推敲的','/tʃɔɪs/','/tʃɔɪs/','noun',["Do I have a choice of what color to paint it?","She didn''t leave us much choice.","The ice cream sundae is a popular choice for dessert."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('introduce','v.介绍；引进；提出；采用','/ˌɪntɹəˈdjuːs/','/ˌɪntɹəˈdus/','verb',["Let me introduce you to my friends.","Let me introduce our guest speaker.","Various pollutants were introduced into the atmosphere."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ride','v.骑马；乘车；依靠；漂浮n.骑；乘坐；交通工具；可供骑行的路；（乘坐汽车等的）旅行；乘骑；（乘车或骑车的）短途旅程；供乘骑的游乐设施','/ɹaɪd/','/ɹaɪd/','noun',["Can I have a ride on your bike?","That''s a nice ride; what did it cost?","Can you give me a ride?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circulate','v.传播，流传；循环；流通','/ˈsɚˌkju.leɪt/','/ˈsɚˌkju.leɪt/','verb',["to circulate money or gossip"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('person','n.人；身体；容貌，外表；人称','/ˈpɜːsən/','/ˈpɝsən/','noun',["Each person is unique, both mentally and physically.","At common law a corporation or a trust is legally a person."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nursery','n.苗圃；托儿所；温床','/ˈnɜːsəɹi/','/ˈnɜːsəɹi/','noun',["Commerce is the nursery of seamen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regards','n.致意，问候v.视为，注意（regard的第三人称单数）','/ɹɪˈɡɑːdz/','/ɹɪˈɡɑɹdz/','noun',["He is held in great regard in Whitehall.","She regarded us warily.","He regards honesty as a duty."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postman','n.邮递员；邮差','/ˈpəʊsmən/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sceptical','adj.怀疑的；怀疑论的；习惯怀疑的','','','adjective',["I can see why people are so skeptical about him, but I think he''s on to something here. (regarded by organizations such as the BBC as an error)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cruel','adj.残酷的，残忍的；使人痛苦的，让人受难的；无情的，严酷的','/kɹuː(ə)l/','/kɹuː(ə)l/','verb',["The supervisor was very cruel to Josh, as he would always give Josh the hardest, most degrading work he could find."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seem','v.似乎；像是；装作n.(Seem)人名；(英)西姆','/siːm/','/siːm/','verb',["He seems to be ill.   Her eyes seem blue.   It seems like it is going to rain later.   How did she seem to you?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('access','v.使用；存取；接近n.进入；使用权；通路','/ˈæksɛs/','/ˈækˌsɛs/','noun',["an access of territory"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statement','n.声明；陈述，叙述；报表，清单','/ˈsteɪtm(ə)nt/','/ˈsteɪtmənt/','noun',["a bank statement"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambiguous','adj.模糊不清的；引起歧义的','/æmˈbɪɡjuəs/','/æmˈbɪɡjuəs/','adjective',["The politician was criticized for his ambiguous statements and lack of precision.","He gave an ambiguous answer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('island','n.岛；岛屿；安全岛；岛状物adj.岛的vt.孤立；使成岛状','/ˈaɪ̯lənd/','/ˈaɪ̯lənd/','noun',["an island of colors on a butterfly''s wing","the island in the middle of a roundabout"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('honey','n.蜂蜜；宝贝；甜蜜adj.甘美的；蜂蜜似的v.对…说甜言蜜语；加蜜使甜','/ˈhʌni/','/ˈhʌni/','noun',["Honey, I''m home.","Man, there are some fine honeys here tonight!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wherever','adv.无论什么地方；究竟在哪里conj.无论在哪里；无论什么情况下','/wɛəˈɹɛvə/','/(h)wɛɹˈɛvɚ/','adverb',["Wherever have you been all my life?","You can sit wherever you like.","Add quotations wherever they are needed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yes','adv.是,是的n.是（表示肯定）','/jɛs/','/jɛs/','noun',["Was that a yes?","The workers voted on whether to strike, and there were thirty \"yeses\" and one \"no\".","Did he yes the veto?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breathless','adj.喘不过气来的；停止呼吸的','/ˈbɹɛθləs/','/ˈbɹɛθləs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('golf','n.高尔夫球；高尔夫球运动v.打高尔夫球','/ɡɒlf/','/ɡɑlf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('danger','n.危险；危险物，威胁','/ˈdeɪn.dʒə(ɹ)/','/ˈdeɪndʒɚ/','noun',["There''s plenty of danger in the desert.","The north signal was at danger because of the rockslide."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interest','n.兴趣，爱好；利息；趣味；同行v.使……感兴趣；引起……的关心；使……参与','/ˈɪntəɹɪst/','/ˈɪntəɹst/','noun',["Our bank offers borrowers an annual interest of 5%.","He has a lot of interest in vintage cars.","I have business interests in South Africa."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flaming','adj.燃烧的；火红的；激昂的v.燃烧；变亮；发光（flame的ing形式）n.(Flaming)人名；(法)弗拉曼','/ˈfleɪmɪŋ/','/ˈfleɪmɪŋ/','verb',["I flamed him for spamming in my favourite newsgroup.","You can expect a flaming if you post irrelevant spam to a newsgroup.","The flaming debris kept the firefighter well back, and the sparks threatened the neighborhood."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temporary','adj.暂时的，临时的n.临时工，临时雇员','/ˈtɛmpəɹi/','/ˈtɛmpəˌɹɛɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accomplish','v.完成；实现；达到','/əˈkɐm.plɪʃ/','/əˈkɑm.plɪʃ/','verb',["to accomplish a design, an object, a promise"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stupid','adj.愚蠢的；麻木的；乏味的n.傻瓜，笨蛋','/ˈstjuːpɪd/','/ˈst(j)upɪd/','noun',["His stupid knows no bounds.","Neurobiology bores me stupid.","That dunk was stupid! His head was above the rim!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glue','v.粘合；似胶般固着于n.胶；各种胶合物','/ɡluː/','/ɡluː/','noun',["I need to glue the chair-leg back into place.","His eyes were glued to the screen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exercise','n.运动；练习；运用；操练；礼拜；典礼v.锻炼；练习；使用；使忙碌；使惊恐','/ˈɛk.sə.saɪz/','/ˈɛk.sɚ.saɪz/','noun',["The teacher told us that the next exercise is to write an essay.","I do crosswords for mental exercise.","The law guarantees us the free exercise of our rights."]);
