INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sandwich','v.夹入；挤进；把做成三明治n.三明治；夹心面包','/ˈsæmwɪd͡ʒ/','/ˈsæmˌwɪt͡ʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heap','n.堆；许多；累积v.堆；堆积','/heːp/','/hiːp/','noun',["a heap of earth or stones","You should move these structures from the stack to the heap to avoid a potential stack overflow.","My first car was an old heap."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trend','n.趋势，倾向；走向v.趋向，伸向','/tɹɛnd/','/tɹɛnd/','noun',["the trend of a coastline","There is a trend, these days, for people in films not to smoke.","Miniskirts were one of the biggest trends of the 1960s."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cellar','n.地窖；酒窖；地下室vt.把…藏入地窖','/ˈsɛlə(ɹ)/','/ˈsɛlə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visitor','n.访问者，参观者；视察者；候鸟','/ˈvɪzɪtə/','/ˈvɪzɪtɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seed','n.种子；根据；精液；萌芽；子孙；原由v.播种；结实；成熟；去…籽','/siːd/','/siːd/','noun',["If you plant a seed in the spring, you may have a pleasant surprise in the autumn.","The entire field was covered with geese eating the freshly sown seed.","A man must use his seed to start and raise a family."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('out','adv.出现；在外；出局；出声地；不流行地adj.外面的；出局的；下台的n.出局prep.向；离去v.出来；暴露','/æɔt/','/aʊt/','noun',["They wrote the law to give those organizations an out.","A Brazilian company outed the new mobile phone design.","I''m sorry, Mr Smith is out at the moment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breakfast','n.早餐；早饭v.吃早餐','/ˈbɹɛkfəst/','/ˈbɹɛkfəst/','noun',["You should put more protein in her breakfast so she will grow.","We serve breakfast all day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certainly','adv.当然；行（用于回答）；必定','/ˈsɜːtn̩li/','/ˈsɝʔn̩li/','adverb',["That was certainly sweet of him.","Would you like it with ice?  Certainly, and with lemon please."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('them','pron.他们；它们；她们n.(Them)人名；(老)探','/ðʌm/','','pronoun',[]);
