INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('camel','n.[畜牧][脊椎]骆驼；打捞浮筒；工作作风官僚adj.驼色的；暗棕色的vi.工作刻板平庸','/ˈkæməl/','/ˈkæməl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engine','n.引擎，发动机；机车，火车头；工具','/end͡ʒən/','/ˈɛnd͡ʒɪn/','noun',["a graphics engine","Vessels are often built by one firm and engined by another."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lift','v.举起；提升；鼓舞；空运；抄袭n.电梯；举起；起重机；搭车','/lɪft/','/lɪft/','noun',["He gave me a lift to the bus station.","Take the lift to the fourth floor.","What''s the maximum lift of this crane?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surrounding','adj.周围的，附近的n.环境，周围的事物','/səˈɹaʊndɪŋ/','/səˈɹaʊndɪŋ/','verb',["to surround the world"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flexible','adj.灵活的；柔韧的；易弯曲的','/ˈflɛk.sə.bəl/','/ˈflɛk.sə.bəl/','noun',["This was a principle more flexible to their purpose. -Rogers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('holy','adj.圣洁的，神圣的；至善的n.神圣的东西','/ˈhəʊli/','/ˈhoʊli/','noun',["I''m planning to visit the holy city of Jerusalem this Christmas.","My grandmother is a very holy woman.","Holy cow, I can’t believe he actually lost the race!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrong','adv.错误地；邪恶地，不正当地n.坏事；不公正adj.错误的；失常的；不适当的v.委屈；无理地对待；诽谤','/ɹɒŋ/','/ɹɔŋ/','noun',["Injustice is a heinous wrong.","Some of your answers were correct, and some were wrong.","You''re wrong: he''s not Superman at all."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crop','n.产量；农作物；庄稼；平头v.种植；收割；修剪；剪短','/kɹɒp/','/kɹɑp/','noun',["the farmer had lots of crops to sell at the market","it was a good crop of lambs that year","a crop of ideas"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subjective','adj.主观的；个人的；自觉的','/səbˈdʒɛktɪv/','/səbˈdʒɛktɪv/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blame','v.责备；归咎于n.责备；责任；过失','/bleɪm/','/bleɪm/','noun',["Blame came from all directions.","The blame for starting the fire lies with the arsonist.","They accepted the blame, but it was an accident."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fireplace','n.壁炉','/ˈfaɪəpleɪs/','/ˈfaɪɹpleɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheek','n.面颊，脸颊；臀部v.无礼地向…讲话，对…大胆无礼','/tʃiːk/','/tʃiːk/','noun',["You’ve got some cheek, asking me for money!","the cheeks of a vice; the cheeks of a gun carriage","Don''t cheek me, you little rascal!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fluency','n.（语言、文章）流利；（技能）娴熟','/ˈfluːənsi/','/ˈfluːənsi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pen','n.钢笔；作家；围栏v.写；关入栏中','/pɛn/','/pɛn/','noun',["There are two steers in the third pen.","They caught him with a stolen horse, and he wound up in the pen again.","Two righties are up in the pen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('survival','n.幸存，残存；幸存者，残存物','/sɚˈvaɪvəl/','/sɚˈvaɪvəl/','noun',["His survival in the open ocean was a miracle; he had fully expected to die.","His survival kit had all the things he needed in the wilderness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slavery','n.奴役；奴隶制度；奴隶身份','/ˈsleɪvəɹi/','/ˈsleɪvəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explorer','n.探险家；勘探者；探测器；[医]探针','/ɛkˈsplɔːɹə(ɹ)/','/ɛkˈsplɔːɹə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admission','n.承认；入场费；进入许可；坦白；录用','/ædˈmɪʃ.ən/','/ædˈmɪʃ.ən/','noun',["I request admission for two adults","There is no way he has seen that show, the admission is more than he makes in a week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stress','n.压力；强调；紧张；重要性；重读v.强调；使紧张；加压力于；用重音读','/stɹɛs/','/stɹɛs/','noun',["Go easy on him, he''s been under a lot of stress lately.","Some people put the stress on the first syllable of “controversy”; others put it on the second.","“Emphasis” is stressed on the first syllable, but “emphatic” is stressed on the second."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brunch','n.早午餐','/bɹʌntʃ/','/bɹʌntʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('victory','n.胜利；成功；克服','/ˈvɪkt(ə)ɹi/','/ˈvɪkt(ə)ɹi/','noun',["It was a great victory on the battlefield."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('safe','adj.安全的；可靠的；平安的n.保险箱；冷藏室；纱橱','/seɪf/','/seɪf/','noun',["You’ll be safe here.","It’s safe to eat this.","We have to find a safe spot, where we can hide out until this is over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passport','n.护照，通行证；手段','/ˈpɑːspɔːt/','/ˈpæspɔɹt/','noun',["You will have to bring your passport to prove who you are.","The tenor''s voice was his passport to the international concert circuit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pregnant','adj.怀孕的；富有意义的','/ˈpɹɛɡnənt/','/ˈpɹɛɡnənt/','noun',["I went to the doctor and, guess what, I''m pregnant!","a pregnant pause"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stair','n.楼梯，阶梯；梯级','/stɛə/','/stɛəɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bravery','n.勇敢；勇气','/ˈbɹeɪvəɹi/','/ˈbɹeɪvəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('struggle','v.奋斗，努力；挣扎n.努力，奋斗；竞争','/ˈstrʌɡəl/','/ˈstrʌɡəl/','noun',["During the centuries, the people of Ireland struggled constantly to assert their right to govern themselves.","She struggled to escape from her assailant''s grasp."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abundant','adj.丰富的；充裕的；盛产','/əˈbʌn.dn̩t/','/əˈbn̩.dn̩t/','adjective',["With their magical words they poets bring forth to our eyesight the abundant images and beauties of creation. — Leigh Hunt, On the Realities of Imagination","Abundant in goodness and truth. — Exodus, 34:6"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pronunciation','n.发音；读法','/pɹəˌnaʊn.siˈeɪ.ʃən/','/pɹəˌnaʊn.siˈeɪ.ʃən/','noun',["What is the pronunciation of \"hiccough\"?","His Italian pronunciation is terrible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relay','v.转播；接替n.[电]继电器；接替，接替人员；驿马','','','noun',["Can you relay this message to John?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unconscious','adj.无意识的；失去知觉的；不省人事的；未发觉的','/ˌʌnˈkɒnʃəs/','/ˌʌnˈkɑnʃəs/','noun',["After the anesthetist administered the general anesthetic the patient was unconscious.","My sudden fright was an unconscious response."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('racial','adj.种族的；人种的','/ˈɹeɪʃəl/','/ˈɹeɪʃəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silly','adj.愚蠢的；不明事理的；没头脑的n.傻瓜','/ˈsɪli/','/ˈsɪli/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remote','adj.遥远的；偏僻的；疏远的n.远程','[ɹəˈməʊt]','[ɹɪˈmoʊt]','noun',["A remote operator may control the vehicle with a wireless handset.","After his fall from the emperor''s favor, the general was posted to a remote outpost.","There was only a remote possibility that we would be rescued as we were far outside of the regular shipping lanes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shallow','adj.浅的；肤浅的n.[地理]浅滩v.使变浅','/ˈʃaləʊ/','/ˈʃæl.oʊ/','noun',["The ship ran aground in an unexpected shallow.","Saute the onions in a shallow pan.","The water is shallow here."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('satellite','n.卫星；人造卫星；随从；卫星国家','/ˈsætəlaɪt/','/ˈsætəlaɪt/','noun',["A spent upper stage is a derelict satellite.","Many telecommunication satellites orbit at 36000km above the equator.","Do you have satellite at your house?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expert','adj.熟练的；内行的；老练的n.专家；行家；能手vt.当专家；在…中当行家','/ˈɛkspəːt/','/ˈɛkspɚt/','noun',["We called in several experts on the subject, but they couldn''t reach an agreement.","I am expert at making a simple situation complex.","This problem requires expert knowledge."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bath','n.沐浴；浴室；浴盆v.洗澡','/bɐːθ/','[bæθ⁓bɛəθ⁓beəθ]','noun',["a bath of heated sand, ashes, steam, or hot air","Most Americans don''t know ''WC'' and many Brits mock ''bathroom'' but almost everyone understands ''toilet'' or ''lavatory''."]);
