INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primitive','adj.原始的，远古的；简单的，粗糙的n.原始人','/ˈpɹɪmɪtɪv/','/ˈpɹɪmɪtɪv/','noun',["primitive innocence;   the primitive church","a primitive style of dress","primitive ideas"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moustache','n.小胡子；髭；触须','/məˈstɑːʃ/','/məˈstæʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goose','n.鹅；鹅肉；傻瓜；雌鹅v.突然加大油门；嘘骂','/ˈɡuːs/','/ˈɡuːs/','noun',["There is a flock of geese on the pond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absence','n.没有；缺乏；缺席；不注意','/ˈæb.s(ə)n̩s/','/æbˈsɒns/','noun',["Absence makes the heart grow fonder.","He had an absence of enthusiasm.","absence of mind"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repair','v.修理；修复n.修理，修补；修补部位','/ɹɪˈpɛə/','/ɹəˈpɛɚ/','noun',["I took the car to the workshop for repair.","If you look closely you can see the repair in the paintwork.","The car was overall in poor repair before the accident. But after the workshop had it for three weeks it was returned in excellent repair. But the other vehicle was beyond repair."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admit','v.承认；准许进入；可容纳','/ədˈmɪt/','/ədˈmɪt/','verb',["A ticket admits one into a playhouse.","the prisoner was admitted to bail","he admitted his guilt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valley','n.山谷；流域；溪谷','/ˈvæli/','/ˈvæli/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bomb','v.轰炸，投弹于n.炸弹','/bɒm/','/bɑm/','noun',["box office bomb","cost a bomb","I was bombing down the road on my motorbike."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choir','n.唱诗班；合唱队；舞蹈队v.合唱','/kwaɪə(ɹ)/','/kwaɪɚ/','noun',["The church choir practices Thursday nights.","Seraphim, Cherubim, and Thrones are three of the choirs of angels."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thing','n.事情；东西；事物；情况','/θɪŋ/','/θɪŋ/','noun',["Bacon pie? Is that a thing?","Hold on, let me just grab my things.","get me a thing of apple juice at the store;  I just ate a whole thing of jelly beans"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toothpaste','n.牙膏','/ˈtuːθpeɪst/','/ˈtuːθpeɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yours','pron.你（们）的东西；你的责任[义务]；你的家属；来信，尊函adj.你（们）的（东西）；信末署名前用语','/jɔː(ɹ)z/','/jɔɹz/','pronoun',["If this edit is mine, the other must be yours.  Their encyclopedia is good, but yours is even better.  It’s all yours.","Yours sincerely,  Yours faithfully,  Yours,  Sincerely yours,"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geography','n.地理；地形','/dʒɪˈɒɡɹəfi/','/dʒiˈɑɡɹəfi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loudly','adv.大声地，响亮地','/ˈlaʊdli/','/ˈlaʊdli/','adverb',["He spoke loudly so that his brother could hear him from across the street."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wealthy','adj.富有的；充分的；丰裕的n.富人','/ˈwɛl.θi/','/ˈwɛl.θi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hi','int.嗨！（表示问候或用以唤起注意）n.(Hi)人名；(柬)希','/haɪ/','/haɪ/','noun',["I didn''t even get a hi.","Hi, how are you?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('channel','v.引导，开导；形成河道n.通道；频道；海峡','/ˈtʃænəl/','/ˈtʃænəl/','noun',["The water coming out of the waterwheel created a standing wave in the channel.","A channel was dredged to allow ocean-going vessels to reach the city.","We were careful to keep our boat in the channel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pillow','n.枕头v.垫；枕于…；使…靠在','/ˈpɪləʊ/','/ˈpɛloʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soup','n.汤，羹；马力v.加速；增加马力','/suːp/','/sup/','noun',["Pho is a traditional Vietnamese soup."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('analysis','n.分析；分解；验定','/əˈnælɪsɪs/','/əˈnælɪsɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cassette','n.盒式磁带；暗盒；珠宝箱；片匣','/kæˈsɛt/','/kæˈsɛt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laundry','n.洗衣店，洗衣房；要洗的衣服；洗熨；洗好的衣服','/ˈlɑn.dɹi/','/ˈlɔːn.dɹi/','noun',["You''ve left your dirty laundry all over the house."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decrease','n.减少，减小；减少量v.减少，减小','','','noun',["One research team has recorded Baishui’s decrease at about 27 meters per year over the last 10 years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insert','v.插入；嵌入n.插入物；管芯；镶块；[机械]刀片','/ɪnˈsɜːt/','/ɪnˈsɜːt/','noun',["This software can print compact disc inserts if you have the right size of paper.","a threaded insert","In order to withdraw money from a cash machine, you have to insert your debit card."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encouragement','n.鼓励','[ɪnˈkʌɹɪdʒmənt]','[ɪnˈkʌɹɪdʒmənt]','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('youth','n.青年；青春；年轻；青少年时期','/juθ/','/juθ/','noun',["Her youth and beauty attracted him to her.","I made many mistakes in my youth, but learned from them all.","There was a group of youths hanging around the parking lot, reading fashion magazines and listening to music."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thousand','n.一千；一千个；许许多多adj.成千的；无数的','/ˈθaʊzənd/','/ˈθaʊz(ə)nd/','numeral',["Many thousands of people came to the conference."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physical','adj.[物]物理的；身体的；物质的；根据自然规律的，符合自然法则的n.体格检查','/ˈfɪzɪkəl/','/ˈfɪzɪkəl/','noun',["How long has it been since your last physical?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('change','v.改变；交换n.变化；找回的零钱','/tʃeɪndʒ/','/tʃeɪndʒ/','noun',["The product is undergoing a change in order to improve it.","Can I get change for this $100 bill please?","A customer who pays with a 10-pound note for a £9 item receives one pound in change."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allowance','n.津贴，零用钱；允许；限额v.定量供应','/əˈlaʊəns/','/əˈlaʊəns/','noun',["her meagre allowance of food or drink","to make allowance for his naivety","Tare and tret are examples of allowance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('asleep','adj.睡着的；麻木的；长眠的adv.熟睡地；进入睡眠状态','/əˈsliːp/','/əˈsliːp/','adjective',["I was asleep when you called.","How could you miss that? Were you asleep?","My arm fell asleep. You know, like pins and needles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swimming','n.游泳；目眩adj.游泳的；游泳用的；善于游泳的；晕眩的v.游泳；漂浮；旋转（swim的ing形式）','/ˈswɪmɪŋ/','/ˈswɪmɪŋ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alternative','adj.供选择的；选择性的；交替的n.二中择一；供替代的选择','/ɒl.ˈtɜː(ɹ).nə.tɪv/','/ɔl.ˈtɝ.nə.tɪv/','noun',["an alternative proposition"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kindness','n.仁慈；好意；友好的行为','/ˈkaɪndnəs/','/ˈkaɪndnəs/','noun',["How can I thank you for your many kindnesses?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accept','v.接受；承认；承担；承兑；容纳','/ækˈsɛpt/','/əkˈsɛpt/','verb',["The Boy Scouts were going to accept him as a member.","I accept the notion that Christ lived.","I accept your proposal, amendment, or excuse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noise','n.[环境]噪音；响声；杂音v.谣传','/nɔɪz/','/nɔɪz/','noun',["He knew that it was trash day, when the garbage collectors made all the noise.","The problems with the new computer system are causing a lot of noise at Head Office."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clear','adj.清楚的；清澈的；晴朗的；无罪的v.通过；清除；使干净；跳过adv.清晰地；完全地n.清除；空隙','/klɪə(ɹ)/','/klɪɹ/','noun',["a room ten feet square in the clear","If you clear the table, I''ll wash up.","Please clear all this stuff off the table."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adaptation','n.适应；改编；改编本，改写本','/ˌædæpˈteɪʃən/','/ˌædæpˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('novel','adj.新奇的；异常的n.小说','/ˈnɒvl̩/','/ˈnɑvəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inventor','n.发明家；[专利]发明人；创造者','/ɪnˈvɛntə/','/ɪnˈvɛntə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merciful','adj.仁慈的；慈悲的；宽容的','/ˈmɜːsɪfl̩/','/ˈmɝsɪfl̩/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shopping','n.购物，买东西v.购物（shop的ing形式）','/ˈʃɒpɪŋ/','/ˈʃɒpɪŋ/','verb',["He’s shopping for clothes.","Shop our new arrivals.","He shopped his mates in to the police."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soccer','n.英式足球，足球','/ˈsɒk.ə/','/ˈsɒk.ə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pan','n.平底锅；盘状的器皿；淘盘子，金盘，秤盘v.淘金；在浅锅中烹调（食物）；[非正式用语]严厉的批评','/pæn/','/pæn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forecast','v.预报，预测；预示n.预测，预报；预想','/ˈfɔːkɑːst/','/ˈfɔɹkæst/','noun',["to forecast a rise in prices"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drunk','v.喝酒（drink的过去分词）adj.喝醉了的','/dɹʌŋk/','/dɹʌŋk/','verb',["He drank the water I gave him.","Jack drank the whole bottle by himself.","Everyone who is drinking is drinking, but not everyone who is drinking is drinking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whom','pron.谁（who的宾格）','/huːm/','/huːm/','pronoun',["He''s a person with whom I work. (defining)","To whom it may concern, all business of John Smith Ltd. has now been transferred to Floggitt & Runne."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mind','n.理智，精神；意见；智力；记忆力v.介意；专心于；照料','/maɪnd/','/maɪnd/','noun',["Despite advancing age, his mind was still as sharp as ever.","There was no doubt in his mind that they would win.","My mind just went blank."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sideways','adv.向侧面地；向一旁adj.向侧面的；一旁的','/ˈsaɪdweɪz/','/ˈsaɪdweɪz/','noun',["He gave the ball a sideways kick.","There was a stack of papers in front of each seat at the table, but each stack was sideways.","Once we get out of this sideways economy, our figures will more accurately reflect what we''re truly capable of."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spare','v.节约，吝惜；饶恕；分出，分让adj.多余的；瘦的；少量的n.剩余；备用零件','/ˈspɛə(ɹ)/','/ˈspɛəɹ/','noun',["a spare diet","I have no spare time.","a spare anchor; a spare bed or room"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unique','adj.独特的，稀罕的；[数]唯一的，独一无二的n.独一无二的人或物','/juːˈniːk/','/juːˈniːk/','noun',["Every person has a unique life, therefore every person has a unique journey. ― Gary Cook"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('export','n.输出，出口；出口商品v.输出物资','/ˈɛks.pɔːt/','/ˈɛks.pɔːt/','noun',["Oil is the main export of Saudi Arabia.","The export of fish is forbidden in this country.","Japan exports electronic goods throughout the world."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('success','n.成功，成就；胜利；大获成功的人或事物','/səkˈsɛs/','/səkˈsɛs/','noun',["His third attempt to pass the entrance exam was a success.","Don''t let success go to your head.","Scholastically, he was a success."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mess','n.混乱；食堂，伙食团；困境；脏乱的东西v.弄乱，弄脏；毁坏；使就餐','/mɛs/','/mɛs/','noun',["He made a mess of it.","My boss dumped a whole mess of projects on my desk today.","Parked under a tree, my car was soon covered in birds'' mess."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airmail','n.航空邮件','/ˈɛə.meɪl/','/ˈɛə.meɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('innocent','adj.无辜的；无罪的；无知的n.天真的人；笨蛋','/ˈɪnəsn̩t/','/ˈɪnəsn̩t/','noun',["The slaughter of the innocents was a significant event in the New Testament.","an innocent trade","innocent goods carried to a belligerent nation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('care','n.关怀；照料；谨慎；忧虑v.照顾；关心；喜爱；顾虑','/kɛə/','/ke(ə)ɹ/','noun',["Care should be taken when holding babies.","I don''t have a care in the world.","dental care"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grand','adj.宏伟的；豪华的；极重要的n.大钢琴；一千美元','/ɡɹænd/','/ɡɹænd/','noun',["a grand army","His simple vision has transformed into something far more grand.","The Grand Viziers of the Ottoman Empire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('triangle','n.三角（形）；三角关系；三角形之物；三人一组','/ˈtɹaɪəŋɡəl/','/ˈtɹaɪˌæŋɡəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('full','adj.完全的，完整的；满的，充满的；丰富的；完美的；丰满的；详尽的adv.十分，非常；完全地；整整v.把衣服缝得宽大n.全部；完整','/fʊl/','/fʊl/','adjective',["The jugs were full to the point of overflowing.","Our book gives full treatment to the subject of angling.","She had tattoos the full length of her arms.   He was prosecuted to the full extent of the law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('translation','n.翻译；译文；转化；调任','/tɹæns-/','/tɹæn(t)sˈleɪʃ(ə)n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pound','n.英镑；重击，重击声；兽栏；拘留所v.捣烂；敲打；监禁，拘留','/paʊnd/','/paʊnd/','noun',["the Rhode Island pound; the New Hampshire pound"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('count','v.计算；认为n.计数；计算；伯爵','/kaʊnt/','/kaʊnt/','noun',["Give the chairs a quick count to check if we have enough.","He has a 3–2 count with the bases loaded.","Can you count to a hundred?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('or','conj.或，或者；还是n.(Or)人名；(中)柯(广东话·威妥玛)；(柬)奥；(土、匈、土库、阿塞、瑞典)奥尔','/ɔː(ɹ)/','/ɔɹ/','conjunction',["He might get cancer, or be hit by a bus, or God knows what.","It''s raining! Come inside or you''ll catch a cold!","The country Myanmar, or Burma"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paddle','n.划桨；明轮翼v.拌；搅；用桨划','/ˈpæ.dəl/','/ˈpæ.dəl/','noun',["We had a nice paddle this morning.","The paddle practically ousted the British cane for spankings in the independent US.","A sea turtle''s paddles make it swim almost as fast as land tortoises are slow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invitation','n.邀请；引诱；请帖；邀请函','/ɪn.vɪˈteɪ.ʃn̩/','/ɪn.vɪˈteɪ.ʃn̩/','noun',["an invitation to a party, to a dinner, or to visit a friend","We need to print off fifty invitations for the party."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('test','n.试验；检验v.试验；测试','/test/','/test/','noun',["Climbing the mountain tested our stamina.","to test the soundness of a principle; to test the validity of an argument","He tested positive for cancer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bathtub','n.浴缸','/ˈbæθtʊb/','/ˈbæθtʊb/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opinion','n.意见；主张','/əˈpɪnjən/','/əˈpɪnjən/','noun',["Every man is a fool in some man''s opinion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delight','n.高兴v.高兴','/dəˈlaɪt/','/dəˈlaɪt/','noun',["A beautiful landscape delights the eye."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirst','n.渴望；口渴；热望v.渴望；口渴','/θɜːst/','/θɝst/','noun',["a thirst for gold","I thirst for knowledge and education will sate me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('register','v.登记；注册；记录；挂号邮寄；把…挂号；正式提出n.登记；注册；记录；寄存器；登记簿','/ˈɹɛdʒ.ɪs.tə/','/ˈɹɛdʒ.ɪs.tɚ/','noun',["The teacher took the register by calling out each child''s name.","a register of deeds","My ex-boss used \"let go\", in the euphemistic register, when he sacked me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opening','n.开始；机会；通路；空缺的职位adj.开始的v.开放（open的ing形式）；打开；公开','/ˈəʊ.pənɪŋ/','/ˈoʊ.pənɪŋ/','verb',["Turn the doorknob to open the door.","He opened a path through the undergrowth.","I don''t want to open that subject."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puzzle','v.使…困惑；使…为难；苦思而得出n.谜；难题；迷惑','/ˈpʌzəl/','/ˈpʌzəl/','noun',["Where he went after he left the house is a puzzle.","to be in a puzzle","We puzzled over the curious-shaped lock, but were unable to discover how the key should be inserted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('we','pron.我们（主格）；笔者，本人（作者或演讲人使用）；朕，寡人n.(We)人名；(缅)韦','/wiː/','/wi/','pronoun',["How are we all tonight?","How are we feeling this morning?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bear','v.结果实，开花（正式）n.熊','/bɛə(ɹ)/','/bɑɹ/','noun',["That window can be a bear to open.","to bear a railroad stock","The great bear market starting in 1929 scared a whole generation of investors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bedroom','n.卧室adj.两性关系的；城郊住宅区的','/ˈbɛdɹʊm/','/ˈbɛdɹʊm/','noun',["Please don''t enter my bedroom without knocking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurricane','n.飓风，暴风','/ˈhʌɹɪkən/','/ˈhɝɪˌkeɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mouthful','n.一口，满口','','','noun',["He swallowed a mouthful of sea water when he fell in.","“She sells sea shells” is a bit of a mouthful to say."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apologize','v.道歉；辩解；赔不是','/əˈpɒləd͡ʒaɪz/','/əˈpɑləd͡ʒaɪz/','verb',["My correspondent apologized for not answering my letter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handtruck','手推车','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garbage','n.垃圾；废物','/ˈɡɑːbɪd͡ʒ/','/ɡɑ(ɹ)ˈbɑːʒ/','noun',["Garbage is collected on Tuesdays; rubbish on Fridays","The garbage truck collects all residential municipal waste.","He threw the newspaper into the garbage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spelling','n.拼写；拼字；拼法v.拼写；意味着（spell的ing形式）；迷住','/ˈspɛlɪŋ/','/ˈspɛlɪŋ/','verb',["I find it difficult to spell because I''m dyslexic.","The letters “a”, “n” and “d” spell “and”.","Please spell it out for me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('useful','adj.有用的，有益的；有帮助的','/ˈjuːsfəl/','/ˈjuːsfəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronomy','n.天文学','/æˈstɹɑnəˌmi/','/æˈstɹɑnəˌmi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lesson','n.教训；课vt.教训；上课','/ˈlɛsn̩/','/ˈlɛsn̩/','noun',["In our school a typical working week consists of around twenty lessons and ten hours of related laboratory work.","Nature has many lessons to teach to us.","I hope this accident taught you a lesson!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harbour','v.藏匿；入港停泊；庇护n.海港（等于harbor）；避难所','/ˈhɑːbə/','/ˈhɑɹbəɹ/','noun',["The neighborhood is a well-known harbor for petty thieves.","The docks, which once harbored tall ships, now harbor only petty thieves.","The fleet harbored in the south."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('herself','pron.她自己（she的反身代词）；她亲自','/hɜːˈsɛlf/','/hɝˈsɛlf/','pronoun',["She injured herself.","She was injured herself.","Have you seen herself yet this morning?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiet','adj.安静的；安定的；不动的；温顺的n.安静；和平v.使平息；安慰','/ˈkwaɪ.ət/','/ˈkwaɪ.ət/','noun',["There was a strange quiet in the normally very lively plaza.","When you quiet, we can start talking.","Can you quiet your child? He''s making lots of noise."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downstairs','adv.在楼下adj.楼下的n.楼下','/daʊnˈstɛəz/','/daʊnˈstɛɹz/','noun',["The wind lifted up her skirt and I caught a glimpse of her downstairs.","The kids sleep in the downstairs bedroom, we sleep in the upstairs one.","walk downstairs"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violent','adj.暴力的；猛烈的','/ˈvaɪ(ə)lənt/','/ˈvaɪ(ə)lənt/','noun',["A violent wind ripped the branch from the tree.","We would rather negotiate, but we will use violent means if necessary.","The escaped prisoners are considered extremely violent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dictation','n.听写；口述；命令','/dɪkˈteɪʃən/','/dɪkˈteɪʃən/','noun',["Since I learned shorthand, I can take dictation at eighty words a minute.","1908: Lucy Maud Montgomery, Anne of Green Gables - We had reading and geography and Canadian history and dictation today.","1852: Lysander Spooner, An Essay on the Trial by Jury - ...jurors in England have formerly understood it to be their right and duty to judge only according to their consciences, and not to submit to any dictation from the court, either as to law or fact."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cathedral','n.大教堂','/kəˈθiː.dɹəl/','/kəˈθiː.dɹəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respect','n.尊敬，尊重；方面；敬意v.尊敬，尊重；遵守','/ɹɪˈspɛkt/','/ɹɪˈspɛkt/','noun',["He is an intellectual giant, and I have great respect for him.","The mourners paid their last respects to the deceased poet.","This year''s model is superior to last year''s in several respects."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expression','n.表现，表示，表达；表情，脸色，态度，腔调，声调；式，符号；词句，语句，措辞，说法','/ɪkˈspɹɛʃ.ən/','/ɪkˈspɹɛʃ.ən/','noun',["The expression \"break a leg!\" should not be taken literally.","Her expression changed from joy to misery after realising her winning lottery ticket had expired.","expression from a gland"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dioxide','n.二氧化物','/daɪˈɒksaɪd/','/daɪˈɒksaɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('villager','n.乡村居民，村民','/ˈvɪlɪd͡ʒə/','/ˈvɪlɪd͡ʒə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guidance','n.指导，引导；领导','/ˈɡaɪdəns/','/ˈɡaɪdəns/','noun',["divine guidance"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grey','adj.灰色的；灰白的v.使变成灰色；使变老n.灰色','/ɡɹeɪ/','/ɡɹeɪ/','adjective',["Wash colored items separately from whites and darks to prevent the colors from bleeding.","The room was red, with a dark-colored rug.","The singer wore a colored shirt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refer','v.参考；涉及；提到；查阅','/ɹɪˈfɜː/','/ɹɪˈfɝ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('booth','n.货摊；公用电话亭','/buːð/','/buːð/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bookmark','n.书签（等于bookmarker）；标记','/ˈbʊkmɑɹk/','/ˈbʊkmɑɹk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('walkman','n.随身听（商标名称）','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ha','int.哈！（表示惊异，愉快，怀疑，胜利等）abbr.一种元素(hahnium,原子序105)n.(Ha)人名；(德)哈；(日)巴(姓)','/hɑː/','','interjection',["Ha, ha, ha! That’s funny.","Ha! Checkmate!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('culture','n.文化，文明；修养；栽培v.[细胞][微]培养（等于cultivate）','/ˈkʌlt͡ʃə/','/ˈkʌlt͡ʃɚ/','noun',["I''m headed to the lab to make sure my cell culture hasn''t died."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burial','n.埋葬；葬礼；弃绝adj.埋葬的','/ˈbɛɹɪəl/','/ˈbɛɹiəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bored','adj.无聊的；无趣的；烦人的v.使厌烦（bore的过去式）；烦扰','/bɔːd/','/bɔːd/','verb',["An insect bores into a tree.","to bore a steam cylinder or a gun barrel; to bore a hole","to bore one''s way through a crowd"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possess','v.控制；使掌握；持有；迷住；拥有，具备','/pəˈzɛs/','/pəˈzɛs/','verb',["He does not even possess a working telephone.","They thought he was possessed by evil spirits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ease','v.减轻，缓和；使安心n.轻松，舒适；安逸，悠闲','/iːz/','/iz/','noun',["He eased his conscience by confessing.","He loosened his shoe to ease the pain.","The provision of extra staff eased their workload."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gardening','n.园艺；园林工人的工作','','','verb',["I love to garden — this year I''m going to plant some daffodils.","His hobby was gardening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whatever','adj.不管什么样的pron.无论什么；诸如此类conj.无论什么','/wɒtˈɛvə/','/wʌtˈɛvɚ/','adjective',["There is no point whatever in going on with this discussion.","Whatever he does, he will still lose the game.","I’ll do whatever I can."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawback','n.缺点，不利条件；退税','/ˈdɹɔːˌbæk/','/ˈdɹɔːˌbæk/','noun',["Poor fuel economy is a common drawback among larger vehicles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('database','n.数据库，资料库','/ˈdeɪtəˌbeɪs/','/ˈdeɪtəˌbeɪs/','noun',["I have a database of all my contacts in my personal organizer.","The \"books\" database will have three tables, and the \"customers\" database will have two tables.","Which database do you use: MySQL or Oracle?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poisonous','adj.有毒的；恶毒的；讨厌的','/ˈpɔɪznəs/','/ˈpɔɪznəs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('throat','n.喉咙；嗓子，嗓音；窄路vt.开沟于；用喉音说','/ˈθɹəʊt/','/ˈθɹoʊt/','noun',["The wild pitch bounced and hit the catcher in the throat.","As I swallowed I felt something strange in my throat.","The water leaked out from the throat of the bottle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wise','adj.明智的；聪明的；博学的v.使知道；教导n.(Wise)人名；(英)怀斯','/waɪz/','/waɪz/','verb',["After Mo had a word with him, he wised up.","\"It is a profitable thing, if one is wise, to seem foolish\" - Aeschylus","Don''t get wise with me!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('importance','n.价值；重要；重大；傲慢','/ɪmˈpɔːtəns/','/ɪmˈpɔɹtəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Baby','n.婴儿，婴孩；孩子气的人v.纵容，娇纵；把……当婴儿般对待adj.婴儿的；幼小的','/ˈbeɪbi/','/ˈbeɪbi/','noun',["When is your baby due?","Stand up for yourself – don''t be such a baby!","I only qualified as an architect this summer, so I''m still a baby."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hunter','n.猎人；猎犬；搜寻者','/ˈhʌntɚ/','/ˈhʌntɚ/','noun',["The hunter becomes the hunted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acid','n.酸；<俚>迷幻药adj.酸的；讽刺的；刻薄的','/ˈæs.ɪd/','/ˈæs.ɪd/','noun',["acid fruits or liquors"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('signature','n.署名；签名；信号','/ˈsɪɡnətʃə/','/ˈsɪɡnətʃə/','noun',["Your signature must not exceed 600 pixels.","Rabbit in mustard sauce is my signature dish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('board','n.董事会；木板；甲板；膳食v.上（飞机、车、船等）；用板盖上；给提供膳宿','/bɔːd/','/bɔːd/','noun',["Each player starts the game with four counters on the board.","We have to wait to hear back from the board.","Room and board"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('November','n.十一月','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accelerate','v.使……加快；使……增速','/æk.ˈsɛl.ə.ˌɹeɪt/','','verb',["to accelerate the growth of a plant, the increase of wealth, etc.","to accelerate our departure"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cow','n.奶牛，母牛；母兽v.威胁，恐吓','/kaʊ/','/kaʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motor','n.发动机，马达；汽车adj.汽车的；机动的v.乘汽车','/ˈməʊtə/','/ˈmoʊtɚ/','noun',["Nice motor!","On Saturday we motored down to Plymouth.","Sales were slow at first, but now things are really motoring."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('birth','n.出生；血统，出身；起源','/bɜːθ/','/bɝθ/','noun',["Intersex babies account for roughly one per cent of all births.","the birth of an empire","He was of noble birth, but fortune had not favored him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wife','n.妻子，已婚妇女；夫人','/waɪf/','/waɪf/','noun',["A new wife for the gander is introduced into the pen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('totally','adv.完全地','/ˈtoʊt.əl.i/','/ˈtoʊt.əl.i/','adverb',["They''ve totally demolished the bank on Main Street.","That was totally wicked!","That was totally not what happened."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('situation','n.情况；形势；处境；位置','/sɪtjuːˈeɪʃən/','/sɪtjuːˈeɪʃən/','noun',["The United States is in an awkward situation with debt default looming.","The Botanical Gardens are in a delightful situation on the river bank.","Boss, we''ve got a situation here..."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('winter','n.冬季；年岁；萧条期v.过冬adj.冬天的；越冬的','/ˈwɪntɚ/','/ˈwɪntɚ/','noun',["When they retired, they hoped to winter in Florida."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apparent','adj.显然的；表面上的','/əˈpæ.ɹənt/','/əˈpæ.ɹənt/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('picnic','n.野餐v.去野餐','/ˈpɪknɪk/','/ˈpɪknɪk/','noun',["We went out for a picnic in the forest.","We remind the guests that dealing with this problem is no picnic, and to be patient."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carbon','n.[化学]碳；碳棒；复写纸adj.碳的；碳处理的','/ˈkɑɹbən/','/ˈkɑɹbən/','noun',["A methane molecule is made up of a single carbon with four hydrogens.","When I send it, I''ll carbon Julia so she''s aware."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proud','adj.自豪的；得意的；自负的n.(Proud)人名；(英)普劳德','/pɹaʊd/','/pɹaʊd/','adjective',["I am proud of Sivu’s schoolwork.","I was too proud to apologise.","It was a proud day when we finally won the championship."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Italy','n.意大利（欧洲南部国家）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('energy','n.[物]能量；精力；活力；精神','/ˈɛnəd͡ʒi/','/ˈɛnɚd͡ʒi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lifetime','n.一生；寿命；终生；使用期adj.一生的；终身的','/ˈlaɪftaɪm/','/ˈlaɪftaɪm/','noun',["I''ve been waiting a lifetime for a train."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entry','n.进入；入口；条目；登记；报关手续；对土地的侵占','/ˈɛntɹi/','/ˈɛntɹi/','noun',["Children are allowed entry only if accompanied by an adult.","What does the entry for 2 August 2005 say?","The entry in the second row and first column of this matrix is 6."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('general','adj.一般的，普通的；综合的；大体的n.一般；将军，上将；常规','/ˈd͡ʒɛnɹəl/','/ˈd͡ʒɛnəɹəl/','noun',["We have dealt with the generals; now let us turn to the particulars.","Hannibal was one of the greatest generals of the ancient world.","I work in general."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bean','n.豆；嘴峰；毫无价值的东西v.击…的头部','/biːn/','/biːn/','noun',["I haven''t got a bean.","The pitcher beaned the batter, rather than letting him hit another home run."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('such','adj.这样的，如此的n.(Such)人名；(英)萨奇；(德)祖赫','/sʌt͡ʃ/','/sʌt͡ʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruct','v.指导；通知；命令；教授','/ˌɪnˈstɹʌkt/','/ˌɪnˈstɹʌkt/','noun',["Listen carefully when someone instructs you how to assemble the furniture.","The doctor instructed me to keep my arm immobilised and begin physiotherapy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amusement','n.消遣，娱乐；乐趣','/əˈmjuzmənt/','/əˈmjuzmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afterward','adv.以后，后来','/ˈɑːftə.wəd/','/ˈæf.tɚ.wɚd/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defense','n.防卫，防护；防御措施；防守vt.谋划抵御','/dɪˈfɛns/','/dɪˈfɛns/','noun',["Department of Defense"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fellow','n.家伙；朋友；同事；会员adj.同伴的，同事的；同道的vt.使…与另一个对等；使…与另一个匹敌','/ˈfɛləʊ/','/ˈfɛloʊ/','noun',["Roger and his fellow workers are to go on strike.","I''ve lost touch with all my old schoolmates: I only see them at class reunions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accumulate','v.累积；积聚','/əˈkjuːmjʊˌleɪt/','/ə.ˈkjum.jə.ˌleɪt/','verb',["He wishes to accumulate a sum of money."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opera','n.歌剧；歌剧院；歌剧团','/ˈɒp.əɹ.ə/','/ˈɑ.pəɹ.ə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phrase','n.短语,习语,措辞,乐句v.措词,将(乐曲)分成乐句','/fɹeɪz/','/fɹeɪz/','noun',["I wasn''t sure how to phrase my condolences without sounding patronising."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheap','adj.便宜的；小气的；不值钱的adv.便宜地','/t͡ʃiːp/','/t͡ʃiːp/','noun',["the cheap trick of hiding deadly lava under pushable blocks","Insurance is expensive, but don''t be so cheap that you risk losing your home because of a fire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deer','n.鹿','/diːɹ/','/dɪɹ/','noun',["I wrecked my car after a deer ran across the road.","Oh, I''ve never had deer before."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('internet','n.因特网','/ˈɪntəˌnɛt/','/ˈɪntɚˌnɛt/','noun',["Do you have internet at your place?  My internet is down and I want to check my email.","Having no idea what that means, I am internetting like mad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('course','n.科目；课程；过程；进程；道路；路线，航向；一道菜v.追赶；跑过','/kɔːs/','/kɔɹs/','noun',["The normal course of events seems to be just one damned thing after another.","His illness ran its course.","Main course and mainsail are the same thing in a sailing ship."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glare','n.刺眼；耀眼的光；受公众注目v.瞪眼表示','/ɡlɛə/','/ɡlɛə/','noun',["a glare of ice","He walked in late, with the teacher glaring at him the whole time.","The sun glared down on the desert sand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('walk','n.步行，走；散步v.散步；走过','/wɔːk/','/wɔk/','verb',["To walk briskly for an hour every day is to keep fit.","If you can’t present a better case, that robber is going to walk.","If you leave your wallet lying around, it’s going to walk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weep','v.哭泣；流泪；哀悼；滴落；渗出液体n.哭泣；眼泪；滴下','/wiːp/','/wiːp/','noun',["Sometimes you just have to have a good weep.","a weeping spring, which discharges water slowly"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brilliant','adj.灿烂的，闪耀的；杰出的；有才气的；精彩的，绝妙的','/ˈbɹɪljənt/','/ˈbɹɪljənt/','noun',["the brilliant lights along the promenade","butterflies with brilliant blue wings","The actor''s performance in the play was simply brilliant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radioactive','adj.[核]放射性的；有辐射的','/ˌɹeɪdioʊˈaktɪv/','/ˌɹeɪdioʊˈaktɪv/','noun',["Even sleazy tactics and his radioactive mouth may not be able to contain this debacle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wave','v.波动；起伏；挥手示意；摇动；呈波形n.波动；波浪；高潮；挥手示意；卷曲','/weɪv/','/weɪv/','verb',["The flag waved in the gentle breeze.","I waved goodbye from across the room.","Jones waves at strike one."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tomb','n.坟墓；死亡vt.埋葬','/tuːm/','/tum/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seize','v.抓住；夺取；理解；逮捕','/siːz/','/siːz/','verb',["to seize a ship after libeling","a fever seized him","to seize or stop one rope on to another"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('design','v.设计；计划；构思n.设计；图案','/dɪˈzaɪn/','/dɪˈzaɪn/','noun',["To be hateful of the truth by design.","Danish furniture design is world-famous.","The king designed to mount an expedition to the New World."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('small','adj.少的，小的；微弱的；几乎没有的；不重要的；幼小的adv.小小地；卑鄙地n.小件物品；矮小的人','/smɔːl/','/smɔl/','noun',["A small group.","Remember when the children were small?","a small space of time"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heat','n.高温；压力；热度；热烈v.使激动；把…加热','/hit/','/hit/','noun',["This furnace puts out 5000 BTUs of heat.   That engine is really throwing off some heat.   Removal of heat from the liquid caused it to turn into a solid.","Stay out of the heat of the sun!","The chili sauce gave the dish heat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('junk','n.垃圾，废物；舢板','/dʒʌŋk/','/dʒʌŋk/','noun',["junk fish; junk trees","(On Facebook, a record collector wrote:) \"The newest addition to my Annette Hanshaw collection, I junked this beautiful flawless E-copy within walking distance from my house.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sorrow','n.悲伤；懊悔；伤心事v.懊悔；遗憾；感到悲伤','/ˈsɔɹoʊ/','/ˈsɑɹoʊ/','noun',["Parting is such sweet sorrow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bungalow','n.平房；小屋','','','noun',["My aunt can''t manage the stairs any more, so she''s moving to a bungalow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technology','n.技术；工艺；术语','/tɛkˈnɒlədʒi/','/tɛkˈnɒlədʒi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardly','adv.几乎不，简直不；刚刚','/ˈhɑːdli/','/ˈhɑɹdli/','adverb',["I can''t really deal hardly with people.","they hardly ever watch television;  I hardly think they''ll come in this bad weather;  it''s hardly possible he could lose the election.","I think the Beatles are a really overrated band. ― Hardly!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fee','n.费用；酬金；小费v.付费给……','/fiː/','/fiː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('promise','n.许诺，允诺；希望v.允诺，许诺；给人以…的指望或希望','/ˈpɹɒmɪs/','/ˈpɹɑmɪs/','noun',["if I make a promise, I always stick to it;  he broke his promise","She shows great promise as an actress.","He promised to never return to this town again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mass','n.块，团；群众，民众；大量，众多；质量adj.群众的，民众的；大规模的，集中的v.聚集起来，聚集','/mæs/','/mæs/','noun',["I mass 70 kilograms.","There is evidence of mass extinctions in the distant past.","Mass unemployment resulted from the financial collapse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('settle','v.解决；定居；沉淀；下陷n.有背长椅','/ˈsɛtəl/','/ˈsɛtəl/','verb',["to settle her estate","the weather settled;  wait until the crowd settles before speaking","the Saxons who settled in Britain"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competitor','n.竞争者，对手','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chapter','n.章，回；（俱乐部、协会等的）分会；人生或历史上的重要时期vt.把…分成章节','/ˈt͡ʃæptə/','/ˈt͡ʃæptɚ/','noun',["Detective novel writers try to keep up the suspense until the last chapter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electricity','n.电力；电流；强烈的紧张情绪','/ɪˌlɛkˈtɹɪsɪti/','/iˌlɛkˈtɹɪsɪti/','noun',["Opening night for the new production had an electricity unlike other openings."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sudden','adj.突然的，意外的；快速的n.突然发生的事','/ˈsʌdən/','/ˈsʌdən/','noun',["The sudden drop in temperature left everyone cold and confused."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supreme','adj.最高的；至高的；最重要的n.至高；霸权','/ˌs(j)uːˈpɹiːm/','','noun',["supreme disgust; supreme courage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eyewitness','n.目击者；见证人','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('information','n.信息，资料；知识；情报；通知','/ˌɪnfəˈmeɪʃən/','/ˌɪnfəɹˈmeɪʃən/','noun',["I need some more information about this issue.","For your information, I did this because I wanted to."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('queue','n.队列；长队；辫子v.排队；排队等候','/kjuː/','/kjuː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candy','v.用糖煮；使结晶为砂糖；美化n.糖果（等于sweets）；冰糖（等于sugarcandy，rockcandy）；毒品adj.新潮的（服饰）；甜言蜜语的','/ˈkændi/','/ˈkændi/','noun',["Fruits preserved in sugar candy after a time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleep','v.睡，睡觉n.睡眠','/sliːp/','/slip/','verb',["You should sleep 8 hours a day.","This caravan can sleep four people comfortably.","to sleep a dreamless sleep"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('act','v.扮演；装作，举动像n.行为，行动；法令，法案；（戏剧，歌剧的）一幕，段；装腔作势','/æk/','/æk/','noun',["an act of goodwill","He was caught in the act of stealing.","The pivotal moment in the play was in the first scene of the second act."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belt','n.带；腰带；地带v.用带子系住；用皮带抽打','/bɛlt/','/bɛlt/','noun',["As part of the act, the fat clown''s belt broke, causing his pants to fall down.","Keep your belt fastened; this is going to be quite a bumpy ride.","The motor had a single belt that snaked its way back and forth around a variety of wheels."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('widespread','adj.普遍的，广泛的；分布广的','','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('study','n.学习，研究；课题；书房；学问v.学习；考虑；攻读；细察','/ˈstʌdi/','/ˈstʌdi/','verb',["I need to study my biology notes.","I study medicine at the university.","Biologists study living things."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advantage','n.优势；利益；有利条件v.获利','/ədˈvɑːn.tɪdʒ/','/ədˈvæn.tɪdʒ/','noun',["The enemy had the advantage of a more elevated position.","Having the faster car is of little advantage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abnormal','adj.反常的，不规则的；变态的','/əbˈnɔɹ.ml̩/','/əbˈnɔɹ.ml̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('output','n.输出，输出量；产量；出产v.输出','/ˈaʊtpʊt/','/ˈaʊtpʊt/','noun',["The factory increased its output this year.","a six-page output; six pages of output","We output 1400 units last year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headmaster','n.校长','/ˈhɛdˌmɑːstə/','/ˈhɛdˌmɑːstə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sport','n.运动；游戏；娱乐；运动会；玩笑v.游戏adj.运动的','/spɔːt/','/spɔɹt/','noun',["Joe was banned from getting legal help. He seemed to view lawsuits as a sport.","Jen may have won, but she was sure a poor sport; she laughed at the loser.","You''re such a sport! You never get upset when we tease you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admirable','adj.令人钦佩的；极好的；值得赞扬的','/ˈæd.məɹ.ə.bəl/','/ˈæd.məɹ.ə.bəl/','adjective',["It''s admirable that Shelley overcame her handicap and excelled in her work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dash','n.破折号；冲撞v.使…破灭；猛撞；泼溅','/dæʃ/','/dæʃ/','noun',["Add a dash of vinegar.","There is a dash of craziness in his personality.","Aren''t we full of dash this morning?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirteen','n.十三；十三岁；十三个num.十三adj.十三的；十三个的','/ˌθɜːˈtiːn/','/ˈθɜɹ.tin/','numeral',["There are thirteen cards of each of the four suits in a deck of playing cards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambition','n.野心，雄心；抱负，志向v.追求；有…野心','/æmˈbɪ.ʃən/','/æmˈbɪ.ʃən/','noun',["My son, John, wants to be a firefighter very much. He has a lot of ambition.","My ambition is to own a helicopter.","Pausanias, ambitioning the sovereignty of Greece, bargains with Xerxes for his daughter in marriage. — Trumbull."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enter','v.进入；开始；参加n.[计]输入；回车','/ˈɛntə(ɹ)/','/ˈɛntɚ/','noun',["You should knock before you enter, unless you want to see me naked.","to enter a knife into a piece of wood;  to enter a boy at college, a horse for a race, etc.","My twelve-year-old son will be entering his teens next year.  She had planned to enter the legal profession."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('able','adj.能；[经管]有能力的；能干的n.(Able)人名；(伊朗)阿布勒；(英)埃布尔','/ˈeɪ.bl̩/','/ˈeɪ.bl̩/','adjective',["I’ll see you as soon as I’m able.","After the past week of forced marches, only half the men are fully able.","He was born to an able family."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('severe','adj.严峻的；严厉的；剧烈的；苛刻的','/sɪˈvɪə/','','adjective',["a severe taskmaster","a severe old maiden aunt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sharpener','n.卷笔刀；[机]磨具；研磨者','/ˈʃɑː(ɹ)pənə(ɹ)/','/ˈʃɑː(ɹ)pənə(ɹ)/','noun',["There was a pencil sharpener at the front of the classroom."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dream','v.梦想；做梦，梦见；想到n.梦想，愿望；梦adj.梦的；理想的；不切实际的','/dɹiːm/','/dɹim/','noun',["a dream of bliss","Stop dreaming and get back to work.","I dreamed a vivid dream last night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bookshelf','n.书架','/ˈbʊkˌʃɛlf/','/ˈbʊkˌʃɛlf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('analyze','v.对…进行分析，分解（等于analyse）','/ˈæn.ə.laɪz/','/ˈæn.ə.laɪz/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('woman','n.妇女；女性；成年女子','/ˈwʊmən/','/ˈwʊmən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extraordinary','adj.非凡的；特别的；离奇的；临时的；特派的','/ɪksˈtɹɔː(ɹ)dɪnəɹi/','','noun',["an extraordinary poet","an extraordinary professor in a German university"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outcome','n.结果，结局；成果','/ˈaʊtkʌm/','/ˈaʊtkʌm/','noun',["A quality automobile is the outcome of the work of skilled engineers and thousands of workers.","Three is a possible outcome of tossing a six-sided die.","The outcomes of this course are outlined in your syllabus."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yoghurt','n.酸奶（等于yoghourt）；酸乳酪','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('make','v.使得；进行；布置，准备，整理；制造；认为；获得；形成；安排；引起；构成n.制造；构造；性情','/meɪk/','/meɪk/','noun',["What make of car do you drive?","The camera was of German make.","He made as if to punch him, but they both laughed and shook hands."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('only','adv.只，仅仅；不料adj.唯一的，仅有的；最合适的conj.但是；不过；可是','/ˈəʊn.li/','/ˈoʊn.li/','noun',["He is the only doctor for miles.","He is their only son, in fact, an only child.","My heart is hers, and hers only."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('title','n.冠军；标题；头衔；权利；字幕v.加标题于；赋予头衔；把…称为adj.冠军的；标题的；头衔的','/ˈtaɪtl̩/','/ˈtaɪtl̩/','noun',["a good title to an estate, or an imperfect title","I know the singer''s name, but not the title of the song.","Buyers of the new video game console can choose from three bundled titles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('card','n.卡片；纸牌；明信片v.记于卡片上','/kaːd/','/kɑɹd/','noun',["He played cards with his friends.","He accused them of playing the race card.","What’s on the card for tonight?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spell','v.拼，拼写；意味着；招致；拼成；迷住；轮值n.符咒；一段时间；魅力','/spɛl/','/spɛl/','noun',["He cast a spell to cure warts.","under a spell"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('win','v.赢得；在…中获胜；劝诱n.赢；胜利','/wɪn/','/wɪn/','verb',["to win the jackpot in a lottery;  to win a bottle of wine in a raffle","Who would win in a fight between an octopus and a dolphin?","Ever since the 2013 Boston Marathon bombing, Bostonians now run as \"One Boston.\" The terrorists did not win."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Australian','adj.澳大利亚的，澳大利亚人的n.澳大利亚人','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('champion','n.冠军；拥护者；战士v.支持；拥护adj.优胜的；第一流的','/ˈtʃæmpiən/','/ˈtʃæmpiən/','noun',["The defending champion is expected to defeat his challenger.","Barcelona is eligible to play in FIFA Club World Cup as the champion of Europe.","champion of women''s suffrage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clarify','v.澄清；阐明','/ˈklæɹɪfaɪ/','/ˈklæɹɪfaɪ/','verb',["Leave the wine for 24 hours and it will clarify."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comedy','n.喜剧；喜剧性；有趣的事情','/ˈkɒmədi/','/ˈkɑmədi/','noun',["Why would you be watching comedy when there are kids starving right now?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biography','n.传记；档案；个人简介','/baɪˈɒɡɹəfi/','/baɪˈɑːɡɹəfi/','noun',["There are many biographies of Benjamin Franklin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clock','n.时钟；计时器v.记录；记时','/klɒk/','/klɑk/','noun',["This car has over 300,000 miles on the clock.","I can''t go off to lunch yet: I''m still on the clock.","He was clocked at 155 miles per hour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('employ','v.使用，采用；雇用；使忙于，使从事于n.使用；雇用','/ɛmˈplɔɪ/','/ɛmˈplɔɪ/','noun',["The school district has six thousand teachers in its employ.","Yesterday our local garage employed a new mechanic.","The burglar employed a jemmy to get in."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sixth','n.月的第六日，（与the连用的）第六个；六分之一adj.（与the连用）第六的，第六个的；六分之一的','/sɪk(s)θ/','/sɪk(s)θ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('injure','v.伤害，损害','/ˈɪndʒə/','/ˈɪndʒɚ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('period','n.周期，期间；时期；月经；课时；（语法学）句点，句号adj.某一时代的','/ˈpɪəɹɪəd/','/ˈpɪəɹɪəd/','noun',["There was a period of confusion following the announcement.","Food rationing continued in the post-war period.","When she is on her period, she prefers not to go swimming."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excuse','n.借口；理由v.原谅；为…申辩；给…免去','','','noun',["Tell me why you were late – and I don''t want to hear any excuses!","He''s a sorry excuse of a doctor.","I excused him his transgressions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prayer','n.祈祷，祷告；恳求；祈祷文','/pɹɛə(ɹ)/','/pɹɛɚ/','noun',["Through prayer I ask for God''s blessings.","In many cultures, prayer involves singing.","Christians recite the Lord''s Prayer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fork','n.叉；餐叉；耙v.叉起；使成叉状','/fɔːk/','/fɔɹk/','noun',["West Fork White River and East Fork White River join together to form the White River of Indiana.","LibreOffice is a fork of OpenOffice.","Are you qualified to drive a fork?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greet','v.欢迎，迎接；致敬，致意；映入眼帘n.(Greet)人名；(英)格里特','/ɡɹiːt/','/ɡɹiːt/','verb',["A brilliant dawn greeted her eyes as she looked out of the window."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pray','v.祈祷；恳求；央求n.(Pray)人名；(匈)普劳伊；(英)普雷','/pɹeɪ/','/pɹeɪ/','verb',["Muslims pray in the direction of Mecca.","pray silence for…"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brown','adj.棕色的，褐色的；太阳晒黑的v.变成褐色n.褐色，棕色','/bɹaʊn/','/bɹaʊn/','noun',["The browns and greens in this painting give it a nice woodsy feel.","Fry the onions until they brown.","Brown the onions in a large frying pan."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burden','n.负担；责任；船的载货量v.使负担；烦扰；装货于','/ˈbɜːdn/','/ˈbɝdn/','noun',["a ship of a hundred tons burden","A burden of gad steel is 120 pounds.","to burden a nation with taxes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civilization','n.文明；文化','[ˌsɪv.ə.lɑeˈzæɪ.ʃən]','[ˌsɪv.ə.lɑeˈzæɪ.ʃən]','noun',["Modern civilization is a product of industrialization and globalization.","A hermit doesn''t much care for civilization.","The teacher''s civilization of the child was no easy task."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rate','n.比率，率；速度；价格；等级v.认为；估价；责骂','/ɹeɪt/','/ɹeɪt/','noun',["At the height of his powers, he was producing pictures at the rate of four a year.","The car was speeding down here at a hell of a rate.","The rate of production at the factory is skyrocketing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('system','n.制度，体制；系统；方法','/ˈsɪstəm/','/ˈsɪstəm/','noun',["There are eight planets in the solar system.","Followers should have a system to follow that works in their interests, not against them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advertise','v.通知；为…做广告；使突出','/ˈadvə(ɹ)taɪz/','/ˈadvə(ɹ)taɪz/','verb',["For personal needs, advertise on the internet or in a local newspaper.","Over the air, they advertise their product on drive-time radio talk shows and TV news shows."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metal','n.金属；合金v.以金属覆盖adj.金属制的','/ˈmɛtəl/','[ˈmɛ.ɾɫ̩]','noun',["We have American Airlines tickets, but it''s on British Airways metal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forgive','v.原谅；免除（债务、义务等）','/fɚˈɡɪv/','/fɚˈɡɪv/','verb',["Forgive others, not because they deserve forgiveness, but because you deserve peace."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fat','adj.肥的，胖的；油腻的；丰满的n.脂肪，肥肉v.养肥；在…中加入脂肪','/fæt/','/fæt/','noun',["We need to trim the fat in this company","I saw Daniel crack a fat.","to live on the fat of the land"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('go','v.走；达到；运转；趋于n.去；进行；尝试','/ɡəʉ/','/ɡoʊ/','noun',["It’s your go.","I’ll give it a go.","We will begin as soon as the boss says it''s a go."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collection','n.采集，聚集；[税收]征收；收藏品；募捐','/kəˈlɛkʃən/','/kəˈlɛkʃən/','noun',["The asteroid belt consists of a collection of dust, rubble, and minor planets.","He has a superb coin collection.","Collection of trash will occur every Thursday."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rich','adj.富有的；肥沃的；昂贵的n.(Rich)人名；(丹)里克；(捷)里赫；(英、西)里奇；(葡、法)里什','/ɹɪt͡ʃ/','/ɹɪt͡ʃ/','verb',["a rich dish; rich cream or soup; rich pastry","a rich treasury; a rich entertainment; a rich crop","rich soil or land; a rich mine"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underwear','n.内衣物','/ˈʌndəwɛə/','/ˈʌndɚwɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choke','v.呛；使窒息；阻塞；抑制；扑灭n.窒息；噎；[动力]阻气门','/t͡ʃəʊk/','/t͡ʃəʊk/','noun',["Ever since he choked on a bone, he has refused to eat fish.","The collar of this shirt is too tight; it’s choking me.","to choke a cave passage with boulders and mud"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oh','int.哦；哎呀（表示惊讶或恐惧等）','/əʊ/','/əʊ/','noun',["Oh! I didn''t see you there.","Oh, wow! That''s amazing.","Oh, so that''s how it works."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sixteenth','num.第十六；十六分之一adj.第十六的；十六分之一的','/ˌsɪksˈtiːnθ/','/ˌsɪksˈtiːnθ/','noun',["A sixteenth of 320 is 20."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elder','n.老人；长辈；年长者；父辈adj.年长的；年龄较大的；资格老的','/ˈeldə/','/ˈeldə/','noun',["We were presented to the village elder.","Respect your elders.","a travelling elder"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beauty','n.美；美丽；美人；美好的东西','/ˈbuːti/','/ˈbjuɾi/','noun',["1988, \"… beauty and recollection, like danger, glamour, greed, hunger- everything but disappointment and desire- were concepts belonging to other people.” -Second Son, Robert Ferro","Brigitte Bardot was a renowned beauty.","What a goal! That was a real beauty!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shy','adj.害羞的；畏缩的，胆怯的v.投；畏缩；惊退；厌恶n.投掷；惊跳','/ʃaɪ/','/ʃaɪ/','noun',["coconut shy","I shy away from investment opportunities I don''t understand.","The horse shied away from the rider, which startled him so much he shied away from the horse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('existence','n.存在，实在；生存，生活；存在物，实在物','/ɛɡ.ˈzɪs.təns/','/ɛɡ.ˈzɪs.təns/','noun',["In order to destroy evil, we must first acknowledge its existence."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('run','v.经营；奔跑；运转n.奔跑；赛跑；趋向；奔跑的路程','/ɹʊn/','/ɹʌn/','verb',["I just got back from my morning run.","I need to make a run to the store.","Let''s go for a run in the car."]);
