INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('living','adj.活的；现存的；活跃的；逼真的n.生活；生存；生计v.生活；居住（live的ing形式）；度过','/ˈlɪvɪŋ/','/ˈlɪvɪŋ/','verb',["He''s not expected to live for more than a few months.","I live at 2a Acacia Avenue.  He lives in LA, but he''s staying here over the summer.","Her memory lives in that song."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carriage','n.运输；运费；四轮马车；举止；客车厢','/ˈkæɹɪdʒ/','/ˈkæɹɪdʒ/','noun',["The carriage ride was very romantic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chain','n.链；束缚；枷锁v.束缚；囚禁；用铁链锁住','/ˈt͡ʃeɪn/','/ˈt͡ʃeɪn/','noun',["He wore a gold chain around the neck.","This led to an unfortunate chain of events.","That chain of restaurants is expanding into our town."]);
