INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('careless','adj.粗心的；无忧无虑的；淡漠的n.(Careless)人名；(英)凯尔利斯','/ˈkɛələs/','/ˈkɛɹləs/','adjective',["Jessica was so careless that she put her shorts on backwards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('river','n.河，江','/ˈɹɪvə/','/ˈɹɪvɚ/','noun',["Occasionally rivers overflow their banks and cause floods.","a river of blood","Johnny rivered me by drawing that ace of spades."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('routine','n.[计]程序；日常工作；例行公事adj.日常的；例行的','/ɹuːˈtiːn/','/ɹuːˈtiːn/','noun',["Connie was completely robotic and emotionless by age 12; her entire life had become one big routine.","stand-up comedy routine"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gymnastics','n.体操；体育；体操运动','/dʒɪmˈnæs.tɪks/','/dʒɪmˈnæs.tɪks/','noun',["Gymnastics was a significant part of the physical education curriculum.","His mental gymnastics are legendary."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('storage','n.存储；仓库；贮藏所','/ˈstɔ.ɹɪd͡ʒ/','/ˈstɔ.ɹɪd͡ʒ/','noun',["There''s a lot of storage space in the loft.","I′d recommend backing up these files to storage before reinstalling the operating system."]);
