INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violate','v.违反；侵犯，妨碍；亵渎','/ˈvaɪəˌleɪt/','/ˈvaɪəˌleɪt/','verb',["Accessing unauthorized files violates security protocol."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tale','n.故事；传说；叙述；流言蜚语','/ˈteɪl/','/ˈteɪl/','noun',["Don''t tell tales!","the Canterbury Tales"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('society','n.社会；交往；社团；社交界','/səˈsaɪ.ə.ti/','/səˈsaɪ.ə.ti/','noun',["This society has been known for centuries for its colorful clothing and tight-knit family structure.","It was then that they decided to found a society of didgeridoo-playing unicyclists.","The gap between Western and Eastern societies seems to be narrowing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restrict','v.限制；约束；限定','/ɹɪˈstɹɪkt/','/ɹɪˈstɹɪkt/','verb',["After suffering diahrroea, the patient was restricted to a diet of rice, cold meat, and yoghurt."]);
