INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('son','n.儿子；孩子（对年轻人的称呼）；男性后裔','/sɒn/','/sɒn/','noun',["Before the birth of the man''s child, he said: \"I want a son, not a daughter.\"","He was a son of the mafia system.","The pharaohs were believed to be sons of the Sun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attitude','n.态度；看法；意见；姿势','/ˈætɪˌtjuːd/','/ˈætɪtud/','noun',["The ballet dancer walked with a graceful attitude.","Don''t give me your negative attitude.","The airliner had to land with a nose-up attitude after the incident."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('AD','n.公元；广告（ad）','/æd/','/æd/','noun',["I have placed both of the ads in the newspaper as instructed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('altitude','n.高地；高度；[数]顶垂线；（等级和地位等的）高级；海拔','/ˈælt.ɪˌtjuːd/','/ˈælt.ɪˌtjuːd/','noun',["As the altitude increases, the temperature gets lower, so remember to bring warm clothes to the mountains.","The perpendicular height of a triangle is known as its altitude."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everything','pron.每件事物；最重要的东西；（有关的）一切；万事','/ˈɛvɹiθɪŋ/','/ˈɛvɹiθɪŋ/','pronoun',["I checked the list again and everything is done.","A:What do you want to do at the amusement park?\nB:Everything!","She wasn''t feeling well this morning but now everything is fine."]);
