INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trunk','n.树干；躯干；象鼻；汽车车尾的行李箱vt.把…放入旅行箱内adj.干线的；躯干的；箱子的','/tɹʌŋk/','/tɹʌŋk/','noun',["the trunk of a vein or of an artery, as distinct from the branches"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('other','adj.其他的，另外的pron.另外一个','/ʊðə/','/ˈʌðɚ/','noun',["I''m afraid little Robbie does not always play well with others.","One boat is not better than the other.","I get paid every other week."]);
