INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debate','v.辩论，争论，讨论n.辩论；辩论会','/dɪˈbeɪt/','','noun',["After a four-hour debate, the committee voted to table the motion.","The debate over the age of the universe is thousands of years old.","There has been considerable debate concerning exactly how to format these articles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sell','v.销售；推销；出卖；欺骗n.销售；失望；推销术','/sɛl/','/sɛl/','noun',["This is going to be a tough sell.","I''ll sell you all three for a hundred dollars.","The corn sold for a good price."]);
