INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peach','n.桃子；桃树；桃红色；受人喜欢的人（或物）adj.桃色的；用桃子制成的v.告密','/piːt͡ʃ/','/piːt͡ʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('third','num.第三；三分之一adj.第三的；三分之一的','/θɜːd/','/tɜjd/','noun',["Jones came in third.","He ate a third of the pie. Divided by two-thirds.","Now put it into third."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tube','n.管；电子管；隧道；电视机v.使成管状；把…装管；用管输送','/tjuːb/','/tjuːb/','noun',["A tube of toothpaste.","I took the tube to Waterloo and walked the rest of the way.","Are you just going to sit around all day and watch the tube?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delighted','adj.高兴的；欣喜的v.使…兴高采烈；感到快乐（delight的过去分词）','/dɪˈlaɪtəd/','','verb',["A beautiful landscape delights the eye."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('why','int.哎呀！什么？adv.为什么','/waɪ/','/waɪ/','noun',["A good article will cover the who, the what, the when, the where, the why and the how.","That''s the reason why I did that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('control','n.控制；管理；抑制；操纵装置v.控制；管理；抑制','/kənˈtɹəʊl/','/kənˈt(ʃ)ɹoʊl/','noun',["The government has complete control over the situation.","With a simple remote, he could control the toy truck."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Saturday','n.星期六','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alley','n.小巷；小路；小径','/ˈæ.li/','/ˈæ.li/','noun',["The parking lot to my friend''s apartment building is in the alley.","He hit one deep into the alley."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('home','n.家，住宅；产地；家乡；避难所adv.在家，回家；深入地adj.国内的，家庭的；有效的v.归巢，回家','/(h)əʊm/','/hoʊm/','noun',["the home of the pine","The dog homed.","The missile was able to home in on the target."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smog','n.烟雾','/smɒɡ/','/smɒɡ/','noun',["If the car is more than five years old, you''ll have to have it smogged before you can register it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('survive','v.幸存；生还；幸免于；比活得长','/səˈvʌɪv/','/sɚˈvaɪv/','verb',["His children survived him; he was survived by his children.","He did not survive the accident."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stewardess','n.女管家；女干事；女服务员','/stjuː.əˈdɛs/','/stjuː.əˈdɛs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snow','n.雪，积雪；下雪v.降雪','/snəʊ/','/snoʊ/','noun',["We have had several heavy snows this year.","It is snowing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cool','adj.凉爽的；冷静的；出色的v.使…冷却；使…平静下来n.凉爽；凉爽的空气adv.冷静地','/kuːl/','/kuːl/','noun',["in the cool of the morning","Linen has made cool and breathable clothing for millennia.","If you have a reddish complexion, you should mainly wear cool colors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('useless','adj.无用的；无效的','/ˈjuːs.ləs/','/ˈjuːs.ləs/','adjective',["This fork has prongs that are bent. It''s useless now.","I think it''s useless to keep this discussion going. It''s like talking to a wall.","Bill never mows the lawn, takes out the trash or anything. He''s useless, but I love him anyways."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secure','adj.安全的；无虑的；有把握的；稳当的v.保护；弄到；招致；缚住','/səˈkjɔː(ɹ)/','/səˈkjɔɹ/','verb',["to secure a creditor against loss; to secure a debt by a mortgage","to secure a prisoner; to secure a door, or the hatches of a ship","to secure an estate"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pipe','n.管；烟斗；笛v.吹笛；尖叫','/paɪp/','/paɪp/','noun',["to pipe flowers on to a cupcake"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minibus','n.面包车（等于microbus）；小型公共汽车；中客车vi.乘中客车','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('me','pron.我（宾格）n.自我；极端自私的人；自我的一部分','/miː/','/mi/','pronoun',["Can you hear me?","Come with me.","He gave me this."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrival','n.到来；到达；到达者','/əˈɹaɪ.vəl/','/əˈɹaɪ.vəl/','noun',["The early arrival of the bride created a stir.","The arrival of the railway made the local tourist industry viable.","There has been a significant growth in illegal arrivals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conservative','adj.保守的n.保守派，守旧者','/kənˈsɜːvətɪv/','/kənˈsɜːvətɪv/','noun',["The curriculum committee at this university is extremely conservative.","At a conservative estimate, growth may even be negative next year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('however','adv.无论如何；不管怎样（接副词或形容词）；然而；可是conj.无论以何种方式;不管怎样','/hɑʊˈɛvə/','/haʊˈɛvɚ/','adverb',["He told me not to do it. I, however, did it anyway. / I did it anyway, however. / (sometimes proscribed:) However, I did it anyway.","However clear you think you''ve been, many questions will remain.","Let me know when you''ve had your interview, however it goes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mature','adj.成熟的；充分考虑的；到期的；成年人的v.成熟；到期','/məˈtjʊə/','/məˈtjʊə/','adjective',["She is quite mature for her age.","a mature plan","The headmaster decided to expel the boy after a mature consideration."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guide','n.指南；向导；入门书v.引导；带领；操纵','/ɡaɪd/','/ɡaɪd/','noun',["The guide led us around the museum and explained the exhibits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('traffic','n.交通；运输；贸易；[通信]通信量v.用…作交换；在…通行','/ˈtɹæfɪk/','/ˈtɹæfɪk/','noun',["The traffic is slow during rush hour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('block','n.块；街区；大厦；障碍物v.阻止；阻塞；限制；封盖adj.成批的，大块的；交通堵塞的','/blɒk/','/blɑk/','noun',["a block of ice","Anne Boleyn placed her head on the block and awaited her execution.","I''m going for a walk around the block."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('happy','adj.幸福的；高兴的；巧妙的n.(Happy)人名；(英、瑞典、喀)哈皮','/ˈhæpiː/','/ˈhæpi/','noun',["Music makes me feel happy.","Are you happy to pay me back by the end of the week?","a happy coincidence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elect','adj.选出的；当选的；卓越的n.被选的人；特殊阶层；上帝的选民v.选举；选择；推选','/iːˈlɛkt/','/iːˈlɛkt/','noun',["He is the President elect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('August','adj.威严的；令人敬畏的n.八月（简写为Aug）','/ɔːˈɡʌst/','/ɔːˈɡʌst/','adjective',["an august patron of the arts","an august lineage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('past','n.过去；往事adj.过去的；结束的prep.越过；晚于adv.过；经过','/pɑːst/','/pæst/','verb',["a book about a time machine that can transport people back into the past","past glories","during the past year"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saying','n.话；谚语；言论v.说（say的ing形式）','/ˈseɪɪŋ/','/ˈseɪɪŋ/','verb',["Please say your name slowly and clearly.","Martha, will you say the Pledge of Allegiance?","He said he would be here tomorrow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hello','int.喂；哈罗n.表示问候，惊奇或唤起注意时的用语','/həˈləʊ/','/həˈləʊ/','noun',["Hello, everyone.","Hello? How may I help you?","Hello? Is anyone there?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repeat','v.重复；复制；背诵n.重复；副本','','','noun',["We gave up after the third repeat because it got boring.","The scientists repeated the experiment in order to confirm the result.","Add 100, left 50. Repeat, over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('separately','adv.分别地；分离地；个别地','/ˈsɛpəɹətli/','/ˈsɛpəɹətli/','adverb',["We''ve been living separately for three years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cave','v.使凹陷，使塌落；在…挖洞穴n.洞穴，窑洞','/keɪv/','/keɪv/','noun',["We found a cave on the mountainside where we could take shelter.","This wine has been aged in our cave for thirty years.","My room was a cozy cave where I could escape from my family."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urge','v.力劝，催促；驱策，推进n.强烈的欲望，迫切要求；推动力','/ɜːd͡ʒ/','/ɝd͡ʒ/','noun',["to urge an argument; to urge the necessity of a case","to urge an ore with intense heat"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whistle','n.口哨；汽笛；呼啸声v.吹口哨；鸣汽笛','/wɪsl̩/','/wɪsl̩/','noun',["the whistle of the wind in the trees","Never whistle at a funeral.","The stream train whistled as it passed by."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruction','n.指令，命令；指示；教导；用法说明','/ɪnˈstɹʌkʃən/','/ɪnˈstɹʌkʃən/','noun',["Instruction will be provided on how to handle difficult customers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postcard','n.明信片','/ˈpoʊstˌkɑɹd/','/ˈpoʊstˌkɑɹd/','noun',["to postcard one''s friends","to postcard one''s news"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civil','adj.公民的；民间的；文职的；有礼貌的；根据民法的n.(Civil)人名；(土)吉维尔；(法)西维尔','/ˈsɪv.əl/','/ˈsɪv.əl/','adjective',["She went into civil service because she wanted to help the people.","It was very civil of him to stop the argument.","a civil case"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knowledge','n.知识，学问；知道，认识；学科','/ˈnɒlɪdʒ/','/ˈnɑlɪdʒ/','noun',["His knowledge of Iceland was limited to what he''d seen on the Travel Channel.","Knowledge consists in recognizing the difference between good and bad decisions.","A secretary should have a good knowledge of shorthand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fantasy','n.幻想；白日梦；幻觉adj.虚幻的v.空想；想像','/ˈfæntəsi/','/ˈfæntəsi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airline','n.航空公司；航线adj.航线的','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('till','n.[地理][水文]冰碛；放钱的抽屉；备用现金prep.直到conj.直到为止v.耕种；犁','/tɪl/','/tɪl/','preposition',["I have to work till eight o''clock tonight.","They led him till his tent","Maybe you can, maybe you can''t: you won''t know till you try."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sixteen','adj.十六的，十六个的num.十六','/ˈsɪks.tiːn/','','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('born','v.出世（bear的过去分词）adj.天生的n.(Born)人名；(柬)邦；(英、西、俄、捷、德、瑞典、匈)博恩','/ˈbɔːn/','/ˈbɔɹn/','verb',["Judging from the look on his face, he wasn''t bearing good news.","By my readings, we''re bearing due south, so we should turn about ten degrees east."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('actual','adj.真实的，实际的；现行的，目前的','/ˈak(t)ʃj(ʊ)əl/','/ˈæk(t)ʃ(əw)əl/','noun',["The actual government expenses dramatically exceed the budget."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wage','v.进行；发动；从事n.工资；代价；报偿','/weɪd͡ʒ/','/weɪd͡ʒ/','noun',["Before her promotion, her wages were 20% less."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aeroplane','n.飞机（等于airplane）','/ˈeə.ɹə.pleɪn/','/ˈeə.ɹə.pleɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('word','n.[语]单词；话语；消息；诺言；命令v.用言辞表达','/wɜːd/','/wɝd/','noun',["mum''s the word","Have you had any word from John yet?","Don''t fire till I give the word"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('significance','n.意义；重要性；意思','/sɪɡˈnɪfɪkəns/','/sɪɡˈnɪfɪkəns/','noun',["As a juror your opinion is of great significance for the outcome of the trial.","the significance of a gesture"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quantity','n.量，数量；大量；总量','/ˈkwɒn.tɪ.ti/','/ˈkwɑn(t)ɨti/','noun',["You have to choose between quantity and quality.","Olive oil can be used practically in any quantity.","Generally it should not be used in a quantity larger than 15 percent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shock','n.休克；震惊；震动；打击；禾束堆v.使休克；使震惊；使震动；使受电击；把…堆成禾束堆adj.浓密的；蓬乱的','/ʃɒk/','/ʃɑk/','noun',["The train hit the buffers with a great shock.","The disaster shocked the world."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recognise','v.认出；承认，认可；识别','/ˈɹɛkənaɪz/','/ˈɹɛkənaɪz/','verb',["I recognised his face immediately.","The US and a number of EU countries are expected to recognize Kosovo on Monday.","I recognize that my behaviour has been unacceptable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twice','adv.两次；两倍','/twaɪs/','/twaɪs/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('special','n.特使，特派人员；特刊；特色菜；专车；特价商品adj.特别的；专门的，专用的','/ˈspɛ.ʃəl/','/ˈspɛ.ʃəl/','noun',["We''re running a special on turkey for Thanksgiving.","Today''s special is our tuna melt on rye.","Did you see the Christmas special?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('major','adj.主要的；重要的；主修的；较多的n.[人类]成年人；主修科目；陆军少校v.主修','/ˈmeɪ.dʒə(ɹ)/','/ˈmeɪ.dʒɚ/','noun',["He used to be a major in the army."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minimum','n.最小值；最低限度；最小化；最小量adj.最小的；最低的','/ˈmɪn.ɪ.məm/','/ˈmɪn.ə.məm/','noun',["We need a minimum of three staff members on duty at all time.","He always tries to get away with doing the minimum.","The Maunder minimum of the Sun reportedly corresponded to a period of great cold on Earth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earthquake','n.地震；大动荡','/ˈɜːθkweɪk/','/ˈɝθkweɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('troublesome','adj.麻烦的；讨厌的；使人苦恼的','/ˈtɹʌbl̩səm/','/ˈtɹʌbl̩səm/','adjective',["The computer has been very troublesome for me. It never works when I need to use it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skillful','adj.熟练的；巧妙的','/ˈskɪl.fəl/','/ˈskɪl.fəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('away','adv.离去，离开；在远处','/əˈweɪ/','/əˈweɪ/','verb',["At 9 o''clock sharp he awayed to bed.","The master is away from home.","He''s miles away by now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anger','n.怒，愤怒；忿怒v.使发怒，激怒；恼火','/ˈæŋɡə(ɹ)/','/ˈæŋɡɚ/','noun',["You need to control your anger.","He who angers you conquers you.","You anger too easily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spade','n.铁锹，铲子v.铲；把……弄实抹平','/speɪd/','/speɪd/','noun',["I''ve got only one spade in my hand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('section','n.截面；部分；部门；地区；章节v.被切割成片；被分成部分','/ˈsɛkʃən/','/ˈsɛkʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('railway','n.（英）铁路；轨道；铁道部门vi.乘火车旅行','/ˈɹeɪlˌweɪ/','/ˈɹeɪlˌweɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comment','n.评论；意见；批评v.发表评论；发表意见','/ˈkɒmɛnt/','/ˈkɑmɛnt/','noun',["I have no comment on that.","I wish I''d commented this complicated algorithm back when I remembered how it worked."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salute','n.致敬，欢迎；敬礼v.行礼致敬，欢迎','/səˈl(j)uːt/','/səˈlut/','noun',["The soldiers greeted the dignitaries with a crisp salute.","They saluted the flag as it passed in the parade.","I would like to salute the many dedicated volunteers that make this project possible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('part','n.部分；角色；零件；一些；片段v.分离；分配；分开adv.部分地adj.部分的','/pɐːt/','/pɑɹt/','noun',["to do one’s part","The part of his hair was slightly to the left.","to part the curtains"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hate','v.憎恨；厌恶；遗憾n.憎恨；反感','/heɪt/','/heɪt/','noun',["One of my pet hates is traffic wardens.","He gave me a look filled with pure hate.","Do not fear; he who fears hates; he who hates kills. — attributed to Gandhi"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirsty','adj.口渴的，口干的；渴望的，热望的','/ˈθɜː(ɹ)st.i/','/ˈθɜː(ɹ)st.i/','adjective',["After all that work I am really thirsty.","After the president left office, the nation was thirsty for change.","This is the third time that girl brought up her crush. She must really be thirsty for her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enterprise','n.企业；事业；进取心；事业心','/ˈɛntɚˌpɹaɪz/','/ˈɛntɚˌpɹaɪz/','noun',["A micro-enterprise is defined as a business having 5 or fewer employees and a low seed capital.","Biosphere 2 was a scientific enterprise aimed at the exploration of the complex web of interactions within life systems.","He has shown great enterprise throughout his early career."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freeze','v.冻结；冷冻；僵硬n.冻结；凝固','/ˈfɹiːz/','/ˈfɹiːz/','verb',["The lake froze solid.","Don''t freeze meat twice.","It didn''t freeze this winter, but last winter was very harsh."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candle','n.蜡烛；烛光；烛形物v.对着光检查','/ˈkændl̩/','/ˈkændl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('campaign','v.作战；参加竞选；参加活动n.运动；活动；战役','/kæmˈpeɪn/','/kæmˈpeɪn/','noun',["The company is targeting children in their latest advertising campaign.","She campaigned for better social security."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vast','adj.广阔的；巨大的；大量的；巨额的n.浩瀚；广阔无垠的空间','/vɑːst/','/væst/','noun',["The Sahara desert is vast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maple','n.枫树；淡棕色','/ˈmeɪpl̩/','/ˈmeɪpl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('benefit','n.利益，好处；救济金v.有益于，对…有益','/ˈbɛn.ɪ.fɪt/','/ˈbɛn.ə.fɪt/','noun',["It was for her benefit.   His benefit was free beer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neither','conj.也不；既不adv.两个都不；既不……也不adj.两者都不的pron.两者都不','/ˈnaɪð.ə(ɹ)/','/ˈnaɪðɚ/','adverb',["Just as you would not correct it, neither would I.","I''ve tried on both shirts, but neither fits properly.","Neither now, nor ever will he forsake his mother."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sword','n.刀，剑；武力，战争','/sɔːd/','/sɔɹd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desire','n.欲望；要求，心愿；性欲v.想要；要求；希望得到…','/dɪˈzaɪə/','/diˈzaɪɚ/','noun',["It is my desire to speak with you.","His desire for her kept him awake at night.","Too much desire can seriously affect one’s judgment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relief','n.救济；减轻，解除；安慰；浮雕','/ɹɪˈliːf/','/ɹɪˈliːf/','noun',["I sighed with relief when I found out that my daughter hadn''t got lost, but was waiting for me at home.","Officer Schmidt can finally go home because his relief has arrived."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catch','v.赶上；抓住；感染；了解n.捕捉；捕获物；窗钩','/kæt͡ʃ/','/kæt͡ʃ/','noun',["The catch of the perpetrator was the product of a year of police work.","Nice catch!","Good catch. I never would have remembered that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consult','v.查阅；商量；向…请教','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preserve','v.保存；保护；维持；腌；禁猎n.保护区；禁猎地；加工成的食品','/pɹəˈzɜːv/','/pɹəˈzɝv/','noun',["Every people have the right to preserve its identity and culture.","to preserve peaches or grapes","to preserve appearances; to preserve silence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('next','adv.然后；下次；其次adj.下一个的；其次的；贴近的n.下一个prep.靠近；居于…之后','/nɛkst/','/nɛkst/','noun',["Next, please, don''t hold up the queue!","the next chapter; the next man I see; the next week; the Sunday next before Easter","The man was driven by his love for money and his desire to become the next Bill Gates."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('numb','v.使麻木；使发愣；使失去感觉adj.麻木的；发愣的','/nʌm/','/nʌm/','verb',["The dentist gave me novocaine to numb my tooth before drilling, thank goodness.","He turned to alcohol to numb his pain.","fingers numb with cold"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('one','pron.一个人；任何人adj.一的；唯一的n.一num.一；一个','/wan/','/wʌn/','noun',["I knew as soon I met him that John was the one for me and we were married within a month.","2003 September 26, \"DEAL WITH IT!!!!11one!!\", in alt.games.video.nintendo.gamecube, Usenet","One day the prince set forth to kill the dragon that had brought terror to his father’s kingdom for centuries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shoe','n.鞋；蹄铁；外胎v.给……穿上鞋；穿……鞋','/ʃuː/','/ʃuː/','noun',["Get your shoes on now, or you''ll be late for school.","Throw the shoe from behind the line, and try to get it to land circling (a ringer) or touching the far stake.","Remember to turn the rotors when replacing the brake shoes, or they will wear out unevenly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('so','adv.如此，这么；确是如此conj.所以；因此pron.这样n.(So)人名；(柬)索','/səʊ/','/soʊ/','adjective',["That is so.  You are responsible for this, is that not so?","Is he so?","It was so hot outside that all the plants died.  He was so good, they hired him on the spot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('husband','v.节约地使用（或管理）n.丈夫','/ˈhʌz.bənd/','/ˈhʌz.bənd/','noun',["You should start dating so you can find a suitable husband.","While reading her book, Sally leaned back against her husband, wishing it were the human kind.","For my means, I''ll husband them so well, / They shall go far. — Shakespeare."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occur','v.发生；出现；存在','/əˈkɜː/','/əˈkɝ/','verb',["The liftoff will occur in exactly twelve seconds.","I will write if the opportunity occurs.","The chemical monofluoroacetate occurs in all parts of Dichapetalum cymosum, and is responsible for its toxic effects."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prescription','n.药方；指示；惯例adj.凭处方方可购买的','/pɝˈskɹɪpʃən/','/pɝˈskɹɪpʃən/','noun',["\"Jurisdiction to prescribe\" is a state''s authority to make its laws applicable to certain persons or activities. -- Richard G. Alexander, Iran and Libya Sanctions Act of 1996: Congress exceeds its jurisdiction to prescribe law. Washington and Lee Law Review, 1997.","The surgeon wrote a prescription for a pain killer and physical therapy.","The pharmacist gave her a bottle containing her prescription."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoonful','n.一匙；一匙的量','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mankind','n.人类；男性','/mænˈkaɪnd/','/mænˈkaɪnd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slip','v.滑动；滑倒；犯错；失足；减退n.滑，滑倒；片，纸片；错误；下跌；事故adj.滑动的；有活结的；活络的abbr.串行线路接口协议，是旧式的协议（SerialLineInterfaceProtocol）','/slɪp/','/slɪp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eastern','adj.东方的；朝东的；东洋的n.东方人；（美国）东部地区的人','/ˈiːstən/','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thought','n.思想；思考；想法；关心v.想，思考；认为（think的过去式和过去分词）','/θɔːt/','/θɔt/','verb',["Idly, the detective thought what his next move should be.","I thought for three hours about the problem and still couldn’t find the solution.","I tend to think of her as rather ugly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cattle','n.牛；牲畜（骂人的话）；家畜；无价值的人','/ˈkæt(ə)l/','/ˈkæt(ə)l/','noun',["Do you want to raise cattle?","goods and cattle"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dumpling','n.饺子，汤团；面团布丁','/ˈdʌmplɪŋ/','/ˈdʌmplɪŋ/','noun',["My little dumpling."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accountant','n.会计师；会计人员','/ə.ˈkæʊn.(t)ən̩(t)/','/ə.ˈkæʊn.(t)ən̩(t)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('path','n.道路；小路；轨道','[pʰɑːθ]','[pʰeəθ]','noun',["the path of a meteor, of a caravan, or of a storm"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('veal','n.小牛（等于vealer）；小牛肉','/viːl/','/viːl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('initial','adj.最初的；字首的v.用姓名的首字母签名n.词首大写字母','/ɪˈnɪʃəl/','/ɪˈnɪʃəl/','noun',["You can get your initials printed at the top.","Please initial each page and sign the contract in full at the bottom.","Our initial admiration for their efficiency gave way to disgust about their methods."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medium','adj.中间的，中等的；半生熟的n.方法；媒体；媒介；中间物','/ˈmiːdɪəm/','/ˈmiːdɪəm/','noun',["Acrylics, oils, charcoal, and gouache are all mediums I used in my painting.","a happy medium"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beat','v.打；打败n.拍子；敲击；有规律的一连串敲打adj.筋疲力尽的；疲惫不堪的','/biːt/','/biːt/','noun',["a beat of the heart; the beat of the pulse","the beat of him","a dead beat"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('background','n.背景；隐蔽的位置v.作…的背景adj.背景的；发布背景材料的','/ˈbæk.ɡɹaʊnd/','/ˈbæk.ɡɹaʊnd/','noun',["The lawyer had a background in computer science.","The photographer let us pick a background for the portrait.","The antivirus program is running in the background."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('caution','n.小心，谨慎；警告，警示v.警告','/ˈkɔːʃ(ə)n/','/ˈkɑːʃ(ə)n/','noun',["The guideline expressed caution against excessive radiographic imaging.","Oh, that boy, he''s a caution! He does make me laugh."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beef','n.牛肉；肌肉；食用牛；牢骚v.抱怨，告发；发牢骚','/biːf/','/biːf/','noun',["I love eating beef.","He''s got a beef with everyone in the room.","Ugh, who just beefed in here?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Belgium','n.比利时（西欧国家，首都布鲁塞尔Brussels）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stare','v.凝视，盯着看；显眼n.凝视；注视','/stɛə(ɹ)/','/stɛə(ɹ)/','noun',["the stares of astonished passers-by","to stare a timid person into submission","staring windows or colours"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mistake','n.错误；误会；过失v.弄错；误解','/mɪˈsteɪk/','/mɪˈsteɪk/','noun',["Don''t mistake my kindness for weakness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freedom','n.自由，自主；直率','/ˈfɹiːdəm/','/ˈfɹidəm/','noun',["Having recently been released from prison, he didn''t know what to do with his newfound freedom.","Every child has a right to freedom from fear and freedom from want."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fountain','n.喷泉，泉水；源泉','[ˈfaʊn.ʔn̩]','[ˈfaʊn.ʔn̩]','noun',["Lava fountained from the volcano."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bakery','n.面包店','/ˈbeɪ.kə.ɹi/','/ˈbeɪ.kə.ɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juice','n.（水果）汁，液；果汁','/d͡ʒuːs/','/d͡ʒus/','noun',["Squeeze the orange and some juice will come out.","I’d like two orange juices please."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('similar','adj.相似的n.类似物','/ˈsɪmələ/','/ˈsɪməlɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pond','vt.筑成池塘vi.筑成池塘n.池塘','/pɒnd/','/pɑnd/','noun',["I haven''t been back home across the pond in twenty years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swim','v.游泳；漂浮；浸；眩晕n.游泳；漂浮；眩晕adj.游泳时穿戴的','/swɪm/','/swɪm/','noun',["I''m going for a swim.","a bare few bits of meat swimming in watery sauce","For exercise, we like to swim laps around the pool."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tonight','adv.在今晚n.今晚','/təˈnaɪt/','/təˈnaɪt/','noun',["I have high hopes for tonight.","I had a wonderful time with you tonight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apart','adv.相距；与众不同地；分离着adj.分离的；与众不同的','/əˈpɑː(ɹ)t/','/əˈpɑɹt/','adjective',["a world apart","Consider the two propositions apart.","We took the computer apart and put it back together."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fly','v.飞；驾驶飞机；飘扬n.飞行；苍蝇；两翼昆虫adj.敏捷的','/flaɪ/','/flaɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undertake','v.承担，保证；从事；同意；试图','/ʌndəˈteɪk/','','verb',["He undertook to exercise more in future.","I hate people who try and undertake on the motorway."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punctuate','v.不时打断；强调；加标点于','/ˈpʌŋktjuːeɪt/','/ˈpʌŋktjuːeɪt/','verb',["That occurrence of \"its\" needs to be punctuated.","My father punctuated his tirade with thumps on the desk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brick','n.砖，砖块；砖形物；心肠好的人v.用砖砌adj.用砖做的；似砖的','/bɹɪk/','/bɹɪk/','noun',["This wall is made of bricks.","This house is made of brick.","a plastic explosive brick"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dictionary','n.字典；词典','/ˈdɪkʃ(ə)n(ə)ɹi/','/ˈdɪkʃəˌnɛɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carrier','n.[化学]载体；运送者；带菌者；货架','/ˈkæ.ɹɪ.ə/','/ˈkæ.ɹɪ.ə/','noun',["aircraft carrier","inert carrier gas, which transports a chemical reactant"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quake','v.震动；颤抖n.地震；颤抖','/kweɪk/','/kweɪk/','noun',["We felt a quake in the apartment every time the train went by.","California is plagued by quakes; there are a few minor ones almost every month.","I felt the ground quaking beneath my feet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medal','n.勋章，奖章；纪念章','[ˈmɛd.ɫ̩]','[ˈmeɾ.ɫ̩]','noun',["He medalled twice at the Olympics."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theatre','n.电影院，戏院；戏剧；阶梯式讲堂','','','noun',["His grandfather was in the Pacific theater during the war.","This man is about to die, get him into theater at once!","We sat in the back row of the theater and threw popcorn at the screen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shot','n.发射；炮弹；射手；镜头adj.用尽的；破旧的；杂色的，闪光的v.射击（shoot的过去式和过去分词）','/ʃɒt/','/ʃɑt/','verb',["The land shoots into a promontory.","The shot was wide off the mark.","They took the lead on a last-minute shot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roof','n.屋顶；最高处，顶部；最高限度v.给…盖屋顶，覆盖','/ɹuːf/','/ɹuːf/','noun',["The roof was blown off by the tornado.","Let''s go up to the roof.","The palate is the roof of the mouth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harmful','adj.有害的；能造成损害的','/ˈhɑːmfl̩/','/ˈhɑɹmfl̩/','adjective',["Wear a hat to protect your skin from harmful sunlight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socialist','n.社会主义者；社会党党员adj.社会主义的','/ˈsəʊʃəlɪst/','/ˈsoʊ.ʃə.lɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ring','v.按铃；敲钟；回响；成环形n.戒指；铃声，钟声；拳击场；环形物','/ɹɪŋ/','/ɹɪŋ/','noun',["onion rings","a crime ring; a prostitution ring; a bidding ring (at an auction sale)","a benzene ring"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supermarket','n.超级市场；自助售货商店','/ˌsuːpəˈmɑːkɪt/','/ˌsuːpəˈmɑːkɪt/','noun',["I went to the supermarket to buy some food."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pattern','n.模式；图案；样品v.模仿；以图案装饰','/ˈpat(ə)n/','/ˈpat(ə)n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kite','n.风筝v.使用空头支票；像风筝一样飞；轻快地移动','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remark','n.注意；言辞v.评论；觉察','/ɹɪˈmɑːk/','/ɹɪˈmɑɹk/','noun',["a biting remark","He remarked that it was getting late."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greedy','adj.贪婪的；贪吃的；渴望的','/ˈɡɹiːdi/','/ˈɡɹiːdi/','adjective',["This regular expression performs a greedy match."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('savage','adj.野蛮的；残酷的；狂怒的；荒凉的n.未开化的人；粗鲁的人；残暴成性的人v.乱咬；粗暴的对待','/ˈsævɪdʒ/','/ˈsævɪdʒ/','noun',["No matter how anyone might savage me, I should stay strong.","His latest film was savaged by most reviewers.","a savage wilderness"]);
