INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('close','adj.紧密的；亲密的；亲近的v.关；结束；使靠近adv.紧密地n.结束','/kləʊz/','/kloʊz/','noun',["We owe them our thanks for bringing the project to a successful close."]);
