INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('not','adv.表示否定，不n.“非”（计算机中逻辑运算的一种）','/nɒt/','/nɑt/','noun',["Did you take out the trash? No, I did not.","It''s not you, it''s me.","It was not my favorite movie of all time."]);
