INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unknown','adj.未知的；陌生的，默默无闻的n.未知数；未知的事物，默默无闻的人','/ʌnˈnəʊn/','/ʌnˈnoʊn/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pump','v.打气；用抽水机抽…n.泵，抽水机；打气筒','/pʌmp/','/pʌmp/','noun',["This pump can deliver 100 gallons of water per minute.","It takes thirty pumps to get 10 litres; he did 50 pumps of the weights.","This pump is out of order, but you can gas up at the next one."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('publicly','adv.公然地；以公众名义','/ˈpʌblɪkli/','/ˈpʌblɪkli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fortunate','adj.幸运的；侥幸的；吉祥的；带来幸运的','/ˈfɔːt͡ʃənət/','/ˈfɔɹt͡ʃnɪt/','adjective',["It is a fortunate sign if the sun shines on a newly wedded couple.","Patrick was the unlikely match-winner as Berkeley earned a fortunate victory over Chisolm.","This is a time when we think of those less fortunate than ourselves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assist','n.帮助；助攻v.参加；出席','/əˈsɪst/','/əˈsɪst/','noun',["The foundation gave a much needed assist to the shelter.","He had two assists in the game.","This book will assist you in getting your life in order."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weak','adj.[经]疲软的；虚弱的；无力的；不牢固的','/wiːk/','/wiːk/','adjective',["The child was too weak to move the boulder.","a weak timber; a weak rope","weak resolutions; weak virtue"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accommodation','n.住处，膳宿；调节；和解；预订铺位','/ə.ˌkɒm.ə.ˈdeɪ.ʃən/','/ə.ˌkɒm.ə.ˈdeɪ.ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kettle','n.壶；[化工]釜；罐；鼓','/ˈkɛ.təl/','/ˈkɛ.təl/','noun',["There''s a hot kettle of soup on the stove.","Stick the kettle on and we''ll have a nice cup of tea.","a kettle of hawks"]);
