INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('president','n.总统；董事长；校长；主席','/ˈpɹɛzɨdənt/','/ˈpɹɛzɨdənt/','noun',["The vast majority of presidents have been male."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mark','n.标志；马克；符号；痕迹；分数v.作记号','/mɑɹk/','/mɑɹk/','noun',["to mark a box or bale of merchandise","See where this pencil has marked the paper.","She folded over the corner of the page to mark where she left off reading."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tournament','n.锦标赛，联赛；比赛','/ˈtɔːnəmənt/','/ˈtɔːnəmənt/','noun',[]);
