INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invite','v.邀请，招待；招致n.邀请','/ɪnˈvaɪt/','/ɪnˈvaɪt/','verb',["We invited our friends round for dinner.","I invite you all to be seated.","I always invite criticism of my definitions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merely','adv.仅仅，只不过；只是','/ˈmɪəli/','/ˈmɪɹli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punctuation','n.标点；标点符号','/pʌŋk.tʃuˈeɪ.ʃən/','/pʌŋk.tʃuˈeɪ.ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stay','v.停留；坚持；暂住；停下n.逗留；停止；支柱','/steɪ/','/steɪ/','noun',["I hope you enjoyed your stay in Hawaii.","The governor granted a stay of execution.","stand at a stay"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('examine','v.检查；调查；检测；考试','/ɪɡˈzæmɪn/','/ɪɡˈzæmɪn/','verb',["He examined the crime scene for clues.","The doctor examined the patient.","The witness was examined under oath."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('difference','n.差异；不同；争执','/ˈdɪfəɹən(t)s/','/ˈdɪfəɹən(t)s/','noun',["You need to learn to be more tolerant of difference.","There are three differences between these two pictures.","We have our little differences, but we are firm friends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('than','conj.比（用于形容词、副词的比较级之后）；除…外（用于other等之后）；与其…（用于rather等之后）；一…就（用于nosooner等之后）prep.比；超过n.(Than)人名；(老、柬、德)坦；(缅)丹','/ðæn/','/ðæn/','adverb',["A player than whom none is more skillful.","she''s taller than I am;  she found his advice more witty than helpful;  we have less work today than we had yesterday;  We had no choice than to return home"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poster','n.海报，广告；招贴','/ˈpoʊstɚ/','/ˈpoʊstɚ/','noun',["He has posters of his favorite band, sports teams and holiday resorts up.","I saw a poster for the film on the side of a bus.","Some posters left the online message board after the squabble."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rice','n.稻；米饭v.把…捣成米糊状','/ɹaɪs/','/ɹaɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hooray','vi.呼万岁vt.呼万岁n.万岁int.万岁','/həˈɹeɪ/','/həˈɹeɪ/','noun',["Lizzie has broken a world record, and she is now an Olympic medallist! – Hooray!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hay','n.干草v.把晒干','/heɪ/','/heɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('construction','n.建设；建筑物；解释；造句','/kənˈstɹʌkʃən/','/kənˈstɹʌkʃən/','noun',["Construction is underway on the new bridge.","The engineer marvelled at his construction.","He had worked in construction all his life."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('art','n.艺术；美术；艺术品adj.艺术的；艺术品的v.是（be的变体）','/ɑːt/','/ɑɹt/','noun',["There is a debate as to whether graffiti is art or vandalism.","She''s mastered the art of programming.","He''s at university to study art."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crossing','n.十字路口；杂交；横渡；横道v.横越（cross的现在分词）','/ˈkɹɑsɪŋ/','/ˈkɹɔsɪŋ/','verb',["They managed to cross a sheep with a goat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whisper','n.私语；谣传；飒飒的声音v.耳语；密谈；飒飒地响','/ˈ(h)wɪspə/','/ˈ(h)wɪspɚ/','noun',["There are whispers of rebellion all around.","The soup had just a whisper of basil."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consensus','n.一致；舆论；合意','','','noun',["After years of debate over the best wine to serve at Thanksgiving, no real consensus has emerged.","a financial consensus forecast"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secretary','n.秘书；书记；部长；大臣','/ˈsɛk.ɹə.tɹi/','/ˈsɛkɹəˌtɛɹi/','noun',["Ban Ki-Moon was a secretary general of the United Nations."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('midday','n.中午；正午adj.正午的','/mɪdˈdeɪ/','/mɪdˈdeɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('every','adj.每一的，每个的；每隔…的n.(Every)人名；(英)埃夫里','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('until','conj.在…以前；直到…时prep.在…以前；到…为止','/ənˈtɪl/','/ənˈtɪl/','preposition',["If you can wait until after my meeting with her, we''ll talk then.","Keep walking until the second set of traffic lights, then turn left."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gay','adj.快乐的；放荡的；艳丽的n.同性恋者','/ɡeɪ/','/ɡeɪ/','noun',["The Gay Science","Pennsylvania Dutch include the plain folk and the gay folk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virtue','n.美德；优点；贞操；功效','/-tjuː/','/ˈvɝtʃu/','noun',["Without virtue, there is no freedom."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glance','n.一瞥；一滑；闪光v.扫视，匆匆一看；反光；瞥闪，瞥见','/ɡlɑːns/','/ɡlæns/','noun',["copper glance","She glanced at her reflection as she passed the mirror.","The spring sunlight was glancing on the water of the pond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conflict','n.冲突，矛盾；斗争；争执v.冲突，抵触；争执；战斗','/kənˈflɪkt/','/kənˈflɪkt/','noun',["The conflict between the government and the rebels began three years ago.","I wanted to attend the meeting but there''s a conflict in my schedule that day.","It appears that our schedules conflict."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('telephone','n.（美）电话；电话机；电话耳机v.打电话','/ˈtɛləfəʊn/','/ˈtɛləfoʊn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bell','n.铃，钟；钟声，铃声；钟状物v.装钟于，系铃于','/bɛl/','/bɛl/','noun',["I’ll give you a bell later.","Who will bell the cat?","to bell a tube"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cold','adj.寒冷的；冷淡的，不热情的；失去知觉的n.寒冷；感冒adv.完全地','/kɔʊld/','/koʊld/','adjective',["A cold wind whistled through the trees.","The forecast is that it will be very cold today.","She was so cold she was shivering."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dance','n.舞蹈；舞会；舞曲v.跳舞；跳跃；飘扬adj.舞蹈的；用于跳舞的','[dɑːns]','/dæns/','noun',["So how much longer are we gonna do this dance?","I danced with her all night long.","His eyes danced with pleasure as he spoke.   She accused her political opponent of dancing around the issue instead of confronting it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bank','n.银行；岸；浅滩；储库v.将…存入银行；倾斜转弯','/bæŋk/','/bæŋk/','noun',["blood bank; sperm bank; data bank","If you want to buy a bicycle, you need to put the money in your piggy bank.","He banked with Barclays."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thread','n.线；螺纹；思路；衣服；线状物；玻璃纤维；路线v.穿过；穿线于；使交织','[θɾ̪̊ɛd]','[θɾ̪̊ɛd]','noun',["All of these essays have a common thread.","thread a needle","I think I can thread my way through here, but it’s going to be tight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skilled','adj.熟练的；有技能的；需要技能的','/skɪld/','/skɪld/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boxing','n.拳击；装箱；围模；做箱的材料v.将…装入盒中（box的ing形式）','/ˈbɒksɪŋ/','/ˈbɒksɪŋ/','verb',["Leave this place before I box you!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('air','n.空气，大气；天空；样子；曲调v.使通风，晾干；夸耀','/ˈɛə/','/ˈɛəɹ/','noun',["I''m going outside to get some air.","The flock of birds took to the air.","to give it an air of artistry and sophistication"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exist','v.存在；生存；生活；继续存在','/ɪɡˈzɪst/','/ɪɡˈzɪst/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tobacco','n.烟草，烟叶；烟草制品；抽烟','/təˈbækoʊ/','/təˈbækoʊ/','noun',["Tobaccos from the Connecticut Valley were used for wrapping cigars."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snatch','n.抢夺；抓举；小量v.夺得；抽空做；及时救助','/snætʃ/','/snætʃ/','noun',["The leftfielder makes a nice snatch to end the inning.","I heard a snatch of Mozart as I passed the open window.","He snatched up the phone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('three','n.三，三个num.三adj.三的，三个的','/θɹiː/','/θɹiː/','noun',["Put all the threes in a separate container.","All the threes will go in Mrs. Smith''s class, while I''ll take the fours and fives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('double','n.两倍；双精度型adj.双重的；两倍的v.加倍，加倍努力；快步走adv.双重地；两倍地；弓身地','/ˈdʌb.əl/','/ˈdʌb.əl/','noun',["Saddam Hussein was rumored to have many doubles.","On second thought, make that a double.","Before printing the photos, Liam deleted the doubles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invention','n.发明；发明物；虚构；发明才能','/ɪnˈvɛnʃən/','','noun',["I''m afraid there was no burglar. It was all the housekeeper''s invention.","The invention of the printing press was probably the most significant innovation of the medieval ages.","It took quite a bit of invention to come up with a plan, but we did it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('printing','n.印刷；印刷术','/ˈpɹɪntɪŋ/','/ˈpɹɪntɪŋ/','verb',["Print the draft double-spaced so we can mark changes between the lines.","The circuitry is printed onto the semiconductor surface.","I''m only in grade 2, so I only know how to print."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worthless','adj.无价值的；不值钱的；卑微的','/ˈwɜːθləs/','/ˈwɝθləs/','adjective',["Don''t be a worthless slouch! Go get yourself a job."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tortoise','n.龟，[脊椎]乌龟（等于testudo）；迟缓的人','/ˈtɔː.təs/','/ˈtɔːɹ.təs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('because','conj.因为','/bɪˈkɒz/','','adverb',["My life is ruined because of you!","I hid myself because I was afraid.","I don''t think he is a nice person, because he yells at people for no reason."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dirty','adj.下流的，卑鄙的；肮脏的；恶劣的；暗淡的v.弄脏','/ˈdɜːti/','/ˈdɝti/','verb',["Despite a walk in the rain, my shoes weren''t too dirty.","Don''t put that in your mouth, dear. It''s dirty.","At the reception, Uncle Nick got drunk and told dirty jokes to the bridesmaids."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supply','n.供给，补给；供应品v.供给，提供；补充','/səˈplaɪ/','/səˈplaɪ/','noun',["supply and demand","A supply of good drinking water is essential.","to vote supplies"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inform','v.通知；告诉；报告','/ɪnˈfɔːm/','/ɪnˈfɔɹm/','verb',["His sense of religion informs everything he writes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('responsibility','n.责任，职责；义务','/ɹɪˌspɑnsəˈbɪlɪɾi/','/ɹɪˌspɑnsəˈbɪlɪɾi/','noun',["Responsibility is a heavy burden.","Why didn''t you clean the house? That was your responsibility!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('class','n.阶级；班级；种类；班；等级v.分类；把…分等级；把…归入某等级，把…看作（或分类、归类）；把…编入某一班级adj.极好的；很好的，优秀的，出色的','/klas/','/kleəs/','noun',["Often used to imply membership of a large class.","Jane Austen''s works deal with class in 18th-century England.","Apologizing for losing your temper, even though you were badly provoked, showed real class."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frontier','n.前沿；边界；国境adj.边界的；开拓的','/fɹʌnˈtɪə/','/fɹʌnˈtɪɹ/','noun',["the frontier of civilization"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dine','v.进餐，用餐n.(Dine)人名；(意、葡)迪内；(英)戴恩；(法)迪纳','/daɪn/','/daɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('life','n.生活，生存；寿命','/laɪf/','/laɪf/','noun',["Having experienced both, the vampire decided that he preferred (un)death to life.  He gave up on life.","It''s life, but not as we know it.   She discovered plant life on the planet.   The rover discovered signs of life on the alien world.","Many lives were lost during the war.   Her quick thinking saved many dogs'' lives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('child','n.儿童，小孩，孩子；产物；子孙；幼稚的人；弟子','/t͡ʃaɪld/','/t͡ʃaɪld/','noun',["Go easy on him: he is but a child.","My youngest child is forty-three this year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('UN','abbr.联合国（UnitedNations）；硝酸铀铣（UranylNitrate）','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overweight','adj.超重的；过重的vt.使负担过重n.超重','','','noun',["Apple common stock is one of our overweights.","Our portfolio is very overweight (in) Asian technology stocks."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('important','adj.重要的，重大的；有地位的；有权力的','/ɪmˈpɔːtənt/','/ɪmˈpɔɹtənt/','adjective',["It is very important to give your daughter independence in her life so she learns from experience."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fist','n.拳，拳头；〈口〉笔迹；掌握；[印]指标参见号vt.紧握；握成拳；用拳打','/fɪst/','/fɪst/','noun',["The boxer''s fists rained down on his opponent in the last round.","...may not score a point with his open hand(s), but may score a point by fisting the ball. Damian Cullen. \"Running the rule.\" The Irish Times 18 Aug 2003, pg. 52."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('factory','n.工厂；制造厂；代理店','/ˈfæktəɹi/','/ˈfæktəɹi/','noun',["chicken factory; pig factory","See how there''s another layer of metal there? That''s not factory."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('division','n.[数]除法；部门；分配；分割；师（军队）；赛区','/dɪˈvɪʒən/','/dɪˈvɪʒən/','noun',["I''ve got ten divisions to do for my homework.","Magnolias belong to the division Magnoliophyta.","The House of Commons has voted to approve the third reading of the bill without a division. The bill will now progress to the House of Lords."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrist','n.手腕；腕关节vt.用腕力移动','/ɹɪst/','/ɹɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hundred','n.一百；许多adj.一百的；许多的num.百；百个','/ˈhʌndɚd/','/ˈhʌndɚd/','noun',["He made a hundred in the historic match.","a hundred, one hundred"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chat','v.聊天；闲谈n.聊天；闲谈','/tʃæt/','/tʃæt/','noun',["The Chat just made a joke about my skills.","I like to chat over a coffee with a friend.","I met my old friend in the street, so we chatted for a while."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bring','v.带来；促使；引起；使某人处于某种情况或境地n.(Bring)人名；(英、瑞典)布林','/ˈbɹɪŋ/','/ˈbɹɪŋ/','verb',["Waiter, please bring me a single malt whiskey.","The new company director brought a fresh perspective on sales and marketing.","The controversial TV broadcast brought a storm of complaints."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amaze','v.使吃惊','/əˈmeɪz/','','noun',["He was amazed when he found that the girl was a robot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('village','n.村庄；村民；（动物的）群落','/ˈvɪlɪd͡ʒ/','/ˈvɪlɪd͡ʒ/','noun',["There are 2 churches and 3 shops in our village."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('journalist','n.新闻工作者；报人；记日志者','/ˈdʒɜːnəlɪst/','/ˈdʒɜːnəlɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symbol','n.象征；符号；标志','/ˈsɪmbəl/','/ˈsɪmbəl/','noun',["$ is the symbol for dollars in the US and some other countries.","The lion is the symbol of courage; the lamb is the symbol of meekness or patience.","The Apostles, Nicene Creed and the confessional books of Protestantism, such as the Augsburg Confession of Lutheranism are considered symbols."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spirit','n.精神；心灵；情绪；志气；烈酒v.鼓励；鼓舞；诱拐','/ˈspɪɹɪt/','/ˈspiɹɪt/','noun',["A wandering spirit haunts the island.","School spirit is at an all-time high.","In the spirit of forgiveness, we didn''t press charges."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kick','v.踢；反冲，朝后座n.踢；反冲，后座力','/kɪk/','/kɪk/','noun',["A kick to the knee.","The ballerina did a high kick and a leap.","I finally saw the show. What a kick!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ice','n.冰；冰淇淋；矜持；（俚）钻石v.冰镇；结冰adj.冰的','[ʌɪs]','/aɪs/','noun',["Milton Keynes have yet to ice a team this season","If the Bruins ice the puck, the faceoff will be in their own zone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinguish','v.区分；辨别；使杰出，使表现突出','/dɪsˈtɪŋɡwɪʃ/','/dɪsˈtɪŋɡwɪʃ/','verb',["The soldier distinguished himself in combat and received a medal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gesture','n.姿态；手势v.作手势；用动作示意','/ˈdʒɛs.tʃɚ/','/ˈdʒɛs.tʃɚ/','noun',["The middle-finger gesture is really a nonverbal swear.","We took flowers as a gesture of sympathy.","My dad said to never gesture with my hands when I talk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Tokyo','n.东京（日本首都）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puzzled','adj.困惑的；茫然的；搞糊涂的','/ˈpʌ.zl̩d/','/ˈpʌ.zl̩d/','verb',["We puzzled over the curious-shaped lock, but were unable to discover how the key should be inserted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respond','v.回答；作出反应；承担责任n.应答；唱和','','','noun',["to respond to a question or an argument","The prisoner was held to respond the judgment of the court."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('latest','adv.最迟地；最后地n.最新的事物adj.最新的，最近的；最迟的，最后的','/ˈleɪt.ɪst/','/ˈleɪt.ɪst/','adjective',["It was late in the evening when we finally arrived.","It was getting late and I was tired.","Late Latin is less fully inflected than classical Latin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pride','n.自豪；骄傲；自尊心v.使得意，以…自豪','/pɹaɪd/','/pɹaɪd/','noun',["He had pride of ownership in his department.","to be in the pride of one''s life.","A pride of lions often consists of a dominant male, his harem and their offspring, but young adult males ''leave home'' to roam about as bachelors pride until able to seize/establish a family pride of their own."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('UK','abbr.联合王国（UnitedKingdom）n.英国','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wind','n.风；呼吸；气味；卷绕v.缠绕；上发条；使弯曲；吹号角；绕住或缠住某人','/ˈwaɪnd/','/ˈwaɪnd/','noun',["As they accelerated onto the motorway, the wind tore the plywood off the car''s roof-rack.","the wind of a cannon ball;  the wind of a bellows","After the second lap he was already out of wind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('split','v.分离；使分离；劈开；离开；分解n.劈开；裂缝adj.劈开的','/splɪt/','/splɪt/','noun',["He’s got a nasty split.","In the 3000 m race, his 800 m split was 1:45.32","He has split his lip."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('and','conj.和，与；就；而且；但是；然后n.(And)人名；(土、瑞典)安德','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handsome','adj.（男子）英俊的；可观的；大方的，慷慨的；健美而端庄的','/ˈhæn.səm/','/ˈhæn.səm/','verb',["a handsome garment, house, tree, or horse","Handsome is as handsome does.","a handsome salary"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('left','adj.左边的；左派的；剩下的adv.在左面n.左边；左派；激进分子v.离开（leave的过去式）','/lɛft/','/lɛft/','noun',["The political left is holding too much power.","The left side.","Turn left at the corner."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('storm','n.暴风雨；大动荡v.起风暴；横冲直撞；狂怒咆哮','/stɔːm/','/stɔɹm/','noun',["The proposed reforms have led to a political storm."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shirt','n.衬衫；汗衫，内衣','/ʃɜːt/','/ʃɝt/','noun',["It can take a while to learn how to iron a shirt properly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seventeen','n.十七，十七个adj.十七岁的；十七的，十七个的num.十七','/ˈsɛv.ən.tiːn/','','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unhealthy','adj.不健康的；危险的；有害身心健康的','/ʌnˈhɛl.θi/','/ʌnˈhɛl.θi/','adjective',["The villagers lived in unhealthy surroundings.","He was an unhealthy child.","He liked unhealthy reading material."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lap','n.一圈；膝盖；下摆；山坳v.使重叠；拍打；包围','/læp/','/læp/','noun',["The boy was sitting on his mother''s lap."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neighbourhood','n.邻近；周围；邻居关系；附近一带','','','noun',["Our neighborhood was our only reason to exchange hollow greetings.","He lives in my neighborhood.","The fire alarmed the neighborhood."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('used','adj.习惯的；二手的，使用过的v.用（use的过去式）；（usedto）过去常做','/juːzd/','/juːzd/','verb',["soldiers who are used to hardships and danger","I used to get things done.","to use an animal cruelly"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('windy','adj.多风的，有风的；腹胀的；吹牛的','/ˈwɪndi/','/ˈwɪndi/','noun',["It was a long and windy night.","They made love in a windy bus shelter.","They made windy promises they would not keep."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('murder','v.谋杀，凶杀n.谋杀，凶杀','/ˈmɜːdə(ɹ)/','/ˈmɝ.dɚ/','noun',["The defendant was charged with murder.","There have been ten unsolved murders this year alone.","This headache is murder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nation','n.国家；民族；国民','/ˈneɪ.ʃən/','/ˈneɪ.ʃən/','noun',["The Kurdish people constitute a nation in the Middle East","Though legally single nations, many states comprise several distinct cultural or ethnic groups.","Once widespread across Europe in medieval times, nations are now largely restricted to the ancient universities of Sweden and Finland."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cake','n.蛋糕；块状物；利益总额v.使结块','/keɪk/','/keɪk/','noun',["a johnnycake","buckwheat cakes","a cake of sand"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('often','adv.常常，时常','/ˈɑf(t)ən/','/ˈɔf(t)ən/','adjective',["I often walk to work when the weather is nice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accompany','v.陪伴，伴随；伴奏','/ə.ˈkʌm.pə.ni/','/ə.ˈkʌm.pə.ni/','verb',["Geoffrey accompanied the group on their pilgrimage.","I will accompany her on the oboe.","Thunder almost always accompanies lightning during a rain storm."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subscribe','v.订阅；捐款；认购；赞成；签署','/səbˈskɹaɪb/','/səbˈskɹaɪb/','verb',["Would you like to subscribe or subscribe a friend to our new magazine, Lexicography Illustrated?","I don’t subscribe to that theory.","Each man subscribed ten dollars."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relation','n.关系；叙述；故事；亲属关系','/ɹɪˈleɪʃən/','/ɹɪˈleɪʃən/','noun',["The relation between diet and health is complex.","Yes, he''s a relation of mine, but only a distant one.","Your relation of the events is different from mine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anywhere','adv.在任何地方；无论何处n.任何地方','/ˈɛn.iː.(h)wɛə(ɹ)/','/ˈɛn.i.(h)wɛɹ/','adverb',["I don''t know where I left my keys. They could be anywhere.","Anywhere you go in France, there will be bread and wine with dinner.","Anywhere is better than here!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dilemma','n.困境；进退两难；两刀论法','/daɪˈlɛmə/','/daɪˈlɛmə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beard','v.公然反对；抓…的胡须n.胡须；颌毛','/bɪəd/','/biɚd/','noun',["the beard of grain","Robin Hood is always shown as bearding the Sheriff of Nottingham."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('though','adv.可是，虽然；不过；然而conj.虽然；尽管prep.但','/ðəʊ/','/ðoʊ/','adverb',["I will do it, though.","\"Man, it''s hot in here.\" — \"Isn''t it, though?\"","Though it’s risky, it’s worth taking the chance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bow','n.弓；鞠躬；船首v.鞠躬；弯腰adj.弯曲的','/bəʊ/','/boʊ/','noun',["The musician bowed his violin expertly.","The shelf bowed under the weight of the books.","Cronenberg’s \"Cosmopolis\" bows in Cannes this week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('many','pron.许多；许多人adj.许多的n.(Many)人名；(法)马尼','/ˈmæni/','/ˈmɛni/','noun',["Democracy must balance the rights of the few against the will of the many.","Many are called, but few are chosen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('what','pron.什么；多么；多少adj.什么；多么；何等adv.到什么程度，在哪一方面int.什么；多么','/wɒt/','/wɒt/','adverb',["The market will calculate these higher risks in their funding costs what might result in higher lending rates.","What a beautiful day!","He knows what he wants."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shooting','n.射击；打猎；摄影；射门v.射击（shoot的ing形式）','/ˈʃuːtɪŋ/','/ˈʃuːtɪŋ/','verb',["The land shoots into a promontory.","Police are hunting the people who carried out the shootings last week.","I take part in shooting at the local archery club."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('government','n.政府；政体；管辖','/ˈɡʌvə(n)mənt/','/ˈɡʌvɚ(n)mənt/','noun',["If the citizens must follow the law, then the government must follow the constitution."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('right','adj.正确的；直接的；右方的v.复正；恢复平稳n.正确；右边；正义adv.正确地；恰当地；彻底地','/ˈɹaɪt/','/ˈɹaɪt/','adjective',["a right line","The kitchen counter formed a right angle with the back wall.","a right triangle, a right prism, a right cone"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cash','n.现款，现金v.将…兑现；支付现款','/kæʃ/','/kæʃ/','noun',["After you bounced those checks last time, they want to be paid in cash."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chest','n.胸，胸部；衣柜；箱子；金库','/t͡ʃɛst/','/t͡ʃɛst/','noun',["The clothes are kept in a chest.","You can take the money from the chest.","She had a sudden pain in her chest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advise','v.建议；劝告，忠告；通知；警告','/ədˈvaɪz/','/ədˈvaɪz/','verb',["The dentist advised me to brush three times a day.","The dentist advised brushing three times a day.","The lawyer advised me to drop the case, since there was no chance of winning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sad','adj.难过的；悲哀的，令人悲痛的；凄惨的，阴郁的（形容颜色）','/sæd/','/sæd/','verb',["I can''t believe you use drugs; you''re so sad!","sad bread"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('another','adj.又一，另一；另外的；不同的pron.另一个；又一个prep.另一个；另一个人','','','pronoun',["There is one sterling and here is another","I saw one movie, but I think I will see another.","His interests keep shifting from one thing to another."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pole','n.杆；极点；电极v.用竿支撑','/pɔːl/','/poʊl/','noun',["Huck Finn poled that raft southward down the Mississippi because going northward against the current was too much work.","He poled off the serial of the Gulfstream to confirm its identity.","to pole beans or hops"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('average','n.平均；平均数；海损adj.平均的；普通的；通常的v.算出…的平均数；将…平均分配；使…平衡','/ˈævəɹɪd͡ʒ/','/ˈævəɹɪd͡ʒ/','noun',["The average of 10, 20 and 24 is (10 + 20 + 24)/3 = 18.","batting average","If you average 10, 20 and 24, you get 18."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capital','n.首都，省会；资金；大写字母；资本家adj.首都的；重要的；大写的','/ˈkæp.ɪ.təl/','','noun',["He does not have enough capital to start a business.","The Welsh government claims that Cardiff is Europe’s youngest capital.","Interpreters need a good amount of cultural capital in order to function efficiently in the profession."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sit','v.坐；位于n.(Sit)人名；(东南亚国家华语)硕；(罗)西特','/sɪt/','/sɪt/','noun',["After a long day of walking, it was good just to sit and relax.","I asked him to sit.","The temple has sat atop that hill for centuries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stain','v.沾污；败坏；给…着色n.污点；瑕疵；着色剂','/steɪn/','/steɪn/','noun',["armour stained with blood","the stained glass used for church windows"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aluminium','adj.铝的n.铝','/ˌæl.(j)ʊˈmɪn.i.əm/','/ˌæl(j)uˈmɪn.j.əm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conventional','adj.符合习俗的，传统的；常见的；惯例的','/kənˈvɛnʃənl/','/kənˈvɛnʃənl/','noun',["They wear conventional clothes, eat conventional food, and keep conventional hours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prepare','v.准备；使适合；装备；起草','/pɹɪˈpɛə/','/pɹəˈpɛəɹ/','noun',["We prepared the spacecraft for takeoff.","We prepared a fish for dinner.","We prepared for a bumpy ride."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elegant','adj.高雅的，优雅的；讲究的；简炼的；简洁的','/ˈɛl.ə.ɡənt/','/ˈɛl.ə.ɡənt/','adjective',["an elegant solution"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('present','v.提出；介绍；呈现；赠送adj.现在的；出席的n.现在；礼物；瞄准','/pɹəˈzɛnt/','/ˈpɹɛzənt/','noun',["The barbaric practice continues to the present day.","Is there a doctor present?  Several people were present when the event took place.","a present wit"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bachelor','n.学士；单身汉；（尚未交配的）小雄兽','/ˈbætʃ.ə.lə(ɹ)/','/ˈbætʃ.lɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('religious','adj.宗教的；虔诚的；严谨的；修道的n.修道士；尼姑','/ɹɪ.ˈlɪ.d͡ʒəs/','','noun',["It is the job of this court to rule on legal matters. We do not consider religious issues.","I was much more religious as a teenager than I am now.","I''m a religious fan of college basketball."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mailbox','n.邮箱；邮筒','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dizzy','adj.晕眩的；使人头晕的；昏乱的；心不在焉的；愚蠢的v.使头晕眼花；使混乱；使茫然n.(Dizzy)人名；(英)迪齐','/ˈdɪzi/','/ˈdɪzi/','verb',["I stood up too fast and felt dizzy.","We climbed to a dizzy height.","My new secretary is a dizzy blonde."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chopsticks','n.筷子','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accustomed','adj.习惯的；通常的；独有的v.使习惯于（accustom的过去分词）','/ə.ˈkʌs.təmd/','/ə.ˈkʌs.təmd/','adjective',["accustomed to cold"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ancient','adj.古代的；古老的，过时的；年老的n.古代人；老人','/ˈeɪn.ʃənt/','/ˈeɪn.ʃənt/','noun',["an ancient city  an ancient forest","an ancient author  an ancient empire"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquire','v.获得；取得；学到；捕获','/əˈkwaɪə/','/əˈkwaɪəɹ/','verb',["He acquired a title."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regardless','adj.不管的；不顾的；不注意的adv.不顾后果地；不管怎样，无论如何；不惜费用地','/ɹɪˈɡɑːd.lɪs/','/ɹɪˈɡɑːd.lɪs/','adjective',["Tatiana knew the meat had passed its expiry date, but she ate it regardless."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('firefighter','n.消防队员','/ˈfaɪə(ɹ)ˌfaɪt.ə(ɹ)/','/ˈfaɪə(ɹ)ˌfaɪt.ə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pineapple','n.[园艺]菠萝；[园艺]凤梨adj.凤梨科的','/ˈpaɪnəpəl/','/ˈpaɪnəpəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impossible','adj.不可能的；不可能存在的；难以忍受的；不真实的n.不可能；不可能的事','/ɪmˈpɒs.ə.bəl/','/ɪmˈpɑ.səbl/','noun',["Late 14th century: “Madame,” quod he, “this were an impossible!” — Geoffrey Chaucer, ‘The Franklin''s Tale’, Canterbury Tales","It is difficult, if not impossible, to memorize 20,000 consecutive numbers.","You never listen to a word I say – you''re impossible!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classmate','n.同班同学','/ˈklɑːs.meɪt/','/ˈklɑːs.meɪt/','noun',["Danny and I have been classmates for five years, but I''ve never spoken to him outside of lessons."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pop','abbr.卖点广告（PointofPurchase）','/pɒp/','/pɑp/','noun',["Listen to the pop of a champagne cork.","Lunch was sandwiches and a bottle of pop.","Go in the store and buy us three pops."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contribute','v.贡献，出力；投稿；捐献','/kənˈt(ʃ)ɹɪb.juːt/','/kənˈt(ʃ)ɹɪb.jut/','verb',["to contribute articles to a journal"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('license','n.执照，许可证；特许v.许可；特许；发许可证给','/ˈlaɪsəns/','/ˈlaɪsəns/','noun',["In order to enter the building, I need to show my license.","It was decided to license Wikipedia under the GFDL.","I am licensed to practice law in this state."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peaceful','adj.和平的，爱好和平的；平静的','/ˈpiːsfəl/','/ˈpiːsfəl/','adjective',["peaceful protest"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('probable','adj.很可能的；可信的n.很可能的事；大有希望的候选者','/ˈpɹɒbəbl̩/','/ˈpɹɑbəbl̩/','noun',["It''s probable that it will rain tomorrow.","With all the support we have, success is looking probable.","probable evidence; probable presumption"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admire','v.钦佩；赞美','/ədˈmaɪə/','/ədˈmaɪɹ/','verb',["He had always admired the work ethos and family values of his friend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identity','n.身份；同一性，一致；特性；恒等式','/aɪˈdɛntəti/','/aɪˈdɛntəti/','noun',["I''ve been through so many changes, I have no sense of identity.","This criminal has taken on several identities.","2013 April 4, \"Cricket identities consult lawyers\", New Zealand Herald"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('observe','v.庆祝','/əbˈzɝv/','/əbˈzɝv/','verb',["From this vantage point we can observe the behavior of the animals in their natural habitat.","Please observe all posted speed limits.","The senator observed that the bill would be detrimental to his constituents."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profession','n.职业，专业；声明，宣布，表白','/pɹəˈfɛʃən/','/pɹəˈfɛʃən/','noun',["Despite his continued professions of innocence, the court eventually sentenced him to five years.","My father was a barrister by profession.","His conduct is against the established practices of the legal profession."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('with','prep.用；随着；支持；和…在一起n.(With)人名；(德、芬、丹、瑞典)维特','','','adverb',["Do you want to come with?","He picked a fight with the class bully.","He went with his friends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minister','n.部长；大臣；牧师v.执行牧师职务；辅助或伺候某人','/ˈmɪnɪstə/','/ˈmɪnɨstɚ/','noun',["The minister said a prayer on behalf of the entire congregation.","He was newly appointed to be Minister of the Interior."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enough','adv.足够地，充足地n.很多；充足adj.充足的int.够了！','/iˈnʌf/','/iˈnʌf/','adverb',["Are you man enough to fight me?","He is ready enough to accept the offer.","Enough of you are here to begin the class."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cup','n.杯子；奖杯；酒杯v.使成杯状；为…拔火罐','/kʌp/','/kʌp/','noun',["Pour the tea into the cup.","I drank two cups of water but still felt thirsty.","The World Cup is awarded to the winner of a quadrennial football tournament."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gy','abbr.灰色（gray）；圭亚那（Guyana）n.戈瑞','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('movement','n.运动；活动；运转；乐章','/ˈmuːv.mənt/','/ˈmuːv.mənt/','noun',["I saw a movement in that grass on the hill.","The labor movement has been struggling in America since the passage of the Taft-Hartley act in 1947.","Albuquerque International Sunport serviced over 200,000 movements last year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ending','n.结局；结尾','/ˈɛndɪŋ/','/ˈɛndɪŋ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centigrade','adj.摄氏的；[仪]摄氏温度的；百分度的','','','noun',["a temperature of 34 centigrades"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ceremony','n.典礼，仪式；礼节，礼仪；客套，虚礼','/ˈsɛɹɪməni/','/ˈsɛɹəmoʊni/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('point','n.要点；得分；标点；[机]尖端v.指向；弄尖；加标点于','/pɔɪnt/','/pɔɪnt/','noun',["point de Venise; Brussels point","The dog came to a point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sniff','v.嗅；嗤之以鼻n.吸，闻；嗤之以鼻；气味；以鼻吸气；吸气声','/snɪf/','/snɪf/','noun',["She gave the flowers a quick sniff to check they were real.","I sniffed the meat to see whether it had gone off.","\"He''s never coming back, is he?\" she sniffed while looking at a picture of him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annoy','v.骚扰；惹恼；打搅n.烦恼（等于annoyance）','/əˈnɔɪ/','/əˈnɔɪ/','noun',["Marc loved his sister, but when she annoyed him he wanted to switch her off.","to annoy an army by impeding its march, or by a cannonade"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('architecture','n.建筑学；建筑风格；建筑式样；架构','/ˈɑː.kɪ.ˌtɛk.tʃə/','/ˈɑɹkɪtɛktʃɚ/','noun',["Architecture is the visual public expression of a culture’s achievements, values, and outlook. ― Max Roscoe, \"How Your City Is Killing You With Ugliness\"","The Intel architectures have more software written for them.","The architecture of the company''s billing system is designed to support its business goals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('television','n.电视，电视机；电视业','/ˈtɛləˌvɪʒən/','/ˈtɛləˌvɪʒən/','noun',["It’s a good thing that television doesn’t transmit smell.","I have an old television in the study.","fifty-seven channels and nothing on television"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('editor','n.编者，编辑；社论撰写人；编辑装置','/ˈɛdɪtə/','/ˈɛdɪtəɹ/','noun',["John Johnson wrote this term paper and the editor was Joan Johnson.","John is the city editor at the Daily Times.","The TPU EVE editor is an excellent, extensible, programmable editor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('criminal','n.罪犯adj.刑事的；犯罪的；罪恶的','/ˈkɹɪmənəl/','/ˈkɹɪmənəl/','noun',["His long criminal record suggests that he is a dangerous man.","Printing such asinine opinions is criminal!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dialogue','n.对话；意见交换vi.对话vt.用对话表达','/ˈdaɪəlɑɡ/','/ˈdaɪəlɔɡ/','noun',["Bill and Melinda maintained a dialogue via email over the course of their long-distance relationship.","The movie had great special effects, but the dialogue was lackluster.","A literary historian, she specialized in the dialogues of ancient Greek philosophers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('per','prep.每；经；按照；每一n.(Per)人名；(德、挪、丹、瑞典)佩尔','/pɜː(ɹ)/','/pɝ/','preposition',["$2.50 per dozen","100 centimeters per meter","Introduce the endoscope per nasum."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('programme','n.计划，规划；节目；程序v.编程序；制作节目','/ˈpɹəʊɡɹæm/','/ˈpɹoʊˌɡɹæm/','noun',["Our program for today’s exercise class includes swimming and jogging.","The program consisted of ads for restaurants and the credits of everyone connected with the play.","Tonight’s program was hosted by Johnny Carson."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('menu','n.菜单','/ˈmɛnju/','/ˈmɛnju/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pancake','n.薄烤饼；粉饼；平降（全称pancakelanding）vi.平坠着陆；平展vt.使平坠著陆；使平展','/ˈpæn.keɪk/','/ˈpæn.keɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('her','pron.她（she的宾格）；她的（she的所有格）；她（指某个国家；一艘船）n.（法）埃尔（人名）','/ə(ɹ)/','/ɚ/','noun',["I think this bird is a him, but it may be a her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mist','n.薄雾；视线模糊不清；模糊不清之物v.下雾；变模糊','/mɪst/','/mɪst/','noun',["It was difficult to see through the morning mist.","There was an oily mist on the lens.","It''s misting this morning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pace','n.一步；步速；步伐；速度v.踱步；缓慢而行','/peɪs/','/peɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('story','n.故事；小说；新闻报道；来历；假话vt.用历史故事画装饰vi.说谎','/ˈstɔː.ɹi/','/ˈstɔː.ɹi/','noun',["The book tells the story of two roommates.","You’ve been telling stories again, haven’t you?","What will she do without being able to watch her stories?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regret','n.遗憾；抱歉；悲叹v.后悔；惋惜；哀悼','/ɹiˈɡɹɛt/','/ɹiˈɡɹɛt/','noun',["He regretted his words.","I regret that I have to do this, but I don''t have a choice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grocer','n.杂货店；食品商','/ˈɡɹəʊ.sə/','/ˈɡɹəʊ.sə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('celebration','n.庆典，庆祝会；庆祝；颂扬','/ˌsɛlɪˈbɹeiʃən/','/ˌsɛlɪˈbɹeiʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('build','v.建立；建筑n.构造；体形；体格','/bɪld/','/bɪld/','noun',["Rugby players are of sturdy build.","The computer company has introduced a new prototype build to beta testers.","I made a build that looked like the Parthenon in that game."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smoke','n.烟；抽烟；无常的事物v.冒烟，吸烟；抽烟；弥漫','/sməʊk/','/smoʊk/','noun',["Can I bum a smoke off you?;  I need to go buy some smokes.","Hey, you got some smoke?","I''m going out for a smoke."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confuse','v.使混乱；使困惑','/kənˈfjuːz/','/kənˈfjuːz/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cottage','n.小屋；村舍；（农舍式的）小别墅','/ˈkɒtɪdʒ/','/ˈkɑtədʒ/','noun',["Most cottages in the area were larger and more elaborate than my home."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manage','v.管理；经营；控制；设法','/ˈmænɪdʒ/','/ˈmænədʒ/','noun',["He managed to climb the tower.","It''s a tough job, but I''ll manage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lovely','adj.可爱的；令人愉快的；爱恋的；秀丽的，优美的n.美女；可爱的东西','/ˈlʌvli/','/ˈlʌvli/','noun',["a calendar depicting young lovelies in bikinis","Goodbye, my lovely.","It''s a lovely day and the sun is shining."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rude','adj.粗鲁的；无礼的；狂暴的；未开化的n.(Rude)人名；(英、西、瑞典)鲁德；(法)吕德','/ɹʉːd/','/ɹud/','adjective',["Karen broke up with Fred because he was often rude to her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nursing','n.护理；看护；养育v.看护；养育（nurse的ing形式）','/ˈnɜːsɪŋ/','/ˈnɜːsɪŋ/','verb',["She believes that nursing her baby will make him strong and healthy.","She nursed him back to health.","She nursed the rosebush and that season it bloomed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compensate','v.补偿，赔偿；抵消','/ˈkɒm.pən.seɪt/','/ˈkɑm.pənˌseɪt/','verb',["It is hard work, but they will compensate you well for it.","His loud voice cannot compensate for a lack of personality.","I don''t like driving that old car because it always steers a little to the left so I''m forever compensating for that when I drive it. Trust me, it gets annoying real fast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yourselves','pron.你们自己；你们本人（yourself的复数）','/jɔːˈsɛlvz/','/jɔːˈsɛlvz/','pronoun',["You shouldn''t blame yourselves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('always','adv.永远，一直；总是；常常','/ˈɔː(l).weɪz/','/ˈɔl.weɪz/','adverb',["Airplanes did not always exist as a form of transportation.","In this street, the shops always close during lunchtime.","I thought I could always go back to work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('origin','n.起源；原点；出身；开端','/ˈɒɹ.ə.dʒən/','/ˈɑɹ.ɪ.dʒɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinction','n.区别；差别；特性；荣誉、勋章','/dɪˈstɪŋkʃən/','/dɪˈstɪŋkʃən/','noun',["There is a distinction to be made between resting and slacking.","She had the distinction of meeting the Queen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('begin','v.开始n.(Begin)人名；(以、德)贝京；(英)贝让','/biˈɡɪn/','/biˈɡɪn/','noun',["I began playing the piano at the age of five.   Now that everyone is here, we should begin the presentation.","The program begins at 9 o''clock on the dot.    I rushed to get to class on time, but the lesson had already begun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garlic','n.大蒜；蒜头','/ˈɡɑːlɪk/','/ˈɡɑːlɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tailor','v.剪裁；使合适n.裁缝','/ˈteɪlə/','/ˈteɪlɚ/','noun',["He works as a tailor on Swanston Street.","We can tailor that jacket for you if you like.","The website was tailored to the client''s needs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('off','prep.离开；脱落adv.切断；走开adj.远离的；空闲的','/ɔːf/','/ɔf/','noun',["He has been very obviously an untrustworthy narrator right from the off.","He got in the way so I had him offed.","Can you off the light?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unit','n.单位，单元；装置；[军]部队；部件','/ˈjuː.nɪt/','/ˈjuː.nɪt/','noun',["The centimetre is a unit of length.","He was a member of a special police unit.","The fifth tank brigade moved in with 20 units. (i.e., 20 tanks)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allergic','adj.对…过敏的；对…极讨厌的','[ə.ˈlɜː.dʒɪk]','[ə.ˈlɜː.dʒɪk]','noun',["I am allergic to cats."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finger','n.手指；指针，指状物v.伸出；用手指拨弄','/ˈfɪŋəɹ/','/ˈfɪŋɡɚ/','noun',["Humans have two hands and ten fingers. Each hand has one thumb and four fingers.","a finger of land; a finger of smoke"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upstairs','adv.在楼上，向楼上；上楼；往楼上adj.楼上的n.楼上','/ˈʌpˌstɛəz/','/ˈʌpˌstɛɹz/','noun',["They can sleep in the upstairs bedroom.","That fastball was upstairs for a ball.","I hate the people who live upstairs, and I especially hate their piano."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('misunderstand','v.误解；误会','/mɪs.ʌn.də(ɹ)ˈstænd/','/mɪs.ʌn.də(ɹ)ˈstænd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cater','v.投合，迎合；满足需要；提供饮食及服务n.(Cater)人名；(英)凯特','/ˈkeɪtə/','/ˈkeɪdɚ/','noun',["The merchants are the purveyors of fine selections."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('riddle','v.解谜；给出谜；充满于n.谜语；粗筛；谜一般的人、东西、事情等','/ˈɹɪdəl/','/ˈɹɪdəl/','noun',["Here''s a riddle: It''s black, and white, and red all over. What is it?","Riddle me this."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('huge','adj.巨大的；庞大的；无限的n.(Huge)人名；(英)休奇','[hʊudʒ]','/hjuːd͡ʒ/','adjective',["The castle was huge.","Our next album is going to be huge!  In our league our coach is huge!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centimetre','n.厘米；公分','/ˈsɛn.tɪ.miː.tə/','/ˈsɛn.tɪ.miː.tə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('more','adv.更多；此外；更大程度地adj.更多的；附加的pron.更多的数量n.更多','/ˈmɔː/','/ˈmɔɹ/','adverb',["I could no more climb that than fly!","You''re more beautiful than I ever imagined.","I was more better at English than you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unable','adj.不会的，不能的；[劳经]无能力的；不能胜任的','/ʌnˈeɪbəl/','/ʌnˈeɪbəl/','adjective',["Are you unable to mind your own business or something?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('telescope','v.压缩；使套叠n.望远镜；缩叠式旅行袋','/ˈtɛlɪskəʊp/','/ˈtɛləˌskoʊp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('castle','n.城堡；象棋中的车v.置…于城堡中；筑城堡防御','/kæsl̩/','/kæsl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noisy','adj.嘈杂的；喧闹的；聒噪的','/ˈnɔːɪzɪ/','/ˈnɔɪzi/','adjective',["the noisy crowd.","a noisy bar","noisy clothes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('which','pron.哪/那一个；哪/那一些adj.哪一个；哪一些','/wɪt͡ʃ/','/wɪt͡ʃ/','pronoun',["By now, you must surely know which is which.","Please take which you please.","He had to leave, which was very difficult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equip','v.装备，配备','/ɪˈkwɪp/','/ɪˈkwɪp/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rain','n.雨；下雨；雨天；雨季v.下雨；降雨','/ɹeɪn/','/ɹeɪn/','noun',["The rains came late that year.","A rain of mortar fire fell on our trenches.","It will rain today."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hill','n.小山；丘陵；斜坡；山冈','/hɪl/','/hɪl/','noun',["The park is sheltered from the wind by a hill to the east.","You need to pick up speed to get up the hill that''s coming up.","a hill of corn or potatoes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doctor','v.修理；篡改，伪造；为…治病；授以博士学位n.医生；博士','/ˈdɒktə/','/ˈdɑktɚ/','noun',["If you still feel unwell tomorrow, see your doctor.","the doctor of a calico-printing machine, which is a knife to remove superfluous colouring matter","Her children doctored her back to health."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incorrect','adj.错误的，不正确的；不适当的；不真实的','/ˌɪnkəˈɹɛkt/','/ˌɪnkəˈɹɛkt/','adjective',["He gave an incorrect answer to a simple question.","The computer crashed due to incorrect programming.","He was sacked because of his incorrect behaviour towards his secretary."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('help','v.帮助；促进；治疗；补救n.帮助；补救办法；帮忙者；有益的东西','/hɛlp/','/hɛlp/','noun',["I need some help with my homework.","He was a great help to me when I was moving house.","I can''t find anything in the help about rotating an image."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('room','n.房间；空间；余地；机会；房间里所有的人v.为…提供住处；租房，合住；投宿，住宿；留…住宿','/ɹuːm/','/ɹuːm/','noun',["Go to your room!","The room was on its feet.","Some users may not be able to access the AOL room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('park','n.公园；[交]停车场v.停放；放置；寄存','[paːk]','[paːk]','noun',["A country''s tank park or artillery park.","I parked the drive heads of my hard disk before travelling with my laptop.","Let''s park that until next week''s meeting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idiom','n.成语，习语；土话','/ˈɪdɪəm/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beneficial','adj.有益的，有利的；可享利益的','/ˌbɛnəˈfɪʃəl/','/ˌbɛnəˈfɪʃəl/','noun',["Recycling and reusing garbage can be beneficial to the environment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incident','n.事件，事变；插曲adj.[光]入射的；附带的；易发生的，伴随而来的','/ˈɪn.sɪ.dənt/','/ˈɪn.sɪ.dənt/','noun',["It was an incident that he hoped to forget.","The incident light illuminated the surface."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('text','n.[计]文本；课文；主题v.发短信','/tɛkst/','/tɛkst/','noun',["German text","I''ll text the address to you as soon as I find it.","Have you been texting all afternoon?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strength','n.力量；力气；兵力；长处','/stɹɛŋkθ/','/stɹɛŋkθ/','noun',["It requires great strength to lift heavy objects.","He had the strength of ten men.","We all have our own strengths and weaknesses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('their','pron.他们的，她们的；它们的n.(Their)人名；(英)蒂尔；(芬、瑞典)泰尔','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('material','adj.重要的；物质的，实质性的；肉体的n.材料，原料；物资；布料','/məˈtɪəɹɪəl/','/məˈtɪəɹɪəl/','noun',["Asphalt, composed of oil and sand, is a widely used material for roads.","We were a warm-up act at the time; we didn''t have enough original material to headline.","You''ll need about a yard of material to make this."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receipt','n.收到；收据；收入v.收到','/ɹɪˈsiːt/','/ɹɪˈsiːt/','noun',["A balance payable on receipt of the goods.","This weekend''s receipts alone cover our costs to mount the production!","to receipt delivered goods"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('actor','n.男演员；行动者；作用物','/ˈæk.tə/','/ˈæk.tɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('globe','n.地球；地球仪；球体vt.使…成球形vi.成球状','/ɡloːb/','/ɡloːb/','noun',["the globe of the eye; the globe of a lamp"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chief','n.首领；酋长；主要部分adj.首席的；主要的；主任的adv.主要地；首要地','/tʃiːf/','/tʃiːf/','noun',["All firefighters report to the fire chief.","Hey, chief.","Negligence was the chief cause of the disaster."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('politics','n.政治，政治学；政治活动；政纲','/ˈpɒl.ɪ.tɪks/','/ˈpɑl.ɪˌtɪks/','verb',["He made a career out of politics.","Their politics are clear from the bumper stickers on their cars.","We''re trying to talk about comic books, don''t mention politics."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heart','n.心脏；感情；勇气；心形；要点vt.鼓励；铭记vi.结心','/hɑːt/','/hɑːt/','noun',["The team lost, but they showed a lot of heart.","a good, tender, loving, bad, hard, or selfish heart","Listen, dear heart, we must go now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chew','n.咀嚼；咀嚼物v.嚼碎，咀嚼','/tʃuː/','/tʃu/','noun',["I popped the gum into my mouth and gave it a chew.","Phillip purchased a bag of licorice chews at the drugstore.","The school had banned chew and smokes from the school grounds, even for adults."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extension','n.延长；延期；扩大；伸展；电话分机','/ɪkˈstɛnʃən/','/ɪkˈstɛnʃən/','noun',["Files with the .txt extension usually contain text.","a browser extension"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('botanical','adj.植物学的n.植物性药材','','','noun',["a botanical system"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lame','adj.跛足的；僵痛的；不完全的；无说服力的；差劲的，蹩脚的v.变跛','/leɪm/','/leɪm/','noun',["1877, Anna Sewell, Black Beauty: And if you don''t want to lame your horse you must look sharp and get them stones stuck in hooves out quickly.","a lame leg, arm or muscle","He had a really lame excuse for missing the birthday party."]);
