INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('litter','n.垃圾；轿，担架；一窝（动物的幼崽）；凌乱v.乱丢；给…垫褥草；把…弄得乱七八糟','/ˈlɪtə(ɹ)/','/ˈlɪtɚ/','noun',["sleep in the litter","drop litter","the cat''s litter"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sneaker','n.运动鞋；卑鄙者；鬼鬼祟祟做事的人','/ˈsnikɚ/','/ˈsnikɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abstract','n.摘要；抽象；抽象的概念adj.抽象的；深奥的v.摘要；提取；使……抽象化；转移(注意力、兴趣等)；使心不在焉','/ˈæbˌstɹækt/','/ˈæbˌstɹækt/','noun',["He was wholly abstracted by other objects.","He abstracted out the square root function."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nowadays','adv.现今；时下n.当今','/ˈnaʊ.ə.deɪz/','/ˈnaʊ.ə.deɪz/','adverb',[]);
