INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('just','adv.只是，仅仅；刚才，刚刚；正好，恰好；实在；刚要adj.公正的，合理的；正直的，正义的；正确的；公平的；应得的n.(Just)人名；(英)贾斯特；(法)朱斯特；(德、匈、波、捷、挪)尤斯特；(西)胡斯特','/d͡ʒʌst/','/d͡ʒʌst/','adjective',["It is a just assessment of the facts.","It looks like a just solution at first glance.","He calls it vermilion, but it''s just red to me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acknowledge','v.承认；答谢；报偿；告知已收到','/əkˈnɒ.lɪdʒ/','/ækˈnɑː.lɪdʒ/','verb',["to acknowledge the being of a god","to acknowledge a favor","This is to acknowledge your kind invitation to participate in the upcoming debate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enlarge','v.扩大；放大；详述','/ɪnˈlɑːd͡ʒ/','/ɪnˈlɑɹd͡ʒ/','verb',["Knowledge enlarges the mind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Switzerland','n.瑞士（欧洲国家）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conclusion','n.结论；结局；推论','/kənˈkluːʒən/','/kənˈkluːʒən/','noun',["The board has come to the conclusion that the proposed takeover would not be in the interest of our shareholders."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theirs','pron.他们的；她们的；它们的','/ðɛəz/','/ðɛɚz/','pronoun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('labourer','n.劳动者；劳工','/ˈleɪ.bə.ɹə/','/ˈleɪ.bə.ɹə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forbid','v.禁止；不准；不允许；〈正式〉严禁','/fəˈbɪd/','/fɚˈbɪd/','verb',["Smoking in the restaurant is forbidden.","An impassable river forbids the approach of the army.","What part of \"no\" do you forbid to understand?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weekly','adj.每周的；周刊的；一周一次的n.周刊adv.每周一次；逐周','/wiːk.li/','/wiːk.li/','noun',["He''s going for his weekly check-up at the hospital.","She visits her mother weekly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skip','v.跳跃；跳绳；遗漏；跳读n.跳跃；跳读','/skɪp/','/skɪp/','noun',["She will skip from one end of the sidewalk to the other.","The rock will skip across the pond.","I bet I can skip this rock to the other side of the pond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('something','pron.某事；某物n.重要的人；值得重视的事adv.非常；有点；大约adj.大约；有点象','/ˈsamθɪŋ/','/ˈsʌmθɪŋ/','noun',["The baby looks something like his father.","I have a feeling something good is going to happen today.","That child is something of a genius."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('themselves','pron.他们自己；他们亲自','/ðəmˈsɛlvz/','/ðəmˈsɛlvz/','pronoun',["They are going to try climbing Mount Everest themselves.","Everyone must do it themselves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('net','n.网；网络；净利；实价v.编网adj.纯粹的；净余的','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rail','n.铁轨；扶手；横杆；围栏v.抱怨；责骂','/ɹeɪl/','/ɹeɪl/','noun',["We travelled to the seaside by rail.","We''re experimenting with ads in the right-hand rail."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interrupt','v.中断；打断；插嘴；妨碍n.中断','/ˌɪntəˈɹʌpt/','/ˌɪntəˈɹʌpt/','noun',["The interrupt caused the packet handler routine to run.","A maverick politician repeatedly interrupted the debate by shouting.","The evenness of the road was not interrupted by a single hill."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('case','n.情况；实例；箱v.包围；把…装于容器中','/keɪs/','/keɪs/','noun',["For a change, in this case, he was telling the truth.","It was one of the detective''s easiest cases.  Social workers should work on a maximum of forty active cases.  The doctor told us of an interesting case he had treated that morning.","The teaching consists of theory lessons and case studies."]);
