INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shoot','v.射击，射中；拍摄；发芽；使爆炸；给…注射n.射击；摄影；狩猎；急流','/ʃuːt/','/ʃuːt/','noun',["The land shoots into a promontory."]);
