INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consistent','adj.始终如一的，一致的；坚持的','/kənˈsɪstənt/','/kənˈsɪstənt/','noun',["He is very consistent in his political choices: economy good or bad, he always votes Labour!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organization','n.组织；机构；体制；团体','/ˌɔɹɡənaɪˈzeɪʃən/','/ˌɔɹɡənɪˈzeɪʃən/','noun',["This painting shows little organization at first glance, but little by little the structure becomes clear.","The organization of the book is as follows.","In response to the crisis, the nations in the region formed an organization.   If you want to be part of this organization, you have to follow its rules."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('each','adj.每；各自的adv.每个；各自pron.每个；各自','/iːt͡ʃ/','/it͡ʃ/','noun',["The apples cost 50 cents each.","From each according to his ability, to each according to his needs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stone','n.石头；结石；[宝]宝石adj.石的，石制的v.向扔石块；用石头铺','/stəʊn/','/stoʊn/','noun',["a peach stone","kidney stone","She got stoned to death after they found her."]);
