INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foot','n.脚；英尺；步调；末尾v.步行；跳舞；总计','[fɵʔt]','[fʊt̚]','noun',["A spider has eight feet.","Southern Italy is shaped like a foot.","There is a lot of foot traffic on this street."]);
