INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hilly','adj.丘陵的；陡的；多小山的；多坡的n.(Hilly)人名；(阿拉伯)希利','/ˈhɪli/','/ˈhɪli/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('command','v.命令，指挥；控制n.指挥，控制；命令；司令部','/kəˈmɑːnd/','/kəˈmænd/','noun',["I was given a command to cease shooting.","to have command of an army","England has long held command of the sea"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('string','n.线，弦，细绳；一串，一行','/stɹɪŋ/','/stɹɪŋ/','noun',["There were stalls for fourteen horses in the squire''s stables.","a bowstring","a string of sausages"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thus','adv.因此；从而；这样；如此conj.因此n.乳香','/ˈðʌs/','/ˈðʌs/','adverb',["If you throw the ball thus, as I’m showing you, you’ll have better luck hitting the target.","I have all the tools I need; thus, I will be able to fix the car without having to call a mechanic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percent','n.百分比，百分率；部分；百分数adj.百分之…的adv.以百分之…地','/pəˈsɛnt/','/pɚˈsɛnt/','noun',["only a small percent attain the top ranks"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('banana','n.香蕉；喜剧演员；大鹰钩鼻','/bəˈnɑːnə/','/bəˈnænə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thick','n.最拥挤部分；活动最多部分；事物的粗大浓密部分adj.厚的；浓的；粗大的adv.密集地；浓浓地，厚厚地','/θɪk/','/θɪk/','noun',["It was mayhem in the thick of battle.","I want some planks that are two inches thick.","He had such a thick neck that he had to turn his body to look to the side."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('far','adv.很；遥远地；久远地；到很远的距离；到很深的程度adj.远的；久远的n.远方','/fɑː/','/fɑɹ/','adjective',["He went to a far land.","the far future","He moved to the far end of the state. She remained at this end."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronaut','n.宇航员，航天员；太空旅行者','/ˈæstɹəˌnɒt/','/ˈæstɹəˌnɒt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('much','adv.非常，很adj.大量的n.许多，大量pron.许多，大量','/mʌt͡ʃ/','/mʌt͡ʃ/','adjective',["He is much fatter than I remember him.","Does he get drunk much?","I don''t like Wagner as much as I like Mozart."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('security','n.安全；保证；证券；抵押品adj.安全的；保安的；保密的','/sɪˈkjɔːɹəti/','/səˈkjɔɹ.ɪˌti/','noun',[]);
