INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keeper','n.监护人；饲养员；看守人；管理人','/ˈkiːpə/','/ˈkiːpɚ/','noun',["Finders keepers; losers weepers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('backward','adj.向后的；反向的；发展迟缓的adv.向后地；相反地','/ˈbæk.wə(ɹ)d/','/ˈbæk.wə(ɹ)d/','noun',["They left without a backward glance.","The occasional backward movement of planets is evidence they revolve around the sun.","a backward child"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uncle','n.叔叔；伯父；伯伯；舅父；姨丈；姑父','/ˈʌŋ.kəl/','/ˈʌŋ.kəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reality','n.现实；实际；真实','/ɹiˈæləti/','/ɹiˈæləti/','noun',["The reality of the crash scene on TV dawned upon him only when he saw the victim was no actor but his friend.","The ultimate reality of life is that it ends in death."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rot','n.腐烂；腐败；腐坏v.腐烂；腐败；堕落int.（表示厌恶、蔑视、烦恼等）胡说；糟了','/ɹɔt/','[ɹɑt]','noun',["The apple left in the cupboard all that time had started to rot.","Your brain will rot if you spend so much time on the computer, Tony!","to rot vegetable fiber"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receive','v.收到；接待；接纳','/ɹɪˈsiːv/','/ɹɪˈsiːv/','noun',["She received many presents for her birthday.","to receive a lodger, visitor, ambassador, messenger, etc.","I received a bloody nose from the collision."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bee','n.蜜蜂，蜂；勤劳的人','/ˈbiː/','/ˈbiː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appreciation','n.欣赏，鉴别；增值；感谢','/əˌpɹiː.ʃiˈeɪ.ʃən/','/əˌpɹiː.ʃiˈeɪ.ʃən/','noun',["We give to you this trophy as a token of our appreciation of all your years of service.","an appreciation of colors"]);
