INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lavatory','n.厕所，盥洗室','/ˈlæv.ə.təɹ.i/','/ˈlæv.ə.təɹ.i/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('judge','v.判断；审判n.法官；裁判员','/d͡ʒʌd͡ʒ/','/d͡ʒʌd͡ʒ/','noun',["At a boxing match, the decision of the judges is final.","She is a good judge of wine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tough','adj.艰苦的，困难的；坚强的，不屈不挠的；坚韧的，牢固的；强壮的，结实的n.恶棍v.坚持；忍受，忍耐adv.强硬地，顽强地','/tʌf/','/tʌf/','noun',["They were doing fine until they encountered a bunch of toughs from the opposition.","The tent, made of tough canvas, held up to many abuses.","To soften a tough cut of meat, the recipe suggested simmering it for hours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biochemistry','n.生物化学','','','noun',["The biochemistries of fungal and bacterial cells are quite distinct.","Our study compared the biochemistries of epilepsy and Parkinson''s."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dull','adj.钝的；迟钝的；无趣的；呆滞的；阴暗的v.使迟钝；使阴暗；缓和n.(Dull)人名；(罗、匈)杜尔；(柬)杜；(英)达尔','/dəl/','/dʌl/','verb',["Years of misuse have dulled the tools.","He drinks to dull the pain.","A razor will dull with use."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('king','n.国王；最有势力者；王棋vi.统治；做国王vt.立…为王adj.主要的，最重要的，最大的','/kɪŋ/','/kiŋ/','noun',["Henry VIII was the king of England from 1509 to 1547.","Howard Stern styled himself as the \"king of all media\".","In times of financial panic, cash is king."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crash','n.撞碎；坠毁；破产；轰隆声；睡觉v.摔碎；坠落；发出隆隆声；(金融企业等)破产','/kɹæʃ/','/kɹæʃ/','noun',["After the lightning came the crash of thunder.","Nobody survived the plane crash","My computer had a crash so I had to reboot it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('church','n.教堂；礼拜；教派adj.教会的；礼拜的v.领…到教堂接受宗教仪式','/t͡ʃɜːt͡ʃ/','/t͡ʃɝt͡ʃ/','noun',["There is a lovely little church in the valley.","These worshippers make up the Church of Christ.","The Church of England separated from the Roman Catholic Church in 1534."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('language','n.语言；语言文字；表达能力','[ˈleɪŋɡwɪd͡ʒ]','[ˈleɪŋɡwɪd͡ʒ]','noun',["Deaf and mute people communicate using languages like ASL.","the gift of language","legal language;   the language of chemistry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boundary','n.边界；范围；分界线','/ˈbaʊndɹi/','/ˈbaʊndəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheat','v.欺骗；骗取n.欺骗，作弊；骗子','/tʃiːt/','/tʃiːt/','verb',["My brother flunked biology because he cheated on his mid-term.","After he found out his wife cheated, he left her.","He cheated death when his car collided with a moving train."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cocoa','n.可可粉；可可豆；可可饮料；深褐色','/ˈkəʊ.kəʊ/','/ˈkoʊ.koʊ/','noun',["Do you like cocoa?","I like to watch TV with a cocoa."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idea','n.想法；主意；概念','/ɑeˈdiə̯/','/aɪˈdi.ə/','noun',["The mere idea of you is enough to excite me.","I have an idea of how we might escape.","Yeah, that''s the idea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('climb','v.爬；攀登；上升n.爬；攀登','/klaɪm/','/klaɪm/','noun',["Prices climbed steeply.","Climbing a tree"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upset','v.使心烦；颠覆；扰乱adj.心烦的；混乱的；弄翻的n.混乱；翻倒；颠覆','','','noun',["My late arrival caused the professor considerable upset.","\"collision and upset\": impact with another object or an overturn for whatever reason.","I’m sure the bad news will upset him, but he needs to know."]);
