INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appeal','v.呼吁，恳求；上诉；诉诸，求助；有吸引力，迎合爱好；（体育比赛中）诉诸裁判n.呼吁，请求；吸引力，感染力；上诉；诉诸裁判','/əˈpiːl/','/əˈpiːl/','noun',["He made an appeal for volunteers to help at the festival.","I appeal to all of you to help the orphans.","That idea appeals to me."]);
