INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socket','n.插座；窝，穴；牙槽vt.给…配插座','/ˈsɒkɪt/','/ˈsɑkɪt/','noun',[]);
