INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('owner','n.[经]所有者；物主','/ˈəʊnə/','/ˈoʊnɚ/','noun',["The police recovered the stolen car and returned it to its owner."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grow','v.发展；生长；渐渐变得…n.(Grow)人名；(英)格罗','/ɡɹəʊ/','/ɡɹoʊ/','verb',["Children grow quickly.","A long tail began to grow from his backside.","As I grew throughout adolescence, I came to appreciate many things about human nature."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beautiful','adj.美丽的','/ˈbjuːtɪfəl/','/ˈbjuːtɪfəl/','noun',["Hey, beautiful!","Anyone who has ever met her thought she was absolutely beautiful.","It''s beautiful outside, let''s go for a walk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fierce','adj.凶猛的；猛烈的；暴躁的n.(Fierce)人名；(英)菲尔斯','/fɪəs/','/fɪɹs/','adjective',["A fierce storm battered the coast.","We made a fierce attempt to escape.","The lion gave a fierce roar."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pedestrian','adj.徒步的；缺乏想像力的n.行人；步行者','/pəˈdɛst.ɹi.ən/','/pəˈdɛst.ɹi.ən/','noun',["pedestrian crossing","His manner of dress was pedestrian but tidy.","The choreographer prefers pedestrian movements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('court','n.法院；球场；朝廷；奉承v.招致（失败、危险等）；向…献殷勤；设法获得','/kɔːt/','/kɔɹt/','noun',["The girls were playing in the court.","The local sports club has six tennis courts and two squash courts.","He was courting big new accounts that previous salesman had not attempted."]);
