INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cause','n.原因；事业；目标v.引起；使遭受','/kɔːz/','/kɔz/','noun',["They identified a burst pipe as the cause of the flooding.","The end of the war was a cause for celebration.","The lightning caused thunder."]);
