INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nervous','adj.神经的；紧张不安的；强健有力的','/ˈnɜːvəs/','/ˈnɝːvəs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thorough','adj.彻底的；十分的；周密的','/ˈθʌɹə/','/ˈθɜɹoʊ/','noun',["He is the most thorough worker I have ever seen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seal','n.密封；印章；海豹；封条；标志v.密封；盖章','/siːl/','/siːl/','noun',["The seals in the harbor looked better than they smelled.","They''re organizing a protest against sealing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tissue','n.组织；纸巾；薄纱；一套v.饰以薄纱；用化妆纸揩去','/ˈtɪsjuː/','/ˈtɪʃu/','noun',["a tissue of forgeries, or of lies"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('damp','v.使潮湿；使阻尼；使沮丧，抑制n.潮湿，湿气adj.潮湿的','/dæmp/','/dæmp/','noun',["to damp cloth","The lawn was still damp so we decided not to sit down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condemn','v.谴责；判刑，定罪；声讨','/kənˈdɛm/','/kənˈdɛm/','verb',["The president condemned the terrorists.","The house was condemned after it was badly damaged by fire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yawn','n.哈欠；裂口v.打哈欠；裂开','/jɔːn/','/jɔːn/','noun',["The slideshow we sat through was such a yawn. I was glad when it finished.","I could see my students yawning, so I knew the lesson was boring them.","Death yawned before us, and I hit the brakes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biology','n.（一个地区全部的）生物；生物学','/baɪˈɒlədʒɪ/','/baɪˈɑlədʒi/','noun',["the biology of the whale"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('announcement','n.公告；宣告；发表；通告','/əˈnaʊns.mɛnt/','/əˈnaʊns.mɛnt/','noun',["He raised his hand to make his announcement and said \"Excuse me everyone, I have an announcement to make.","This announcement was made during the first training session.","The announcement implied that somebody needed a spare Toshiba charger."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punish','v.惩罚；严厉对待；贪婪地吃喝','/ˈpʌnɪʃ/','/ˈpʌnɪʃ/','verb',["If a prince violates the law, then he must be punished like an ordinary person."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('army','n.陆军，军队','/ˈɑː.miː/','/ˈɑɹ.mi/','noun',["The army was sent in to quell the uprising.","The army opposed the legislature''s involvement.","It took an army of accountants to uncover the fraud."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hunger','n.饿，饥饿；渴望v.渴望；挨饿','/ˈhʌŋɡə/','/ˈhʌŋɡɚ/','noun',["I have a hunger to win."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('businesswoman','n.女商人','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('well','adv.很好地；充分地；满意地；适当地adj.良好的；健康的；适宜的n.井；源泉v.涌出','/wɛl/','/wɛl/','adjective',["I had been sick, but now I''m well.","“How are you?” — “I''m well, thank you!”","He does his job well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airplane','n.飞机','/ˈɛəpleɪn/','/ˈɛəɹˌpleɪ̯n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boss','n.老板；首领；工头v.指挥，调遣；当…的领导','/bɒs/','','noun',["Chat turned to whisper when the boss entered the conference room.","They named him boss because he had good leadership skills.","He is the Republican boss in Kentucky."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warm','adj.温暖的；热情的v.同情；激动；变温暖n.取暖；加热','/wɔːm/','/wɔɹm/','adjective',["The tea is still warm.","We have a warm friendship.","a warm piano sound"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('figure','n.数字；人物；图形；价格；（人的）体形；画像v.计算；出现；扮演角色','/ˈfɪɡjɚ/','/ˈfɪɡjɚ/','noun',["a figure in bronze; a figure cut in marble","He cut a sorry figure standing there in the rain.","The muslin was of a pretty figure."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condition','n.条件；情况；环境；身份v.决定；使适应；使健康；以…为条件','/kənˈdɪʃən/','/kənˈdɪʃən/','noun',["Environmental protection is a condition for sustainability.   What other planets might have the right conditions for life?   The union had a dispute over sick time and other conditions of employment.","My aunt couldn''t walk up the stairs in her condition.","National reports on the condition of public education are dismal.   The condition of man can be classified as civilized or uncivilized."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bus','n.公共汽车','/bɐs/','/bɐs/','noun',["He bussed tables as the restaurant emptied out.","He’s been bussing for minimum wage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('works','n.作品；工厂；工程结构','/wɜːks/','/wɝks/','noun',["We don''t have much time. Let''s get to work piling up those sandbags.","Tell me you''re using clean works at least.","He’s working in a bar."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bargain','n.交易；便宜货；契约v.讨价还价；议价；(谈价钱后)卖','/-ɡɪn/','/ˈbɑːɹɡən/','noun',["At that price, it''s not just a bargain, it''s a steal.","They had to bargain for a few minutes to get a decent price for the rug."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Dynamic','adj.动态的；动力的；动力学的；有活力的n.动态；动力','/daɪˈnæ.mɪk/','/daɪˈnæ.mɪk/','noun',["Watch the dynamic between the husband and wife when they disagree.","The study of fluid dynamics quantifies turbulent and laminar flows.","If you pay attention to the dynamics as you play, it''s a very moving piece."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('song','n.歌曲；歌唱；诗歌；鸣声','/sɒŋ/','/sɑŋ/','noun',["Thomas listened to his favorite song on the radio yesterday.","I love hearing the song of canary birds.","He bought that car for a song."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goal','n.目标；球门，得分数；终点vi.攻门，射门得分','/ɡɒʊl/','/ɡoʊl/','noun',["My lifelong goal is to get into a Hollywood movie."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grain','n.粮食；颗粒；[作物]谷物；纹理v.成谷粒','/ɡɹeɪn/','/ɡɹeɪn/','noun',["We stored a thousand tons of grain for the winter.","a grain of wheat","The fields were planted with grain."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('add','v.加；增加；加起来；做加法n.加法，加法运算','/æd/','/æd/','noun',["When the player has fought the boss for one minute, two adds will arrive from the back and must be dealt with.","to add numbers","to add a column of numbers"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('premier','adj.第一的；最初的n.总理，首相','/ˈpɹemjə/','/ˈpɹemjə/','noun',["The composer invited all his friends when they premiered the movie he orchestrated, we got to see it before anyone but the crew."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('starve','v.饿死；挨饿；渴望','/stɑːv/','/stɑɹv/','verb',["Hey, ma, I''m starving! What''s for dinner?","The patient''s brain was starved of oxygen.","I was half starved waiting out in that wind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('himself','pron.他自己；他亲自，他本人','/hɪmˈsɛlf/','/hɪmˈsɛlf/','pronoun',["He injured himself.","He was injured himself.","Has himself come down to breakfast yet?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pie','n.馅饼；饼图；爱说话的人vt.使杂乱','/paɪ/','/paɪ/','noun',["The family had steak and kidney pie for dinner and cherry pie for dessert.","Shepherd''s pie is made of mince covered with mashed potato.","I''d like to see someone pie the chairman of the board."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slave','n.奴隶；从动装置v.苦干；拼命工作','/sleɪv/','/sleɪv/','noun',["a slave to passion, to strong drink, or to ambition","I was slaving all day over a hot stove.","to slave a hard disk"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('December','n.十二月','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('budget','n.预算，预算费v.安排，预定；把…编入预算adj.廉价的','/ˈbʌdʒ.ɪt/','/ˈbʌdʒ.ɪt/','noun',["Budgeting is even harder in times of recession","The PM’s pet projects are budgeted rather generously","The prestigious building project is budgeted in great detail, from warf facilities to the protocollary opening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dinner','n.晚餐，晚宴；宴会；正餐','/ˈdɪnə/','/ˈdɪnəɹ/','noun',["Give the dog its dinner."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patience','n.耐性，耐心；忍耐，容忍','/ˈpeɪʃəns/','/ˈpeɪʃəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('should','aux.应该；就；可能；将要','/ʃʊd/','/ʃʊd/','verb',["I hope that we shall win the game.","(determination): You shall go to the ball!","Let us examine that, shall we?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mistaken','adj.错误的；弄错的；被误解的v.弄错（mistake的过去分词）','/mɪsˈteɪkən/','/mɪsˈteɪkən/','verb',["Don''t mistake my kindness for weakness.","A mistaken sense of loyalty.","He admitted he was mistaken about the budget numbers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjust','v.调整，使…适合；校准','/əˈdʒʌst/','/əˈdʒʌst/','verb',["Morimoto''s recipes are adjusted to suit the American palate.","He adjusted his initial conclusion to reflect the new data.","Most immigrants adjust quickly to a new community.   She waited for her eyes to adjust to the darkness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possession','n.拥有；财产；领地；自制；着迷','/pəˈzɛʃən/','/pəˈzɛʃən/','noun',["I would gladly give all of my worldly possessions just to be able to do that.","I''m in possession of the car.","Réunion is the largest of France''s overseas possessions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blanket','n.毛毯，毯子；毯状物，覆盖层adj.总括的，全体的；没有限制的v.覆盖，掩盖；用毯覆盖','/ˈblæŋkɪt/','/ˈblæŋkɪt/','noun',["The baby was cold, so his mother put a blanket over him.","The city woke under a thick blanket of fog.","A press operator must carefully wash the blanket whenever changing a plate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ashamed','adj.惭愧的，感到难为情的；耻于……的','/əˈʃeɪmd/','/əˈʃeɪmd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crowded','adj.拥挤的；塞满的v.拥挤（crowd的过去分词）','/ˈkɹaʊdɪd/','/ˈkɹaʊdɪd/','verb',["The man crowded into the packed room.","They crowded through the archway and into the park.","He tried to crowd too many cows into the cow-pen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('long','n.长时间；[语]长音节；（服装的）长尺寸；长裤adj.长的；过长的；做多头的；长时间的；冗长的，长音v.渴望；热望adv.长期地；始终','/ˈlɔːŋ/','/ˈlɔːŋ/','noun',["Every uptick made the longs cheer.","It''s a long way from the Earth to the Moon.","The pyramids of Egypt have been around for a long time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('review','n.回顾；复习；评论；检讨；检阅v.回顾；检查；复审','/ɹɪˈvjuː/','/ɹɪˈvjuː/','noun',["I need to make a review of the book before I can understand it.","The newspaper review was full of praise for the play.","The victims demanded a full judicial review of the case."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shine','v.发出光；反射光，闪耀；出类拔萃，表现突出；露出；照耀；显露；出众n.光亮，光泽；好天气；擦亮；晴天；擦皮鞋；鬼把戏或诡计','/ʃaɪn/','/ʃaɪn/','noun',["She''s certainly taken a shine to you.","My nephew tried other sports before deciding on football, which he shone at right away, quickly becoming the star of his school team.","I shone my light into the darkness to see what was making the noise."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rid','v.使摆脱；使去掉n.(Rid)人名；(英)里德','/ˈɹɪd/','/ˈɹɪd/','verb',["We''re trying to rid the world of poverty.","I’m glad to be rid of that stupid nickname."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('learn','v.学习；得知；认识到','/lɜːn/','/lɝn/','noun',["learn from one''s mistakes","I learn medicine.","He just learned that he will be sacked."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disagreement','n.不一致；争论；意见不同','/dɪsəˈɡɹiːmənt/','','noun',["They had a bit of a disagreement about what color to paint the bedroom, but they have reached a compromise.","The theory shows considerable disagreement with the data."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lose','v.浪费；使沉溺于；使迷路；遗失；错过n.(Lose)人名；(英)洛斯；(德)洛泽','/luːz/','/luːz/','verb',["He lost his hearing in the explosion.","I lost my way in the forest.","We lost the football match."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graduate','v.授予…学位；分等级；标上刻度n.研究生；毕业生adj.毕业的；研究生的','','','noun',["If the government wants graduates to stay in the country they should offer more incentives.","The man graduated in 1967.","Trisha graduated college."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everybody','pron.每个人；人人','/ˈɛvɹibɒdi/','/ˈɛvɹibɑdi/','pronoun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('describe','v.描述，形容；描绘','/dəˈskɹaɪb/','/dəˈskɹaɪb/','verb',["The feeling is difficult to describe, but not unpleasant.","to describe a circle by the compasses;   a torch waved about the head in such a way as to describe a circle","The function describes a very complex surface."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('especially','adv.特别；尤其；格外','/əˈspɛʃ(ə)li/','/əˈspɛʃ(ə)li/','adverb',["Invite them all, especially Molly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Tuesday','n.星期二','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crossroads','n.十字路口；交叉路口；聚会的中心地点（crossroad的复数形式）','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soon','adv.快；不久，一会儿；立刻；宁愿','/suːn/','/suːn/','adjective',["I need the soonest date you have available."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspect','v.检查；视察；检阅','/ɪnˈspɛkt/','/ɪnˈspɛkt/','verb',["Inspect the system for leaks.","The general inspected the troops and their barracks."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protection','n.保护；防卫；护照','/pɹəˈtɛkʃən/','/pɹəˈtɛkʃən/','noun',["Raincoats give protection from rain."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fasten','v.使固定；集中于；扎牢；强加于n.(Fasten)人名；(英)法森','/ˈfɑːsn̩/','/ˈfæsn̩/','verb',["Can you fasten these boards together with some nails?","to fasten a blow"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deeply','adv.深刻地；浓浓地；在深处','/ˈdiːpli/','/ˈdiːpli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tanker','n.油轮；运油飞机；油槽车；坦克手','','','noun',["I swung the tanker around just in time to take off with the lip"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lion','n.狮子；名人；勇猛的人；社交场合的名流','/ˈlaɪən/','/ˈlaɪən/','noun',["Tigers and lions share a common ancestor from a few million years ago."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skill','n.技能，技巧；本领，技术','/skɪl/','/skɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('familiar','adj.熟悉的；常见的；亲近的n.常客；密友','/fəˈmɪl.i.ə/','/fəˈmɪl.i.ɚ/','noun',["The witch’s familiar was a black cat.","there’s a familiar face; that tune sounds familiar","I''m quite familiar with this system; she''s not familiar with manual gears"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silence','n.沉默；寂静；缄默；不谈；无声状态v.使沉默；使安静；压制；消除噪音int.安静！；别作声！','/ˈsaɪ.ləns/','/ˈsaɪ.ləns/','noun',["When the motor stopped, the silence was almost deafening.","\"You have the right to silence,\" said the police officer.","During silence a message came to me that there was that of God in every person."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('send','v.发送，寄；派遣；使进入；发射n.上升运动','/sɛnd/','/sɛnd/','noun',["Every day at two o''clock, he sends his secretary out to buy him a coffee.","Seeing how ill she was, we sent for a doctor at once.","She finally sent the 12a after hours of failed attempts."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('birthday','n.生日，诞辰；诞生的日子','/ˈbɜːθ.deɪ/','/ˈbɝθˌdeɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compare','n.比较v.比拟，喻为；[语]构成','/kəmˈpɛə/','/kəmˈpɛɚ/','noun',["Compare the tiger''s coloration with that of the zebra.","Astronomers have compared comets to dirty snowballs.","We compare \"good\" as \"good\", \"better\", \"best\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illness','n.病；疾病','/ˈɪl.nəs/','/ˈɪl.nəs/','noun',["Her grandmother had passed away after a long illness.","Many working days this year have been lost through illness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('universal','adj.普遍的；通用的；宇宙的；全世界的；全体的n.一般概念；普通性','/ˌjuːnɪˈvɜːsl̩/','/ˌjunɪˈvɝsl̩/','noun',["She achieved universal fame.","universal wrench"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arise','v.出现；上升；起立n.(Arise)人名；(西)阿里塞；(日)在濑(姓)','/əˈɹaɪz/','/əˈɹaɪz/','verb',["to arise from a kneeling posture","He arose early in the morning.","A cloud arose and covered the sun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reason','n.理由；理性；动机v.推论；劝说','/ˈɹiːzən/','/ˈɹiːzən/','noun',["Mankind should develop reason above all other virtues.","I reasoned the matter with my friend.","to reason one into a belief; to reason one out of his plan"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('picture','n.照片，图画；影片；景色；化身v.画；想像；描写','/ˈpɪktʃə/','/ˈpɪk(t)ʃɚ/','noun',["There was a picture hanging above the fireplace.","I took a picture of the church.","Casablanca is my all-time favorite picture."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lack','v.缺乏；不足；没有；需要n.缺乏；不足','/lak/','/læk/','noun',["My life lacks excitement.","He''ll never lack for company while he''s got all that money."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('westerner','n.西方人，欧美人；美国西部的人','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unless','conj.除非，如果不prep.除…之外','/ənˈlɛs/','/ənˈlɛs/','conjunction',["I’m leaving unless I get a pay rise (AmE: raise)."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everyday','adj.每天的，日常的n.平时；寻常日子','/ˈɛvɹiˌdeɪ/','/ˈɛvɹiˌdeɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gift','n.礼物；天赋；赠品v.赋予；向…赠送','/ɡɪft/','/ɡɪft/','noun',["She had a gift for playing the flute.","The office is in the gift of the President."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soap','n.肥皂v.将肥皂涂在……上；对……拍马屁（俚语）','/səʊp/','/soʊp/','noun',["I tried washing my hands with soap, but the stain wouldn''t go away.","Be sure to soap yourself well before rinsing.","Those kids soaped my windows!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('painting','n.绘画；油画；着色v.绘画（paint的ing形式）；涂色于','/ˈpeɪn.tɪŋ/','/ˈpeɪn.tɪŋ/','verb',["to paint a portrait or a landscape","I''ve been painting since I was a young child.","She sued the author of the biography, claiming it painted her as a duplicitous fraud."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advance','n.发展；前进；增长；预付款v.提出；预付；使……前进；将……提前adj.预先的；先行的','/ədˈvaːns/','/ədˈvæns/','noun',["an advance in health or knowledge","an advance on the prime cost of goods","He made an advance payment on the prior shipment to show good faith."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sex','n.性；性别；性行为；色情v.引起…的性欲；区别…的性别','/sɛks/','/sɛks/','noun',["The effect of the medication is dependent upon age, sex, and other factors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thunderstorm','n.[气象]雷暴；雷暴雨；大雷雨','/ˈθʌn.də(ɹ)ˌstɔː(ɹ)m/','/ˈθʌn.də(ɹ)ˌstɔː(ɹ)m/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('privilege','n.特权；优待v.给与…特权；特免','/ˈpɹɪv(ɪ)lɪdʒ/','/ˈpɹɪv(ɪ)lɪdʒ/','noun',["All first-year professors here must teach four courses a term, yet you''re only teaching one! What entitled you to such a privilege?","Your honor, my client is not required to answer that; her response is protected by attorney-client privilege.","to privilege representatives from arrest"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personal','adj.个人的；身体的；亲自的n.人事消息栏；人称代名词','/ˈpɜː.sən.əl/','/ˈpɜɹ.sən.əl/','noun',["Her song was her personal look at the values of friendship.","personal charms","a personal interview;  personal settings"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('introduction','n.介绍；引进；采用；入门；传入','/ˌɪntɹəˈdʌkʃən/','/ˌɪntɹəˈdʌkʃən/','noun',["the introduction of a new product into the market"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carpet','v.在…上铺地毯，把地毯铺在…上；斥责n.地毯；地毯状覆盖物','/ˈkɑː(ɹ)pɪt/','/ˈkɑɹpət/','noun',["After the fire, they carpeted over the blackened hardwood flooring.","Popcorn and candy wrappers carpeted the floor of the cinema."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chemistry','n.化学；化学过程','/ˈkɛm.ɪ.stɹi/','/ˈkɛm.ɪ.stɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hear','v.听到，听；听说；审理','/hɪə(ɹ)/','/hɪɹ/','verb',["I was deaf, and now I can hear.","I heard a sound from outside the window.","Eventually the king chose to hear her entreaties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('combine','v.使化合；使联合，使结合n.联合收割机；联合企业','/kəmˈbaɪn/','/kəmˈbaɪn/','noun',["We can''t finish harvesting because our combine is stuck in the mud.","Combine the milk and the hot water in a large bowl.   I''m combining business and pleasure on this trip.","Joe combines the intelligence of a rock with the honesty of a politician."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smelly','adj.有臭味的，发臭的','/ˈsmɛli/','/ˈsmɛli/','adjective',["She was hesitant to remove her shoes, as her socks were rather smelly.","The detective read the documents and thought, \"Something sure is smelly about this case.\"","That smelly code needs to be refactored."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tourism','n.旅游业；游览','/tɔːɹɪz(ə)m/','/tɔːɹɪz(ə)m/','noun',["libel tourism; suicide tourism; sex tourism"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Japan','n.日本（东亚国家名）','/dʒəˈpæn/','/dʒəˈpæn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affection','n.喜爱，感情；影响；感染','/əˈfɛkʃən/','/əˈfɛkʃən/','noun',["I have a lot of affection for my little sister."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('locust','n.[植保]蝗虫，[昆]蚱蜢','/ˈləʊ.kəst/','/ˈloʊ.kəst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accuse','v.控告，指控；谴责；归咎于','/əˈkjuːz/','/əˈkjuz/','noun',["For the U.S. President to be impeached, he must be accused of a high crime or misdemeanor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beam','n.横梁；光线；电波；船宽；[计量]秤杆v.发送；以梁支撑；用…照射；流露','/biːm/','/biːm/','noun',["This ship has more beam than that one.","a beam of energy","a beam of hope, or of comfort"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embarrass','v.使局促不安；使困窘；阻碍','/ɪmˈbæ.ɹəs/','/ɪmˈbæ.ɹəs/','verb',["The crowd''s laughter and jeers embarrassed him.","The motion was advanced in order to embarrass the progress of the bill.","A man or his business is embarrassed when he cannot meet his pecuniary engagements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('businessman','n.商人','/ˈbɪznəsmən/','/ˈbɪznəsmæn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bat','n.蝙蝠；球棒；球拍；批处理文件的扩展名v.用球棒击球；击球率达…','/bæt/','/bæt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('English','adj.英国人的；英国的；英文的n.英语；英国人；英文；英格兰人vt.把…译成英语','/ˈɪŋ.ɡlɪʃ/','/ˈɪŋ.ɡlɪʃ/','noun',["You can''t hit it directly, but maybe if you give it some english."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reference','n.参考，参照；涉及，提及；参考书目；介绍信；证明书v.引用','/ˈɹɛf.(ə)ɹəns/','/ˈɹɛf.(ə)ɹəns/','noun',["You must thoroughly reference your paper before submitting it.","Reference the dictionary for word meanings.","In his speech, the candidate obliquely referenced the past failures of his opponent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beer','n.啤酒vi.喝啤酒','/bɪə/','/bɪɹ/','noun',["Beer is brewed all over the world.","Can I buy you a beer?","I haven''t tried this beer before."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('public','adj.公众的；政府的；公用的；公立的n.公众；社会；公共场所','/ˈpʌblɪk/','/ˈpʌblɪk/','noun',["Members of the public may not proceed beyond this point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breathe','v.呼吸；低语；松口气；（风）轻拂','/bɹiːð/','/bɹið/','verb',["Fish have gills so they can breathe underwater.","While life as we know it depends on oxygen, scientists have speculated that alien life forms might breathe chlorine or methane.","I will not allow it, as long as I still breathe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eggplant','n.茄子adj.深紫色的','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cousin','n.堂兄弟姊妹；表兄弟姊妹','/ˈkʌz.n̩/','/ˈkʌz.n̩/','noun',["I think my cousin is a good man."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('push','v.推动，增加；对…施加压力，逼迫；按；说服n.推，决心；大规模攻势；矢志的追求','[pʷʊʃ]','[pʷʊʃ]','noun',["Give the door a hard push if it sticks.","One more push and the baby will be out.","Let''s give one last push on our advertising campaign."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tolerate','v.忍受；默许；宽恕','/ˈtɒl.ə.ɹeɪt/','/ˈtɑl.ə.ɹeɪt/','verb',["I can tolerate working on Saturdays, but not on Sundays."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('golden','adj.金色的，黄金般的；珍贵的；金制的n.(Golden)人名；(英、法、罗、德、瑞典)戈尔登','/ˈɡəʊl.dən/','/ˈɡəʊl.dən/','noun',["She wore a golden crown.","Under a golden sun.","The Renaissance was a golden era."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waitress','n.女服务员；女侍者v.做女服务生','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('senior','adj.高级的；年长的；地位较高的；年资较深的，资格较老的n.上司；较年长者；毕业班学生','/ˈsiːnjə(r)/','/ˈsinjɚ/','noun',["He was four years her senior.","senior citizen","senior member; senior counsel"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('FALSE','adj.错误的；虚伪的；伪造的adv.欺诈地','/fɒls/','/fɑls/','noun',["The student received a failing grade for circling every true and false on her quiz.","false legislation, false punishment","false teeth"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('February','n.二月','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suffering','n.受难；苦楚adj.受苦的；患病的v.受苦；蒙受（suffer的ing形式）','/ˈsʌfəɹɪŋ/','/ˈsʌfəɹɪŋ/','verb',["Is anyone here afraid of suffering hardship?","At least he didn''t suffer when he died in the car crash.","If you keep partying like this, your school-work will suffer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peace','n.和平；平静；和睦；秩序','/piːs/','/piːs/','noun',["Our lounge strives to maintain an environment of peace for the comfort of our customers.","The safety equipment will give me some peace of mind.","May there be peace in our time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronomer','n.天文学家','/ə.ˈstɹɑ.nə.mɚ/','/ə.ˈstɹɒ.nə.mɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biscuit','n.小点心，饼干','/ˈbɪskɪt/','/ˈbɪskɪt/','noun',["cheese and biscuits"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reuse','n.重新使用，再用v.再使用','/ɹiːˈjuːs/','/ɹiːˈjuːs/','noun',["Code reuse can save programmers a lot of typing.","The students reused empty plastic bottles in their science experiment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rope','n.绳，绳索v.捆，绑','/ɹəʊp/','/ɹoʊp/','noun',["Nylon rope is usually stronger than similar rope made of plant fibers.","The swinging bridge is constructed of 40 logs and 30 ropes.","The duchess wore a rope of pearls to the soirée."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radio','n.收音机；无线电广播设备v.用无线电进行通信','/ˈɹeɪdiˌəʊ/','/ˈɹeɪdiˌoʊ/','noun',["I think the boat is sinking; we''d better radio for help. / I radioed him already. / Radio the coordinates this time. / OK. I radioed them the coordinates."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cent','n.分；一分的硬币；森特（等于半音程的百分之一）','/sɛnt/','/sɛnt/','noun',["He blew every last cent.","shopping center, convention center, civic center, garment center, Lincoln Center for the Performing Arts, Rockefeller Center","the center of attention"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refreshments','n.点心；[食品]茶点；小吃','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vital','adj.至关重要的；生死攸关的；有活力的n.(Vital)人名；(法、德、意、俄、葡)维塔尔；(西)比塔尔','/ˈvaɪt̬əl/','/ˈvaɪt̬əl/','adjective',["vital energies; vital functions; vital actions","The brain is a vital organ.","The transition to farming was vital for the creation of civilisation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('settlement','n.解决，处理；[会计]结算；沉降；殖民','/ˈset.l.mənt/','/ˈset.l.mənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pot','n.壶；盆；罐v.把…装罐；射击；节略','/pɒt/','/pɑt/','noun',["After his arrest, his prospects went to pot.","to pot a plant","potted meat"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('windbreaker','n.防风夹克，同windcheater','/ˈwɪndbɹeɪkə(ɹ)/','/ˈwɪndbɹeɪkə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frog','n.青蛙；[铁路]辙叉；饰扣v.捕蛙','/fɹɒɡ/','/fɹɑɡ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sure','adj.确信的；可靠的；必定的adv.当然；的确n.(Sure)人名；(英)休尔','/ʃoː/','/ʃɔɹ/','adjective',["This investment is a sure thing.   The bailiff had a sure grip on the prisoner''s arm.","He was sure she was lying.   I am sure of my eventual death.   John was acting sure of himself but in truth had doubts.","Be sure to lock the door when you leave."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poor','adj.贫穷的；可怜的；贫乏的；卑鄙的n.(Poor)人名；(英、伊朗)普尔','/pɔː(ɹ)/','/pɔɹ/','noun',["The poor are always with us.","We were so poor that we couldn''t afford shoes.","That was a poor performance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soft','adj.软的，柔软的；温柔的，温和的；软弱的；笨的adv.柔软地；温和地n.柔性；柔软的东西；柔软部分','/sɑft/','/sɔft/','noun',["My head sank easily into the soft pillow.","Polish the silver with a soft cloth to avoid scratching.","I could hear the soft rustle of the leaves in the trees."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relevant','adj.相关的；切题的；中肯的；有重大关系的；有意义的，目的明确的','/ˈɹɛləvənt/','/ˈɹɛləvənt/','adjective',["His mother provided some relevant background information concerning his medical condition."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limit','n.限制；限度；界线v.限制；限定','/ˈlɪmt/','/ˈlɪmɪt/','noun',["There are several existing limits to executive power.","The sequence of reciprocals has zero as its limit.","Category theory defines a very general concept of limit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sow','v.播种；散布；使密布n.母猪','/saʊ/','/saʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('usual','adj.通常的，惯例的；平常的','/ˈjuːʒʊəl/','/ˈjuːʒʊəl/','noun',["I''ll just have the usual.","It is becoming more usual these days to rear children as bilingual."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jazz','n.爵士乐，爵士舞；喧闹v.奏爵士乐，跳爵士舞；游荡adj.爵士乐的；喧吵的','/d͡ʒæz/','/d͡ʒæz/','noun',["What is all this jazz lying around?","I''m just going down to the shops and jazz.","That show was the jazz!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('century','n.世纪，百年；（板球）一百分','/ˈsɛn.t͡ʃə.ɹiː/','/ˈsɛn.t͡ʃə.ɹiː/','noun',["That was his tenth professional century."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tea','n.茶叶；茶树；茶点vt.给…沏茶vi.喝茶；进茶点','/tiː/','/ti/','noun',["After smoking a bowl of that fine marijuana, they ate some brownies.","a fish supper; a pizza supper","Darjeeling tea is grown in India."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corner','n.角落，拐角处；地区，偏僻处；困境，窘境v.囤积；相交成角','/ˈkɔːnə(ɹ)/','/ˈkɔɹnɚ/','noun',["The corners of the wire mesh were reinforced with little blobs of solder.","Shining a light in the dark corners of the mind.  I took a trip out to his corner of town.","On weekends, Emily liked to find a quiet corner and curl up with a good book."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fiction','n.小说；虚构，编造；谎言','/ˈfɪk.ʃən/','/ˈfɪk.ʃən/','noun',["I am a great reader of fiction.","The butler’s account of the crime was pure fiction."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('understand','v.理解；懂；获悉；推断；省略','/(ˌ)ʌndəˈstænd/','/ˌʌndɚˈstænd/','verb',["I''m sorry. I don''t understand.","I understand that you have a package for me?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mean','adj.平均的；卑鄙的；低劣的；吝啬的v.意味；想要；意欲n.平均值','/miːn/','/miːn/','verb',["Does she really mean what she said to him last night?","One faltering step means certain death.","Formality and titles mean nothing in their circle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resist','v.抵抗，抗拒；忍耐n.[助剂]抗蚀剂；防染剂','/ɹəˈzɪst/','/ɹəˈzɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('playmate','n.玩伴；游伴','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fault','n.故障；[地质]断层；错误；缺点；毛病；（网球等）发球失误v.弄错；产生断层','/fɒlt/','/fɒlt/','noun',["No! This is my fault, not yours.","For all her faults, she’s a good person at heart.","The fault lies with you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thriller','n.惊险小说；使人毛骨悚然的东西；使人毛骨悚然的小说','/ˈθɹɪlɚ/','/ˈθɹɪlɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('message','n.消息；差使；启示；预言；广告词v.报信，报告；[通信]报文','/ˈmɛsɪd͡ʒ/','/ˈmɛsɪd͡ʒ/','noun',["We''ve just received an urgent message from the President.","The main message of the novel is that time heals all wounds.","I messaged her about the concert."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theme','n.主题；主旋律；题目adj.以奇想主题布置的','/θiːm/','/θiːm/','noun',["We themed the birthday party around superheroes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('am','abbr.调频，调谐，调幅（amplitudemodulation）v.（用于第一人称单数现在时）aux.（与v-ing连用构成现在进行时，与v-ed连用构成被动语态）n.（柬）安（人名）','[e̞m]','[ɛ̃ə̃ːm]','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accuracy','n.[数]精确度，准确性','[ˈækjʊrəsɪ]','/ˈæk.jɚ.ə.si/','noun',["The value of testimony depends on its accuracy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balloon','v.激增；膨胀如气球n.气球adj.像气球般鼓起的','/bəˈluːn/','/bəˈlun/','noun',["the balloon of St. Paul''s Cathedral in London","His stomach ballooned from eating such a large meal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('you','pron.你；你们n.(You)人名；(柬)尤；(东南亚国家华语)猷','/juː/','/jə/','verb',["Both of you should get ready now.","You are all supposed to do as I tell you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oil','n.油；石油；油画颜料v.加油；涂油；使融化','/ɔɪl/','/ɔɪl/','noun',["I prefer to paint in oil"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('departure','n.离开；出发；违背','/dɪˈpɑː(ɹ)tjə(ɹ)/','','noun',["The departure was scheduled for noon.","There are several significant departures, however, from current practice.","The area is computed by latitudes and departures."]);
