INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chorus','n.合唱队；齐声；歌舞队v.合唱；异口同声地说','/ˈkɔːɹəs/','/ˈkɔːɹəs/','noun',["The performance of the chorus was awe-inspiring and exhilarating.","The catchiest part of most songs is the chorus.","a chorus of crickets"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competition','n.竞争；比赛，竞赛','/ˌkɒmpəˈtɪʃən/','/ˌkɑːmpəˈtɪʃən/','noun',["The competition for this job is strong.","The newspaper is featuring a competition to win a car.","The new stain remover was ten times more effective than the competition."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boat','n.小船；轮船v.划船','/bəʊt/','/boʊt/','noun',["a stone boat;  a gravy boat","to boat goods","to boat oars"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fur','n.皮，皮子；毛皮；软毛v.用毛皮覆盖；使穿毛皮服装','/fɜː(ɹ)/','/fɝ/','noun',[]);
