INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encourage','v.鼓励，怂恿；激励；支持','/ɪnˈkʌɹɪdʒ/','/ɪnˈkɝɹɪdʒ/','verb',["I encouraged him during his race.","We encourage the use of bicycles in the town centre.","The royal family has always encouraged the arts in word and deed"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('road','n.公路，马路；道路；手段vt.（狗）沿臭迹追逐（猎物）adj.（美）巡回的','/ɹəʊd/','/ɹoʊd/','noun',["We travelled to the seaside by road."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punishment','n.惩罚；严厉对待，虐待','/ˈpʌnɪʃmənt/','/ˈpʌnɪʃmənt/','noun',["a vehicle that can take a lot of punishment"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('place','n.地方；住所；座位v.放置；任命；寄予','/pleɪs/','/pleɪs/','noun',["I''m in a strange place at the moment.","three decimal places;  the hundreds place","That''s what I said in the first place!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parking','n.停车adj.停车的v.停车（park的ing形式）','/ˈpɑːkɪŋ/','/ˈpɑːkɪŋ/','verb',["I parked the drive heads of my hard disk before travelling with my laptop.","Let''s park that until next week''s meeting.","to park artillery, wagons, automobiles, etc."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('machine','n.机械，机器；机构；机械般工作的人v.用机器制造','','/məˈʃin/','noun',["I called you earlier, but all I got was the machine.","Game developers assume they''re pushing the limits of the machine.","Bruce Campbell was a \"demon-killing machine\" because he made quick work of killing demons."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tell','v.告诉，说；辨别；吩咐；断定n.(Tell)人名；(英、德、瑞典)特尔；(罗、意)泰尔；(阿拉伯)塔勒','/tɛl/','/tɛl/','noun',["All told, there were over a dozen.  Can you tell time on a clock?  He had untold wealth.","I want to tell a story;  I want to tell you a story.","Finally, someone told him the truth.  He seems to like to tell lies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('think','v.想；认为；想起；想像；打算n.想；想法adj.思想的','/θɪŋk/','/θɪŋk/','noun',["I''ll have a think about that and let you know.","Idly, the detective thought what his next move should be.","I thought for three hours about the problem and still couldn’t find the solution."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nearby','adj.附近的，邻近的adv.在附近prep.在…附近','','','adjective',["He stopped at a nearby store for some groceries.","I''m glad my friends live nearby where I can visit them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('human','adj.人的；人类的n.人；人类','/ˈhjuː.mən/','/ˈ(h)ju.mən/','noun',["Humans share common ancestors with other apes.","To err is human; to forgive, divine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('range','n.范围；幅度；排；山脉v.（在内）变动；平行，列为一行；延伸；漫游；射程达到','/ɹeɪndʒ/','/ɹeɪndʒ/','noun',["We sell a wide range of cars.","One can use the speed of sound to estimate the range of a lightning flash.","This missile''s range is 500 kilometres."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complex','adj.复杂的；合成的n.复合体；综合设施','','','noun',["Jim has a real complex about working for a woman boss."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fever','n.发烧，发热；狂热vt.使发烧；使狂热；使患热病vi.发烧；狂热；患热病','/ˈfiːvə/','/ˈfivɚ/','noun',["\"I have a fever. I think I''ve the flu.\"","a fevered lip"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('royal','adj.皇家的；盛大的；女王的；高贵的；第一流的n.王室；王室成员','/ˈɹɔɪəl/','/ˈɹɔɪəl/','noun',["royal mast;  royal sail","a royal pain in the neck"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brave','adj.勇敢的；华丽的v.勇敢地面对n.勇士','/bɹeɪv/','/bɹeɪv/','noun',["After braving tricks on the high-dive, he braved a jump off the first diving platform."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irrigate','v.灌溉；冲洗；使清新','/ˈɪɹəˌɡeɪt/','/ˈɪɹəˌɡeɪt/','verb',["We need to irrigate the land before we plant the crops.","The nurse will show you how to irrigate the wound to prevent infection."]);
