INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beg','v.乞讨；恳求；回避正题n.(Beg)人名；(德、塞、巴基)贝格','/bɛɡ/','/bɛɡ/','noun',["He begged on the street corner from passers-by.","He begged her to go to the prom with him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trust','n.信任，信赖；责任；托拉斯v.信任，信赖；盼望；赊卖给','/trʊst/','/trʌst/','noun',["He needs to regain her trust if he is ever going to win her back.","I was out of cash, but the landlady let me have it on trust.","I put the house into my sister''s trust."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strike','v.打，打击；罢工；敲，敲击；抓；打动；穿透n.罢工；打击；殴打','/stɹaɪk/','/stɹaɪk/','noun',["Thus hand strikes now include single knuckle strikes, knife hand strikes, finger strikes, ridge hand strikes etc., and leg strikes include front kicks, knee strikes, axe kicks, ...","The batsmen have crossed, and Dhoni now has the strike.","Please strike the last sentence."]);
