INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amateur','n.爱好者；业余爱好者；外行adj.业余的；外行的','/ˈæ.mə.tə/','/ˈæ.mə.tɚ/','noun',["The contest is only open to amateurs.","The entire thing was built by some amateurs with screwdrivers and plywood.","amateur sports"]);
