INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phone','n.电话；耳机，听筒v.打电话','/fəʊ̯n/','/foʊ̯n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('province','n.省；领域；职权','/ˈpɹɒvɪns/','/ˈpɹɑvɪns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('workplace','n.工作场所；车间','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('play','v.游戏；扮演；演奏；播放；同…比赛n.游戏；比赛；剧本','/pleɪ/','/pleɪ/','noun',["Children learn through play.","This kind of play helps the young lion cubs develop their hunting skills.","After the rain break, play resumed at 3 o''clock."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reply','v.回答；[法]答辩；回击n.回答；[法]答辩','/ɹɪˈplaɪ/','/ɹɪˈplaɪ/','noun',["Joanne replied to Pete''s insult with a slap to his face."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('department','n.部；部门；系；科；局','/dɪˈpɑːtm(ə)nt/','/dəˈpɑɹtmənt/','noun',["Technical things are not his department; he''s a people person.","the Department of the Potomac"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intention','n.意图；目的；意向；愈合','/ɪnˈtɛnʃən/','/ɪnˈtɛnʃən/','noun',["It’s easy to promise anything when you have no intention of fulfilling any of it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tutor','v.辅导；约束n.导师；家庭教师；助教','/ˈtjuːtə/','/ˈtutɚ/','noun',["He passed the difficult class with help from his tutor.","To help pay her tuition, the college student began to tutor high school students in calculus and physics."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graduation','n.毕业；毕业典礼；刻度，分度；分等级','/ˌɡɹædʒuˈeɪʃən/','/ˌɡɹædʒuˈeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spear','n.矛，枪v.用矛刺','/spɪɹ/','/spɪɹ/','noun',["asparagus and broccoli spears","a spear counterpart","the spear side of the family"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communication','n.通讯，[通信]通信；交流；信函','/kəˌmjuːnɪˈkeɪʃən/','/kəˌmjuːnɪˈkeɪʃən/','noun',["communication of a secret","Some say that communication is a necessary prerequisite for sentience; others say that it is a result thereof.","Surveillance was accomplished by means of intercepting the spies'' communications."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plant','n.工厂，车间；植物；设备；庄稼v.种植；培养；栽培；安置','/plɑːnt/','/plænt/','noun',["The garden had a couple of trees, and a cluster of colourful plants around the border.","That gun''s not mine! It''s a plant! I''ve never seen it before!","That gun''s not mine! It was planted there by the real murderer!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('listen','v.听，倾听；听从，听信n.听，倾听','/ˈlɪs.ən/','/ˈlɪs.ən/','noun',["Give the motor a listen and tell me if it sounds off.","Please listen carefully as I explain.  I like to listen to music.","You should listen for the starting gun."]);
