INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('betray','v.背叛；出卖；泄露（秘密）；露出…迹象','/bəˈtɹeɪ/','/bəˈtɹeɪ/','verb',["an officer betrayed the city","My eyes have been betraying me since I turned sixty.","Though he had lived in England for many years, a faint accent betrayed his Swedish origin."]);
