INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squid','n.鱿鱼；乌贼；枪乌贼','/skwɪd/','/skwɪd/','noun',["Can you lend me five squid? I feel like a bacon sarnie."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convenient','adj.方便的；[废语]适当的；[口语]近便的；实用的','/kənˈviːniənt/','/kənˈvinjənt/','adjective',["Fast food might be convenient, but it''s also very unhealthy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dark','adj.黑暗的，深色的；模糊的；无知的；忧郁的n.黑暗；夜；黄昏；模糊','/dɑːk/','/dɑɹk/','adjective',["The room was too dark for reading.","my sister''s hair is darker than mine;  her skin grew dark with a suntan","a dark villain;  a dark deed"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zero','n.零点，零度num.零','/ˈzɪəɹəʊ/','/ˈzi(ˌ)ɹoʊ/','noun',["In unary and k-adic notation in general, zero is the empty string.","One million has six zeroes.","He knows zero about humour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interesting','adj.有趣的；引起兴趣的，令人关注的','/ˈɪnt(ə)ɹɛstɪŋ/','/ˈɪnt(ʃ)ɹɛstɪŋ/','verb',["Action films don''t really interest me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chips','n.[食品]炸土豆条；小木片；（作赌注用的）圆形筹码；缺口（chip的复数形式）','/tʃɪps/','/tʃɪps/','noun',["This cup has a chip in it.","Do you want sauce or mayonnaise on your chips?","The workers chipped the dead branches into mulch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sugar','n.糖；食糖；甜言蜜语v.加糖于；粉饰','/ˈʃʊɡə(ɹ)/','/ˈʃʊɡɚ/','noun',["He usually has his coffee white with one sugar.","I''ll be with you in a moment, sugar.","I think John has a little bit of sugar in him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silk','n.丝绸；蚕丝；丝织物adj.丝的；丝绸的；丝制的vi.（玉米）处于长须的阶段中','/sɪlk/','/sɪlk/','noun',["The thread made of silk was barely visible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nod','n.点头；打盹；摆动v.点头；点头表示','/nɔd/','/nɑd/','noun',["For the fifth time in her career she received a Grammy nod, she has yet to win the award.","The plan is expected to get the nod from councillors at the next meeting.","They nodded their assent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('float','v.使漂浮；实行n.彩车，花车；漂流物；浮舟；浮萍','/fləʊt/','/floʊt/','noun',["Attach the float and the weight to the fishing line, above the hook.","When pouring a new driveway, you can use a two-by-four as a float.","That float covered in roses is very pretty."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('believe','v.信任；料想；笃信宗教','/bɪˈliːv/','/bi-/','verb',["I believe there are faeries.","Why did I ever believe you?","After that night in the church, I believed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Mom','n.妈妈','/mʌm/','/mɑm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('June','n.六月；琼（人名，来源于拉丁语，含义是“年轻气盛的六月”）','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treatment','n.治疗，疗法；处理；对待','/ˈtɹiːtmənt/','/ˈtɹiːtmənt/','noun',["He still has nightmares resulting from the treatment he received from his captors.","A treatment or cure is applied after a medical problem has already started."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sight','n.视力；景象；眼界；见解v.看见；瞄准adj.见票即付的；即席的','/saɪt/','/saɪt/','noun',["He is losing his sight and now can barely read.","to gain sight of land","We went to London and saw all the sights – Buckingham Palace, Tower Bridge, and so on."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calm','adj.静的，平静的；沉着的v.使平静；使镇定n.风平浪静','/kam/','/kɑlm/','noun',["to calm a crying baby"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plenty','n.丰富，大量；充足adj.足够的，很多的adv.足够','/ˈplɛnti/','/ˈplɛnti/','noun',["We are lucky to live in a land of peace and plenty.","She was plenty mad at him.","I think six eggs should be plenty for this recipe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('missile','n.导弹；投射物adj.导弹的；可投掷的；用以发射导弹的','/ˈmɪsaɪl/','/ˈmɪsaɪl/','noun',["The Rhodians, who used leaden bullets, were able to project their missiles twice as far as the Persian slingers, who used large stones.","That missile is explosive enough to kill hundreds."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('environment','n.环境，外界','/-mɪnt/','/-mɪnt/','noun',["That program uses the Microsoft Windows environment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyone','pron.任何人；任何一个','/ˈæniˌwʌn/','/ˈæniˌwʌn/','pronoun',["Almost anyone can change a light bulb."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clearly','adv.清晰地；明显地；无疑地；明净地','/ˈkliːɹli/','/ˈklɪɹli/','adverb',["He enunciated every syllable clearly.","Clearly, the judge erred in his opinion.","He was clearly wrong on all points but one."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('climate','n.气候；风气；思潮；风土','/ˈklaɪmɪt/','/ˈklaɪmɪt/','noun',["Industries that require a lot of fossil fuels are unlikely to be popular in the current political climate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behave','v.表现；（机器等）运转；举止端正；（事物）起某种作用','/bəˈheɪv/','/bəˈheɪv/','verb',["You need to behave yourself, young lady.","He behaves like a child whenever she''s around.","His mother threatened to spank him if he didn''t behave."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delete','v.删除','/diˈliːt/','/diˈliːt/','noun',["I lost the file when I accidentally hit delete."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('call','v.呼叫；拜访；叫牌n.电话；呼叫；要求；访问','/kɔːɫ/','/kɔl/','noun',["I received several calls today.","I paid a call to a dear friend of mine.","The ship made a call at Southampton."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catastrophe','n.大灾难；大祸；惨败','/kəˈtæstɹəfi/','/kəˈtæstɹəfi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orbit','n.轨道；眼眶；势力范围；生活常规v.盘旋；绕轨道运行','/ˈɔː(ɹ)bɪt/','/ˈɔː(ɹ)bɪt/','noun',["The Moon''s orbit around the Earth takes nearly one month to complete.","In the post WWII era, several eastern European countries came into the orbit of the Soviet Union.","The convenience store was a heavily travelled point in her daily orbit, as she purchased both cigarettes and lottery tickets there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('customs','n.海关；风俗（custom的复数）；习惯；关税','/ˈkʌstəmz/','/ˈkʌstəmz/','noun',["Customs of £200 were due on all the wine we took back from France.","Customs has pulled us over on our way for an inspection."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snowy','adj.下雪的，多雪的；被雪覆盖的；洁白无瑕的','/snəʊi/','','adjective',["snowy day","snowy hillside"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waste','n.浪费；废物；荒地；损耗；地面风化物v.浪费；消耗；使荒芜adj.废弃的；多余的；荒芜的','/weɪst/','/weɪst/','noun',["The cage was littered with animal waste","Her life seemed a waste"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regard','n.注意；尊重；问候；凝视v.注重，考虑；看待；尊敬；把…看作；与…有关','/ɹɪˈɡɑːd/','/ɹɪˈɡɑɹd/','noun',["He is held in great regard in Whitehall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communism','n.共产主义','/ˈkɒm.juˌnɪzm̩/','/ˈkɒm.juˌnɪzm̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('less','adv.较少地；较小地；更小地adj.较少的；较小的prep.减去n.较少；较小','/lɛs/','/lɛs/','noun',["I have less to do today than yesterday.","I like him less each time I see him.","It should then tax all of that as personal income, less the proportion of the car''s annual mileage demonstrably clocked up on company business."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('French','adj.法国的；法语的；法国人的n.法国人；法语','/fɹɛnt͡ʃ/','/fɹɛnt͡ʃ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reduce','v.减少；降低；使处于；把…分解','/ɹɪˈdjuːs/','/ɹɪˈduːs/','verb',["to reduce weight, speed, heat, expenses, price, personnel etc.","Hester Prynne was shocked at the condition to which she found the clergyman reduced.","to reduce a province or a fort"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identification','n.鉴定，识别；认同；身份证明','/aɪˌdɛntɪfɪˈkeɪʃən/','/aɪˌdɛntɪfɪˈkeɪʃən/','noun',["Much education and experience is required for proper identification of bird species","information necessary to make a good identification","The authorities asked for his identification"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alphabet','n.字母表，字母系统；入门，初步','/ˈæl.fə.bɛt/','/ˈæl.fə.bɛt/','noun',["In the first year of school, pupils are taught to recite the alphabet.","Let L be a regular language over the alphabet \\Sigma."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lawyer','n.律师；法学家','/ˈlɔɪ.ə(ɹ)/','/ˈlɔ.jɚ/','noun',["A lawyer''s time and advice are his stock in trade. - aphorism often credited to Abraham Lincoln, but without attestation","You''ve been lawyered!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moon','n.月亮；月球；月光；卫星v.闲荡；出神','/muːn/','/muːn/','proper noun',["That''s no moon, you idiot... it''s a space station!","They stayed with their aunt and uncle for many moons.","The moons surrounding the city walls were built in the sixteenth century."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('robot','n.机器人；遥控设备，自动机械；机械般工作的人','/ˈɹoʊbət/','/ˈɹoʊbɑt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nineteen','num.十九','/naɪnˈtiːn/','/ˈnaɪnˌtin/','numeral',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sigh','v.叹息，叹气n.叹息，叹气','/saɪ/','/saɪ/','noun',["He sighed over the lost opportunity.","He silently sighed for his lost youth.","She sighed a sigh that was nearly a groan."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('food','n.食物；养料','/fuːd/','/fuːd/','noun',["The innkeeper brought them food and drink.","Mozart and Bach are food for my soul."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('raise','v.提高；筹集；养育；升起n.高地；上升；加薪','/ɹeɪz/','/ɹeɪz/','noun',["The boss gave me a raise.","to raise your hand if you want to say something; to raise your walking stick to defend yourself","We need to raise the motivation level in the company."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strengthen','v.加强；巩固','/ˈstɹɛŋ(k)θən/','/ˈstɹɛŋ(k)θən/','verb',["strengthen a muscle"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('league','n.联盟；社团；范畴v.使…结盟；与…联合','/liːɡ/','/liːɡ/','noun',["the League of Nations","My favorite sports organizations are the National Football League and the American League in baseball.","Forget about dating him; he''s out of your league."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scissors','n.剪刀；剪式跳法v.剪开；删除（scissor的第三人称单数）','/ˈsɪzəz/','/ˈsɪzɚz/','noun',["The erroneous testimony was scissored from the record.","The runner scissored over the hurdles.","Scissors are used to cut the flowers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweat','v.使出汗；流出；使干苦活；剥削；藉出汗减轻；焦急地期待n.汗；水珠；焦急；苦差使','/swɛt/','/swɛt/','noun',["Just thinking about the interview tomorrow puts me into a nervous sweat.","the sweat of hay or grain in a mow or stack"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reflect','v.反映；反射，照出；表达；显示;反省','/ɹɪˈflɛkt/','/ɹɪˈflɛkt/','verb',["A mirror reflects the light that shines on it.","The moonlight reflected from the surface of water.","The shop window reflected his image as he walked past."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deep','n.深处；深渊adj.深的；低沉的；深奥的adv.深入地；深深地；迟','/diːp/','/diːp/','noun',["creatures of the deep","the deep of night","Russell is a safe pair of hands in the deep."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tooth','n.牙齿vt.给……装齿vi.啮合','/tuːθ/','/tuːθ/','noun',["I have a sweet tooth: I love sugary treats.","to tooth a saw"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orange','adj.橙色的；橘色的n.橙；橙色；桔子','/ˈɔɹɪ̈nd͡ʒ/','/ˈɔɹɪ̈nd͡ʒ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prohibit','v.阻止，禁止','/pɹəʊˈhɪbɪt/','/pɹoʊˈhɪbɪt/','verb',["The restaurant prohibits smoking on the patio."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finance','n.财政，财政学；金融v.负担经费，供给…经费','/faɪˈnæns/','/faɪˈnæns/','noun',["Who''s really in charge of a democracy''s finances?","Finance on all our new cars is provided by ABC Loans Ltd.","He financed his home purchase through a local credit union."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rule','v.统治；管辖；裁定n.统治；规则','/ɹuːl/','/ɹuːl/','noun',["All participants must adhere to the rules.","As a rule, our senior editors are serious-minded.","a rule for extracting the cube root"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tank','n.坦克；水槽；池塘v.把…贮放在柜内；打败','/tæŋk/','/tæŋk/','noun',["I burned three tanks of gas on the drive to New York."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worthy','adj.值得的；有价值的；配得上的，相称的；可尊敬的；应…的n.杰出人物；知名人士','/ˈwɜːði/','/ˈwɝði/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communicate','v.通讯，传达；相通；交流；感染','/kəˈmjuːnɪkeɪt/','/kəˈmjuːnɪkeɪt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('population','n.人口；[生物]种群，[生物]群体；全体居民','/ˌpɒpjʊˈleɪʃən/','/pɒpjuːˈleɪʃən/','noun',["The population of New Jersey will not stand for this!","India has the third-largest population of English-speakers in the world.","The town’s population is only 243."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('influence','n.影响；势力；感化；有影响的人或事v.影响；改变','/ˈɪn.flu.əns/','/ˈɪn.flu.əns/','noun',["I have absolutely no influence over him.","I''m not able to exercise influence over him.","He has been a great influence on the voters during the elections."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Oceania','n.大洋洲','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noble','adj.高尚的；贵族的；惰性的；宏伟的n.贵族vt.抓住；逮捕','/ˈnəʊbəl/','/ˈnoʊbəl/','noun',["This country house was occupied by nobles in the 16th century.","He is a noble man who would never put his family in jeopardy.","a noble edifice"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knife','n.刀；匕首v.用刀切；（口）伤害','/naɪf/','/naɪf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grandson','n.孙子；外孙','/ˈɡɹæn(d)sʌn/','/ˈɡɹæn(d)sʌn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revolution','n.革命；旋转；运行；循环','/ˌɹɛvəˈl(j)uːʃən/','/ˌɹɛvəˈl(j)uːʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clone','n.克隆；无性系；无性繁殖；靠营养生殖而由母体分离繁殖的植物v.无性繁殖，复制','/kləʊn/','/kloʊn/','noun',["The scientists were able to clone a sheep."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('post','n.岗位；邮件；标杆v.张贴；公布；邮递；布置','/pəʊst/','/poʊst/','noun',["ram a post into the ground","Post no bills.","to post someone for cowardice"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bunch','n.群；串；突出物v.隆起；打褶；形成一串','/ˈbʌntʃ/','/ˈbʌntʃ/','noun',["a bunch of grapes;  a bunch of bananas;  a bunch of keys;  a bunch of yobs on a street corner","He still hangs out with the same bunch.","a bunch of trouble"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twenty','n.二十；二十年代num.二十adj.二十的','/ˈtwɛnti/','/ˈtwɛni/','noun',["The waiter’s face lit up when I gave him a twenty.","What’s your twenty, good buddy?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('troop','n.军队；组；群；多数v.群集；成群而行；结队','/tɹuːp/','/tɹuːp/','noun',["The children trooped into the room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kangaroo','n.袋鼠','/kaŋ.ɡə.ˈɹuː/','/kaŋ.ɡə.ˈɹuː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dear','adj.亲爱的；尊敬的；昂贵的adv.高价地；疼爱地int.哎呀n.亲爱的人','/diːɹ/','/dɪɹ/','noun',["My cousin is such a dear, always drawing me pictures.","Pass me the salt, would you dear?","The dearer the jewel, the greater the love expressed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('welfare','n.福利；幸福；福利事业；安宁adj.福利的；接受社会救济的','/ˈwɛlˌfɛə/','/ˈwɛlˌfɛə/','noun',["welfaring the poor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roll','v.卷；滚动，转动；辗n.卷，卷形物；名单；摇晃','/ɹəʊl/','/ɹoʊl/','noun',["Look at the roll of the waves.","Hear the roll of cannon.","Calculate the roll of that aircraft."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explanation','n.说明，解释；辩解','/ˌɛkspləˈneɪʃən/','/ˌɛkspləˈneɪʃən/','noun',["The explanation was long and drawn-out.","An explanation for the UFO sightings was easily found."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feel','v.感觉；认为；触摸；试探n.感觉；触摸','/fiːl/','/fiːl/','noun',["Bark has a rough feel.","You should get a feel of the area before moving in.","She gave me a quick feel to show that she loves me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mad','adj.疯狂的；发疯的；愚蠢的；着迷的n.狂怒','/ˈmæːd/','/ˈmæd/','verb',["He''s got this mad idea that he''s irresistible to women.","Are you mad at me?","It''s mad that I got that job back a day after being fired."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squirrel','n.松鼠；松鼠毛皮v.贮藏','/ˈskwɪɹl̩/','/ˈskwɪɹl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('she','pron.她（主格）；它（用来指雌性动物或国家、船舶、地球、月亮等）n.女人；雌性动物','/ʃiː/','/ʃi/','noun',["Pat is definitely a she.","After the cat killed a mouse, she left it on our doorstep.","She could do forty knots in good weather."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destination','n.目的地，终点','/dɛstɪˈneɪʃən/','/dɛstɪˈneɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('differ','v.使…相异；使…不同n.(Differ)人名；(法)迪费','/ˈdɪfə/','/ˈdɪfɚ/','verb',["These shoes only differ from those ones in having slightly longer laces.","The numbers 3 and 21 differ by 18."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pack','n.包装；一群；背包；包裹；一副v.包装；压紧；捆扎；挑选；塞满','/pæk/','/pæk/','noun',["The horses carried the packs across the plain.","a pack of complaints","We were going to play cards, but nobody brought a pack."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seaman','n.海员，水手；水兵','/ˈsiːmən/','/ˈsiːmən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terror','n.恐怖；恐怖行动；恐怖时期；可怕的人','/ˈtɛɹə/','/ˈtɛɚ/','noun',["a terror attack; the War on Terror"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('force','n.力量；武力；军队；魄力v.促使，推动；强迫；强加','/fɔːs/','/fɔɹs/','noun',["the force of an appeal, an argument, or a contract","police force","show of force"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discussion','n.讨论，议论','/dɪsˈkʊʃən/','/dɪˈskʌʃən/','noun',["My discussion with the professor was very enlightening.","Under each heading, you will find a discussion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('station','n.车站；驻地；地位；身份v.配置；安置；驻扎','/ˈsteɪʃən/','/ˈsteɪʃən/','noun',["She had ambitions beyond her station.","I used to listen to that radio station.","I was stationed on the pier."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('business','n.商业；[贸易]生意；[贸易]交易；事情','/ˈbɪd.nəs/','/ˈbɪd.nəs/','noun',["I was left my father''s business.","He is in the motor and insurance businesses.","He''s such a poor cook, I can''t believe he''s still in business!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('granny','n.奶奶；外婆；婆婆妈妈的人','/ˈɡɹæni/','/ˈɡɹæni/','noun',["I''m going to be a granny.","There are too many grannies around here getting in the way.","granny dress; granny glasses"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Arabic','adj.阿拉伯的；阿拉伯人的n.阿拉伯语','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bone','n.骨；骨骼v.剔去的骨；施骨肥于','/bəʉn/','/ˈboʊn/','noun',["to bone stays","boning rod","bone up"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('OK','adj.好的；不错的adv.行；很好int.好；可以v.对…表示同意n.同意','','','adjective',["Do you think it''s OK to stay here for the night?","The soup was OK, but the dessert was excellent.","He''s not feeling well now, but he should be OK after some rest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bishop','n.（基督教的）主教；（国际象棋的）象','/ˈbɪʃəp/','/ˈbɪʃəp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refusal','n.拒绝；优先取舍权；推却；取舍权','/ɹɪˈfjuːzl̩/','/ɹɪˈfjuːzl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eager','adj.渴望的；热切的；热心的n.(Eager)人名；(英)伊格','/ˈiːɡə/','/ˈiɡɚ/','adjective',["I was eager to show my teacher how much I''d learned over the holidays.","an eager algorithm"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cancel','vt.取消','/ˈkænsl̩/','/ˈkænsl̩/','noun',["He cancelled his order on their website.","This machine cancels the letters that have a valid zip code.","The corrective feedback mechanism cancels out the noise."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prepare','v.准备；配制','/pɹɪˈpɛə/','/pɹəˈpɛəɹ/','noun',["We prepared the spacecraft for takeoff.","We prepared a fish for dinner.","We prepared for a bumpy ride."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('govern','v.统治；管理','/ˈɡʌvən/','/ˈɡʌvɚn/','noun',["The old king governed the land wisely.","Govern yourselves like civilized people.","Chance governs the outcome of many card games."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surgeon','n.外科医生','/ˈsɜːdʒən/','/ˈsɜːdʒən/','noun',["The surgeon refused to operate because the patient was her son."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('analyse','vt.分析；研究','','','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abrupt','adj.突然的，意外的','/aˈbɹʌpt/','/aˈbɹʌpt/','noun',["The party came to an abrupt end when the parents of our host arrived."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resemble','vt.像，类似','/ɹɪˈzɛmb(ə)l/','/ɹɪˈzɛmb(ə)l/','verb',["The twins resemble each other."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discourage','vt.使气馁，打消','/dɪsˈkʌɹɪd͡ʒ/','/dɪsˈkɝɪd͡ʒ/','noun',["Don''t be discouraged by the amount of work left to do: you''ll finish it in good time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hall','n.大厅，礼堂；门厅，过道','/hɔːl/','/hɔl/','noun',["The drinking fountain was out in the hall.","The hotel had three halls for conferences, and two were in use by the convention.","The duke lived in a great hall overlooking the sea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pollution','n.污染','/pəˈl(j)uːʃn̩/','/pəˈl(j)uːʃn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remote','adj.遥远的','[ɹəˈməʊt]','[ɹɪˈmoʊt]','noun',["A remote operator may control the vehicle with a wireless handset.","After his fall from the emperor''s favor, the general was posted to a remote outpost.","There was only a remote possibility that we would be rescued as we were far outside of the regular shipping lanes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explanation','n.解释，说明','/ˌɛkspləˈneɪʃən/','/ˌɛkspləˈneɪʃən/','noun',["The explanation was long and drawn-out.","An explanation for the UFO sightings was easily found."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cafeteria','n.自助餐厅','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salary','n.工资，薪水','/ˈsælɚi/','/ˈsælɚi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pretend','v.假装，装作','/pɹɪˈtɛnd/','/pɹɪˈtɛnd/','verb',["As children we used to go on \"spying\" missions around the neighbour''s house, but it was all pretend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('youth','n.青春；青年','/juθ/','/juθ/','noun',["Her youth and beauty attracted him to her.","I made many mistakes in my youth, but learned from them all.","There was a group of youths hanging around the parking lot, reading fashion magazines and listening to music."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('without','prep.没有，不','/wɪθˈʌʊt/','/wɪðˈaʊt/','adverb',["Being from a large, poor family, he learned to live without.","The snow was swirling without the cottage, but it was warm within.","It was a mistake to leave my house without a coat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drunk','adj.醉的','/dɹʌŋk/','/dɹʌŋk/','verb',["He drank the water I gave him.","Jack drank the whole bottle by himself.","Everyone who is drinking is drinking, but not everyone who is drinking is drinking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('would','modalverb.将，将会〔表示想做某事或认为某事会发生〕','/wʊd/','/wʊd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pick','v.拾起，采集；挑选','/pɪk/','/pɪk/','noun',["so many picks to an inch","Don''t pick at that scab.","It''s time to pick the tomatoes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('customs','n.海关；关税','/ˈkʌstəmz/','/ˈkʌstəmz/','noun',["Customs of £200 were due on all the wine we took back from France.","Customs has pulled us over on our way for an inspection."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calculate','v.计算，核算','/ˈkælkjəleɪt/','/ˈkælkjəleɪt/','verb',["Calculate the square root of 3 to 10 decimal places.","to calculate or cast one''s nativity","to calculate a system of laws for the government and protection of a free people"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('energy','n.精力；能量','/ˈɛnəd͡ʒi/','/ˈɛnɚd͡ʒi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audience','n.观众，听众','/ˈɔːdi.əns/','/ˈɔːdi.əns/','noun',["We joined the audience just as the lights went down.","She managed to get an audience with the Pope.","\"Private Eye\" has a small but faithful audience."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solid','adj.结实的，固体的n.固体','/ˈsɒlɪd/','/ˈsɑlɪd/','noun',["I owe him; he did me a solid last year.","I prefer solids over paisleys.","The doctor said I can''t eat any solids four hours before the operation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thus','adv.这样；因而','/ˈðʌs/','/ˈðʌs/','adverb',["If you throw the ball thus, as I’m showing you, you’ll have better luck hitting the target.","I have all the tools I need; thus, I will be able to fix the car without having to call a mechanic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meanwhile','adv.同时','/ˈmiːnhwaɪl/','/ˈmiːnhwaɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sniff','v.用力吸；嗅，闻','/snɪf/','/snɪf/','noun',["She gave the flowers a quick sniff to check they were real.","I sniffed the meat to see whether it had gone off.","\"He''s never coming back, is he?\" she sniffed while looking at a picture of him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possess','vt.占有，拥有','/pəˈzɛs/','/pəˈzɛs/','verb',["He does not even possess a working telephone.","They thought he was possessed by evil spirits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('require','vt.需求；要求','/ɹɪˈkwaɪə/','/ɹɪˈkwaɪɹ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optional','adj.可选择的；随意的','','','noun',["On that beach clothing is entirely optional."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scratch','v.抓，划破；乱涂n.乱写；抓痕','/skɹætʃ/','/skɹætʃ/','noun',["Her skin was covered with tiny scratches.","The dog sat up and had a good scratch.","There were two scratches in race 8, which reduced the field from 9 horses to 7."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('analysis','n.分析；解析','/əˈnælɪsɪs/','/əˈnælɪsɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('click','v.点击；发出滴答声n.滴答声','/klɪk/','/klɪk/','noun',["I turned the key, the lock gave a click and the door opened;  a click of one’s fingers","Visit a location, call, or click www.example.com.","From the home page, click through to the Products section."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apparent','adj.明显的，清楚的','/əˈpæ.ɹənt/','/əˈpæ.ɹənt/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('journalist','n.记者，新闻工作者','/ˈdʒɜːnəlɪst/','/ˈdʒɜːnəlɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('left','adv.向左边，在左边adj.左边的n.左，左边','/lɛft/','/lɛft/','noun',["The political left is holding too much power.","The left side.","Turn left at the corner."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dawn','n.黎明，拂晓','/doːn/','/dɔn/','noun',["She rose before dawn to meet the train.","the dawn of civilization","A new day dawns."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sideways','adj.斜向一边的','/ˈsaɪdweɪz/','/ˈsaɪdweɪz/','noun',["He gave the ball a sideways kick.","There was a stack of papers in front of each seat at the table, but each stack was sideways.","Once we get out of this sideways economy, our figures will more accurately reflect what we''re truly capable of."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('object','v.反对n.物体；目标；宾语','/ˈɒb.d͡ʒɛkt/','/ˈɑb.d͡ʒɛkt/','noun',["Mary Jane had been the object of Peter''s affection for years.","I object to the proposal to build a new airport terminal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harbour','n.港口','/ˈhɑːbə/','/ˈhɑɹbəɹ/','noun',["The neighborhood is a well-known harbor for petty thieves.","The docks, which once harbored tall ships, now harbor only petty thieves.","The fleet harbored in the south."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chapter','n.章','/ˈt͡ʃæptə/','/ˈt͡ʃæptɚ/','noun',["Detective novel writers try to keep up the suspense until the last chapter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accessible','adj.可使用的；可进入的；易接近的','','/əkˈsɛs.ə.bəl/','adjective',["an accessible town or mountain","accessible public transport"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flight','n.飞行；航班；楼梯的一段','/flaɪt/','/flaɪt/','noun',["Most birds are capable of flight.","The migrating birds'' flight took them to Africa.","a flight of swallows"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hang','v.悬挂；装饰；绞死','[heɪŋ]','[heɪŋ]','noun',["This skirt has a nice hang.","He got the hang of it after only two demonstrations.","We sometimes get system hangs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('role','n.[Ｃ]角色；作用','/ɹəʊl/','/ɹəʊl/','noun',["Her dream was to get a role in a Hollywood movie, no matter how small.","The role of women has changed significantly in the last century.","Local volunteers played an important role in cleaning the beach after the oil spill."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('independent','adj.独立的，有主见的','/ɪndɪˈpɛndənt/','/ɪndɪˈpɛndənt/','noun',["the independent candidate","an independent property","a man of an independent mind"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carriage','n.四轮马车；客车厢','/ˈkæɹɪdʒ/','/ˈkæɹɪdʒ/','noun',["The carriage ride was very romantic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defence','n.防御；防护；辩护','/dɪˈfɛns/','/dɪˈfɛns/','noun',["Department of Defence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('achieve','vt.达到，取得','/əˈtʃiːv/','','verb',["Show all the spoils by valiant kings achieved."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ahead','adv.在前，向前','/əˈhɛd/','/əˈhɛd/','adverb',["Just ahead you can see the cliffs.","There may be tough times ahead.","He paid his rent ahead."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anybody','pron.任何人，无论谁','/ˈɛn.i.bɒd.i/','/ˈɛn.i.bɑd.i/','pronoun',["Anybody will do.","Everybody who wants to be anybody will come to Jake''s party."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roll','v.滚动,打滚n.面包圈；卷状物','/ɹəʊl/','/ɹoʊl/','noun',["Look at the roll of the waves.","Hear the roll of cannon.","Calculate the roll of that aircraft."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turn','v.旋转；转变；转弯n.轮流','/tɜːn/','/tɝn/','verb',["They say they can turn the parts in two days.","We turned a pretty penny with that little scheme.","Ivory turns well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elect','vt.选举','/iːˈlɛkt/','/iːˈlɛkt/','noun',["He is the President elect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('example','n.例子，范例','/əɡˈzæmpl̩/','/əɡˈzæmpl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('result','n.结果，效果','/ɹɪˈzʌlt/','/ɹɪˈzʌlt/','noun',["the result of a course of action;  the result of a mathematical operation","This measure will result in good or in evil."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('same','adj.同样的，同一的n.同样的事','/seɪm/','/seɪm/','adjective',["Are you the same person who phoned me yesterday?","It took all night to find our hotel room, as we forgot our room number and each door looked the same.","You have the same hair I do!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('selfish','adj.自私的','/ˈsɛlfɪʃ/','/ˈsɛlfɪʃ/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('after','prep&conj&adv.在…之后，后来','/ˈæf.tə(ɹ)/','/ˈæf.tɚ/','adjective',["The after gun is abaft the forward gun.","I left the room, and the dog bounded after.","The Cold War began shortly after the Second World War."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headline','n.标题；','/ˈhɛd.laɪn/','/ˈhɛd.laɪn/','noun',["The headline on today''s newspaper reads \"John Doe Wins Wood-Splitting Competition.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('connect','vt.连接，把…联系起来','/kəˈnɛkt/','/kəˈnɛkt/','verb',["I think this piece connects to that piece over there.","Both roads have the same name, but they don''t connect: they''re on opposite sides of the river, and there''s no bridge there.","The new railroad will connect the northern part of the state to the southern part."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hand','n.手；指针vt.交付；传递','/hænd/','/hænd/','noun',["Her hands are really strong.","an old hand at speaking;  large farms need many farm hands","Bob gave Alice a hand to move the furniture."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merciful','adj.仁慈的；宽大的','/ˈmɜːsɪfl̩/','/ˈmɝsɪfl̩/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rebuild','vt.重建','/ˈɹiːbɪld/','/ˈɹiːbɪld/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sharpen','v.变锐利，削尖','','/ˈʃɑɹpɨn/','verb',["to sharpen a pencil or a knife or a musical note"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('committee','n.委员会','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('address','n.地址','/əˈdɹɛs/','/æˈdɹɛs/','noun',["He addressed some portions of his remarks to his supporters, some to his opponents.","He addressed a letter.","The ship was addressed to a merchant in Baltimore."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('union','n.联合，联盟','/ˈjuːnjən/','/ˈjuːnjən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('straight','adj&adv.直的','/stɹeɪt/','/stɹeɪt/','noun',["My friends call straights \"heteros\".","After four straight wins, Mudchester United are top of the league.","a straight Democrat"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wipe','vt.擦；扫','/waɪp/','/waɪp/','noun',["multiple wipes of a computer''s hard disk","I wiped the sweat from my brow with the back of my hand.","I accidentally wiped my hard drive."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sale','n.卖，出售','/seɪl/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('component','n.成分；零部件','/kʌmˈpoʊnənt/','/kʌmˈpoʊnənt/','noun',["A CPU is a component of a computer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suite','n.套，组；套间','/swiːt/','/swiːt/','noun',["the ambassador''s suite","a suite of minerals","The Presidential suite is well appointed and allows for good security."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consultant','n.顾问；会诊医师','/kənˈsʌltənt/','/kənˈsʌltənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outdoors','adv.户外的，野外的n.户外','','','noun',["She loves the outdoors.","They went outdoors to light up their cigarettes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('throw','v.投，掷，扔','/θɹəʊ/','/θɹoʊ/','verb',["What a great throw by the quarterback!","The gambler staked everything on one throw of the dice.","He''s always had a pretty decent throw."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obvious','adj.明显的，显而易见的','/ˈɒ.vɪəs/','/ˈɑ.vi.əs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arch','n.拱门；拱形','/ɑːt͡ʃ/','/ɑɹt͡ʃ/','noun',["to pass into the arch of a bridge","The cat arched its back"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discuss','v.讨论，议论','/dɪsˈkʊs/','/dɪsˈkʌs/','verb',["I don''t wish to discuss this further. Let''s talk about something else."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('standard','adj.标准的n.标准，规格','/ˈstændəd/','/ˈstændəɹd/','noun',["standard works in history; standard authors"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violent','adj.暴力的；猛烈的','/ˈvaɪ(ə)lənt/','/ˈvaɪ(ə)lənt/','noun',["A violent wind ripped the branch from the tree.","We would rather negotiate, but we will use violent means if necessary.","The escaped prisoners are considered extremely violent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harmony','n.协调，融洽','/ˈhɑːməni/','/ˈhɑɹməni/','noun',["a harmony of the Gospels"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correct','adj.正确的，对的；恰当的vt.改正；纠正','/kəˈɹɛkt/','/kəˈɹɛkt/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empty','adj.空的vt.倒空','/ˈɛmpti/','/ˈɛmpti/','noun',["Put the empties out to be recycled.","The cinema emptied quickly after the end of the film.","Salmon River empties on the W shore about 2 miles below Bear River."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wish','n&v.祝愿；想要','/wɪʃ/','/wɪʃ/','noun',["My dearest wish is to see them happily married.","I''ll come tomorrow, if you wish it.","We wish you a Merry Christmas."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('institution','n.公共机构；协会','/ˌɪnstɪˈtjuːʃən/','/ˌɪnstɪˈtuːʃən/','noun',["He''s been in an institution since the crash.","Over time, the local pub has become something of an institution.","The institution of higher speed limits was a popular move but increased the severity of crashes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tie','v.系，拴，扎n.关系；领带；绳子，结','/taɪ/','/taɪ/','noun',["It''s two outs in the bottom of the ninth, tie score.","the sacred ties of friendship or of duty","Ties work to maintain structural integrity in windstorms and earthquakes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wise','adj.聪明的，明智的','/waɪz/','/waɪz/','verb',["After Mo had a word with him, he wised up.","\"It is a profitable thing, if one is wise, to seem foolish\" - Aeschylus","Don''t get wise with me!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambition','n.雄心，野心','/æmˈbɪ.ʃən/','/æmˈbɪ.ʃən/','noun',["My son, John, wants to be a firefighter very much. He has a lot of ambition.","My ambition is to own a helicopter.","Pausanias, ambitioning the sovereignty of Greece, bargains with Xerxes for his daughter in marriage. — Trumbull."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tin','n.罐头','/tɪn/','/tɪn/','noun',["muffin tin"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enlarge','v.扩大，放大','/ɪnˈlɑːd͡ʒ/','/ɪnˈlɑɹd͡ʒ/','verb',["Knowledge enlarges the mind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('besides','adv.此外；再说prep.除…以外','/biˈsaɪdz/','/biˈsaɪdz/','adverb',["I don''t feel like going out tonight. Besides, I have to work tomorrow morning anyway.","I have been to Spain but nowhere besides.","I don''t want to go anywhere besides India."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('serious','adj.严肃的，严重的；认真的','/ˈsɪə.ɹi.əs/','/ˈsɪə.ɹi.əs/','adjective',["It was a surprise to see the captain, who had always seemed so serious, laugh so heartily.","This is a serious problem. We''ll need our best experts.","After all these years, we''re finally getting serious attention."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tip','vt.告诫，提示；给小费n.顶端；小费；提示','/tɪp/','/tɪp/','noun',["The shape of the nozzle prevents the use of aftermarket eartips.","a cat with an eartip","the tip of one''s nose"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('export','vi.出口vt.输出n.出口','/ˈɛks.pɔːt/','/ˈɛks.pɔːt/','noun',["Oil is the main export of Saudi Arabia.","The export of fish is forbidden in this country.","Japan exports electronic goods throughout the world."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conversation','n.谈话，交谈','/ˌkɒn.vəˈseɪ.ʃən/','/ˌkɑn.vəɹˈseɪ.ʃən/','noun',["I had an interesting conversation with Nicolas yesterday about how much he''s getting paid."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laugh','vi.笑，大笑n.笑，大笑，笑声；嘲笑','/laːf/','/læf/','noun',["His deep laughs boomed through the room.","Your new hat''s an absolute laugh, dude.","There were many laughing children running on the school grounds."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('murder','n&v.谋杀','/ˈmɜːdə(ɹ)/','/ˈmɝ.dɚ/','noun',["The defendant was charged with murder.","There have been ten unsolved murders this year alone.","This headache is murder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fantasy','n.幻想，白日梦','/ˈfæntəsi/','/ˈfæntəsi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pay','v.付钱，给…报酬n.工资','/peɪ/','/peɪ/','noun',["Many employers have rules designed to keep employees from comparing their pays.","he paid her off the books and in kind where possible","he has paid his debt to society"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('check','v.核对；检查；批改n.检查；批改','/t͡ʃɛk/','/t͡ʃɛk/','noun',["I don''t know if she will be there, but it''s worth a check.","The castle moat should hold the enemy in check.","Place a check by the things you have done."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('list','n.一览表，清单vt.列表','/lɪst/','/lɪst/','noun',["to list a door","to list a board"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strange','adj.奇怪的，奇特的；陌生的','/ˈstɹeɪnd͡ʒ/','/ˈstɹeɪnd͡ʒ/','noun',["He thought it strange that his girlfriend wore shorts in the winter.","I moved to a strange town when I was ten."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lack','n&v.缺乏，缺少','/lak/','/læk/','noun',["My life lacks excitement.","He''ll never lack for company while he''s got all that money."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toast','vt.向…敬酒；烘，烤n.烤面包，吐司；祝酒，祝酒词','/təʊst/','/toʊst/','noun',["I ate a piece of toast for breakfast.","At the reception, there were many toasts from the well-wishers.","He was the toast of high society."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aside','adv.在旁边','/əˈsaɪd/','/əˈsaɪd/','noun',["Move aside, please, so that these people can come through."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circumstance','n.环境；情况','/-æns/','/ˈsɝ.kəm.ˌstæns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('success','n.成功，成就；成功的人','/səkˈsɛs/','/səkˈsɛs/','noun',["His third attempt to pass the entrance exam was a success.","Don''t let success go to your head.","Scholastically, he was a success."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brunch','n.早午饭','/bɹʌntʃ/','/bɹʌntʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('authority','n.权威；当局','/ɔːˈθɒɹəti/','/əˈθɑɹəti/','noun',["I have the authority to penalise the staff in my department, but not the authority to sack them.","the world''s foremost authority on orangutans"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creature','n.生物；动物','/ˈkɹiːt͡ʃə/','/ˈkɹiːt͡ʃəɹ/','noun',["He''s a creature of habit.   insects and other creatures"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outgoing','adj.好交际的，外向的；即将离职的','','','verb',["Tom is very outgoing and enjoys meeting people; his brother, on the other hand, is painfully shy.","Is there any outgoing post?","The outgoing politician wasn''t too disappointed he''d lost the election; he was tired of political infighting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tasteless','adj.无滋味的','','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harm','n&vt.伤害，损伤','/hɑːm/','/hɑɹm/','noun',["No harm came to my possessions.","Although not physically injured in the car accident, she received some psychological harm.","I wish him no harm."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instrument','n.乐器；工具，器械','/ˈɪnstɹəmənt/','/ˈɪnstɹəmənt/','noun',["The violinist was a master of her instrument.","The instrument detected an increase in radioactivity.","The dentist set down his tray of instruments."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medium','adj.中间的，中等的n.媒介','/ˈmiːdɪəm/','/ˈmiːdɪəm/','noun',["Acrylics, oils, charcoal, and gouache are all mediums I used in my painting.","a happy medium"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remove','vt.移动，拿走；去除','/ɹɪˈmuːv/','/ɹɪˈmuːv/','noun',["He removed the marbles from the bag.","The President removed many postmasters."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wisdom','n.智慧','/ˈwɪzdəm/','/ˈwɪzdəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('starvation','n.饥饿；饿死','/stɑːˈveɪʃən/','/stɑːˈveɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nowhere','adv.任何地方都不；无处','/ˈnəʊ.wɛə/','/ˈnoʊ.(h)wɛɹ/','noun',["They went on a cruise to nowhere.","Nowhere did the rules say anything about popcorn.","We sat in traffic, going nowhere."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('psychology','n.心理学','/saɪˈkɒlədʒɪ/','/saɪˈkɑlədʒi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrestle','v.摔跤，格斗；斟酌','/ˈɹɛ.səl/','/ˈɹɛ.səl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treasure','n.金银财宝，财富','/ˈtɹɛʒə/','/ˈtɹɛʒɚ/','noun',["Oh, this ring is beautiful! I’ll treasure it forever."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('multiply','v.相乘；增加','/ˈmʌltɪplaɪ/','/ˈmʌltɪplaɪ/','noun',["when you multiply 3 by 7, you get 21;  he multiplied several numbers","He had been multiplying, but it occurred to him he needed to resolve the exponents, first."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('live','vi.生活，居住adj.活的；直播的vt.过着，经历','/lɪv/','/lɪv/','verb',["He''s not expected to live for more than a few months.","I live at 2a Acacia Avenue.  He lives in LA, but he''s staying here over the summer.","Her memory lives in that song."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approval','n.赞成；认可；批准','/əˈpɹuːvəl/','/əˈpɹuvəl/','noun',["I need to get an approval on this purchase order.","Words of approval never seem to come from him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('victory','n.[C]胜利','/ˈvɪkt(ə)ɹi/','/ˈvɪkt(ə)ɹi/','noun',["It was a great victory on the battlefield."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mobile','adj.活动的，可移动的','/ˈməʊbaɪl/','/ˈməʊbaɪl/','noun',["there are many business opportunities in mobile","a mobile home","mobile internet"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perform','v.表演，表现；履行','/pəˈfɔːm/','/pɚˈfɔɹm/','verb',["It took him only twenty minutes to perform the task.","She will perform in the play."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evolution','n.进展，演变，进化','/ˈɛvəluːʃ(ə)n/','/ˌivə-/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expose','vt.暴露；揭露','/ɪkˈspəʊz/','/ɛkˈspoʊz/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concentrate','v.集中，聚集','/ˈkɒn.sən.tɹeɪt/','/ˈkɒn.sən.tɹeɪt/','noun',["to concentrate rays of light into a focus","to concentrate acid by evaporation","Population tends to concentrate in cities."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheer','n&v.欢呼，喝彩','/t͡ʃɪə(ɹ)/','/t͡ʃɪɹ/','noun',["a table loaded with good cheer","A cheer rose from the crowd.","We were cheered by the offer of a cup of tea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('with','prep.与，伴随；有，以','','','adverb',["Do you want to come with?","He picked a fight with the class bully.","He went with his friends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('there','adv.在那里int.那！你瞧！','/ðɛə(ɹ)/','/ðɛəɹ/','noun',["You rinse and de-string the green beans; I''ll take it from there.","He did not stop there, but continued his speech.","Is there an answer?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permit','v.许可，允许n.许可证，执照','','','noun',["A construction permit can be obtained from the town offices.","The Building Department permitted that project last week.","We''ve been busy permitting the State Street development."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('well','adv.好，充分地adj.健康的int.好吧n.井','/wɛl/','/wɛl/','adjective',["I had been sick, but now I''m well.","“How are you?” — “I''m well, thank you!”","He does his job well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suitable','adj.合适的，适宜的','/ˈsuːtəbl/','/ˈsuːtəbl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personnel','n.人员，职员','/-el/','/pɝ.səˈnɛl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hopeless','adj.没有希望的；不可救药的','/ˈhəʊplɪs/','/ˈhoʊplɪs/','adjective',["a hopeless cause","He''s a hopeless writer, but can draw very well.","He is a hopeless idler."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freeway','n.高速公路','/ˈfɹiː.wei/','/ˈfɹiː.wei/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fountain','n.喷泉；源泉','[ˈfaʊn.ʔn̩]','[ˈfaʊn.ʔn̩]','noun',["Lava fountained from the volcano."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pile','v.堆积，积累n.堆','/paɪl/','/paɪl/','noun',["When we were looking for a new housemate, we put the nice woman on the \"maybe\" pile, and the annoying guy on the \"no\" pile","a pile of shot","He made a pile from that invention of his."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('channel','n.海峡；频道；通道','/ˈtʃænəl/','/ˈtʃænəl/','noun',["The water coming out of the waterwheel created a standing wave in the channel.","A channel was dredged to allow ocean-going vessels to reach the city.","We were careful to keep our boat in the channel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunburnt','adj.晒黑的，晒伤的','','','adjective',["The van was painted a sunburnt brown."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('focus','v.聚焦，集中n.中心，焦点','/ˈfəʊ.kəs/','/ˈfəʊ.kəs/','noun',["The heat of sunlight at the focus of a magnifying glass can easily set dry leaves on fire.","Unfortunately, the license plate is out of focus in this image.","During this scene, the boy’s face shifts subtly from soft focus into sharp focus."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entire','adj.整个的，全部的','/ənˈtaɪə/','/ənˈtaɪɚ/','noun',["We had the entire building to ourselves for the evening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approach','v.接近，靠近n.方式，方法','/əˈpɹəʊt͡ʃ/','/əˈpɹoʊt͡ʃ/','noun',["1991, Carol Lee Johnston, Jeanne Lazaris, Plane Trigonometry, A New Approach.","as he approaches to the character of the ablest statesman.","\"Would counsel please approach the bench?\" asked the judge."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrist','n.手腕，腕关节','/ɹɪst/','/ɹɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('experiment','n.实验','/ɛk.ˈspɛ.ɹɪ.mənt/','/ɪk.ˈspɛɹ.ə.mənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fierce','adj.猛烈的，激烈的','/fɪəs/','/fɪɹs/','adjective',["A fierce storm battered the coast.","We made a fierce attempt to escape.","The lion gave a fierce roar."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reservation','n.预订；预约','/ˌɹɛzəˈveɪʃən/','/ˌɹɛzəˈveɪʃən/','noun',["The committee authorised the reservation of funds.","I have reservations about your intentions.","I have a hotel reservation in the name of Mr Smith."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('e-mail','n.电子邮件vt.给…发电子邮件','/ˈiːmeɪl/','/ˈiːmeɪl/','noun',["He sent me his details via email.","I am searching through my old email.","He sent me an email last week to remind me about the meeting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hate','vt.恨，讨厌，不喜欢n.怨恨','/heɪt/','/heɪt/','noun',["One of my pet hates is traffic wardens.","He gave me a look filled with pure hate.","Do not fear; he who fears hates; he who hates kills. — attributed to Gandhi"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('block','v.阻塞，阻挡n.大块；街区','/blɒk/','/blɑk/','noun',["a block of ice","Anne Boleyn placed her head on the block and awaited her execution.","I''m going for a walk around the block."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('write','v.写','/ɹaɪt/','/ɹaɪt/','noun',["How many writes per second can this hard disk handle?","The pupil wrote his name on the paper.","My uncle writes newspaper articles for The Herald."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pet','n.宠物，爱畜','/pɛt/','/pɛt/','noun',["His daughter was petted and spoiled.","The professor seemed offended by the criticism of her pet theory.","pet rock"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flow','v.流动n.流，流动','/fləʊ/','/floʊ/','noun',["The notion of flow is basic to the study of ordinary differential equations.","The room was small, but it had good symmetry and flow.","Other devices measure water flow in streams fed by melted ice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('order','n.顺序；命令vt.命令；点菜；订货','/ˈɔːdə/','/ˈɔɹdɚ/','noun',["The house is in order; the machinery is out of order.","to preserve order in a community or an assembly","St. Ignatius Loyola founded the Jesuit order in 1537."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wage','n.工资，报酬','/weɪd͡ʒ/','/weɪd͡ʒ/','noun',["Before her promotion, her wages were 20% less."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('period','n.时期，时代','/ˈpɪəɹɪəd/','/ˈpɪəɹɪəd/','noun',["There was a period of confusion following the announcement.","Food rationing continued in the post-war period.","When she is on her period, she prefers not to go swimming."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('musical','adj.音乐的，爱好音乐的n.音乐剧','/ˈmju.zɪ.kəl/','/ˈmju.zɪ.kəl/','noun',["musical proportion; musical instruments","She had a musical voice.","the child is musical; having a musical ear"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corporation','n.团体；公司，企业','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distant','adj.远的，遥远的','/ˈdɪstənt/','','adjective',["We heard a distant rumbling but didn''t pay any more attention to it.   She was surprised to find that her fiancé was a distant relative of hers.   His distant look showed that he was not listening to me.","Ever since our argument, she has been totally distant toward me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('understand','v.懂得，理解','/(ˌ)ʌndəˈstænd/','/ˌʌndɚˈstænd/','verb',["I''m sorry. I don''t understand.","I understand that you have a package for me?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dismiss','v.解雇；解散','/dɪsˈmɪs/','/dɪsˈmɪs/','verb',["The company dismissed me after less than a year.","The soldiers were dismissed after the parade.","He dismissed all thoughts of acting again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intelligence','n.智力，聪明','/ɪnˈtɛl.ɪ.d͡ʒəns/','/ɪnˈtɛl.ɪ.d͡ʒəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reform','v.改革，革新n.改革；改善','/ɹɪˈfɔːm/','/ɹəˈfɔɹm/','noun',["A major reform is needed to improve the efficiency in the factory.","1909, H. G. Wells, The History of Mr. Polly Chapter 9","It is hoped that many criminals, upon being freed, will eventually reform."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ever','adv.曾经；无论何时','/ˈɛvə/','/ˈɛvɚ/','adjective',["It was ever thus.","He''s back and better than ever.","How can I ever get there in time?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('even','adv.甚至，更加，还要adj.平坦的','/ˈiːvən/','/ˈivn̩/','noun',["So let''s see. There are two evens here and three odds.","We need to even this playing field; the west goal is too low.","Thrice nine evens twenty seven."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restriction','n.限制','/ɹɪˈstɹɪkʃən/','/ɹɪˈstɹɪkʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crazy','adj.疯狂的','/ˈkɹeɪzi/','/ˈkɹeɪzi/','noun',["His ideas were both frightening and crazy.","When she gets on the motorcycle she goes crazy.","He went crazy when he won."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('razor','n.剃须刀','/ˈɹeɪzə/','/ˈɹeɪzə/','noun',["Occam''s razor, Hanlon''s razor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coach','v.指导，训练n.教练；马车；长途车','/kəʊtʃ/','/koʊtʃ/','noun',["John flew coach to Vienna, but first-class back home.","She has coached many opera stars."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('champion','n.冠军，优胜者','/ˈtʃæmpiən/','/ˈtʃæmpiən/','noun',["The defending champion is expected to defeat his challenger.","Barcelona is eligible to play in FIFA Club World Cup as the champion of Europe.","champion of women''s suffrage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wait','v.等待n.等待，等候','/weɪt/','/weɪt/','noun',["I had a very long wait at the airport security check.","They lay in wait for the patrol.","Wait here until your car arrives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circuit','n.电路','[ˈsəɾ.kɪʈ]','[ˈsɝ.kət]','noun',["Having circuited the air."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pint','n.品脱；一品脱啤酒','/paɪnt/','/paɪnt/','noun',["Please leave three pints tomorrow, milkman."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('matter','vi.要紧，有重大关系n.事情，物质；原因','/ˈmætə/','/ˈmætɚ/','noun',["What''s the matter?;   state matters","I stayed for a matter of months.","Sorry for pouring ketchup on your clean white shirt! - Oh, don''t worry, it does not matter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instant','adj.立即的；速食的n.瞬间','/ˈɪnstənt/','/ˈɪnstənt/','noun',["She paused for only an instant, which was just enough time for John to change the subject.","The instant the alarm went off, he fled the building."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personalization','n.个性化','/ˌpɜːs(ə)nəlaɪˈzeɪʃən/','/ˌpɜːs(ə)nəlaɪˈzeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shaver','n.电动剃须刀','/ˈʃeɪvə/','/ˈʃeɪvə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('top','n.顶部；上面','/tɒp/','/tɑp/','noun',["His kite got caught at the top of the tree.","The boy was amazed at how long the top would spin.","I prefer being a top, and my boyfriend prefers being a bottom."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('native','adj.本土的，本国的','/ˈneɪtɪv/','/ˈneɪtəv/','noun',["English is not my native language.","The native peoples of Australia are called aborigines.","Many native artists studied abroad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('too','adv.也；又；太；很','/tuː/','/tu/','adverb',["There has been a cutback in federal subsidies. Too, rates have been increasing.","She doesn''t talk too much.  I''m not too sure about this.","\"You''re not old enough yet.\"  \"I am, too!\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('have','v.帮助构成完成时态vt.有，使，令','','','noun',["I have a house and a car.","Do you have the key? (not necessarily one''s own key)","I have a really mean boss."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violence','n.暴力；强烈','/ˈvaɪləns/','/ˈvaɪləns/','noun',["The violence of the storm, fortunately, was more awesome than destructive.","We try to avoid violence in resolving conflicts.","Violence between the government and the rebels continues."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roast','v.烤','/ɹəʊst/','/ɹoʊst/','noun',["Dark roast means that the coffee bean has been roasted to a higher temperature and for a longer period of time than in light roast.","to roast meat on a spit","to roast a potato in ashes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('energetic','adj.精力旺盛的','/ˌɛnəˈdʒɛtɪk/','/ˌɛnɚˈdʒɛtɪk/','adjective',["Cosmic rays are energetic particles from outer space.","Those kids are so energetic: they want to run around playing all day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consequence','n.结果，后果','/ˈkɒnsɪkwɛns/','/ˈkɑnsɪkwəns/','noun',["I''m warning you. If you don''t get me the report on time, there will be consequences."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quilt','n.加衬芯床罩','/kwɪlt/','/kwɪlt/','noun',["My grandmother is going to sew a quilt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('famous','adj.著名的，出名的','/ˈfeɪməs/','/ˈfeɪməs/','verb',["Some people are only famous within their city."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('question','vt.询问n.问题','/ˈkwɛstjən/','/ˈkwɛstjən/','noun',["What is your question?","The question of seniority will be discussed at the meeting.","He obeyed without question."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vinegar','n.醋','/ˈvɪnəɡə/','/ˈvɪnəɡɚ/','noun',["a range of herb-flavoured vinegars"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spirit','n.精神，灵魂','/ˈspɪɹɪt/','/ˈspiɹɪt/','noun',["A wandering spirit haunts the island.","School spirit is at an all-time high.","In the spirit of forgiveness, we didn''t press charges."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('premier','n.总理，首相','/ˈpɹemjə/','/ˈpɹemjə/','noun',["The composer invited all his friends when they premiered the movie he orchestrated, we got to see it before anyone but the crew."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('produce','v.生产，制造','/pɹəˈdjuːs/','/pɹəˈdjuːs/','verb',["to produce a side of a triangle","to produce a man''s life to threescore","highly produced sound"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allergic','adj.过敏的','[ə.ˈlɜː.dʒɪk]','[ə.ˈlɜː.dʒɪk]','noun',["I am allergic to cats."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheat','v.哄骗，欺骗，骗取n.骗子；诈骗','/tʃiːt/','/tʃiːt/','verb',["My brother flunked biology because he cheated on his mid-term.","After he found out his wife cheated, he left her.","He cheated death when his car collided with a moving train."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('framework','n.框架，结构','/ˈfɹeɪm.wɜːk/','/ˈfɹeɪm.wɜːk/','noun',["These ‘three principles of connexion’ compose the framework of principles in Hume''s account of the association of ideas."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regard','v.当做，看待n.关心，注意；致意','/ɹɪˈɡɑːd/','/ɹɪˈɡɑɹd/','noun',["He is held in great regard in Whitehall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anecdote','n.轶事；趣事','/ˈæ.nɪk.doʊt/','/ˈæ.nɪk.doʊt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prohibit','vt.禁止，阻止','/pɹəʊˈhɪbɪt/','/pɹoʊˈhɪbɪt/','verb',["The restaurant prohibits smoking on the patio."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('almost','adv.几乎，差不多','/ɔːl.ˈməʊst/','/ˈɑl.moʊst/','noun',["In all the submissions, they found four papers that were clearly worth publishing and another dozen almosts.","Almost all people went there. - Not all but very close to it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steward','n.男乘务员','/ˈstjuː.əd/','/ˈstuɚd/','noun',["a steward in a Methodist church"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fuel','n.燃料','/ˈfjuːl/','/ˈfjuːl/','noun',["His books were fuel for the revolution."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manner','n.方式；举止；','/ˈmænə/','/ˈmænɚ/','noun',["His natural manner makes him seem like the boss.","These people have strange manners.","It is in a manner done already."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upon','prep.在…上面','/əˈpɒn/','/əˈpɑn/','adverb',["He was set upon by the agitated dogs","Place the book upon the table.","She balanced upon one foot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foresee','vt.预见，预知','/fɔːˈsiː/','/fɔɹˈsi/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harmful','adj.有害的；致伤的','/ˈhɑːmfl̩/','/ˈhɑɹmfl̩/','adjective',["Wear a hat to protect your skin from harmful sunlight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('associate','v.结合；结交','/əˈsəʊsi.ət/','/əˈsoʊsi.ət/','noun',["She associates with her coworkers on weekends.","He associated his name with many environmental causes.","particles of gold associated with other substances"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pray','v.祈祷，祈求','/pɹeɪ/','/pɹeɪ/','verb',["Muslims pray in the direction of Mecca.","pray silence for…"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wake','v.醒来，叫醒','/ˈweɪk/','/ˈweɪk/','noun',["I woke up at four o''clock this morning.","The neighbour''s car alarm woke me from a strange dream.","Command unto the guards that they diligently wake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pin','vt.钉住，别住n.别针；胸针','/pɪn/','/pɪn/','noun',["Pull the pin out of the grenade before throwing it at the enemy.","I''m not so good on my pins these days.","The UK standard connector for domestic mains electricity has three pins."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('academic','adj.学术的；院校的n.大学教师；学者','/ˌækəˈdɛmɪk/','/ˌækəˈdɛmɪk/','noun',["the academic sect or philosophy","I have always had an academic interest in hacking.","I''m more academic than athletic — I get lower marks in phys. ed. than in anything else."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whether','conj.是否','/ˈwɛðə(ɹ)/','/ˈwɛðə(ɹ)/','pronoun',["He chose the correct answer, but I don''t know whether it was by luck or (whether it was) by skill.","Do you know whether he''s coming?","He''s coming, whether you like it or not."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('function','vi.起作用；行使职责n.功能，作用，职责；函数','/ˈfʌŋ(k)ʃən/','/ˈfʌŋkʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('raise','vt.举起；提高，使升高；饲养，养育','/ɹeɪz/','/ɹeɪz/','noun',["The boss gave me a raise.","to raise your hand if you want to say something; to raise your walking stick to defend yourself","We need to raise the motivation level in the company."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoon','n.勺，匙，调羹','/spuːn/','/spun/','noun',["Sarah spooned some apple sauce onto her plate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quite','adv.完全，十分','/kwaɪt/','/kwaɪt/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lap','n.大腿；一圈','/læp/','/læp/','noun',["The boy was sitting on his mother''s lap."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mineral','n.矿物质，矿物','/ˈmɪ.nəɹ.əl/','/ˈmɪ.nəɹ.əl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('representative','n.代表','/ˌɹɛpɹɪˈzɛnt(ət)ɪv/','/ˌɹɛpɹɪˈzɛnt(ət)ɪv/','noun',["Are you sure this paper is representative of your child''s writing?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terror','n.恐怖；可怕的人','/ˈtɛɹə/','/ˈtɛɚ/','noun',["a terror attack; the War on Terror"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beneath','prep.在…下方，在…下面','/bɪˈniːθ/','/bɪˈniːθ/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everyone','pron.每人，人人','/ˈɛv.ɹi.wʌn/','/ˈɛv.ɹi.wʌn/','pronoun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lay','v.放，搁；产','/leɪ/','/leɪ/','noun',["the lay of the land","Worm and parcel with the lay; turn and serve the other way.","What was I, just another lay you can toss aside as you go on to your next conquest?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swap','v.交换','/swɒp/','/swɒp/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hatch','v.孵蛋','/hætʃ/','/hætʃ/','noun',["The cook passed the dishes through the serving hatch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pardon','vt&n.原谅，宽恕；对不起','/ˈpɑɹ.dən/','/ˈpɑɹ.dn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plenty','n.充足，大量，丰富','/ˈplɛnti/','/ˈplɛnti/','noun',["We are lucky to live in a land of peace and plenty.","She was plenty mad at him.","I think six eggs should be plenty for this recipe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tick','v.发出滴答声n.钟表的滴答声；记号','/tɪk/','/tɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basis','n.[C]基础；根据；原则','/ˈbeɪsɪs/','/ˈbeɪsɪs/','noun',["Cars must be checked on a yearly basis.","The collection of all possible unions of basis elements of a basis is said to be the topology generated by that basis."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adventure','n.冒险；奇遇','/ædˈvɛnt͡ʃɚ/','/ædˈvɛnt͡ʃɚ/','noun',["A life full of adventures.","his sense of adventure"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condition','n.条件，状况','/kənˈdɪʃən/','/kənˈdɪʃən/','noun',["Environmental protection is a condition for sustainability.   What other planets might have the right conditions for life?   The union had a dispute over sick time and other conditions of employment.","My aunt couldn''t walk up the stairs in her condition.","National reports on the condition of public education are dismal.   The condition of man can be classified as civilized or uncivilized."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('improve','v.改进，更新','/ɪmˈpɹuːv/','/ɪmˈpɹuːv/','verb',["Buying more servers would improve performance.","I have improved since taking the tablets.","to improve negligence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ceremony','n.典礼，仪式','/ˈsɛɹɪməni/','/ˈsɛɹəmoʊni/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bingo','n.宾果','/ˈbɪŋ.ɡəʊ/','/ˈbɪŋ.ɡoʊ/','noun',["There were two bingos in the last game, so the players split the prize money."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('try','v.尝试，试图；努力','/tɹaɪ/','/tɹaɪ/','noun',["I gave unicycling a try but I couldn’t do it.","I gave sushi a try but I didn’t like it.","Today I scored my first try."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gym','n.体育馆；健身房','/dʒɪm/','/dʒɪm/','noun',["On Wednesdays I hike; on Fridays I gym.","Gymnastics was a significant part of the physical education curriculum.","His mental gymnastics are legendary."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basic','adj.基本的n.要素；基础','/ˈbeɪsɪk/','/ˈbeɪsɪk/','noun',["Rice is a basic for many Asian villagers.","Arithmetic is a basic for the study of mathematics.","The drill sergeants gave him hell in basic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twist','v.拧，扭曲n.扭曲，歪曲','/twɪst/','/twɪst/','noun',["Damascus twist","a twist toward fanaticism","Avarice twists itself into all human concerns."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unite','v.联合，团结','/juˈnaɪt/','/juˈnaɪt/','noun',["I hope this song can unite people from all different cultures.","If we want to win, we will need to unite."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bush','n.灌木丛，矮树丛','/bʊʃ/','/bʊʃ/','noun',["bushes to support pea vines","to bush peas","to bush a piece of land; to bush seeds into the ground"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technique','n.技术，技巧','/tɛkˈniːk/','/tɛkˈniːk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cause','n.原因，起因vt.促使，引起','/kɔːz/','/kɔz/','noun',["They identified a burst pipe as the cause of the flooding.","The end of the war was a cause for celebration.","The lightning caused thunder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dioxide','n.二氧化物','/daɪˈɒksaɪd/','/daɪˈɒksaɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wound','vt.伤，使受伤；伤害n.[Ｃ]创伤；伤口','/wuːnd/','/wund/','noun',["It took a long time to get over the wound of that insult.","The police officer wounded the suspect during the fight that ensued.","The actor''s pride was wounded when the leading role went to his rival."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catastrophe','n.灾难；灾祸；横祸','/kəˈtæstɹəfi/','/kəˈtæstɹəfi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('busy','adj.忙碌的','/ˈbɪzi/','/ˈbɪzi/','noun',["On my vacation I''ll busy myself with gardening.","We crossed a busy street.","He is busy with piano practice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convey','vt.搬运；传播，传达','/kənˈveɪ/','/kənˈveɪ/','verb',["Air conveys sound. Water is conveyed through the pipe.","to convey an impression; to convey information","He conveyed ownership of the company to his daughter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extra','adj.额外的，外加的','/ˈɛkstɹə/','/ˈɛkstɹə/','noun',["Extra, extra! Read all about it!","I don''t mind doing some extra work, as long as I get extra pay.","You unfollowed her for posting cat memes? You''re so extra!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('design','v.设计；制订；筹划n.样式','/dɪˈzaɪn/','/dɪˈzaɪn/','noun',["To be hateful of the truth by design.","Danish furniture design is world-famous.","The king designed to mount an expedition to the New World."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generous','adj.慷慨的，大方的','/ˈdʒɛn(ə)ɹəs/','/ˈdʒɛn(ə)ɹəs/','adjective',["Thank you for your generous words.","She''s been extremely generous with her winnings.","Add a generous helping of mayonnaise."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('land','v.登陆；降落n.陆地','/lænd/','/lænd/','noun',["Most insects live on land.","There are 50 acres of land in this estate.","wet land; good or bad land for growing potatoes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coincidence','n.一致；巧合','/kəʊˈɪnsɪdəns/','/koʊˈɪnsɪdəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('victim','n.受害人，牺牲品','/ˈvɪktəm/','/ˈvɪktəm/','noun',["the youngest victims of the brutal war"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('department','n.部门；系','/dɪˈpɑːtm(ə)nt/','/dəˈpɑɹtmənt/','noun',["Technical things are not his department; he''s a people person.","the Department of the Potomac"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possibility','n.可能，可能性','/ˌpɒsɪˈbɪliti/','/ˌpɑsɪˈbɪliti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('direction','n.方向；说明；说明书；指导','/d(a)ɪˈɹɛk.ʃən/','/d(a)ɪˈɹɛk.ʃən/','noun',["Keep going in the same direction.","The trombonist looked to the bandleader for direction.","The screenplay was good, but the direction was weak."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhibition','n.展览，展览会；展品','/ɛksɪˈbɪʃən/','/ɛksɪˈbɪʃən/','noun',["There was an art exhibition on in the town hall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burn','v.燃，烧，着火；使烧焦；','/bɜːn/','/bɝn/','noun',["She had second-degree burns from falling in the bonfire.","chili burn from eating hot peppers","They''re doing a controlled burn of the fields."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garlic','n.大蒜','/ˈɡɑːlɪk/','/ˈɡɑːlɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alcoholic','adj.酒精的；酒精中毒的n.饮酒过度的人','/ˌælkəˈhɒlɪk/','/ˌælkəˈhɔlɪk/','noun',["He ordered an alcoholic beverage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bachelor','n.学士；单身汉','/ˈbætʃ.ə.lə(ɹ)/','/ˈbætʃ.lɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('countryside','n.乡下，农村','/ˈkʌn.tɹiˌsaɪd/','/ˈkʌn.tɹiˌsaɪd/','noun',["We live in the Swedish countryside."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chief','adj.主要的，首要的n.领导','/tʃiːf/','/tʃiːf/','noun',["All firefighters report to the fire chief.","Hey, chief.","Negligence was the chief cause of the disaster."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('automatic','adj.自动的，机械的','/ˌɔːtəˈmætɪk/','/ˌɔtəˈmætɪk/','noun',["I never learned to drive a stick. I can only drive an automatic.","The G-men raiding the speakeasy were equipped with .45 automatics, while the local policemen were carrying revolvers and shotguns.","The automatic clothes washer was a great labor-saving device."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lamp','n.灯，油灯；光源','/læmp/','/læmp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cry','v.喊叫；哭n.喊；哭声','/kɹaɪ̯/','/kɹaɪ̯/','noun',["After we broke up, I retreated to my room for a good cry.","I heard a cry from afar.","a battle cry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Antarctic','adj.南极的n.南极地区','/ænˈtɑːktɪk/','/ænˈtɑːktɪk/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conduct','vt.引导；管理','/kənˈdʌkt/','/ˈkɒndʌkt/','noun',["Good conduct will be rewarded and likewise poor conduct will be punished.","The commander conducted thousands of troops.","He conducted himself well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bury','vt.埋，葬','/ˈbʌ.ɹi/','/ˈbɛ.ɹi/','noun',["bury a bone;  bury the embers","she buried her face in the pillow;  they buried us in paperwork","secrets kept buried; she buried her shame and put on a smiling face."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obey','v.服从，顺从','/əʊˈbeɪ/','/oʊˈbeɪ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stable','adj.稳定的','/ˈsteɪ.bəɫ/','/ˈsteɪ.bəɫ/','noun',["There were stalls for fourteen horses in the squire''s stables."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lamb','n.羔羊；羔羊肉','/læm/','/læm/','noun',["The shepherd was up all night, lambing her young ewes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fantastic','adj.极好的，美妙的，很棒的','/fænˈtæstɪk/','/fænˈtæstɪk/','noun',["He told fantastic stories of dragons and goblins.","She entered the lab and stood gaping for a good ten minutes at the fantastic machinery at work all around her.","\"I had a simply fantastic vacation, and I can''t wait to tell you all about it!\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('changeable','adj.易变的，变化无常的','/ˈt͡ʃeɪnd͡ʒəbəl/','/ˈt͡ʃeɪnd͡ʒəbəl/','adjective',["The weather is very changeable today: we''ve had bright sunshine, clouds, wind and rain in the same half-hour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoken','adj.口语的','/ˈspoʊkən/','/ˈspoʊkən/','verb',["I was so surprised I couldn''t speak.","It''s been ages since we''ve spoken.","Actions speak louder than words."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respond','v.回答；做出反应','','','noun',["to respond to a question or an argument","The prisoner was held to respond the judgment of the court."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incident','n.事件','/ˈɪn.sɪ.dənt/','/ˈɪn.sɪ.dənt/','noun',["It was an incident that he hoped to forget.","The incident light illuminated the surface."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('walk','v.走路，步行n.散步','/wɔːk/','/wɔk/','verb',["To walk briskly for an hour every day is to keep fit.","If you can’t present a better case, that robber is going to walk.","If you leave your wallet lying around, it’s going to walk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lame','adj.跛的；残废的','/leɪm/','/leɪm/','noun',["1877, Anna Sewell, Black Beauty: And if you don''t want to lame your horse you must look sharp and get them stones stuck in hooves out quickly.","a lame leg, arm or muscle","He had a really lame excuse for missing the birthday party."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marry','v.和…结婚','/ˈmæɹɪ/','/ˈmeɹi/','verb',["Neither of her daughters showed any desire to marry.","His daughter was married some five years ago to a tailor''s apprentice.","He was eager to marry his daughter to a nobleman."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pity','n.怜悯，同情；憾事','/ˈpɪti/','/ˈpɪti/','noun',["I can''t feel any pity towards the gang, who got injured while attempting to break into a flat.","It''s a pity you''re feeling unwell because there''s a party on tonight.","You have got to pity the guy - he lost his wife, mother and job in the same month."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absorb','vt.吸收；吸引','/əbˈsɔːb/','/æbˈsɔɹb/','verb',["Heat, light, and electricity are absorbed in the substances into which they pass."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supply','v.供给，提供n.供给；供应品','/səˈplaɪ/','/səˈplaɪ/','noun',["supply and demand","A supply of good drinking water is essential.","to vote supplies"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uncertain','adj.不确定的','/ʌnˈsɜːtən/','/ʌnˈsɜːtən/','noun',["Tomorrow''s weather is uncertain."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concern','n.关系；关心vt.涉及，关系到','/kənˈsɜːn/','/kənˈsɝn/','noun',["Judy''s eyes filled with concern as she listened to the news report.","The employees’ attitude is really hurting the concern.","A good prince concerns himself in the happiness of his subjects."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circulate','vt.使流通；使运行','/ˈsɚˌkju.leɪt/','/ˈsɚˌkju.leɪt/','verb',["to circulate money or gossip"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liberty','n.自由','/ˈlɪbɚti/','/ˈlɪbɚti/','noun',["The army is here, your liberty is assured.","The prisoners gained their liberty from an underground tunnel.","Everyone has the right to life, liberty and security of person."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recycle','v.再循环，回收','/ɹiˈsaɪkəl/','/ɹiˈsaɪkəl/','noun',["Both paper and plastic can be recycled.","Sulfur recycles in the sulfur cycle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('let','vt.让','/lɛt/','/lɛt/','noun',["After he knocked for hours, I decided to let him come in.","Let me alone!","The physicians let about a pint of his blood, but to no avail."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('state','n.状态；国家；州vt.宣称','/steɪt/','/steɪt/','noun',["He stated that he was willing to help.","State your intentions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('press','vt.压，按n.压，按；新闻界，出版社','/pɹɛs/','/pɹɛs/','noun',["a flower press","Stop the presses!","This article appeared in the press."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('welcome','n&vt&adj.欢迎','/ˈwɛlkəm/','/ˈwɛlkəm/','noun',["We entered the house and found a ready welcome.","We welcome suggestions for improvement.","Refugees welcome in London!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confidential','adj.极受信任的；秘密的','/ˌkɑːnfɪˈdɛnʃl/','/ˌkɑːnfɪˈdɛnʃl/','adjective',["The newspaper claims a leaked confidential report by the government admits to problems with corrupt MPs.","Sitting in front of the fire, they became quite confidential, and began to gossip.","a confidential agent; a confidential servant; a confidential whisper"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chaos','n.混乱','/ˈkeɪ.ɒs/','/ˈkeɪ.ɑs/','noun',["After the earthquake, the local hospital was in chaos"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abundant','adj.丰富的，充裕的','/əˈbʌn.dn̩t/','/əˈbn̩.dn̩t/','adjective',["With their magical words they poets bring forth to our eyesight the abundant images and beauties of creation. — Leigh Hunt, On the Realities of Imagination","Abundant in goodness and truth. — Exodus, 34:6"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('want','v.想要，需要','/wɒnt/','/wɑnt/','noun',["What do you want to eat?  I want you to leave.  I never wanted to go back to live with my mother.","Danish police want him for embezzlement.","You can leave if you want."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pace','n.步子，步速；节奏','/peɪs/','/peɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ballet','n.芭蕾舞，芭蕾舞剧','/bælæe/','/bæˈleɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opposite','adj.相反的，对面的n.相反，对面；对立面，对立物','/ˈɒpəsɪt/','/ˈɑp(ə)sɪt/','noun',["\"Up\" is the opposite of \"down\".","She saw him walking on the opposite side of the road.","They were moving in opposite directions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forecast','n.预知vt.预告，预测','/ˈfɔːkɑːst/','/ˈfɔɹkæst/','noun',["to forecast a rise in prices"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recognize','vt.认出；承认','/ˈɹɛkənaɪz/','/ˈɹɛkənaɪz/','verb',["I recognised his face immediately.","The US and a number of EU countries are expected to recognize Kosovo on Monday.","I recognize that my behaviour has been unacceptable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warehouse','n.仓库；大商店','','','noun',["the warehousing of syndicated TV shows"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pack','v.包装，整理n.包，背包；一群','/pæk/','/pæk/','noun',["The horses carried the packs across the plain.","a pack of complaints","We were going to play cards, but nobody brought a pack."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('each','adj&pron.每人，每个，每件','/iːt͡ʃ/','/it͡ʃ/','noun',["The apples cost 50 cents each.","From each according to his ability, to each according to his needs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abnormal','adj.反常的；变态的','/əbˈnɔɹ.ml̩/','/əbˈnɔɹ.ml̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('difference','n.不同','/ˈdɪfəɹən(t)s/','/ˈdɪfəɹən(t)s/','noun',["You need to learn to be more tolerant of difference.","There are three differences between these two pictures.","We have our little differences, but we are firm friends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('must','modalverb.必须n.必须做的事；必不可少的东西','','','noun',["If you''ll be out all day, a map is a must.","If it has rained all day, it must be very wet outside.","This door handle must be rotated fully."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circle','v.围起来，环绕n.圆圈','/ˈsɜɹkəl/','[ˈsɝ.kəɫ]','noun',["The set of all points (x, y) such that (x − 1)2 + y2 = r2 is a circle of radius r around the point (1, 0).","Children, please join hands and form a circle.","circle of friends"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resign','v.辞去，辞职','/ɹɪˈzaɪn/','/ɹɪˈzaɪn/','verb',["He resigned the crown to follow his heart.","After fighting for so long, she finally resigned to her death."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drier','n.烘干机，吹风机','/ˈdɹaɪə/','/ˈdɹaɪə/','noun',["The sun and a northwesterly wind are great driers of the earth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bathe','v.洗澡，沐浴，浸洗','/beɪð/','/beɪð/','noun',["I''m going to have a midnight bathe tonight.","We bathe our baby before going to bed; other parents do it in the morning if they have time.","She bathed her eyes with liquid to remove the stinging chemical."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polite','adj.有礼貌的，有教养的','/pəˈlaɪt/','/pəˈlaɪt/','verb',["It''s not polite to use a mobile phone in a restaurant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cut','v.切，剪，削，割；删节n.伤口','/kʌt/','/kʌt/','noun',["He made a fine cut with his sword.","a smooth or clear cut","Look at this cut on my finger!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entertainment','n.娱乐；娱乐表演','/ˈɛn.tɚˈteɪn.mənt/','/ˈɛn.tɚˈteɪn.mənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('probably','adv.很可能，大概','/ˈpɹɒbli/','/ˈpɹɑbli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('document','n.文件，文献','/ˈdɒkjʊmɛnt/','/ˈdɑkjʊmənt/','noun',["He documented each step of the process as he did it, which was good when the investigation occurred.","A ship should be documented according to the directions of law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aluminum','n.铝','','/ə.ˈluː.mɨ.nəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ward','vt.保卫，看护n.病房，收容所','/wɔːd/','/wɔɹd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('starve','v.饿死，挨饿','/stɑːv/','/stɑɹv/','verb',["Hey, ma, I''m starving! What''s for dinner?","The patient''s brain was starved of oxygen.","I was half starved waiting out in that wind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prize','n.奖赏，奖品，奖金','/pɹaɪz/','/pɹaɪz/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accident','n.事故，意外事件','/ˈæk.sə.dənt/','/ˈæk.sə.dənt/','noun',["to die by an accident","My insurance went up after the second accident in three months.","Beauty is an accident."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clay','n.黏土；泥土','/kleɪ/','/kleɪ/','noun',["The French Open is played on clay.","We went shooting clays at the weekend.","Danzig is rightfully German clay."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moment','n.[C]片刻，瞬间，刹那','/ˈməʊmənt/','/ˈmoʊmənt/','noun',["Wait a moment, while I lock the front door.","If the points represent mass, then the zeroth moment is the total mass, the first moment divided by the total mass is the center of mass, and the second moment is the rotational inertia."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyway','adv.不管怎样','/ˈɛniweɪ/','/ˈɛniweɪ/','adverb',["He didn''t enjoy washing his car, but it was so dirty that he did it anyway.","I don''t think that''s true. I haven''t found any evidence, anyway."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('promote','vt.促进；提升；推销','/pɹəˈməʊt/','/pɹəˈmoʊt/','verb',["He promoted his clerk to office manager.","They promoted the abolition of daylight saving time.","At the end of the season, three teams are promoted to the Premier League."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('routine','n.常规，日常事务','/ɹuːˈtiːn/','/ɹuːˈtiːn/','noun',["Connie was completely robotic and emotionless by age 12; her entire life had become one big routine.","stand-up comedy routine"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('found','vt.成立，建立','/faʊnd/','/faʊnd/','verb',["I found my car keys. They were under the couch.","Water is found to be a compound substance.","to find leisure; to find means"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tear','v.扯破，撕开n.眼泪','','','noun',["A small tear is easy to mend, if it is on the seam.","to go on a tear","He tore his coat on the nail."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excuse','n.借口，理由vt.原谅，宽恕','','','noun',["Tell me why you were late – and I don''t want to hear any excuses!","He''s a sorry excuse of a doctor.","I excused him his transgressions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attack','v&n.攻击，袭击','/əˈtæk/','/əˈtæk/','noun',["They claimed the censorship of the article was an attack on free speech.","The army timed their attack to coincide with the local celebrations.","Having washed the plates from dinner, I made an attack on the laundry."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoonful','n.一匙','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humour','n.幽默，幽默感','/ˈhjuː.mə(ɹ)/','/ˈhjuːmɚ/','noun',["She has a great sense of humour, and I always laugh a lot whenever we get together.","He was in a particularly vile humour that afternoon.","I know you don''t believe my story, but humour me for a minute and imagine it to be true."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divorce','n.离婚vt.使离婚','/dɪˈvɔːs/','/dɪˈvɔːs/','noun',["Richard obtained a divorce from his wife some years ago, but hasn''t returned to the dating scene.","The Civil War split between Virginia and West Virginia was a divorce based along cultural and economic as well as geographic lines.","A ship captain can marry couples, but cannot divorce them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('currency','n.货币','/ˈkʌɹ.ən.si/','/ˈkɝ.ən.si/','noun',["Wampum was used as a currency by Amerindians.","The jargon’s currency."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distribute','v.分布；分配','/dɨˈstɹɪbjuːt/','/dɪˈstɹɪbjut/','verb',["He distributed the bread amongst his followers.","The agency distributes newspapers to local shops.","A network of children distributes flyers to every house."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worried','adj.担心的；烦恼的','/ˈwʌɹid/','','adjective',["She was worried about her son who had been sent off to fight in the war.","Stop worrying about your test, it’ll be fine.","Your tone of voice worries me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attach','vt.系上，贴上','/əˈtætʃ/','/əˈtætʃ/','verb',["An officer is attached to a certain regiment, company, or ship.","Dower will attach.","attached to a friend; attaching others to us by wealth or flattery"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canal','n.运河；水道','/kəˈnæl/','/kəˈnɛl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shout','v.呼喊，呼叫n.[C]喊，高声呼喊','/ʃaʊt/','/ʃaʊt/','noun',["Next up the new single from Beyoncé, but first a shout to Barry Bloggins and his wife Belinda...","They shouted his name to get his attention.","He′s shouting us all to the opening night of the play."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('escape','v&n.逃跑，逃脱；避开','/əˈskeɪp/','/əˈskeɪp/','noun',["The prisoners made their escape by digging a tunnel.","You forgot to insert an escape in the datastream.","The factory was evacuated after toxic gases escaped from a pipe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flashlight','n.手电筒；闪光信号','/ˈflæʃˌlaɪt/','/ˈflæʃˌlaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ankle','n.脚踝','/ˈæŋ.kəl/','/ˈæŋ.kəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('situation','n.形势，情况','/sɪtjuːˈeɪʃən/','/sɪtjuːˈeɪʃən/','noun',["The United States is in an awkward situation with debt default looming.","The Botanical Gardens are in a delightful situation on the river bank.","Boss, we''ve got a situation here..."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('think','v.想，思索；认为','/θɪŋk/','/θɪŋk/','noun',["I''ll have a think about that and let you know.","Idly, the detective thought what his next move should be.","I thought for three hours about the problem and still couldn’t find the solution."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receive','v.收到，得到','/ɹɪˈsiːv/','/ɹɪˈsiːv/','noun',["She received many presents for her birthday.","to receive a lodger, visitor, ambassador, messenger, etc.","I received a bloody nose from the collision."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirst','n.渴，口渴','/θɜːst/','/θɝst/','noun',["a thirst for gold","I thirst for knowledge and education will sate me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('participate','vi.参加，参与','/pɑːˈtɪsɪpeɪt/','','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surplus','n.剩余，过剩','/ˈsɜːpləs/','/ˈsɜːpləs/','noun',["It is surplus to our needs"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refresh','v.精神振作；更新','/ɹiˈfɹɛʃ/','/ɹɪˈfɹɛʃ/','noun',["Sleep refreshes the body and the mind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('librarian','n.图书管理员，图书馆馆长','/laɪˈbɹɛɹ.i.ən/','/laɪˈbɹɛɹ.i.ən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theft','n.盗窃案','/θɛft/','/θɛft/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('religion','n.宗教','/ɹɪˈlɪdʒən/','/ɹɪˈlɪdʒən/','noun',["My brother tends to value religion, but my sister not as much.","Eckankar is a new religion but Zoroastrianism is an old religion.","The monk entered religion when he was 20 years of age."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diagram','n.图表，图样','/ˈdaɪ.ə.ɡɹæm/','/ˈdaɪ.ə.ɡɹæm/','noun',["Electrical diagrams show device interconnections."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('claw','n.爪','/klɔː/','/klɔ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prayer','n.祈祷','/pɹɛə(ɹ)/','/pɹɛɚ/','noun',["Through prayer I ask for God''s blessings.","In many cultures, prayer involves singing.","Christians recite the Lord''s Prayer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speech','n.演讲','/ˈspiːtʃ/','/ˈspiːtʃ/','noun',["It was hard to hear the sounds of his speech over the noise. He had a bad speech impediment.","The candidate made some ambitious promises in his campaign speech.","Her speech was soft and lilting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('watch','v.观察，观看n.手表','/wɒt͡ʃ/','/wɑt͡ʃ/','noun',["More people today carry a watch on their wrists than in their pockets.","The second watch of the night began at midnight.","The watch stopped the travelers at the city gates."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clap','v.拍手，鼓掌','/klæp/','/klæp/','noun',["He summoned the waiter with a clap.","Off in the distance, he heard the clap of thunder.","His father''s affection never went further than a handshake or a clap on the shoulder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quit','v.离开；停止','/kwɪt/','/kwɪt/','verb',["After having to work overtime without being paid, I quit my job.","John is planning to quit smoking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polish','v.擦亮，磨光；润色','/ˈpɒlɪʃ/','/ˈpɑlɪʃ/','noun',["A good silver polish will remove tarnish easily.","The floor was waxed to a high polish.","The lecturer showed a lot of polish at his last talk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chart','n.图表；航海图','/tʃɑːt/','/tʃɑɹt/','noun',["Let''s chart how we''re going to get from here to there.","The band first charted in 1994."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insurance','n.保险','/ɪn.ˈʃɔː.ɹəns/','/ɪn.ˈʃɝ.əns/','noun',["The car was totalled, but fortunately I had insurance.","After five years in banking, I switched to insurance.","The sky was clear, but I took my umbrella for insurance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medical','adj.医学的，医疗的','/ˈmɛdɪkl̩/','/ˈmɛdɪkl̩/','noun',["You''ll have to get a medical before you apply for that job.","Do you have any medical experience?","medical marijuana; medical cannabis; medical treatment"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('principle','n.原则；原理','/ˈpɹɪnsəpəl/','/ˈpɹɪnsəpəl/','noun',["We need some sort of principles to reason from.","The principle of least privilege holds that a process should only receive the permissions it needs.","I don''t doubt your principles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('till','conj&prep.直到，直到…为止','/tɪl/','/tɪl/','preposition',["I have to work till eight o''clock tonight.","They led him till his tent","Maybe you can, maybe you can''t: you won''t know till you try."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attend','v.出席，参加；专心，考虑；看护，照料','/əˈtɛnd/','/əˈtɛnd/','verb',["Secretaries attend to correspondence.","Servants attend the king day and night.","Children must attend primary school."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goods','n.商品，货物','/ɡʊdz/','/ɡʊdz/','noun',["The best is the enemy of the good."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lie','vi.躺，卧，平放；位于n.谎言vt.说谎','/laɪ̯/','/laɪ̯/','noun',["The book lies on the table;  the snow lies on the roof;  he lies in his coffin","The paper does not lie smooth on the wall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secure','adj.安全的，可靠的；放心的，无虑的','/səˈkjɔː(ɹ)/','/səˈkjɔɹ/','verb',["to secure a creditor against loss; to secure a debt by a mortgage","to secure a prisoner; to secure a door, or the hatches of a ship","to secure an estate"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smell','n.气味v.闻出，闻到，嗅到','/smɛl/','/smɛl/','noun',["I love the smell of fresh bread.","I can smell fresh bread.","Her feet smell of cheese."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('used','tov.过去常常','/juːzd/','/juːzd/','verb',["soldiers who are used to hardships and danger","I used to get things done.","to use an animal cruelly"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unable','adj.不能的，不能胜任的','/ʌnˈeɪbəl/','/ʌnˈeɪbəl/','adjective',["Are you unable to mind your own business or something?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glare','v.瞪眼，怒目而视；闪耀n.强光','/ɡlɛə/','/ɡlɛə/','noun',["a glare of ice","He walked in late, with the teacher glaring at him the whole time.","The sun glared down on the desert sand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disappointed','adj.失望的','/ˌdɪsəˈpɔɪntɪd/','/ˌdɪsəˈpɔɪntɪd/','verb',["His lack of respect disappointed her.","After all his anticipation, the trip left him deeply disappointed.","a disappointed tone / face / silence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irrigation','n.灌溉','/ˌɪɹəˈɡeɪʃən/','/ˌɪɹəˈɡeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('late','adv.晚，迟adj.晚的，迟的','/leɪt/','/leɪt/','noun',["It was late in the evening when we finally arrived.","It was getting late and I was tired.","Late Latin is less fully inflected than classical Latin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continue','v.延伸；继续','/kənˈtɪnjuː/','/kənˈtɪnjuː/','noun',["Do you want me to continue to unload these?","When will the concert continue?","This meeting has been continued to the thirteenth of July."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shoot','vt.射击，射中；摄影n.嫩枝，苗，芽','/ʃuːt/','/ʃuːt/','noun',["The land shoots into a promontory."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('realize','vt.认识到；实现','/ˈɹɪə.laɪz/','/ˈɹi.ə.laɪz/','verb',["The objectives of the project were never fully realized.","He realized that he had left his umbrella on the train.","to realize large profits from a speculation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('budget','n.预算','/ˈbʌdʒ.ɪt/','/ˈbʌdʒ.ɪt/','noun',["Budgeting is even harder in times of recession","The PM’s pet projects are budgeted rather generously","The prestigious building project is budgeted in great detail, from warf facilities to the protocollary opening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('actual','adj.实际的，现实的','/ˈak(t)ʃj(ʊ)əl/','/ˈæk(t)ʃ(əw)əl/','noun',["The actual government expenses dramatically exceed the budget."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tension','n.紧张，不安；拉紧，绷紧；压力，张力','/ˈtɛnʃən/','/ˈtɛnʃən/','noun',["We tensioned the cable until it snapped."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chest','n.箱子；胸部','/t͡ʃɛst/','/t͡ʃɛst/','noun',["The clothes are kept in a chest.","You can take the money from the chest.","She had a sudden pain in her chest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eastern','adj.东方的，东部的','/ˈiːstən/','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marathon','n.马拉松','/ˈmæɹəθən/','/ˈmæɹəθən/','noun',["He had a cleaning marathon the night before his girlfriend came over.","We''re going to marathon Star Trek next weekend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('last','determiner.最近的，最近一段时间的，最近一次的adv.最近，上次v.(使)持续n.鞋楦','/last/','/læst/','adjective',["“Eyes Wide Shut” was the last film to be directed by Stanley Kubrick.","I have received your note dated the 17th last, and am responding to say that","He is the last person to be accused of theft."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adapt','v.适应；改编','/əˈdæpt/','/əˈdæpt/','verb',["to adapt a story for the stage","a word of an adapted form","They could not adapt to the new climate and so perished."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wash','v.洗涤，冲刷n.洗；洗的衣服','/wɒʃ/','/wɑʃ/','noun',["I''m going to have a quick wash before coming to bed.","hand wash","There''s a lot in that wash: maybe you should split it into two piles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weight','n.重量','/weɪt/','/weɪt/','noun',["He''s working out with weights.","the weight of care or business","He was pushing weight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doubt','n&v.怀疑，疑惑','/dʌʊt/','/daʊt/','noun',["I have doubts about how to convert this code to JavaScript.","He doubted that was really what you meant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheerful','adj.兴高采烈的，快活的','/ˈt͡ʃɪəfəl/','/ˈt͡ʃɪɹfəl/','adjective',["They enjoyed a cheerful room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uncomfortable','adj.不舒服的，不安的','/ʌnˈkʌm.fə.tə.bəl/','/ʌnˈkʌm.fɚ.tə.bəl/','adjective',["The class squirmed and fidgeted in the uncomfortable new chairs.","Sharing a house with them made me uncomfortable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('develop','v.发展；发育；开发；冲洗','/dɛˈvɛ.ləp/','/dɪˈvɛ.ləp/','verb',["Let''s see how things develop and then make our decision.","Isabel developed from a tropical depression to a tropical storm to a hurricane.   An embryo develops into a fetus and then into an infant.","I need to develop a plan for the next three weeks."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('misunderstand','vt.误会，不理解','/mɪs.ʌn.də(ɹ)ˈstænd/','/mɪs.ʌn.də(ɹ)ˈstænd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warn','vt.警告；预告','/wɔːn/','/wɔːn/','verb',["Don''t let me catch you running in the corridor again, I warn you.","A sign warns trespassers off/away from the site."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('measure','v.测量；权衡n.方法，措施','/ˈmɛʒə/','/ˈmɛʒɚ/','noun',["We measured the temperature with a thermometer.   You should measure the angle with a spirit level.","The window measured two square feet.","I measure that at 10 centimetres."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guilty','adj.有罪的，犯法的；内疚的','/ˈɡɪl.ti/','/ˈɡɪl.ti/','noun',["He was guilty of cheating at cards.","The guilty man was led away.","Do you have a guilty conscience?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crossroads','n.十字路口','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('district','n.区，地区','/ˈdɪstɹɪkt/','/ˈdɪstɹɪkt/','noun',["the Soho district of London","the Lake District in Cumbria","South Oxfordshire District Council"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receipt','n.收据；收到，接收','/ɹɪˈsiːt/','/ɹɪˈsiːt/','noun',["A balance payable on receipt of the goods.","This weekend''s receipts alone cover our costs to mount the production!","to receipt delivered goods"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assume','vt.假定，设想；承担','/əˈsjuːm/','/əˈsuːm/','verb',["We assume that, as her parents were dentists, she knows quite a bit about dentistry.","Mr. Jones will assume the position of a lifeguard until a proper replacement is found.","He assumed an air of indifference"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swim','vi.游泳；游','/swɪm/','/swɪm/','noun',["I''m going for a swim.","a bare few bits of meat swimming in watery sauce","For exercise, we like to swim laps around the pool."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('full','adv.完整地，十分地adj.满的，充满的，完全的','/fʊl/','/fʊl/','adjective',["The jugs were full to the point of overflowing.","Our book gives full treatment to the subject of angling.","She had tattoos the full length of her arms.   He was prosecuted to the full extent of the law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basement','n.地下室','/ˈbeɪsmənt/','/ˈbeɪsmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pepper','n.胡椒粉','/ˈpɛpə/','/ˈpɛpə/','noun',["Some ballparks have signs saying \"No pepper games\".","After the hailstorm, the beach was peppered with holes.","He liked to pepper his conversation with long words."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chant','v.唱；歌颂n.圣歌，赞美诗','/tʃænt/','/tʃænt/','noun',["The football fans chanted insults at the referee."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capsule','n.胶囊；太空舱','/ˈkæpsjuːl/','/ˈkæpsjuːl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('away','adv.离开，远离','/əˈweɪ/','/əˈweɪ/','verb',["At 9 o''clock sharp he awayed to bed.","The master is away from home.","He''s miles away by now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memory','n.回忆，记忆','/ˈmɛm(ə)ɹi/','/ˈmɛm(ə)ɹi/','noun',["Memory is a facility common to all animals.","I have no memory of that event.","This data passes from the CPU to the memory."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concept','n.概念，观念','/ˈkɒn.sɛpt/','/ˈkɒn.sɛpt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motivation','n.动机','','','noun',["The motivation scores showed that 65% of people wanted to visit our website to learn more about the offer after watching the commercial."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impossible','adj.不可能的，办不到的','/ɪmˈpɒs.ə.bəl/','/ɪmˈpɑ.səbl/','noun',["Late 14th century: “Madame,” quod he, “this were an impossible!” — Geoffrey Chaucer, ‘The Franklin''s Tale’, Canterbury Tales","It is difficult, if not impossible, to memorize 20,000 consecutive numbers.","You never listen to a word I say – you''re impossible!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('effort','n.努力，艰难的尝试','/ˈɛfət/','/ˈɛfɚt/','noun',["It took a lot of effort to find a decent-sized, fully-furnished apartment within walking distance of the office.   He made a conscious effort to not appear affected by the stories in the paper.","Although he didn''t win any medals, Johnson''s effort at the Olympics won over many fans."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wave','v.挥手；摇动n.波，波浪','/weɪv/','/weɪv/','verb',["The flag waved in the gentle breeze.","I waved goodbye from across the room.","Jones waves at strike one."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disaster','n.灾难，祸患','/dɪˈzæs.tə/','/dɪˈzæs.tɚ/','noun',["People would suffer disasters when society''s morality degenerates."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anything','pron.某事；任何事','/ˈɛ.nə.θɪŋ/','/ˈɛn.i.θɪŋ/','noun',["I would not do it for anything."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agriculture','n.农业，农学','/ˈæɡɹɪˌkʌltʃə/','/ˈæɡɹɪˌkʌltʃɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grocer','n.零售商人；食品店','/ˈɡɹəʊ.sə/','/ˈɡɹəʊ.sə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ecology','n.生态学','/ɛˈkɒlədʒi/','/ɛˈkɒlədʒi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stare','v.盯着看，凝视','/stɛə(ɹ)/','/stɛə(ɹ)/','noun',["the stares of astonished passers-by","to stare a timid person into submission","staring windows or colours"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('painful','adj.痛苦的；疼痛的','/ˈpeɪn.fəl/','','adjective',["His violin playing is painful."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steady','adj.稳固的；平稳的','/ˈstɛdi/','/ˈstɛdi/','noun',["Hold the ladder steady while I go up.","a man steady in his principles, in his purpose, or in the pursuit of an object","a steady ride"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vote','v.选举，投票','/vəʊt/','/voʊt/','noun',["One occasion indicative votes were used was in 2003 when MPs were presented with seven different options on how to reform the House of Lords.","The Supreme Court upheld the principle of one person, one vote.","Did you vote last month?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('early','adv.早，在早期adj.早的，早期的','/ˈɜː.li/','/ˈɝli/','noun',["at eleven, we went for an early lunch;  she began reading at an early age;  his mother suffered an early death","The early guests sipped their punch and avoided each other''s eyes.","Early results showed their winning 245 out of 300 seats in parliament. The main opponent locked up only 31 seats."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harvest','n&v.收割；收获','/ˈhaːvəst/','/ˈhɑɹ.vəst/','noun',["Harvest is usually very damp and rainy.","This year''s cotton harvest was great but the corn harvest was disastrous.","Harvesting is a stressing, thirsty occupation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pain','n.疼痛；','/peɪn/','/peɪn/','noun',["I had to stop running when I started getting pains in my feet.","In the final analysis, pain is a fact of life.","Your mother is a right pain."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disease','n.病，疾病','/dɪˈziːz/','/dɪˈziz/','noun',["The tomato plants had some kind of disease that left their leaves splotchy and fruit withered."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('start','n&v.开始，着手；出发','/stɑːt/','/stɑɹt/','noun',["The movie was entertaining from start to finish.","He woke with a start.","Captured pieces are returned to the start of the board."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purchase','n&vt.购买','/ˈpɜːtʃəs/','/ˈpɝtʃəs/','noun',["They offer a free hamburger with the purchase of a drink.","He was pleased with his latest purchase.","It is hard to get purchase on a nail without a pry bar or hammer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yet','adv.到目前为止；还；仍然','/jɛt/','/jɛt/','adverb',["He has never yet been late for an appointment;   I’m not yet wise enough to answer that;   Have you finished yet?","The workers went to the factory early and are striking yet.","The riddle will be solved yet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engineer','n.工程师；技师','/ˌɛnd͡ʒɪˈnɪə/','/ˌɛnd͡ʒɪˈnɪɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pair','n.一双，一对','/pɛə(ɹ)/','/pɛɹ/','noun',["I couldn''t decide which of the pair of designer shirts I preferred, so I bought the pair.","Spouses should make a great pair.","a pair of scissors; two pairs of spectacles; several pairs of jeans"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manage','vi.应付过去vt.管理；达成','/ˈmænɪdʒ/','/ˈmænədʒ/','noun',["He managed to climb the tower.","It''s a tough job, but I''ll manage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equal','adj.平等的，相等的vt.等于，比得上','/ˈiːkwəl/','/ˈiːkwəl/','noun',["This beer has no equal.","Two plus two equals four.","David equaled the water levels of the bottles, so they now both contain exactly 1 liter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alike','adv.类似于，以同样的方式adj.相同的，相似的','/əˈlaɪk/','/əˈlaɪk/','adjective',["The twins were alike.","We are all alike concerned in religion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gravity','n.地心引力，重力','/ˈɡɹævɪti/','/ˈɡɹævɪti/','noun',["I hope you appreciate the gravity of the situation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typical','adj.典型的；象征性的','/ˈtɪpɪkl̩/','/ˈtɪpɪkl̩/','noun',["Among the moths, typicals were more common than melanics."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bravery','n.勇敢，勇气','/ˈbɹeɪvəɹi/','/ˈbɹeɪvəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finance','n.财政，金融','/faɪˈnæns/','/faɪˈnæns/','noun',["Who''s really in charge of a democracy''s finances?","Finance on all our new cars is provided by ABC Loans Ltd.","He financed his home purchase through a local credit union."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parking','n.停车','/ˈpɑːkɪŋ/','/ˈpɑːkɪŋ/','verb',["I parked the drive heads of my hard disk before travelling with my laptop.","Let''s park that until next week''s meeting.","to park artillery, wagons, automobiles, etc."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shadow','n.[C]影子，阴影','/ˈʃædəʊ/','/ˈʃædoʊ/','noun',["My shadow lengthened as the sun began to set.","I immediately jumped into shadow as I saw them approach.","The mountains block the passage of rain-producing weather systems and cast a \"shadow\" of dryness behind them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hydrogen','n.氢','/ˈhaɪdɹədʒ(ə)n/','/ˈhaɪdɹədʒən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('put','vt.放，摆','/pʊt/','/pʊt/','noun',["He bought a January ''08 put for Procter and Gamble at 80 to hedge his bet.","the put of a ball","She put her books on the table."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('climb','v.爬，攀登','/klaɪm/','/klaɪm/','noun',["Prices climbed steeply.","Climbing a tree"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offence','n.犯罪；过错；冒犯；攻击','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carbon','n.碳','/ˈkɑɹbən/','/ˈkɑɹbən/','noun',["A methane molecule is made up of a single carbon with four hydrogens.","When I send it, I''ll carbon Julia so she''s aware."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circus','n.马戏团','/ˈsɜːkəs/','/ˈsɝkəs/','noun',["The circus will be in town next week.","Oxford Circus in London is at the north end of Regent Street."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('controversial','adj.争论的，争议的','/kɒn.tɹə.ˈvɜː.sjəl/','/kɒn.tɹə.ˈvɜː.sjəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dinosaur','n.恐龙','/ˈdaɪnəsɔː(ɹ)/','/ˈdaɪnəsɔː(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enter','v.进入','/ˈɛntə(ɹ)/','/ˈɛntɚ/','noun',["You should knock before you enter, unless you want to see me naked.","to enter a knife into a piece of wood;  to enter a boy at college, a horse for a race, etc.","My twelve-year-old son will be entering his teens next year.  She had planned to enter the legal profession."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attain','vt.获得；达到','/əˈteɪn/','/əˈteɪn/','verb',["To attain such a high level of proficiency requires hours of practice each day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trap','vt.使陷入困境n.陷阱，圈套','/tɹæp/','/tɹæp/','noun',["I put down some traps in my apartment to try and deal with the mouse problem.","Unfortunately she fell into the trap of confusing biology with destiny.","Close the trap, would you, before someone falls and breaks their neck."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lonely','adj.孤独的，寂寞的','/ˈləʊnli/','/ˈloʊnli/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tram','n.有轨电车','/tɹam/','/tɹam/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pale','adj.苍白的，灰白的','/peɪl/','/peɪl/','noun',["I have pale yellow wallpaper.","His face turned pale after hearing about his mother''s death.","He is but a pale shadow of his former self."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('struggle','n&v.努力，斗争，挣扎','/ˈstrʌɡəl/','/ˈstrʌɡəl/','noun',["During the centuries, the people of Ireland struggled constantly to assert their right to govern themselves.","She struggled to escape from her assailant''s grasp."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallery','n.画廊，美术品陈列室','/ˈɡæləɹi/','/ˈɡæləɹi/','noun',["a clip-art gallery in a wordprocessor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pest','n.害虫','/pɛst/','/pɛst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warmth','n.温暖，暖和；热烈，热情，热心','/wɔːmθ/','/wɔɹmθ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lesson','n.课；功课；教训','/ˈlɛsn̩/','/ˈlɛsn̩/','noun',["In our school a typical working week consists of around twenty lessons and ten hours of related laboratory work.","Nature has many lessons to teach to us.","I hope this accident taught you a lesson!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destroy','v.破坏，毁坏','/dɪˈstɹɔɪ/','/dɪˈstɹɔɪ/','verb',["Hooligans destroy unprovoked.","Smoking destroys the natural subtlety of the palate.","Destroying a rabid dog is required by law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supreme','adj.极度的；极大的，最高的','/ˌs(j)uːˈpɹiːm/','','noun',["supreme disgust; supreme courage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambulance','n.救护车','/ˈæm.bjə.ləns/','/ˈæm.bjə.ləns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('junior','adj.初级的；年少的','/ˈdʒuːnɪə/','/ˈdʒuːnɪə/','noun',["four years his junior"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coast','n.海岸，海滨','/kəʊst/','/koʊst/','noun',["The rocky coast of Maine has few beaches.","When I ran out of gas, fortunately I managed to coast into a nearby gas station."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shuttle','n.车辆、飞机等','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provide','v.提供','/pɹəˈvaɪd/','/pɹəˈvaɪd/','verb',["It is difficult to provide for my family working on minimum wage.","Provide against disaster.","I''ll lend you the money, provided that you pay it back by Monday."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allocate','vt.分配；配给；拨出','/ˈæl.ə.keɪt/','/ˈæl.ə.keɪt/','verb',["The bulk of K–12 education funds are allocated to school districts that in turn pay for the cost of operating schools."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('light','vi.点，变亮adj.明亮的；轻的；浅色的n.光，灯，灯光','/laɪt/','[ɫɐɪ̯ʔ]','noun',["As you can see, this spacious dining-room gets a lot of light in the mornings.","Put that light out!","Can you throw any light on this problem?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valuable','adj.值钱的，贵重的','/ˈvæljuəbl̩/','/ˈvæljuəbl̩/','noun',["valuable gemstones","a valuable friend; a valuable companion"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primary','adj.初级的；首要的','/ˈpɹɒeməɹi/','/ˈpɹaɪməɹi/','noun',["most common primaries","Children attend primary school, and teenagers attend secondary school.","Preferred stock has primary claim on dividends, ahead of common stock."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stubborn','adj.顽固的，固执的；难应付的','/ˈstʌbən/','/ˈstʌbɚn/','noun',["Blood can make a very stubborn stain on fabrics if not washed properly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enterprise','n.企业，事业','/ˈɛntɚˌpɹaɪz/','/ˈɛntɚˌpɹaɪz/','noun',["A micro-enterprise is defined as a business having 5 or fewer employees and a low seed capital.","Biosphere 2 was a scientific enterprise aimed at the exploration of the complex web of interactions within life systems.","He has shown great enterprise throughout his early career."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paperwork','n.文书工作','/ˈpeɪ.pɚ.wɚk/','/ˈpeɪ.pɚ.wɚk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solar','adj.太阳的','/ˈsəʊlə/','/ˈsoʊlɚ/','adjective',["solar influence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consume','vt.消耗；消费','/kənˈsjuːm/','/kənˈsuːm/','verb',["The power plant consumes 30 tons of coal per hour.","Baby birds consume their own weight in food each day.","Desire consumed him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('triangle','adj.三角形的n.三角形','/ˈtɹaɪəŋɡəl/','/ˈtɹaɪˌæŋɡəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competence','n.能力','/ˈkɒmpətəns/','/ˈkɒmpətəns/','noun',["That question is out with the competence of this court and must be taken to a higher court."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('helmet','n.头盔','/ˈhɛlmət/','/ˈhɛlmət/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theme','n.主题','/θiːm/','/θiːm/','noun',["We themed the birthday party around superheroes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consult','v.请教，商议；查询','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merely','adv.仅仅，只不过','/ˈmɪəli/','/ˈmɪɹli/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wealth','n.财富','/wɛlθ/','/wɛlθ/','noun',["She brings a wealth of knowledge to the project."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('editor','n.编辑','/ˈɛdɪtə/','/ˈɛdɪtəɹ/','noun',["John Johnson wrote this term paper and the editor was Joan Johnson.","John is the city editor at the Daily Times.","The TPU EVE editor is an excellent, extensible, programmable editor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('means','n.方法，手段','/miːnz/','/miːnz/','verb',["Does she really mean what she said to him last night?","One faltering step means certain death.","Formality and titles mean nothing in their circle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chain','n.链，链条','/ˈt͡ʃeɪn/','/ˈt͡ʃeɪn/','noun',["He wore a gold chain around the neck.","This led to an unfortunate chain of events.","That chain of restaurants is expanding into our town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desire','n&v.渴望，期望','/dɪˈzaɪə/','/diˈzaɪɚ/','noun',["It is my desire to speak with you.","His desire for her kept him awake at night.","Too much desire can seriously affect one’s judgment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('survive','vi.幸存，生还vt.比…活得长','/səˈvʌɪv/','/sɚˈvaɪv/','verb',["His children survived him; he was survived by his children.","He did not survive the accident."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('initial','adj.开始的，最初的','/ɪˈnɪʃəl/','/ɪˈnɪʃəl/','noun',["You can get your initials printed at the top.","Please initial each page and sign the contract in full at the bottom.","Our initial admiration for their efficiency gave way to disgust about their methods."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('muddy','adj.泥泞的，多泥的','[ˈmʌdi]','[ˈmʌdi]','verb',["If you muddy your shoes don''t wear them inside.","The discussion only muddied their understanding of the subject.","He slogged across the muddy field."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consistent','adj.一致的，连贯的','/kənˈsɪstənt/','/kənˈsɪstənt/','noun',["He is very consistent in his political choices: economy good or bad, he always votes Labour!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sword','n.剑，刀','/sɔːd/','/sɔɹd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fingernail','n.手指甲','/ˈfɪŋɡɚˌneɪl/','/ˈfɪŋɡɚˌneɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permanent','adj.永久的，持久的','/ˈpɜːmənənt/','/ˈpɝmənənt/','noun',["Nothing in this world is truly permanent.","The countries are now locked in a permanent state of conflict."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chat','vi.聊天，闲谈n.聊天，闲谈','/tʃæt/','/tʃæt/','noun',["The Chat just made a joke about my skills.","I like to chat over a coffee with a friend.","I met my old friend in the street, so we chatted for a while."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fetch','v.去取来，去请来','/fɛtʃ/','/fɛtʃ/','noun',["If you put some new tyres on it, and clean it up a bit, the car should fetch about $5,000","to fetch headway or sternway","to fetch a man to"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fellow','n.同伴，伙伴','/ˈfɛləʊ/','/ˈfɛloʊ/','noun',["Roger and his fellow workers are to go on strike.","I''ve lost touch with all my old schoolmates: I only see them at class reunions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choice','n.选择，抉择','/tʃɔɪs/','/tʃɔɪs/','noun',["Do I have a choice of what color to paint it?","She didn''t leave us much choice.","The ice cream sundae is a popular choice for dessert."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('travel','n&vi.旅行','/ˈtɹævəl/','/ˈtɹævəl/','noun',["space travel","I’m off on my travels around France again.","My drill press has a travel of only 1.5 inches."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civilization','n.文明，文化','[ˌsɪv.ə.lɑeˈzæɪ.ʃən]','[ˌsɪv.ə.lɑeˈzæɪ.ʃən]','noun',["Modern civilization is a product of industrialization and globalization.","A hermit doesn''t much care for civilization.","The teacher''s civilization of the child was no easy task."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('before','adv.以前conj.在…之前prep.在…以前，在…前面','/bɪˈfɔː/','/biˈfɔɹ/','adverb',["I''ve never done this before.","I want this done before Monday.","He stood before me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fiction','n.小说；虚构，杜撰','/ˈfɪk.ʃən/','/ˈfɪk.ʃən/','noun',["I am a great reader of fiction.","The butler’s account of the crime was pure fiction."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('friendly','adj.友好的','/ˈfɹɛndli/','/ˈfɹɛndli/','noun',["This match is merely a friendly, so don''t worry too much about it.","Your cat seems very friendly.","He gave a friendly smile."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possession','n.所有，拥有；财产，所有物','/pəˈzɛʃən/','/pəˈzɛʃən/','noun',["I would gladly give all of my worldly possessions just to be able to do that.","I''m in possession of the car.","Réunion is the largest of France''s overseas possessions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tell','v.告诉，吩咐；辨别，知道','/tɛl/','/tɛl/','noun',["All told, there were over a dozen.  Can you tell time on a clock?  He had untold wealth.","I want to tell a story;  I want to tell you a story.","Finally, someone told him the truth.  He seems to like to tell lies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replace','vt.取代，代替；把…放回原处','/ɹɪˈpleɪs/','/ɹɪˈpleɪs/','verb',["When you''ve finished using the telephone, please replace the handset.","You can take what you need from the petty cash, but you must replace it tomorrow morning.","I replaced my car with a newer model."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appointment','n.约会','/əˈpɔɪnt.mɛnt/','/əˈpɔɪnt.mɛnt/','noun',["His appointment was deemed suitable","the appointment of treasurer","I''m leaving work early because I have a doctor''s appointment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stomach','n.[C]胃，胃部','/ˈstʌmək/','/ˈstʌmək/','noun',["a good stomach for roast beef","I have no stomach for a fight today.","I can''t stomach her cooking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('experience','vt.经历，体验n.经验；经历','/ɪkˈspɪə.ɹɪəns/','/ɪkˈspɪɹ.i.əns/','noun',["It was an experience he would not soon forget."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('listen','vi.听，仔细听，留神听','/ˈlɪs.ən/','/ˈlɪs.ən/','noun',["Give the motor a listen and tell me if it sounds off.","Please listen carefully as I explain.  I like to listen to music.","You should listen for the starting gun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hit','n&v.打，撞；击中','/hɪt/','/hɪt/','noun',["The hit was very slight.","The catcher got a hit to lead off the fifth.","Where am I going to get my next hit?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('major','adj.主要的；成年的n.主修专业','/ˈmeɪ.dʒə(ɹ)/','/ˈmeɪ.dʒɚ/','noun',["He used to be a major in the army."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interrupt','v.打扰，打断','/ˌɪntəˈɹʌpt/','/ˌɪntəˈɹʌpt/','noun',["The interrupt caused the packet handler routine to run.","A maverick politician repeatedly interrupted the debate by shouting.","The evenness of the road was not interrupted by a single hill."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beat','v.打赢；跳动；敲打n.节拍','/biːt/','/biːt/','noun',["a beat of the heart; the beat of the pulse","the beat of him","a dead beat"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worldwide','adj.遍及全球的，世界各地的','/ˈwɜːldwaɪd/','/ˈwɝldˌwaɪd/','adjective',["A large meteorite impact would cause worldwide extinction of life.","English is spoken worldwide."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bear','v.承担；忍受n.熊','/bɛə(ɹ)/','/bɑɹ/','noun',["That window can be a bear to open.","to bear a railroad stock","The great bear market starting in 1929 scared a whole generation of investors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affair','n.事，事情','/əˈfɛə/','/əˈfɛə(ɹ)/','noun',["a difficult affair to manage","an affair of honor, a duel;  an affair of love, an intrigue","He used a hook-shaped affair with a long handle to unlock the car."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consider','vt.考虑；认为','/kənˈsɪdə/','/kənˈsɪdɚ/','verb',["Consider that we’ve had three major events and the year has hardly begun.","I’m considering going to the beach tomorrow.","Consider yourself lucky, but consider your opponent skillful."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('housework','n.家务劳动','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('potential','adj.潜在的，可能的n.潜力','/pəˈtɛnʃəl/','/po(ʊ)ˈtɛnʃəl/','noun',["Even from a young age it was clear that she had the potential to become a great musician."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accustomed','adj.通常的，习惯的','/ə.ˈkʌs.təmd/','/ə.ˈkʌs.təmd/','adjective',["accustomed to cold"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('group','n.组，群','/ɡɹuːp/','/ɡɹuːp/','noun',["A group of people gathered in front of the Parliament to demonstrate against the Prime Minister''s proposals.","Did you see the new jazz group?","Nitro is an electron-withdrawing group."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jewelry','n.〈总称〉珠宝，首饰','','','noun',["She had more jewellery ornamented about her than any three ladies needed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obtain','vt.获得，得到','/əbˈteɪn/','/əbˈteɪn/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lounge','n.休息厅，休息室','/laʊndʒ/','/laʊndʒ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rugby','n.英式橄榄球','/ˈɹʌɡbi/','/ˈɹʌɡbi/','noun',["The scrum is a distinctive element of rugby."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resist','vt.抵抗；挡开','/ɹəˈzɪst/','/ɹəˈzɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('format','n.版式，格式','/ˈfɔː(ɹ).mæt/','/ˈfɔːɹ.mæt/','noun',["The radio station changed the format of its evening program.","I lost weeks of work when I inadvertently formatted my hard drive."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacrifice','n&v.牺牲，奉献','/ˈsækɹɪfaɪs/','/ˈsækɹɪfaɪs/','noun',["the sacrifice of one''s spare time in order to volunteer","Venison has many advantages over meat from factory farms, although it still requires a hunter to sacrifice the life of a deer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('particular','adj.特殊的；个别的','/pəˈtɪkjələ/','/pəˈtɪkjələ/','noun',["I couldn''t find the particular model you asked for, but I hope this one will do.","I don''t appreciate your particular brand of cynicism.","He brought no particular news."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illegal','adj.违法的，不合规定的','/ɪˈliːɡəl/','/ɪˈliːɡəl/','noun',["Nearly 40 million people live in UK areas with illegal air pollution","Moving a pawn backward is an illegal move in chess.","illegal immigrant;  illegal logger;  illegal pilot"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pause','n&vi.暂停，停止','/pɔːz/','/pɔz/','noun',["Teach the pupil to mind the pauses.","When telling the scary story, he paused for effect.","to pause a song, a video, or a computer game"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congratulate','vt.祝贺，恭贺','/-t͡ʃə-/','/-d͡ʒə-/','verb',["Remind me to congratulate Dave and Lisa on their wedding.","I congratulated myself on the success of my plan."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('careless','adj.粗心的；漫不经心的','/ˈkɛələs/','/ˈkɛɹləs/','adjective',["Jessica was so careless that she put her shorts on backwards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('square','adj.平方的；方形的n.广场；正方形','/skwɛə(ɹ)/','/skwɛɚ/','noun',["64 is the square of 8.","Why do you always wear a tie? Don''t be such a square!","Enter your account number followed by a square."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rainbow','n.彩虹；幻想','/ˈɹeɪnbəʊ/','/ˈɹeɪmboʊ/','noun',["a rainbow of possibilities","Many electoral promises are rainbows, vanishing soon after poll day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twice','adv.两次；两倍','/twaɪs/','/twaɪs/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ample','adj.充足的，丰富的','/ˈæm.pəl/','/ˈæm.pəl/','adjective',["an ample house","ample material","an ample story"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('altitude','n.高度；高处','/ˈælt.ɪˌtjuːd/','/ˈælt.ɪˌtjuːd/','noun',["As the altitude increases, the temperature gets lower, so remember to bring warm clothes to the mountains.","The perpendicular height of a triangle is known as its altitude."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('request','n&vt.要求，请求','/ɹɪˈkwɛst/','/ɹɪˈkwɛst/','noun',["The server returned a 404 error to the HTTP request.","I have requested that the furniture be moved back to its original position.","She called me into her office and requested me to sit down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classify','vt.分类','/ˈklæsɪfaɪ/','/ˈklæsɪfaɪ/','verb',["Should we classify \"make up\" as an idiom or as a phrasal verb?","They decided to classify that information."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('part','v.分离，分别n.部分；角色','/pɐːt/','/pɑɹt/','noun',["to do one’s part","The part of his hair was slightly to the left.","to part the curtains"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percent','n.百分之…','/pəˈsɛnt/','/pɚˈsɛnt/','noun',["only a small percent attain the top ranks"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('point','v.指，指向n.点；要点，观点；分数','/pɔɪnt/','/pɔɪnt/','noun',["point de Venise; Brussels point","The dog came to a point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paddle','v.划桨；戏水n.桨状物；蹼','/ˈpæ.dəl/','/ˈpæ.dəl/','noun',["We had a nice paddle this morning.","The paddle practically ousted the British cane for spankings in the independent US.","A sea turtle''s paddles make it swim almost as fast as land tortoises are slow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('general','adj.大体的，总的；一般的；普遍的','/ˈd͡ʒɛnɹəl/','/ˈd͡ʒɛnəɹəl/','noun',["We have dealt with the generals; now let us turn to the particulars.","Hannibal was one of the greatest generals of the ancient world.","I work in general."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tend','vi.趋向，往往是vt.照管，护理','/tɛnd/','/tɛnd/','verb',["It tends to snow here in winter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frighten','vt.使惊恐，吓唬','/ˈfɹaɪtn̩/','/ˈfɹaɪtn̩/','verb',["Avery puts a sheet over her head, pretending to be a ghost to frighten Emily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relief','n.缓解；轻松','/ɹɪˈliːf/','/ɹɪˈliːf/','noun',["I sighed with relief when I found out that my daughter hadn''t got lost, but was waiting for me at home.","Officer Schmidt can finally go home because his relief has arrived."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boycott','n&vt.联合抵制','/ˈbɔɪkɒt/','/ˈbɔɪkɒt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dimension','n.尺寸，尺度','/daɪˈmɛnʃən/','/daɪˈmɛnʃən/','noun',["The dimension of velocity is length divided by time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('park','n.公园；停车场vt.停放','[paːk]','[paːk]','noun',["A country''s tank park or artillery park.","I parked the drive heads of my hard disk before travelling with my laptop.","Let''s park that until next week''s meeting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unbelievable','adj.难以置信的','/ˌʌnbəˈliːvəbl̩/','/ˌʌnbəˈliːvəbl̩/','adjective',["The most unbelievable thing happened to me today!","His excuse seems rather unbelievable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('process','vt.加工，处理n.程序；方法','/ˈpɹəʊsɛs/','/ˈpɹɑsɛs/','noun',["This product of last month''s quality standards committee is quite good, even though the process was flawed.","1960, Mack Tyner, Process Engineering Calculations: Material and Energy Balances – Ordinarily a process plant will use a steam boiler to supply its process heat requirements and to drive a steam-turbine generator.","We have processed the data using our proven techniques, and have come to the following conclusions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deserve','vt.应受，值得','/dɪˈzɜːv/','/dɪˈzɝv/','verb',["After playing so well, the team really deserved their win."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subscribe','v.捐赠；订阅','/səbˈskɹaɪb/','/səbˈskɹaɪb/','verb',["Would you like to subscribe or subscribe a friend to our new magazine, Lexicography Illustrated?","I don’t subscribe to that theory.","Each man subscribed ten dollars."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clear','adj.清晰的；明亮的；清楚的','/klɪə(ɹ)/','/klɪɹ/','noun',["a room ten feet square in the clear","If you clear the table, I''ll wash up.","Please clear all this stuff off the table."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chef','n.厨师','/ʃɛf/','/ʃɛf/','noun',["Kiss the chef. (slogan on aprons used by home barbecue enthusiasts)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alternative','adj.选择性的，二者择一的','/ɒl.ˈtɜː(ɹ).nə.tɪv/','/ɔl.ˈtɝ.nə.tɪv/','noun',["an alternative proposition"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zoom','v.突然扩大，使猛增','/zuːm/','/zuːm/','verb',["prices zoomed"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('colleague','n.同事','/ˈkɒliːɡ/','/ˈkɑliɡ/','noun',["Young Fortinbras,/ Holding a weak supposal of our worth/...Colleagued with the dream of his advantage,/...hath not failed to pester us with message/ Importing the surrender of those lands/Lost by his father. - Hamlet (Act I, Scene 2)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diamond','n.钻石，金刚石；菱形','/ˈdaɪ(ə)mənd/','/ˈdaɪ(ə)mənd/','noun',["The saw is coated with diamond.","The dozen loose diamonds sparkled in the light.","What a beautiful engagement diamond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('someone','pron.某人；重要人物','/ˈsʌmwʌn/','/ˈsʌmwʌn/','noun',["Do you need a gift for that special someone?","He thinks he has become someone.","Can someone help me, please?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('build','v.建造n.构造','/bɪld/','/bɪld/','noun',["Rugby players are of sturdy build.","The computer company has introduced a new prototype build to beta testers.","I made a build that looked like the Parthenon in that game."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mean','v.意味着，意思是','/miːn/','/miːn/','verb',["Does she really mean what she said to him last night?","One faltering step means certain death.","Formality and titles mean nothing in their circle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approve','vi.赞成；满意vt.批准，通过','/əˈpɹuːv/','/əˈpɹuːv/','verb',["Although we may disagree with it, we must nevertheless approve the sentence handed down by the court-martial.","We approve the measure of the administration, for it is an excellent decision.","Her mother never approves of any of her boyfriends. She thinks nobody is good enough for her little girl."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neither','determiner.两者都不（的），两者中无一（的）adv.也不','/ˈnaɪð.ə(ɹ)/','/ˈnaɪðɚ/','adverb',["Just as you would not correct it, neither would I.","I''ve tried on both shirts, but neither fits properly.","Neither now, nor ever will he forsake his mother."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earn','vt.挣得，赚得','/ɜːn/','/ɝn/','verb',["You can have the s''mores: you earned them, clearing the walkway of snow so well.","He earns seven million dollars a year as CEO.  My bank account is only earning one percent interest.","Now that you are earning, you can start paying me rent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glad','adj.高兴的，乐意的','/ɡlæd/','/ɡlæd/','verb',["I''m glad the rain has finally stopped."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chew','v.咀嚼','/tʃuː/','/tʃu/','noun',["I popped the gum into my mouth and gave it a chew.","Phillip purchased a bag of licorice chews at the drugstore.","The school had banned chew and smokes from the school grounds, even for adults."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pedestrian','n.步行者，行人','/pəˈdɛst.ɹi.ən/','/pəˈdɛst.ɹi.ən/','noun',["pedestrian crossing","His manner of dress was pedestrian but tidy.","The choreographer prefers pedestrian movements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurry','v.赶快；急忙n.匆忙，仓促','/ˈhʌ.ɹi/','/ˈhʌ.ɹi/','noun',["Why are you in such a big hurry?","There is no hurry on that paperwork.","He''s hurrying because he''s late."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('account','v.总计有；认为n.账目；描述','/ə.ˈkaʊnt/','/ə.ˈkaʊnt/','noun',["to keep one''s account at the bank.","No satisfactory account has been given of these phenomena.","Don''t trouble yourself on my account."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tolerate','vt.忍受，容忍','/ˈtɒl.ə.ɹeɪt/','/ˈtɑl.ə.ɹeɪt/','verb',["I can tolerate working on Saturdays, but not on Sundays."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radioactive','adj.放射性的','/ˌɹeɪdioʊˈaktɪv/','/ˌɹeɪdioʊˈaktɪv/','noun',["Even sleazy tactics and his radioactive mouth may not be able to contain this debacle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underline','vt.在…下面划线；强调','/ˈʌndəˌlaɪn/','/ˈʌndɚˌlaɪn/','noun',["underline the important words in the text"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('innocent','adj.清白的，无罪的；纯真的','/ˈɪnəsn̩t/','/ˈɪnəsn̩t/','noun',["The slaughter of the innocents was a significant event in the New Testament.","an innocent trade","innocent goods carried to a belligerent nation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chopsticks','n.筷子','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alphabet','n.字母表','/ˈæl.fə.bɛt/','/ˈæl.fə.bɛt/','noun',["In the first year of school, pupils are taught to recite the alphabet.","Let L be a regular language over the alphabet \\Sigma."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambiguous','adj.暧昧的；不明确的','/æmˈbɪɡjuəs/','/æmˈbɪɡjuəs/','adjective',["The politician was criticized for his ambiguous statements and lack of precision.","He gave an ambiguous answer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advance','v&n.推进，前进','/ədˈvaːns/','/ədˈvæns/','noun',["an advance in health or knowledge","an advance on the prime cost of goods","He made an advance payment on the prior shipment to show good faith."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trip','n.[C]旅行，旅程','/tɹɪp/','/tɹɪp/','noun',["We made a trip to the beach.","He was injured due to a trip down the stairs.","He had a strange trip after taking LSD."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('botanical','adj.植物学的，植物的','','','noun',["a botanical system"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appreciate','vt.欣赏；感激','/əˈpɹiː.si.eɪt/','/əˈpɹiː.si.eɪt/','verb',["I appreciate your efforts","You must learn to appreciate time","I appreciate that what I''m asking you to do is very difficult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('record','v.录制，记录n.记录；唱片','/ˈɹɛkɔːd/','/ˈɹɛkɚd/','noun',["The person had a record of the interview so she could review her notes.","We have no record of you making this payment to us.","The heat and humidity were both new records."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diverse','adj.不同的，多种多样的','/daɪˈvɜːs/','/daɪ.ˈvɝs/','adjective',["Idris Elba was a diverse hire for the franchise"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cube','n.立方体，立方','/kjuːb/','/kjub/','noun',["a stock cube","the cube of 2 is 8","Three cubed can be written as 33, and equals twenty-seven."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strict','adj.严格的，严密的','/stɹɪkt/','/stɹɪkt/','adjective',["strict embrace","strict fiber","to keep strict watch"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jump','v.跳跃；惊起；猛扑n.[C]跳跃','/dʒʌmp/','/dʒʌmp/','noun',["The boy took a skip and a jump down the lane.","He went off a jump.","There were a couple of jumps from the bridge."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knowledge','n.知识，学问','/ˈnɒlɪdʒ/','/ˈnɑlɪdʒ/','noun',["His knowledge of Iceland was limited to what he''d seen on the Travel Channel.","Knowledge consists in recognizing the difference between good and bad decisions.","A secretary should have a good knowledge of shorthand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('happen','v.发生，碰巧','/ˈhæpən/','/ˈhæpən/','verb',["Let me tell you how it happened.","Do you happen to have an umbrella?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pass','v.传递；经过','[pʰäːs]','[pʰaːs]','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('past','adj.过去的，最近的prep.经过；晚于n.过去，往事','/pɑːst/','/pæst/','verb',["a book about a time machine that can transport people back into the past","past glories","during the past year"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('festival','n.节日','/ˈfɛstəvəl/','/ˈfɛstəvəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shock','vt.使震惊n.震动，冲击','/ʃɒk/','/ʃɑk/','noun',["The train hit the buffers with a great shock.","The disaster shocked the world."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delighted','adj.高兴的，快乐的','/dɪˈlaɪtəd/','','verb',["A beautiful landscape delights the eye."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pancake','n.薄煎饼','/ˈpæn.keɪk/','/ˈpæn.keɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('active','adj.积极的，主动的','/ˈæk.tɪv/','/ˈæk.tɪv/','noun',["certain active principles","an active child or animal","active hostilities"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bill','n.钞票；账单；法案，议案','/bɪl/','/bɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whichever','pron.不论哪个','/wɪtʃˈɛvɚ/','/wɪtʃˈɛvɚ/','pronoun',["These chocolates all look delicious. Whichever shall I choose?","Whichever you pick, be content with it.","I have a few books; please borrow whichever interest you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('court','n.法庭，法院；球场','/kɔːt/','/kɔɹt/','noun',["The girls were playing in the court.","The local sports club has six tennis courts and two squash courts.","He was courting big new accounts that previous salesman had not attempted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whose','pron&conj.谁的','/huːz/','/huːz/','pronoun',["Several people have lost their suitcases. Whose have you found?","This car is blocking the way, but Mr Smith, whose it is, will be here shortly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bucket','n.桶；铲斗','/ˈbʌkɪt/','/ˈbʌkɪt/','noun',["I need a bucket to carry the water from the well.","The horse drank a whole bucket of water.","The forward drove to the bucket."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('senior','adj.年长的，资深的；高年级的n.上级，长辈；高年级学生','/ˈsiːnjə(r)/','/ˈsinjɚ/','noun',["He was four years her senior.","senior citizen","senior member; senior counsel"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flexible','adj.柔软的，灵活的','/ˈflɛk.sə.bəl/','/ˈflɛk.sə.bəl/','noun',["This was a principle more flexible to their purpose. -Rogers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relative','adj.相对的；比较的n.亲属，亲戚','[ˈɹɛl.ə.tʰɪv]','[ˈɹɛl.ə.tʰɪv]','noun',["Why do my relatives always talk about sex?","The relative URL /images/pic.jpg, when evaluated in the context of http://example.com/docs/pic.html, corresponds to the absolute URL http://example.com/images/pic.jpg.","relative to your earlier point about taxes, ..."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attitude','n.态度；看法','/ˈætɪˌtjuːd/','/ˈætɪtud/','noun',["The ballet dancer walked with a graceful attitude.","Don''t give me your negative attitude.","The airliner had to land with a nose-up attitude after the incident."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organ','n.器官','/ˈɔː.ɡən/','/ˈɔɹ.ɡən/','noun',["bodily organs"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('average','adj.平均的；普通的n.平均数','/ˈævəɹɪd͡ʒ/','/ˈævəɹɪd͡ʒ/','noun',["The average of 10, 20 and 24 is (10 + 20 + 24)/3 = 18.","batting average","If you average 10, 20 and 24, you get 18."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compare','vt.比较，对照','/kəmˈpɛə/','/kəmˈpɛɚ/','noun',["Compare the tiger''s coloration with that of the zebra.","Astronomers have compared comets to dirty snowballs.","We compare \"good\" as \"good\", \"better\", \"best\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sceptical','adj.怀疑的，怀疑论的','','','adjective',["I can see why people are so skeptical sic about him, but I think he''s on to something here. (regarded by organizations such as the BBC as an error)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unwilling','adj.不愿意，勉强的','/ʌnˈwɪlɪŋ/','/ʌnˈwɪlɪŋ/','adjective',["We are unwilling to restore his previous privileges after his betrayal of our trust."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thriller','n.使人激动的人；惊险、恐怖、刺激的小说、戏剧或电影','/ˈθɹɪlɚ/','/ˈθɹɪlɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transparent','adj.显然的；透明的','/tɹæn(t)sˈpæɹənt/','/tɹæn(t)sˈpæɹənt/','adjective',["The waters of the lake were transparent until the factory dumped waste there.","His reasons for the decision were transparent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('characteristic','adj.特有的，独特的，典型的','/ˌkæɹəktəˈɹɪstɪk/','/ˌkæɹəktəˈɹɪstɪk/','noun',["The characteristic of a field, if non-zero, must be a prime number."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('how','adv.怎样，如何；多少；多么','/haʊ/','/haʊ/','noun',["I am not interested in the why, but in the how.","How often do you practice?","How do you solve this puzzle?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grasp','vt.抓住，紧握；领会','/ɡɹɑːsp/','/ɡɹæsp/','noun',["The goal is within my grasp.","I have never been able to grasp the concept of infinity."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Buddhism','n.佛教','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receptionist','n.接待员','/ɹɪˈsɛpʃənɪst/','/ɹɪˈsɛpʃənɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('composition','n.作文；作曲','/ˌkɒmpəˈzɪʃən/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unlike','prep.不像，和…不同','/ʌnˈlaɪk/','/ʌnˈlaɪk/','noun',["The brothers are quite unlike each other.","They contributed in unlike amounts.","Being late is unlike him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hearing','n.听力','/ˈhiːɹ.ɪŋ/','/ˈhɪɹ.ɪŋ/','verb',["I was deaf, and now I can hear.","I heard a sound from outside the window.","Eventually the king chose to hear her entreaties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('term','n.学期；术语；条款；项','/tɜːm/','/tɝm/','noun',["\"Alright, look...we can spend the holidays with your parents, but this time it will be on my terms.\"","The term of a lease agreement is the period of time during which the lease is effective, and may be fixed, periodic, or of indefinite duration.","Be sure to read the terms and conditions before signing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volcano','n.火山','/vɒlˈkeɪnəʊ/','/vɑlˈkeɪnoʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wedding','n.婚礼，结婚','/ˈwɛdɪŋ/','/ˈwɛdɪŋ/','verb',["The priest wed the couple.","She wed her first love.","I''m not wedded to this proposal; suggest an alternative."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquisition','n.获得；获得物','/æ.kwɪ.ˈzɪ.ʃən/','/æ.kwɪ.ˈzɪ.ʃən/','noun',["The acquisition of sports equipment can be fun in itself.","That graphite tennis racquet is quite an acquisition."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rigid','adj.刚硬的，刚性的；严格的','/ˈɹɪdʒɪd/','/ˈɹɪdʒɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deadline','n.最后期限，截止日期','/ˈdɛdˌlaɪn/','/ˈdɛdˌlaɪn/','noun',["I must make this deadline or my boss will kill me!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spare','adj.空闲的；多余的，剩余的vt.提供；匀出，分出','/ˈspɛə(ɹ)/','/ˈspɛəɹ/','noun',["a spare diet","I have no spare time.","a spare anchor; a spare bed or room"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mine','pron.我的v.开采，挖掘n.矿藏','/maɪn/','/maɪn/','pronoun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mind','v.介意n.思想','/maɪnd/','/maɪnd/','noun',["Despite advancing age, his mind was still as sharp as ever.","There was no doubt in his mind that they would win.","My mind just went blank."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grateful','adj.感激的，感谢的','/ˈɡɹeɪtfəl/','/ˈɡɹeɪtfəl/','adjective',["I''m grateful that you helped me out."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('business','n.商业，生意；职业，事业','/ˈbɪd.nəs/','/ˈbɪd.nəs/','noun',["I was left my father''s business.","He is in the motor and insurance businesses.","He''s such a poor cook, I can''t believe he''s still in business!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bungalow','n.平房','','','noun',["My aunt can''t manage the stairs any more, so she''s moving to a bungalow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staff','n.全体职员','/ˈstæf/','','noun',["The company employed 10 new members of staff this month.","a constable''s staff"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possible','adj.可能的','/ˈpɒsɪbl̩/','/ˈpɑsəbl̩/','noun',["Jones is a possible for the new opening in sales.","It''s not just possible, it''s probable.","It''s possible for anyone to learn to pay the bagpipes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partly','adv.部分地，在一定程度上','/ˈpɑːtli/','/ˈpɑɹtli/','adverb',["they partly finished the house so they could move in before winter;  the car was partly visible in the garage"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breathless','adj.喘不过气来的','/ˈbɹɛθləs/','/ˈbɹɛθləs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meet','v.遇见，会面；满足n.集会','/miːt/','/mit/','noun',["OK, let''s arrange a meet with Tyler and ask him.","This proposal meets my requirements. The company agrees to meet the cost of any repairs.","The eye met a horrid sight. He met his fate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('answer','v.回答，应答；接电话n.答案','/ˈan.sə/','/ˈæn.sɚ/','noun',["Her answer to his proposal was a slap in the face.","There is no simple answer to corruption."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('borrow','v.借用；借','/ˈbɔɹoʊ/','/ˈbɑɹoʊ/','noun',["This putt has a big left-to right borrow on it.","to borrow the style, manner, or opinions of another","Can I borrow a sheet of paper?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maximum','n&adj.最大量，最大限度','/ˈmæksɪməm/','/ˈmæksɪməm/','noun',["Use the proper dose for the maximum effect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('under','adv.在下prep.在…下面，向…下面','/ˈʊndə/','/ˈʌndɚ/','adjective',["Ensure the patient is sufficiently under.","It took the hypnotist several minutes to make his subject go under.","He served in World War II under General Omar Bradley."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desert','v.舍弃，遗弃n.沙漠','/dɪˈzɜːt/','/dɪˈzɜːt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('represent','vt.代表；表现','/ɹɛp.ɹɪ.ˈzɛnt/','/ɹɛp.ɹɪ.ˈzɛnt/','verb',["The sculptor represented a horse in bronze.","It has always been his dream to represent Hamlet on Broadway.","An attorney''s job is to represent his client in court"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compete','vi.比赛，竞赛','/kəm.ˈpiːt/','/kəm.ˈpiːt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('die','v.死亡；消失；熄灭','/daɪ/','/daɪ/','verb',["He died a hero''s death.","I''m dying for a packet of crisps.","The day our sister eloped, she died to our mother."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radium','n.镭','/ˈɹeɪ.dɪ.əm/','/ˈɹeɪ.dɪ.əm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fragrant','adj.香的，芬芳的','/ˈfɹeɪ.ɡɹənt/','/ˈfɹeɪ.ɡɹənt/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dig','v.挖，掘','/dɪɡ/','/dɪɡ/','noun',["He guffawed and gave me a dig in the ribs after telling his latest joke.","a £1 charity shop dig","If the plane can''t pull out of the dive it is in, it''ll dig a hole in the ground."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accountant','n.会计，会计师','/ə.ˈkæʊn.(t)ən̩(t)/','/ə.ˈkæʊn.(t)ən̩(t)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stocking','n.长筒袜','/ˈstɒkɪŋ/','/ˈstɑkɪŋ/','noun',["a pair of stockings"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sometimes','adv.有时','/ˈsʌmtaɪmz/','/ˈsʌmtaɪmz/','adjective',["Sometimes I sit and think, but mostly I just sit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emergency','n.紧急情况或状态','/ɪˈmɝ.dʒən.si/','/ɪˈmɝ.dʒən.si/','noun',["Cardiac arrest is an emergency and if you find someone in cardiac arrest you should call 999 immediately."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('promise','v.答应，允诺；预示n.答应，允诺；希望，前景','/ˈpɹɒmɪs/','/ˈpɹɑmɪs/','noun',["if I make a promise, I always stick to it;  he broke his promise","She shows great promise as an actress.","He promised to never return to this town again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dip','v.浸，蘸','/dɪp/','/dɪp/','noun',["There is a dip in the road ahead.","I''m going for a dip before breakfast.","This onion dip is just scrumptious."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hold','v.拿，握住；举行','/həʊld/','/hoʊld/','noun',["Keep a firm hold on the handlebars.","Can I have a hold of the baby?","Senator X placed a hold on the bill, then went to the library and placed a hold on a book."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('habit','n.习惯，习性','/ˈhæbət/','/ˈhæbət/','noun',["It’s become a habit of mine to have a cup of coffee after dinner.","By force of habit, he dressed for work even though it was holiday.","It’s interesting how Catholic and Buddhist monks both wear habits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passport','n.护照','/ˈpɑːspɔːt/','/ˈpæspɔɹt/','noun',["You will have to bring your passport to prove who you are.","The tenor''s voice was his passport to the international concert circuit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absurd','adj.不合理的；荒谬的','/æbˈzɝd/','/æbˈsɝd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burglar','n.盗贼，窃贼','/ˈbɜːɡlə(ɹ)/','/ˈbɜːɡlə(ɹ)/','noun',["The burglar made off with a large diamond from the museum."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('considerate','adj.体贴的，考虑周到的；替人着想的','/kənˈsɪdəɹət/','/kənˈsɪdəɹət/','verb',["Consider that we’ve had three major events and the year has hardly begun.","I’m considering going to the beach tomorrow.","Consider yourself lucky, but consider your opponent skillful."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rubber','n.橡皮；橡胶；合成橡胶','/ˈɹʌbə(ɹ)/','/ˈɹʌbɚ/','noun',["Jones toes the rubber and then fires to the plate.","Johnny, don''t forget your rubbers today.","Jones enters the pits to get new rubber."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legal','adj.法律的，法定的','/ˈliː.ɡəl/','/ˈliɡəl/','noun',["Legal wants this in writing.","legal profession","legal precedent"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underwear','n.内衣','/ˈʌndəwɛə/','/ˈʌndɚwɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talk','v.谈话，议论n.谈话，会谈；演讲','/toːk/','/toːk/','verb',["Although I don''t speak Chinese I managed to talk with the villagers using signs and gestures.","That''s enough about work, let''s talk holidays!","We talk French sometimes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reply','n&vi.回答，答复','/ɹɪˈplaɪ/','/ɹɪˈplaɪ/','noun',["Joanne replied to Pete''s insult with a slap to his face."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('train','v.培训，训练n.火车','/tɹeɪn/','/tɹeɪn/','noun',["She trained seven hours a day to prepare for the Olympics.","You can''t train a pig to write poetry.","I trained with weights all winter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parcel','n.包裹','[ˈpʰaː.səɫ]','[ˈpʰɑɹ.səɫ]','noun',["I saw a brown paper parcel on my doorstep.","I own a small parcel of land between the refinery and the fish cannery.","A certain piece of land is part and parcel of another piece."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('test','n&vt.测试，考查，试验','/test/','/test/','noun',["Climbing the mountain tested our stamina.","to test the soundness of a principle; to test the validity of an argument","He tested positive for cancer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('journey','n.旅行，路程','/ˈd͡ʒɜːni/','/ˈd͡ʒɝni/','noun',["my journey of dealing with grief"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('count','v.数；计算；有价值','/kaʊnt/','/kaʊnt/','noun',["Give the chairs a quick count to check if we have enough.","He has a 3–2 count with the bases loaded.","Can you count to a hundred?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graph','n.图表，曲线图','/ɡɹæf/','/ɡɹæf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upwards','adv.向上，往上','/ˈʌpwədz/','/ˈʌpwədz/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feast','n.盛宴；节日；令人愉悦的事情','/fiːst/','/fiːst/','noun',["We had a feast to celebrate the harvest.","It was a feast for the eyes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contradictory','adj.相互矛盾的；不一致的','/ˌkɑntɹəˈdɪktəɹi/','/ˌkɑntɹəˈdɪktəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('take','v.拿走；接受，接纳','/teɪk/','/teɪk/','noun',["What''s your take on this issue, Fred?","a new take on a traditional dish","Act seven, scene three, take two."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accompany','vt.陪伴，伴随；伴奏','/ə.ˈkʌm.pə.ni/','/ə.ˈkʌm.pə.ni/','verb',["Geoffrey accompanied the group on their pilgrimage.","I will accompany her on the oboe.","Thunder almost always accompanies lightning during a rain storm."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('petrol','n.汽油','/ˈpɛt.ɹəl/','/ˈpɛt.ɹəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beneficial','adj.有益的，受益的','/ˌbɛnəˈfɪʃəl/','/ˌbɛnəˈfɪʃəl/','noun',["Recycling and reusing garbage can be beneficial to the environment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blame','n&vt.责备，责怪','/bleɪm/','/bleɪm/','noun',["Blame came from all directions.","The blame for starting the fire lies with the arsonist.","They accepted the blame, but it was an accident."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('final','adj.最后的n.决赛；期末考试','/ˈfaɪ.nəl/','/ˈfaɪ.nəl/','noun',["final solution;   the final day of a school term","a final judgment;   the battle of Waterloo brought the contest to a final issue"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('some','pron.若干，一些adj.一些，若干；有些；某一','/sɐm/','/sʌm/','adverb',["I guess he must have weighed some 90 kilos.","Some enjoy spicy food, others prefer it milder.","Can I have some of them?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squeeze','v.压榨，挤n.紧握，捏','/skwiːz/','/skwiːz/','noun',["I''m in a tight squeeze right now when it comes to my free time.","a gentle squeeze on the arm","I want to be your main squeeze."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blank','adj.空的；茫然的n.空格，空白，空白处','/blæŋk/','/blæŋk/','noun',["the double blank","I blanked out my previous entry.","She blanked me for no reason."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rather','adv.相当，宁可','/ˈɹɑːðə/','/ˈɹæðɚ/','verb',["I''d like this one rather than the other one.","It wasn''t supposed to be popular; rather, it was supposed to get the job done.","I didn''t want to leave. Or rather I did, just not alone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('importance','n.重要性','/ɪmˈpɔːtəns/','/ɪmˈpɔɹtəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('session','n.会议；开庭','/ˈsɛʃən/','/ˈsɛʃən/','noun',["\"Are we having a recording session?\" / \"Yes. We''ve even got some session musicians to provide some brass.\"","This court is now in session.","Logging out or shutting down the computer will end your session."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('back','adv.回；向后adj.后面的n.背后，后部；背','/bæk/','/bæk/','noun',["Could you please scratch my back?","He sat in the back of the room.","The small boat raced over the backs of the waves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worthy','adj.值得的；相称的','/ˈwɜːði/','/ˈwɝði/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endless','adj.无止境的；没完没了的','/ˈɛndləs/','/ˈɛndləs/','adjective',["endless time; endless praise","an endless line"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('training','n.培训','/ˈtɹeɪnɪŋ/','/ˈtɹeɪnɪŋ/','verb',["She trained seven hours a day to prepare for the Olympics.","You can''t train a pig to write poetry.","I trained with weights all winter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expectation','n.预料；期望','/ɛkspɛkˈteɪʃən/','/ɛkspɛkˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mist','n.雾','/mɪst/','/mɪst/','noun',["It was difficult to see through the morning mist.","There was an oily mist on the lens.","It''s misting this morning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miss','v.错过；想念','/mɪs/','/mɪs/','noun',["I think I’ll give the meeting a miss.","I missed the target.","to miss an opportunity"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pound','n.磅；英镑','/paʊnd/','/paʊnd/','noun',["the Rhode Island pound; the New Hampshire pound"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('load','n.担子，货物','/ləʊd/','/loʊd/','noun',["I struggled up the hill with the heavy load in my rucksack.","She put another load of clothes in the washing machine.","I put a load on before we left."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bite','v.咬，叮n.咬；一口','/bʌɪt/','/baɪt/','noun',["That snake bite really hurts!","After just one night in the jungle I was covered with mosquito bites.","There were only a few bites left on the plate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ferry','n.渡船','/ˈfɛɹɪ/','/ˈfɛɹi/','noun',["Trucks plowed through the water to ferry flood victims to safety.","Being a good waiter takes more than the ability to ferry plates of food around a restaurant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disgusting','adj.令人讨厌的','/dɪsˈɡʊstɪŋ/','/dɪsˈkʌstɪŋ/','verb',["It disgusts me to see her chew with her mouth open."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignore','vt.不理睬；忽视','/ɪɡˈnɔː/','/ɪɡˈnɔɹ/','verb',["A problem ignored is a problem doubled."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loaf','n.一条','/ləʊf/','/ləʊf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reception','n.接待','/ɹɪˈsɛp.ʃn̩/','/ɹɪˈsɛp.ʃn̩/','noun',["The new system provides exceptional quality of the reception signal.","After the wedding we proceeded to the reception.","The ambassador''s jokes met a cold reception."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applaud','v.鼓掌，喝彩','/əˈplɔːd/','/əˈplɔd/','noun',["After the performance, the audience applauded for five minutes.","Although we don''t like your methods, we applaud your motives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('just','adv.刚才，恰好；只是，仅adj.公正的','/d͡ʒʌst/','/d͡ʒʌst/','adjective',["It is a just assessment of the facts.","It looks like a just solution at first glance.","He calls it vermilion, but it''s just red to me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outward','adv.向外，在外adj.向外的，外出的','/ˈaʊt.wəd/','/ˈaʊt.wɚd/','adjective',["By all outward indications, he''s a normal happy child, but if you talk to him, you will soon realize he has some psychological problems.","an outward war","We are outward bound."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notice','v.注意到n.通告，注意','/ˈnəʊtɪs/','/ˈnoʊtɪs/','noun',["He took no notice of the changes, and went on as though nothing had happened.","I always read the death notices in the paper.","The sidewalk adjacent to the damaged bridge stonework shall be closed until further notice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yummy','adj.美味的','/ˈjʌm.i/','/ˈjʌm.i/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('holy','adj.神圣的','/ˈhəʊli/','/ˈhoʊli/','noun',["I''m planning to visit the holy city of Jerusalem this Christmas.","My grandmother is a very holy woman.","Holy cow, I can’t believe he actually lost the race!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relax','v.放松，轻松','/ɹɪˈlæks/','/ɹɪˈlæks/','verb',["to relax a rope or cord","to relax discipline","Amusement relaxes the mind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relay','n.接力；','','','noun',["Can you relay this message to John?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('custom','n.习惯，习俗','/ˈkʌstəm/','/ˈkʌstəm/','noun',["The Ancient Egyptian culture had many distinctive and interesting beliefs and customs.","My feet are very large, so I need custom shoes.","We can embroider a wide range of ready designs or a custom logo."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('length','n.长，长度','/lɛn(t)θ/','/lɛn(t)θ/','noun',["the length of a book","a length of rope"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permission','n.允许，许可，同意','/pəˈmɪʃən/','/pɚˈmɪʃən/','noun',["Sire, do I have your permission to execute this traitor?","I used the \"chmod\" command to change the file''s permission."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grand','adj.宏伟的，盛大的','/ɡɹænd/','/ɡɹænd/','noun',["a grand army","His simple vision has transformed into something far more grand.","The Grand Viziers of the Ottoman Empire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('schedule','n.时刻表vt.安排，排定','/ˈskɛ.dʒu.əl/','/ˈskɛ.dʒu.əl/','noun',["schedule of tribes","stick to the schedule","I''ll schedule you for three-o''clock then."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eastwards','adv.向东','','','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('print','v.印刷','/pɹɪnt/','/pɹɪnt/','noun',["TV and the internet haven''t killed print.","Write in print using block letters.","The print is too small for me to read."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rewind','v.重绕；回转','/ɹiːˈwaɪnd/','/ɹiːˈwaɪnd/','noun',["I meant to pause the picture, but hit the rewind by mistake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('although','conj.虽然，尽管','/ɔːlˈðəʊ/','/ɑlˈðoʊ/','conjunction',["Although it was very muddy, the football game went on.","It was difficult, although not as difficult as we had expected."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('material','n.材料，原料；物质','/məˈtɪəɹɪəl/','/məˈtɪəɹɪəl/','noun',["Asphalt, composed of oil and sand, is a widely used material for roads.","We were a warm-up act at the time; we didn''t have enough original material to headline.","You''ll need about a yard of material to make this."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approximately','adv.近似地，大约','/əˈpɹɒk.sɪ.mət.li/','/əˈpɹɒk.sɪ.mət.li/','adverb',["...approximately 60 beats per minute."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encouragement','n.鼓励，支持，促进；起激励作用的事物','[ɪnˈkʌɹɪdʒmənt]','[ɪnˈkʌɹɪdʒmənt]','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('universe','n.宇宙','/ˈjuːnɪˌvɜːs/','/ˈjuːnəˌvɝs/','proper noun',["Powerful telescopes look far back into the distant reaches of the Universe.","I think that the universe was created by a life force rather than a deity.","In all this universe of possibilities, there is only one feasible option."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biochemistry','n.生物化学','','','noun',["The biochemistries of fungal and bacterial cells are quite distinct.","Our study compared the biochemistries of epilepsy and Parkinson''s."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('iron','v.熨烫n.铁；熨斗','/ˈaɪən/','/ˈaɪɚn/','noun',["wrought iron, ductile iron, cast iron, pig iron, gray iron","He appeared easygoing, but inside he was pure iron.","He lifts iron on the weekends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idiom','n.习语，成语','/ˈɪdɪəm/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blanket','n.毛毯，毯子','/ˈblæŋkɪt/','/ˈblæŋkɪt/','noun',["The baby was cold, so his mother put a blanket over him.","The city woke under a thick blanket of fog.","A press operator must carefully wash the blanket whenever changing a plate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hug','v.紧抱，拥抱n.拥抱','/hʌɡ/','/hʌɡ/','noun',["Billy hugged Danny until he felt better."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explain','vt.解释，说明','/ɛkˈspleɪn/','/ɛkˈspleɪn/','verb',["To explain a chapter of the Bible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('envy','n&v.嫉妒，羡慕','/ˈɛnvi/','/ˈɛnvi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discount','n.折扣','/dɪsˈkaʊnt/','/dɪsˈkaʊnt/','noun',["This store offers discounts on all its wares. That store specializes in discount wares, too.","Merchants sometimes discount five or six per cent for prompt payment of bills.","the banks discount notes and bills of exchange"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('construct','vt.构筑；建造','/ˈkɒn.stɹʌkt/','/ˈkɒn.stɹʌkt/','noun',["Loops and conditional statements are constructs in computer programming.","Bohr''s theoretical construct of the atom was soon superseded by quantum mechanics.","We constructed the radio from spares."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hope','n&v.希望','/həʊp/','/hoʊp/','verb',["I am still hoping that all will turn out well.","I hope you all the best."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attempt','vt&n.试图，尝试','/əˈtɛmpt/','/əˈtɛmpt/','noun',["It was worth the attempt.","1584 No man can charge us of any attempt against the realm. (Allen''s Defence Of English Catholics, cited after Edinburgh review 1883, p. 378)","A group of 80 budding mountaineers attempted Kilimanjaro, but 30 of them didn''t make it to the top."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soon','adv.不久，很快，一会儿','/suːn/','/suːn/','adjective',["I need the soonest date you have available."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('division','n.除，除法；分开，分割；分界线','/dɪˈvɪʒən/','/dɪˈvɪʒən/','noun',["I''ve got ten divisions to do for my homework.","Magnolias belong to the division Magnoliophyta.","The House of Commons has voted to approve the third reading of the bill without a division. The bill will now progress to the House of Lords."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tablet','n.药片','/ˈtæblət/','/ˈtæblət/','noun',["Many people take vitamin tablets as a food supplement."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hook','n.钩子vt.钩住，用钩子挂','/huːk/','/huːk/','noun',["He is not handling this job, so we''re giving him the hook.","The song''s hook snared me.","We''ve added hooks to allow undefined message types to be handled with custom code."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balance','v.使平衡；权衡n.平衡','/ˈbæləns/','/ˈbæləns/','noun',["Blair thought he could provide a useful balance to Bush''s policies.","I think the balance of opinion is that we should get out while we''re ahead.","I just need to nip to a bank and check my balance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bend','v.弯曲；弯腰，屈身','/bɛnd/','/bɛnd/','noun',["There''s a sharp bend in the road ahead.","A diver who stays deep for too long must ascend very slowly in order to prevent the bends.","the midship bends"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('action','n.行动','/ˈæk.ʃən/','/ˈæk.ʃən/','noun',["Knead bread with a rocking action.","a movie full of exciting action","a rifle action"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lock','n.锁vt.锁，锁上','/lɒk/','/lɑk/','noun',["If you put the brakes on too hard, the wheels will lock.","Remember to lock the door when you leave.","This door locks with a key."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stadium','n.体育场','/ˈsteɪ.di.əm/','/ˈsteɪ.di.əm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fear','n&v.害怕，恐惧，担忧','/fɪə/','/fɪəɹ/','noun',["He was struck by fear on seeing the snake.","Not everybody has the same fears.  I have a fear of ants.","I fear the worst will happen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appreciation','n.欣赏；评论；感激','/əˌpɹiː.ʃiˈeɪ.ʃən/','/əˌpɹiː.ʃiˈeɪ.ʃən/','noun',["We give to you this trophy as a token of our appreciation of all your years of service.","an appreciation of colors"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electrical','adj.与电有关的，电气的','/ɪˈlɛktɹɪkəl/','/ɪˈlɛktɹɪkəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statue','n.雕像','/ˈstæt.juː/','/ˈstætʃu/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sense','n.感觉，意识','/sɛn(t)s/','/sɛns/','noun',["a sense of security","It''s common sense not to put metal objects in a microwave oven.","You don’t make any sense."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cream','n.奶油；乳脂','/kɹiːm/','/kɹiːm/','noun',["Take 100 ml of cream and 50 grams of sugar…","the cream of the crop;  the cream of a collection of books or pictures","You look really sunburnt; you should apply some cream."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensitive','adj.敏感的；灵敏的；易被惹恼的','/ˈsɛnsɪtɪv/','/ˈsɛnsɪtɪv/','noun',["Max is very sensitive; he cried today because of the bad news.","Religion is often a sensitive topic of discussion and should be avoided when dealing with foreign business associates.","These are highly sensitive documents."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('being','n.生物，人；存在','/ˈbiːɪŋ/','/ˈbiŋ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacant','adj.空的，空白的','/ˈveɪkənt/','/ˈveɪkənt/','adjective',["a vacant stare"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afford','vt.买得起；有时间做；承担得起；提供','/əˈfɔːd/','/əˈfoɹd/','verb',["I think we can afford the extra hour it will take.  We can only afford to buy a small car at the moment.","A affords his goods cheaper than B.","Grapes afford wine.  Olives afford oil.  The earth affords fruit.  The sea affords an abundant supply of fish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('birthplace','n.出生地，故乡','/ˈbɝθˌpleɪs/','/ˈbɝθˌpleɪs/','noun',["Portsmouth was Charles Dickens’ birthplace.","Coney Island was the birthplace of the hot dog."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dustbin','n.垃圾箱','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impression','n.印象，感觉','/ɪmˈpɹɛʃən/','/ɪmˈpɹɛʃən/','noun',["His head made an impression on the pillow.","He tried to make a good impression on his parents.","I have the impression that he''s already left for Paris."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interval','n.间歇，间隔；幕间休息','/ˈɪntəvəl/','/ˈɪntɚvəl/','noun',["the interval between contractions during childbirth"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evaluate','vt.评价；估计','/ɨˈvaljʊeɪt/','/ɪ̈ˈvaljəˌweɪt/','verb',["It will take several years to evaluate the material gathered in the survey.","Evaluate this integral."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('status','n.身份，地位','/ˈsteɪt.əs/','/ˈsteɪt.əs/','noun',["Superstition is highly correlated with economic status.","New York is known for its status as a financial center.","I''m just about to update my status to \"busy\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upset','adj.心烦的，苦恼的vt.使苦恼','','','noun',["My late arrival caused the professor considerable upset.","\"collision and upset\": impact with another object or an overturn for whatever reason.","I’m sure the bad news will upset him, but he needs to know."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dot','n.点，圆点','/dɒt/','/dɑt/','noun',["a dot of colour","a dot of a child","His jacket was dotted with splashes of paint."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deliver','vt.投递；交付，给','/dɪˈlɪvə(ɹ)/','/dɪˈlɪvɚ/','verb',["deliver a captive from the prison","deliver a package;  deliver the mail","deliver the thief to the police"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tailor','v.定做n.裁缝','/ˈteɪlə/','/ˈteɪlɚ/','noun',["He works as a tailor on Swanston Street.","We can tailor that jacket for you if you like.","The website was tailored to the client''s needs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stamp','n.[C]邮票','/stæmp/','/stæmp/','noun',["The horse gave two quick stamps and rose up on its hind legs.","My passport has quite a collection of stamps.","She loved to make designs with her collection of stamps."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skip','vi.跳过；跳读','/skɪp/','/skɪp/','noun',["She will skip from one end of the sidewalk to the other.","The rock will skip across the pond.","I bet I can skip this rock to the other side of the pond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phenomenon','n.现象','/fɪˈnɒmənɒn/','/fɪˈnɒmənɒn/','noun',["An electromagnetic phenomenon.","A volcanic eruption is an impressive phenomenon."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mention','vt.提到，说起n.提及','/ˈmɛnʃən/','/ˈmɛnʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mad','adj.发疯的；生气的','/ˈmæːd/','/ˈmæd/','verb',["He''s got this mad idea that he''s irresistible to women.","Are you mad at me?","It''s mad that I got that job back a day after being fired."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barbecue','n.烤肉野餐','/ˈbɑːbɪˌkjuː/','/ˈbɑɹbɪˌkju/','noun',["We cooked our food on the barbecue.","We''re having a barbecue on Saturday, and you''re invited.","She ordered a plate of barbecue with a side of slaw."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('file','n.文件，档案','/faɪl/','/faɪl/','noun',["I''m going to delete these unwanted files to free up some disk space.","She filed for divorce the next day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laundry','n.洗衣店；要洗的衣服','/ˈlɑn.dɹi/','/ˈlɔːn.dɹi/','noun',["You''ve left your dirty laundry all over the house."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('member','n.成员，会员','/ˈmɛmbə/','/ˈmɛmbɚ/','noun',["The I-beams were to become structural members of a pedestrian bridge.","The zip file holding the source code of this application has 245 members."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brewery','n.啤酒厂，酿酒厂','/ˈbɹuːəɹi/','/ˈbɹuːəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accumulate','vt.堆积，积累','/əˈkjuːmjʊˌleɪt/','/ə.ˈkjum.jə.ˌleɪt/','verb',["He wishes to accumulate a sum of money."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crime','n.罪，罪行','/kɹaɪm/','/kɹaɪm/','noun',["Crime doesn’t pay."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stand','vi.站立vt.承担，忍受n.站；台','/stænd/','/stænd/','noun',["The Commander says we will make our stand here.","They took a firm stand against copyright infringement.","They have a four-game stand at home against the Yankees.  They spent the summer touring giving 4 one-night stands a week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surround','vt.围绕，包围','/səˈɹaʊnd/','/səˈɹaʊnd/','noun',["to surround the world"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('together','adv.一起，共同','/təˈɡɛð.ə(ɹ)/','/təˈɡɛðɚ/','adjective',["He''s really together.","We went to school together.","He put all the parts together."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pavement','n.人行道','/ˈpeɪvmənt/','/ˈpeɪvmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cigarette','n.香烟','/sɪ.ɡəˈɹɛt/','/sɪ.ɡəˈɹɛt/','noun',["Could someone cigarette me?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('may','modalverb.可能，也许n.山楂花','/meɪ/','/meɪ/','verb',["you may smoke outside;  may I sit there?","he may be lying;  Schrödinger''s cat may or may not be in the box","may you win;  may the weather be sunny"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('could','modalverb.能，会，可以〔can的过去式〕','/kʊd/','/kʊd/','verb',["She can speak English, French, and German.   I can play football.   Can you remember your fifth birthday?","You can go outside and play when you''re finished with your homework.   Can I use your pen?","Animals can experience emotions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forward','adv.向前，前进adj.早的；前进的','/ˈfoːwəd/','/ˈfɔɹ.wɚd/','noun',["I''ll be glad to forward your mail to you while you''re gone.","The fire was confined to the forward portion of the store.","The stock price is currently 12 times forward earnings."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bent','n.爱好，嗜好adj.弯曲的；决心的','/bɛnt/','/bɛnt/','verb',["Don’t bend your knees.","Look at the trees bending in the wind.","The road bends to the right"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strike','vt.罢工；侵袭；敲；','/stɹaɪk/','/stɹaɪk/','noun',["Thus hand strikes now include single knuckle strikes, knife hand strikes, finger strikes, ridge hand strikes etc., and leg strikes include front kicks, knee strikes, axe kicks, ...","The batsmen have crossed, and Dhoni now has the strike.","Please strike the last sentence."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('health','n.健康，卫生','/hɛlθ/','/hɛlθ/','noun',["Her mental health is really affected by stressful environments.","The directors are concerned about the financial health of the project.","The enemies on this level have a lot of health."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('positive','adj.积极的；肯定的','/ˈpɒzɪ̈tɪv/','/ˈpɑzɪ̈tɪv/','noun',["I’m absolutely positive you''ve spelt that wrong.","‘Better’ is an irregular comparative of the positive form ‘good’.","The idea of beauty is not positive, but depends on the different tastes of individuals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('favourite','adj.特别喜爱的n.特别喜爱的人','/ˈfeɪv.ɹɪt/','/ˈfeɪv.ɹɪt/','noun',["The teacher''s favourite always went first.","She''s the favourite, she''ll probably be elected.","This is my second favourite occupation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bless','vt.保佑，降福','/blɛs/','/blɛs/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('menu','n.菜单','/ˈmɛnju/','/ˈmɛnju/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Pacific','adj.太平洋的','/pəˈsɪfɪk/','/pəˈsɪfɪk/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('able','adj.有能力的；有才干的，有本事的','/ˈeɪ.bl̩/','/ˈeɪ.bl̩/','adjective',["I’ll see you as soon as I’m able.","After the past week of forced marches, only half the men are fully able.","He was born to an able family."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mend','v.修理，修补','/mɛnd/','/mɛnd/','noun',["My trousers have a big rip in them and need a mend.","My trousers have a big rip in them and need mending.","Her stutter was mended by a speech therapist."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('return','v.归还，返回n.返回，来回','/ɹɪˈtɜːn/','/ɹɪˈtɝn/','noun',["I expect the house to be spotless upon my return.","Do you want a one-way or a return?","Last year there were 250 returns of this product, an improvement on the 500 returns the year before."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mail','n.邮政，邮递vt.〈美〉邮寄','/meɪ̯l/','/meɪ̯l/','noun',["Don''t forget to pick up the mail on your way.","He decided to send his declaration by mail.","Please mail me the spreadsheet by the end of the day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conscience','n.道德心，良心','/kɒnʃəns/','/kɒnʃəns/','noun',["Your conscience is your highest authority."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subject','n.题目，主题；学科；主语；主体','/ˈsʌb.dʒɪkt/','/ˈsʌb.dʒɛkt/','adjective',["He''s subject to sneezing fits.","The local board sets local policy, subject to approval from the State Board."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('use','n.利用；应用','','','noun',["The use of torture has been condemned by the United Nations.","What''s the use of a law that nobody follows?","This tool has many uses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bonus','n.奖金，红利','/ˈbəʊ.nəs/','/ˈbəʊ.nəs/','noun',["The employee of the week receives a bonus for his excellent work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feel','vi.摸索，寻找v.觉得；摸起来vt.感觉；触摸；认为','/fiːl/','/fiːl/','noun',["Bark has a rough feel.","You should get a feel of the area before moving in.","She gave me a quick feel to show that she loves me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('main','adj.主要的','/meɪn/','/meɪn/','verb',["He mains the same character as me in that game.","main timbers  main branch of a river  main body of an army"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thrill','n.激动，兴奋；刺激vt.使激动；使胆战心惊','[t̪ɾ̪̊ɪl]','[θɾ̪̊ɪɫ]','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('serve','vt.服务，招待；服役','/sɜːv/','/sɝv/','noun',["Whose serve is it?","I''ve received a summons for jury duty. It says I serve one day or one trial."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cassette','n.[C]卡式盒；暗盒','/kæˈsɛt/','/kæˈsɛt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smile','n&v.微笑','/ˈsmaɪ.əl/','/ˈsmaɪ.əl/','noun',["He always puts a smile on my face.","the smile of the gods","I don''t know what he''s smiling about."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fine','adj.好的；晴朗的；健康的vt.处…以罚金','/fæːn/','/faɪn/','noun',["They filtered silt and fines out of the soil.","to fine gold","to fine the soil"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('find','vt.找到，发现；感到','/faɪnd/','/faɪnd/','noun',["I found my car keys. They were under the couch.","Water is found to be a compound substance.","to find leisure; to find means"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('host','n.主人；节目主持人vt.招待；主持','/həʊst/','/hoʊst/','noun',["A good host is always considerate of the guest’s needs.","Our company is host of the annual conference this year.","The host was terrible, but the acts themselves were good."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accelerate','vt.加速，促进','/æk.ˈsɛl.ə.ˌɹeɪt/','','verb',["to accelerate the growth of a plant, the increase of wealth, etc.","to accelerate our departure"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grain','n.谷物，谷类','/ɡɹeɪn/','/ɡɹeɪn/','noun',["We stored a thousand tons of grain for the winter.","a grain of wheat","The fields were planted with grain."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('international','adj.国际的','/ˌɪntəˈnæʃ(ə)n(ə)l/','/ˌɪntɚˈnæʃ(ə)n(ə)l/','noun',["The United team includes five England internationals.","an international discussion","an international competition"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maid','n.女仆；少女','/meɪd/','/meɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('credit','n.信用；信赖；贷方','/ˈkɹɛdɪt/','/ˈkɹɛdɪt/','noun',["He arrived five minutes late, but to his credit he did work an extra ten minutes at the end of his shift.","She received a singing credit in last year''s operetta.","They kissed, and then the credits rolled."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oxygen','n.氧；氧气','/ˈɒksɪdʒən/','/ˈɒksɪdʒən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regardless','adv.不管，不顾；不加理会','/ɹɪˈɡɑːd.lɪs/','/ɹɪˈɡɑːd.lɪs/','adjective',["Tatiana knew the meat had passed its expiry date, but she ate it regardless."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terrible','adj.可怕的；糟糕的','/ˈtɛ.ɹə.bl̩/','','adjective',["The witch gave him a terrible curse.","He paid a terrible price for his life of drinking.","The food was terrible, but it was free."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('combine','v.联合，结合','/kəmˈbaɪn/','/kəmˈbaɪn/','noun',["We can''t finish harvesting because our combine is stuck in the mud.","Combine the milk and the hot water in a large bowl.   I''m combining business and pleasure on this trip.","Joe combines the intelligence of a rock with the honesty of a politician."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upward','adv.向上，往上','/ˈʌpwəd/','/ˈʌpwɜː(ɹ)d/','noun',["with upward eye; with upward course","We ran upward"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waste','vt.浪费n.废弃物；粪便','/weɪst/','/weɪst/','noun',["The cage was littered with animal waste","Her life seemed a waste"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('citizen','n.公民，市民','/ˈsɪtɪzən/','/ˈsɪtɪsən/','noun',["Diogenes reckoned himself a citizen of the world."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occur','vi.发生，出现','/əˈkɜː/','/əˈkɝ/','verb',["The liftoff will occur in exactly twelve seconds.","I will write if the opportunity occurs.","The chemical monofluoroacetate occurs in all parts of Dichapetalum cymosum, and is responsible for its toxic effects."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comedy','n.喜剧','/ˈkɒmədi/','/ˈkɑmədi/','noun',["Why would you be watching comedy when there are kids starving right now?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleasant','adj.令人愉快的，舒适的','/ˈplɛzənt/','/ˈplɛzənt/','noun',["It wasn''t so hot outside, but pleasant enough to have lunch in the garden."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('difficult','adj.难的；艰难的；不易相处的','/ˈdɪfɪkəlt/','/ˈdɪfɪkəlt/','verb',["However, the difficult weather conditions will ensure Yunnan has plenty of freshwater.","Stop being difficult and eat your broccoli—you know it''s good for you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pressure','n.压；压力；压强','[ˈpɹɛʃ.ə(ɹ)]','[ˈpɹɛʃ.ɚ]','noun',["Apply pressure to the wound to stop the bleeding.","the pressure of poverty; the pressure of taxes; the pressure of motives on the mind; the pressure of civilization.","She has felt pressure lately because her boss expects her to get the job done by the first."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sort','v.分类，拣选n.种类，类别','/sɔːt/','/sɔɹt/','noun',["I had a sort of my cupboard.","Popular algorithms for sorts include quicksort and heapsort."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fill','v.填空；装满；充满','/fɪl/','/fɪl/','verb',["the bucket filled with rain;  the sails fill with wind","My heart filled with joy.","The pharmacist filled my prescription for penicillin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dentist','n.牙科医生','/ˈdɛntɪst/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('numb','adj.麻木的','/nʌm/','/nʌm/','verb',["The dentist gave me novocaine to numb my tooth before drilling, thank goodness.","He turned to alcohol to numb his pain.","fingers numb with cold"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feed','v.喂，饲；吃','/ˈfiːd/','/ˈfiːd/','noun',["They sell feed, riding helmets, and everything else for horses.","a satellite feed","the paper feed of a printer"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forget','v.忘记，忘掉','/fəˈɡɛt/','/fɚˈɡɛt/','verb',["I have forgotten most of the things I learned in school.","I forgot to buy flowers for my wife at our 14th wedding anniversary.","I forgot my car keys."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('professor','n.教授','/pɹəˈfɛsə/','/pɹəˈfɛsɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convenient','adj.便利的，方便的','/kənˈviːniənt/','/kənˈvinjənt/','adjective',["Fast food might be convenient, but it''s also very unhealthy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specialist','n.专家，专科医生；专家；专业人员','/ˈspɛʃəlɪst/','/ˈspɛʃəlɪst/','noun',["The tree Lepidothamnus laxifolius is a high alpine specialist found in high-altitude bog communities and in scrub."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compass','v.包围n.指南针','/ˈkʌm.pəs/','/ˈkʌm.pəs/','noun',["within the compass of an encircling wall"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('background','n.背景','/ˈbæk.ɡɹaʊnd/','/ˈbæk.ɡɹaʊnd/','noun',["The lawyer had a background in computer science.","The photographer let us pick a background for the portrait.","The antivirus program is running in the background."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('true','adj.真正的，确实的；正确的','/tɹuː/','/tɹu/','noun',["He trued the spokes of the bicycle wheel.","We spent all night truing up the report.","This is a true story."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adolescent','adj.青春期的n.[C]青少年','/ˌædəˈlɛsənt/','/ˌædəˈlɛsənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valley','n.山谷，溪谷','/ˈvæli/','/ˈvæli/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('position','n.位置；职位','/pəˈzɪʃ(ə)n/','/pəˈzɪʃ(ə)n/','noun',["Chief of Staff is the second-highest position in the army.","My position on this issue is unchanged.","Stand in this position, with your arms at your side."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('present','adj.当前的；出席的n.礼物，赠品vt.赠送；介绍','/pɹəˈzɛnt/','/ˈpɹɛzənt/','noun',["The barbaric practice continues to the present day.","Is there a doctor present?  Several people were present when the event took place.","a present wit"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laughter','n.笑，笑声','/ˈlɑːftə/','/ˈlæftɚ/','noun',["Their loud laughter betrayed their presence."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('since','prep.自从…以来，自从…之后','/sɪns/','/sɪns/','adverb',["A short/long time since","I have loved you since I first met you.","Since you didn''t call, we left without you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patent','n.专利权','/ˈpeɪtənt/','/ˈpeɪtənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belong','vi.属，附属','/bɪˈlɒŋ/','/bɪˈlɔŋ/','verb',["Where does this document belong?","That house belongs to me.","Suppose x belongs to \\mathbb{R}...  (— written: x \\in \\mathbb{R})"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soul','n.灵魂，心灵','/səʊl/','/soʊl/','noun',["Fifty souls were lost when the ship sank."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dangerous','adj.危险的','/ˈdeɪnd͡ʒ(ə)ɹəs/','/ˈdeɪnd͡ʒ(ə)ɹəs/','adjective',["Railway crossings without gates are highly dangerous."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certificate','n.证明，证明书','','','noun',["The film is certificate 15."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mess','v.弄乱n.凌乱','/mɛs/','/mɛs/','noun',["He made a mess of it.","My boss dumped a whole mess of projects on my desk today.","Parked under a tree, my car was soon covered in birds'' mess."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sour','adj.酸的','/ˈsaʊə/','/ˈsaʊ(ə)ɹ/','noun',["Too much lemon juice will sour the recipe.","We broke up after our relationship soured.","Lemons have a sour taste."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delete','vt.删除','/diˈliːt/','/diˈliːt/','noun',["I lost the file when I accidentally hit delete."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stain','n.污点，瑕疵','/steɪn/','/steɪn/','noun',["armour stained with blood","the stained glass used for church windows"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breath','n.气息，呼吸','/bɹɛθ/','/bɹɛθ/','noun',["I could hear the breath of the runner behind me.","I took a deep breath and started the test.","I could feel the runner''s breath on my shoulder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transform','v.转变，转换','/tɹænzˈfɔːm/','/tɹænzˈfɔɹm/','noun',["The alchemists sought to transform lead into gold."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advise','vt.忠告，劝告，建议','/ədˈvaɪz/','/ədˈvaɪz/','verb',["The dentist advised me to brush three times a day.","The dentist advised brushing three times a day.","The lawyer advised me to drop the case, since there was no chance of winning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repeat','vt.重说，重做；重复','','','noun',["We gave up after the third repeat because it got boring.","The scientists repeated the experiment in order to confirm the result.","Add 100, left 50. Repeat, over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physical','adj.身体的；物理的；客观存在的','/ˈfɪzɪkəl/','/ˈfɪzɪkəl/','noun',["How long has it been since your last physical?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('make','vt.制造，做；使成为','/meɪk/','/meɪk/','noun',["What make of car do you drive?","The camera was of German make.","He made as if to punch him, but they both laughed and shook hands."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microwave','n.微波','/ˈmaɪkɹəʊˌweɪv/','/ˈmaɪkɹəʊˌweɪv/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rooster','n.公鸡','/ˈɹuːstə/','/ˈɹustəɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brochure','n.小册子','/ˈbɹəʊ.ʃə(ɹ)/','/bɹoʊˈʃɝ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('master','vt.精通，掌握n.主人；硕士','/ˈmastə/','/ˈmæstɚ/','noun',["Mark Twain was a master of fiction.","She has a master in psychology.","He is a master of marine biology."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extraordinary','adj.非常的；非凡的','/ɪksˈtɹɔː(ɹ)dɪnəɹi/','','noun',["an extraordinary poet","an extraordinary professor in a German university"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('witness','v.目击，作证n.证人，目击者','/ˈwɪtnəs/','/ˈwɪtnəs/','noun',["She can bear witness, since she was there at the time.","As a witness to the event, I can confirm that he really said that.","The witness for the prosecution did not seem very credible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conventional','adj.惯例的，传统的；常规的','/kənˈvɛnʃənl/','/kənˈvɛnʃənl/','noun',["They wear conventional clothes, eat conventional food, and keep conventional hours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regulation','n.规则，规章','/ˌɹɛɡjʊˈleɪʃən/','/ˌɹɛɡjʊˈleɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('due','adj.预期的；约定的','/dʒʉː/','/du/','noun',["Give him his due — he is a good actor.","He can wait for the amount due him.","With all due respect, you''re wrong about that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ripen','v.成熟','/ˈɹaɪpən/','/ˈɹaɪpən/','verb',["Grapes ripen in the sun.","The warm sun ripened the corn.","ripen the judgment"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puzzle','v.迷惑，困扰n.难题；谜','/ˈpʌzəl/','/ˈpʌzəl/','noun',["Where he went after he left the house is a puzzle.","to be in a puzzle","We puzzled over the curious-shaped lock, but were unable to discover how the key should be inserted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evident','adj.明显的，显然的','/ˈɛ.vɪ.dənt/','/ˈɛ.vɪ.dənt/','adjective',["It was evident she was angry, after she slammed the door."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accommodation','n.住处；工作场所','/ə.ˌkɒm.ə.ˈdeɪ.ʃən/','/ə.ˌkɒm.ə.ˈdeɪ.ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('authentic','adj.真的，可信的','/ɒ.ˈθɛn.tɪk/','/ɒ.ˈθɛn.tɪk/','adjective',["The experts confirmed it was an authentic signature.","The report was completely authentic."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socket','n.插座，插孔；孔，穴','/ˈsɒkɪt/','/ˈsɑkɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biscuit','n.饼干','/ˈbɪskɪt/','/ˈbɪskɪt/','noun',["cheese and biscuits"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fence','n.栅栏，篱笆','/fɛns/','/fɛns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breast','n.胸部；胸怀','/bɹɛst/','/bɹɛst/','noun',["Tanya''s breasts grew remarkably during pregnancy.","She kindled hope in the breast of all who heard her.","The robin has a red breast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mercy','n.怜悯','/ˈmɜːsi/','/ˈmɝsi/','noun',["She took mercy on him and quit embarrassing him.","Have mercy on the poor and assist them if you can.","Mercy is one of his many virtues."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annoy','vt.使烦恼，使生气；骚扰','/əˈnɔɪ/','/əˈnɔɪ/','noun',["Marc loved his sister, but when she annoyed him he wanted to switch her off.","to annoy an army by impeding its march, or by a cannonade"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inform','v.通知，告诉','/ɪnˈfɔːm/','/ɪnˈfɔɹm/','verb',["His sense of religion informs everything he writes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depend','vi.依靠，指望；取决于','/dɪˈpɛnd/','/dɪˈpɛnd/','verb',["We would like to go skiing, but it depends on the amount of snow.","we depend on the mailman to come at the usual time.","a cause depending in court"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commit','v.犯，干','/kəˈmɪt/','/kəˈmɪt/','noun',["Tony should be committed to a nuthouse!","to commit a series of heinous crimes","to commit oneself to a certain action"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('about','adv.大约；到处，周围prep.关于；在附近，在周围','/əˈbɛʊt/','/əˈbaʊt/','adjective',["After my bout with Guillan-Barre Syndrome, it took me 6 months to be up and about again.","This idea has been about for a while but has only recently become fashionable.","I had my keys just a minute ago, so they must be about somewhere."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scream','v.尖叫，尖声喊叫n.尖叫','/skɹiːm/','/skɹim/','noun',["We had a real scream of a time at the beach.","He almost hit a pole, the way he came screaming down the hill.","Do you know what screams \"I''m obnoxious\"? People who feel the need to comment on every little thing they notice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sorrow','n.悲伤，悲痛','/ˈsɔɹoʊ/','/ˈsɑɹoʊ/','noun',["Parting is such sweet sorrow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cure','n&v.治疗，医好','/kɜː(ɹ)/','/kjɝ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('danger','n.危险','/ˈdeɪn.dʒə(ɹ)/','/ˈdeɪndʒɚ/','noun',["There''s plenty of danger in the desert.","The north signal was at danger because of the rockslide."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crash','v&n.碰撞；坠毁','/kɹæʃ/','/kɹæʃ/','noun',["After the lightning came the crash of thunder.","Nobody survived the plane crash","My computer had a crash so I had to reboot it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cover','n.盖子；罩；封面vt.覆盖；掩盖；包括；报道','/ˈkʌvə/','/ˈkʌvɚ/','noun',["The soldiers took cover behind a ruined building.","There''s a $15 cover tonight.","We need to set another cover for the Smith party."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('firm','adj.坚固的；坚定的n.公司，企业','/fɜːm/','/fɜɹm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('character','n.字符；性格','/ˈkæɹəktə/','/ˈkæɹəktɚ/','noun',["A single locus governing the petal colour character was detected on the linkage group A2.","A study of the suspect''s character and his cast iron alibi ruled him out.","\"You may not like to eat liver,\" said Calvin''s father, \"but it builds character.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reflect','vt.反射，反映','/ɹɪˈflɛkt/','/ɹɪˈflɛkt/','verb',["A mirror reflects the light that shines on it.","The moonlight reflected from the surface of water.","The shop window reflected his image as he walked past."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contribution','n.贡献；捐款','/ˌkɒntɹɪˈbjuːʃən/','/ˌkɑntɹɪˈbjuʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('above','adv.在上面adj.上面的，上述的；上文的prep.在…上面，在…上方；多于，大于','/əˈbʌv/','/əˈbʌv/','noun',["He''s in a better place now, floating free as the clouds above.","He appealed to the court above.","It was a cold day at only 5 above."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fire','n.火，火灾vt.点火；射击；解雇','/ˈfɑeə(ɹ)/','/ˈfaɪɚ/','noun',["We sat about the fire singing songs and telling tales.","During hot and dry summers many fires in forests are caused by regardlessly discarded cigarette butts.","The fire was laid and needed to be lit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stick','v.黏住；坚持n.木棒，木棍','/stɪk/','/stɪk/','noun',["Sealing wax is available as a cylindrical or rectangular stick.","to stick type"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orbit','n.运行轨道','/ˈɔː(ɹ)bɪt/','/ˈɔː(ɹ)bɪt/','noun',["The Moon''s orbit around the Earth takes nearly one month to complete.","In the post WWII era, several eastern European countries came into the orbit of the Soviet Union.","The convenience store was a heavily travelled point in her daily orbit, as she purchased both cigarettes and lottery tickets there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('band','n.乐队；带子；镶边','/bænd/','/bænd/','noun',["valence band;  conduction band"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('height','n.高，高度','/haɪt/','/haɪt/','noun',["She''s at the height of her career."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spray','v.喷洒n.水雾，喷雾','/spɹeɪ/','/spɹeɪ/','noun',["The sailor could feel the spray from the waves.","The firemen sprayed the house.","Spray some ointment on that scratch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinguish','v.区分，辨别','/dɪsˈtɪŋɡwɪʃ/','/dɪsˈtɪŋɡwɪʃ/','verb',["The soldier distinguished himself in combat and received a medal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outer','adj.外部的','/ˈaʊtə/','/ˈaʊtɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invent','vt.发明，创造','/ɪnˈvɛnt/','/ɪnˈvɛnt/','verb',["After weeks of hard work, I invented a new way to alphabetize matchbooks.","I knew I had to invent an excuse, and quickly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fluent','adj.流利的，流畅的','/ˈfluːənt/','/ˈfluənt/','noun',["fluent handwriting","She''s fluent in French."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wonderful','adj.极好的','/ˈwʌn.də.fl/','/ˈwʌn.dɚ.fl̩/','adjective',["They served a wonderful six-course meal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shortcoming','n.[C]缺点，短处','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haircut','n.理发','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('howl','v.嚎叫，嚎哭','/haʊl/','/haʊl/','noun',["The howl of the wind","to howl derision"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('something','pron.某事；某物','/ˈsamθɪŋ/','/ˈsʌmθɪŋ/','noun',["The baby looks something like his father.","I have a feeling something good is going to happen today.","That child is something of a genius."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('benefit','n.利益，好处vt.使受益','/ˈbɛn.ɪ.fɪt/','/ˈbɛn.ə.fɪt/','noun',["It was for her benefit.   His benefit was free beer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flood','v.淹没，泛滥n.洪水','/flʌd/','/flʌd/','noun',["a flood of complaints","The floor was flooded with beer.","The station''s switchboard was flooded with listeners making complaints."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quality','n.质量；品质','/ˈkwɒlɪti/','/ˈkwɑləti/','noun',["Quality of life is usually determined by health, education, and income.","One of the qualities of pure iron is that it does not rust easily.","A peasant is not allowed to fall in love with a lady of quality."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intention','n.计划，意图，目的','/ɪnˈtɛnʃən/','/ɪnˈtɛnʃən/','noun',["It’s easy to promise anything when you have no intention of fulfilling any of it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('booth','n.岗；亭或小隔间','/buːð/','/buːð/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rude','adj.无礼的，粗鲁的，粗暴的','/ɹʉːd/','/ɹud/','adjective',["Karen broke up with Fred because he was often rude to her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enthusiastic','adj.热心的，热情的','/ɪnˌθjuːzɪˈæstɪk/','/ɪnˌθjuːzɪˈæstɪk/','adjective',["an enthusiastic lover of art"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symptom','n.症状','/ˈsɪm(p)təm/','/ˈsɪm(p)təm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('funeral','n.葬礼','/ˈfjuːnəɹəl/','/ˈfjunəɹəl/','noun',["Many mourners turned up at the local artist''s funeral to pay homage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unique','adj.唯一的，独特的','/juːˈniːk/','/juːˈniːk/','noun',["Every person has a unique life, therefore every person has a unique journey. ― Gary Cook"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('except','prep.除…之外','/ɪkˈsɛpt/','/ɛkˈsɛpt/','verb',["to except to a witness or his testimony","There was nothing in the cupboard except a tin of beans.","I never made fun of her except teasingly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ministry','n.部门','/ˈmɪnɪstɹi/','/ˈmɪnɪstɹi/','noun',["She works for the ministry of finance.","The premier offered his last ministry''s resignation to the monarch, and is asked to form a new one in accordance with the election results.","the present ministry of the Holy Spirit"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('religious','adj.宗教的；虔诚的','/ɹɪ.ˈlɪ.d͡ʒəs/','','noun',["It is the job of this court to rule on legal matters. We do not consider religious issues.","I was much more religious as a teenager than I am now.","I''m a religious fan of college basketball."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shelter','n.掩蔽；隐蔽处','/ˈʃɛltə/','/ˈʃɛltɚ/','noun',["During the rainstorm, we sheltered under a tree."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fact','n.事实，现实','/fækt/','/fækt/','noun',["In this story, the Gettysburg Address is a fact, but the rest is fiction.","Gravity is a fact, not a theory.","Let''s look at the facts of the case before deciding."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('examine','v.检查，诊察','/ɪɡˈzæmɪn/','/ɪɡˈzæmɪn/','verb',["He examined the crime scene for clues.","The doctor examined the patient.","The witness was examined under oath."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scan','v.细看；浏览；扫描','/skæn/','/skæn/','noun',["The operators vacated the room during the scan.","The doctors looked at the scans and made a diagnosis.","She scanned the passage carefully but could not find what she was looking for."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fundamental','adj.基础的，基本的','/ˌfʌndəˈmɛntəl/','/ˌfʌndəˈmɛntəl/','noun',["one of the fundamentals of linear algebra","A need for belonging seems fundamental to humans."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('association','n.联合；联盟；结交，交往；协会','/əˌsəʊsiˈeɪʃən/','/əˌsoʊsiˈeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('believe','vt.相信；认为','/bɪˈliːv/','/bi-/','verb',["I believe there are faeries.","Why did I ever believe you?","After that night in the church, I believed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remember','v.记得；纪念','/ɹɪˈmɛmbə/','/ɹɪˈmɛmbɚ/','verb',["Please remember this formula!","Remember what I''ve said.","Remember to lock the door when you go out."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outline','n.大纲，轮廓；要点，概要vt.描绘轮廓；略述','/ˈaʊtlaɪn/','/ˈaʊtlaɪn/','noun',["the outline of a speech","Wikipedia items featuring books usually outline them after giving their background."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fade','v.褪色；使消退；枯萎','/feɪd/','/feɪd/','noun',["The milkman''s whistling faded into the distance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unless','conj.如果不，除非','/ənˈlɛs/','/ənˈlɛs/','conjunction',["I’m leaving unless I get a pay rise (AmE: raise)."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glance','v&n.扫视，匆匆一看','/ɡlɑːns/','/ɡlæns/','noun',["copper glance","She glanced at her reflection as she passed the mirror.","The spring sunlight was glancing on the water of the pond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('free','adj.自由的，空闲的；免费的','/fɹiː/','/fɹiː/','noun',["He was given free rein to do whatever he wanted.","It''s free real estate.","We had a wholesome, filling meal, free of meat.  I would like to live free from care in the mountains."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equality','n.平等，同等，均等','/ɪˈkwɒl.ɪ.ti/','/ɪˈkwɒl.ɪ.ti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mix','v.混合，搅拌','/ˈmɪks/','/ˈmɪks/','verb',["Mix the eggs and milk with the flour until the consistency is smooth.","Don''t mix the meat recipes with the dairy recipes.","Yellow and blue paint mix to make green."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ought','aux.应该，应当；大概vi.应该，应当；大概','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dictation','n.听写','/dɪkˈteɪʃən/','/dɪkˈteɪʃən/','noun',["Since I learned shorthand, I can take dictation at eighty words a minute.","1908: Lucy Maud Montgomery, Anne of Green Gables - We had reading and geography and Canadian history and dictation today.","1852: Lysander Spooner, An Essay on the Trial by Jury - ...jurors in England have formerly understood it to be their right and duty to judge only according to their consciences, and not to submit to any dictation from the court, either as to law or fact."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crayon','n.蜡笔；蜡笔画','/ˈkɹeɪ.ɒ̃/','/ˈkɹaʊn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('honour','vt.尊敬，给予荣誉n.荣誉，光荣','/ˈɒnə(ɹ)/','/ˈɒnə(ɹ)/','noun',["The crowds gave the returning general much honor and praise.","He was a most perfect knight, for he had great honor and chivalry.","Audie Murphy received many honors, such as the Distinguished Service Cross."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bother','vt.烦扰，打扰','[ˈbɒðə(ɹ)]','[ˈbɔðə(ɹ)]','noun',["There was a bit of bother at the hairdresser''s when they couldn''t find my appointment in the book.","Yes, I can do that for you - it''s no bother.","Would it bother you if I smoked?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expression','n.表情；表达法，表达方式','/ɪkˈspɹɛʃ.ən/','/ɪkˈspɹɛʃ.ən/','noun',["The expression \"break a leg!\" should not be taken literally.","Her expression changed from joy to misery after realising her winning lottery ticket had expired.","expression from a gland"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('middle','adj.中部的，中间的，中级的n.中间，当中','/ˈmɪdəl/','/ˈmɪdəl/','noun',["The middle of a circle is the point which has the same distance to every point of circle.","I woke up in the middle of the night.","the middle point"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('childhood','n.幼年时代，童年','/ˈtʃaɪldhʊd/','/ˈtʃaɪldhʊd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('though','conj&adv.虽然，可是，尽管','/ðəʊ/','/ðoʊ/','adverb',["I will do it, though.","\"Man, it''s hot in here.\" — \"Isn''t it, though?\"","Though it’s risky, it’s worth taking the chance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thorough','adj.彻底的','/ˈθʌɹə/','/ˈθɜɹoʊ/','noun',["He is the most thorough worker I have ever seen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appeal','n&v.呼吁，请求','/əˈpiːl/','/əˈpiːl/','noun',["He made an appeal for volunteers to help at the festival.","I appeal to all of you to help the orphans.","That idea appeals to me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everyday','adj.日常的','/ˈɛvɹiˌdeɪ/','/ˈɛvɹiˌdeɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stay','v.保持，停止，阻止n.逗留','/steɪ/','/steɪ/','noun',["I hope you enjoyed your stay in Hawaii.","The governor granted a stay of execution.","stand at a stay"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appear','vi.出现；看来，似乎','/əˈpiːɹ/','/əˈpiɹ/','verb',["A great writer appeared at that time.","He appeared quite happy with the result."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('face','n.脸；面容；表情；面子；正面vt.面向；面对，朝；正视；面临','/feɪs/','/feɪs/','noun',["That girl has a pretty face.","Why the sad face?","Children! Stop making faces at each other!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abandon','vt.放弃','/əˈbæn.dən/','/əˈbæn.dn̩/','verb',["Many baby girls have been abandoned on the streets of Beijing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congratulation','n.祝贺，恭贺','/kənˌɡɹætjʊˈleɪʃ(ə)n/','/kənˌɡɹætjʊˈleɪʃ(ə)n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspire','v.鼓舞，激励；启示','/ɪn.ˈspaɪə(ɹ)/','/ɪn.ˈspaɪə(ɹ)/','verb',["Elders should inspire children with sentiments of virtue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afraid','adj.害怕的，恐惧的','/əˈfɹeɪd/','/əˈfɹeɪd/','adjective',["He is afraid of death.","I am afraid I cannot help you in this matter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('progress','vi.进展；进行n.进步，上进','/ˈpɹɒɡɹɛs/','/ˈpɹoʊɡɹɛs/','noun',["Testing for the new antidote is currently in progress.","Science has made extraordinary progress in the last fifty years.","The thick branches overhanging the path made progress difficult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geometry','n.几何学','/dʒiːˈɒmɪtɹi/','/dʒiˈɑmətɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invite','vt.邀请；招待','/ɪnˈvaɪt/','/ɪnˈvaɪt/','verb',["We invited our friends round for dinner.","I invite you all to be seated.","I always invite criticism of my definitions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('open','adj.公开的；开着的v.打开；公开','/ˈəʊ.pən/','/ˈoʊ.pən/','adjective',["an open hand; an open flower","Banks are not open on bank holidays.","I am open to new ideas."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devote','vt.奉献；致力；专心','/dɪˈvəʊt/','/dɪˈvoʊt/','verb',["I devoted this afternoon to repainting my study, and nothing will get in my way.","The city was devoted to the flames."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agent','n.代理商','/ˈeɪ.dʒənt/','/ˈeɪ.dʒənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treat','vt.对待，看待；治疗','/tɹiːt/','/tɹiːt/','noun',["Here are some healthy Halloween treats for ghouls and witches of all ages.","It was such a treat to see her back in action on the London stage.","I lured the cat into her carrier by throwing a couple of treats in there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abortion','n.流产；堕胎','/əˈbɔɹ.ʃn̩/','/əˈbɔɹ.ʃn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bishop','n.主教','/ˈbɪʃəp/','/ˈbɪʃəp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suffering','n.痛苦，苦难','/ˈsʌfəɹɪŋ/','/ˈsʌfəɹɪŋ/','verb',["Is anyone here afraid of suffering hardship?","At least he didn''t suffer when he died in the car crash.","If you keep partying like this, your school-work will suffer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afterward','adv.后来','/ˈɑːftə.wəd/','/ˈæf.tɚ.wɚd/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reputation','n.名誉，名声','/ˌɹɛpjʊˈteɪʃən/','/ˌɹɛpjʊˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('project','n.项目，工程','','','noun',["Projects like Pruitt-Igoe were considered irreparably dangerous and demolished.","a man given to projects","The CEO is projecting the completion of the acquisition by April 2007."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inside','adv.在里面，在内部prep.在…里面，在…之内','/ɪnˈsaɪd/','/ɪnˈsaɪd/','noun',["The inside of the building has been extensively restored.","On a motorway, you should never pass another vehicle on the inside.","The car in front drifted wide on the bend, so I darted up the inside to take the lead."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('independence','n.独立','/ɪndɪˈpɛndəns/','/ɪndɪˈpɛndəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presentation','n.演示，演出；呈现，展示','/ˌpɹizənˈteɪʃən/','/ˌpɹizənˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whenever','conj.无论何时','/wəˈnɛvə/','/hwəˈnɛvɚ/','adverb',["Whenever will I find time to finish that jigsaw?","Feel free to visit whenever.","Visit whenever you want to."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dynasty','n.朝代，王朝','/ˈdɪnəsti/','/ˈdaɪnəsti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bark','v.〔狗〕吠叫n.狗叫声，吠声','/bɑːk/','/bɑɹk/','noun',["The neighbour''s dog is always barking.","The sergeant barked an order."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greedy','adj.贪婪的','/ˈɡɹiːdi/','/ˈɡɹiːdi/','adjective',["This regular expression performs a greedy match."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awkward','adj.笨拙的；难使用的','/ˈɑkwɚd/','/ˈɔkwɚd/','noun',["John was awkward at performing the trick. He''ll have to practice to improve.","An awkward silence had fallen.","I''m very awkward at parties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bare','adj.赤裸的vt.使赤裸；露出','/bɛə(ɹ)/','/bɛəɹ/','noun',["a bare majority","I do wonder why keeping my little breasts bare can be lewd even as none tells my brother anything for being bare-chested.","The cupboard was bare."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ruin','v.毁坏；毁灭','/ˈɹuː.ɪn/','/ˈɹuː.ɪn/','noun',["The monastery has fallen into ruin.","Gambling has been the ruin of many.","the ruin of a ship or an army;  the ruin of a constitution or a government;  the ruin of health or hopes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mutton','n.羊肉','/ˈmʌtn̩/','/ˈmʌtn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('celebrate','v.庆祝','/ˈsɛl.ə.bɹeɪt/','/ˈsɛl.ə.bɹeɪt/','verb',["to celebrate the name of the Most High","to celebrate a birthday","I was promoted today at work—let’s celebrate!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admirable','adj.令人钦佩的；极好的','/ˈæd.məɹ.ə.bəl/','/ˈæd.məɹ.ə.bəl/','adjective',["It''s admirable that Shelley overcame her handicap and excelled in her work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('please','v.使人高兴，令人满意int.请','/pliːz/','/pliz/','verb',["Her presentation pleased the executives.","Just do as you please."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('look','vi.看，瞧；看起来；注意n.[C]看，瞧','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offshore','adj&adv.近海的，向海的','/ɒfˈʃɔː(ɹ)/','/ɒfˈʃɔː(ɹ)/','noun',["an offshore oil rig"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fortnight','n.两星期','/ˈfɔːt.naɪt/','/ˈfɔɹt.naɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scar','n.伤疤','/skɑː(ɹ)/','/skɑː(ɹ)/','noun',["Seeing his parents die in a car crash scarred him for life."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mountainous','adj.多山的','/ˈmaʊntɪnəs/','/ˈmaʊntɪnəs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspect','vt.检查；审视','/ɪnˈspɛkt/','/ɪnˈspɛkt/','verb',["Inspect the system for leaks.","The general inspected the troops and their barracks."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('campaign','vi.参加活动；作战n.战役；竞选活动','/kæmˈpeɪn/','/kæmˈpeɪn/','noun',["The company is targeting children in their latest advertising campaign.","She campaigned for better social security."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vital','adj.重大的，生死攸关的','/ˈvaɪt̬əl/','/ˈvaɪt̬əl/','adjective',["vital energies; vital functions; vital actions","The brain is a vital organ.","The transition to farming was vital for the creation of civilisation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conflict','n.斗争，冲突','/kənˈflɪkt/','/kənˈflɪkt/','noun',["The conflict between the government and the rebels began three years ago.","I wanted to attend the meeting but there''s a conflict in my schedule that day.","It appears that our schedules conflict."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allow','vt.允许，准许','/əˈlaʊ/','/əˈlaʊ/','verb',["to allow a servant his liberty;  to allow a free passage;  to allow one day for rest","to allow a right;  to allow a claim;  to allow the truth of a proposition","To allow a sum for leakage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rough','adj.粗糙的；粗略的','/ɹʌf/','/ɹʌf/','noun',["Rough in the shape first, then polish the details.","a rough estimate; a rough sketch of a building; a rough plan","rough sea"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knock','n&v.敲；打；击','/nɒk/','/nɑk/','noun',["I heard a knock on my door.","He took a knock on the head.","He played a slow but sure knock of 35."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mass','n.众多，大量；','/mæs/','/mæs/','noun',["I mass 70 kilograms.","There is evidence of mass extinctions in the distant past.","Mass unemployment resulted from the financial collapse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rule','n.规则，规定；统治vt.统治；支配','/ɹuːl/','/ɹuːl/','noun',["All participants must adhere to the rules.","As a rule, our senior editors are serious-minded.","a rule for extracting the cube root"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proper','adj.恰当的，合适的','/ˈpɹɔp.ə/','/ˈpɹɑ.pɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('update','vt&n.现代化；更新','','','noun',["He gave me an update on the situation in New York.","I just made an update to the Wikipedia article on guerillas.","I just made an update to my blog about my trip to Rome."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amateur','adj.业余爱好的n.业余爱好者','/ˈæ.mə.tə/','/ˈæ.mə.tɚ/','noun',["The contest is only open to amateurs.","The entire thing was built by some amateurs with screwdrivers and plywood.","amateur sports"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poisonous','adj.有毒的；有害的；致命的','/ˈpɔɪznəs/','/ˈpɔɪznəs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condemn','vt.谴责，声讨','/kənˈdɛm/','/kənˈdɛm/','verb',["The president condemned the terrorists.","The house was condemned after it was badly damaged by fire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assistance','n.援助，帮助','/əˈsɪs.təns/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bitter','adj.有苦味的；痛苦的；严酷的','/ˈbɪtə/','/ˈbɪtəɹ/','noun',["The coffee tasted bitter.","They''re bitter enemies.","I''ve been bitter ever since that defeat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speed','v.加速n.速度','/spiːd/','/spiːd/','noun',["How does Usain Bolt run at that speed?","Speed limits provide information to the drivers about the safe speed to travel in average conditions.","We could go to the shore next week, or somewhere else if that''s not your speed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gesture','n.姿势；手势','/ˈdʒɛs.tʃɚ/','/ˈdʒɛs.tʃɚ/','noun',["The middle-finger gesture is really a nonverbal swear.","We took flowers as a gesture of sympathy.","My dad said to never gesture with my hands when I talk."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admit','v.承认；准许','/ədˈmɪt/','/ədˈmɪt/','verb',["A ticket admits one into a playhouse.","the prisoner was admitted to bail","he admitted his guilt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('common','adj.普通的；公共的；共有的','/ˈkɒmən/','/ˈkɑmən/','noun',["The two competitors have the common aim of winning the championship.","It is common to find sharks off this coast.","It differs from the common blackbird in the size of its beak."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interest','n.兴趣，趣味；利息vt.使产生兴趣','/ˈɪntəɹɪst/','/ˈɪntəɹst/','noun',["Our bank offers borrowers an annual interest of 5%.","He has a lot of interest in vintage cars.","I have business interests in South Africa."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wonder','v.想知道；对…感到惊讶n.奇迹','/ˈwʌndə/','/ˈwʌndɚ/','noun',["Wonders of the World seem to come in sevens.","The idea was so crazy that it is a wonder that anyone went along with it.","He''s a wonder at cooking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleepy','adj.想睡的，困倦的，瞌睡的','/ˈsliːpi/','/ˈsliːpi/','noun',["a sleepy drink or potion","a sleepy English village"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sneeze','n&vi.打喷嚏','/sniːz/','/sniːz/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bath','n.[C]洗澡；浴室；澡盆','/bɐːθ/','[bæθ⁓bɛəθ⁓beəθ]','noun',["a bath of heated sand, ashes, steam, or hot air","Most Americans don''t know ''WC'' and many Brits mock ''bathroom'' but almost everyone understands ''toilet'' or ''lavatory''."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('every','adj.每一，每个的；每…','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mask','v.戴面具；掩饰n.口罩，面罩；遮盖物','/mæsk/','/mæsk/','noun',["a dancer''s mask; a fencer''s mask; a ball player''s mask","to mask a body of troops or a fortess by a superior force, while some hostile evolution is being carried out"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thermos','n.热水瓶','/ˈθɝ.məs/','/ˈθɝ.məs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('summary','n.[C]摘要，概要','/ˈsʌməɹi/','/ˈsʌməɹi/','noun',["A summary review is in the appendix.","They used summary executions to break the resistance of the people.","Summary justice is bad justice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apply','v.申请；应用','/əˈplaɪ/','/əˈplaɪ/','verb',["to apply cream to a rash","to apply funds to the repayment of a debt","We need to apply the skills we''ve learned to solve this problem"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overlook','vt.俯瞰；远眺','/əʊvəˈlʊk/','/oʊvəɹˈlʊk/','noun',["Our hotel room overlooks the lake.","These errors were overlooked by the proofreaders.","I’m not willing to overlook such bad behaviour."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('politician','n.政治家','/ˈpɒl.ɪ.tɪʃ.ən/','/pɑl.ɪˈtɪʃ.ən/','noun',["Politicians should serve the country''s interest.","Unlike the other candidates, I''m not a politician.","Only real politicians are interested in this issue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('taxpayer','n.纳税人','','','noun',["1945: I got into the bus full of taxpayers who were giving some money to a taxpayer who had on his taxpayer''s stomach a little box which allowed the other taxpayers to continue their taxpayers'' journeys. I noticed in this bus a taxpayer with a long taxpayer''s neck and whose taxpayer''s head bore a taxpayer''s felt hat encircled by a plait the like of which no taxpayer ever wore before. Suddenly the said taxpayer peremptorily addressed a nearby taxpayer, complaining bitterly that he was purposely treading on his taxpayer''s toes every time other taxpayers got on or off the taxpayers'' bus. Then the angry taxpayer went and sat down in a seat for taxpayers which another taxpayer had just vacated. — Raymond Queneau, ''from Polyptotes'' in Exercises in Style, 1945 (Eng. 1958)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indeed','adv.确实，实在','/ɪnˈdiːd/','/ɪnˈdiːd/','adverb',["Indeed, he made several misplays.","As a soccer player, he is terrible indeed.","\"I am a great runner.\" \"Indeed!\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seagull','n.海鸥','/ˈsiː.ɡʌl/','/ˈsiː.ɡʌl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artificial','adj.人造的；非天然的','/ɑː(ɹ)təˈfɪʃəl/','/ɑː(ɹ)təˈfɪʃəl/','adjective',["The flowers were artificial, and he thought them rather tacky.","Her manner was somewhat artificial."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disagree','vi.意见不一致，持不同意见','/dɪsəˈɡɹiː/','/dɪsəˈɡɹiː/','verb',["Bob says cats are friendlier than dogs, but I disagree.","My results in the laboratory consistently disagree with yours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comment','v.评论；注释n.评论','/ˈkɒmɛnt/','/ˈkɑmɛnt/','noun',["I have no comment on that.","I wish I''d commented this complicated algorithm back when I remembered how it worked."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('step','v.走；跨步n.脚步；台阶','/stɛp/','/stɛp/','noun',["He improved step by step, or by steps.","The driver must have a clear view of the step in order to prevent accidents.","One step is generally about three feet, but may be more or less."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forever','adv.永远地，永恒地','/fəˈɹɛvə(ɹ)/','/fəˈɹɛvɚ/','noun',["I haven''t seen him in forever!","Sure, I''d be happy to meet with you on the 12th of forever.","I shall love you forever."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mark','v.做记号，标记n.标记；分数','/mɑɹk/','/mɑɹk/','noun',["to mark a box or bale of merchandise","See where this pencil has marked the paper.","She folded over the corner of the page to mark where she left off reading."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('base','n.根据地；底部vt.以…为基础，基于…','/beɪs/','/beɪs/','noun',["The logarithm to base 2 of 8 is 3.","Peter adjusted the equalizer on his audio equipment to emphasize the bass.","The conductor preferred to situate the bass in the middle rear, rather than to one side of the orchestra."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('employ','vt.雇用','/ɛmˈplɔɪ/','/ɛmˈplɔɪ/','noun',["The school district has six thousand teachers in its employ.","Yesterday our local garage employed a new mechanic.","The burglar employed a jemmy to get in."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trend','n.倾向，趋势；时尚','/tɹɛnd/','/tɹɛnd/','noun',["the trend of a coastline","There is a trend, these days, for people in films not to smoke.","Miniskirts were one of the biggest trends of the 1960s."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('achievement','n.[U]完成，达到；[C]成就，成绩','/əˈtʃiːvmənt/','/əˈtʃiːvmənt/','noun',["Finishing the game does not give you a 100% score until you have unlocked all of the achievements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whole','adj.完整的，所有的','/həʊl/','/hoʊl/','noun',["This variety of fascinating details didn''t fall together into an enjoyable, coherent whole.","I ate a whole fish.","He is of whole mind, but the same cannot be said about his physical state."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fair','adj.公平的；晴朗的；白皙的n.集市，展览会','/feː(ə)/','/fɛəɹ/','noun',["When will we learn to distinguish between the fair and the foul?","Monday''s child is fair of face.","After scratching out and replacing various words in the manuscript, he scribed a fair copy to send to the publisher."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('during','prep.在…期间，在…过程中','/ˈdjɔː.ɹɪŋ/','/ˈd(j)ʊɚ.ɪŋ/','verb',["I lived with my parents during the 1970s.","I lived with my parents at several points during the 1980s."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balcony','n.阳台；包厢','/ˈbælkəni/','/ˈbælkəni/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revolution','n.革命，变革','/ˌɹɛvəˈl(j)uːʃən/','/ˌɹɛvəˈl(j)uːʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mop','v.用拖把拖地n.拖把','/mɒp/','/mɑp/','noun',["He gave the floor a quick mop to soak up the spilt juice.","He ran a comb through his mop and hurried out the door.","to mop (or scrub) a floor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consist','vi.由…组成','/kənˈsɪst/','/kənˈsɪst/','verb',["The greeting package consists of some brochures, a pen, and a notepad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preparation','n.准备，预备；准备工作，准备措施','/pɹɛpəˈɹeɪʃən/','/pɹɛpəˈɹeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relation','n.关系；亲属','/ɹɪˈleɪʃən/','/ɹɪˈleɪʃən/','noun',["The relation between diet and health is complex.","Yes, he''s a relation of mine, but only a distant one.","Your relation of the events is different from mine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reliable','adj.可靠的','/ɹɪˈlaɪəbəl/','/ɹɪˈlaɪəbəl/','noun',["the old reliables"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loss','n.丧失；损耗','/lɑs/','/lɔs/','noun',["In other areas, glacier loss creates serious risk of a dry period across the Third Pole, Wang said.","It was a terrible crash; both cars were total losses.","The match ended in their first loss of the season."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relate','v.有关；涉及','/ɹiˈleɪt/','/ɹiˈleɪt/','verb',["Please relate the circumstances of your journey here today.","The patterns on the screen relate to the pitch and volume of the music being played.","I find it difficult to relate to others because I''m extremely introverted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typhoon','n.台风','/taɪˈfuːn/','/taɪˈfun/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decoration','n.装饰，修饰；勋章','/ˌdɛkəˈɹeɪʃən/','/ˌdɛkəˈɹeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eggplant','n.茄子','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zip','v.拉开拉链，拉上拉链n.拉链','/zɪp/','/zɪp/','noun',["I know zip about economics.","zip one''s lip","The bullet zipped through the air."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profession','n.职业；专业','/pɹəˈfɛʃən/','/pɹəˈfɛʃən/','noun',["Despite his continued professions of innocence, the court eventually sentenced him to five years.","My father was a barrister by profession.","His conduct is against the established practices of the legal profession."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('still','adv.仍然，还adj.静止的，平静的','/stɪl/','/stɪl/','noun',["the still of the night","Still waters run deep.","still water; still wines"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worn','adj.破烂的，损坏的','/wɔːn/','/wɔɹn/','verb',["He''s wearing some nice pants today.  She wore her medals with pride.  Please wear your seatbelt.  Can you wear makeup and sunscreen at the same time?  He was wearing his lunch after tripping and falling into the buffet.","He wears eyeglasses.  She wears her hair in braids.","She wore a smile all day.  He walked out of the courtroom wearing an air of satisfaction."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arise','vi.起来，升起；出现','/əˈɹaɪz/','/əˈɹaɪz/','verb',["to arise from a kneeling posture","He arose early in the morning.","A cloud arose and covered the sun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dizzy','adj.头晕目眩的','/ˈdɪzi/','/ˈdɪzi/','verb',["I stood up too fast and felt dizzy.","We climbed to a dizzy height.","My new secretary is a dizzy blonde."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('work','v.工作；运作；奏效n.工作；著作','/wɜːk/','/wəik/','noun',["We don''t have much time. Let''s get to work piling up those sandbags.","Tell me you''re using clean works at least."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lose','vt.失去，丢失','/luːz/','/luːz/','verb',["He lost his hearing in the explosion.","I lost my way in the forest.","We lost the football match."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agree','v.同意；应允','/əˈɡɹi/','/əˈɡɹi/','verb',["all parties agree in the expediency of the law.","to agree to an offer, or to opinion.","the picture does not agree with the original; the two scales agree exactly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fail','v.失败；不及格；衰退','/feɪl/','/feɪl/','noun',["The project was full of fail.","Throughout my life, I have always failed.","The truck failed to start."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toward','prep.向，朝，对于','/tɘ.ˈwoːd/','/tʊ.ˈwɔɹd/','adjective',["She moved toward the door.","What are your feelings toward him?","I''m saving money toward retirement."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enjoyable','adj.愉快的；有趣的','/ɛnˈdʒɔɪ.jə.bəl/','/ɛnˈdʒɔɪ.jə.bəl/','adjective',["That was an enjoyable day; I had a lot of fun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyone','pron.任何人，无论谁','/ˈæniˌwʌn/','/ˈæniˌwʌn/','pronoun',["Almost anyone can change a light bulb."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convince','vt.使确信，使信服','/kənˈvɪns/','/kənˈvɪns/','verb',["I wouldn''t have or do something, unless I''m convinced that it''s good."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pride','v.自豪，自夸n.自豪，骄傲','/pɹaɪd/','/pɹaɪd/','noun',["He had pride of ownership in his department.","to be in the pride of one''s life.","A pride of lions often consists of a dominant male, his harem and their offspring, but young adult males ''leave home'' to roam about as bachelors pride until able to seize/establish a family pride of their own."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emperor','n.皇帝','/ˈempɘɹɘ/','/ˈɛmpəɹɚ/','noun',["The Investiture Controversy was a conflict between the Emperor and the Pope."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('word','n.单词；言语；消息，音讯','/wɜːd/','/wɝd/','noun',["mum''s the word","Have you had any word from John yet?","Don''t fire till I give the word"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theory','n.理论','/ˈθiːəɹi/','/ˈθiːəɹi/','noun',["Knot theory classifies the mappings of a circle into 3-space.","A theory is consistent if it has a model."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('broadcast','v.广播n.广播节目','/ˈbɹɑdkæst/','/ˈbɹɔdkæst/','noun',["The DJ was feeling nervous before his first national broadcast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('love','n.爱；热爱；爱情；爱好vt.爱，热爱；很喜欢','/lʌv/','/lʌv/','noun',["Hello love, how can I help you?","I love my spouse.   I love you!","Mold loves moist, dark places."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extension','n.伸展，延伸','/ɪkˈstɛnʃən/','/ɪkˈstɛnʃən/','noun',["Files with the .txt extension usually contain text.","a browser extension"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('signature','n.签名','/ˈsɪɡnətʃə/','/ˈsɪɡnətʃə/','noun',["Your signature must not exceed 600 pixels.","Rabbit in mustard sauce is my signature dish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steep','adj.险峻的，陡峭的','/stiːp/','/stiːp/','noun',["a steep hill or mountain; a steep roof; a steep ascent; a steep barometric gradient","Twenty quid for a shave? That''s a bit steep.","The steep rake of the windshield enhances the fast lines of the exterior. http//legacy.sandiegouniontribune.com/uniontrib/20070303/news_lz1dd3maynard.html"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seize','v.抓住','/siːz/','/siːz/','verb',["to seize a ship after libeling","a fever seized him","to seize or stop one rope on to another"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('literary','adj.文学的','/ˈlɪt(ə)ɹi/','/ˈlɪtəɹɛ(ə)ɹi/','adjective',["a literary history","a literary man"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('architect','n.建筑师；设计师','/ˈɑːkɪtɛkt/','/ˈɑɹkɪtɛkt/','noun',["Plato made the causes of things to be matter, ideas, and an efficient architect.","Peisistratus was the first architect of the Iliad and the Odyssey.","He architected the military coup against the government."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forehead','n.前额','/ˈfɒɹɛd/','/ˈfɑɹɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enjoy','v.欣赏，享受…之乐趣；喜欢','/ənˈd͡ʒɔɪ/','/ənˈd͡ʒɔɪ/','verb',["Enjoy your holidays!   I enjoy dancing.","I plan to go travelling while I still enjoy good health.","I enjoyed a lot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('privilege','n.特权，特别待遇','/ˈpɹɪv(ɪ)lɪdʒ/','/ˈpɹɪv(ɪ)lɪdʒ/','noun',["All first-year professors here must teach four courses a term, yet you''re only teaching one! What entitled you to such a privilege?","Your honor, my client is not required to answer that; her response is protected by attorney-client privilege.","to privilege representatives from arrest"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fireworks','n.烟火','/ˈfaɪ̯.ə.wɜːks/','/ˈfaɪ̯.ə.wɜːks/','noun',["Commercial firework displays are commonly launched from boats or other vessels","I left the room after John came home drunk but before the fireworks went off."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('substitute','vt.替换','/ˈsʌbstɪtjut/','/ˈsʌbstɪtjut/','noun',["I had no shallots so I substituted onion.","I had to substitute new parts for the old ones.","I had to substitute old parts with the new ones."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foreign','adj.外国的','/ˈfɒɹən/','/ˈfɔɹən/','noun',["He liked visiting foreign cities.","There are many more foreign students in Europe since the Erasmus scheme started.","foreign policy; foreign navies"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('across','prep.横过，穿过','/əˈkɹɑs/','/əˈkɹɔs/','noun',["I solved all of the acrosses, but then got stuck on 3 down.","she helped the blind man across;  the river is half a mile across","If we sail off at noon, when will we be across?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uniform','n.制服','/ˈjuːnɪfɔːm/','/ˈjunəfɚm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fall','v.落，降落；跌倒n.秋季','/fɔːl/','/fɔl/','noun',["the fall of Rome","He set up his rival to take the fall.","Have the goodness to secure the falls of the mizzen halyards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identity','n.身份；一致','/aɪˈdɛntəti/','/aɪˈdɛntəti/','noun',["I''ve been through so many changes, I have no sense of identity.","This criminal has taken on several identities.","2013 April 4, \"Cricket identities consult lawyers\", New Zealand Herald"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violate','vt.违反，干扰','/ˈvaɪəˌleɪt/','/ˈvaɪəˌleɪt/','verb',["Accessing unauthorized files violates security protocol."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('federal','adj.中央的，联邦的','/ˈfɛdəɹəl/','/ˈfɛdəɹəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('event','n.事件，大事；竞赛','/əˈvɛnt/','/əˈvɛnt/','noun',["I went to an event in San Francisco last week.","In the event, he turned out to have what I needed anyway."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('academy','n.学院','/əˈkæd.ə.mi/','/əˈkæd.ə.mi/','noun',["the military academy at West Point; a riding academy; the Academy of Music.; a music academy; a language academy"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wherever','conj.无论何处；任何地方','/wɛəˈɹɛvə/','/(h)wɛɹˈɛvɚ/','adverb',["Wherever have you been all my life?","You can sit wherever you like.","Add quotations wherever they are needed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reward','n.奖赏；报答；报酬；回报','/ɹəˈwɔːd/','/ɹiˈwɔɹd/','noun',["For catching the thief, you''ll get a nice reward.","The rewards for bringing in badly wanted criminals are printed on ''dead or alive'' posters","Is this the reward I get for telling the truth: to be put in jail?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('include','vt.包含，包括','/ɪnˈkluːd/','/ɪnˈkluːd/','noun',["I will purchase the vacation package if you will include car rental.","Does this volume of Shakespeare include his sonnets?","You have to include the strings library to use this function."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alongside','adv&prep.在旁边；沿着','/ə.lɒŋˈsaɪd/','/ə.lɔŋˈsaɪd/','adverb',["Ahoy! Bring your boat alongside mine.","The nurse worked alongside the doctor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swallow','vt.吞下；咽下n.燕子','/ˈswɒləʊ/','/ˈswɑloʊ/','noun',["He took the aspirin with a single swallow of water.","My throat was so sore that I was unable to swallow.","to swallow one''s opinions"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agency','n.代理处，经销处','/ˈeɪ.dʒən.si/','/ˈeɪ.dʒən.si/','noun',["individual agency","authority of agency","Agency for Toxic Substances and Disease Registry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abstract','adj.抽象的n.抽象；概要','/ˈæbˌstɹækt/','/ˈæbˌstɹækt/','noun',["He was wholly abstracted by other objects.","He abstracted out the square root function."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agenda','n.议程','/əˈdʒɛn.də/','/əˈdʒɛn.də/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opinion','n.看法，见解','/əˈpɪnjən/','/əˈpɪnjən/','noun',["Every man is a fool in some man''s opinion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('altogether','adv.总共','/ɔː.tuːˈɡɛð.ə(ɹ)/','/ɔl.tuˈɡɛð.ɚ/','adverb',["Altogether, I''m sorry it happened."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appearance','n.出现，露面；容貌','/əˈpɪəɹəns/','/əˈpɪɹəns/','noun',["His sudden appearance surprised me.","There was a strange appearance in the sky.","Some people say I''m shallow because I care so much about my appearance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('culture','n.文化','/ˈkʌlt͡ʃə/','/ˈkʌlt͡ʃɚ/','noun',["I''m headed to the lab to make sure my cell culture hasn''t died."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devotion','n.奉献，奉献精神','/dɪˈvəʊʃən/','/dɪˈvoʊʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prefer','vt.宁愿；更喜欢','/pɹɪˈfɜː/','/pɹɪˈfɝ/','verb',["I prefer tea to coffee."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perfect','adj.完美的，极好的','/ˈpɜː.fɛkt/','/ˈpɝfɪkt/','noun',["a perfect circle","That bucket with the hole in the bottom is a poor bucket, but it is perfect for watering plants.","Practice makes perfect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('butcher','vt.屠宰，残杀n.肉店；屠夫','/ˈbʊtʃ.ə(ɹ)/','/ˈbʊt͡ʃ.ɚ/','noun',["The band at that bar really butchered \"Hotel California\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('float','v.漂浮，浮动','/fləʊt/','/floʊt/','noun',["Attach the float and the weight to the fishing line, above the hook.","When pouring a new driveway, you can use a two-by-four as a float.","That float covered in roses is very pretty."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pole','n.杆，电线杆；极','/pɔːl/','/poʊl/','noun',["Huck Finn poled that raft southward down the Mississippi because going northward against the current was too much work.","He poled off the serial of the Gulfstream to confirm its identity.","to pole beans or hops"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minority','n.少数；少数民族','/maɪˈnɒɹ.ɪ.ti/','/maɪˈnɑɹ.ɪ.ti/','noun',["Most people agreed, but a sizable minority were upset by the decision.","The company claims it has hired several minorities since the complaint was lodged.","They hold a minority interest in the company."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tight','adj&adv.紧的','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('space','n.空白处；空地；空间；太空','/speɪs/','/speɪs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reference','n.涉及；参考；证明书','/ˈɹɛf.(ə)ɹəns/','/ˈɹɛf.(ə)ɹəns/','noun',["You must thoroughly reference your paper before submitting it.","Reference the dictionary for word meanings.","In his speech, the candidate obliquely referenced the past failures of his opponent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrange','vt.安排，布置','/əˈɹeɪndʒ/','/əˈɹeɪndʒ/','verb',["to arrange to meet;   to arrange for supper"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('from','prep.从；从…起；距；来自','/fɹɒm/','','preposition',["I got a letter from my brother.","This manuscript is from the 1980s.","Face away from the wall!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alley','n.小巷；弄堂；胡同','/ˈæ.li/','/ˈæ.li/','noun',["The parking lot to my friend''s apartment building is in the alley.","He hit one deep into the alley."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discover','vt.发现，找到','/dɪsˈkʊvə/','/dɪsˈkʌvɚ/','verb',["Turning the corner, I discovered a lovely little shop. I discovered that they sold widgets.","The gust of wind discovered a bone in the sand.","This move discovers an attack on a vital pawn."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bench','n.长凳；工作台','/bɛntʃ/','/bɛntʃ/','noun',["They sat on a park bench and tossed bread crumbs to the ducks and pigeons.","They are awaiting a decision on the motion from the bench.","She sat on the bench for 30 years before she retired."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commitment','n.承诺，许诺；保证；献身；投入','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excite','vt.刺激；使兴奋，使激动','/ɪkˈsaɪt/','/ɪkˈsaɪt/','verb',["The fireworks which opened the festivities excited anyone present.","Favoritism tends to excite jealousy in the ones not being favored.","By applying electric potential to the neon atoms, the electrons become excited, then emit a photon when returning to normal."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rhyme','v.押韵；作诗n.韵，押韵','/ɹaɪm/','/ɹaɪm/','noun',["Many editors say they don''t want stories written in rhyme.","Tennyson’s rhymes","Norse poetry is littered with rhymes like \"sól ... sunnan\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spade','n.铲子；纸牌中的黑桃','/speɪd/','/speɪd/','noun',["I''ve got only one spade in my hand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revision','n.复习，温习；修订','/riˈvɪ.ʒ(ə)n/','/riˈvɪ.ʒ(ə)n/','noun',["A revision story"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('qualification','n.资格，条件；资格证书','/ˌkwɒlɪfɪˈkeɪʃən/','/ˌkwɒlɪfɪˈkeɪʃən/','noun',["Qualification for this organization is extraordinarily difficult.","What are your qualifications for this job?","I accept your offer, but with the following qualification."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collision','n.碰撞；冲突','/kəˈlɪʒən/','/kəˈlɪʒən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bridegroom','n.新郎','/ˈbɹaɪdˌɡɹuːm/','/ˈbɹaɪdˌɡɹuːm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repair','vt.修理，修补；纠正；恢复n.修理，修补','/ɹɪˈpɛə/','/ɹəˈpɛɚ/','noun',["I took the car to the workshop for repair.","If you look closely you can see the repair in the paintwork.","The car was overall in poor repair before the accident. But after the workshop had it for three weeks it was returned in excellent repair. But the other vehicle was beyond repair."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advice','n.忠告，劝告，建议','/ədˈvaɪs/','/ædˈvaɪs/','noun',["She was offered various piece of advice on what to do with her new-found wealth.","late advices from France","An advice of an incoming settlement payment order may be given to an off-line receiving bank."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frequent','adj.经常的，频繁的','/ˈfɹiː.kwənt/','/ˈfɹiː.kwənt/','adjective',["I am a frequent visitor to that city."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insure','v.确保；给…保险','/ɪnˈʃɔː/','/ɪnˈʃʊɚ/','verb',["I use an alarm clock to ensure that I get up on time.","I''m not insured against burglary."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elder','adj.年长的n.长者，前辈','/ˈeldə/','/ˈeldə/','noun',["We were presented to the village elder.","Respect your elders.","a travelling elder"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('error','n.错误','/ˈɛɹə(ɹ)/','/ˈɛɹɚ/','noun',["Remove that line of code and the script should stop erroring there.","The block transmission errored near the start and could not be received."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('windy','adj.多风的','/ˈwɪndi/','/ˈwɪndi/','noun',["It was a long and windy night.","They made love in a windy bus shelter.","They made windy promises they would not keep."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Oceania','n.大洋洲','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('public','adj.公共的，公众的，国家的n.公众','/ˈpʌblɪk/','/ˈpʌblɪk/','noun',["Members of the public may not proceed beyond this point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spend','vt.度过；花费','/spɛnd/','/spɛnd/','noun',["I’m sorry, boss, but the advertising spend exceeded the budget again this month.","He spends far more on gambling than he does on living proper.","to spend an estate in gambling"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barbershop','n.理发店','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('track','n.小道；足迹；轨道','/tɹæk/','/tɹæk/','noun',["Can you see any tracks in the snow?","The fox tracks were still visible in the snow.","Follow the track for a hundred metres."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('value','n.价值，益处vt.估价，评价','/ˈvæljuː/','/ˈvæljuː/','noun',["The Shakespearean Shylock is of dubious value in the modern world.","The value of my children''s happiness is second only to that of my wife.","He does not share his parents'' values."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foggy','adj.有雾的，多雾的','','','adjective',["He was still foggy with sleep."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quantity','n.数量','/ˈkwɒn.tɪ.ti/','/ˈkwɑn(t)ɨti/','noun',["You have to choose between quantity and quality.","Olive oil can be used practically in any quantity.","Generally it should not be used in a quantity larger than 15 percent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fortune','n.财产；运气','/ˈfɔːtʃuːn/','/ˈfɔːtʃuːn/','noun',["She read my fortune. Apparently I will have a good love life this week, but I will have a bad week for money.","Fortune favors the brave.","He''s amassed a small fortune working in the Middle East."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advantage','n.优点，好处','/ədˈvɑːn.tɪdʒ/','/ədˈvæn.tɪdʒ/','noun',["The enemy had the advantage of a more elevated position.","Having the faster car is of little advantage."]);
