INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('command','n&v.命令','/kəˈmɑːnd/','/kəˈmænd/','noun',["I was given a command to cease shooting.","to have command of an army","England has long held command of the sea"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expensive','adj.昂贵的，高消费的','/ɛkˈspɛnsɪv/','/ɛkˈspɛnsɪv/','adjective',["an unnecessarily expensive choice of algorithm"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cloudy','adj.多云的，阴天的','/ˈklaʊːdɪ/','/ˈkɫaʊdi/','adjective',["a cloudy infrastructure"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compulsory','adj.必修的；义务的','/kəmˈpʌlsəri/','/kəmˈpʌlsəri/','noun',["The ten-dollar fee was compulsory.","Such compulsory measures are limited."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trade','n.贸易vt.买卖','/tɹeɪd/','/tɹeɪd/','noun',["I did no trades with them once the rumors started.","The skilled trades were the first to organize modern labor unions.","It is not a retail showroom. It is only for the trade."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dessert','n.甜点，甜食','/dɪˈzɜːt/','/dɪˈzɝt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('round','adv.转过来adj.圆的，球形的prep.环绕一周，围着','/ˈɹaʊnd/','/ˈɹaʊnd/','adverb',["High above, vultures circled around.","Everybody please gather around.","An adult elephant weighs around five tons."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambassador','n.大使','/æmˈbæs.ə.də(ɹ)/','/æmˈbæs.ə.də(ɹ)/','noun',["As front hall porter, you are an ambassador for the hotel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('non-stop','adj&adv.不停的，不断的','','','noun',["There''s a nonstop flight to Mauritius, but I''m not sitting on the same plane for thirteen hours.","He worked nonstop for fourteen hours yesterday, just so he could get today off."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temple','n.庙宇，寺院','/ˈtɛmp(ə)l/','/ˈtɛmp(ə)l/','noun',["a temple of commerce, a temple of drinking and dining","My body is my temple."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('growth','n.生长；增长','/ɡɹəʊθ/','/ɡɹoʊθ/','noun',["Growth was dampened by a softening of the global economy in 2001, but picked up in the subsequent years due to strong growth in China."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vague','adj.含糊的，不清楚的','/veɪɡ/','/veɪɡ/','noun',["a vague term of abuse","I haven’t the vaguest idea.","a vague longing"]);
