INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awful','adj.糟糕的，可怕的','/ˈɔːfəl/','/ˈɔfəl/','adjective',["My socks smell awful.","I have learnt an awful amount today.","He was blubbering away something awful."]);
