INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graduate','v.毕业n.毕业生；研究生','','','noun',["If the government wants graduates to stay in the country they should offer more incentives.","The man graduated in 1967.","Trisha graduated college."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visual','adj.视力的，视觉的','/ˈvɪʒuəl/','/ˈvɪʒuəl/','noun',[]);
