INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rag','n.破布，抹布','/ɹæɡ/','/ɹæɡ/','noun',["I have ace-four on my hand. In other words, I have ace-rag."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('because','conj.因为','/bɪˈkɒz/','','adverb',["My life is ruined because of you!","I hid myself because I was afraid.","I don''t think he is a nice person, because he yells at people for no reason."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('near','adv.附近，邻近adj.近的prep.在…附近，靠近','/nɪə(ɹ)/','/nɪɹ/','noun',["The ship nears the land.","I can''t see near objects very clearly without my glasses.","The end is near."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('educate','v.教育，培养','/ˈɛdjʊkeɪt/','/ˈɛdʒəkeɪt/','verb',["Wang said such changes to the Baishui glacier provide the chance to educate visitors about global warming."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ashamed','adj.惭愧的，害臊的，羞耻的','/əˈʃeɪmd/','/əˈʃeɪmd/','verb',[]);
