INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruct','v.指示；教导；通知','/ˌɪnˈstɹʌkt/','/ˌɪnˈstɹʌkt/','noun',["Listen carefully when someone instructs you how to assemble the furniture.","The doctor instructed me to keep my arm immobilised and begin physiotherapy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excellent','adj.极好的，优秀的','/ˈɛksələnt/','','adjective',["Bill and Ted had an excellent adventure last week in preparation of their history exam."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fairly','adv.相当；还算；公正地','/ˈfɛə(ɹ).li/','/ˈfɛɹ.li/','adverb',["A jury is expected to ensure that the accused is fairly judged.","a town fairly situated for foreign trade","Consumer laws aim to have consumers fairly treated."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handwriting','n.书法','/ˈhændɹaɪtɪŋ/','/ˈhændɹaɪtɪŋ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('raw','adj.生的；未加工的','/ɹɔː/','/ɹɔː/','noun',["raw cane sugar","a raw wound","a raw beginner"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merchant','adj.商业的，商人的n.商人，生意人','/ˈmɜːtʃənt/','/ˈmɝtʃənt/','noun',["a merchanting service"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retell','vt.重讲，重复，复述','/ɹiˈtɛl/','/ɹiˈtɛl/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ray','n.光辉，光线','/ɹeɪ/','/ɹeɪ/','noun',["I saw a ray of light through the clouds.","Unfortunately he didn''t have a ray of hope."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('version','n.译文；版本','/ˈvɜːʃən/','/ˈvɝʒən/','noun',["It''s only in the King James Version of the Bible.","He gave another version of the affair.","Upgrade to the latest version for new features and bug fixes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exam','n.考试，测试；检查','/ɛɡˈzæm/','/ɛɡˈzæm/','noun',["He examined the crime scene for clues.","The doctor examined the patient.","The witness was examined under oath."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stop','vt.停止；阻止n.停；站','/stɒp/','/stɑp/','noun',["They agreed to meet at the bus stop.","That stop was not planned.","door stop"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nationality','n.国籍；民族','/-ˈnæl.ti/','/-ˈnæl.ti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guess','v.猜，猜测；认为','/ɡɛs/','/ɡɛs/','verb',["He who guesses the riddle shall have the ring.","That album is quite hard to find, but I guess you could try ordering it online.","\"I guess I''ll go to bed.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adolescence','n.青春期','/ˌædəˈlɛsəns/','/ˌædəˈlɛsəns/','noun',["During adolescence, the body and mind go through many complex changes, some of which are difficult to deal with."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aboard','prep&adv.在船上，上船','/əˈbɔːd/','/əˈbɔɹd/','adverb',["We all climbed aboard.","To sling a saddle aboard.","He doubled with two men aboard, scoring them both."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('institute','v.建立，设立n.协会；学院','/ˈɪnstɪt(j)uːt/','/ˈɪnstɪt(j)uːt/','noun',["I work in a medical research institute."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poster','n.海报，广告','/ˈpoʊstɚ/','/ˈpoʊstɚ/','noun',["He has posters of his favorite band, sports teams and holiday resorts up.","I saw a poster for the film on the side of a bus.","Some posters left the online message board after the squabble."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shortly','adv.不久','/ʃɔːɹtli/','/ʃɔːɹtli/','adverb',["Ideas are generally expressed more shortly in verse than in prose"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appropriate','adj.适当的','','','verb',["Let no man appropriate the use of a common benefit.","A spot of ground is appropriated for a garden.","The headmaster wondered what an appropriate measure would be to make the pupil behave better."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('criterion','n.标准，规则','/kɹaɪˈtɪəɹi.ən/','/kɹaɪˈtɪəɹi.ən/','noun',["Criterion of choice, of decision, of selection"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('least','n.最少，最少量','/list/','/list/','noun',["It was the least surprising thing.","They travel the least of all."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immediately','adv.立即','/əˈmiːdi.ətli/','/əˈmiːdi.ətli/','adverb',["I hope we can begin immediately."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symphony','n.交响乐','/ˈsɪm.fə.ni/','/ˈsɪm.fə.ni/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optimistic','adj.乐观的','/ˌɒptɪˈmɪstɪk/','/ˌɒptɪˈmɪstɪk/','adjective',["in an optimistic mood","optimistic concurrency"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleep','n&vi.睡觉','/sliːp/','/slip/','verb',["You should sleep 8 hours a day.","This caravan can sleep four people comfortably.","to sleep a dreamless sleep"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vocabulary','n.词汇，词汇表','/vəʊˈkabjʊləɹɪ/','/voʊˈkæbjəlɛɹi/','noun',["My Russian vocabulary is very limited.","The vocabulary of social sciences is often incomprehensible to ordinary people.","The vocabulary of any language is influenced by contacts with other cultures."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refuse','v.拒绝，不愿','/ˈɹɛfjuːs/','/ˈɹɛfjuːs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aspect','n.方面；外表','/ˈæspɛkt/','/ˈæspɛkt/','noun',["Japan''s aging population is an important aspect of its economy.","The house has a southern aspect, i.e. a position which faces the south."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aggressive','adj.侵略的；咄咄逼人的','/əˈɡɹɛs.ɪv/','/əˈɡɹɛs.ɪv/','adjective',["an aggressive policy, war, person, nation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('close','adv.近，靠近adj.近的；亲密的v.关，关闭','/kləʊz/','/kloʊz/','noun',["We owe them our thanks for bringing the project to a successful close."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweep','vt.扫除，打扫','/swiːp/','/swiːp/','noun',["Give the front steps a quick sweep to get rid of those fallen leaves.","Bradman attempted a sweep, but in fact top edged the ball to the wicket keeper","Jim will win fifty dollars in the office sweep if Japan wins the World Cup."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('website','n.网站','/ˈwɛbˌsaɪt/','/ˈwɛbˌsaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('learn','vi.学，学习；得知，获悉vt.学，学习，学会，得知','/lɜːn/','/lɝn/','noun',["learn from one''s mistakes","I learn medicine.","He just learned that he will be sacked."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swing','v.挥舞，摆动n.秋千','/ˈswɪŋ/','/ˈswɪŋ/','noun',["Door swing indicates direction the door opens.","The plant swung in the breeze.","The children laughed as they swung."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ridiculous','adj.荒谬的，可笑的','/ɹiːˈdɪkjʊləs/','/ɹiːˈdɪkjʊləs/','adjective',["It''s ridiculous to charge so much for a little souvenir.","Gaines is a classic motor player with a low center of gravity and ridiculous strength."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('severe','adj.严重的','/sɪˈvɪə/','','adjective',["a severe taskmaster","a severe old maiden aunt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spin','vt.纺纱；旋转n.旋转','/spɪn/','/spɪn/','noun',["He put some spin on the cue ball.","The politician was mocked in the press for his reliance on spin rather than facts.","I''m off out for a spin in my new sports car."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grocery','n.杂货；食品；食品杂货店','/ˈɡɹəʊs(ə)ɹi/','/ˈɡɹəʊs(ə)ɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communism','n.共产主义','/ˈkɒm.juˌnɪzm̩/','/ˈkɒm.juˌnɪzm̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spit','v.吐唾沫；吐痰','/spɪt/','/spɪt/','noun',["to spit a loin of veal","She’s spitting the roast in the kitchen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anniversary','n.周年纪念','/ˌænɪˈvɜːs(ə)ɹi/','/ˌænəˈvɝs(ə)ɹi/','noun',["Today is the fiftieth anniversary of the end of the war."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('register','v.登记，注册n.记录，登记簿','/ˈɹɛdʒ.ɪs.tə/','/ˈɹɛdʒ.ɪs.tɚ/','noun',["The teacher took the register by calling out each child''s name.","a register of deeds","My ex-boss used \"let go\", in the euphemistic register, when he sacked me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('couple','n.夫妇；对，双','/ˈkʌpəl/','/ˈkʌpəl/','noun',["I''ve coupled our system to theirs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communicate','v.交际；传达；通信','/kəˈmjuːnɪkeɪt/','/kəˈmjuːnɪkeɪt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eager','adj.渴望的，热切的','/ˈiːɡə/','/ˈiɡɚ/','adjective',["I was eager to show my teacher how much I''d learned over the holidays.","an eager algorithm"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evidence','n.证据','[ˈɛvəɾəns]','[ˈɛvəɾəns]','noun',["There is no evidence that anyone was here earlier.","She was furious, as evidenced by her slamming the door."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('republic','n.共和国','[ɹɪˈpʌblɪk]','[ɹɪˈpʌblɪk]','noun',["The United States is a republic; the United Kingdom of Great Britain and Northern Ireland is a constitutional monarchy.","The Republic of Udmurtia is west of the Permian Oblast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('official','adj.官方的，政府的；公务的n.官员；高级职员','/əˈfɪʃəl/','/əˈfɪʃəl/','noun',["David Barnes was the official charged with the running of the sports club.","In most soccer games there are three officials: the referee and two linesmen.","official duties"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acid','adj.酸的','/ˈæs.ɪd/','/ˈæs.ɪd/','noun',["acid fruits or liquors"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assessment','n.估价；评价','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('post','n.岗位，职位；邮政，邮寄，邮件vt.投寄；邮寄；发布','/pəʊst/','/poʊst/','noun',["ram a post into the ground","Post no bills.","to post someone for cowardice"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agricultural','adj.农业的','/ˌæɡɹɪˈkʌltjʊəɹəl/','/ˌæɡɹɪˈkʌlt͡ʃəɹəl/','noun',["An agricultural tool"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leave','v.离开；留下；遗忘','/liːv/','/liv/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duck','v.躲避；浸入水中n.鸭子','/dʌk/','/dʌk/','verb',["I''m just going to duck into the loo for a minute, can you hold my bag?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cottage','n.小屋；村舍；小别墅','/ˈkɒtɪdʒ/','/ˈkɑtədʒ/','noun',["Most cottages in the area were larger and more elaborate than my home."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tiresome','adj.令人厌烦的，讨厌的','/ˈtaɪəsəm/','/ˈtaɪəsəm/','adjective',["Eventually his long stories became tiresome."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finish','v.结束，做完','/ˈfɪnɪʃ/','/ˈfɪnɪʃ/','noun',["The car''s finish was so shiny and new.","Be sure to finish your homework before you go to bed!","The furniture was finished in teak veneer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discrimination','n.歧视','/dɪskɹɪmɪˈneɪʃən/','/dɪskɹɪmɪˈneɪʃən/','noun',["reverse discrimination"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('female','adj.女性的，雌性的n.女性，女人','/ˈfiː.meɪl/','/ˈfiː.meɪl/','noun',["female authors, the leading male and female artists, a female bird cooing at a male, intersex female patients, a trans female vlogger","stereotypically female pastimes, an insect with typically female coloration","the female chromosome;   estrogen, the primary female sex hormone, is produced by both females and males"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melon','n.甜瓜','/ˈmɛlən/','/ˈmɛlən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swift','adj.快的，迅速的','/swɪft/','/swɪft/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('add','v.添加，增加','/æd/','/æd/','noun',["When the player has fought the boss for one minute, two adds will arrive from the back and must be dealt with.","to add numbers","to add a column of numbers"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minister','n.部长；牧师','/ˈmɪnɪstə/','/ˈmɪnɨstɚ/','noun',["The minister said a prayer on behalf of the entire congregation.","He was newly appointed to be Minister of the Interior."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('need','v.必须vt.需要modaln.需要，需求','/niːd/','/niːd/','noun',["I''ve always tried to have few needs beyond food, clothing and shelter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cruel','adj.残忍的，残酷的；无情的','/kɹuː(ə)l/','/kɹuː(ə)l/','verb',["The supervisor was very cruel to Josh, as he would always give Josh the hardest, most degrading work he could find."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erupt','v.喷发，爆发','/ɪˈɹʌpt/','/ɪˈɹʌpt/','verb',["The volcano erupted, spewing lava across a wide area.","The third molar tooth erupts late in most people, and sometimes does not appear at all.","The crowd erupted in anger."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shade','n.阴凉处，树荫处','/ʃeɪd/','/ʃeɪd/','noun',["The old oak tree gave shade in the heat of the day.","Close the shade, please: it''s too bright in here.","I''ve painted my room in five lovely shades of pink and chartreuse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('often','adv.经常地','/ˈɑf(t)ən/','/ˈɔf(t)ən/','adjective',["I often walk to work when the weather is nice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gather','v.聚集；采集','/ˈɡæðə/','/ˈɡæðɚ/','noun',["I''ve been gathering ideas from the people I work with.","She gathered the shawl about her as she stepped into the cold.","From his silence, I gathered that things had not gone well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insist','v.坚持，坚决认为','/ɪnˈsɪst/','/ɪnˈsɪst/','verb',["I insist that my secretary dresses nicely.","I insist that my secretary dress nicely."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('article','n.文章；东西；冠词','/ˈɑːtɪkəl/','/ˈɑɹtəkl̩/','noun',["a sales article","The Articles of War are a set of regulations to govern the conduct of military forces","Each of the chelicerae is composed of two articles, forming a powerful pincer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respect','n.尊敬，尊重；方面vt.尊敬，尊重','/ɹɪˈspɛkt/','/ɹɪˈspɛkt/','noun',["He is an intellectual giant, and I have great respect for him.","The mourners paid their last respects to the deceased poet.","This year''s model is superior to last year''s in several respects."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ache','vi.疼痛n.痛，疼痛','/eɪk/','/eɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loose','adj.松散的；宽松的','/luːs/','/luːs/','noun',["This wheelbarrow has a loose wheel.","''You can buy apples in a pack, but they are cheaper loose.","The dog is loose again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('therefore','adv.因此，所以','/ˈðɛəfɔː/','/ˈðɛəɹfɔɹ/','adverb',["Traditional values will always have a place, therefore they will never lose relevance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exchange','n&v.交换；交流；兑换','/ɛksˈtʃeɪndʒ/','/ɛksˈtʃeɪndʒ/','noun',["All in all, it was an even exchange.","The stock exchange is open for trading.","NPA-NXX-1234 is standard format, where NPA is the area code and NXX is the exchange."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjustment','n.调整，调节；校正','/əˈdʒʌst.mənt/','/əˈdʒʌst.mənt/','noun',["The credit card company made an adjustment to my account to waive the late fee.","When Jim graduated, he found adjustment to the working world difficult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hesitate','v.犹豫，踌躇','/ˈhɛzɪteɪt/','/ˈhɛzɪteɪt/','verb',["He hesitated whether to accept the offer or not; men often hesitate in forming a judgment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardly','adv.几乎不','/ˈhɑːdli/','/ˈhɑɹdli/','adverb',["I can''t really deal hardly with people.","they hardly ever watch television;  I hardly think they''ll come in this bad weather;  it''s hardly possible he could lose the election.","I think the Beatles are a really overrated band. ― Hardly!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bored','adj.无聊的，厌烦的','/bɔːd/','/bɔːd/','verb',["An insect bores into a tree.","to bore a steam cylinder or a gun barrel; to bore a hole","to bore one''s way through a crowd"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trust','vt&n.相信，信任，信赖','/trʊst/','/trʌst/','noun',["He needs to regain her trust if he is ever going to win her back.","I was out of cash, but the landlady let me have it on trust.","I put the house into my sister''s trust."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('income','n.收入，所得','/ˈɪnˌkʌm/','/ˈɪnˌkʌm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('private','adj.私人的；私营的；秘密的','/ˈpɹaɪvət/','/ˈpɹaɪvət/','noun',["If you want to learn ballet, consider taking privates.","Her address is private; you can''t have it.","private property"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technical','adj.技术的，工艺的','/ˈtɛk.nɪk.əl/','/ˈtɛk.nɪk.əl/','noun',["The performance showed technical virtuosity, but lacked inspiration.","The market had a technical rally, due to an oversold condition.","Crossing the front lawn of that house to get to the mailbox was a technical trespass."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('companion','n.同伴，同事','/kəmˈpænjən/','/kəmˈpænjən/','noun',["His dog has been his trusted companion for the last five years.","The companion guide gives an in-depth analysis of this particular translation.","a companion of the Bath"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choose','vt.选择；决定','/t͡ʃuːz/','/t͡ʃuːz/','verb',["I chose a nice ripe apple from the fruit bowl.","He was chosen as president in 1990.","I chose to walk to work today."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('directory','n.姓名地址录；公司名录','/daɪˈɹɛktəɹi/','/daɪˈɹɛktəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peaceful','adj.和平的，安宁的','/ˈpiːsfəl/','/ˈpiːsfəl/','adjective',["peaceful protest"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prevent','v.防止，阻止','/pɹəˈvɛnt/','/pɹəˈvɛnt/','verb',["I brush my teeth regularly to prevent them from turning yellow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behave','v.表现；行为得体','/bəˈheɪv/','/bəˈheɪv/','verb',["You need to behave yourself, young lady.","He behaves like a child whenever she''s around.","His mother threatened to spank him if he didn''t behave."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accomplish','vt.完成，达到','/əˈkɐm.plɪʃ/','/əˈkɑm.plɪʃ/','verb',["to accomplish a design, an object, a promise"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disturbing','adj.令人不安的；引起烦恼的','/dɪsˈtɜːbɪŋ/','/dɪsˈtɜːbɪŋ/','verb',["A school of fish disturbed the water.","A mudslide disturbed the course of the river.","A disturbing film that tries to explore the mind of a serial killer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engine','n.发动机，引擎','/end͡ʒən/','/ˈɛnd͡ʒɪn/','noun',["a graphics engine","Vessels are often built by one firm and engined by another."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('photographer','n.摄影师','/fəˈtɒɡɹəfə/','/fəˈtɒɡɹəfə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('end','v.结束，终止n.终点；结束','/ɛnd/','/ɛnd/','noun',["At the end of the road, turn left.","Is there no end to this madness?","He met a terrible end in the jungle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mistake','v.弄错n.错误','/mɪˈsteɪk/','/mɪˈsteɪk/','noun',["Don''t mistake my kindness for weakness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pour','v.倾泻，不断流出','/pɔː/','/pɔɹ/','noun',["The bartender''s inexpert pour left me with a pint of beer that was half foam.","pour water from a jug","the rain poured down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('message','n.消息，留言；要旨','/ˈmɛsɪd͡ʒ/','/ˈmɛsɪd͡ʒ/','noun',["We''ve just received an urgent message from the President.","The main message of the novel is that time heals all wounds.","I messaged her about the concert."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('praise','n&vt.赞扬，表扬','/pɹeɪz/','/pɹeɪz/','noun',["Be sure to praise Bobby for his excellent work at school this week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('significance','n.意义，重要性','/sɪɡˈnɪfɪkəns/','/sɪɡˈnɪfɪkəns/','noun',["As a juror your opinion is of great significance for the outcome of the trial.","the significance of a gesture"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('special','adj.特别的；专门的','/ˈspɛ.ʃəl/','/ˈspɛ.ʃəl/','noun',["We''re running a special on turkey for Thanksgiving.","Today''s special is our tuna melt on rye.","Did you see the Christmas special?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scissors','n.剪刀','/ˈsɪzəz/','/ˈsɪzɚz/','noun',["The erroneous testimony was scissored from the record.","The runner scissored over the hurdles.","Scissors are used to cut the flowers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('environment','n.环境','/-mɪnt/','/-mɪnt/','noun',["That program uses the Microsoft Windows environment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('truth','n.事实；真理','/tɹuːθ/','/tɹuːθ/','noun',["The truth is that our leaders knew a lot more than they were letting on.","There was some truth in his statement that he had no other choice.","Truth to one''s own feelings is all-important in life."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clone','n&v.克隆，无性繁殖','/kləʊn/','/kloʊn/','noun',["The scientists were able to clone a sheep."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('betray','vt.出卖，背叛','/bəˈtɹeɪ/','/bəˈtɹeɪ/','verb',["an officer betrayed the city","My eyes have been betraying me since I turned sixty.","Though he had lived in England for many years, a faint accent betrayed his Swedish origin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pronounce','v.发音','/pɹəˈnaʊns/','/pɹəˈnaʊns/','verb',["I hereby pronounce you man and wife.","The doctor pronounced them legally dead.","The judge had pronounced often before, but never in front of such a crowd."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('family','n.家；家人','/ˈfæm(ɪ)li/','/ˈfæm(ə)li/','noun',["Our family lives in town.","1915, William T. Groves, A History and Genealogy of the Groves Family in America","Our company is one big happy family."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swear','v.发誓，诅咒','/swɛə/','/swɛɚ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gift','n.赠品；礼物；天赋，才能','/ɡɪft/','/ɡɪft/','noun',["She had a gift for playing the flute.","The office is in the gift of the President."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('atmosphere','n.气氛；大气','/ˈæt.məsˌfɪə(ɹ)/','/ˈætməsˌfɪɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decorate','v.装饰，修饰','/ˈdɛkəɹeɪt/','/ˈdɛkəɹeɪt/','verb',["We decorated the Christmas tree with tinsel and baubles.","There''s some paint left over from when we decorated the guest bedroom.","People tend to decorate for the holidays or special events."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('education','n.教育，培养','/ˌɛdjʊˈkeɪʃn̩/','/ˌɛdjʊˈkeɪʃn̩/','noun',["2016-06-17 AROP JOSEPH \"Education is the slight hammer that breaks the yoke of ignorance, and moulds knowledge, skills, ideas, good moral values in a person be it a child, a youth or full grown adult. no matter a persons age learning never stops\".","He has had a classical education."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occupation','n.职业，工作；占领，占据','/ɒkjəˈpeɪʃən/','/ɑkjəˈpeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tendency','n.[C]倾向，趋势','/ˈtɛndənsi/','/ˈtɛndənsi/','noun',["Denim has a tendency to fade."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slim','adj.苗条的，纤细的','/slɪm/','/slɪm/','noun',["I only smoke slims.","I''m afraid your chances are quite slim.","A slimly-shod lad;"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arithmetic','n.算术','','','noun',["arithmetic geometry","arithmetic progression"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('caption','n.标题；字幕','/ˈkæp.ʃən/','/ˈkæp.ʃən/','noun',["Only once the drawing is done will the letterer caption it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rid','vt.使…摆脱','/ˈɹɪd/','/ˈɹɪd/','verb',["We''re trying to rid the world of poverty.","I’m glad to be rid of that stupid nickname."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moral','adj.道德的，精神的n.道德；寓意','/ˈmɒɹəl/','/ˈmɑɹəl/','noun',["a candidate with strong morals","moral judgments;  a moral poem","a moral obligation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('number','n.数字，号码；数量','/ˈnʌmbə/','/ˈnʌmbə/','noun',["Zero, one, −1, 2.5, and pi are all numbers.","The number 8 is usually made with a single stroke.","The equation e^{i\\pi}+1=0 includes the most important numbers: 1, 0, \\pi, i, and e."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explode','v.爆炸；爆发','/ɪkˈspləʊd/','/ɪkˈsploʊd/','verb',["The assassin exploded the car by means of a car bomb.","They sought to explode the myth.","Explode the assembly drawing so that all the fasteners are visible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greengrocer','n.蔬菜水果商','/ˈɡɹinˌɡɹəʊs.ə(ɹ)/','/ˈɡɹinˌɡɹəʊs.ə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punish','vt.惩罚，处罚','/ˈpʌnɪʃ/','/ˈpʌnɪʃ/','verb',["If a prince violates the law, then he must be punished like an ordinary person."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('casual','adj.偶然的，不经意的；非正式的；临时的','/ˈkɛʒɘl/','/ˈkɛʒɘl/','noun',["The devs dumbed the game down so the casuals could enjoy it.","They only had casual meetings.","The purchase of donuts was just a casual expense."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decline','v.下降；衰败；倾斜；谢绝','/dɪˈklaɪn/','/dɪˈklaɪn/','noun',["The dollar has declined rapidly since 2001.","My health declined in winter.","a line that declines from straightness"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('narrow','adj.狭窄的','/ˈnæɹəʊ/','/ˈnæɹoʊ/','noun',["the narrows of New York harbor","a narrow hallway","a narrow interpretation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('judge','v.判断，评价n.裁判，法官','/d͡ʒʌd͡ʒ/','/d͡ʒʌd͡ʒ/','noun',["At a boxing match, the decision of the judges is final.","She is a good judge of wine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('similar','adj.相似的，像','/ˈsɪmələ/','/ˈsɪməlɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contradict','v.同…矛盾，同…抵触','/kɒntɹəˈdɪkt/','/kɒntɹəˈdɪkt/','verb',["His testimony contradicts hers.","Everything he says contradicts me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Catholic','adj.天主教的','/ˈkaθ(ə)lɪk/','/ˈkæθ(ə)lɪk/','adjective',["Christmas is celebrated at different dates in the Catholic and Orthodox calendars.","Catholic churches are built differently than Protestant ones."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shape','n.形状，外形vt.使成形；制造，塑造','/ʃeɪp/','/ʃeɪp/','noun',["The used bookshop wouldn''t offer much due to the poor shape of the book.","The vet checked to see what kind of shape the animal was in.","He cut a square shape out of the cake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nothing','pron.没有东西，没有什么；无关紧要的东西','/ˈnʌθɪŋ/','/ˈnʌθɪŋ/','noun',["You''re nothing to me now!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headmistress','n.女校长','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyhow','adv.不管怎样','/ˈæn.i.haʊ/','/ˈæn.i.haʊ/','adverb',["Anyhow, he is dead now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whistle','v.鸣笛，吹口哨n.口哨声；汽笛声','/wɪsl̩/','/wɪsl̩/','noun',["the whistle of the wind in the trees","Never whistle at a funeral.","The stream train whistled as it passed by."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handle','vt.处理n.柄，把手','/ˈhæn.dl/','/ˈhæn.dl/','noun',["The daily handle of a Las Vegas casino is typically millions of dollars.","The successful businessman was knighted and acquired a handle to his name.","This article describes how to find the module name from the window handle."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chain','storesn.连锁店','/ˈt͡ʃeɪn/','/ˈt͡ʃeɪn/','noun',["He wore a gold chain around the neck.","This led to an unfortunate chain of events.","That chain of restaurants is expanding into our town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crossing','n.十字路口；人行横道','/ˈkɹɑsɪŋ/','/ˈkɹɔsɪŋ/','verb',["They managed to cross a sheep with a goat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tough','adj.结实的；棘手的','/tʌf/','/tʌf/','noun',["They were doing fine until they encountered a bunch of toughs from the opposition.","The tent, made of tough canvas, held up to many abuses.","To soften a tough cut of meat, the recipe suggested simmering it for hours."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exit','n.出口','/ˈɛksɪt/','/ˈɛksət/','noun',["He made his exit at the opportune time.","the untimely exit of a respected politician"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('system','n.体系，系统','/ˈsɪstəm/','/ˈsɪstəm/','noun',["There are eight planets in the solar system.","Followers should have a system to follow that works in their interests, not against them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('giraffe','n.长颈鹿','/dʒɪˈɹɑːf/','/d͡ʒəˈɹæf/','noun',["Are you having a giraffe?!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spot','n.斑点，污点；场所，地点vt.沾上污渍，弄脏；认出，发现','/spɒt/','/spɑt/','noun',["The leopard is noted for the spots of color in its fur.","I have tried everything, and I can’t get this spot out.","I think she''s got chicken pox; she''s covered in spots."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aid','v.帮助n.援助，救护；辅助器具','/eɪd/','','noun',["He came to my aid when I was foundering.","Slimming aids include dietary supplements and appetite suppressants.","The incompetent general''s brilliant aid often made priceless suggestions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('other','pron&adj.其他的，另外的','/ʊðə/','/ˈʌðɚ/','noun',["I''m afraid little Robbie does not always play well with others.","One boat is not better than the other.","I get paid every other week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aim','v.计划；瞄准；针对n.目的','/eɪm/','/eɪm/','noun',["Take time with the aim of your gun.","My number one aim in life is to make money to make my parents, siblings and kids happy.","The police officer has excellent aim, always hitting the bullseye in shooting practice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('against','prep.对着；反对','/əˈɡeɪnst/','/əˈɡɛnst/','preposition',["It is hard work to swim against the current.","The rain pounds against the window.","The kennel was put against the back wall."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confident','adj.自信的；确信的','/ˈkɒn.fɪ.dənt/','/ˈkɑn.fɪ.dənt/','noun',["I''m pretty confident that she''s not lying, she''s acting normally."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cell','n.细胞；蜂房；电池','/sɛl/','/sɛl/','noun',["Gregor Mendel must have spent a good amount of time outside of his cell.","The combatants spent the night in separate cells.","This MP3 player runs on 2 AAA cells."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swell','v.肿胀，增大','/swɛl/','/swɛl/','verb',["Rains and dissolving snow swell the rivers in spring.","The organ music swelled.","to be swelled with pride or haughtiness"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('courage','n.勇气，胆略','/ˈkʌɹɪdʒ/','/ˈkɝɹɪdʒ/','noun',["It takes a lot of courage to be successful in business.","He plucked up the courage to tell her how he felt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('local','adj.当地的，地方的','/ˈləʊkl̩/','/ˈloʊkl̩/','noun',["It''s easy to tell the locals from the tourists.","I''m in the TWU, too. Local 6.","The expresses skipped my station, so I had to take a local."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remind','vt.提醒，使记起','/ɹəˈmaɪnd/','/ɹəˈmaɪnd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crew','n.全体人员','','','verb',["He’s been crowing all day about winning the game of cards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valid','adj.有效的','/ˈvælɪd/','/ˈvælɪd/','adjective',["I will believe him as soon as he offers a valid answer.","A valid format for the date is MM/DD/YY.","An argument is valid if and only if the set consisting of both (1) all of its premises and (2) the contradictory of its conclusion is inconsistent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defeat','vt.击败；战胜','/dɪˈfiːt/','/dɪˈfiːt/','verb',["Wellington defeated Napoleon at Waterloo."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spear','n.矛','/spɪɹ/','/spɪɹ/','noun',["asparagus and broccoli spears","a spear counterpart","the spear side of the family"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encourage','vt.鼓励，激励','/ɪnˈkʌɹɪdʒ/','/ɪnˈkɝɹɪdʒ/','verb',["I encouraged him during his race.","We encourage the use of bicycles in the town centre.","The royal family has always encouraged the arts in word and deed"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electronic','adj.电子的','/ɪˌlɛkˈtɹɒn.ɪk/','/ɪˌlɛkˈtɹɑn.ɪk/','adjective',["electronic music"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacation','n.假期，休假','/veɪˈkeɪʃ(ə)n/','/veɪˈkeɪʃən/','noun',["The Conservative Party’s vacation of the centre ground gave an opportunity to its opponents.","This year, we’re vacationing in Mexico."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speak','v.说，讲；谈话；发言','/spiːk/','/spik/','noun',["Corporate speak; IT speak.","I was so surprised I couldn''t speak.","It''s been ages since we''ve spoken."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('share','v.分享，共同使用n.一份；股份','/ʃɛə/','/ʃɛəɹ/','noun',["Upload media from the browser or directly to the file share.","to share a shelter with another;  They share a language.","He shared his story with the press."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bureaucratic','adj.官僚政治的','','','adjective',["the European Union is legalistic, bureaucratic and runs by precedent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacred','adj.宗教的；庄严的，神圣的','/ˈseɪkɹɪd/','/ˈseɪkɹɪd/','adjective',["a sacred day"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elegant','adj.文雅的，雅致的','/ˈɛl.ə.ɡənt/','/ˈɛl.ə.ɡənt/','adjective',["an elegant solution"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outcome','n.结果，成果','/ˈaʊtkʌm/','/ˈaʊtkʌm/','noun',["A quality automobile is the outcome of the work of skilled engineers and thousands of workers.","Three is a possible outcome of tossing a six-sided die.","The outcomes of this course are outlined in your syllabus."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curriculum','n.课程','/kəˈɹɪk.jə.ləm/','/kəˈɹɪkjələm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('satisfaction','n.满意','/sætɪsˈfækʃən/','/sætɪsˈfækʃən/','noun',["He enjoyed the dish with great satisfaction. He''ll order it again the next time he arrives.","The count demanded satisfaction in the form of a duel at dawn."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sharp','adj.尖锐的；敏锐的；整点的','/ʃɑːp/','/ʃɑɹp/','noun',["The pitch pipe sounded out a perfect F♯ (F sharp).","The piece was difficult to read after it had been transposed, since in the new key many notes were sharps.","Beethoven''s \"Moonlight Sonata\" is written in C♯ minor (C sharp minor.)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('powerful','adj.强有力的，强大的；有影响力的','/ˈpaʊəfl/','/ˈpaʊɚfəl/','adjective',["Not very many (of them) had been damaged.","He was the very best runner there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slip','v.溜；滑动n.片，纸片；滑倒','/slɪp/','/slɪp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('future','n.将来','/ˈfjuːt͡ʃə/','/ˈfjuːt͡ʃɚ/','noun',["There is no future in dwelling on the past.","Future generations will either laugh or cry at our stupidity."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anchor','v.抛锚；停泊n.锚','/ˈæŋ.kə/','/ˈæŋ.kɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquaintance','n.相识，熟人','/əˈkweɪntəns/','/ʌˈkweɪn.təns/','noun',["I know of the man; but have no acquaintance with him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('novelist','n.小说家','/ˈnɒvəlɪst/','/ˈnɒvəlɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('royal','adj.王室的，皇家的；第一流的','/ˈɹɔɪəl/','/ˈɹɔɪəl/','noun',["royal mast;  royal sail","a royal pain in the neck"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shake','vt.使摇动；震动','/ˈʃeɪk/','/ˈʃeɪk/','noun',["She replied in the negative, with a shake of her head.","He shook the can of soda for thirty seconds before delivering it to me, so that, when I popped it open, soda went everywhere.","Shaking his head, he kept repeating \"No, no, no\"."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eyesight','n.视力，视觉','/ˈaɪˌsaɪt/','/ˈaɪˌsaɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('semicircle','n.半圆','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('screen','n.幕，荧光屏','/skɹiːn/','/skɹiːn/','noun',["a fire screen","a drug screen, a genetic screen","Mary screened the beans to remove the clumps of gravel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('autonomous','adj.自治的','/ɔːˈtɒnəməs/','/ɔˈtɑnəməs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('referee','n.仲裁人，调解人；裁判员','/ˌɹɛf.əˈɹiː/','/ˌɹɛfəˈɹiː/','noun',["The referee kicked Jim out of the game for fighting.","Your application, along with letters from three referees, should be received by January 31.","He has to referee three hockey games this weekend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trial','n.审判；试验','/ˈtɹaɪəl/','/ˈtɹaɪəl/','noun',["They will perform the trials for the new equipment next week.","That boy was a trial to his parents.","soccer trials"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correspond','vi.通信；一致；相当；协调','/ˌkɒɹəˈspɒnd/','/ˌkɑɹəˈspɑnd/','verb',["I''ve been corresponding with my German pen pal for three years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undertake','vt.承担；保证','/ʌndəˈteɪk/','','verb',["He undertook to exercise more in future.","I hate people who try and undertake on the motorway."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insect','n.昆虫','/ˈɪnsɛkt/','/ˈɪnsɛkt/','noun',["Our shed has several insect infestions, including ants, yellowjackets, and wasps.","The swamp is swarming with every sort of insect.","The manager’s assistant was the worst sort of insect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buffet','n.自助餐','/ˈbʊfeɪ/','/bəˈfeɪ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entrance','n.入口；入场；入学许可','/ˈɛn.tɹəns/','/ˈɛn.tɹəns/','noun',["Her entrance attracted no attention whatsoever.","the entrance of an heir upon his inheritance, or of a magistrate into office","Place your bag by the entrance so that you can find it easily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pregnant','adj.怀孕的','/ˈpɹɛɡnənt/','/ˈpɹɛɡnənt/','noun',["I went to the doctor and, guess what, I''m pregnant!","a pregnant pause"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('all','adj&pron&adv.全部','/ɔːl/','/ɔl/','noun',["She gave her all, and collapsed at the finish line.","The butter is all.","It suddenly went all quiet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('always','adv.总是；一直；永远','/ˈɔː(l).weɪz/','/ˈɔl.weɪz/','adverb',["Airplanes did not always exist as a form of transportation.","In this street, the shops always close during lunchtime.","I thought I could always go back to work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('border','n.边缘；边境，国界','/ˈbɔːdə/','/ˈbɔɹdɚ/','noun',["the borders of the garden","There''s a nice frilly border around the picture frame.","The border between Canada and USA is the longest in the world."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('below','adv.在下面prep.在…下面','/bɪˈləʊ/','/bəˈloʊ/','adverb',["the landlubbers lying down below","The treasure is buried two meters below the surface.","\"By their execution hereof, the Parties incur a legal obligation to pass consideration under this Loan Contract as is set forth below.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('already','adv.已经','/ɑlˈɹɛdi/','/ɔlˈɹɛdi/','adverb',["Are you quitting already?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('touch','v.触摸，接触n.接触；联系vt.感动','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shall','modalverb.〔某事〕必定，一定〔发生〕','/ˈʃæl/','/ˈʃæl/','verb',["I hope that we shall win the game.","(determination): You shall go to the ball!","Let us examine that, shall we?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admission','n.准许进入；承认','/ædˈmɪʃ.ən/','/ædˈmɪʃ.ən/','noun',["I request admission for two adults","There is no way he has seen that show, the admission is more than he makes in a week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('real','adj.真实的，确实的','/ɹiːl/','/ɹiːl/','noun',["This is real leather.","These are real tears!","a description of real life"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expense','n.费用，支出','/ɪkˈspɛns/','/ɪkˈspɛns/','noun',["Buying the car was a big expense, but will be worth it in the long run.","Jones reached the final at the expense of Smith, who couldn''t beat him.","It should be acceptable to expense a business lunch with a client."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unit','n.单元；单位','/ˈjuː.nɪt/','/ˈjuː.nɪt/','noun',["The centimetre is a unit of length.","He was a member of a special police unit.","The fifth tank brigade moved in with 20 units. (i.e., 20 tanks)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yell','vt.大叫，呼喊','/jɛl/','/jɛl/','noun',["He yelled directions to the party from the car.","If I come home late again, my dad is gonna yell at me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contemporary','adj.当代的；同时代的','/kənˈtɛm.p(ə).ɹi/','/kənˈtɛm.pəˌɹɛɹ.i/','noun',["Cervantes was a contemporary of Shakespeare."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collect','v.收集，搜集','/kəˈlɛkt/','/kəˈlɛkt/','verb',["Suzanne collected all the papers she had laid out.","A bank collects a monthly payment on a client''s new car loan.   A mortgage company collects a monthly payment on a house.","I don''t think he collects as much as hoards."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dusty','adj.尘土般的；尘土多的','/ˈdʌsti/','/ˈdʌsti/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amusement','n.娱乐，消遣','/əˈmjuzmənt/','/əˈmjuzmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boundary','n.边界，分界线','/ˈbaʊndɹi/','/ˈbaʊndəɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shame','n.遗憾的事；羞愧','/ʃeɪm/','/ʃeɪm/','noun',["The teenager couldn’t bear the shame of introducing his parents.","It was a shame not to see the show after driving all that way.","Shame, you poor thing, you must be cold!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rob','v.抢夺，抢劫','/ɹɒb/','/ɹɑb/','verb',["He robbed three banks before he was caught.","The best way to rob a bank is to own one.","Working all day robs me of any energy to go out in the evening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outing','n.远足；郊游','/ˈaʊtɪŋ/','/ˈaʊtɪŋ/','verb',["A Brazilian company outed the new mobile phone design."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trick','n.[C]诡计，把戏','/tɹɪk/','/tɹɪk/','noun',["It was just a trick to say that the house was underpriced.","And for my next trick, I will pull a wombat out of a duffel bag.","That''s a nice skateboard, but can you do any tricks on it?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('favour','n.恩惠；好感；帮助','/ˈfeɪ.və/','/ˈfeɪ.vɚ/','noun',["He did me a favor when he took the time to drive me home.","She enjoyed the queen''s favor.","A marriage favour is a bunch or knot of white ribbons or white flowers worn at a wedding."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('around','adv.在周围；在附近；大约；掉头prep.在…周围；绕着','/əˈɹaʊnd/','/əˈɹaʊnd/','adjective',["Is Clare around today?","\"How is old Bob? I heard that his health is failing.\"  \"Oh, he''s still around. He''s feeling better now.\"","High above, vultures circled around."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pollute','vt.污染','/pəˈljuːt/','/pəˈljuːt/','verb',["The factory polluted the river when it cleaned its tanks.","The lights from the stadium polluted the night sky, and we couldn''t see the stars."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disappoint','v.失望','/dɪsəˈpɔɪnt/','/dɪsəˈpɔɪnt/','verb',["His lack of respect disappointed her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rot','v.腐烂，腐败','/ɹɔt/','[ɹɑt]','noun',["The apple left in the cupboard all that time had started to rot.","Your brain will rot if you spend so much time on the computer, Tony!","to rot vegetable fiber"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('construction','n.建造，建设；建筑物','/kənˈstɹʌkʃən/','/kənˈstɹʌkʃən/','noun',["Construction is underway on the new bridge.","The engineer marvelled at his construction.","He had worked in construction all his life."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predict','v.预言；预报','/pɹɪˈdɪkt/','/pɹɪˈdɪkt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('row','v.划船n.排，行','/ˈɹəʊ/','/ˈɹoʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('universal','adj.普遍的，全体的','/ˌjuːnɪˈvɜːsl̩/','/ˌjunɪˈvɝsl̩/','noun',["She achieved universal fame.","universal wrench"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abroad','adv.到国外；在国外','/əˈbɹɔːd/','/əˈbɹɔd/','noun',["A tree spreads its branches abroad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frontier','n.国境，边界；前线','/fɹʌnˈtɪə/','/fɹʌnˈtɪɹ/','noun',["the frontier of civilization"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subjective','adj.主观的','/səbˈdʒɛktɪv/','/səbˈdʒɛktɪv/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deliberately','adv.故意地','/dəˈlɪb(ə)ɹətli/','/dəˈlɪb(ə)ɹətli/','adverb',["He deliberately broke that, didn''t he?","After being called upon, he strode deliberately up to the blackboard."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seaweed','n.海草，海藻','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawer','n.抽屉','/dɹɔː(ɹ)/','/dɹɔɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transport','n.运输；传送器vt.运输，传送','','','noun',["The transport of goods is not included in the price given on the website.","The local transport received a big boost as part of the mayor''s infrastructural plans.","to transport goods; to transport troops"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specific','adj.特殊的；明确的','/spəˈsɪf.ɪk/','/spəˈsɪf.ɪk/','noun',["a highly specific test, specific and nonspecific symptoms","Quinine is a specific medicine in cases of malaria."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('any','pron.任何一个；任何一些adj.任何的；一些','/ˈæni/','/ˈɛni/','adverb',["I will not remain here any longer.","Any may apply."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('application','n.申请；申请书','/aplɪˈkeɪʃ(ə)n/','/ˌæpləˈkeɪʃən/','noun',["The application of this cream should reduce the swelling.","I make the remark, and leave you to make the application.","This iPhone application can connect to most social networks."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freezing','adj.冻结的；极冷的','/ˈfɹiːz.ɪŋ/','/ˈfɹiːz.ɪŋ/','verb',["The lake froze solid.","Don''t freeze meat twice.","It didn''t freeze this winter, but last winter was very harsh."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punctuation','n.标点符号','/pʌŋk.tʃuˈeɪ.ʃən/','/pʌŋk.tʃuˈeɪ.ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acre','n.英亩；田地','/ˈeɪ.kə/','/ˈeɪ.kɚ/','noun',["I like my new house - there’s acres of space!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whisper','n&v.低语，私语','/ˈ(h)wɪspə/','/ˈ(h)wɪspɚ/','noun',["There are whispers of rebellion all around.","The soup had just a whisper of basil."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appetite','n.食欲，胃口','/ˈæp.ə.taɪt/','/ˈæp.ə.taɪt/','noun',["appetite for reading"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('until','prep&conj.直到…为止，在…以前','/ənˈtɪl/','/ənˈtɪl/','preposition',["If you can wait until after my meeting with her, we''ll talk then.","Keep walking until the second set of traffic lights, then turn left."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dull','adj.单调无味的；阴暗的；迟钝的','/dəl/','/dʌl/','verb',["Years of misuse have dulled the tools.","He drinks to dull the pain.","A razor will dull with use."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clumsy','adj.笨拙的','/ˈklʌmzi/','/ˈklʌmzi/','noun',["He''s very clumsy. I wouldn''t trust him with carrying the dishes.","It is a clumsy solution, but it might work for now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reason','v.说服，劝说n.理由，原因','/ˈɹiːzən/','/ˈɹiːzən/','noun',["Mankind should develop reason above all other virtues.","I reasoned the matter with my friend.","to reason one into a belief; to reason one out of his plan"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thought','n.思考，思想；念头','/θɔːt/','/θɔt/','verb',["Idly, the detective thought what his next move should be.","I thought for three hours about the problem and still couldn’t find the solution.","I tend to think of her as rather ugly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accurate','adj.正确的，准确的','/ˈæk.jə.ɹɪt/','/ˈæk.jə.ɹɪt/','adjective',["accurate knowledge","My horoscopes I read last week were surprisingly accurate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ring','v.响；打电话n.电话铃声；环形物','/ɹɪŋ/','/ɹɪŋ/','noun',["onion rings","a crime ring; a prostitution ring; a bidding ring (at an auction sale)","a benzene ring"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('taste','n.喜爱，爱好，口味v.有…的味道','/teɪst/','/teɪst/','noun',["He had a strange taste in his mouth.","His taste was impaired by an illness.","Dr. Parker has good taste in wine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anywhere','adv.任何地方','/ˈɛn.iː.(h)wɛə(ɹ)/','/ˈɛn.i.(h)wɛɹ/','adverb',["I don''t know where I left my keys. They could be anywhere.","Anywhere you go in France, there will be bread and wine with dinner.","Anywhere is better than here!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bargain','v.讨价还价n.便宜货，廉价货','/-ɡɪn/','/ˈbɑːɹɡən/','noun',["At that price, it''s not just a bargain, it''s a steal.","They had to bargain for a few minutes to get a decent price for the rug."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identification','n.辨认，鉴定；身份证明','/aɪˌdɛntɪfɪˈkeɪʃən/','/aɪˌdɛntɪfɪˈkeɪʃən/','noun',["Much education and experience is required for proper identification of bird species","information necessary to make a good identification","The authorities asked for his identification"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jam','v.阻塞n.果酱；阻塞','/ˈdʒæm/','/ˈdʒæm/','noun',["A traffic jam caused us to miss the game''s first period.","Her poor little baby toe got jammed in the door.","The rush-hour train was jammed with commuters."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annual','adj.一年一次的，每年的','/ˈæn.ju.əl/','/ˈæn.ju.əl/','noun',["I read the magazine, but I usually don''t purchase the annuals.","I can''t wait to plant my annuals in the spring.","an annual general meeting;  an annual publication"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gentle','adj.温柔的，柔和的','/ˈdʒɛntl̩/','/ˈdʒɛntl̩/','noun',["Stuart is a gentle man; he would never hurt you.","I felt something touch my shoulder; it was gentle and a little slimy.","We had a gentle swim in the lake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheers','int.干杯','/tʃɪəz/','/tʃɪɹz/','noun',["a table loaded with good cheer","A cheer rose from the crowd.","We were cheered by the offer of a cup of tea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boil','v.沸腾，烧开；煮','/bɔɪl/','/bɔɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sneaker','n.胶底运动鞋','/ˈsnikɚ/','/ˈsnikɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lightning','n.闪电','/ˈlaɪt.nɪŋ/','/ˈlaɪt.nɪŋ/','noun',["Although we did not see the lightning, we did hear the thunder.","That tree was hit by lightning."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remain','vi.余下，留下v.保持，仍是','/ɹɪˈmeɪn/','/ɹɪˈmeɪn/','noun',["There was no food in the house, so I had to remain hungry.","The light remained red for two full minutes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shabby','adj.破旧的，衣衫褴褛的；不公正的，不讲理的；低劣的','/ˈʃæb.i/','/ˈʃæb.i/','adjective',["They lived in a tiny apartment, with some old, shabby furniture.","The fellow arrived looking rather shabby after journeying so far.","shabby treatment"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amaze','vt.惊奇，惊叹，震惊','/əˈmeɪz/','','noun',["He was amazed when he found that the girl was a robot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demand','n&v.要求，需要','/dɪˈmɑːnd/','/dəˈmænd/','noun',["Prices usually go up when demand exceeds supply.","Modern society is responding to women''s demands for equality.","His job makes many demands on his time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('envelope','n.信封','/ˈɒn.və.ləʊp/','/ˈɑn.vəˌloʊp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slow','adj.缓慢的v.放慢速度，减缓','/sləʊ/','/sloʊ/','noun',["a slow train;  a slow computer","That clock is slow.","I''m just sitting here with a desk of cards, enjoying a slow afternoon."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turkey','n.火鸡','/ˈtɜːki/','/ˈtɝki/','noun',["All week after Thanksgiving, I had turkey sandwiches for lunch.","That film was a turkey.","The turkey cut in front of me and then berated me for running into him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grade','n.等级；学年；成绩，分数','/ɡɹeɪd/','/ɡɹeɪd/','noun',["I gave him a good grade for effort.","He got a good grade on the test.","The grade of this hill is more than 5 percent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deposit','n&v.存；堆积','/dɪˈpɒzɪt/','/dɨˈpɑzɪt/','noun',["a deposit of seaweed on the shore","They put a deposit on the apartment.","A crocodile deposits her eggs in the sand."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tasty','adj.味道好的','/ˈteɪsti/','/ˈteɪsti/','adjective',["You could make this tasty meal for breakfast.","These items will make an attractive and tasty display."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('telescope','n.望远镜','/ˈtɛlɪskəʊp/','/ˈtɛləˌskoʊp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flash','v.闪光，闪现n.闪，闪光，转瞬间','/flæʃ/','/flæʃ/','noun',["I just got my first commando flash.","He flashed the light at the water, trying to see what made the noise.","The light flashed on and off."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skillful','adj.熟练的；技艺精湛的；灵巧的','/ˈskɪl.fəl/','/ˈskɪl.fəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continent','n.大陆，大洲','/ˈkɒntɪnənt/','/ˈkɑntɪnənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accuse','vt.控告，谴责','/əˈkjuːz/','/əˈkjuz/','noun',["For the U.S. President to be impeached, he must be accused of a high crime or misdemeanor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maybe','adv.可能，大概，也许','/ˈmeɪbi/','/ˈmeɪbi/','noun',["The results of the poll were inconclusive. We got two yeses, three nos, and four maybes.","About your raise: it''s a big maybe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('another','pron.另一个adj.另一；别的','','','pronoun',["There is one sterling and here is another","I saw one movie, but I think I will see another.","His interests keep shifting from one thing to another."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guarantee','vt&n.保证，担保','/ˌɡæɹənˈtiː/','/ˌɡæɹənˈtiː/','noun',["Can you give me a guarantee that he will be fit for the match?","The cooker comes with a five-year guarantee.","The long sunny days guarantee a good crop."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('algebra','n.代数学','/ˈæl.dʒɪ.bɹə/','/ˈæl.dʒə.bɹə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recommend','v.推荐','/ɹɛkəˈmɛnd/','/ɹɛkəˈmɛnd/','verb',["The board recommends Philips, given his ample experience in similar positions.","A city that has much to recommend it.","The therapist recommends resting the mind and exercising the body."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquire','vt.获得；学到','/əˈkwaɪə/','/əˈkwaɪəɹ/','verb',["He acquired a title."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worth','adj.值得的；价值…','/wɜːθ/','/wɝθ/','noun',["I’ll have a dollar''s worth of candy, please.","Our new director is a man whose worth is well acknowledged.","A painting worth thousands."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('helicopter','n.直升机','/ˈheliˌkɔptə(ɹ)/','/ˈheliˌkɔptə(ɹ)/','noun',["We flew over the city in a helicopter.","helicoptering his jacket, helicoptering his arms"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ripe','adj.成熟的，熟的','/ɹaɪp/','/ɹaɪp/','noun',["ripe apples","ripe cheese"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('where','adv&conj.那儿；何处','/wɛə(ɹ)/','/wɛəɹ/','noun',["A good article will cover the who, the what, the when, the where, the why and the how.","He asked where I grew up.","Where would we be without our parents?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disabled','adj.残疾的','[dɪsˈeɪbəɫd]','[dɪsˈeɪbəɫd]','verb',["Falling off the horse disabled him.","The pilot had to disable the autopilot of his airplane."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('watermelon','n.西瓜','/ˈwɔːtəˌmɛlən/','/ˈwɔtəɹˌmɛlən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arm','v.以…装备，武装起来n.手臂；支架','/ɑːm/','/ɑɹm/','noun',["She stood with her right arm extended and her palm forward to indicate “Stop!”","The arm and forearm are parts of the upper limb in the human body.","the arms of an octopus"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('popular','adj.流行的，受欢迎的；大众的','/ˈpɒpjʊlə/','/ˈpɑpjələɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('broken','adj.弄坏了的，破碎的','/ˈbɹəʊkən/','/ˈbɹəʊkən/','verb',["If the vase falls to the floor, it might break.","Can you break a hundred-dollar bill for me?","Her child''s death broke Angela."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outwards','adv.向外，在外adj.向外的，外出的','/ˈæotwɘdz/','/ˈæotwɘdz/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vice','prep.副，次；代替n.恶习；缺陷','/vaɪs/','/vaɪs/','noun',["Gluttony is a vice, not a virtue."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poison','n.毒药','/ˈpɔɪz(ə)n/','/ˈpɔɪz(ə)n/','noun',["We used a poison to kill the weeds.","Gossip is a malicious poison.","— I''ll have a glass of whisky."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silly','adj.傻的，愚蠢的','/ˈsɪli/','/ˈsɪli/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liberation','n.解放','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fortunate','adj.幸运的，侥幸的','/ˈfɔːt͡ʃənət/','/ˈfɔɹt͡ʃnɪt/','adjective',["It is a fortunate sign if the sun shines on a newly wedded couple.","Patrick was the unlikely match-winner as Berkeley earned a fortunate victory over Chisolm.","This is a time when we think of those less fortunate than ourselves."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrinkle','n.皱纹','/ˈɹɪŋkl̩/','/ˈɹɪŋkl̩/','noun',["Spending time out in the sun may cause you to develop wrinkles sooner.","Three months later, we''re still discovering new wrinkles.","Be careful not to wrinkle your dress before we arrive."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tour','n.[C]参观，观光，旅行','/tɔː(ɹ)/','/tɔː(ɹ)/','noun',["On our last holiday to Spain we took a tour of the wine-growing regions.","On the company''s website, you can take a virtual tour of the headquarters.","Metallica''s tour of Europe"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persuade','v.说服，劝说；使相信','/pəˈsweɪd/','/pɚˈsweɪd/','verb',["That salesman was able to persuade me into buying this bottle of lotion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('call','n.叫；电话vt.称呼；呼唤；叫；给…打电话','/kɔːɫ/','/kɔl/','noun',["I received several calls today.","I paid a call to a dear friend of mine.","The ship made a call at Southampton."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consensus','n.一致意见','','','noun',["After years of debate over the best wine to serve at Thanksgiving, no real consensus has emerged.","a financial consensus forecast"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('such','adv.那么，如此pron.人，事物adj.这样的，那样的','/sʌt͡ʃ/','/sʌt͡ʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calm','adj.镇静的，沉着的v.镇静，沉着','/kam/','/kɑlm/','noun',["to calm a crying baby"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boring','adj.令人厌烦的','/ˈbɔːɹɪŋ/','/ˈbɔːɹɪŋ/','verb',["An insect bores into a tree.","to bore a steam cylinder or a gun barrel; to bore a hole","to bore one''s way through a crowd"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classic','adj.经典的，一流的','/ˈklæ.sɪk/','/ˈklæ.sɪk/','noun',["Users who dislike the new visual layout can return to classic mode."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kick','v&n.踢','/kɪk/','/kɪk/','noun',["A kick to the knee.","The ballerina did a high kick and a leap.","I finally saw the show. What a kick!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absolute','adj.完全的，绝对的','/ˈæb.səˌljuːt/','/ˈæb.səˌlut/','noun',["moral absolutes","1658, Samuel Hoard, God''s Love to Mankind, Manifested, by disprooving his absolute decree for their damnation","absolute purity, absolute liberty"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ask','v.询问；要求','/ˈask/','/eəsk/','noun',["I know this is a big ask, but …","I asked her age.","to ask a question"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canteen','n.餐厅；食堂','/kænˈtiːn/','/kænˈtiːn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('describe','vt.描写，叙述','/dəˈskɹaɪb/','/dəˈskɹaɪb/','verb',["The feeling is difficult to describe, but not unpleasant.","to describe a circle by the compasses;   a torch waved about the head in such a way as to describe a circle","The function describes a very complex surface."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suck','v.吸，吮','/sʌk/','/sʌk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dilemma','n.进退两难的局面','/daɪˈlɛmə/','/daɪˈlɛmə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wealthy','adj.富有的','/ˈwɛl.θi/','/ˈwɛl.θi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strength','n.力量，力气','/stɹɛŋkθ/','/stɹɛŋkθ/','noun',["It requires great strength to lift heavy objects.","He had the strength of ten men.","We all have our own strengths and weaknesses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dusk','n.黄昏','/dʌsk/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('administration','n.管理；行政部门','/ədˌmɪnəˈstɹeɪʃən/','/ədˌmɪnəˈstɹeɪʃən/','noun',["Successive US administrations have had similar Middle East policies.","oral administration of insulin","The company went into voluntary administration last week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('run','vi.跑，奔跑；褪色；经营，管理','/ɹʊn/','/ɹʌn/','verb',["I just got back from my morning run.","I need to make a run to the store.","Let''s go for a run in the car."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('challenging','adj.具有挑战性的','/ˈtʃæləndʒɪŋ/','/ˈtʃæləndʒɪŋ/','verb',["We challenged the boys next door to a game of football.","to challenge the accuracy of a statement or of a quotation","The sentinel challenged us with \"Who goes there?\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('research','n.研究，调查','/ɹɪˈsɜːtʃ/','/ɹiˈsɝtʃ/','noun',["The research station that houses Wang and his team is outside Lijiang, a city of about 1.2 million people."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debate','n&v.讨论，辩论','/dɪˈbeɪt/','','noun',["After a four-hour debate, the committee voted to table the motion.","The debate over the age of the universe is thousands of years old.","There has been considerable debate concerning exactly how to format these articles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('view','n.看法；景色','/vjuː/','/vjuː/','noun',["a fine view of Lake George","The video was viewed by millions of people.","I view it as a serious breach of trust."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('either','determiner.〔两者中的〕任何一个adv.也(不)','/ˈaɪð.ə(ɹ)/','/ˈaɪð.ə(ɹ)/','adverb',["I don''t like him, and I don''t like her either.","He made me two offers, but I did not accept either.","Either you eat your dinner or you go to your room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furniture','n.〈总称〉家具','/ˈfɜːnɪtʃə/','/ˈfɝnɪtʃɚ/','noun',["A chair is furniture. Sofas are also furniture."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jet','v.喷射n.喷气式飞机；喷射','/dʒɛt/','/dʒɛt/','noun',["Farmers may either dip or jet sheep with chemicals.","jet airplane"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('donate','v.捐赠，赠送','/dəʊˈneɪt/','/doʊˈneɪt/','verb',["He donated an etching from his own collection to the new art gallery."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('helpful','adj.有帮助的，有益的','/ˈhɛlp.fəl/','/ˈhɛlp.fəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dust','n.灰尘，尘土','/dʌst/','/dʌst/','noun',["to raise, or kick up, a dust","The cleaning lady needs a stool to dust the cupboard.","Dusting always makes me cough."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worry','v&n.担忧，烦恼','/ˈwɒɹi/','/ˈwɝɹi/','noun',["I''m afflicted by worry throughout the night.","My main worry is that I''ll miss the train.","Stop worrying about your test, it’ll be fine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cater','v.投合；备办食物','/ˈkeɪtə/','/ˈkeɪdɚ/','noun',["The merchants are the purveyors of fine selections."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imagine','v.想象，设想','/ɪˈmædʒ.ɪn/','/ɪˈmædʒ.ɪn/','noun',["Try to imagine a pink elephant.","She imagined that the man wanted to kill her.","I imagine that he will need to rest after such a long flight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attractive','adj.迷人的，有吸引力的','/əˈtɹæktɪv/','/əˈtɹæktɪv/','adjective',["That''s a very attractive offer.","He is an attractive fellow with a trim figure."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superb','adj.庄重的，华丽的，极好的','/sjuːˈpɜːb/','/suˈpɝb/','adjective',["This champagne is superb.","a superb edifice;  a superb colonnade"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('might','modalverb.可以〔用于礼貌地提出建议〕n.力量；威力；权力','/maɪt/','/maɪt/','noun',["He pushed with all his might, but still it would not move."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bleed','v.出血，流血','/ˈbliːd/','/ˈbliːd/','noun',["If her nose bleeds, try to use ice.","The company was bleeding talent.","Ink traps counteract bleeding."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catalogue','n.目录','/ˈkætəlɑɡ/','/ˈkætəlɔɡ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whatever','conj&pron.无论什么','/wɒtˈɛvə/','/wʌtˈɛvɚ/','adjective',["There is no point whatever in going on with this discussion.","Whatever he does, he will still lose the game.","I’ll do whatever I can."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decrease','v.减小，减少','','','noun',["One research team has recorded Baishui’s decrease at about 27 meters per year over the last 10 years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('camp','n&vi.野营，宿营','[kʰɛəmp]','[kʰɛəmp]','noun',["a hunter''s camp","We''re planning to camp in the field until Sunday.","Go and camp the flag for the win."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('difficulty','n.困难，费力；异议','/ˈdɪfɪkəlti/','/ˈdɪfɪkəlti/','noun',["We faced a difficulty in trying to book a flight so late.","2012 August 2, \"Children rescued after getting into difficulties in Donegal\" BBC Online"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volunteer','v.自愿n.志愿者','/vɒl.ənˈtɪə/','/vɑl.ənˈtɪɹ/','noun',["to volunteer for doing the dishes","to volunteer an explanation","My sister volunteered me to do the dishes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everywhere','adv.到处','/ɛv.ɹi.(h)weə(ɹ)/','/ɛv.ɹi.(h)wɛɹ/','adverb',["He delivers the mail everywhere on this street.","I''ve looked everywhere in the house and still can''t find my glasses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clothing','n.〈总称〉衣服','/ˈkləʊðɪŋ/','/ˈkloʊðɪŋ/','verb',["to feed and clothe a family; to clothe oneself extravagantly","to clothe somebody with authority or power","The clothing and unclothing of the idols was of special significance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aloud','adv.大声地；出声地','/əˈlaʊd/','/əˈlaʊd/','adjective',["Try speaking aloud rather than whispering.","speaking aloud rather than thinking thoughts privately"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thunderstorm','n.雷暴，雷雨交加','/ˈθʌn.də(ɹ)ˌstɔː(ɹ)m/','/ˈθʌn.də(ɹ)ˌstɔː(ɹ)m/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mourn','v.哀痛；哀悼','/mɔːn/','/mɔːn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('next','adv.随后，然后，下一步adj.最近的；紧挨着的，隔壁的；下一次n.下一个人','/nɛkst/','/nɛkst/','noun',["Next, please, don''t hold up the queue!","the next chapter; the next man I see; the next week; the Sunday next before Easter","The man was driven by his love for money and his desire to become the next Bill Gates."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blind','adj.瞎的，盲的','/blaɪnd/','/blaɪnd/','noun',["a duck blind","The blinds are $10/$20 and the ante is $1.","The blinds immediately folded when I reraised."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nod','v&n.点头','/nɔd/','/nɑd/','noun',["For the fifth time in her career she received a Grammy nod, she has yet to win the award.","The plan is expected to get the nod from councillors at the next meeting.","They nodded their assent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('string','n.细绳，线，带','/stɹɪŋ/','/stɹɪŋ/','noun',["There were stalls for fourteen horses in the squire''s stables.","a bowstring","a string of sausages"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('import','n.进口，输入','/ˈɪm.pɔːt/','/ˈɪm.pɔːt/','noun',["It was a matter of great import.","How can I import files from older versions of this application?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distance','n.距离','/ˈdɪs.təns/','/ˈdɪs.təns/','noun',["From Moscow, the distance is relatively short to Saint Petersburg, relatively long to Novosibirsk, but even greater to Vladivostok.","We''re narrowing the distance between the two versions of the bill.  The distance between the lowest and next gear on my bicycle is annoying.","the distance between a descendant and his ancestor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occupy','vt.占领，占据','/ˈɒkjʊpaɪ/','/ˈɒkjʊpaɪ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submit','vt.提交，递交','/səbˈmɪt/','/səbˈmɪt/','verb',["They will not submit to the destruction of their rights.","I submit these plans for your approval."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boom','v.发出隆隆声；兴隆，使繁荣n.繁荣；隆隆声','/buːm/','/buːm/','noun',["The boom of the surf.","You should prepare for the coming boom in the tech industry.","I can hear the organ slowly booming from the chapel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abolish','vt.废止；废除','/əˈbɒlɪʃ/','/əˈbɑl.əʃ/','verb',["Slavery was abolished in the nineteenth century."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absence','n.不在，缺席；没有','/ˈæb.s(ə)n̩s/','/æbˈsɒns/','noun',["Absence makes the heart grow fonder.","He had an absence of enthusiasm.","absence of mind"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nearly','adv.将近；几乎','/ˈniːɹli/','/ˈnɪɹli/','adverb',["He left a nearly full beer on the bar."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attract','v.吸引；引起','/əˈtɹækt/','/əˈtɹækt/','verb',["A magnet attracts iron filings.","Advertising is designed to attract customers.","to attract admirers;   His big smile and brown eyes instantly attracted me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('show','v.给…看，出示，','/ʃəʊ/','/ʃoʊ/','noun',["art show;  dog show","radio show;  television show","Let''s catch a show."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edition','n.版，版本','/əˈdɪʃən/','/əˈdɪʃən/','noun',["The first edition was soon sold.","The 2014 edition of the Tour de France started in Leeds, Yorkshire."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cautious','adj.小心的，谨慎的','/ˈkɔːʃəs/','/ˈkɔːʃəs/','adjective',["He took a few cautious steps toward the cave."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disappear','vi.消失','/dɪsəˈpiːɹ/','/dɪsəˈpɪɹ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perfume','n.香味；香水','/ˈpɜːfjuːm/','/ˈpɜːfjuːm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shot','n.射击，开枪，开炮，射击声；子弹；拍摄','/ʃɒt/','/ʃɑt/','verb',["The land shoots into a promontory.","The shot was wide off the mark.","They took the lead on a last-minute shot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conclusion','n.[C]结论；结束','/kənˈkluːʒən/','/kənˈkluːʒən/','noun',["The board has come to the conclusion that the proposed takeover would not be in the interest of our shareholders."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nor','conj.也不','/nɔː/','/nɔːɹ/','conjunction',["Nor did I stop to think, but ran.","I am neither hungry nor thirsty nor tired.","The struggle didn''t end, nor was it any less diminished."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('central','adj.中心的，中央的；主要的','/ˈsɛntɹəl/','/ˈsɛntɹəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defend','vt.保护，防御','/dɪˈfɛnd/','/diˈfɛnd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrive','vi.到达，达到','/əˈɹaɪv/','/əˈɹaɪv/','verb',["He arrived home for two days.","He had finally arrived on Broadway.","The time has arrived for us to depart."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memorial','adj.纪念的n.纪念碑，纪念物','/məˈmoʊɹi.əl/','/məˈmoʊɹi.əl/','noun',["a memorial building","a memorial possession"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wag','v.摇动，摆动','/wæɡ/','/wæɡ/','noun',["The wag of my dog''s tail expresses happiness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('race','v.赛跑，比赛n.种族；比赛','/ɹeɪs/','/ɹeɪs/','noun',["The race around the park was won by Johnny, who ran faster than the others.","the race to cure cancer","The drivers were racing around the track."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('introduce','vt.介绍；引进','/ˌɪntɹəˈdjuːs/','/ˌɪntɹəˈdus/','verb',["Let me introduce you to my friends.","Let me introduce our guest speaker.","Various pollutants were introduced into the atmosphere."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greet','vt.问候，向…致敬','/ɡɹiːt/','/ɡɹiːt/','verb',["A brilliant dawn greeted her eyes as she looked out of the window."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sculpture','n.雕塑，雕像','/ˈskʌlptj(ʊ)ə/','/ˈskʌlpt͡ʃɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bond','v.黏合；结合n.联结；联结物','/bɒnd/','/bɑnd/','noun',["Investors face a quandary. Cash offers a return of virtually zero in many developed countries; government-bond yields may have risen in recent weeks but they are still unattractive. Equities have suffered two big bear markets since 2000 and are wobbling again. It is hardly surprising that pension funds, insurers and endowments are searching for new sources of return.","The prisoner was brought before the tribunal in iron bonds.","They had grown up as friends and neighbors, and not even vastly differing political views could break the bond of their friendship."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('way','n.道路；方法；作风','/weɪ/','/weɪ/','noun',["You''re going about it the wrong way.  He''s known for his quirky ways.  I don''t like the way she looks at me.","When I returned home, I found my house and belongings in a most terrible way.","To walk the Way of the Runes, you must experience the runes as they manifest both in the part of Midgard that lies outside yourself and the worlds within. (Diana Paxson)"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('target','n.目标，对象；靶子','/tɑːɡɪt/','/ˈtɑɹɡɪt/','noun',["Take careful aim at the target.","They have a target to finish the project by November.","He made a good target."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wax','n.蜡，蜡状物','/wæks/','/wæks/','noun',["What role does the wax in your earhole fulfill?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grey','adj.灰色的；灰白的','/ɡɹeɪ/','/ɡɹeɪ/','adjective',["Wash colored items separately from whites and darks to prevent the colors from bleeding.","The room was red, with a dark-colored rug.","The singer wore a colored shirt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('what','pron&adj&conj.什么','/wɒt/','/wɒt/','adverb',["The market will calculate these higher risks in their funding costs what might result in higher lending rates.","What a beautiful day!","He knows what he wants."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urban','adj.城市的，市内的','/ˈɜːbən/','/ˈɜːbən/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guidance','n.引导，指导','/ˈɡaɪdəns/','/ˈɡaɪdəns/','noun',["divine guidance"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refer','v.谈到，提到','/ɹɪˈfɜː/','/ɹɪˈfɝ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nervous','adj.紧张不安的，神经质的','/ˈnɜːvəs/','/ˈnɝːvəs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duty','n.责任；义务；税','/ˈdjuːti/','/duːti/','noun',["We don''t have a duty to keep you here.","I’m on duty from 6 pm to 6 am."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('risk','n.冒险，风险vt.冒…的危险','/ɹɪsk/','/ɹɪsk/','noun',["2006, Trever Ramsey on BBC News website, Exercise ''cuts skin cancer risk'' read at http//news.bbc.co.uk/1/hi/health/4764535.stm on 14 May 2006"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flame','n.火焰，光辉','/fleɪm/','/fleɪm/','noun',["The cello has a two-piece back with a beautiful narrow flame.","I flamed him for spamming in my favourite newsgroup."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rise','n.上升，上涨','/ɹaɪs/','/ɹaɪs/','verb',["to rise a hill","to rise a fish, or cause it to come to the surface of the water"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('play','v.玩；打；播放n.玩耍；戏剧','/pleɪ/','/pleɪ/','noun',["Children learn through play.","This kind of play helps the young lion cubs develop their hunting skills.","After the rain break, play resumed at 3 o''clock."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delicate','adj.精巧的，精致的','/ˈdɛlɪkət/','/ˈdɛlɪkət/','noun',["Don''t put that in with your jeans: it''s a delicate!","The negotiations were very delicate.","Her face was delicate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fancy','adj.奇特的；空想的n.空想，假想vt.想象，空想','/ˈfæn.si/','/ˈfæn.si/','noun',["I had a fancy to learn to play the flute.","He took a fancy to her.","Trainspotting is the fancy of a special lot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bounce','v.使反弹；跳跃','/baʊns/','/baʊns/','noun',["Them pro-ballers got bounce!","The tennis ball bounced off the wall before coming to rest in the ditch.","He bounces nervously on his chair."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tissue','n.薄的纱织品；薄纸；组织','/ˈtɪsjuː/','/ˈtɪʃu/','noun',["a tissue of forgeries, or of lies"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decide','v.决定，下决心','/dɪˈsaɪd/','/dɪˈsaɪd/','verb',["Her last-minute goal decided the game.","I have decided that it is healthier to walk to work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rent','v.租用；出租n.租金','/ɹɛnt/','/ɹɛnt/','noun',["A New York city taxicab license earns more than $10,000 a year in rent.","I rented a house from my friend''s parents for a year.","We rented our house to our son''s friend for a year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('when','adv.在那时conj.什么时候；当…的时候','/wɛn/','/wɛn/','noun',["A good article will cover the who, the what, the when, the where, the why and the how.","Do you know when they arrived?","He''s mister high and mighty now, but I remember him when."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nearby','adv.在附近adj.附近的','','','adjective',["He stopped at a nearby store for some groceries.","I''m glad my friends live nearby where I can visit them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carpenter','n.木匠','/ˈkɑː.pən.tə/','/ˈkɑː.pən.tə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modest','adj.谦虚的，谦逊的','/ˈmɑdəst/','/ˈmɑdəst/','adjective',["He earns a modest amount of money.","modest thoughts or language"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cast','vt.扔，抛n.演员表','/kæst/','/kæst/','noun',["The area near the stream was covered with little bubbly worm casts.","He’s in the cast of Oliver.","The men got into position for the cast, two at the ladle, two with long rods, all with heavy clothing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anxious','adj.忧虑的；焦急的','/ˈaŋ(k)ʃəs/','/ˈæŋ(k).ʃəs/','adjective',["I could tell she was anxious as she was biting her nails.","There was an anxious wait before the results were revealed.","All the voters were anxious to hear the election result."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fan','n.迷，狂热的爱好者、支持者；风扇','/fæn/','/fæn/','noun',["We enjoyed standing at the edge of the cliff, being fanned by the wind.","I attempted to fan the disagreeable odour out of the room."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slice','n.片，薄片','/slaɪs/','/slaɪs/','noun',["Jim was munching on a slice of toast.","I bought a ham and cheese slice at the service station.","Slice the cheese thinly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('far','adj&adv.远的','/fɑː/','/fɑɹ/','adjective',["He went to a far land.","the far future","He moved to the far end of the state. She remained at this end."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frost','n.霜','/fɹɑst/','/fɹɔst/','noun',["I think the boss''s decision frosted him a bit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catch','vt.接住；捉住；赶上；染上','/kæt͡ʃ/','/kæt͡ʃ/','noun',["The catch of the perpetrator was the product of a year of police work.","Nice catch!","Good catch. I never would have remembered that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fax','n.传真','/fæks/','/fæks/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plan','n&v.计划，打算','/plæn/','/plæn/','noun',["The plans for many important buildings were once publicly available.","He didn''t really have a plan; he had a goal and a habit of control.","Seen in plan, the building had numerous passageways not apparent to visitors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cash','n.现金，现钞vt.兑现','/kæʃ/','/kæʃ/','noun',["After you bounced those checks last time, they want to be paid in cash."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('case','n.情况；病例；案件；容器','/keɪs/','/keɪs/','noun',["For a change, in this case, he was telling the truth.","It was one of the detective''s easiest cases.  Social workers should work on a maximum of forty active cases.  The doctor told us of an interesting case he had treated that morning.","The teaching consists of theory lessons and case studies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generation','n.代，一代','/ˌd͡ʒɛnəˈɹeɪʃən/','/ˌd͡ʒɛnəˈɹeɪʃən/','noun',["This is the book of the generations of Adam - Genesis 5:1","the generation of a line or curve","Generation X grew up in the eighties, whereas the generation known as the millennials grew up in the nineties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('give','v.给，付出','/ɡɪv/','/ɡɪv/','noun',["There is no give in his dogmatic religious beliefs.","I give it a 95% chance of success.","One pillar gave, then more, and suddenly the whole floor pancaked onto the floor below."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('double','adj.两倍的；双重的v.加倍n.两个；双打','/ˈdʌb.əl/','/ˈdʌb.əl/','noun',["Saddam Hussein was rumored to have many doubles.","On second thought, make that a double.","Before printing the photos, Liam deleted the doubles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downtown','n&adj.市区，闹市区','','','noun',["John walked every day to his downtown job.","You need to go downtown four blocks.","That shot came from way downtown!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trunk','n.树干；大箱子','/tɹʌŋk/','/tɹʌŋk/','noun',["the trunk of a vein or of an artery, as distinct from the branches"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stainless','adj.无污染的；无瑕疵的；不锈的','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explicit','adj.清楚的；直率的','/ɪkˈsplɪsɪt/','/ɪkˈsplɪsɪt/','adjective',["I gave explicit instructions for him to stay here, but he followed me, anyway.","The film had several scenes including explicit language and sex."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rely','vi.依赖，依靠；信任','/ɹɪˈlaɪ/','/ɹɪˈlaɪ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phone','v.打电话n.电话；电话机','/fəʊ̯n/','/foʊ̯n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slide','v.滑行，滑动n.幻灯片；滑道','/slaɪd/','/slaɪd/','noun',["The long, red slide was great fun for the kids.","The slide closed the highway.","a slide on the ice"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comfortable','adj.舒服的；安逸的；舒服自在的','/ˈkʌm.fə.tə.bəl/','/ˈkʌm.fə.tə.bəl/','noun',["This is the most comfortable bed I''ve ever slept in.","What a great guestroom! I''ll be quite comfortable here.","A comfortable income should suffice to consider oneself rich."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waist','n.腰部，腰围','/weɪst/','/weɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('style','n.风格，时尚','/staɪl/','/staɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jungle','n.丛林，密林','/ˈdʒʌŋ.ɡ(ə)l/','/ˈdʒʌŋ.ɡ(ə)l/','noun',["It’s a jungle out there."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flesh','n.肉，肉体','/flɛʃ/','/flɛʃ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suit','vt.适合n.一套','/s(j)uːt/','/s(j)ut/','noun',["Nick hired a navy-blue suit for the wedding.","Be sure to keep your nose to the grindstone today; the suits are making a \"surprise\" visit to this department.","If you take my advice, you''ll file a suit against him immediately."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grill','n.烤架；烤肉','/ɡɹɪl/','/ɡɹɪl/','noun',["I put some peppers and mushrooms on the grill to go with dinner.","a packet of frozen cauliflower cheese grills","These coupons will get you a discount at Johnny''s Bar and Grill."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('care','v.介意，在乎；在意；关心n.照料；保护；小心','/kɛə/','/ke(ə)ɹ/','noun',["Care should be taken when holding babies.","I don''t have a care in the world.","dental care"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('damage','n&v.毁坏，损害','/ˈdæmɪdʒ/','/ˈdæmɪdʒ/','noun',["The storm did a lot of damage to the area.","\"What''s the damage?\" he asked the waiter.","Be careful not to damage any of the fragile items while unpacking them."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guard','v.保卫，看守n.防护装置；警戒','/ɡɑːd/','/ɡɑɹd/','noun',["The prison guard unlocked the door of the cell.   After completing the repairs, he replaced the sump guard.","The president inspected the guard of honour.","The motorcycle mechanic removed the damaged chain guard."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('settle','vi.安家，定居vt.解决','/ˈsɛtəl/','/ˈsɛtəl/','verb',["to settle her estate","the weather settled;  wait until the crowd settles before speaking","the Saxons who settled in Britain"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('direct','adj.直接的；直达的v.指挥，指导','/d(a)ɪˈɹɛkt/','/d(a)ɪˈɹɛkt/','verb',["to direct the affairs of a nation or the movements of an army","He directed his question to the room in general.","He directed me to the left-hand road."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pattern','n.式样；模式','/ˈpat(ə)n/','/ˈpat(ə)n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exercise','v.锻炼n.[C]练习；[U]锻炼','/ˈɛk.sə.saɪz/','/ˈɛk.sɚ.saɪz/','noun',["The teacher told us that the next exercise is to write an essay.","I do crosswords for mental exercise.","The law guarantees us the free exercise of our rights."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('labour','n.劳动，劳力','/ˈleɪ.bə/','/ˈleɪ.bɚ/','noun',["I think we''ve all got the idea. There''s no need to labour the point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gain','v.获得，挣得n.收获','/ɡeɪn/','/ɡeɪn/','noun',["Looks like you''ve gained a new friend.","The sick man gains daily.","to gain a battle; to gain a case at law"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vehicle','n.车辆','/ˈvɪː(ə).kəl/','/ˈvi.ə.kəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardship','n.困难，艰辛','/ˈhɑːdˌʃɪp/','/ˈhɑːdˌʃɪp/','noun',["He has survived periods of financial hardship before."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confuse','vt.使糊涂；搞乱','/kənˈfjuːz/','/kənˈfjuːz/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kilo','n.千克；公斤','/ˈkiːləʊ/','/ˈkiːləʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freedom','n.自由','/ˈfɹiːdəm/','/ˈfɹidəm/','noun',["Having recently been released from prison, he didn''t know what to do with his newfound freedom.","Every child has a right to freedom from fear and freedom from want."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cushion','n.垫子','/ˈkʊʃən/','/ˈkʊʃən/','noun',["to cushion a sofa","to cushion a blow"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scold','vt.责骂，谴责','/skəʊld/','/skoʊld/','verb',["to scald the hand","Scald the milk until little bubbles form."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modern','adj.现代的，近代的；时尚的','/ˈmɒd(ə)n/','/ˈmɑdɚn/','noun',["Our online interactive game is a modern approach to teaching about gum disease.  Although it was built in the 1600s, the building still has a very modern look."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physics','n.物理','/ˈfɪz.ɪks/','/ˈfɪz.ɪks/','noun',["Newtonian physics was extended by Einstein to explain the effects of travelling near the speed of light; quantum physics extends it to account for the behaviour of atoms.","The physics of car crashes would not let Tom Cruise walk away like that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seldom','adv.很少，不常','/ˈsɛldəm/','/ˈsɛldəm/','adjective',["They seldom come here now."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physician','n.医生','/fɪˈzɪʃən/','/fɪˈzɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protect','vt.保护','/pɹəˈtɛkt/','/pɹəˈtɛkt/','verb',["Condoms are designed to protect against sexually-transmitted diseases."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('architecture','n.建筑，建筑学','/ˈɑː.kɪ.ˌtɛk.tʃə/','/ˈɑɹkɪtɛktʃɚ/','noun',["Architecture is the visual public expression of a culture’s achievements, values, and outlook. ― Max Roscoe, \"How Your City Is Killing You With Ugliness\"","The Intel architectures have more software written for them.","The architecture of the company''s billing system is designed to support its business goals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('souvenir','n.纪念品，纪念物','/ˌsuːvəˈnɪə(ɹ)/','/ˌsuːvəˈnɪə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dial','v.拨','/ˈdaɪəɫ/','/ˈdaɪəɫ/','noun',["President Trump has recently dialled down the rhetoric.","In an emergency dial 999.","Please be careful when dialling."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stress','n.压力vt.强调','/stɹɛs/','/stɹɛs/','noun',["Go easy on him, he''s been under a lot of stress lately.","Some people put the stress on the first syllable of “controversy”; others put it on the second.","“Emphasis” is stressed on the first syllable, but “emphatic” is stressed on the second."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explore','v.探险；探索','/ɪkˈsplɔː/','/ɪkˈsplɔɹ/','noun',["The committee has been exploring alternative solutions to the problem at hand.","It was around that time that the expedition began exploring the Arctic Circle.","It is normal for a boy of this age to be exploring his sexuality."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('more','adv.更pron.更多的…；另外的…adj.更多的','/ˈmɔː/','/ˈmɔɹ/','adverb',["I could no more climb that than fly!","You''re more beautiful than I ever imagined.","I was more better at English than you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wet','adj.湿的','/wɛt/','/wɛt/','noun',["Don''t go out in the wet.","Johnny wets the bed several times a week.","Wet ''em up!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('born','adj.出生的','/ˈbɔːn/','/ˈbɔɹn/','verb',["Judging from the look on his face, he wasn''t bearing good news.","By my readings, we''re bearing due south, so we should turn about ten degrees east."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strawberry','n.草莓','/ˈstɹɔːb(ə)ɹi/','/ˈstɹɔːb(ə)ɹi/','noun',["They went to pick strawberries today.","She has the best strawberry patch I''ve ever seen.","I''d like a large strawberry shake."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electricity','n.电；电流','/ɪˌlɛkˈtɹɪsɪti/','/iˌlɛkˈtɹɪsɪti/','noun',["Opening night for the new production had an electricity unlike other openings."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tentative','adj.试验性的；试探的n.试验；假设','/ˈtɛntətɪv/','/ˈtɛntətɪv/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('climate','n.气候；风气；环境气氛','/ˈklaɪmɪt/','/ˈklaɪmɪt/','noun',["Industries that require a lot of fossil fuels are unlikely to be popular in the current political climate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kill','vt.杀死，弄死；消磨','/kɪl/','/kɪl/','noun',["The assassin liked to make a clean kill, and thus favored small arms over explosives.","The hunter delivered the kill with a pistol shot to the head.","The fox dragged its kill back to its den."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conductor','n.管理人；指导者；售票员，列车员；乐队指挥','/kənˈdʌktɚ/','/kənˈdʌktɚ/','noun',["train conductor; tram conductor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('porridge','n.稀饭，粥','/ˈpɔɹɪdʒ/','/ˈpɔɹɪdʒ/','noun',["Eat your porridge while it''s hot!","Just do your porridge and keep your head down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleased','adj.高兴的','/pliːzd/','/pliːzd/','verb',["Her presentation pleased the executives.","Just do as you please."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certain','adj.某些；确定的，无疑的；一定会…','/ˈsɝtn̩/','/ˈsɝtn̩/','noun',["I was certain of my decision.","Bankruptcy is the certain outcome of your constant gambling and lending.","There were serious objections to certain of the proposals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('woolen','adj.羊毛的，羊毛制的','/ˈwʊlən/','/ˈwʊlən/','noun',["Put all the woolens in this basket.","a woolen draper"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('board','n.木板；布告牌；委员会vt.上','/bɔːd/','/bɔːd/','noun',["Each player starts the game with four counters on the board.","We have to wait to hear back from the board.","Room and board"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statistics','n.统计表，数字，数据','/stəˈtɪstɪks/','/stəˈtɪstɪks/','noun',["Statistics is the only mathematical field required for many social sciences."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shut','v.（使）关[合]上，（使）关闭adj.关闭的，关上的','/ʃʌt/','/ʃʌt/','adjective',["a close alley; close quarters","Is your house close?","He is a close friend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrest','vt&n.逮捕，拘留','/əˈɹɛst/','/əˈɹɛst/','noun',["The police have arrested a suspect in the murder inquiry."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinction','n.区别；差别','/dɪˈstɪŋkʃən/','/dɪˈstɪŋkʃən/','noun',["There is a distinction to be made between resting and slacking.","She had the distinction of meeting the Queen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('widow','n.寡妇','/ˈwɪ.dəʊ/','/ˈwɪ.doʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mature','adj.成熟的，成年的','/məˈtjʊə/','/məˈtjʊə/','adjective',["She is quite mature for her age.","a mature plan","The headmaster decided to expel the boy after a mature consideration."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('navy','n.海军','/ˈneɪvi/','/ˈneɪvi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disability','n.残疾；无能','/dɪsəˈbɪlɪti/','/dɪsəˈbɪlɪti/','noun',["Dyscalculia is math disability.","Did you get your disability this month?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fee','n.费，费用','/fiː/','/fiː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('section','n.段；部分；部门','/ˈsɛkʃən/','/ˈsɛkʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simple','adj.简单的，简易的','/ˈsɪmpəl/','/ˈsɪmpəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('used','adj.用过的；旧的，二手的','/juːzd/','/juːzd/','verb',["soldiers who are used to hardships and danger","I used to get things done.","to use an animal cruelly"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('influence','n&vt.影响','/ˈɪn.flu.əns/','/ˈɪn.flu.əns/','noun',["I have absolutely no influence over him.","I''m not able to exercise influence over him.","He has been a great influence on the voters during the elections."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mustard','n.芥末，芥子粉','[ˈmɐs.təd]','[ˈmɐs.təd]','noun',["When the waitress brought the food, I asked whether she had any Dijon mustard.","Mustard and cress sandwiches."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percentage','n.百分率；比例','/pəˈsɛntɪd͡ʒ/','/pɚˈsɛntɪd͡ʒ/','noun',["A high percentage of secondary school leavers take a gap year.","She gets a percentage for every vacuum cleaner sold.","There was no percentage in staying at home."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talent','n.天才，才能','/ˈtalənt/','/ˈtælənt/','noun',["He has a real talent for drawing.","The director searched their talent pool to fill the new opening.","Not much talent in this bar tonight—let''s hit the clubs."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('few','pron.不多，少数adj.不多的，少数的','/fjuː/','/fju/','pronoun',["Many are called, but few are chosen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('otherwise','adv.否则，要不然','/ˈʌð.əˌwaɪz/','','adjective',["He said he didn’t do it, but the evidence was otherwise.","Could I do otherwise than smile?.","I’m not well today, otherwise I would have helped.  You have to open your umbrella, otherwise you''ll get wet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negotiate','v.谈判，协商','/nəˈɡəʊ.ʃi.eɪt/','/nəˈɡoʊ.ʃi.eɪt/','verb',["The client and server computers must first negotiate a network protocol to be used.","Although the car was quite rickety, he could negotiate the curves very well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hunt','v&n.寻找；狩猎，猎取','/hʌnt/','/hʌnt/','noun',["Her uncle will go out and hunt for deer, now that it is open season.","The little girl was hunting for shells on the beach.","He was hunted from the parish."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('package','n.一包，一袋，一盒；包裹','/ˈpækɪdʒ/','/ˈpækɪdʒ/','noun',["Did you test the software package to ensure completeness?","For third and short, they''re going to bring in their jumbo package."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pronunciation','n.发音','/pɹəˌnaʊn.siˈeɪ.ʃən/','/pɹəˌnaʊn.siˈeɪ.ʃən/','noun',["What is the pronunciation of \"hiccough\"?","His Italian pronunciation is terrible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kind','adj.善良的，亲切的，和蔼的，仁慈的n.[C]种；类','/kaɪnd/','/kaɪnd/','noun',["This is a strange kind of tobacco.","The opening served as a kind of window.","I''ll pay in kind for his insult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('survival','n.幸存；生存','/sɚˈvaɪvəl/','/sɚˈvaɪvəl/','noun',["His survival in the open ocean was a miracle; he had fully expected to die.","His survival kit had all the things he needed in the wilderness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strait','n.海峡','/stɹeɪt/','/stɹeɪt/','noun',["The Strait of Gibraltar","to be in dire straits","to follow the strait and narrow"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('both','pron.两者都；双方都adj.双方的','/bəʊθ/','/boʊθ/','pronoun',["\"Did you want this one or that one?\" — \"Give me both.\"","Both you and I are students."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voyage','n.航行，旅行','/ˈvɔɪ.ɪdʒ/','/ˈvɔɪ.ɪdʒ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('important','adj.重要的','/ɪmˈpɔːtənt/','/ɪmˈpɔɹtənt/','adjective',["It is very important to give your daughter independence in her life so she learns from experience."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nutrition','n.营养','/njuːˈtɹɪ.ʃən/','/nuˈtɹɪ.ʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detective','n.侦探','/dɪˈtɛktɪv/','/dɪˈtɛktɪv/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phrase','n.短语，习惯用语','/fɹeɪz/','/fɹeɪz/','noun',["I wasn''t sure how to phrase my condolences without sounding patronising."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personally','adv.就自己而言','/ˈpɜːsnəli/','/ˈpɜːsnəli/','adverb',["Personally, I think that …","I like you personally, but as a colleague you are useless."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outside','adv.在外面，向外面，出界adj.外面的，外表的prep.在…外n.外面，外表，外界','','','noun',["He''s repainting the outside of his house.","Her outside was stern, but inside was a heart of gold.","Viewed from the outside, the building seemed unremarkable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passer-by','n.过客，过路人','','','noun',["When he tripped and fell in the street, several kind passers-by helped him up."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keep','v.保留；保存；使…保持某种状态；保持，继续','/kiːp/','/kiːp/','noun',["He works as a cobbler''s apprentice for his keep.","to be in good keep","to keep silence;  to keep one''s word;  to keep possession"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('effect','n.效果；作用，影响','/ɪˈfɛkt/','/əˈfɛkt/','noun',["The effect of the hurricane was a devastated landscape.","The effect of flying was most convincing.","I just bought a couple of great effects."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affection','n.友爱；爱情','/əˈfɛkʃən/','/əˈfɛkʃən/','noun',["I have a lot of affection for my little sister."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yoghurt','n.酸乳酪','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skate','vi.溜冰，滑冰','/skeɪt/','/skeɪt/','noun',["There''s time for a quick skate before dinner.","The boys had a skate every morning when the lake was frozen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correction','n.改正','/kəˈɹɛkʃən/','/kəˈɹɛkʃən/','noun',["I have four T-80 tanks at grid Three-niner-niner-four-eight-eight, Correction: Grid Three niner-niner-four-eight-five. How copy? Over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embarrass','vt.使困窘，使局促不安','/ɪmˈbæ.ɹəs/','/ɪmˈbæ.ɹəs/','verb',["The crowd''s laughter and jeers embarrassed him.","The motion was advanced in order to embarrass the progress of the bill.","A man or his business is embarrassed when he cannot meet his pecuniary engagements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('who','pron.谁','/huː/','/huː/','noun',["I don''t know who it is. (indirect question)","I don''t like what you did, but who am I to criticize you? I''ve done worse.","It was a nice man who helped us."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weigh','v.称量；重','/weɪ/','/weɪ/','verb',["He weighed out two kilos of oranges for a client.","You have been weighed in the balance and found wanting.","I weigh ten and a half stone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sponsor','n.赞助者；主办者vt.赞助；主办','/ˈspɒn.sə/','/ˈspɒn.sə/','noun',["He was my sponsor when I applied to join the club.","And now a word from our sponsor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acute','adj.尖锐的；敏锐的；严重的；急性的','/əˈkjuːt/','/əˈkjut/','noun',["The word ‘cafe’ often has an acute over the ‘e’.","He acutes his rising inflection too much.","It was an acute event."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kindergarten','n.幼儿园','/ˈkɪndəɹˌɡɑːɹd(ə)n/','/ˈkɪndəɹˌɡɑːɹd(ə)n/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jog','v.慢跑','/dʒɒɡ/','/dʒɑɡ/','noun',["jog one''s elbow","I tried desperately to jog my memory.","to jog a horse"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terrify','vt.使人感到害怕，使恐惧','/ˈtɛɹɪfaɪ/','/ˈtɛɹɪfaɪ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contribute','v.捐款，捐献','/kənˈt(ʃ)ɹɪb.juːt/','/kənˈt(ʃ)ɹɪb.jut/','verb',["to contribute articles to a journal"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faith','n.信仰，信念；信任','/feɪθ/','/feɪθ/','noun',["I have faith in the goodness of my fellow man.","I have faith in the healing power of crystals.","The Christian faith."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insert','vt.插入','/ɪnˈsɜːt/','/ɪnˈsɜːt/','noun',["This software can print compact disc inserts if you have the right size of paper.","a threaded insert","In order to withdraw money from a cash machine, you have to insert your debit card."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('why','adv.为什么interjection.哎呀，嗨〔表示惊讶或突然意识到某事〕','/waɪ/','/waɪ/','noun',["A good article will cover the who, the what, the when, the where, the why and the how.","That''s the reason why I did that."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remark','n&v.陈述，评论','/ɹɪˈmɑːk/','/ɹɪˈmɑɹk/','noun',["a biting remark","He remarked that it was getting late."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forbid','v.禁止，不许','/fəˈbɪd/','/fɚˈbɪd/','verb',["Smoking in the restaurant is forbidden.","An impassable river forbids the approach of the army.","What part of \"no\" do you forbid to understand?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microscope','n.显微镜','/ˈmaɪkɹəˌskəʊp/','/ˈmaɪkɹəˌskəʊp/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tortoise','n.乌龟','/ˈtɔː.təs/','/ˈtɔːɹ.təs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candidate','n.候选人','/ˈkæn.dɪdət/','/ˈkæn.dɪ.deɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alone','adj.单独的，孤独的','/əˈləʊn/','/əˈloʊn/','adjective',["I can''t ask for help because I am alone.","Jones alone could do it.","She walked home alone."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('database','n.资料库，数据库','/ˈdeɪtəˌbeɪs/','/ˈdeɪtəˌbeɪs/','noun',["I have a database of all my contacts in my personal organizer.","The \"books\" database will have three tables, and the \"customers\" database will have two tables.","Which database do you use: MySQL or Oracle?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parallel','adj.平行的n.平行线；类似','/ˈpæɹəˌlɛl/','/ˈpæɹəˌlɛl/','noun',["The 31st parallel passes through the center of my town.","Johnson''s parallel between Dryden and Pope","The horizontal lines on my notebook paper are parallel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patient','adj.耐心的n.病人','/ˈpeɪʃənt/','/ˈpeɪʃənt/','noun',["The subject of a passive verb is usually a patient.","Be patient: your friends will arrive in a few hours.","patient endeavour"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reject','vt.拒绝','','','noun',["She even rejected my improved offer.","I''ve been rejected three times this week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dialogue','n.对话','/ˈdaɪəlɑɡ/','/ˈdaɪəlɔɡ/','noun',["Bill and Melinda maintained a dialogue via email over the course of their long-distance relationship.","The movie had great special effects, but the dialogue was lackluster.","A literary historian, she specialized in the dialogues of ancient Greek philosophers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diet','v.节食n.饮食；节食','/ˈdaɪət/','/ˈdaɪət/','noun',["The diet of the Giant Panda consists mainly of bamboo.","He''s been reading a steady diet of nonfiction for the last several years.","diet soda"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profit','v.赢利，获益于n.利润，益处','/ˈpɹɒfɪt/','/ˈpɹɑfɪt/','noun',["Reading such an enlightening book on the subject was of much profit to his studies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('win','v.赢得，获胜','/wɪn/','/wɪn/','verb',["to win the jackpot in a lottery;  to win a bottle of wine in a raffle","Who would win in a fight between an octopus and a dolphin?","Ever since the 2013 Boston Marathon bombing, Bostonians now run as \"One Boston.\" The terrorists did not win."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rest','vi.休息，歇息n.休息；剩余的部分，其余的人','/ɹɛst/','/ɹɛst/','noun',["I need to get a good rest tonight; I was up late last night.","We took a rest at the top of the hill to get our breath back.","It was nice to have a rest from the phone ringing when I unplugged it for a while."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('move','v.移动，搬动，搬家','/muːv/','/muːv/','noun',["A slight move of the tiller, and the boat will go off course.","He made another move towards becoming a naturalized citizen.","She always gets spontaneous applause for that one move."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amount','vi.总计；等于n.数量','/əˈmaʊnt/','/əˈmaʊnt/','noun',["The amount of atmospheric pollution threatens a health crisis.","Pour a small amount of water into the dish.","It amounts to three dollars and change."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handful','n.把；少数，少量','/ˈhæn(d)fəl/','/ˈhæn(d)fəl/','noun',["Those twins are a real handful to look after."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('album','n.照相簿；集邮本；签名纪念册','/ˈælbəm/','/ˈælbəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electric','adj.电的','/əˈlɛktɹɪk/','/əˈlɛktɹɪk/','noun',["We had to sit in the dark because the electric was cut off."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yawn','v.打呵欠','/jɔːn/','/jɔːn/','noun',["The slideshow we sat through was such a yawn. I was glad when it finished.","I could see my students yawning, so I knew the lesson was boring them.","Death yawned before us, and I hit the brakes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('say','v.说，讲','/seɪ/','/seɪ/','noun',["Please say your name slowly and clearly.","Martha, will you say the Pledge of Allegiance?","He said he would be here tomorrow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('also','adv.也','/ˈɔːl.səʊ/','/ˈɔl.soʊ/','adverb',["They had porridge for breakfast, and also toast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terminal','n.终点站；终端','/ˈtɚmɪnəl/','/ˈtɚmɪnəl/','noun',["terminal cancer","a student''s terminal fees"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enough','n&adj&adv.足够；充足','/iˈnʌf/','/iˈnʌf/','adverb',["Are you man enough to fight me?","He is ready enough to accept the offer.","Enough of you are here to begin the class."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('increase','v.增加，繁殖n.增加，加大','','','noun',["His rage only increased when I told him of the lost money.","The Moon increases."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('differ','vi.不一致，有区别','/ˈdɪfə/','/ˈdɪfɚ/','verb',["These shoes only differ from those ones in having slightly longer laces.","The numbers 3 and 21 differ by 18."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shine','v.发光；照耀','/ʃaɪn/','/ʃaɪn/','noun',["She''s certainly taken a shine to you.","My nephew tried other sports before deciding on football, which he shone at right away, quickly becoming the star of his school team.","I shone my light into the darkness to see what was making the noise."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spread','n&v.延伸，展开；传播','/spɹɛd/','/spɹɛd/','noun',["He spread his newspaper on the table.","I spread my arms wide and welcomed him home.","I spread the rice grains evenly over the floor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('various','adj.各种各样的，不同的','/ˈvɛə.ɹi.əs/','/ˈvæɹ.i.əs/','adjective',["The reasons are various.","a various reading of a Biblical text"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attention','n.注意；关心','/əˈtɛn.ʃən/','/əˈtɛn.ʃən/','noun',["Please direct your attention to the following words.","The company will now come to attention."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('latter','n.后者','/ˈlæt̬.əɹ/','/ˈlæt̬.əɹ/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('front','adj.前面的；前部的n.前面；前部；前线','/fɹʌnt/','/fɹʌnt/','noun',["Officially it''s a dry-cleaning shop, but everyone knows it''s a front for the mafia.","He says he likes hip-hop, but I think it''s just a front.","to front court"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visit','n&v.参观，访问，拜访','/ˈvɪzɪt/','/ˈvɪzɪt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clinic','n.诊所','/ˈklɪnɪk/','/ˈklɪnɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('customer','n.顾客，主顾','/ˈkʌstəmə/','/ˈkʌstəmə/','noun',["Every person who passes by is a potential customer.","a cool customer, a tough customer, an ugly customer"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stupid','adj.愚蠢的，笨的','/ˈstjuːpɪd/','/ˈst(j)upɪd/','noun',["His stupid knows no bounds.","Neurobiology bores me stupid.","That dunk was stupid! His head was above the rim!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greeting','n.祝贺；问候；致谢','/ˈɡɹiːtɪŋ/','/ˈɡɹiːtɪŋ/','verb',["A brilliant dawn greeted her eyes as she looked out of the window.","It''s polite to begin a letter with a greeting, but this practice is less common in email."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bring','vt.拿来，带来，取来','/ˈbɹɪŋ/','/ˈbɹɪŋ/','verb',["Waiter, please bring me a single malt whiskey.","The new company director brought a fresh perspective on sales and marketing.","The controversial TV broadcast brought a storm of complaints."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beddings','n.被褥','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awake','v.唤醒adj.醒着的','/əˈweɪk/','/əˈweɪk/','adjective',["They were awake to the possibility of a decline in sales."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kiss','n.[C]吻，亲吻vt.吻，亲吻','/kɪs/','/kɪs/','verb',["His ball kissed the black into the corner pocket."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ban','vt.禁止；取缔n.禁令','/bæn/','/bæn/','noun',["Bans is common and ordinary amongst the Feudists, and signifies a proclamation, or any public notice.","France was at such a Pinch..that they call''d their Ban and Arriere Ban, the assembling whereof had been long discussed, and in a manner antiquated.","Bare feet are banned in this establishment."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hamburger','n.汉堡包','/ˈhæm.bə.ɡə/','/ˈhæm.bə.ɡə/','noun',["I''m going to make you into hamburger if you do that again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fond','adj.喜爱的，爱好的','/fɒnd/','/fɑnd/','verb',["a fond farewell","I have fond grandparents who spoil me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fit','v.适合adj.适合的，健康的','/fɪt/','/fɪt/','noun',["Since he put on weight, his jeans have been a tight fit.","It''s hard to get a good fit using second-hand parts.","The Wonder Bread advertising research results showed the “White Picket Fence” commercial had strong fit ratings."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offer','v&n.提供；提出；出价','/ˈɑfɚ/','/ˈɔfɚ/','noun',["I decline your offer to contract.","His offer was $3.50 per share.","His first letter was not a real offer, but an attempt to determine interest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('robot','n.机器人','/ˈɹoʊbət/','/ˈɹoʊbɑt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bar','n.酒吧；条，横木；栅栏','/bɑː/','/bɑɹ/','noun',["The window was protected by steel bars.","Ancient Sparta used iron bars instead of handy coins in more valuable alloy, to physically discourage the use of money.","bar of chocolate"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suffer','v.受苦，遭受','/ˈsʌfə/','/ˈsʌfɚ/','verb',["Is anyone here afraid of suffering hardship?","At least he didn''t suffer when he died in the car crash.","If you keep partying like this, your school-work will suffer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fix','v.修理，安装；确定，决定','/ˈfɪks/','/ˈfɪks/','noun',["That plumber''s fix is much better than the first one''s.","It rained before we repaired the roof, and were we in a fix!","We have a fix on your position."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neighbourhood','n.四邻，邻近地区','','','noun',["Our neighborhood was our only reason to exchange hollow greetings.","He lives in my neighborhood.","The fire alarmed the neighborhood."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complex','adj.复杂的；联合的n.联合体','','','noun',["Jim has a real complex about working for a woman boss."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('draft','vt.起草n.草稿','/dɹæft/','/dɹæft/','noun',["She took a deep draft from the bottle of water.","His first drafts were better than most authors'' final products.","He left the country to avoid the draft."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('honest','adj.诚实的，正直的','/ˈɒnɪst/','/ˈɑnɪst/','verb',["We’re the most honest people you will ever come across.","an honest account of events","an honest mistake"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pension','n.养老金','/ˈpɛnʃ(ə)n/','/ˈpɛnʃ(ə)n/','noun',["Many old people depend on their pension to pay the bills.","A pension had somewhat less to offer than a hotel; it was always smaller, and never elegant; it sometimes offered breakfast, and sometimes not (John Irving)."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assumption','n.假设，假定','/əˈsʌmp.ʃən/','/əˈsʌmp.ʃən/','noun',["His assumption of secretarial duties was timely.","Their assumption of his guilt disqualified them from jury duty."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rank','n.等级，级别；职衔，军衔','/ɹæŋk/','/ɹæŋk/','adjective',["rank nonsense","rank grass","rank land"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rubbish','n.垃圾；废物','/ˈɹʌbɪʃ/','/ˈɹə-/','noun',["The rubbish is collected every Thursday in Gloucester, but on Wednesdays in Cheltenham.","Much of what they sell is rubbish.","Everything the teacher said during that lesson was rubbish. How can she possibly think that a bass viol and a cello are the same thing?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('addition','n.增加；加法','/æˈdɪʃən/','/æˈdɪʃən/','noun',["The addition of five more items to the agenda will make the meeting unbearably long."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afterwards','adv.后来','/ˈɑːftə.wədz/','/ˈæf.tɚ.wɚdz/','adverb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sure','adv.〈口语〉的确，一定，当然adj.确信，肯定','/ʃoː/','/ʃɔɹ/','adjective',["This investment is a sure thing.   The bailiff had a sure grip on the prisoner''s arm.","He was sure she was lying.   I am sure of my eventual death.   John was acting sure of himself but in truth had doubts.","Be sure to lock the door when you leave."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grow','v.种植；生长，发育；渐渐变得，变成','/ɡɹəʊ/','/ɡɹoʊ/','verb',["Children grow quickly.","A long tail began to grow from his backside.","As I grew throughout adolescence, I came to appreciate many things about human nature."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carve','v.刻；雕刻','/kɑːv/','/kɑɹv/','noun',["give that turkey a careful carve","You carve the roast and I''ll serve the vegetables.","to carve a name into a tree"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrink','v.收缩；缩短','/ˈʃɹɪŋk/','/ˈʃɹɪŋk/','noun',["My shrink said that he was an enabler, bad for me.","The dryer shrank my sweater.","This garment will shrink when wet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ancestor','n.祖宗，祖先','/ˈæn.sɛs.tə/','/ˈæn.sɛs.tɚ/','noun',["This fossil animal is regarded as the ancestor of the horse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('league','n.联盟，社团','/liːɡ/','/liːɡ/','noun',["the League of Nations","My favorite sports organizations are the National Football League and the American League in baseball.","Forget about dating him; he''s out of your league."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personal','adj.个人的，私人的','/ˈpɜː.sən.əl/','/ˈpɜɹ.sən.əl/','noun',["Her song was her personal look at the values of friendship.","personal charms","a personal interview;  personal settings"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('angry','adj.生气的，愤怒的','/ˈæŋ.ɡɹi/','/ˈæŋ.ɡɹi/','adjective',["An angry mob started looting the warehouse.","The broken glass left two angry cuts across my arm.","Angry clouds raced across the sky."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('former','adj.以前的，从前的；前者','/ˈfɔːmə/','/ˈfɔɹmɚ/','adjective',["A former president;  the former East Germany","I drive two vehicles, a Chevy Camaro and an AMC Gremlin. I won the former on a game show."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('panic','v.惊恐，恐慌n.惊慌，恐慌','/ˈpænɪk/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fold','v.折叠；合拢；包围','/fəʊld/','/foʊld/','noun',["After two reraises in quick succession, John realised his best option was probably a fold.","If you fold the sheets, they''ll fit more easily in the drawer.","Cardboard doesn''t fold very easily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stewardess','n.女乘务员，空中小姐','/stjuː.əˈdɛs/','/stjuː.əˈdɛs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('as','adv.像…一样conj.当…时；正如；因为；尽管prep.作为，以…身份','','','adverb',["It''s not as well made, but it''s twice as expensive.","1865, The Act of Suicide as Distinct from the Crime of Self-Murder: A Sermon","They''re big as houses."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delay','n&v.拖延','/dɪˈleɪ/','/dɪˈleɪ/','noun',["the delay before the echo of a sound","The mail is delayed by a heavy fall of snow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('at','prep.在…；以…','','','verb',["Cars 2 is the most influential film of all time. Don''t @ me.","Caesar was at Rome;  at the corner of Fourth Street and Vine;  at Jim’s house","at six o’clock;  at closing time;  at night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chemical','adj.化学的n.化学制品','/ˈkɛmɪkəl/','/ˈkɛmɪkəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turning','n.拐弯处，拐角处','[ˈtɜː.nɪŋ]','[ˈtɝ.nɪŋ]','verb',["They say they can turn the parts in two days.","We turned a pretty penny with that little scheme.","Ivory turns well."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peace','n.和平；安宁','/piːs/','/piːs/','noun',["Our lounge strives to maintain an environment of peace for the comfort of our customers.","The safety equipment will give me some peace of mind.","May there be peace in our time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plant','vt.种植；播种n.植物','/plɑːnt/','/plænt/','noun',["The garden had a couple of trees, and a cluster of colourful plants around the border.","That gun''s not mine! It''s a plant! I''ve never seen it before!","That gun''s not mine! It was planted there by the real murderer!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('folk','adj.民间的','/fəʊk/','/foʊk/','noun',["Young folk, old folk, everybody come, / To our little Sunday School and have a lot of fun.","folk psychology; folk linguistics"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enquiry','n.询问','/ɛnˈkwaɪ.ɹi/','/ɛnˈkwaɪ.ɹi/','noun',["scientific enquiry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drive','v.驾驶，开；驱赶','/dɹaɪv/','/dɹaɪv/','noun',["Crassus had wealth and wit, but Pompey had drive and Caesar as much again.","Napoleon''s drive on Moscow was as determined as it was disastrous.","Some old model trains have clockwork drives."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurt','v.伤害','/hɜːt/','/hɝt/','noun',["how to overcome old hurts of the past","Does your leg still hurt? / It is starting to feel better.","If anybody hurts my little brother, I will get upset."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deal','v.处理n.量，数额；交易','/diːl/','/diːl/','noun',["We gave three deals of grain in tribute to the king."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abuse','vt.滥用n.辱骂，粗话','/əˈbjuːs/','/əˈbjus/','noun',["All abuse, whether physical, verbal, psychological or sexual, is bad."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prove','vi.证明是，结果是，原来是vt.证明，证实','/pɹuːv/','/pɹuːv/','verb',["I will prove that my method is more effective than yours.","It proved to be a cold day.","Have an exit strategy should your calculations prove incorrect."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homeland','n.祖国','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affect','vt.影响','/əˈfɛkt/','/əˈfɛkt/','verb',["The experience affected me deeply.","He was deeply affected by the tragic ending of the play.","Hepatitis affects the liver."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deaf','adj.聋的','/diːf/','/diːf/','noun',["Those people are deaf to reason.","a deaf nut; deaf corn"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admire','vt.钦佩；羡慕','/ədˈmaɪə/','/ədˈmaɪɹ/','verb',["He had always admired the work ethos and family values of his friend."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virus','n.病毒','/ˈvaɪɹəs/','/ˈvaɪɹəs/','noun',["He caught a virus and had to stay home from school."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amuse','vt.使快乐，逗乐','/əˈmjuːz/','/əˈmjuːz/','verb',["I watch these movies because they amuse me.","His jokes rarely fail to amuse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('see','v.看见，看到；领会','/siː/','/siː/','verb',["1999 saw the release of many great films.","I''ll see you hang for this!  I saw that they didn''t make any more trouble.","I saw the old lady safely across the road."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('search','n&v.搜寻，搜查','/sɜːt͡ʃ/','/sɝt͡ʃ/','noun',["With only five minutes until we were meant to leave, the search for the keys started in earnest.","Search is a hard problem for computers to solve efficiently.","I searched the garden for the keys and found them in the vegetable patch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furnished','adj.配备了家具的','/ˈfɜːnɪʃt/','/ˈfɝnɪʃt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('responsibility','n.责任','/ɹɪˌspɑnsəˈbɪlɪɾi/','/ɹɪˌspɑnsəˈbɪlɪɾi/','noun',["Responsibility is a heavy burden.","Why didn''t you clean the house? That was your responsibility!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sudden','adj.突然的','/ˈsʌdən/','/ˈsʌdən/','noun',["The sudden drop in temperature left everyone cold and confused."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fool','v.欺骗；做蠢事；游手好闲n.傻子，蠢人，白痴','/fuːl/','/fuːl/','noun',["The village fool threw his own shoes down the well.","an apricot fool; a gooseberry fool"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civil','adj.国内的；平民的；民事的','/ˈsɪv.əl/','/ˈsɪv.əl/','adjective',["She went into civil service because she wanted to help the people.","It was very civil of him to stop the argument.","a civil case"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('by','prep.靠近；到…时；被；由；以…的标准','/baɪ/','/baɪ/','noun',["geography bee","I watched as it passed by.","The shop is hard by the High Street."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whom','pron&conj.谁','/huːm/','/huːm/','pronoun',["He''s a person with whom I work. (defining)","To whom it may concern, all business of John Smith Ltd. has now been transferred to Floggitt & Runne."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indicate','vt.指出，显示','/ˈɪndɪkeɪt/','/ˈɪndɪkeɪt/','verb',["The guard blew his whistle to indicate imminent departure.","Great prostration of strength indicates the use of stimulants."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('set','vt.设置，调整；树立；摆放；日落n.一套；设备','/sɛt/','/sɛt/','verb',["Set the tray there.","I have set my heart on running the marathon.","to set a coach in the mud"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charge','v.收费；指控；索价；充电n.费用，价钱','/t͡ʃɑːd͡ʒ/','/t͡ʃɑɹd͡ʒ/','noun',["There will be a charge of five dollars.","Pickett did not die leading his famous charge.","That''s a slanderous charge of abuse of trust."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contain','vt.包含；包括','/kənˈteɪn/','/kənˈteɪn/','verb',["I''m so excited, I can hardly contain myself!","A group contains a unique inverse for each of its elements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outstanding','adj.突出的，显著的；杰出的','','','verb',["outstanding contracts"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('litter','v.乱丢杂物','/ˈlɪtə(ɹ)/','/ˈlɪtɚ/','noun',["sleep in the litter","drop litter","the cat''s litter"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oval','adv.椭圆','/ˈəʊvəl/','/ˈəʊvəl/','noun',["oval conceptions"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('procedure','n.程序，手续','/pɹəˈsiːdʒə/','/pɹəˈsidʒɚ/','noun',["Ensure that you follow procedure when accessing customers'' personal information."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('familiar','adj.熟悉的','/fəˈmɪl.i.ə/','/fəˈmɪl.i.ɚ/','noun',["The witch’s familiar was a black cat.","there’s a familiar face; that tune sounds familiar","I''m quite familiar with this system; she''s not familiar with manual gears"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biography','n.传记','/baɪˈɒɡɹəfi/','/baɪˈɑːɡɹəfi/','noun',["There are many biographies of Benjamin Franklin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breathe','v.呼吸','/bɹiːð/','/bɹið/','verb',["Fish have gills so they can breathe underwater.","While life as we know it depends on oxygen, scientists have speculated that alien life forms might breathe chlorine or methane.","I will not allow it, as long as I still breathe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applicant','n.申请人','/ˈæp.lə.kɪnt/','/ˈæp.lə.kɪnt/','noun',["Our job advertisement attracted seven applicants."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('battle','n.战斗；战役','/ˈbætəl/','/ˈbætl̩/','noun',["the battle of life","Scientists always battle over theories.","She has been battling cancer for years."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awesome','adj.可怕的；引起敬畏的','/ˈɔːsəm/','/ˈɔs.əm/','noun',["pure awesome; made of awesome","The tsunami was awesome in its destructive power.","Awesome, dude!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partner','n.搭档，合作者','/ˈpɐːtnə/','/ˈpɑɹtnɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gifted','adj.有天赋的，有才华的','/ˈɡɪftɪd/','/ˈɡɪftɪd/','verb',["a gifted artist"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visa','n.签证','/ˈviː.sə/','/ˈviː.sə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zipper','n.拉链','/ˈzɪpɚ/','/ˈzɪpɚ/','noun',["He zippered his sweater against the cold.","These fall jackets are zippered."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Arctic','n.北极','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unfit','adj.不适宜的，不相宜的','/ʌnˈfɪt/','/ʌnˈfɪt/','verb',["Jack cannot run, making him unfit for the track team.","I''ve become so unfit after stopping cycling to town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interview','n&v.采访；会见；面试','/ˈɪntəvjuː/','/ˈɪntɚvjuː/','noun',["The reporter gave the witness an interview.","It was a dreadful interview; I have no hope of getting the job.","He interviewed the witness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clarify','v.澄清，阐明','/ˈklæɹɪfaɪ/','/ˈklæɹɪfaɪ/','verb',["Leave the wine for 24 hours and it will clarify."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beauty','n.美，美丽；美人','/ˈbuːti/','/ˈbjuɾi/','noun',["1988, \"… beauty and recollection, like danger, glamour, greed, hunger- everything but disappointment and desire- were concepts belonging to other people.” -Second Son, Robert Ferro","Brigitte Bardot was a renowned beauty.","What a goal! That was a real beauty!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beg','v.请求，乞求','/bɛɡ/','/bɛɡ/','noun',["He begged on the street corner from passers-by.","He begged her to go to the prom with him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scare','v.惊吓，威吓；受惊','/skɛə/','/skɛɚ/','noun',["Johnny had a bad scare last night.","a food-poisoning scare"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('do','v.用以构成疑问句及否定句vt.做，干','/dʉː/','/du/','noun',["We’re having a bit of a do on Saturday to celebrate my birthday.","Nice do!","All you ever do is surf the Internet. What will you do this afternoon?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('observe','v.观察；遵守','/əbˈzɝv/','/əbˈzɝv/','verb',["From this vantage point we can observe the behavior of the animals in their natural habitat.","Please observe all posted speed limits.","The senator observed that the bill would be detrimental to his constituents."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humorous','adj.幽默的','/ˈhjuːməɹəs/','/ˈhjuːməɹəs/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garment','n.衣服，外衣','/ˈɡɑː.mənt/','/ˈɡɑː.mənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rare','adj.罕见的，稀有的','[ɹɜɹ]','/ɹɛəɹ/','noun',["Black pearls are very rare and therefore very valuable."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('useless','adj.无用的','/ˈjuːs.ləs/','/ˈjuːs.ləs/','adjective',["This fork has prongs that are bent. It''s useless now.","I think it''s useless to keep this discussion going. It''s like talking to a wall.","Bill never mows the lawn, takes out the trash or anything. He''s useless, but I love him anyways."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('which','pron.哪一个；哪一些','/wɪt͡ʃ/','/wɪt͡ʃ/','pronoun',["By now, you must surely know which is which.","Please take which you please.","He had to leave, which was very difficult."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disadvantage','n.不利条件；弱点','/ˌdɪsədˈvɑːntɪdʒ/','/ˌdɪsədˈvɑːntɪdʒ/','noun',["The disadvantage to owning a food processor is that you have to store it somewhere.","My height is a disadvantage for reaching high shelves.","They fear it might disadvantage honest participants to allow automated entries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garbage','n.垃圾','/ˈɡɑːbɪd͡ʒ/','/ɡɑ(ɹ)ˈbɑːʒ/','noun',["Garbage is collected on Tuesdays; rubbish on Fridays","The garbage truck collects all residential municipal waste.","He threw the newspaper into the garbage."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mainland','n.大陆','/ˈmeɪ̪nlənd/','/ˈmeɪ̪nlənd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downstairs','adv.在楼下，到楼下','/daʊnˈstɛəz/','/daʊnˈstɛɹz/','noun',["The wind lifted up her skirt and I caught a glimpse of her downstairs.","The kids sleep in the downstairs bedroom, we sleep in the upstairs one.","walk downstairs"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marble','n.大理石','/ˈmɑːbəl/','/ˈmɑɹbəl/','noun',["The Elgin Marbles were originally part of the temple of the Parthenon.","a marble mantel","a marble heart"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('never','adv.决不，从来没有','/ˈnɛv.ə(ɹ)/','/ˈnɛ.vɚ/','adverb',["I finally finished, and I never want to do that again.","I never saw him today."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anxiety','n.忧虑；焦急','/ˌæŋ(ɡ)ˈzaɪ.ə.ti/','/ˌæŋ(ɡ)ˈzaɪ.ə.ti/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('piece','n.一块；小的部分','/piːs/','/piːs/','noun',["I’d like another piece of pie.","a piece of machinery","a sixpenny piece"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjust','v.适应；调整，调节','/əˈdʒʌst/','/əˈdʒʌst/','verb',["Morimoto''s recipes are adjusted to suit the American palate.","He adjusted his initial conclusion to reflect the new data.","Most immigrants adjust quickly to a new community.   She waited for her eyes to adjust to the darkness."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carry','v.携带；搬运；背','/ˈkæ.ɹi/','/ˈkæ.ɹi/','noun',["Adjust your carry from time to time so that you don''t tire too quickly.","The carry on this trade is 25 basis points per annum.","to carry an account to the ledger"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burst','v.突然发生；爆炸','/bɜːst/','/bɝst/','noun',["The bursts of the bombs could be heard miles away.","I blew the balloon up too much, and it burst.","I burst the balloon when I blew it up too much."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('western','adj.西方的；西部的','/ˈwɛstən/','/ˈwɛstɚn/','noun',["the western approaches"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debt','n.债务，欠款','/dɛt/','/dɛt/','noun',["I am in your debt."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('little','adj.小的；少的','/ˈlɪtəl/','/ˈlɪtl̩/','noun',["Can I try a little of that sauce?","This is a little table.","It''s of little importance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('however','adv.可是，然而，尽管如此；无论如何','/hɑʊˈɛvə/','/haʊˈɛvɚ/','adverb',["He told me not to do it. I, however, did it anyway. / I did it anyway, however. / (sometimes proscribed:) However, I did it anyway.","However clear you think you''ve been, many questions will remain.","Let me know when you''ve had your interview, however it goes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deep','adv.深深地；在深处adj.深的；深厚的；沉睡的；渊博的','/diːp/','/diːp/','noun',["creatures of the deep","the deep of night","Russell is a safe pair of hands in the deep."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goose','n.鹅','/ˈɡuːs/','/ˈɡuːs/','noun',["There is a flock of geese on the pond."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forgive','vt.原谅，宽恕','/fɚˈɡɪv/','/fɚˈɡɪv/','verb',["Forgive others, not because they deserve forgiveness, but because you deserve peace."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('origin','n.起源；由来','/ˈɒɹ.ə.dʒən/','/ˈɑɹ.ɪ.dʒɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('for','conj.因为，由于prep.为了；在…期间；对于','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mistaken','adj.错误的','/mɪsˈteɪkən/','/mɪsˈteɪkən/','verb',["Don''t mistake my kindness for weakness.","A mistaken sense of loyalty.","He admitted he was mistaken about the budget numbers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('content','adj.满意的n.内容；含量','/kənˈtɛnt/','/kənˈtɛnt/','noun',["You can''t have any more - you''ll have to content yourself with what you already have."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deed','n.行为，事迹','/diːd/','/diːd/','noun',["I have fulfilled my promise in word and in deed.","I inherited the deed to the house.","He deeded over the mineral rights to some fellas from Denver."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burden','n.担子，负担','/ˈbɜːdn/','/ˈbɝdn/','noun',["a ship of a hundred tons burden","A burden of gad steel is 120 pounds.","to burden a nation with taxes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salute','n&v.敬礼；问候','/səˈl(j)uːt/','/səˈlut/','noun',["The soldiers greeted the dignitaries with a crisp salute.","They saluted the flag as it passed in the parade.","I would like to salute the many dedicated volunteers that make this project possible."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('random','adj.随意的，任意的','/ˈɹændəm/','/ˈɹændəm/','noun',["The party was boring. It was full of randoms.","The flip of a fair coin is purely random.","A toss of loaded dice is still random, though biased."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perhaps','adv.可能，或许','/pəˈhæps/','/pɚˈhæps/','noun',["Perhaps John will come over for dinner."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plot','vt.密谋n.情节','/plɒt/','/plɑt/','noun',["The assassination of Lincoln was part of a larger plot.","They had plotted a robbery.","They plotted the number of edits per day."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rate','v.估价；认为n.比率；价格；速度','/ɹeɪt/','/ɹeɪt/','noun',["At the height of his powers, he was producing pictures at the rate of four a year.","The car was speeding down here at a hell of a rate.","The rate of production at the factory is skyrocketing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skill','n.技能，技巧','/skɪl/','/skɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trouble','n.问题；疾病；麻烦vt.使苦恼；使忧虑；使麻烦','/ˈtɹʌb(ə)l/','/ˈtɹə-/','noun',["He was in trouble when the rain started.","The trouble was a leaking brake line.   The trouble with that suggestion is that we lack the funds to put it in motion.   The bridge column magnified the trouble with a slight tilt in the wrong direction.","the troubles in Northern Ireland"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unfair','adj.不公平的，不公正的','/ʌnˈfɛə(ɹ)/','/ʌnˈfɛɚ/','verb',["It was unfair for the boss to give larger bonuses to his friends."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divide','v.分，划分；除以','/dɪˈvaɪd/','','noun',["Stay on your side of the divide, please.","The divide left most of the good land on my share of the property.","There is a great divide between us."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contrary','adj.相反的n.反面','/ˈkɒntɹəɹi/','/ˈkɑntɹɛɹi/','noun',["contrary winds","What may be \"politically correct\" could be contrary to the teachings of Jesus.","a contrary disposition; a contrary child"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sit','vi.坐','/sɪt/','/sɪt/','noun',["After a long day of walking, it was good just to sit and relax.","I asked him to sit.","The temple has sat atop that hill for centuries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digital','adj.数字的，数码的','/ˈdɪd͡ʒɪtəɫ/','/ˈdɪd͡ʒɪtəɫ/','noun',["He moved to digital for the first time, using a Sony camera.","digital computer;  digital clock","Digital payment systems are replacing cash transactions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('over','adv.越过adj.完了，结束了prep.在…之上；超过','/ˈəʊ.və(ɹ)/','/ˈoʊ.vɚ/','noun',["He overed the fence in good style.","The cattle have been overing all day because of the flies.","The show is over."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brilliant','adj.闪耀的；有才气的','/ˈbɹɪljənt/','/ˈbɹɪljənt/','noun',["the brilliant lights along the promenade","butterflies with brilliant blue wings","The actor''s performance in the play was simply brilliant."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practical','adj.实际的；适用的；实用的；应用的','/ˈpɹæktɪkəl/','/ˈpɹæktɪkəl/','noun',["Jack didn''t get an engineering degree, but has practical knowledge of metalworking.","Jack''s knowledge has the practical benefit of giving us useful prototype parts.","All in all, Jack''s a very practical chap."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pesticide','n.杀虫剂','/ˈpɛstɨsaɪd/','/ˈpɛstɨsaɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bound','adj.被束缚的；有义务的v.跳跃','/ˈbaʊnd/','/ˈbaʊnd/','verb',["Just to make the cheese more binding","I wish I knew why the sewing machine binds up after I use it for a while.","These are the ties that bind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('false','adj.假的；不正确的','/fɒls/','/fɑls/','noun',["The student received a failing grade for circling every true and false on her quiz.","false legislation, false punishment","false teeth"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('go','v.去，走；进行；进展；变得，变成','/ɡəʉ/','/ɡoʊ/','noun',["It’s your go.","I’ll give it a go.","We will begin as soon as the boss says it''s a go."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tease','v.取笑，嘲弄','/tiːz/','/tiːz/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fork','n.叉；餐叉','/fɔːk/','/fɔɹk/','noun',["West Fork White River and East Fork White River join together to form the White River of Indiana.","LibreOffice is a fork of OpenOffice.","Are you qualified to drive a fork?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('form','v.形成，组建n.表格；形式；结构','/fɔːm/','/fɔɹm/','noun',["To apply for the position, complete the application form.","The orchestra was on top form this evening.","participial forms;  verb forms"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('publish','v.出版，发行','/ˈpʌblɪʃ/','/ˈpʌblɪʃ/','verb',["Most of the sketches Faulkner published in 1925 appeared in the Sunday magazine section of the New Orleans Times-Picayune.","No newspaper published the victim''s name.","Grove Press published many avant-garde authors."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pyramid','n.角锥形；金字塔','/ˈpɪɹəmɪd/','/ˈpɪɹəmɪd/','noun',["Build your pyramid with all cards face down, except the cards in the bottom row."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheque','n.支票','/tʃɛk/','/tʃɛk/','noun',["I was not carrying cash, so I wrote a cheque for the amount."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avoid','vt.避免，躲开，逃避','/əˈvɔɪd/','/əˈvɔɪd/','verb',["I try to avoid the company of gamblers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bid','v&n.出价，投标','/bɪd/','/bɪd/','verb',["He bade me come in.","She was bidden to the wedding.","Have you ever bid in an auction?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fresh','adj.新鲜的；不熟练的','/fɹɛʃ/','/fɹɛʃ/','noun',["He followed the fresh hoofprints to find the deer.","After taking a beating in the boxing ring, the left side of his face looked like fresh meat.","What a nice fresh breeze."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astonish','vt.使惊讶','/əˈstɒnɪʃ/','/əˈstɑnɪʃ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withdraw','v.缩回，撤回','/wɪðˈdɹɔː/','/wɪðˈdɹɔː/','verb',["to withdraw false charges"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('straightforward','adj&adv.正直的，坦率的','','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('very','adv.很，非常adj.恰好的，正好的','/ˈvɛɹi/','/ˈvɛɹi/','adjective',["He tried his very best.","He proposed marriage in the same restaurant, at the very table where they first met.","Not very many (of them) had been damaged."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decade','n.十年','/dəˈkeɪd/','/dəˈkeɪd/','noun',["a decade of soldiers","There are decades between 1.8 and 18, between 25 and 250 and between 0.03 and 0.003."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expert','n.专家，能手','/ˈɛkspəːt/','/ˈɛkspɚt/','noun',["We called in several experts on the subject, but they couldn''t reach an agreement.","I am expert at making a simple situation complex.","This problem requires expert knowledge."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practice','n.实践；练习；惯例，常规','/ˈpɹæktɪs/','/ˈpɹæktɪs/','noun',["He will need lots of practice with the lines before he performs them.","Being on a team is hard: you''re always having to go to practice while everyone else is taking it easy.","She ran a thriving medical practice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('select','adj.精选的vt.选择，挑选，选拔','/sɪˈlɛkt/','/sɪˈlɛkt/','verb',["He looked over the menu, and selected the roast beef.","Only a select few were allowed into the premiere.","This is a select cut of beef."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crowd','v.拥挤，群聚n.人群；堆','/kɹaʊd/','/kɹaʊd/','noun',["After the movie let out, a crowd of people pushed through the exit doors.","There was a crowd of toys pushed beneath the couch where the children were playing.","That obscure author''s fans were a nerdy crowd which hardly ever interacted before the Internet age."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sick','adj.有病的，患病的，不舒服的；呕吐的','/sɪk/','/sɪk/','noun',["We have to cure the sick.","He lay there in a pool of his own sick.","I woke up at 4 am and sicked on the floor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bit','n.一点，一些，少量','/bɪt/','/bɪt/','noun',["A horse hates having a bit put in its mouth.","a threepenny bit","A quarter is two bits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('welfare','n.福利；安宁，幸福','/ˈwɛlˌfɛə/','/ˈwɛlˌfɛə/','noun',["welfaring the poor"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('output','n.产量，输出量','/ˈaʊtpʊt/','/ˈaʊtpʊt/','noun',["The factory increased its output this year.","a six-page output; six pages of output","We output 1400 units last year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corner','n.角；角落；拐角','/ˈkɔːnə(ɹ)/','/ˈkɔɹnɚ/','noun',["The corners of the wire mesh were reinforced with little blobs of solder.","Shining a light in the dark corners of the mind.  I took a trip out to his corner of town.","On weekends, Emily liked to find a quiet corner and curl up with a good book."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('else','adv.别的，其他的','/ɛls/','/ɛls/','adjective',["The instructor is busy. Can anyone else help me?","How else (=in what other way) can it be done?","Then the Wronskian of f and g must be nonzero, else they could not be linearly independent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modem','n.调制解调器','/ˈməʊdəm/','/ˈməʊdəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('majority','n.多数','/məˈd͡ʒɒɹɪti/','/məˈd͡ʒɑɹɪti/','noun',["The majority agreed that the new proposal was the best.","The winner with 53% had a 6% majority over the loser with 47%.","By the time I reached my majority, I had already been around the world twice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beside','prep.在…旁边；靠近','/bɪˈsaɪd/','/biˈsaɪd/','adverb',["A small table beside the bed","That is beside the point"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('join','v.参加，加入；连接；会合','/ˈdʒɔɪn/','/ˈdʒɔɪn/','noun',["The plumber joined the two ends of the broken pipe.","Parallel lines never join.","I will join you watching the football game as soon as I have finished my work."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drag','v.拖，拽','/dɹæɡ/','','noun',["When designing cars, manufacturers have to take drag into consideration.","Travelling to work in the rush hour is a real drag.","to run a drag"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reduce','vt.减少，缩减','/ɹɪˈdjuːs/','/ɹɪˈduːs/','verb',["to reduce weight, speed, heat, expenses, price, personnel etc.","Hester Prynne was shocked at the condition to which she found the clergyman reduced.","to reduce a province or a fort"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('likely','adj.很可能的','/ˈlaɪkli/','/ˈlaɪkli/','noun',["Rain is likely later this afternoon.","He is likely to succeed at anything he tries.","Jones is a likely candidate for management."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('large','adj.大的；巨大的','/ˈlɑːd͡ʒ/','/ˈlɑɹd͡ʒ/','noun',["Getting a car tricked out like that will cost you 50 large.","One small coffee and two larges, please.","Russia is a large country.   The fruit-fly has large eyes for its body size.   He has a large collection of stamps."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bakery','n.面包店','/ˈbeɪ.kə.ɹi/','/ˈbeɪ.kə.ɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vain','adj.自负的；徒劳的','/veɪn/','/veɪn/','adjective',["vain toil;  a vain attempt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ordinary','adj.普通的，平常的','/ˈɔːdənɹi/','/ˈɔɹdɪnɛ(ə)ɹi/','noun',["On an ordinary day I wake up at nine o''clock, work for six hours, and then go to the gym.","He looked so ordinary, I never thought he''d be capable of murder."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fry','v.油炸，油煎','/fɹaɪ/','/fɹaɪ/','noun',["to be in a fry"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somebody','pron.某人；重要人物','/ˈsʌmbədɪ/','/ˈsʌmbɑdi/','noun',["I''m tired of being a nobody – I want to be a somebody.","Somebody has to clean this mess up."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drink','v.喝n.饮酒','/dɹɪŋk/','/dɹɪŋk/','verb',["He drank the water I gave him.","Jack drank the whole bottle by himself.","Everyone who is drinking is drinking, but not everyone who is drinking is drinking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('announce','v.宣布，宣告','/əˈnaʊns/','/əˈnaʊns/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('traditional','adj.传统的','/tɹəˈdɪʃnəl/','/tɹəˈdɪʃnəl/','noun',["I think her traditional values are antiquated.","traditional expositions of the Scriptures.","The traditional form of the character has twice as many strokes as the simplified form."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lively','adj.活泼的；充满生气的','/ˈlaɪvli/','/ˈlaɪvli/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('operate','v.动手术；操作，运转','/ˈɒpəɹeɪt/','/ˈɑpəɹeɪt/','verb',["to operate a machine"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('begin','v.开始，着手','/biˈɡɪn/','/biˈɡɪn/','noun',["I began playing the piano at the age of five.   Now that everyone is here, we should begin the presentation.","The program begins at 9 o''clock on the dot.    I rushed to get to class on time, but the lesson had already begun."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('become','vt.变得，成为','/bəˈkʊm/','/biˈkʌm/','verb',["It hath becomen so that many a man had to sterve.","She became a doctor when she was 25.","That dress really becomes you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bacterium','n.细菌','/bækˈtɪəɹ.ɪəm/','/bækˈtɪəɹ.ɪəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paragraph','n.段落','/ˈpæɹəɡɹɑːf/','/ˈpɛɹəɡɹæf/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oilfield','n.油田','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alive','adj.活着的，存在的','','/əˈlaɪv/','adjective',["As long as the plant is alive, he will continue to water it.","to keep the affections alive","Although quite dull during the day, the main street comes alive at night, with many bars and clubs opening."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eventually','adv.最终地','/ɪ.ˈvɛn.tjʊ.li/','/ɪ.ˈvɛn.t͡ʃu.li/','adverb',["Eventually, all prime numbers are odd."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neighbour','n.邻居','/ˈneɪbə/','/ˈneɪbɚ/','noun',["My neighbour has two noisy cats.","Though France neighbours Germany, its culture is significantly different.","That sort of talk is neighbouring on treason."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tournament','n.比赛，锦标赛','/ˈtɔːnəmənt/','/ˈtɔːnəmənt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cycle','vi.骑自行车，循环n.周期；循环vt.使循环','/ˈsaɪkəl/','/ˈsaɪkəl/','noun',["the cycle of the seasons, or of the year","electoral cycle","The interval cycle C4 consists of the pitch classes 0, 4 and 8; when starting on E, it is realised as the pitches E, G# and C."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thinking','n.思索；见解；想法','/ˈθɪŋkɪŋ/','/ˈθɪŋkɪŋ/','noun',["What is your thinking on this subject?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('literature','n.文学','/ˈlɪ.tə.ɹɪ.tʃə(ɹ)/','/ˈlɪ.tə.ɹɪ.tʃə(ɹ)/','noun',["However, even “literary” science fiction rarely qualifies as literature, because it treats characters as sets of traits rather than as fully realized human beings with unique life stories. —Adam Cadre, 2008"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronomer','n.天文学家','/ə.ˈstɹɑ.nə.mɚ/','/ə.ˈstɹɒ.nə.mɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prejudice','n.偏见，成见','/ˈpɹɛd͡ʒədɪs/','/ˈpɹɛd͡ʒədɪs/','noun',["I am free of all prejudices. I hate everyone equally."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digest','v.消化；领会n.摘要，概要；文摘','/daɪˈdʒɛst/','/daɪˈdʒɛst/','verb',["to digest laws","I just ate an omelette and I''m waiting for it to digest."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('angle','n.角度','/ˈæŋ.ɡəl/','/ˈæŋ.ɡəl/','noun',["the angle between lines A and B","The angle between lines A and B is π/4 radians, or 45 degrees.","an angle of a building"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tradition','n.传统，惯例','/tɹəˈdɪʃn̩/','/tɹəˈdɪʃn̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ability','n.能力；才能','/əˈ.bɪl.ɪ.ti/','/əˈ.bɪl.ɪ.ti/','noun',["This phone has the ability to have its software upgraded wirelessly.","She has an uncanny ability to defuse conflict."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everything','pron.每件事；一切，所有的东西','/ˈɛvɹiθɪŋ/','/ˈɛvɹiθɪŋ/','pronoun',["I checked the list again and everything is done.","A:What do you want to do at the amusement park?\nB:Everything!","She wasn''t feeling well this morning but now everything is fine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unbearable','adj.无法忍受的','','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urgent','adj.急迫的，紧急的','/ˈɜːdʒənt/','/ˈɚdʒənt/','adjective',["An urgent appeal was sent out for assistance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('programme','v.为…编制程序n.节目；项目','/ˈpɹəʊɡɹæm/','/ˈpɹoʊˌɡɹæm/','noun',["Our program for today’s exercise class includes swimming and jogging.","The program consisted of ads for restaurants and the credits of everyone connected with the play.","Tonight’s program was hosted by Johnny Carson."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belief','n.[C]信条，信念，信仰；[U]信任，相信','/bəˈliːf/','/bəˈliːf/','noun',["It''s my belief that the thief is somebody known to us.","Based on this data, it is our belief that X does not occur.","The ancient people have a belief in many deities."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delight','n.快乐，乐事vt.使高兴，使快乐','/dəˈlaɪt/','/dəˈlaɪt/','noun',["A beautiful landscape delights the eye."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immigration','n.移民','/ɪmɪˈɡɹeɪʃn/','/ɪmɪˈɡɹeɪʃn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('break','v.打破，弄坏；撕开n.间歇；休息','/bɹeɪk/','/bɹeɪk/','noun',["The femur has a clean break and so should heal easily.","He waited minutes for a break in the traffic to cross the highway.","Let’s take a five-minute break."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chain','storen.连锁店','/ˈt͡ʃeɪn/','/ˈt͡ʃeɪn/','noun',["He wore a gold chain around the neck.","This led to an unfortunate chain of events.","That chain of restaurants is expanding into our town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vest','n.背心，内衣','/vɛst/','/vɛst/','noun',["to vest a court with power to try cases of life and death","The power of life and death is vested in the king, or in the courts.","to vest money in goods, land, or houses"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('change','vt.改变；更换；兑换n.零钱；变化','/tʃeɪndʒ/','/tʃeɪndʒ/','noun',["The product is undergoing a change in order to improve it.","Can I get change for this $100 bill please?","A customer who pays with a 10-pound note for a £9 item receives one pound in change."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suggestion','n.[C]建议','/səˈd͡ʒɛstjən/','/səɡˈd͡ʒɛstʃən/','noun',["I have a small suggestion for fixing this: try lifting the left side up a bit.","Suggestion often works better than explicit demand.","He''s somehow picked up the suggestion that I like peanuts."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fluency','n.流利，流畅','/ˈfluːənsi/','/ˈfluːənsi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('draw','v.绘画；拉，吸引；提取','/dɹɔː/','/dɹɔː/','noun',["The game ended in a draw.","The draw is on Saturday.","She had to draw upon her experience to solve the problem."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('systematic','adj.系统的，有体系的','/ˌsɪs.təˈmæt.ɪk/','/ˌsɪs.təˈmæt.ɪk/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trolleybus','n.无轨电车','/tɹɒlɪbʌs/','/tɹɒlɪbʌs/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lantern','n.灯笼','/ˈlæn.tən/','/ˈlæn.tɚn/','noun',["the lantern of the cupola of the Capitol at Washington, or that of the Florence cathedral","to lantern a lighthouse"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cupboard','n.碗柜，橱柜','/ˈkʌbəd/','/ˈkʌbɚd/','noun',["Put the cups back into the cupboard."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('off','prep&adv.离开，走开','/ɔːf/','/ɔf/','noun',["He has been very obviously an untrustworthy narrator right from the off.","He got in the way so I had him offed.","Can you off the light?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comfort','v.安慰，缓和n.安慰，慰问','/ˈkʊm.fət/','/ˈkʌm.fəɹt/','noun',["Sleep in comfort with our new mattress.","the comforts of home","We still have the spare tire? That''s a comfort at least."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('joke','n.笑话','/dʒəʊk/','/dʒoʊk/','noun',["It was a joke!","The president was a joke.","I didn’t mean what I said — I was only joking."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knee','n.膝盖','/niː/','/ni/','noun',["Penny was wearing a miniskirt, so she skinned her exposed knees when she fell.","To make a knee.","the knee of a graph"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punishment','n.惩罚，处罚','/ˈpʌnɪʃmənt/','/ˈpʌnɪʃmənt/','noun',["a vehicle that can take a lot of punishment"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hide','v.掩饰；隐藏','/haɪd/','/haɪd/','verb',["He hides his magazines under the bed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('troublesome','adj.令人烦恼的；讨厌的','/ˈtɹʌbl̩səm/','/ˈtɹʌbl̩səm/','adjective',["The computer has been very troublesome for me. It never works when I need to use it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruction','n.说明，须知；教导','/ɪnˈstɹʌkʃən/','/ɪnˈstɹʌkʃən/','noun',["Instruction will be provided on how to handle difficult customers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('report','n&vt.报道，报告','/ɹəˈpoːt/','/ɹɪˈpɔɹt/','noun',["A report by the telecommunications ministry on the phone network revealed a severe capacity problem.","For insurance reasons, I had to report the theft to the local police station.","If you do that again I''ll report you to the boss."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oral','adj.口头的，口述的','/ˈɒɹəl/','/ˈɒɹəl/','noun',["We''ve got our Spanish oral tomorrow.","I gave my boyfriend oral for the first time on his birthday.","oral hygiene"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complete','adj.完成的，完整的vt.完成；结束','/kəmˈpliːt/','/kəmˈpliːt/','noun',["He completed the assignment on time.","The last chapter completes the book nicely.","After she found the rook, the chess set was complete."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compensate','v.补偿，赔偿','/ˈkɒm.pən.seɪt/','/ˈkɑm.pənˌseɪt/','verb',["It is hard work, but they will compensate you well for it.","His loud voice cannot compensate for a lack of personality.","I don''t like driving that old car because it always steers a little to the left so I''m forever compensating for that when I drive it. Trust me, it gets annoying real fast."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fun','n.乐趣，娱乐','/fʊn/','/fʌn/','noun',["Hey, don''t get bent out of shape over it; I was just funning you.","He is such a fun person to be with.","This year''s fashion style is much more fun than recent seasons."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constant','adj.经常的，不断的','/ˈkɒnstənt/','/ˈkɑnstənt/','noun',["constant time   constant space"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smog','n.烟雾','/smɒɡ/','/smɒɡ/','noun',["If the car is more than five years old, you''ll have to have it smogged before you can register it."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sob','n&v.抽泣，呜咽地说','/sɒb/','/sɑb/','noun',["\"He doesn''t love me!\" she sobbed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('political','adj.政治的','/pəˈlɪtɪkəl/','/pəˈlɪtɪkəl/','noun',["Political principles are rarely absolute, as political logic holds an imperfect result by compromise is better than a theoretically perfect abstention from the political process in the opposition.","Good political staff is hard to find, they may neither be ambitious and corrupted by power nor tempted by private sector careers.","“The Court invalidates Minnesota’s political apparel ban based on its inability to define the term ‘political''”"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('while','conj.正当…的时候；然而n.一小会儿','/waɪl/','/waɪl/','noun',["He lectured for quite a long while.","He was sleeping while I was singing.","This case, while interesting, is a bit frustrating."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anger','n.愤怒','/ˈæŋɡə(ɹ)/','/ˈæŋɡɚ/','noun',["You need to control your anger.","He who angers you conquers you.","You anger too easily."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('second','adj.二等的num.第二n.秒','/ˈsɛkɪnd/','/ˈsɛk.(ə)nd/','noun',["They were discounted because they contained blemishes, nicks or were otherwise factory seconds.","That was good barbecue. I hope I can get seconds.","I second the motion."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('that','determiner.那，那个〔指已经提到或已经知道的人、事物、想法等〕conjunction.〔用于动词、名词或形容词后引导一个从句，表示某人所说或所想，或陈述一个事实或理由〕adv.那么〔大、多等〕〔尤指通过手势比画来表示大小、数量等〕','/ˈðæt/','','noun',["\"The ribbon was that thin.\" \"I disagree, I say it was not that thin, it was thicker... or maybe thinner...\"","I did the run last year, and it wasn''t that difficult.","Ooh, I was that happy I nearly kissed her."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edge','n.边缘','/ɛdʒ/','/ɛdʒ/','noun',["I have the edge on him.","He is standing on the edge of a precipice.","in the edge of evening"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('download','n&vt.下载','/ˈdaʊnˌləʊd/','/ˈdaʊnˌloʊd/','noun',["The download took longer than I expected.","I got the download but it wouldn''t work on my computer.","You can download a trial version of the program for thirty days to determine whether you want to purchase the full version."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('split','vt.撕开，切开','/splɪt/','/splɪt/','noun',["He’s got a nasty split.","In the 3000 m race, his 800 m split was 1:45.32","He has split his lip."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('than','conj.比','/ðæn/','/ðæn/','adverb',["A player than whom none is more skillful.","she''s taller than I am;  she found his advice more witty than helpful;  we have less work today than we had yesterday;  We had no choice than to return home"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limit','vt.限制，限定；减少','/ˈlɪmt/','/ˈlɪmɪt/','noun',["There are several existing limits to executive power.","The sequence of reciprocals has zero as its limit.","Category theory defines a very general concept of limit."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('widespread','adj.分布广的','','','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antique','n.古董','/ænˈtiːk/','/ænˈtiːk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sow','v.播种','/saʊ/','/saʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('different','adj.不同的，有差异的','/ˈdɪf.(ə)ɹ.ənt/','/ˈdɪf.(ə)ɹ.ənt/','noun',["Several different scientists all reached this conclusion at about the same time."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fasten','v.扎牢，扣住','/ˈfɑːsn̩/','/ˈfæsn̩/','verb',["Can you fasten these boards together with some nails?","to fasten a blow"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('porter','n.搬运工','/ˈpɔːtə/','/ˈpɔːtə/','noun',["By the time I reached the train station I was exhausted, but fortunately there was a porter waiting."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('level','adj.平坦的n.水平线，水平','/ˈlɛv.əl/','/ˈlɛv.əl/','noun',["Hand me the level so I can tell if this is correctly installed.","By the end of the day, we''d dug down to the level of the old basement floor.","The sound level is much too high; this hurts my ears.   We''ve reached a new level of success."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dirt','n.污物，脏物；尘土','/dɜːt/','/dɝt/','noun',["The reporter uncovered the dirt on the businessman by going undercover."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('videophone','n.可视电话','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preserve','vt.保护，保存','/pɹəˈzɜːv/','/pɹəˈzɝv/','noun',["Every people have the right to preserve its identity and culture.","to preserve peaches or grapes","to preserve appearances; to preserve silence"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plus','prep.加，加上','/plʌs/','/plʌs/','noun',["He is a real plus to the team.","−2 * −2 = +4 (\"minus 2 times minus 2 equals plus four\")","He is a plus factor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relevant','adj.有关的','/ˈɹɛləvənt/','/ˈɹɛləvənt/','adjective',["His mother provided some relevant background information concerning his medical condition."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('license','n.执照，许可证','/ˈlaɪsəns/','/ˈlaɪsəns/','noun',["In order to enter the building, I need to show my license.","It was decided to license Wikipedia under the GFDL.","I am licensed to practice law in this state."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entry','n.进入；入口','/ˈɛntɹi/','/ˈɛntɹi/','noun',["Children are allowed entry only if accompanied by an adult.","What does the entry for 2 August 2005 say?","The entry in the second row and first column of this matrix is 6."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expand','vi.发展vt.扩张','/ɛkˈspænd/','/ɛkˈspænd/','verb',["You can expand this compact umbrella to cover a large table.","A flower expands its leaves.","Use the binomial theorem to expand {(x+1)}^4."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dream','n.梦v.梦想，希望','/dɹiːm/','/dɹim/','noun',["a dream of bliss","Stop dreaming and get back to work.","I dreamed a vivid dream last night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noble','adj.高贵的，贵族的','/ˈnəʊbəl/','/ˈnoʊbəl/','noun',["This country house was occupied by nobles in the 16th century.","He is a noble man who would never put his family in jeopardy.","a noble edifice"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plug','vt.把…塞住；接通电源n.塞子，插头','/plʌɡ/','/plʌɡ/','noun',["I pushed the plug back into the electrical socket and the lamp began to glow again.","Pull the plug out of the tub so it can drain.","He preferred a plug of tobacco to loose chaw."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bunch','n.串，束','/ˈbʌntʃ/','/ˈbʌntʃ/','noun',["a bunch of grapes;  a bunch of bananas;  a bunch of keys;  a bunch of yobs on a street corner","He still hangs out with the same bunch.","a bunch of trouble"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spy','v.侦探，刺探n.密探，间谍','/spaɪ/','/spaɪ/','noun',["During the Cold War, Russia and America would each spy on each other for recon.","I think I can spy that hot guy coming over here."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postpone','vt.推迟，延期','/poʊstˈpoʊn/','/poʊstˈpoʊn/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tense','adj.紧张的；拉紧的n.时态','/tɛns/','/tɛns/','noun',["English only has a present tense and a past tense; it has no future tense.","Dyirbal verbs are not inflected for tense.","tensing a verb"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bride','n.新娘','/bɹaɪd/','/bɹaɪd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heat','v.加热n.热','/hit/','/hit/','noun',["This furnace puts out 5000 BTUs of heat.   That engine is really throwing off some heat.   Removal of heat from the liquid caused it to turn into a solid.","Stay out of the heat of the sun!","The chili sauce gave the dish heat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behind','adv.在后面；向后prep.在…后面','/bəˈhaɪnd/','/bəˈhaɪnd/','noun',["to look behind","I''m two weeks behind in my schedule.","My watch is four minutes behind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hammer','v.敲，锤击n.锤子，锣锤','/ˈhæm.ə(ɹ)/','/ˈhæmɚ/','noun',["Bobby used a hammer and nails to fix the two planks together","The nail is too loose - give it a hammer.","The sound the piano makes comes from the hammers striking the strings"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seal','n.海豹','/siːl/','/siːl/','noun',["The seals in the harbor looked better than they smelled.","They''re organizing a protest against sealing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recipe','n.食谱','/ˈɹɛs.ə.pi/','/ˈɹɛs.ə.pi/','noun',["His new approach is definitely a recipe for success.","Stepper recipes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambassadress','n.大使夫人；女大使','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mental','adj.精神的，脑力的','/ˈmɛntəl/','/ˈmɛntəl/','adjective',["He is the most mental freshman I''ve seen yet.","That was a mental party last night."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bow','v&n.鞠躬，弯腰','/bəʊ/','/boʊ/','noun',["The musician bowed his violin expertly.","The shelf bowed under the weight of the books.","Cronenberg’s \"Cosmopolis\" bows in Cannes this week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('storage','n.贮藏，储存；存放','/ˈstɔ.ɹɪd͡ʒ/','/ˈstɔ.ɹɪd͡ʒ/','noun',["There''s a lot of storage space in the loft.","I′d recommend backing up these files to storage before reinstalling the operating system."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('racial','adj.种族的','/ˈɹeɪʃəl/','/ˈɹeɪʃəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('switch','v&n.更换，转换','/swɪtʃ/','/swɪtʃ/','noun',["Use the /b switch to specify black-and-white printing.","2004, \"Curt\", Can I use IF statements, and still use switches? (on newsgroup microsoft.public.word.mailmerge.fields)","I want to switch this red dress for a green one."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('total','adj.总数的；总括的；完全的n.合计vt.合计为','/ˈtəʊ.təl/','/ˈtəʊ.təl/','noun',["A total of £145 was raised by the bring-and-buy stall.","The total of 4, 5 and 6 is 15.","When we totalled the takings, we always got a different figure."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('of','prep.…的','/ɔv/','/ʌv/','preposition',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reserve','n&vt.保留，储备；预订','/ɹɪˈzɜːv/','/ɹɪˈzɝv/','noun',["We reserve the right to make modifications.","This cake is reserved for the guests!","I reserved a table for us at the best restaurant in town."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somehow','adv.以某种方式；不知怎么地','/ˈsʌmhaʊ/','/ˈsʌmhaʊ/','adverb',["This problem has to be tackled somehow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brick','n.砖；砖块','/bɹɪk/','/bɹɪk/','noun',["This wall is made of bricks.","This house is made of brick.","a plastic explosive brick"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dive','vi.跳水','/ˈdaɪv/','/ˈdaɪv/','noun',["the dive of a hawk after prey","to dive into home plate","She dove right in and started making improvements."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heap','v.堆起来n.堆','/heːp/','/hiːp/','noun',["a heap of earth or stones","You should move these structures from the stack to the heap to avoid a potential stack overflow.","My first car was an old heap."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sympathy','n.同情','/ˈsɪmpəθi/','/ˈsɪmpəθi/','noun',["Many people in Hollywood were blacklisted merely because they were suspected of Communist sympathies."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hear','v.听见，听说，得知','/hɪə(ɹ)/','/hɪɹ/','verb',["I was deaf, and now I can hear.","I heard a sound from outside the window.","Eventually the king chose to hear her entreaties."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fight','n&v.打仗，打架；争论','/faɪt/','[fʌɪt]','verb',["A wounded animal will fight like a maniac, relentless, savage and murderous.","The two boxers have been fighting for more than half an hour.","He fought for the Democrats in the last election."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roundabout','adj.绕道的；不直接的n.转盘路','/ˈɹaʊndəˌbaʊt/','/ˈɹaʊndəˌbaʊt/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rescue','vt&n.营救，援救','/ˈɹɛs.kjuː/','/ˈɹɛs.kjuː/','noun',["The rescue of Jerusalem was the original motive of the Crusaders","The dog was a rescue with some behavior issues.","The well-trained team rescued everyone after the avalanche."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('facial','adj.面部用的','/ˈfeɪʃəl/','/ˈfeɪʃəl/','noun',["He gave his wife a creamy facial.","The facial constitutionality of the law is in question."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('on','adv.继续prep.在…上；在…时候；在…地方；关于','/ɒn/','/ɔn/','verb',["Can you on the light?","All the lights are on, so they must be home.","Are we still on for tonight?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zebra','n.斑马','/ˈziːbɹə/','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brief','adj.简洁的','/bɹiːf/','/bɹiːf/','noun',["We got a news brief.","I wear boxers under trousers but for sports I usually wear a brief.","The U.S. president was briefed on the military coup and its implications on African stability."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unfortunate','adj.不幸的，倒霉的','/ʌnˈfɔːtjʊnət/','/ʌnˈfɔːtjʊnət/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recover','vi.痊愈vt.恢复；重新获得','/ɹɪˈkʌvə/','/ɹɪˈkʌvɚ/','noun',["After days of inquiries, he finally recovered his lost wallet.","They recovered three of the explorers very much alive, then another, wracked with severe hypothermia, who was taken to hospital.","At the top of the hill I asked to stop for a few minutes to recover my strength."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('or','conj.或者；还是，否则','/ɔː(ɹ)/','/ɔɹ/','conjunction',["He might get cancer, or be hit by a bus, or God knows what.","It''s raining! Come inside or you''ll catch a cold!","The country Myanmar, or Burma"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chance','n.机会；可能性','[tʃʰɑːns]','[tʃʰeəns]','noun',["We had the chance to meet the president last week.","Why leave it to chance when a few simple steps will secure the desired outcome?","There is a 30 percent chance of rain tomorrow."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('determine','v.决定；测定；确定','/dɪˈtɜːmɪn/','/dɪˈtɝmɪn/','verb',["The news of his father''s illness determined him to depart immediately.","The court has determined the cause.","I determined to go home at once."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nature','n.自然；性质；本性','/ˈneɪtʃə/','/ˈneɪtʃɚ/','noun',["Nature never lies (i.e. tells untruths)."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('social','adj.社会的；社交的；群居的','/ˈsəʊʃəl/','/ˈsoʊ.ʃəl/','noun',["They organized a social at the dance club to get people to know each other.","James is a very social guy; he knows lots of people.","Teresa feels uncomfortable in certain social situations."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wheel','n.轮，车轮；方向盘','/ʍiːl/','/wil/','noun',["the wheel of life","Wheel that trolley over here, would you?","The vulture wheeled above us."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interesting','adj.有趣的','/ˈɪnt(ə)ɹɛstɪŋ/','/ˈɪnt(ʃ)ɹɛstɪŋ/','verb',["Action films don''t really interest me."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cross','n.十字形的东西；十字架vt.越过；穿过','/kɹɑs/','/kɹɔs/','noun',["Put a cross for a wrong answer and a tick for a right one.","Criminals were commonly executed on a wooden cross.","She made the cross after swearing."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('control','vt&n.控制','/kənˈtɹəʊl/','/kənˈt(ʃ)ɹoʊl/','noun',["The government has complete control over the situation.","With a simple remote, he could control the toy truck."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drill','v.钻；重复训练n.钻头；训练','/dɹɪl/','/dɹɪl/','noun',["Wear safety glasses when operating an electric drill.","Use a drill with a wire brush to remove any rust or buildup.","Regular fire drills can ensure that everyone knows how to exit safely in an emergency."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('friction','n.摩擦；摩擦力','/ˈfɹɪkʃən̩/','/ˈfɹɪkʃən̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clerk','n.书记员；办事员；职员','/klɐːk/','/klɝk/','noun',["The law school graduate clerked for the supreme court judge for the summer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('walnut','n.胡桃，胡桃木','/ˈwɔːlnʌt/','/ˈwɑlnət/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acknowledge','vt.答谢；承认','/əkˈnɒ.lɪdʒ/','/ækˈnɑː.lɪdʒ/','verb',["to acknowledge the being of a god","to acknowledge a favor","This is to acknowledge your kind invitation to participate in the upcoming debate."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equip','vt.装备；训练','/ɪˈkwɪp/','/ɪˈkwɪp/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radiation','n.放射；放射物；放射疗法','/ɹaɪ.di.ˈaɪ.ʃən/','/ɹaɪ.di.ˈaɪ.ʃən/','noun',["heat radiation"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quarrel','n&vi.争吵，吵架','/ˈkwɒɹəl/','/ˈkwɑɹəl/','noun',["We got into a silly quarrel about what food to order.","A few customers in the shop had some quarrels with us, so we called for the manager.","to quarrel with one''s lot"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Christian','adj.基督教徒的n.基督教徒','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pulse','v.搏动，跳动n.脉搏；脉冲','/pʊls/','/pʌls/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maple','n.枫树','/ˈmeɪpl̩/','/ˈmeɪpl̩/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spiritual','adj.精神的；心灵的','/ˈspɪɹɪtjʊəl/','/ˈspɪɹɪtʃuəl/','noun',["He assigns supremacy to the pope in spirituals, and to the emperor in temporals. — Lowell.","Respect towards ancestors is an essential part of Thai spiritual practice.","a spiritual substance or being"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worthwhile','adj.值得做的','/wɜː(ɹ)θˈwaɪl/','/wɜː(ɹ)θˈwaɪl/','adjective',["Doing volunteer work to help others is truly worthwhile."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nation','n.民族，国家','/ˈneɪ.ʃən/','/ˈneɪ.ʃən/','noun',["The Kurdish people constitute a nation in the Middle East","Though legally single nations, many states comprise several distinct cultural or ethnic groups.","Once widespread across Europe in medieval times, nations are now largely restricted to the ancient universities of Sweden and Finland."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upper','adj.较高的，较上的','/ˈʌpə/','/ˈʌpɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('splendid','adj.灿烂的，辉煌的；〈口语〉极好的','/ˈsplɛndɪd/','/ˈsplɛndɪd/','adjective',["a splendid sun","a splendid pageant"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adaptation','n.[U]适应，适合；[C]改编本','/ˌædæpˈteɪʃən/','/ˌædæpˈteɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behalf','n.利益；代表','','','',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somewhere','adv.在某处，到某处','/ˈsʌm.hweːɹ/','/ˈsʌm.wɛɹ/','noun',["I must have left my glasses somewhere.","He plans to go somewhere warm for his vacation."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scene','n.一场，场景，布景；景色，风景','/siːn/','/siːn/','noun',["the scene of the crime","They stood in the centre of the scene.","behind the scenes"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('injure','vt.损害，伤害','/ˈɪndʒə/','/ˈɪndʒɚ/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freeze','v.结冰','/ˈfɹiːz/','/ˈfɹiːz/','verb',["The lake froze solid.","Don''t freeze meat twice.","It didn''t freeze this winter, but last winter was very harsh."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eastward','adv.向东','/ˈiːstwəd/','/ˈistwɚd/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geography','n.地理学','/dʒɪˈɒɡɹəfi/','/dʒiˈɑɡɹəfi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horrible','adj.令人恐惧的，恐怖的','/ˈhɑɹɪbəl/','/ˈhɑɹɪbəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strengthen','v.加强，增强','/ˈstɹɛŋ(k)θən/','/ˈstɹɛŋ(k)θən/','verb',["strengthen a muscle"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('injury','n.损伤；受伤处','/ˈɪn.dʒə.ɹi/','/ˈɪn.dʒə.ɹi/','noun',["The passenger sustained a severe injury in the car accident.","Slander is an injury to the character."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diploma','n.毕业文凭，学位证书','/dɪˈpləʊmə/','/dɪˈpləʊmə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brand','n.商标，牌子','/bɹand/','/bɹand/','noun',["To burn something to brands and ashes.","Some brands of breakfast cereal contain a lot of sugar.","I didn''t appreciate his particular brand of flattery."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspension','n.暂停，中止；悬挂，悬浮','/səˈspɛnʃən/','','noun',["suspension from a hook","suspension from school as a disciplinary measure"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choke','n&v.窒息','/t͡ʃəʊk/','/t͡ʃəʊk/','noun',["Ever since he choked on a bone, he has refused to eat fish.","The collar of this shirt is too tight; it’s choking me.","to choke a cave passage with boulders and mud"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alcohol','n.酒精，酒','/ˈæl.kə.hɒl/','/ˈæl.kə.hɑl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleasure','n.高兴，愉快','/ˈplɛʒə/','/ˈplɛʒɚ/','noun',["He remembered with pleasure his home and family.","Having a good night''s sleep is one of life''s little pleasures.","What is your pleasure: coffee or tea?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('old','adj.老的，旧的','/ˈɒʊld/','/ˈoʊld/','noun',["A civilised society should always look after the old in the community.","when he was an eight-year-old ; a 62-year-old should","I had to sneak out to meet my girlfriend and tell the olds I was going to the library."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recreation','n.消遣，娱乐','/ɹɛkɹiˈeɪʃən/','/ɹɛkɹiˈeɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allowance','n.津贴，补贴','/əˈlaʊəns/','/əˈlaʊəns/','noun',["her meagre allowance of food or drink","to make allowance for his naivety","Tare and tret are examples of allowance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interpreter','n.翻译员，口译人员','/ɪnˈtɜːpɹɪtə/','/ɪnˈtɜːpɹɪtə/','noun',["A Japanese man who is tried before a German court is assisted by an interpreter in making oral statements.","Programs written in the BASIC language are usually run through an interpreter, though some can be compiled."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurricane','n.飓风，狂风','/ˈhʌɹɪkən/','/ˈhɝɪˌkeɪn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('portable','adj.轻便的，便携的','/ˈpɔː(ɹ)təbl̩/','/ˈpɔː(ɹ)təbl̩/','noun',["a portable pension plan"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('then','adv.当时，那时；然后；那么','/ðen/','/ðɛn/','conjunction',["she''s taller than I am;  she found his advice more witty than helpful;  we have less work today than we had yesterday;  We had no choice than to return home","It will be finished before then.","He was happy then."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ancient','adj.古代的，古老的','/ˈeɪn.ʃənt/','/ˈeɪn.ʃənt/','noun',["an ancient city  an ancient forest","an ancient author  an ancient empire"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accept','v.接受','/ækˈsɛpt/','/əkˈsɛpt/','verb',["The Boy Scouts were going to accept him as a member.","I accept the notion that Christ lived.","I accept your proposal, amendment, or excuse."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glory','n.光荣，荣誉','/ˈɡlo(ː)ɹi/','/ˈɡlo(ː)ɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seat','n.座位，座vt.使就座；可容纳','/siːt/','/siːt/','noun',["Be sure to seat the gasket properly before attaching the cover.","The waiter seated us and asked what we would like to drink.","Please seat the audience after the anthem and then introduce the first speaker."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wander','v.游荡；漫步；流浪','/ˈwɒndə/','/ˈwɑndɚ/','noun',["to go for a wander in the park","baseline wander in ECG signals","to wander over the fields"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adopt','vt.采用；收养','/əˈdɒpt/','/əˈdɑpt/','verb',["He adopted a new look in order to fit in with his new workmates.","These resolutions were adopted."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oppose','v.反对','/əˈpəʊz/','/əˈpoʊz/','verb',["There is still time to oppose this plan.","Many religious leaders oppose cloning humans.","They are opposed to any form of hierarchy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minus','adj.负的prep.减去','/ˈmaɪnəs/','/ˈmaɪnəs/','noun',["a minus number","minus seven degrees","He got a grade of B minus for his essay."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belly','n.肚子','/bɛli/','/bɛli/','noun',["the belly of a flask, muscle, violin, sail, or ship"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conservative','adj.守旧的；保守主义的；谨慎的','/kənˈsɜːvətɪv/','/kənˈsɜːvətɪv/','noun',["The curriculum committee at this university is extremely conservative.","At a conservative estimate, growth may even be negative next year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('access','n.通道；机会，权利vt.进入；存取','/ˈæksɛs/','/ˈækˌsɛs/','noun',["an access of territory"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conference','n.会议','/ˈkɒn.fə.ɹəns/','/ˈkɒn.fə.ɹəns/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primitive','adj.原始的，远古的','/ˈpɹɪmɪtɪv/','/ˈpɹɪmɪtɪv/','noun',["primitive innocence;   the primitive church","a primitive style of dress","primitive ideas"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('activity','n.活动','/ækˈtɪ.və.ti/','/ækˈtɪ.və.ti/','noun',["Pit row was abuzz with activity.","The activity for the morning was a walk to the store.","An increasing number of sports activities are on offer at the university."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dormitory','n.学生宿舍','/ˈdɔɹmɪˌtɔɹi/','/ˈdɔɹmɪˌtɔɹi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overcome','v.战胜，克服，胜过','/ˌəʊvəˈkʌm/','/ˌoʊvəɹˈkʌm/','noun',["to overcome enemies in battle","We shall overcome.","I was overcome with anger."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recite','v.背诵','/ɹɪˈsaɪt/','/ɹɪˈsaɪt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seek','v.试图；寻找，寻求','/siːk/','/siːk/','noun',["I seek wisdom.","I seek forgiveness through prayer.","I sought my fortune on the goldfields."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seem','v.似乎，好像','/siːm/','/siːm/','verb',["He seems to be ill.   Her eyes seem blue.   It seems like it is going to rain later.   How did she seem to you?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heel','n.脚后跟','/hiːl/','/hiːl/','noun',["He drove the heel of his hand into the man''s nose.","the heel of a mast","She called to her dog to heel."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('variety','n.种种；种类','/vəˈɹaɪ.ɪ.ti/','/vəˈɹaɪ.ɪ.ti/','noun',["Variety is the spice of life."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disturb','v.打扰，扰乱','/dɪsˈtɜːb/','','noun',["A school of fish disturbed the water.","A mudslide disturbed the course of the river.","A disturbing film that tries to explore the mind of a serial killer."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adore','vt.爱慕，崇拜','/əˈdɔː/','/əˈdɔɹ/','verb',["It is obvious to everyone that Gerry adores Heather."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lecture','n.[C]讲课，演讲','/ˈlɛk.t͡ʃə/','/ˈlɛk.t͡ʃɚ/','noun',["During class today the professor delivered an interesting lecture.","Lecture notes are online.","I really don''t want you to give me a lecture about my bad eating habits."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civilian','n.平民，老百姓','/sɪˈvɪljən/','/sɪˈvɪljən/','noun',["Three civilians were apprehended by the soldiers and taken away in a military vehicle.","The bathroom was for employees only, so no civilians were allowed to use it.","He worked as a civilian journalist for ten years before being employed by the public broadcaster."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('so','adv.也，同样〔用于表示刚说过的情况也适用于某人或某物〕conjunction.因此，所以n.全音阶的第五音','/səʊ/','/soʊ/','adjective',["That is so.  You are responsible for this, is that not so?","Is he so?","It was so hot outside that all the plants died.  He was so good, they hired him on the spot."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pump','vt.用泵抽水；抽n.抽水机，泵','/pʌmp/','/pʌmp/','noun',["This pump can deliver 100 gallons of water per minute.","It takes thirty pumps to get 10 litres; he did 50 pumps of the weights.","This pump is out of order, but you can gas up at the next one."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('caution','n.小心，谨慎','/ˈkɔːʃ(ə)n/','/ˈkɑːʃ(ə)n/','noun',["The guideline expressed caution against excessive radiographic imaging.","Oh, that boy, he''s a caution! He does make me laugh."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('key','n.[C]钥匙；答案；键；关键','/kiː/','/ki/','noun',["The key to solving this problem is persistence.","The key says that A stands for the accounting department.","Some students cheated by using the answer key."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('teenager','n.青少年，十几岁的少年','/ˈtiːnˌeɪ.dʒə(ɹ)/','/ˈtiːnˌeɪ.dʒə(ɹ)/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dumpling','n.饺子','/ˈdʌmplɪŋ/','/ˈdʌmplɪŋ/','noun',["My little dumpling."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silent','adj.无声的，沉默的','/ˈsaɪlənt/','/ˈsaɪlənt/','noun',["The wind is silent.","Silent letters can make some words difficult to spell.","My phone was on silent."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decision','n.决定；决议','/dɪˈsɪʒən/','','noun',["It is the decision of the court that movies are protected as free speech.","After agonizing deliberations, they finally proceeded with decision.","He has won twice by knockout, once by decision."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('addicted','adj.入迷的，上瘾的','/əˈdɪktɪd/','/əˈdɪktɪd/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necessary','adj.必需的，必要的','/ˈnɛsəsɹɪ/','/ˈnɛsəˌsɛɹi/','noun',["Although I wished to think that all was false, it was yet necessary that I, who thus thought, must in some sense exist.","If it is absolutely necessary to use public computers, you should plan ahead and forward your e-mail to a temporary, disposable account."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('one','num&pron.一个；任何人','/wan/','/wʌn/','noun',["I knew as soon I met him that John was the one for me and we were married within a month.","2003 September 26, \"DEAL WITH IT!!!!11one!!\", in alt.games.video.nintendo.gamecube, Usenet","One day the prince set forth to kill the dragon that had brought terror to his father’s kingdom for centuries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garage','n.汽车间，汽车库','/ˈɡæɹɑː(d)ʒ/','/ɡəˈɹɑː(d)ʒ/','noun',["We garaged the convertible during the monsoon months."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('badminton','n.羽毛球','/ˈbæd.mɪn.tən/','/ˈbæd.mɪn.tən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confirm','vt.确定；批准','/kənˈfɜːm/','/kənˈfɝm/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('single','adj.单一的，单个的','/ˈsɪŋɡəl/','/ˈsɪŋɡəl/','noun',["The Offspring released four singles from their most recent album.","He went to the party, hoping to meet some friendly singles there.","I don''t have any singles, so you''ll have to make change."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pull','v.拉，拖n.拉力，引力','/pʊl/','[pʰʊːɫ]','noun',["He gave the hair a sharp pull and it came out.","She took a pull on her cigarette.","a zipper pull"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unconditional','adj.无条件的，绝对的','/ˌʌnkənˈdɪʃənəl/','/ˌʌnkənˈdɪʃənəl/','adjective',["We demand your unconditional surrender."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallon','n.加仑','/ˈɡælən/','/ˈɡælən/','noun',["The pipe burst and gallons of water flooded into the kitchen."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appoint','vt.指定，任命','/əˈpɔɪnt/','/əˈpɔɪnt/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assist','v.帮助，协助','/əˈsɪst/','/əˈsɪst/','noun',["The foundation gave a much needed assist to the shelter.","He had two assists in the game.","This book will assist you in getting your life in order."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bun','n.馒头；小甜面包','/bʌn/','/bʌn/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('but','conj.但是，可是prep.除了，除…外','/bʊt/','','noun',["It has to be done – no ifs or buts.","But me no buts.","Christmas comes  but once a year."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symbol','n.符号，象征','/ˈsɪmbəl/','/ˈsɪmbəl/','noun',["$ is the symbol for dollars in the US and some other countries.","The lion is the symbol of courage; the lamb is the symbol of meekness or patience.","The Apostles, Nicene Creed and the confessional books of Protestantism, such as the Augsburg Confession of Lutheranism are considered symbols."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sincerely','adv.真诚地','/sɪnˈsɪəli/','/sɪnˈsɪɹli/','adverb',["I sincerely hope they make it home safely."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commercial','adj.商业的，贸易的','/kəˈmɜːʃəl/','/kəˈmɝʃəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('separate','v.分开，分离adj.单独的，分开的','/ˈsɛpəɹət/','/ˈsɛpəɹət/','noun',["Separate the articles from the headings.","If the kids get too noisy, separate them for a few minutes.","The sauce will separate if you don''t keep stirring."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('declare','v.宣布，声明；申报','/dɪˈkleə/','/dəˈklɛɚ/','verb',["He declared him innocent.","declare bankruptcy","Houghton and Sunderland South was the first constituency to declare in the 2015 general election."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reasonable','adj.合理的，有道理的；通情达理的，合乎情理的','/ˈɹiː.zən.ə.bəl/','/ˈɹiː.zən.ə.bəl/','adjective',["a reasonable demand, amount, or price","$20 a bottle is very reasonable for a good wine at a restaurant.","The builders did a reasonable job, given the short notice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dislike','n&vt.不喜欢，嫌恶','/dɪsˈlaɪk/','/dɪsˈlaɪk/','noun',["Tell me your likes and dislikes.","Rebecca Black''s \"Friday\" video has gained notoriety for being one of the most disliked videos in YouTube history."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('willing','adj.情愿的，乐意的','/ˈwɪlɪŋ/','/ˈwɪlɪŋ/','verb',["All the fans were willing their team to win the game.","He willed his stamp collection to the local museum.","If my boyfriend isn''t willing to change his drinking habits, I will split up with him."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('available','adj.有空的；可得到的，可用的','/əˈveɪləb(ə)l/','/əˈveɪləb(ə)l/','adjective',["We have an available candidate.","The list shows the available products in the store.","This is an available plea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('express','vt.表达；表示n.快车','/ɛk.ˈspɹɛs/','/ɛk.ˈspɹɛs/','noun',["I took the express into town.","I gave him express instructions not to begin until I arrived, but he ignored me.","In my eyes it bore a livelier image of the spirit, it seemed more express and single, than the imperfect and divided countenance."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advocate','vt.提倡；鼓吹','/ˈæd.və.keɪt/','/ˈæd.və.keɪt/','noun',["Since she started working with her advocate, she has become much more confident.","I like trees, but I do not advocate living in them.","We have been advocating for changes in immigration law."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amazing','adj.令人惊异的','/əˈmeɪzɪŋ/','/əˈmeɪzɪŋ/','verb',["He was amazed when he found that the girl was a robot.","2015, June 10, Lindsey Bever, \"Morning Mix: Another reason seeing-eye dogs are amazing\"http//www.washingtonpost.com/news/morning-mix/wp/2015/06/10/another-heroic-story-showing-why-seeing-eye-dogs-are-amazing/"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luggage','n.〈总称〉行李','/ˈlʌɡɪd͡ʒ/','/ˈlʌɡɪd͡ʒ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawback','n.缺点；障碍','/ˈdɹɔːˌbæk/','/ˈdɹɔːˌbæk/','noun',["Poor fuel economy is a common drawback among larger vehicles."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dynamic','adj.有活力的；动力的，动力学的','/daɪˈnæ.mɪk/','/daɪˈnæ.mɪk/','noun',["Watch the dynamic between the husband and wife when they disagree.","The study of fluid dynamics quantifies turbulent and laminar flows.","If you pay attention to the dynamics as you play, it''s a very moving piece."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('up','adv.从下往上地，向上地v.提高；增加','/ap/','/ʌp/','noun',["Up is a good way to go.","I hate almost everything about my job. The only up is that it''s so close to home.","She lives in a two-up two-down."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unusual','adj.不平常的，异常的','/ʌnˈjuːʒuəl/','/ʌnˈjuːʒuəl/','noun',["Every once in a while, though, Idol comes across an unusual talent who just blows everyone away."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extreme','adj.极端的，偏激的','/ɛkˈstɹiːm/','/ɪkˈstɹim/','noun',["extremes of temperature","Some people go to extremes for attention on social media.","At the extreme edges, the coating is very thin."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('usual','adj.通常的，平常的','/ˈjuːʒʊəl/','/ˈjuːʒʊəl/','noun',["I''ll just have the usual.","It is becoming more usual these days to rear children as bilingual."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sink','v.下沉；消沉；陷入n.洗涤槽，污水槽','/sɪŋk/','/sɪŋk/','noun',["Jones has a two-seamer with heavy sink.","I have sunk thousands of pounds into this project.","to sink the national debt"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('degree','n.程度；度数；文凭','/dɪˈɡɹiː/','/dɪˈɡɹiː/','noun',["She has two bachelor''s degrees and is studying towards a master''s degree.","A right angle is a ninety-degree angle.","180 degrees Fahrenheit is equivalent to 100 degrees Celsius."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronomy','n.天文学','/æˈstɹɑnəˌmi/','/æˈstɹɑnəˌmi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suppose','vi.料想vt.猜想，假定','/səˈpəʊz/','/səˈpoʊz/','verb',["Suppose that A implies B and B implies C. Then A implies C.","I suppose we all agree that this is the best solution.","Purpose supposes foresight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brake','v.刹车n.闸','/bɹeɪk/','/bɹeɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tube','n.管子','/tjuːb/','/tjuːb/','noun',["A tube of toothpaste.","I took the tube to Waterloo and walked the rest of the way.","Are you just going to sit around all day and watch the tube?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outspoken','adj.坦率的','','','verb',["an outspoken man"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('especially','adv.特别，尤其','/əˈspɛʃ(ə)li/','/əˈspɛʃ(ə)li/','adverb',["Invite them all, especially Molly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('once','adv.一次，一回conjunction.一…便，一旦，一经','/wɒn(t)s/','/wʌn(t)s/','adverb',["I have only once eaten pizza.","He was once the most handsome man around.","Once three is three."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('failure','n.失败','/ˈfeɪl.jɚ/','/ˈfeɪl.jɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quake','n&vi.震动','/kweɪk/','/kweɪk/','noun',["We felt a quake in the apartment every time the train went by.","California is plagued by quakes; there are a few minor ones almost every month.","I felt the ground quaking beneath my feet."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('know','v.知道，了解；认识；懂得','/nəʊ/','/noʊ/','noun',["He knew something terrible was going to happen.","Did you know Michelle and Jack were getting divorced? ― Yes, I knew.","I know your mother, but I’ve never met your father."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sing','v.唱，唱歌','/sɪŋ/','/sɪŋ/','noun',["\"I really want to sing in the school choir,\" said Vera.","to sing somebody to sleep","The air sings in passing through a crevice."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organise','v.组织','','','verb',["an organized being","to organize an anthem","the workers decided to organize; their next task was to organize the workers at the steel mill"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('support','vt&n.支持，赞助；赡养','/səˈpɔːt/','/səˈpɔɹt/','noun',["Don''t move that beam! It''s a support for the whole platform.","The government provides support to the arts in several ways.","Sure they sell the product, but do they provide support?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drop','v.掉下，落下n.滴；下降','/dɹɒp/','/dɹɑp/','noun',["Put three drops of oil into the mixture.","asked for just a drop more tea; she was thirsty and there wasn''t a drop of water to be found","It doesn''t matter where you''re from; anyone who enjoys the drop is a friend of mine."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preview','vt.预演，预习','/ˈpɹiːvjʉː/','/ˈpɹiːvjʉː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('questionnaire','n.调查表，问卷','/ˌk(w)estjəˈnɛə/','/ˌk(w)estjəˈnɛə/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saucer','n.茶碟；小圆盘','/ˈsɔː.sə/','/ˈsɔː.sə/','noun',["The saucer-shaped object could have been a UFO."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hire','vt.租用','/haɪə/','/haɪɹ/','noun',["The sign offered pedalos on hire.","When my grandfather retired, he had over twenty mechanics in his hire.","We pair up each of our new hires with one of our original hires."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breakthrough','n.突破','/ˈbɹeɪkθɹuː/','/ˈbɹeɪkθɹuː/','noun',["Albert Einstein is credited with making some of the greatest breakthroughs in modern physics.","a breakthrough technological advance"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idea','n.主意，意见；打算，想法','/ɑeˈdiə̯/','/aɪˈdi.ə/','noun',["The mere idea of you is enough to excite me.","I have an idea of how we might escape.","Yeah, that''s the idea."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destination','n.目的地','/dɛstɪˈneɪʃən/','/dɛstɪˈneɪʃən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apron','n.围裙；台口','/ˈeɪ.pɹən/','/ˈeɪ.pɹən/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vertical','adj.垂直的，直立的；纵向的','/ˈvɜːtɪkəl/','/ˈvɝtɪkəl/','noun',["We offer specialised accounting software targeting various verticals."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monument','n.纪念碑，纪念物','/ˈmɒnjʊmənt/','/ˈmɑnjəmənt/','noun',["There is a monument on the town green to the soldiers who died in World War I."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pure','adj.纯的，不掺杂的','/ˈpjɔː/','/ˈpjɔɹ/','noun',["Tiger Woods pured his first drive straight down the middle of the fairway.","That idea is pure madness!","You’re pure busy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('successful','adj.成功的，有成就的','/səkˈsɛsfl̩/','/səkˈsɛsfl̩/','adjective',["a successful use of medicine;  a successful experiment;  a successful enterprise"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lovely','adj.美好的，可爱的','/ˈlʌvli/','/ˈlʌvli/','noun',["a calendar depicting young lovelies in bikinis","Goodbye, my lovely.","It''s a lovely day and the sun is shining."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('normal','adj.正常的n.正常，常态，普通','/ˈnɔːməl/','/ˈnɔɹməl/','noun',["Heavy workload is the new normal.","Organize the data into third normal form.","John is feeling normal again."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gradual','adj.逐渐的，渐进的','/ˈɡɹɛdʒɘl/','/ˈɡɹædʒuəl/','noun',["a gradual increase of knowledge; a gradual decline"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('figure','v.认为；描绘n.数字；人物','/ˈfɪɡjɚ/','/ˈfɪɡjɚ/','noun',["a figure in bronze; a figure cut in marble","He cut a sorry figure standing there in the rain.","The muslin was of a pretty figure."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socialist','adj.社会主义的n.社会主义者','/ˈsəʊʃəlɪst/','/ˈsoʊ.ʃə.lɪst/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airmail','n.〈总称〉航空邮件','/ˈɛə.meɪl/','/ˈɛə.meɪl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slight','adj.轻微的，细小的','[sl̥l͡ɐɪʔ̚]','[sl̥l͡ɐɪʔ̚]','noun',["a slight but graceful woman","A slight stone","The sea was slight and calm"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrupt','adj.腐败的，贪污的v.腐烂，腐蚀','/kəˈɹʌpt/','/kəˈɹʌpt/','verb',["to corrupt a book","The government here is corrupt, so we''ll emigrate to escape them.","It turned out that the program was corrupt - that''s why it wouldn''t open."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wide','adj.宽的，宽阔的；广泛的','/waɪd/','/waɪd/','noun',["We walked down a wide corridor.","The inquiry had a wide remit.","That team needs a decent wide player."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('previous','adj.在前的，早先的','/ˈpɹiːvɪəs/','/ˈpɹivi.əs/','noun',["It turned out the shoplifter had a lot of previous.","He is no better than the previous Prime Minister."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('teach','v.教书；教','/tiːt͡ʃ/','/tiːt͡ʃ/','verb',["‘The bliss is there’, mumbled the old man and taught to Heaven.","Can you teach me to sew?  Can you teach sewing to me?","She used to teach at university."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socialism','n.社会主义','/ˈsəʊʃəlɪzəm/','/ˈsəʊʃəlɪzəm/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('argue','v.争论；说服','/ˈɑː.ɡjuː/','/ˈɑɹ.ɡju/','verb',["He also argued for stronger methods to be used against China.","He argued his point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technology','n.技术，科技','/tɛkˈnɒlədʒi/','/tɛkˈnɒlədʒi/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superior','adj.较高的，上好的n.长者；上级','/suːˈpɪəɹi.ə(ɹ)/','/suːˈpɪɹiɚ/','noun',["Rebecca had always thought shorts were far superior to pants, as they didn''t constantly make her legs itch.","A genus is superior to a species.","the superior jaw; the superior part of an image"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('succeed','vi.成功vt.继承，接替','/səkˈsiːd/','/səkˈsiːd/','verb',["Autumn succeeds summer.","The persecution of any righteous practice has never succeeded in the face of history; in fact, it can expedite the collapse of the persecutory regime.","So, if the issue of the elder son succeed before the younger, I am king."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choir','n.唱诗班','/kwaɪə(ɹ)/','/kwaɪɚ/','noun',["The church choir practices Thursday nights.","Seraphim, Cherubim, and Thrones are three of the choirs of angels."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punctual','adj.准时的','/ˈpʌŋktjʊəl/','/ˈpʌŋktʃuəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advertise','vt.为…做广告','/ˈadvə(ɹ)taɪz/','/ˈadvə(ɹ)taɪz/','verb',["For personal needs, advertise on the internet or in a local newspaper.","Over the air, they advertise their product on drive-time radio talk shows and TV news shows."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compromise','v.妥协，折中','/ˈkɒmpɹəˌmaɪz/','/ˈkɑmpɹəˌmaɪz/','noun',["a compromise of character or right","He tried to compromise the security in the computer by guessing the password."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('software','n.软件','/ˈsɑftˌwɛɹ/','/ˈsɔftˌwɛɹ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seminar','n.研究会，讨论发表会','','','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reach','v.到达；够到','/ɹiːt͡ʃ/','/ɹiːt͡ʃ/','noun',["The fruit is beyond my reach.","To call George eloquent is certainly a reach.","He reached for a weapon that was on the table."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('react','vi.起反应，起作用；反抗','/ɹiːˈækt/','/ɹiːˈækt/','noun',["Sad reacts only","Every body reacts on the body that impels it from its natural state."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competition','n.比赛，竞赛','/ˌkɒmpəˈtɪʃən/','/ˌkɑːmpəˈtɪʃən/','noun',["The competition for this job is strong.","The newspaper is featuring a competition to win a car.","The new stain remover was ten times more effective than the competition."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('none','pron.无任何东西或人','/nɒn/','/nɒn/','noun',["I felt none the worse for my recent illness.","He was none too pleased with the delays in the program that was supposed to be his legacy.","None of this meat tastes right."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('type','vt.打字，用打字机打出','/taɪp/','/taɪp/','noun',["This type of plane can handle rough weather more easily than that type of plane.","He was exactly her type.","The fundamental types used to express the simplest and most essential chemical relations are hydrochloric acid, water, ammonia, and methane."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beyond','prep.超过；在…的那边','/biˈjɒnd/','/biˈjɑnd/','noun',["2017 July 13, Joseph Gamp \"Marvel release stirring new set images of Black Panther and we are BEYOND excited\" Metro (UK)","She had no reason for the conviction beyond the very inadequate one that she had seen him around London.","No swimming beyond this point."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practise','v.练习；实习；经常做；养成…的习惯','/ˈpɹæktɪs/','/ˈpɹæktɪs/','verb',["You should practise playing piano every day.","If you want to speak French well, you need to practise.","They gather to practise religion every Saturday."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('review','vt.复习；重新调查n.复习；复查；评论','/ɹɪˈvjuː/','/ɹɪˈvjuː/','noun',["I need to make a review of the book before I can understand it.","The newspaper review was full of praise for the play.","The victims demanded a full judicial review of the case."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sight','n.情景，风景；视力','/saɪt/','/saɪt/','noun',["He is losing his sight and now can barely read.","to gain sight of land","We went to London and saw all the sights – Buckingham Palace, Tower Bridge, and so on."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lift','vi.升起，消散','/lɪft/','/lɪft/','noun',["He gave me a lift to the bus station.","Take the lift to the fourth floor.","What''s the maximum lift of this crane?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motto','n.箴言，格言','/ˈmɒtəʊ/','/ˈmɒtəʊ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nationwide','adj.全国性的','/ˌneɪ.ʃənˈwaɪd/','/ˌneɪ.ʃənˈwaɪd/','adjective',["There was a nationwide search on for the bankrobbers."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('force','vt.强迫，迫使n.力量，武力','/fɔːs/','/fɔɹs/','noun',["the force of an appeal, an argument, or a contract","police force","show of force"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centigrade','adj.摄氏的；百分度的','','','noun',["a temperature of 34 centigrades"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('botany','n.植物学；植物','/-ɪ/','/-ɪ/','noun',["the botany of Greenland"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wear','v.穿，戴；留，蓄；磨损，使变旧','/wɛə/','/wɛə(ɹ)/','noun',["footwear; outdoor wear; maternity wear","He''s wearing some nice pants today.  She wore her medals with pride.  Please wear your seatbelt.  Can you wear makeup and sunscreen at the same time?  He was wearing his lunch after tripping and falling into the buffet.","He wears eyeglasses.  She wears her hair in braids."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('range','n.范围；射程','/ɹeɪndʒ/','/ɹeɪndʒ/','noun',["We sell a wide range of cars.","One can use the speed of sound to estimate the range of a lightning flash.","This missile''s range is 500 kilometres."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weak','adj.虚弱的；差的','/wiːk/','/wiːk/','adjective',["The child was too weak to move the boulder.","a weak timber; a weak rope","weak resolutions; weak virtue"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leak','v.漏，泄漏','/liːk/','/liːk/','noun',["a leak in a boat","The babies'' diapers had big leaks.","The leaks by Chelsea Manning showed the secrets of the US military."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impress','vt.留下印象','/ˈɪmpɹɛs/','/ˈɪmpɹɛs/','noun',["You impressed me with your command of Urdu.","Henderson impressed in his first game as captain.","That first view of the Eiger impressed itself on my mind."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flat','adj.平的n.一套房间；公寓','/flæt/','/flæt/','noun',["She liked to walk in her flats more than in her high heels.","a flat of strawberries","The land around here is flat."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('get','v.变得；到达vt.得到，获得','/ɡɛt/','/ɡɛt/','noun',["I''m going to get a computer tomorrow from the discount store.","He got a severe reprimand for that.","I''ve got a concert ticket for you."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('course','n.过程，经过；课程','/kɔːs/','/kɔɹs/','noun',["The normal course of events seems to be just one damned thing after another.","His illness ran its course.","Main course and mainsail are the same thing in a sailing ship."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barber','n.理发师','/ˈbɑː.bə/','/ˈbɑɹ.bɚ/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('copy','v.复制；抄写；复印n.抄本，副本；一本','/ˈkɒpi/','/ˈkɑpi/','noun',["Please bring me the copies of those reports.","That handbag is a copy. You can tell because the buckle is different.","Submit all copy to the appropriate editor."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precise','adj.精确的，准确的','/pɹɪˈsaɪs/','/pɹɪˈsaɪs/','verb',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('power','n.力量；动力','/ˈpaʊ.ə(ɹ)/','/ˈpaʊ.ɚ/','noun',["the mechanical powers","This CD player is powered by batteries."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('place','n.地方，处所vt.放置，安置','/pleɪs/','/pleɪs/','noun',["I''m in a strange place at the moment.","three decimal places;  the hundreds place","That''s what I said in the first place!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dare','v.敢，敢于','/dɛə(ɹ)/','/dɛ(ə)ɹ/','noun',["I wouldn''t dare argue with my boss.","I dare you (to) kiss that girl.","Will you dare death to reach your goal?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regular','adj.规则的；经常的','/ˈɹɛɡjʊlə/','/ˈɹɛɡjəlɚ/','noun',["Bartenders usually know their regulars by name.","This gentleman was one of the architect''s regulars.","regular clergy, in distinction from the secular clergy"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precious','adj.宝贵的，珍贵的','/ˈpɹɛʃəs/','/ˈpɹɛʃəs/','noun',["The crown had many precious gemstones.   This building work needs site access, and tell the city council that I don''t care about a few lorry tyre ruts across their precious grass verge.","My precious daughter is to marry.","He spent hours painting the eyes of the portrait, which his fellow artists regarded as a bit precious."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sell','v.卖，售','/sɛl/','/sɛl/','noun',["This is going to be a tough sell.","I''ll sell you all three for a hundred dollars.","The corn sold for a good price."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tired','adj.疲劳的，累的；厌烦的','/taɪəd/','/taɪɚd/','verb',["I tire of this book.","I''m tired of this","a tired song"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tremble','v.颤抖，挥动','/ˈtɹɛmbl̩/','/ˈtɹɛmbl̩/','noun',["Her lip started to tremble as she burst into tears"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gymnastics','n.体操，体育','/dʒɪmˈnæs.tɪks/','/dʒɪmˈnæs.tɪks/','noun',["Gymnastics was a significant part of the physical education curriculum.","His mental gymnastics are legendary."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspect','v.怀疑n.犯罪嫌疑人','/ˈsʌs.pɛkt/','/ˈsʌs.pɛkt/','noun',["to suspect the presence of disease","to suspect the truth of a story","I suspect him of being the thief."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suggest','vt.建议；提出；暗示','/səˈdʒɛst/','/sə(ɡ)ˈdʒɛst/','verb',["Are you suggesting that I killed my wife?","The name \"hamburger\" suggests that hamburgers originated from Hamburg.","I’d like to suggest that we go out to lunch.   I’d like to suggest going out to lunch."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apologize','vi.道歉，谢罪','/əˈpɒləd͡ʒaɪz/','/əˈpɑləd͡ʒaɪz/','verb',["My correspondent apologized for not answering my letter."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expect','v.预料；期望；要求','/ɛkˈspɛkt/','/ɛkˈspɛkt/','verb',["He never expected to be discovered.","You are expected to get the task done by the end of next week."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('help','n&v.帮助，帮忙；有帮助，有用','/hɛlp/','/hɛlp/','noun',["I need some help with my homework.","He was a great help to me when I was moving house.","I can''t find anything in the help about rotating an image."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depth','n.深，深度','/dɛpθ/','/dɛpθ/','noun',["Measure the depth of the water in this part of the bay.","The depth of her misery was apparent to everyone.","the depth of a sound"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assess','vt.估定，评定','/əˈsɛs/','/əˈsɛs/','verb',["He assessed the situation.","A $10.00 late fee will be assessed on all overdue accounts.","Once you''ve submitted a tax return, the Tax Department will assess the amount of tax you still owe."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prescription','n.处方，药方','/pɝˈskɹɪpʃən/','/pɝˈskɹɪpʃən/','noun',["\"Jurisdiction to prescribe\" is a state''s authority to make its laws applicable to certain persons or activities. -- Richard G. Alexander, Iran and Libya Sanctions Act of 1996: Congress exceeds its jurisdiction to prescribe law. Washington and Lee Law Review, 1997.","The surgeon wrote a prescription for a pain killer and physical therapy.","The pharmacist gave her a bottle containing her prescription."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behaviour','n.[U]行为，举止','/bɪˈheɪvjə/','/bɪˈheɪvjə/','noun',["She can''t stop the strange behaviour because she has OCD (obsessive-compulsive disorder)."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chorus','n.合唱','/ˈkɔːɹəs/','/ˈkɔːɹəs/','noun',["The performance of the chorus was awe-inspiring and exhilarating.","The catchiest part of most songs is the chorus.","a chorus of crickets"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minimum','adj.最小的n.最小量，最小值','/ˈmɪn.ɪ.məm/','/ˈmɪn.ə.məm/','noun',["We need a minimum of three staff members on duty at all time.","He always tries to get away with doing the minimum.","The Maunder minimum of the Sun reportedly corresponded to a period of great cold on Earth."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('queue','vi.排队n.行列，长队','/kjuː/','/kjuː/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apology','n.道歉；歉意','/əˈpɒl.ə.dʒi/','/əˈpɒl.ə.dʒi/','noun',["The CEO made a public apology for the scandal, and promised full cooperation with the authorities.","The Apology of Socrates.","a poor apology for a hotel room"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('date','n.日期；约会vt.约会；注明日期','/deɪt/','/deɪt/','noun',["We made a nice cake from dates.","There were a few dates planted around the house."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magic','adj.有魔力的n.魔法，魔术','/ˈmadʒɪk/','/ˈmædʒɪk/','noun',["a magic moment","a magic show; a magic trick","— I cleaned up the flat while you were out. — Really? Magic!"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dress','v.穿衣，打扮n.女服，连衣裙；服装','/dɹɛs/','/dɹɛs/','noun',["Amy and Mary looked very pretty in their dresses.","He came to the party in formal dress.","He was dressed in the latest fashions."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('argument','n.[C]争论，辩论','/ˈɑːɡjʊmənt/','/ˈɑɹɡjumənt/','noun',["Parameters are like labeled fillable blanks used to define a function whereas arguments are passed to a function when calling it, filling in those blanks.","The altitude is the argument of the refraction."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passage','n.一节；走廊；通道','/ˈpæsɪd͡ʒ/','/ˈpæsɪd͡ʒ/','noun',["She struggled to play the difficult passages.","He made his passage through the trees carefully, mindful of the stickers.","The company was one of the prime movers in lobbying for the passage of the act."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theoretical','adj.理论的','/ˌθi.əˈɹɛtɪkəl/','/ˌθi.əˈɹɛtɪkəl/','adjective',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adequate','adj.足够的，适当的','','','verb',["an adequate definition"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sound','n.声，声音v.听起来；看起来；好像adj.明智的；合理的；正确的','/saʊnd/','/saʊnd/','adjective',["He was safe and sound.","Fred assured me the floorboards were sound.","\"How are you?\" - \"I''m sound.\""]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('own','adj.自己的vt.拥有','/ˈəʊn/','/ˈoʊn/','adjective',["When we move into the new house, the kids will each have their own bedroom."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hopeful','adj.有希望的；有前途的','/ˈhəʊpfəl/','/ˈhəʊpfəl/','noun',["Several presidential hopefuls are campaigning in New Hampshire this week.","I am hopeful that I will recover from the disease."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dozen','n.十二个；许多','/ˈdʌzən/','/ˈdʌzən/','noun',["Can I have a dozen eggs, please?","There must have been dozens of examples just on the first page."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('translate','v.翻译','/ˈtɹɛnzlæet/','/tɹæn(t)s-/','noun',["William was translated by the blow to the head he received, being unable to speak for the next few minutes."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drug','n.药，药物；毒品','/dɹʌɡ/','/dɹʌɡ/','noun',["Aspirin is a drug that reduces pain, acts against inflammation and lowers body temperature.","2010, Kesha Rose Sebert (Ke$ha), with Pebe Sebert and Joshua Coleman (Ammo), Your Love is My Drug","She suddenly felt strange, and only then realized she''d been drugged."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blow','v.吹；刮风n.击，打击','/bləʊ/','/bloʊ/','noun',["We''re having a bit of a blow this afternoon.","The players were able to get a blow during the last timeout.","Blow the dust off that book and open it up."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curious','adj.好奇的；奇异的','/ˈkjɔː-/','/ˈkjɝ.i.əs/','adjective',["Young children are naturally curious about the world and everything in it.","The platypus is a curious creature, with fur like a mammal and a beak like a bird."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proud','adj.自豪的，骄傲的','/pɹaʊd/','/pɹaʊd/','adjective',["I am proud of Sivu’s schoolwork.","I was too proud to apologise.","It was a proud day when we finally won the championship."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('like','v.喜欢，喜爱prep.像，跟…一样n.爱好','/laɪk/','/laɪk/','noun',["Tell me your likes and dislikes.","I like hamburgers.","I like to go to the dentist every six months."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ugly','adj.丑陋的，难看的','/ˈʌɡli/','/ˈʌɡli/','noun',["He played an ugly trick on us.","an ugly temper; to feel ugly","With all this competition, expect things to get ugly."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earthquake','n.地震','/ˈɜːθkweɪk/','/ˈɝθkweɪk/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tax','n.税，税款','/tæks/','/tæks/','noun',["a heavy tax on time or health"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('towards','prep.向，朝，对于','/tɘˈwoːdz/','/tʊˈwɔɹdz/','preposition',["She moved toward the door.","What are your feelings toward him?","I''m saving money toward retirement."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('messy','adj.乱七八糟的','/ˈmɛsi/','/ˈmɛsi/','adjective',["Jim ran his fingers through his messy brown hair.","He is the messiest person I''ve ever met.","a messy divorce"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embassy','n.大使馆','/ˈɛmbəsi/','/ˈɛmbəsi/','noun',["The American embassy to France is located in Paris."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rectangle','adj.长方形的n.长方形','/ˈrɛktæŋɡ(ə)l/','/ˈrɛkˌtæŋɡəl/','noun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fragile','adj.易碎的，脆的','/ˈfɹædʒaɪl/','/ˈfɹædʒəl/','adjective',["He is a very fragile person and gets easily depressed."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('departure','n.离开；背离；违反','/dɪˈpɑː(ɹ)tjə(ɹ)/','','noun',["The departure was scheduled for noon.","There are several significant departures, however, from current practice.","The area is computed by latitudes and departures."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dash','v.快跑，猛撞n.快跑，猛撞；少量','/dæʃ/','/dæʃ/','noun',["Add a dash of vinegar.","There is a dash of craziness in his personality.","Aren''t we full of dash this morning?"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('send','vt.打发，派遣；送，邮寄','/sɛnd/','/sɛnd/','noun',["Every day at two o''clock, he sends his secretary out to buy him a coffee.","Seeing how ill she was, we sent for a doctor at once.","She finally sent the 12a after hours of failed attempts."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concrete','adj.具体的；有形的','/kɵnˈkɹiːt/','/ˈkɑnkɹiːt/','noun',["The road was made of concrete that had been poured in large slabs.","I hate grass, so I concreted over my lawn.","Fuzzy videotapes and distorted sound recordings are not concrete evidence that bigfoot exists."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('note','n.便条，笔记，注释vt.记录，注意','/nəʊt/','/noʊt/','noun',["a poet of note","If you look to the left, you can note the old cathedral.","We noted his speech."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everybody','pron.每人，人人','/ˈɛvɹibɒdi/','/ˈɛvɹibɑdi/','pronoun',[]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sail','v.航行，开航n.帆；航行','/seɪl/','/seɪl/','noun',["Take in sail: a storm is coming.","Let''s go for a sail.","Twenty sail were in sight."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cab','n.出租车；驾驶室','/kæb/','/kæb/','noun',["a cab ride"]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purpose','n.目的，意图','/ˈpɜːpəs/','/ˈpɝpəs/','noun',["The purpose of turning off the lights overnight is to save energy."]);
INSERT INTO senior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regret','n.遗憾，懊悔；令人遗憾的事vt.遗憾；后悔','/ɹiˈɡɹɛt/','/ɹiˈɡɹɛt/','noun',["He regretted his words.","I regret that I have to do this, but I don''t have a choice."]);
